INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ここに困ってる人は\nいないよね…？\nよかった♪", 1, 100101, 0, 0, 1);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "冒険の準備準備…\nうん、忘れ物はなし！\n…あっ！", 1, 100101, 0, 0, 2);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "リズムを意識して…\nわんつーわんつー！\nうん、調子はバッチリ", 1, 100101, 0, 0, 3);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ここで特訓していい？\n物は壊さないように\n気をつけるね！", 1, 100101, 0, 0, 4);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "なんか落ち着かないや\nもしかして、\n困ってる人が\n近くにいるのかな…？", 1, 100101, 0, 0, 5);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "えへへ…いつも\n一緒にいてくれて\nありがとねっ！", 1, 100101, 0, 0, 6);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ちゃんと覚えてるよ\n騎士くんの声…\nあの時はありがとね！", 1, 100101, 0, 0, 7);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あははっ！\nやったなー！\nお返しだー！\nこちょこちょこちょ…", 1, 100101, 0, 0, 8);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "どうしたの？\nもしかして困ってる？\nあたしにまかせて！", 1, 100101, 0, 0, 9);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "えっとね…しっぽは\n触っちゃダメだよ？", 1, 100101, 0, 0, 10);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "反応しない特訓…\nだったけど無理～！\n悔しいよぉ～！", 1, 100101, 0, 0, 11);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ふぁふぃ？\nやられた～！　ほっぺ\nぷにぷにしないでぇ～", 1, 100101, 0, 0, 12);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "えへへ…\n騎士くんの手だ…\nあったかいな…♪", 1, 100101, 0, 0, 13);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよー！\n今日も元気に\nいっちゃうよー！", 1, 100101, 0, 1, 14);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ユイちゃんに\nおやつ作って\nもらおうかな～♪", 1, 100101, 0, 2, 15);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "寝るのも修行だって\nこないだレイさんが\n言ってたんだ…", 1, 100101, 0, 3, 16);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "ちゃんとケアして\n傷が残らないように\nしないと…", 1, 100101, 0, 0, 17);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "一回休むと\nこのままずるずる\nいきそう…", 1, 100101, 0, 0, 18);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "新しい練習相手に…\nって冗談だよ冗談！\n本気じゃないから！", 1, 100101, 0, 0, 19);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "落ち着くなぁ～\n心だけじゃなくて\n体もほぐれそう♪", 1, 100101, 0, 0, 20);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかい所に\nいると体が丸く\nなっちゃう…", 1, 100101, 0, 0, 21);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "いつ何が起きるか\n分からないし、\nもっと力をつけないと", 1, 100101, 0, 0, 22);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "美味しいけど、\n食べ過ぎないように\nしないと…！！", 1, 100101, 0, 0, 23);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "文字が多いと\n眠くなっちゃう…\n危ない危ない！", 1, 100101, 0, 0, 24);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "リズムを意識して…\nわんつーわんつー！\nうん、調子はバッチリ", 1, 100102, 0, 0, 26);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "のんびりするのって\n退屈かも…\n何かして遊ばない？", 1, 100102, 0, 0, 27);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "留守番はちょっと\n苦手かも…\nなんか寂しいんだもん", 1, 100102, 0, 0, 28);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "あたしのお友達も\n呼んできていい？\nきっと楽しいよ！", 1, 100102, 0, 0, 29);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "誰も困ってないよね？\n…何をすれば\nいいのか分かんないや", 1, 100102, 0, 0, 30);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "ちゃんと覚えてるよ\n騎士くんの声…\nあの時はありがとね！", 1, 100102, 0, 0, 31);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "…なんであたし\n騎士くんばっかり\n見てるんだろ…", 1, 100102, 0, 0, 32);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "反応しない特訓…\nだったけど無理～！\n悔しいよぉ～！", 1, 100102, 0, 0, 33);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "触るのって楽しい？\n…そっか\n少しだけだよ…？", 1, 100102, 0, 0, 34);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あたしの元気を\nわけてあげるね！\nフレー！　フレー！", 1, 100102, 0, 0, 35);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "何かムズムズする！？\nって騎士くんかぁー\nどしたの？", 1, 100102, 0, 0, 36);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "ひゃうっ！　もう…\nしっぽはだめだってば\n次やったらデコピン！", 1, 100102, 0, 0, 37);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "えへへ…\n騎士くんの手だ…\nあったかいな…♪", 1, 100102, 0, 0, 38);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝ごはんと運動！\nこれがあたしの\n元気の素だよ！", 1, 100102, 0, 1, 39);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ユイちゃんに\nおやつ作って\nもらおうかな～♪", 1, 100102, 0, 2, 40);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "寝るのも修行だって\nこないだレイさんが\n言ってたんだ…", 1, 100102, 0, 3, 41);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "これでよし♪\n騎士くん\n気づくかな…？", 1, 100102, 0, 0, 42);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "一回休むと\nこのままずるずる\nいきそう…", 1, 100102, 0, 0, 43);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "新しい練習相手に…\nって冗談だよ冗談！\n本気じゃないから！", 1, 100102, 0, 0, 44);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "こういうの\nなんか気になって\nじーって見ちゃうんだ", 1, 100102, 0, 0, 45);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかい所に\nいると体が丸く\nなっちゃう…", 1, 100102, 0, 0, 46);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "いつ何が起きるか\n分からないし\nもっと力をつけないと", 1, 100102, 0, 0, 47);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "お腹が減ると\nなんか力が\n出ないんだよね…", 1, 100102, 0, 0, 48);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "色んなことを\n知っておくのは\n大事だよね！", 1, 100102, 0, 0, 49);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "お片付けも済んだし\n今度は洗濯ものを\nたたもうかな", 1, 100201, 0, 0, 51);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "この気持ち\nもっとちゃんと\n伝えなくっちゃ…", 1, 100201, 0, 0, 52);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "お茶をいれようと\n思うんだけど\n他に飲みたい人は\nいるかな？", 1, 100201, 0, 0, 53);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "戦いは\n得意じゃないけど\nお料理なら…！", 1, 100201, 0, 0, 54);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "こういう平和な\n時間が、もっと\n続くといいな", 1, 100201, 0, 0, 55);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "わたし…\nもうちょっとだけ勇気\n出してみようかな", 1, 100201, 0, 0, 56);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "みんなのことが大好き\nも、もちろん、\n騎士クンのことも…\nな、仲間として！", 1, 100201, 0, 0, 57);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ひゃうっ！\nな、なに？\nびっくりしたぁ…", 1, 100201, 0, 0, 58);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "男の子って、\nやっぱりおっきいね。\nその…手とか\n他にもいろいろ…", 1, 100201, 0, 0, 59);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "困ったことが\nあったら\nいつでも話してね", 1, 100201, 0, 0, 60);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "え！　む、虫っ！？\n取って取って！\nはやく～！", 1, 100201, 0, 0, 61);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あのね…\n一緒におでかけ\nしたいんだけど…\nダメかな？", 1, 100201, 0, 0, 62);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "騎士クンに\n伝えたいことがあるの\nとっても大切な…\nこ、今度、話すね！", 1, 100201, 0, 0, 63);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お、おはよう！\nあの…朝ごはんは\nもう食べちゃった？", 1, 100201, 0, 1, 64);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼休みだね\nあの…良かったら\nお弁当…食べない？", 1, 100201, 0, 2, 65);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "遅くまでお疲れ様\n明日も頑張ろうね\nふわぁ…", 1, 100201, 0, 3, 66);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "よし…\nこれなら\n褒めてもらえるかな？", 1, 100201, 0, 0, 67);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "がんばることも\n必要だけど、\nお休みも大切だよね", 1, 100201, 0, 0, 68);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいなぁ…\nわたしも今度\n作ってみよう。\nえっと、材料は…", 1, 100201, 0, 0, 69);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "戦う前にもこうやって\n落ち着けたら\nいいのに", 1, 100201, 0, 0, 70);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "…はへっ？\nも、もしかして今\n寝ちゃってた…？", 1, 100201, 0, 0, 71);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "騎士クンと一緒に\n冒険するなら\n体力がないと…！", 1, 100201, 0, 0, 72);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいしいものって\n食べ過ぎちゃうけど…\nしょうがない…よね？", 1, 100201, 0, 0, 73);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "…そっか\nこうすれば魔法が\nもっと強くなるんだ", 1, 100201, 0, 0, 74);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "洗濯と掃除\nどっちから\nはじめよう？", 1, 100202, 0, 0, 76);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "新しい魔道書を\n買いに行かなくちゃ\nもっとたくさん\n魔法を覚えたいな", 1, 100202, 0, 0, 77);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "お茶をいれようと\n思うんだけど\n他に飲みたい人は\nいるかな？", 1, 100202, 0, 0, 78);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "今日はどんな料理に\n挑戦しよう…♪", 1, 100202, 0, 0, 79);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "この気持ち\nもっとちゃんと\n伝えなくっちゃ…", 1, 100202, 0, 0, 80);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "みんなのことが大好き\nも、もちろん\n騎士クンのことも…\nな、仲間として！", 1, 100202, 0, 0, 81);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "騎士クンのそばに\nいられるだけで\n幸せだよ", 1, 100202, 0, 0, 82);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "えっと、その…\nこんな所で\nこういうことされると\n恥ずかしいよ…", 1, 100202, 0, 0, 83);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "え！　む、虫っ！？\n取って取って！\nはやく～！", 1, 100202, 0, 0, 84);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あ、あの…実は\n騎士クンのこと…\nううん、やっぱり\nなんでもない", 1, 100202, 0, 0, 85);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "男の子って\nやっぱりおっきいね\nその…手とか\n他にもいろいろ…", 1, 100202, 0, 0, 86);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "騎士クンに\n伝えたいことがあるの\nとっても大切な…\nこ、今度、話すね！", 1, 100202, 0, 0, 87);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ふふふっ…そんなとこ\nツンツンしないで\nくすぐったいよ～", 1, 100202, 0, 0, 88);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう\nよく眠れた？　今日も\n一日、頑張ろうね♪", 1, 100202, 0, 1, 89);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹空いちゃった…\nそうだ。騎士クンも\n一緒にお昼食べない？", 1, 100202, 0, 2, 90);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もうこんな時間…\nそろそろ寝なくちゃ\nおやすみなさい", 1, 100202, 0, 3, 91);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "よし…\nこれなら\n褒めてもらえるかな？", 1, 100202, 0, 0, 92);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "がんばることも\n必要だけど\nお休みも大切だよね", 1, 100202, 0, 0, 93);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい～♪\n騎士クンは\nこういうのって好き？", 1, 100202, 0, 0, 94);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "戦う前にもこうやって\n落ち着けたら\nいいのに", 1, 100202, 0, 0, 95);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あの…！\nよ、良かったら\n一緒に…！", 1, 100202, 0, 0, 96);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "騎士クンと一緒に\n冒険するなら\n体力がないと…！", 1, 100202, 0, 0, 97);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "最近服のサイズが\n合わないんだけど…\n食べ過ぎなのかな？", 1, 100202, 0, 0, 98);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "…やっぱり\n月刊恋愛指南は\nためになる…", 1, 100202, 0, 0, 99);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "装備の手入れでも\nしようかな…", 1, 100301, 0, 0, 101);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "次に鍛えるべきは\n肉体面か精神面か\nどちらにしよう…？", 1, 100301, 0, 0, 102);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ツムギが作ってくれた\nこの服…一体\nいつサイズを…？", 1, 100301, 0, 0, 103);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "仲間なんていらない\nそう思ってた頃も\nあったな…", 1, 100301, 0, 0, 104);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "考えごとをしていると\nつい部屋中を\n歩いてしまうな", 1, 100301, 0, 0, 105);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "彼は\nどこまで強くなるのか\n私も負けられないな", 1, 100301, 0, 0, 106);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "私が一本を取られる\nなんてね…願い事は\nもう決まったのかな？", 1, 100301, 0, 0, 107);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ああ、キミだったのか\n人の気配がしたから\n誰かと思ったよ", 1, 100301, 0, 0, 108);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "斬りかかるつもりなら\nちゃんとかかってきて\n…呼んだだけ？", 1, 100301, 0, 0, 109);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "なに？　私に相談？\n戦いについてなら\n喜んで", 1, 100301, 0, 0, 110);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "今のが突き？\n軽い！　もっと鋭く！\nさあ、もう一回！", 1, 100301, 0, 0, 111);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ひゃっ！　ど、どこを\n触ってるの！？\n…油断した", 1, 100301, 0, 0, 112);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "キミにはこれからも\n私のそばに…\nいや、なんでもない", 1, 100301, 0, 0, 113);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう\n今日も充実した\n一日にしていこう", 1, 100301, 0, 1, 114);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "そろそろ\nお茶の時間か\nキミも一緒にどう？", 1, 100301, 0, 2, 115);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "遅くまで大変だね\nまだ仕事があるなら\n手伝おうか？", 1, 100301, 0, 3, 116);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "戦いを経てもなお\n美しくあるように…\nこれでよし♪", 1, 100301, 0, 0, 117);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "戦ってばかりで\n休まないと、また\nユイに怒られるな", 1, 100301, 0, 0, 118);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ヒヨリみたいに\n練習相手に…\nいや、やめておこう", 1, 100301, 0, 0, 119);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "これはいい…\n戦いの前の精神統一に\nもってこいじゃないか", 1, 100301, 0, 0, 120);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "時々は落ち着いた\n時間を過ごすのも\n悪くない…", 1, 100301, 0, 0, 121);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "彼に負けないよう\n私も更に強くなろう\n共に戦うために！", 1, 100301, 0, 0, 122);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食事は大切だけど\n食べ過ぎには\n注意しておこう…", 1, 100301, 0, 0, 123);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ユイ…！\nこ、こんな本を\n読んでいたのか…！", 1, 100301, 0, 0, 124);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "海だけじゃなくて\n川でも釣りがしたいな\n道具も新調しよう", 1, 100302, 0, 0, 126);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ツムギが作ってくれた\nこの服…一体\nいつサイズを…？", 1, 100302, 0, 0, 127);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "彼は\nどこまで強くなるのか\n私も負けられないな", 1, 100302, 0, 0, 128);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "そろそろ修行の\n内容を新しくしよう\nより厳しいものにね", 1, 100302, 0, 0, 129);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "強くなって…誰にも\n妨げられない自由な\n生き方がしたい", 1, 100302, 0, 0, 130);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "まさか風邪を引くとは\n彼の看病のおかげで\nすっかり良く\nなったけど", 1, 100302, 0, 0, 131);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "私が一本を取られる\nなんてね…願い事は\nもう決まったのかな？", 1, 100302, 0, 0, 132);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "どうしたの？\nなんでもない？\nそれなら良かった", 1, 100302, 0, 0, 133);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あんまり突っつくと\nお返しするよ？\n覚悟は出来てる？", 1, 100302, 0, 0, 134);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ねぇ、今度また\n釣りに行かない？\n大きいのを狙おう", 1, 100302, 0, 0, 135);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "修行がしたいの？\nそれを早く言ってよ\nすぐに出発しよう！", 1, 100302, 0, 0, 136);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "ひょっとして\n今のも一本だなんて\n言わないよね？", 1, 100302, 0, 0, 137);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "キミにはこれからも\n私のそばに…\nいや、なんでもない", 1, 100302, 0, 0, 138);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日は仕事？\nそれとも修行？\n良ければ付き合うよ", 1, 100302, 0, 1, 139);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "休息も時には\n必要だと、仲間から\n教わったよ", 1, 100302, 0, 2, 140);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "遅くまで大変だね\nまだ仕事があるなら\n手伝おうか？", 1, 100302, 0, 3, 141);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "髪の長さを少し\n変えてみようかな…\nわ、私は何を…！", 1, 100302, 0, 0, 142);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "休息があってこそ\n万全な状態で\n戦えるんだ", 1, 100302, 0, 0, 143);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ヒヨリみたいに\n練習相手に…\nいや、やめておこう", 1, 100302, 0, 0, 144);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "体と同様に\n心もほぐれるね…\nはぁ…", 1, 100302, 0, 0, 145);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "休む時は休む\nヒヨリもそろそろ\n覚えて欲しいな…", 1, 100302, 0, 0, 146);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "彼に負けないよう\n私も更に強くなろう\n共に戦うために！", 1, 100302, 0, 0, 147);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "修行のせいか\n最近食べる量が\n増えてきたような…", 1, 100302, 0, 0, 148);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ユイ…！\nこ、こんな本を\n読んでいたのか…！", 1, 100302, 0, 0, 149);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "お宝の予感！\n部屋中を\n探検しちゃうぞ～", 1, 100401, 0, 0, 151);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "落とし穴…どこに\n作ったんだっけ？", 1, 100401, 0, 0, 152);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "うえ～ん！\n…嘘泣きしたら\n相手は油断するかな", 1, 100401, 0, 0, 153);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ハニートラップって\nすごく甘いお菓子で\nイタズラするのかな？", 1, 100401, 0, 0, 154);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "かくれんぼする人\nこの指、と～まれ！", 1, 100401, 0, 0, 155);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ミソギ以外の人に\nイタズラされちゃ\nダメだよ！", 1, 100401, 0, 0, 156);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ミソギと遊ぶ？\nミソギに遊ばれる？", 1, 100401, 0, 0, 157);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "いいこと思いついた！\nい、イタズラとかじゃ\nないよ～", 1, 100401, 0, 0, 158);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "うわっ！？\n　にいちゃんが、\nミソギにイタズラ？", 1, 100401, 0, 0, 159);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "にいちゃんの\n通りそうなところに\nバナナの皮を…", 1, 100401, 0, 0, 160);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "にいちゃんのオデコと\nホッペと鼻と目と耳に\n落書きを…", 1, 100401, 0, 0, 161);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ここ、ミソギ探検隊の\n基地にしようよ！", 1, 100401, 0, 0, 162);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "だ～れだ…って？\nにいちゃんの声くらい\nわかるよ！\n大好きだもん♪", 1, 100401, 0, 0, 163);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "にいちゃん、おはよ！\n目覚まし時計を\n止めておいたのに、\nよく起きられたね～♪", 1, 100401, 0, 1, 164);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "にいちゃんが\n昼寝したら、\nイタズラし放題♪", 1, 100401, 0, 2, 165);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜の探検も\nおもしろそう！\nねぇ出かけちゃダメ？", 1, 100401, 0, 3, 166);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "イタズラには\nお色気も必要…\nうん、完璧！", 1, 100401, 0, 0, 167);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "座ったら、ブーッって\nいう音が出たら、\nおもしろいな～♪", 1, 100401, 0, 0, 168);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい！\nミソギ探検隊の\nマスコットにしよう♪", 1, 100401, 0, 0, 169);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "吸うとくしゃみが\n止まらなくなるお香を\nここに…くしゅっ！", 1, 100401, 0, 0, 170);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "にひひ…イタズラの\n証拠、ここで\n燃やしちゃおう～！", 1, 100401, 0, 0, 171);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "探検家は\n体力勝負だよー！", 1, 100401, 0, 0, 172);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "みんなに分けて\nあげようかな～\n激辛ソースも\n入れちゃうけどね！", 1, 100401, 0, 0, 173);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "こういう所に\n宝の地図が\n隠れてるんだよね～", 1, 100401, 0, 0, 174);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "お宝の予感！\n部屋中を\n探検しちゃうぞ～", 1, 100402, 0, 0, 176);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "うぅ、探検に出たい！\nじっとしてなんか\nいられないよ～！", 1, 100402, 0, 0, 177);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "うえ～ん！\n…嘘泣きしたら\n相手は油断するかな", 1, 100402, 0, 0, 178);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ハニートラップって\nすごく甘いお菓子で\nイタズラするのかな？", 1, 100402, 0, 0, 179);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "かくれんぼする人\nこの指、と～まれ！", 1, 100402, 0, 0, 180);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "にいちゃんのオデコと\nホッペと鼻と目と耳に\n落書きを…", 1, 100402, 0, 0, 181);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "にいちゃんが喜ぶ\nイタズラ、何かない\nかな～？", 1, 100402, 0, 0, 182);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ミソギがしかけた\nイタズラ\n見つけられるかな？", 1, 100402, 0, 0, 183);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "探検する？\n冒険する？\nそれとも…\nイタズラされる？", 1, 100402, 0, 0, 184);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "将来の夢は探検家！\n探したい物はないけど", 1, 100402, 0, 0, 185);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "にいちゃんに宿題！\n落とし穴を10個\n掘ること！", 1, 100402, 0, 0, 186);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "だ～れだ…って？\nにいちゃんの声くらい\nわかるよ！\n大好きだもん♪", 1, 100402, 0, 0, 187);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ここ、ミソギ探検隊の\n基地にしようよ！", 1, 100402, 0, 0, 188);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "にいちゃん\n探検に行こうよ！\n今からなら遭難しても\n夜には帰れるよ！", 1, 100402, 0, 1, 189);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "にいちゃんが昼寝したら\nイタズラし放題♪", 1, 100402, 0, 2, 190);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜の探検も\nおもしろそう！\nねぇ出かけちゃダメ？", 1, 100402, 0, 3, 191);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "イタズラには\nお色気も必要…\nうん、完璧！", 1, 100402, 0, 0, 192);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ゆっくりまったりして\n次のイタズラを\n考えよ～！", 1, 100402, 0, 0, 193);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい！\nミソギ探検隊の\nマスコットにしよう♪", 1, 100402, 0, 0, 194);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "吸うとくしゃみが\n止まらなくなるお香を\nここに…くしゅっ！", 1, 100402, 0, 0, 195);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "にひひ…イタズラの\n証拠、ここで\n燃やしちゃおう～！", 1, 100402, 0, 0, 196);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "探検家は\n体力勝負だよー！", 1, 100402, 0, 0, 197);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "探検のおやつに\nぴったりかも～！", 1, 100402, 0, 0, 198);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "こういう所に\n宝の地図が\n隠れてるんだよね～", 1, 100402, 0, 0, 199);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "音楽は全部好きだけど\n一番好きなのは\nやっぱりジャズかな", 1, 100601, 0, 0, 201);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "はぁ、はぁ…\n一人でもいっぱい\nしないと…\n特訓…", 1, 100601, 0, 0, 202);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "お姉ちゃんには\nもっと自信を\n持ってほしいなぁ", 1, 100601, 0, 0, 203);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お姉ちゃんのマネ\nしちゃおうかな？", 1, 100601, 0, 0, 204);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "双子って、\n好みのタイプも\n似ちゃうのかな？", 1, 100601, 0, 0, 205);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お兄ちゃんと私は\n相性抜群です♪", 1, 100601, 0, 0, 206);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "もう待ちきれない…\nお兄ちゃん、\n早く帰って来て！", 1, 100601, 0, 0, 207);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あんっ…着替えよう\nと思ったのに\nお兄ちゃんのエッチ！", 1, 100601, 0, 0, 208);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "うふふ、お兄ちゃん！\n今日は何を\nするんですか？", 1, 100601, 0, 0, 209);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そんなところ\n触っちゃダメ♪", 1, 100601, 0, 0, 210);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お兄ちゃん、イジワル\nしないでください…", 1, 100601, 0, 0, 211);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お兄ちゃん、もっと\n上級編のテクニック、\n教えてくださいね！", 1, 100601, 0, 0, 212);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "コーチ、\n今日も特訓\nお願いします！", 1, 100601, 0, 0, 213);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\n昨夜は楽しかった\nですね、うふふ♪", 1, 100601, 0, 1, 214);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "こんな明るい時間から\nす、するんですか…\n二人っきりの特訓…", 1, 100601, 0, 2, 215);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜はこれからですよ\nお兄ちゃん♪", 1, 100601, 0, 3, 216);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "世界一、かわいく\nなるんだから♪", 1, 100601, 0, 0, 217);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "気持ちいい♪\nもう立てないよ～", 1, 100601, 0, 0, 218);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい♪\nアカリのライバル\nだね", 1, 100601, 0, 0, 219);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "はぁ…気持ちいい、\n私、このままダメに\nなっちゃいそう…", 1, 100601, 0, 0, 220);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "はぁ…アカリ、\nとろけちゃう…", 1, 100601, 0, 0, 221);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "はぁ…はぁはぁ、\n私…もう…ダメ\n限界です…！", 1, 100601, 0, 0, 222);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "わぁ、おいしい～\nけど食べ過ぎは美容に\nよくないですよね", 1, 100601, 0, 0, 223);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "この楽譜、\nサックスで吹いて\nみたいなぁ♪", 1, 100601, 0, 0, 224);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "このごろ一人でいると\nお兄ちゃんのこと\nばかり考えちゃう…", 1, 100602, 0, 0, 226);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "はぁ、はぁ…もっと\nいっぱいしなくちゃ\n…練習", 1, 100602, 0, 0, 227);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "このお部屋、なんだか\n落ち着きます…\nお兄ちゃんが\nいるから？", 1, 100602, 0, 0, 228);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "みんなかわいいな～\n世界一かわいくなる\nのは、難しいな…", 1, 100602, 0, 0, 229);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "双子って、\n好みのタイプも\n似ちゃうのかな？", 1, 100602, 0, 0, 230);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "いつか世界でいちばん\nかわいくなって\nお兄ちゃんと…", 1, 100602, 0, 0, 231);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "もう待ちきれない…\nお兄ちゃん、\n早く帰って来て！", 1, 100602, 0, 0, 232);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あんっ…着替えよう\nと思ったのに\nお兄ちゃんのエッチ！", 1, 100602, 0, 0, 233);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "二人きりの秘密の特訓\n今度はいつですか？\n待ち遠しいです…", 1, 100602, 0, 0, 234);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "え？　ここでするの？\nみんなの前で恥ずか\nしいな…筋トレ", 1, 100602, 0, 0, 235);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お兄ちゃん、イジワル\nしないでください…", 1, 100602, 0, 0, 236);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "お兄ちゃんといると\nわ、私…ドキドキ\nしてきちゃう…", 1, 100602, 0, 0, 237);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "コーチ、\n今日も特訓\nお願いします！", 1, 100602, 0, 0, 238);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\n昨夜は楽しかった\nですね、うふふ♪", 1, 100602, 0, 1, 239);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お兄ちゃんに\n食べてもらいたいなぁ\n手作りのお昼ごはん", 1, 100602, 0, 2, 240);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お風呂入ってきますね\nそのあとは…\n二人でい～っぱい\n遊びましょうね", 1, 100602, 0, 3, 241);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "お姉ちゃんのマネ\nしちゃおうかな？", 1, 100602, 0, 0, 242);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "気持ちいい♪\nもう立てないよ～", 1, 100602, 0, 0, 243);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい♪\nアカリのライバル\nだね", 1, 100602, 0, 0, 244);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "はぁ…気持ちいい、\n私、このままダメに\nなっちゃいそう…", 1, 100602, 0, 0, 245);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったか～い…\nまるでお兄ちゃんが\n隣にいる時みたい", 1, 100602, 0, 0, 246);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "汗をかくと\n気持ちいいですよね", 1, 100602, 0, 0, 247);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "お兄ちゃんの特訓に\n付き合うために\nたっぷり\n食べておかないと♪", 1, 100602, 0, 0, 248);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "この楽譜\nサックスで吹いて\nみたいなぁ♪", 1, 100602, 0, 0, 249);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "プリン、プリン、\nプリン、プリン、\nプリン、プリン～♪", 1, 100701, 0, 0, 251);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "う～ら～め～し～や～\nなの～♪", 1, 100701, 0, 0, 252);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "プリンがないなら\n死んだほうがマシなの\nあ、もう死んでたの～", 1, 100701, 0, 0, 253);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "幽霊の正体見たり、\nミヤコなの～", 1, 100701, 0, 0, 254);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ミヤコがいきなり\n消えたら、みんな\n驚くかもなの～♪", 1, 100701, 0, 0, 255);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "アイツがいて、\nプリンもある。\nきっとここが天国なの", 1, 100701, 0, 0, 256);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "アイツはプリンセス\nナイトじゃなくて\nプリンナイトなの～", 1, 100701, 0, 0, 257);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "姿を消して、オマエを\n見張ってやるの～\nむふふ～♪", 1, 100701, 0, 0, 258);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "もし成仏した先に\nプリンがなかったら\n地獄なの～…", 1, 100701, 0, 0, 259);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "右にプリン左にプリン\n後ろにもプリン♪\n前にはオマエなの～！", 1, 100701, 0, 0, 260);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "死んだ人には\nお供え物をするの～\nミヤコにも、プリンを\n毎日お供えするの～", 1, 100701, 0, 0, 261);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "たくさんオマエと\n遊べて、\n成仏しそうなくらい\nうれしいの～！", 1, 100701, 0, 0, 262);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "オマエのこと\n気に入ったからずっと\nとり憑いてやるの～", 1, 100701, 0, 0, 263);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "う～　眠いの…\n二度目の二度寝を\nするの…", 1, 100701, 0, 1, 264);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ご飯はプリンなの\n３時のおやつも、\nプリンなの～", 1, 100701, 0, 2, 265);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ディナーは豪華に、\nプリンのフルコース\nなの～♪", 1, 100701, 0, 3, 266);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "体が透けちゃうから\nうまく使えないの～", 1, 100701, 0, 0, 267);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "まったりなの～\nあとはプリンがあれば\n完璧なの～", 1, 100701, 0, 0, 268);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "む～…かわいいけど\nプリンは分けて\nあげないの～", 1, 100701, 0, 0, 269);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "は～　いい気分なの…\n成仏しそうなの…", 1, 100701, 0, 0, 270);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "も、もしかして\nミヤコ、ここで\n火葬されちゃうの？", 1, 100701, 0, 0, 271);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "幽霊には、体力も\n筋力も関係ないの～！", 1, 100701, 0, 0, 272);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ぱくぱくモグモグ…\nミヤコ、幽霊だけど、\nお腹はすくの～", 1, 100701, 0, 0, 273);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "プリンの写真集が\nあればいいのに\nなの～", 1, 100701, 0, 0, 274);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "うらめしや～…\n裏の飯より\nプリンがいいの～", 1, 100702, 0, 0, 276);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "プリン♪　プリン♪\nプリン♪　なの～♪　", 1, 100702, 0, 0, 277);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "世界中のケーキ屋が\nプリンのおいしさを\n競い合えばいいの～！\n審査員はミヤコなの～", 1, 100702, 0, 0, 278);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "買ってきたプリンには\n全部ミヤコの名前を\n書いておくの～", 1, 100702, 0, 0, 279);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "プリンがないなら\n死んだほうがマシなの\nあ、もう死んでたの～ ", 1, 100702, 0, 0, 280);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "アイツがいて\nプリンもある\nきっとここが天国なの", 1, 100702, 0, 0, 281);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "アイツはプリンセス\nナイトじゃなくて\nプリンナイトなの～", 1, 100702, 0, 0, 282);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "右にプリン左にプリン\n後ろにもプリン♪\n前にはオマエなの～！", 1, 100702, 0, 0, 283);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "もし成仏した先に\nプリンがなかったら\n地獄なの～…", 1, 100702, 0, 0, 284);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日はオマエと\nプリンを買いに行くの\n強制なの～　", 1, 100702, 0, 0, 285);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "死んだ人には\nお供え物をするの～\nミヤコにも、プリンを\n毎日お供えするの～", 1, 100702, 0, 0, 286);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "たくさんオマエと\n遊べて\n成仏しそうなくらい\nうれしいの～！ ", 1, 100702, 0, 0, 287);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ミヤコのプリン\nオマエにだったら\n分けてあげるの～ ", 1, 100702, 0, 0, 288);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "う～　眠いの…\n二度目の二度寝を\nするの… ", 1, 100702, 0, 1, 289);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "う～ら～め～し～や～\n…明るい時間だと\n驚かせないの～ ", 1, 100702, 0, 2, 290);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ひゅ～どろどろ～ん☆\n真っ暗なうちに\nいたずらしまくるの～♪", 1, 100702, 0, 3, 291);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "体が透けちゃうから\nうまく使えないの～ ", 1, 100702, 0, 0, 292);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "落ち着くの～\nいまプリン食べたら\nきっといつもより\nおいしいの～♪ ", 1, 100702, 0, 0, 293);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "む～…かわいいけど\nプリンは分けて\nあげないの～　", 1, 100702, 0, 0, 294);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "は～　いい気分なの…\n成仏しそうなの…", 1, 100702, 0, 0, 295);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "も、もしかして\nミヤコ、ここで\n火葬されちゃうの？ ", 1, 100702, 0, 0, 296);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "幽霊には、体力も\n筋力も関係ないの～！　", 1, 100702, 0, 0, 297);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいしいの～\nプリン味だったら\nもっとおいしいの～ ", 1, 100702, 0, 0, 298);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "プリンの写真集が\nあればいいのに\nなの～ ", 1, 100702, 0, 0, 299);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "もし太陽が滅んでも\nボクの美しさで大地を\n照らしてあげる！", 1, 100801, 0, 0, 301);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "う～ん、この部屋には\nボクの肖像画や\n彫像が必要だね", 1, 100801, 0, 0, 302);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "美の女神と愛の女神が\nボクを作る時、本気\n出しちゃったんだね♪", 1, 100801, 0, 0, 303);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ボクの誕生とともに\n全ての美しさは過去の\n遺物になったんだよ！", 1, 100801, 0, 0, 304);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "うわっ昨日より可愛く\nなってる。明日は\nどうなっちゃう\nのかな？", 1, 100801, 0, 0, 305);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "このボクがいるだけで\nあの人への\nおもてなしだよね", 1, 100801, 0, 0, 306);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ボクの可愛さは、\nふふ…あの人の\nためのものさ", 1, 100801, 0, 0, 307);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ねぇ～、ボクって\n可愛い？\nふふ、知ってる☆", 1, 100801, 0, 0, 308);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "呼んだ？\n可愛いボクと話したい\n気持ちはわかるよ", 1, 100801, 0, 0, 309);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふふ、ボクに触ると\nキミも美しく\nなっちゃうかもよ？", 1, 100801, 0, 0, 310);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "どうかな、\n今日のボク。\n美しい？　可愛い？\nねえ、どっち？", 1, 100801, 0, 0, 311);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あの人も今、\n可愛いボクのこと\n考えてるかな…", 1, 100801, 0, 0, 312);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "美しい…\nキミの瞳に写るボクは\nより一層きれいだ", 1, 100801, 0, 0, 313);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "美しいボクの\n美しい一日が\n始まるよ！", 1, 100801, 0, 1, 314);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "さーて、午後からも\n可愛く美しく\n華麗に優雅に♪", 1, 100801, 0, 2, 315);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "バラの花びら\nいっぱい浮かべた\nお風呂に入ってから\n寝ようっと♪", 1, 100801, 0, 3, 316);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "鏡よ、鏡。この世で\n一番可愛いボクに\nお似合いの人はだれ？", 1, 100801, 0, 0, 317);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ボクが座ったソファは\n「美しいソファ」に\nランクアップした！", 1, 100801, 0, 0, 318);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "わあ、可愛い！\n…まあ、ボクほど\nじゃないけどさ！", 1, 100801, 0, 0, 319);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "服を羽織るように\n香りをまとうボク…\n美しい、美しすぎる！", 1, 100801, 0, 0, 320);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "気安く触ったら\n火傷する…\n炎はボクに似ているね", 1, 100801, 0, 0, 321);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "運動は苦手なのに\n運動するボクの姿は\n可愛いなんて…罪♪", 1, 100801, 0, 0, 322);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ボクが食べると、\n食べ物まで\n可愛いなあ…", 1, 100801, 0, 0, 323);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ボクが触った瞬間に、\nこの本は美を\n携えてしまうんだ", 1, 100801, 0, 0, 324);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ボクの美しさは\nみんなのために\nあるんだよ！", 1, 100802, 0, 0, 326);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "う～ん、この部屋には\nボクの肖像画や\n彫像が必要だね", 1, 100802, 0, 0, 327);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "これ以上美しくなると\nボクをめぐって\n大陸中で戦争が\n始まっちゃう！", 1, 100802, 0, 0, 328);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ボクの誕生とともに\n全ての美しさは過去の\n遺物になったんだよ！", 1, 100802, 0, 0, 329);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ボクの可愛さについて\nみんな話し合わない\nのかな…？", 1, 100802, 0, 0, 330);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "このボクがいるだけで\nあの人への\nおもてなしだよね", 1, 100802, 0, 0, 331);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あの人も今\n可愛いボクのこと\n考えてるかな…", 1, 100802, 0, 0, 332);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "美の女神と愛の女神が\nボクを作る時、本気\n出しちゃったんだね♪", 1, 100802, 0, 0, 333);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ボクの美しさに嫉妬\nしたって意味ないよね\n次元が違うんだから", 1, 100802, 0, 0, 334);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ボクの化粧品使う？\n一緒に可愛くなろうよ", 1, 100802, 0, 0, 335);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ボクがいるだけで\nこの部屋は美の神殿♪\nランドソルの新たな\n観光名所になるね！", 1, 100802, 0, 0, 336);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "呼んだ？\n可愛いボクと話したい\n気持ちはわかるよ", 1, 100802, 0, 0, 337);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "美しい…\nキミの瞳に写るボクは\nより一層綺麗だ", 1, 100802, 0, 0, 338);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝日と共に\nボクの美しさも\n周りを照らすよ", 1, 100802, 0, 1, 339);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ボクの美しさを\n維持するために\nお昼ご飯食べなくちゃ", 1, 100802, 0, 2, 340);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "バラの花びらいっぱい\n浮かべたお風呂に\n入ってから\n寝ようっと♪", 1, 100802, 0, 3, 341);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "鏡よ、鏡。この世で\n一番可愛いボクに\nお似合いの人はだれ？", 1, 100802, 0, 0, 342);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ボクが座ったソファは\n「美しいソファ」に\nランクアップした！", 1, 100802, 0, 0, 343);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "可愛いものを\n可愛いって言える\nボクって可愛いよね！", 1, 100802, 0, 0, 344);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "服を羽織るように\n香りをまとうボク…\n美しい、美しすぎる！", 1, 100802, 0, 0, 345);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "冷えは美容の大敵\nなんだから！\nここ、ボクの場所ね！", 1, 100802, 0, 0, 346);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "運動は苦手なのに\n運動するボクの姿は\n可愛いなんて…罪♪", 1, 100802, 0, 0, 347);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ボクが食べると\n食べ物まで\n可愛いなあ…", 1, 100802, 0, 0, 348);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ボクが触った瞬間に\nこの本は美を\n携えてしまうんだ", 1, 100802, 0, 0, 349);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "「第１０部２０章\n終焉戦争、開幕」\n…これでよし！", 1, 100901, 0, 0, 351);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "今度シグルドに\n私の魔法を一つ\n伝授してやるか", 1, 100901, 0, 0, 352);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ここでは風が\n吹いてこないな…\n換気したい！", 1, 100901, 0, 0, 353);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "そうだ、ナナカに\nこの間借りた本を\n返さないと…", 1, 100901, 0, 0, 354);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "まずは包帯をとって\n手から龍の形の\n炎を出して…", 1, 100901, 0, 0, 355);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "シグルド…\n今頃何処で何を\nしているのだろう…", 1, 100901, 0, 0, 356);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "最近、彼の姿が\nまぶしく見える…\nどうして…？", 1, 100901, 0, 0, 357);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "辞書を知らないか？\n…探している\n理由は聞くな", 1, 100901, 0, 0, 358);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "そうだ！\n貴様の技にも\n名前をつけてやろう！", 1, 100901, 0, 0, 359);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "私に触れても力を\n奪われないのは\n貴様くらいだぞ？", 1, 100901, 0, 0, 360);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "何事だ？\nまさか我が瞳に\n魅入られたのか？", 1, 100901, 0, 0, 361);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "貴様がそばにいると\nとても安心できる…\n…不思議だ", 1, 100901, 0, 0, 362);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "い、いきなり目の前に\n現れるな！　ドキドキ\nするだろうがぁ！", 1, 100901, 0, 0, 363);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "「覚醒」めたか…\n行くぞ、悪を討つ\n戦いに出発だ！", 1, 100901, 0, 1, 364);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼間は「ヤツら」も\n襲ってはこない…\n束の間の休息だ", 1, 100901, 0, 2, 365);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "どうした？　夜はまだ\nこれから…ふぁ…\nね、眠くなどないぞ！", 1, 100901, 0, 3, 366);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "何か足りないな…\n暗黒騎士の紋章を\n作ろうかな", 1, 100901, 0, 0, 367);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "くっ…！\n私を眠りの国へ\n誘うつもりか！", 1, 100901, 0, 0, 368);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "このようなものに\n懐柔されるものか！\n…されるものか！", 1, 100901, 0, 0, 369);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "これを使えば\nもっとそれっぽい\n雰囲気が出そうだ", 1, 100901, 0, 0, 370);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "これが我らの求めた\n安寧か…\n悪くない…", 1, 100901, 0, 0, 371);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "この程度\n前世での激闘に\n比べれば…！", 1, 100901, 0, 0, 372);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "最近金欠でな…\nいやぁありがたい…", 1, 100901, 0, 0, 373);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ここにも\n前世の記憶が\n眠っていたとは…", 1, 100901, 0, 0, 374);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "「第１３部１章\n閃光のシグルド」\n…ついに登場だな", 1, 100902, 0, 0, 376);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "何故だ…何故\nこうもあっさり金欠に\n逆戻りするのだ！？", 1, 100902, 0, 0, 377);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "やはり転生者という\n設定はカッコイイ…\n天才だな、私！", 1, 100902, 0, 0, 378);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "そうだ、ナナカに\nこの間借りた本を\n返さないと…", 1, 100902, 0, 0, 379);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "そろそろ今日の分の\n魔力を溜めないと\nまた魔力切れが…", 1, 100902, 0, 0, 380);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 101, 1, "最近奴がそばに\nいるだけで、鼓動が\n早くなるのは何故だ？", 1, 100902, 0, 0, 381);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "シ、シグルド…！\nだめだ…妄想でも\n上手く言えない…", 1, 100902, 0, 0, 382);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 1, 2, "なんだ？　新たな\n賞金の情報を\n持ってきたのか？", 1, 100902, 0, 0, 383);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "名乗りやポーズは\nその強度で相手を\n圧倒する技術だ", 1, 100902, 0, 0, 384);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "いいか、魔法の\n詠唱中は絶対に\n声をかけるなよ？", 1, 100902, 0, 0, 385);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "おお、ちょうど今\n貴様専用の設定集を\n作成中だぞ！", 1, 100902, 0, 0, 386);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 101, 2, "貴様がそばにいると\nとても安心できる…\n…不思議だ", 1, 100902, 0, 0, 387);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "い、いきなり目の前に\n現れるな！　ドキドキ\nするだろうがぁ！", 1, 100902, 0, 0, 388);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 1, 2, "夜更かしのせいか\nまだ眠気が…いや！\nこれは組織の罠だ！", 1, 100902, 0, 1, 389);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "平穏な時に\n出来るだけ魔力を\n溜めておかねば…", 1, 100902, 0, 2, 390);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜になると、力が\n増した気分になるな\n…なりませんか？", 1, 100902, 0, 3, 391);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "何か足りないな…\n暗黒騎士の紋章を\n作ろうかな", 1, 100902, 0, 0, 392);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "お、おのれ\nヒュプノス…\n私は負けないぞ…", 1, 100902, 0, 0, 393);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "くっくっくっ…\n貴様は特別団員に\nしてやろう", 1, 100902, 0, 0, 394);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "これを使えば\nもっとそれっぽい\n雰囲気が出そうだ", 1, 100902, 0, 0, 395);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "これが我らの求めた\n安寧か…\n悪くない…", 1, 100902, 0, 0, 396);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "新たな戦いに備えて\n魔力だけでなく\n体力も鍛えねば！", 1, 100902, 0, 0, 397);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食事は魔力に\n変換する体力の\n元になるのだ！", 1, 100902, 0, 0, 398);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "フフフ…\nこれを覚えれば\nもっと強く…！", 1, 100902, 0, 0, 399);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "王子はんほんまに\nはんなりしてて、\n王子はんって感じやわ", 1, 101001, 0, 0, 401);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "この絵本の王子はん、\n王子はんみたいで\nええなぁ♪", 1, 101001, 0, 0, 402);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "うちがガラスの靴を\n落としたら、王子はん\n見つけてくれるやろか", 1, 101001, 0, 0, 403);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "マホマホ王国\n次期国王の王子はん\n…見てみたいわ～", 1, 101001, 0, 0, 404);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "王子はんのために\n糸を紡いで、\n編み物でもしまひょか", 1, 101001, 0, 0, 405);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "マホ姫と王子はん、\n絵本の世界より\nベストカップルや", 1, 101001, 0, 0, 406);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "王子はんと\n一緒にいると\n胸がせわしのー\nうごいてかなん", 1, 101001, 0, 0, 407);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "うちら並んでたら\nお雛様みたいに\n見えると思いまへん？", 1, 101001, 0, 0, 408);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "王子はんを\n国に連れて帰ったら\nみんな大歓迎して\nくれるやろなぁ", 1, 101001, 0, 0, 409);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "王子はんは、\n絵本から出てきた人\nみたいやね～", 1, 101001, 0, 0, 410);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "うちの話し方\nのんびりしてます\nやろか？", 1, 101001, 0, 0, 411);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "マホ姫の手は\nつべたいから、\n王子はんが温めて？", 1, 101001, 0, 0, 412);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "うちがもし悪い魔法に\nかかったら、王子はん\n口づけしてくれはる？", 1, 101001, 0, 0, 413);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝は小鳥はんも\nおなかがすいてるから\nよう飛び回りはるねえ", 1, 101001, 0, 1, 414);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お茶請けはお大福が\nよろしおすけど\nクッキーもええなあ", 1, 101001, 0, 2, 415);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "うち、普段から\n夢見がちやけど…\nほんに眠い時間やわぁ", 1, 101001, 0, 3, 416);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "王子はんに\n会いに行くなら、\nおめかしせな\nあかんなぁ", 1, 101001, 0, 0, 417);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "はんなりした\nええお椅子やわぁ\nほっこりしますなあ", 1, 101001, 0, 0, 418);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かいらしもんが\nいっぱいで、\nマホマホ王国みたい\nやわぁ", 1, 101001, 0, 0, 419);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "心地ええどす。まるで\nお花畑にいるようやね", 1, 101001, 0, 0, 420);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ぽかぽかどす。\n心まであったかく\nなりますわぁ", 1, 101001, 0, 0, 421);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "はぁはぁ、お姫はんは\n激しい運動は\nしぃひんもんどす～", 1, 101001, 0, 0, 422);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…あんまり\n速う食べられへんけど\n美味しいわぁ", 1, 101001, 0, 0, 423);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "絵本、絵本～\n幸せやわぁ♪", 1, 101001, 0, 0, 424);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "王子はんにとって\n自慢の姫になるえ～", 1, 101002, 0, 0, 426);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "カボチャの馬車に\nガラスの靴…\n欲しいなぁ", 1, 101002, 0, 0, 427);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "うちがガラスの靴を\n落としたら、王子はん\n見つけてくれるやろか", 1, 101002, 0, 0, 428);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "マホマホ王国\n次期国王の王子はん\n…見てみたいわ～", 1, 101002, 0, 0, 429);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ほんまなぁ\nこの絵本が面白いんよ\n王子はんに\n読んであげよ", 1, 101002, 0, 0, 430);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "マホ姫と王子はん\n絵本の世界より\nベストカップルや", 1, 101002, 0, 0, 431);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "王子はんと\n一緒にいると\n胸がせわしのー\nうごいてかなん", 1, 101002, 0, 0, 432);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "たまには、王子はんの\n好きな絵本も\n知りたいな～", 1, 101002, 0, 0, 433);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "王子はんを\n国に連れて帰ったら\nみんな大歓迎して\nくれるやろなぁ", 1, 101002, 0, 0, 434);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そのうち、王子はんの\nお国にも連れてって\nもらえますやろか？", 1, 101002, 0, 0, 435);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "絵本読むんも\nええなぁ…", 1, 101002, 0, 0, 436);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "うちがもし悪い魔法に\nかかったら、王子はん\n口づけしてくれはる？", 1, 101002, 0, 0, 437);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "うちら並んでたら\nお雛様みたいに\n見えると思いまへん？", 1, 101002, 0, 0, 438);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝は小鳥はんも\nおなかがすいてるから\nよう飛び回りはるねえ", 1, 101002, 0, 1, 439);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "マホマホ王国では\nこの時分は\nみんなお昼寝\nしてたんよ", 1, 101002, 0, 2, 440);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜に飛んだり鳴いたり\nする鳥はんもおるんよ\n昼は寝てはるんかねぇ", 1, 101002, 0, 3, 441);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "王子はんに\n会いに行くなら\nおめかしせな\nあかんなぁ", 1, 101002, 0, 0, 442);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "王子はんも一緒に\nゆっくりしていっても\nええんよ？", 1, 101002, 0, 0, 443);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かいらしい子やねぇ\nうちとお友だちに\nなってくれるん？", 1, 101002, 0, 0, 444);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "癒しアイテムって\nほんま、好っきゃわぁ", 1, 101002, 0, 0, 445);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "うちのお城にも\nほしいわぁ。帰ったら\nさっそく準備せな\nあかんなぁ", 1, 101002, 0, 0, 446);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "部屋の中で運動\nできるのも、なかなか\n面白いもんやわぁ", 1, 101002, 0, 0, 447);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいひいわ～\nマホマホ王国には\nない味やわぁ", 1, 101002, 0, 0, 448);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "しっかり知識を\n身につけんと\n魔法も使えへん\nからなぁ", 1, 101002, 0, 0, 449);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "１、２、３、４…\nあれ？　いま、\n何段目まで\n編んだっけ？", 1, 101101, 0, 0, 451);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "おやつのケーキは\n苺かチョコ…\nどっちも食べよう！", 1, 101101, 0, 0, 452);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "い、いけない！\n縫い針落としちゃった", 1, 101101, 0, 0, 453);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ケーキをクレープで\n巻いたら…\n大ヒット商品の予感！", 1, 101101, 0, 0, 454);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "「どうだ！妹暮らし」\nってことわざ\nなかったっけ？", 1, 101101, 0, 0, 455);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お兄ちゃんに、\nお洋服でも\n作ろうかな？", 1, 101101, 0, 0, 456);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ここがお兄ちゃんの\n部屋…\nドキドキしちゃう～", 1, 101101, 0, 0, 457);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ねぇ、おにいちゃん\n一緒に、スイーツでも\n食べにいかない？", 1, 101101, 0, 0, 458);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "クリームついてた！？\nさっき食べた、\nケーキかも…！", 1, 101101, 0, 0, 459);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "勉強、見てくれるん\nですか？　やった～♪", 1, 101101, 0, 0, 460);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "服がほつれてますよ？\n直してあげます！", 1, 101101, 0, 0, 461);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "私をお嫁さんに\nしたいなら、予約は\nお早目に、ですよ♪", 1, 101101, 0, 0, 462);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ねぇねぇお兄ちゃん！\n…えへへ、\n呼んでみただけ♪", 1, 101101, 0, 0, 463);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日も１日\n勉強がんばります！\n…少しは遊ぼうかな", 1, 101101, 0, 1, 464);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼休憩に\n甘いものが\n食べたいです～", 1, 101101, 0, 2, 465);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ねむいです～\nでももうちょっと\n勉強しないと～…", 1, 101101, 0, 3, 466);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "この服、かわいい♪\n今度作って\nみよっと～！", 1, 101101, 0, 0, 467);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "勉強で疲れたから\n休憩しよ～っと", 1, 101101, 0, 0, 468);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい♪\n私が服を作って\nあげよっか？", 1, 101101, 0, 0, 469);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "リラックスできます～\nお兄ちゃんが隣に\nいるみたい！", 1, 101101, 0, 0, 470);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "のんびりしたら、\nまた勉強しよっと！", 1, 101101, 0, 0, 471);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "運動すると勉強も\nはかどるよね！", 1, 101101, 0, 0, 472);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいし～！\nお兄ちゃんにも\nおすそ上げしますね！", 1, 101101, 0, 0, 473);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "お兄ちゃんの記憶を\n戻す方法、どこかに\n書いてないかな？", 1, 101101, 0, 0, 474);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ケーキの食べ過ぎで\nお腹が…うぅ、\n因果横暴だよー…", 1, 101102, 0, 0, 476);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "１、２、３、４…\nあれ？　いま、\n何段目まで\n編んだっけ？", 1, 101102, 0, 0, 477);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "い、いけない！\n縫い針落としちゃった", 1, 101102, 0, 0, 478);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "笑う時には服着ます！", 1, 101102, 0, 0, 479);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "「どうだ！妹暮らし」\nってことわざ\nなかったっけ？", 1, 101102, 0, 0, 480);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "お兄ちゃんに、\nお洋服でも\n作ろうかな？", 1, 101102, 0, 0, 481);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "お兄ちゃんが帰って\nきたら、何して遊ぼう\nかな～？", 1, 101102, 0, 0, 482);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "勉強、見てくれるん\nですか？　やった～♪", 1, 101102, 0, 0, 483);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "クリームついてた！？\nさっき食べた、\nケーキかも…！", 1, 101102, 0, 0, 484);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おにいちゃん！\nそろそろ、おやつに\nしませんか？", 1, 101102, 0, 0, 485);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "勉強は…\n明日にしようっと", 1, 101102, 0, 0, 486);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "妹だけど、大人な\nレディですからね！", 1, 101102, 0, 0, 487);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "な、ナデナデとか\n恥ずかしいな～", 1, 101102, 0, 0, 488);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日も１日\n勉強がんばります！\n…少しは遊ぼうかな", 1, 101102, 0, 1, 489);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼休憩に\n甘いものが\n食べたいです～", 1, 101102, 0, 2, 490);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お兄ちゃんは\n夜強いんですね\n私は眠くて…", 1, 101102, 0, 3, 491);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "服装や髪形が変わると\n気分も変わるよね", 1, 101102, 0, 0, 492);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ここで寝ちゃったら\n受験勉強が～…\nぐーー", 1, 101102, 0, 0, 493);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい♪\n私が服を作って\nあげよっか？", 1, 101102, 0, 0, 494);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いまならどんな試験も\n合格できそうです！", 1, 101102, 0, 0, 495);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "のんびりしたら\nまた勉強しよっと！", 1, 101102, 0, 0, 496);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "お兄ちゃんを\n守るためには\n毎日、鍛えなくちゃ！", 1, 101102, 0, 0, 497);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいし～！\nお兄ちゃんにも\nおすそ上げしますね！", 1, 101102, 0, 0, 498);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "この本の服\nかわいいなぁ♪\n私に作れるかな？", 1, 101102, 0, 0, 499);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "う～ん、今なら\nどこでだって\n眠れちゃいそう…", 1, 101201, 0, 0, 501);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "たくさん寝すぎて、\n夢の中か現実か\nわかんなく\nなっちゃうんだよね～", 1, 101201, 0, 0, 502);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "…はっ！？\nね、寝てないよ？\nホントだよっ", 1, 101201, 0, 0, 503);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ぐっすり眠って\nパワーを\nフルチャージっ☆", 1, 101201, 0, 0, 504);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "もし、超能力のことが\nバレたら…ブルブル", 1, 101201, 0, 0, 505);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "テレパシーで\nキミの心を覗けたら\n…なんてね！", 1, 101201, 0, 0, 506);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "キミを抱き枕に…\nじょ、冗談冗談！", 1, 101201, 0, 0, 507);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ん～、なになに？\n一緒にお昼寝する？", 1, 101201, 0, 0, 508);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "忘れ物しちゃった。\nま、いっか！\nえ、ダメ？", 1, 101201, 0, 0, 509);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おおっ、相談ごと？\nなにかな\nなにかな～？", 1, 101201, 0, 0, 510);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "う～ん、もしかして\nキミにも仲良しになる\n超能力があるのかも！", 1, 101201, 0, 0, 511);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "むむ～…どう？\nテレパシーで、私の\n気持ちを送ったよ！", 1, 101201, 0, 0, 512);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "えっ？　私とキミとの\n相性？　むむ～…\nうん、バッチリだよ☆", 1, 101201, 0, 0, 513);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "まだこんな時間？\nベッドに行って、\n二度寝しなくちゃ～", 1, 101201, 0, 1, 514);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "適度なお昼寝は\n健康にいいんだって！\n８時間くらいかな？", 1, 101201, 0, 2, 515);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "どんなにお昼寝しても\n夜は眠いんだ～", 1, 101201, 0, 3, 516);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "ん～、また寝癖…\nいっつも\n寝てるからかなぁ？", 1, 101201, 0, 0, 517);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "一休み、一休み…\nどうせなら百休み\nくらいしようかな…", 1, 101201, 0, 0, 518);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "これ…可愛い！\nシオリンに\n届けてあげたい！", 1, 101201, 0, 0, 519);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ん～…気分爽快！\nそれじゃ、おやすみ～\n…すやぁ…", 1, 101201, 0, 0, 520);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "気持ちいい…\nはっ！　ダメダメ！\nまた寝るとこだった！", 1, 101201, 0, 0, 521);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "眠くならないように、\n運動しよっと！", 1, 101201, 0, 0, 522);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "お腹いっぱいになると\n眠くなるよね～", 1, 101201, 0, 0, 523);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "睡眠学習って\n本を読みながら\n寝るんだっけ？", 1, 101201, 0, 0, 524);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "う～ん、今なら\nどこでだって\n眠れちゃいそう…", 1, 101202, 0, 0, 526);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "もっといっぱい\n超能力使えたら\nいいのにな～", 1, 101202, 0, 0, 527);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ねえねえ、\n今から人助け、\n付き合ってほしいなー", 1, 101202, 0, 0, 528);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ぐっすり眠って\nパワーを\nフルチャージっ☆", 1, 101202, 0, 0, 529);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "人助け、頑張ったら\nなんだか、眠く…\n…はっ、ダメダメ！", 1, 101202, 0, 0, 530);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "キミと一緒なら、\nなんだって出来る！\n間違いない！", 1, 101202, 0, 0, 531);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "キミを抱き枕に…\nじょ、冗談冗談！", 1, 101202, 0, 0, 532);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "忘れ物しちゃった\nま、いっか！\nえ、ダメ？", 1, 101202, 0, 0, 533);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "なに？　困ってる？\nちょうど良かった！\n今は体力満タンだよ☆", 1, 101202, 0, 0, 534);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "一緒に\nお出かけしたいなー\nデートしよっ！", 1, 101202, 0, 0, 535);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "うんうん、そうだねっ\n困ってる人がいたら\n見過ごせないよねっ！", 1, 101202, 0, 0, 536);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "むむ～…どう？\nテレパシーで、私の\n気持ちを送ったよ！", 1, 101202, 0, 0, 537);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "う～だんだん眠く…\nねぇ一緒に寝よ？", 1, 101202, 0, 0, 538);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "キミって早起きだね！\n私は寝ようかな～", 1, 101202, 0, 1, 539);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "適度なお昼寝は\n健康にいいんだって！\n８時間くらいかな？", 1, 101202, 0, 2, 540);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "どんなにお昼寝しても\n夜は眠いんだ～", 1, 101202, 0, 3, 541);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "ん～、また寝癖…\nいっつも\n寝てるからかなぁ？", 1, 101202, 0, 0, 542);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "一休み、一休み…\nどうせなら百休み\nくらいしようかな…", 1, 101202, 0, 0, 543);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "これ…可愛い！\nシオリンに\n届けてあげたい！", 1, 101202, 0, 0, 544);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ん～…気分爽快！\nそれじゃ、おやすみ～\n…すやぁ…", 1, 101202, 0, 0, 545);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "うう～ん、なんだか\nいつもより眠ーく\nなってきたよ…", 1, 101202, 0, 0, 546);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "よーし\n困ってる人のために\nパワーアップ☆", 1, 101202, 0, 0, 547);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食べてすぐ寝ると\n牛になるんだっけ？\nまぁ、いいかぁ～", 1, 101202, 0, 0, 548);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "睡眠学習って\n本を読みながら\n寝るんだっけ？", 1, 101202, 0, 0, 549);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "モデルは楽しいよ！\nファンの子みんな\n応援してくれるしー！", 1, 101601, 0, 0, 551);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "今日のおやつは\n駄菓子に決定～！\nいただきまーす！", 1, 101601, 0, 0, 552);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "んー、今日のおやつは\n何にしよう？\nやっぱアメ玉かな！", 1, 101601, 0, 0, 553);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ここで撮影会、\nしようかな～♪", 1, 101601, 0, 0, 554);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "７かける８はぁ\n７＋７＋７＋７＋…\nん、何個数えたっけ？", 1, 101601, 0, 0, 555);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "やば…\nこのままじゃ、うち\nキュン死にかも…", 1, 101601, 0, 0, 556);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "好きなことして\nヒデサイもいて\nうちって超～\nリア充だよね♪", 1, 101601, 0, 0, 557);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "うちの写真撮るの？\nどんなポーズ？", 1, 101601, 0, 0, 558);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ネイルの勉強中～♪\nうまくなったら、\nヒデサイにしてあげる", 1, 101601, 0, 0, 559);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "宿題見てくんない？\nひとりじゃムリ～", 1, 101601, 0, 0, 560);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "みてこのネイル♪\n超エモくな～い？\nヒデサイもする～？", 1, 101601, 0, 0, 561);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "新しい美容液で\n肌まじスベスベ～\nヒデサイも\n触ってみる？", 1, 101601, 0, 0, 562);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ヒデサイと会ってると\n顔熱くなるんだよね\n熱なんかないのに…", 1, 101601, 0, 0, 563);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "早起きとか\nつらたんだよねー\n昼すぎまで寝てたい", 1, 101601, 0, 1, 564);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "撮影にむけて\nダイエットちうだから\nお昼ぬいてるんだー", 1, 101601, 0, 2, 565);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お腹すいたー\nでもこの時間に\n食べたら絶対に\n太るやつだよねー", 1, 101601, 0, 3, 566);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "どんなシーンにも合う\nきれいめわがまま\nちゃんとコーデだよ♪", 1, 101601, 0, 0, 567);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ちょっち疲れたかも？\nガン寝しちゃおっかな", 1, 101601, 0, 0, 568);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "きゃわたーん☆\n君もおしゃれしよっか", 1, 101601, 0, 0, 569);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いいにおいじゃん！\nこれと同じにおいの\n香水ないかな？", 1, 101601, 0, 0, 570);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったまるー\nこれ、サイツヨに\n癒しじゃない？", 1, 101601, 0, 0, 571);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "あはは、なんか\nウォーキングの練習\nしてるみたーい！", 1, 101601, 0, 0, 572);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "体形維持しないと\nいけないけど\nついつい食べちゃう！", 1, 101601, 0, 0, 573);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "全然読めない～\nそだ、ヒデサイに\n読んでもらおっと！", 1, 101601, 0, 0, 574);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "そろそろ\n仕事の時間だ～\n出かける準備\nしよっと！", 1, 101602, 0, 0, 576);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "今日のおやつは\n駄菓子に決定～！\nいただきまーす！", 1, 101602, 0, 0, 577);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ヒデサイを見習って\nうちも少し勉強して\nみよっかな…　", 1, 101602, 0, 0, 578);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "体形維持とか\n気にしてるんだよ～", 1, 101602, 0, 0, 579);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "７かける８はぁ\n７＋７＋７＋７＋…\nん、何個数えたっけ？", 1, 101602, 0, 0, 580);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "やば…\nこのままじゃ、うち\nキュン死にかも…　", 1, 101602, 0, 0, 581);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ヒデサイと会ってると\n顔熱くなるんだよね\n熱なんかないのに…", 1, 101602, 0, 0, 582);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "うちの写真撮るの？\nどんなポーズ？", 1, 101602, 0, 0, 583);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ネイルの勉強中～♪\nうまくなったら、\nヒデサイに\nしてあげる♪", 1, 101602, 0, 0, 584);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "この雑誌の服\nガチめにほしぃ～", 1, 101602, 0, 0, 585);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "うちのコーデで\nヒデサイをオシャンに\nしてあげるね♪", 1, 101602, 0, 0, 586);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "新しい美容液で\n肌まじスベスベ～\nヒデサイも\n触ってみる？", 1, 101602, 0, 0, 587);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "好きなことして\nヒデサイもいて\nうちって超～\nリア充だよね♪", 1, 101602, 0, 0, 588);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日は早起き\nできたんだー\nメイクもばっち\nきまってるっしょ？", 1, 101602, 0, 1, 589);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "撮影にむけて\nダイエットちうだから\nお昼ぬいてるんだー", 1, 101602, 0, 2, 590);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お腹すいたー\nでもこの時間に\n食べたら絶対に\n太るやつだよねー", 1, 101602, 0, 3, 591);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "この服ね～\n今年のトレンドなんだ♪\nかわたんでしょ！", 1, 101602, 0, 0, 592);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ちょっち疲れたかも？\nガン寝しちゃおっかな", 1, 101602, 0, 0, 593);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "うわー\nこのぬいぐるみ\nもきゅすぎでしょ～！", 1, 101602, 0, 0, 594);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いいにおーい♪\nファンのみんなにも\n教えてあげよー♪", 1, 101602, 0, 0, 595);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったまるー\nこれ、サイツヨに\n癒しじゃない？", 1, 101602, 0, 0, 596);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "食べた分は\n消費しないとね～", 1, 101602, 0, 0, 597);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "体形維持しないと\nいけないけど\nついつい食べちゃう！", 1, 101602, 0, 0, 598);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "全然読めない～\nそだ、ヒデサイに\n読んでもらおっと！", 1, 101602, 0, 0, 599);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "やっさー\n踊ってると、どんどん\n楽しくなるさー！", 1, 101701, 0, 0, 601);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "このお菓子、でーじ\nおいしいねー！\nキミも食べる？", 1, 101701, 0, 0, 602);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ハイターイ！　元気な\nあいさつが一番さ～！", 1, 101701, 0, 0, 603);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "あまった食材があれば\nチャンプルーにして\n食べたいさー！ ", 1, 101701, 0, 0, 604);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "さぁ、みんなで歌って\n踊るさ～♪", 1, 101701, 0, 0, 605);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "毎日、最高に幸せさ～\nキミのおかげだねー", 1, 101701, 0, 0, 606);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "キミへの気持ちを\n踊りで表現\nしてみるさ～", 1, 101701, 0, 0, 607);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "海でひと泳ぎ\nしたいさ～\nキミもどう？", 1, 101701, 0, 0, 608);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あぎひゃっ！\n急に声かけたら、\nビックリするさ～", 1, 101701, 0, 0, 609);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "踊りなら、\n私が手とり足とり\n教えてあげるさ～！", 1, 101701, 0, 0, 610);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "空手の型の\n練習するさー\nキミもどう？", 1, 101701, 0, 0, 611);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "よ～し、手をつないで\n踊るさ～！\n恥ずかしがること\nないさ～", 1, 101701, 0, 0, 612);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "キミと一緒だから、\n毎日楽しいこと\nばっかりさー", 1, 101701, 0, 0, 613);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ハイターイ！\n今日も一日、\nがんばるさー！", 1, 101701, 0, 1, 614);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "午後も頑張るために\nお昼ご飯は\nてびちにするさー！", 1, 101701, 0, 2, 615);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "故郷では見えない星が\n見られるんだねえ。\nなんか不思議さぁ", 1, 101701, 0, 3, 616);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "夢中で踊ってたら、\n髪の毛ぼさぼさに\nなってるさ～！？", 1, 101701, 0, 0, 617);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "よく食べてよく踊って\nよく休む。\nそれが元気の秘訣さ～", 1, 101701, 0, 0, 618);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ちゅらかーぎーねー！\nキミはどこから\n来たのー？", 1, 101701, 0, 0, 619);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り～、って\n私もカオリだったさ！\nなんだか照れるね☆", 1, 101701, 0, 0, 620);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "故郷はあんまり暖房を\n使わなかったから、\n新鮮さー！", 1, 101701, 0, 0, 621);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "汗をかくのは\n気持ちいいさー！\nどんどん行くよー！", 1, 101701, 0, 0, 622);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "うーん、おいしいさ～\nゴーヤっぽいものを\n混ぜたいさ～", 1, 101701, 0, 0, 623);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "おおー、故郷の民話！\nこんなとこで見るとは\n懐かしいさぁ～！", 1, 101701, 0, 0, 624);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "焦らなくても\nなんくるないさ～\nなるようになるさ～", 1, 101702, 0, 0, 626);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "さぁ、みんなで歌って\n踊るさ～♪", 1, 101702, 0, 0, 627);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "元気がないときは\n私のところに来るさー", 1, 101702, 0, 0, 628);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "あまった食材があれば\nチャンプルーにして\n食べたいさー！ ", 1, 101702, 0, 0, 629);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ノリノリな音楽と\n踊りで、疲れを\n吹き飛ばすさ～！", 1, 101702, 0, 0, 630);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "毎日、最高に幸せさ～\nキミのおかげだねー", 1, 101702, 0, 0, 631);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "幸せすぎて踊らずには\nいられないさ～", 1, 101702, 0, 0, 632);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "海でひと泳ぎ\nしたいさ～\nキミもどう？", 1, 101702, 0, 0, 633);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ん？　どうしたの～？\nヒマなら一緒に\n踊ろうさ～", 1, 101702, 0, 0, 634);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "キミと一緒だから\n毎日楽しいこと\nばっかりさー", 1, 101702, 0, 0, 635);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ハイターイ！　元気な\nあいさつが一番さ～！", 1, 101702, 0, 0, 636);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "キミと踊ってる時が\n一番幸せさ～\nキミもそう思ってたら\nうれしいさ～", 1, 101702, 0, 0, 637);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "海に沈む夕日は\nとっても綺麗さ～！\n今度一緒に見ようね～ ", 1, 101702, 0, 0, 638);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "気持ちのいい朝さー！\nひとっ走り\nしてくるさー！", 1, 101702, 0, 1, 639);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "午後も頑張るために\nお昼ご飯は\nてびちにするさー！ ", 1, 101702, 0, 2, 640);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "故郷では見えない星が\n見られるんだねえ\nなんか不思議さぁ ", 1, 101702, 0, 3, 641);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "夢中で踊ってたら\n髪の毛ぼさぼさに\nなってるさ～！？", 1, 101702, 0, 0, 642);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "よく食べてよく踊って\nよく休む\nそれが元気の秘訣さ～", 1, 101702, 0, 0, 643);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ちゅらかーぎーねー！\nキミはどこから\n来たのー？ ", 1, 101702, 0, 0, 644);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り～、って\n私もカオリだったさ！\nなんだか照れるね☆ ", 1, 101702, 0, 0, 645);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "故郷はあんまり暖房を\n使わなかったから\n新鮮さー！", 1, 101702, 0, 0, 646);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "徹夜で踊り続ける\nためにも、まずは\n体を鍛えるさ～", 1, 101702, 0, 0, 647);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…もっと\nおかわりがほしいさー", 1, 101702, 0, 0, 648);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "おおー、故郷の民話！\nこんなとこで見るとは\n懐かしいさぁ～！ ", 1, 101702, 0, 0, 649);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "はあ…\nすてきな小説だった～\nキュンキュンしちゃう", 1, 101801, 0, 0, 651);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "このお部屋\n女の子ばかりね。\n魔族の女子校を\n思い出しちゃう♪", 1, 101801, 0, 0, 652);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "次のテスト\n恋愛小説から\n出題したら\nダメかしら…？", 1, 101801, 0, 0, 653);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "キンコンカンコ～ン♪\n授業をはじめま～す", 1, 101801, 0, 0, 654);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "はー…\nちょっと肩が\nこっちゃった…", 1, 101801, 0, 0, 655);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "私、あの子のこと\n無意識に特別扱い\nしちゃってるかな…", 1, 101801, 0, 0, 656);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "物語だと生徒が先生を\n好きになるのにな…\n逆の場合は…", 1, 101801, 0, 0, 657);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あん！　見ちゃダメよ\n明日のテストの問題を\n作ってるとこなの！", 1, 101801, 0, 0, 658);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "勉強勉強で\n疲れたよね？\n膝枕してあげる！", 1, 101801, 0, 0, 659);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "テストがんばったね～\nご褒美に先生が\n特別な授業\nしてあげるね？", 1, 101801, 0, 0, 660);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "学院の外でも\n私は君の先生よ\nなんでも聞いてね♪", 1, 101801, 0, 0, 661);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "今読んでるのは\nヒロインが年下の子と\n恋に落ちる話…あ、\n深い意味はないのよ～", 1, 101801, 0, 0, 662);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "生徒は全員可愛いけど\n君は少し特別…\nみんなには内緒よ？", 1, 101801, 0, 0, 663);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "学校に\n遅刻しないように\n早く準備しないとね", 1, 101801, 0, 1, 664);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "男の子といっしょに\nお弁当を食べるの、\n夢なんだ～", 1, 101801, 0, 2, 665);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "明日の予習はやった？\n先生も手伝うから\n寝る前にやりましょ♪", 1, 101801, 0, 3, 666);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "もしかして…\n少し露出多いかしら？", 1, 101801, 0, 0, 667);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "リラックスすると\nα波が出て、勉強が\nはかどるんですって", 1, 101801, 0, 0, 668);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい♪　あなたも\n私の生徒になる？", 1, 101801, 0, 0, 669);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "学院にもこういう\n安らぐ設備が\n必要かしらね？", 1, 101801, 0, 0, 670);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "まだ寒いわぁ\n誰か隣に\n来てくれたら…", 1, 101801, 0, 0, 671);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "運動部の顧問も\nできるかしら？", 1, 101801, 0, 0, 672);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "学校の給食でも\n食べたいわぁ～", 1, 101801, 0, 0, 673);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "いい参考書を\n見つけちゃった♪", 1, 101801, 0, 0, 674);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "私の生徒に\n不良なんていないわ\nみーんないい子♪", 1, 101802, 0, 0, 676);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "このお部屋\n女の子ばかりね\n魔族の女子校を\n思い出しちゃう♪", 1, 101802, 0, 0, 677);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "あの子、まだかな…\n宿題も見てあげたいし\n早く来ないかしら？", 1, 101802, 0, 0, 678);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "はあ…\nすてきな小説だった～\nキュンキュンしちゃう", 1, 101802, 0, 0, 679);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "学校の図書室に\n恋愛小説を\n置いて欲しいなあ", 1, 101802, 0, 0, 680);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "私、あの子のこと\n無意識に特別扱い\nしちゃってるかな…", 1, 101802, 0, 0, 681);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "物語だと生徒が先生を\n好きになるのにな…\n逆の場合は…　", 1, 101802, 0, 0, 682);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あん！　見ちゃダメよ\n明日のテストの問題を\n作ってるとこなの！", 1, 101802, 0, 0, 683);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "勉強勉強で\n疲れたよね？\n膝枕してあげる！", 1, 101802, 0, 0, 684);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "宿題はもうやった？\n苦手なところは\n先生が見てあげる♪", 1, 101802, 0, 0, 685);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "んん？　なんだか\n元気がないみたい\n先生がぎゅぅ～って\nしてあげる…　", 1, 101802, 0, 0, 686);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "君のお勉強も\nだいぶ進んできたね～\n補習卒業も近いかな？\n少し寂しいけど…", 1, 101802, 0, 0, 687);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "テストがんばったね～\nご褒美に先生が\n特別な授業\nしてあげるね？", 1, 101802, 0, 0, 688);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝の特別授業\nしてあげましょうか？", 1, 101802, 0, 1, 689);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "午後の授業って\n眠いでしょう？\n気持ちは分かるけど\nがんばってね♪", 1, 101802, 0, 2, 690);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "明日の予習はやった？\n先生も手伝うから\n寝る前にやりましょ♪", 1, 101802, 0, 3, 691);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "もしかして…\n少し露出多いかしら？", 1, 101802, 0, 0, 692);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "私の膝枕と、どっちが\nフカフカかしら？", 1, 101802, 0, 0, 693);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "可愛いわね～\n教室に置いたら\n生徒が喜ぶかしら？　", 1, 101802, 0, 0, 694);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "は～落ち着くなぁ～\n教師には\nこういうゆとりも\n必要よね♪　", 1, 101802, 0, 0, 695);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "まだ寒いわぁ\n誰か隣に\n来てくれたら…　", 1, 101802, 0, 0, 696);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "運動部の顧問も\nできるかしら？　", 1, 101802, 0, 0, 697);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "あん！\nお胸にこぼしちゃった", 1, 101802, 0, 0, 698);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "あぁーん♪\nこういう物語みたいな\n恋愛あこがれる～　", 1, 101802, 0, 0, 699);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "おにいちゃんは、\nにんじん食べられる？", 1, 102001, 0, 0, 701);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "えへへ、\nお絵かきしよ～♪", 1, 102001, 0, 0, 702);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "あのね、ミミと\nあそんでほしいな～", 1, 102001, 0, 0, 703);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "さっきね、きれいな\nお花見つけたよ。\nおにいちゃんにも\n見せてあげたいな～", 1, 102001, 0, 0, 704);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "うさぎさん、\nぴょんぴょん\nぴょーん♪", 1, 102001, 0, 0, 705);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "おにいちゃんの絵、\nかいてあげるね♪", 1, 102001, 0, 0, 706);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "おっきくなったら\nおにいちゃんの\nお嫁さんになるんだ♪", 1, 102001, 0, 0, 707);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふわぁ！\nおにいちゃんの手、\nおっきいね～", 1, 102001, 0, 0, 708);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "やった～！\nおにいちゃんが\nほめてくれた～", 1, 102001, 0, 0, 709);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ねえねえ\nおにいちゃん、\n一緒にあそぼっ♪", 1, 102001, 0, 0, 710);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "おにいちゃん、\n遊んでくれるの？\n　わぁい♪", 1, 102001, 0, 0, 711);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "わぁい！\nおにいちゃんだ～♪\nぎゅ～っ！", 1, 102001, 0, 0, 712);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あのねあのね、\nミミの頭ポンポンって\nしてほしいな", 1, 102001, 0, 0, 713);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おひさまさん、\nおはよ～！\n毎朝、早おきだね～", 1, 102001, 0, 1, 714);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "うわぁ！\nお日さまがすごーく\n高いところにある～", 1, 102001, 0, 2, 715);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おにいちゃん\nおやすみのご本\nよんで～", 1, 102001, 0, 3, 716);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "ミミも、\nうさぎさんみたいに、\nかわいくなりたいな♪", 1, 102001, 0, 0, 717);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "のんびり～♪\nゆったり～♪\nまったり～♪", 1, 102001, 0, 0, 718);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "わぁ～かわいい～♪\nミミ、幸せ～♪\n抱きついていいかな？", 1, 102001, 0, 0, 719);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いいにおい～♪\nお鼻ピクピク♪\nうさぎさんも喜ぶよ♪", 1, 102001, 0, 0, 720);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったか～♪\nぬくぬく～♪\nポカポカ～♪", 1, 102001, 0, 0, 721);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "ふ、ふぇ～　ミミ、\n運動苦手だよ～", 1, 102001, 0, 0, 722);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "はむ♪　いっぱい\n食べて、はやく\nおっきくなりたいな～", 1, 102001, 0, 0, 723);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ミミね！\nこのお話だーい好き！", 1, 102001, 0, 0, 724);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ぴょんぴょん\n跳ねるよ\nうっさぎっさ～ん♪", 1, 102002, 0, 0, 726);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "うさぎさんの\nマネだよ～\n似てるかな～？", 1, 102002, 0, 0, 727);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "モフモフすると\nきもちい～よ", 1, 102002, 0, 0, 728);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ミソギちゃん\nキョウカちゃん\nあ～そ～ぼっ！", 1, 102002, 0, 0, 729);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "おにいちゃん\nおやすみのご本\nよんで～", 1, 102002, 0, 0, 730);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "ねえ、おにいちゃん\nミミのこと、すき？", 1, 102002, 0, 0, 731);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "おっきくなったら\nおにいちゃんの\nお嫁さんになるんだ♪", 1, 102002, 0, 0, 732);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "やった～！\nおにいちゃんが\nほめてくれた～", 1, 102002, 0, 0, 733);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おにいちゃん\n遊んでくれるの？\nわぁい♪", 1, 102002, 0, 0, 734);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おにいちゃん\nあのね…\nいいこいいこして～", 1, 102002, 0, 0, 735);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あはは～\nくすぐったいよ～", 1, 102002, 0, 0, 736);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "おにいちゃんの\nおひざの上、とっても\n安心するんだ～！", 1, 102002, 0, 0, 737);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "わぁい♪\nおにいちゃんの\nなでなで\nうれし～な♪", 1, 102002, 0, 0, 738);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おひさまさん\nおはよ～！\n毎朝、早おきだね～", 1, 102002, 0, 1, 739);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼寝お昼寝～♪\nおにいちゃんと一緒に\nお昼寝～♪", 1, 102002, 0, 2, 740);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "眠くなっちゃった～\nおにいちゃん！\n今日は一緒に寝よ～", 1, 102002, 0, 3, 741);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "ミミも\nうさぎさんみたいに\nかわいくなりたいな", 1, 102002, 0, 0, 742);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふわふわ～モコモコ～\n気持ちいい～♪\nミミもゴロゴロ～ン♪", 1, 102002, 0, 0, 743);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "わぁ～かわいい～♪\nミミ、幸せ～♪\n抱きついていいかな？", 1, 102002, 0, 0, 744);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いいにおい～♪\nお鼻ピクピク♪\nうさぎさんも喜ぶよ～♪", 1, 102002, 0, 0, 745);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったか～♪\nぬくぬく～♪\nポカポカ～♪", 1, 102002, 0, 0, 746);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "はぁはぁ…\nふえ～ミミ\n疲れちゃうよ～！", 1, 102002, 0, 0, 747);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "はむ♪　いっぱい\n食べて、はやく\nおっきくなりたいな～", 1, 102002, 0, 0, 748);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ミミね！\nこのお話だーい好き！", 1, 102002, 0, 0, 749);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "はぅぅ…\n部屋のどこにいたら\nいいんだろう…", 1, 102101, 0, 0, 751);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "お外より\nお部屋の中の方が\n落ち着くな…", 1, 102101, 0, 0, 752);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "クッキー焼いたら\nみんな食べてくれる\nかなぁ…", 1, 102101, 0, 0, 753);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "あ、あめんぼあかいな\nあいうえお！", 1, 102101, 0, 0, 754);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "お芝居には\n人間観察が大事…\nじーーーーーー…", 1, 102101, 0, 0, 755);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お兄ちゃんを見ると、\n顔が赤くなっちゃうの\n…な、なんでかな？", 1, 102101, 0, 0, 756);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "れ、恋愛劇…\nお、お兄ちゃんと\n練習…", 1, 102101, 0, 0, 757);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "こ、この本、とっても\nおもしろいんですよ♪", 1, 102101, 0, 0, 758);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "い、一緒に遊んで\nくれるんですか？\nや、やったぁ～♪", 1, 102101, 0, 0, 759);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ランドソルには\n慣れましたか？\nわ、私はまだ…", 1, 102101, 0, 0, 760);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お、お兄ちゃん、\nお、お話の練習に\n付き合って欲しいです", 1, 102101, 0, 0, 761);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "リボンがかわいい？\nほ、ほぇぇぇ～～\nは、恥ずかしいですぅ", 1, 102101, 0, 0, 762);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お兄ちゃん…♪\nえへへ、呼んでみた\nだけです…♪", 1, 102101, 0, 0, 763);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日は一日、\n恥ずかしがらずに\n過ごせるかなあ…？", 1, 102101, 0, 1, 764);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ご飯、どうぞ♪\nわ、私、お料理、\nうまくなったかな？", 1, 102101, 0, 2, 765);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おにいちゃんが\n帰ってくるまで、\nがんばって\n起きてました", 1, 102101, 0, 3, 766);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "可愛い女の子に変身！\n出来ますように…♪", 1, 102101, 0, 0, 767);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふかふかで\nあったかくて…\nお兄ちゃんみたい♪", 1, 102101, 0, 0, 768);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "この子を相手に、\n演技の練習～", 1, 102101, 0, 0, 769);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "リボンや服に\n染み込ませておこう。\nいつでもいい匂い♪", 1, 102101, 0, 0, 770);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "えへへ。\nぽっかぽかです…", 1, 102101, 0, 0, 771);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "はぁはぁ…\nふひぃ…\nはうぅぅぅ～～", 1, 102101, 0, 0, 772);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…えへへ、\n美味しいものを\n食べてると幸せです", 1, 102101, 0, 0, 773);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "戯曲を読んで\n自分が演じるところを\n想像するの…", 1, 102101, 0, 0, 774);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "かわいいものを\nこうして並べて…\nはぁ…落ちつくぅ♪", 1, 102102, 0, 0, 776);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ふぁ～、この部屋は\n時間がゆったりと\n流れてるみたい", 1, 102102, 0, 0, 777);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "この台本、感動…\n涙が止まらないよぉ\nいつか演じてみたいな", 1, 102102, 0, 0, 778);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お芝居には\n人間観察が大事…\nじーーーーーー…", 1, 102102, 0, 0, 779);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "あえいうえおあお\nかけきくけ、かっ…\nむ、難しいですぅぅ", 1, 102102, 0, 0, 780);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "お、お腹が空いた時は\n言ってくださいね\nが、頑張って\n作ります！", 1, 102102, 0, 0, 781);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "れ、恋愛劇…\nお、お兄ちゃんと\n練習…", 1, 102102, 0, 0, 782);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "こ、この本、とっても\nおもしろいんですよ♪", 1, 102102, 0, 0, 783);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お兄ちゃんと\nいっぱい話せた日は、\n嬉しくなっちゃいます", 1, 102102, 0, 0, 784);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "何か私にできる事\n…そうだ！\nお掃除しますね！", 1, 102102, 0, 0, 785);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "私、ちょっとずつ、\n自分に自信が\nついてきたかもです…", 1, 102102, 0, 0, 786);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "リボンがかわいい？\nほ、ほぇぇぇ～～\nは、恥ずかしいですぅ", 1, 102102, 0, 0, 787);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お兄ちゃん…♪\nえへへ、呼んでみた\nだけです…♪", 1, 102102, 0, 0, 788);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます♪\n声出しして、お芝居の\n練習しなくちゃ", 1, 102102, 0, 1, 789);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お茶にしますか？\nクッキー焼いたので、\nよかったら…", 1, 102102, 0, 2, 790);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "寝る前に\n台本を読むと、\n覚えやすいんです", 1, 102102, 0, 3, 791);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "可愛い女の子に変身！\n出来ますように…♪", 1, 102102, 0, 0, 792);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "はぅ…\nフッカフカァ…\n癒されちゃいます…", 1, 102102, 0, 0, 793);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "この子を相手に\n演技の練習～", 1, 102102, 0, 0, 794);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "リボンや服に\n染み込ませておこう\nいつでもいい匂い♪", 1, 102102, 0, 0, 795);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "えへへ\nぽっかぽかです…", 1, 102102, 0, 0, 796);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "え、演劇には\nた、体力も重要\nだから～", 1, 102102, 0, 0, 797);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "残さず\n食べますね…！", 1, 102102, 0, 0, 798);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "戯曲を読んで\n自分が演じるところを\n想像するの…", 1, 102102, 0, 0, 799);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ねえ、人見知りを\n治すための練習に\n付き合ってくれない？", 1, 102201, 0, 0, 801);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "アカリみたいに\nかわいくなるには、\nどうすればいいのかな", 1, 102201, 0, 0, 802);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "レアカードをゲット！\nねえねえ、\nすごいでしょ！？", 1, 102201, 0, 0, 803);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ア、アイツと同じ\n部屋にいるのよね…\nって、だから何よ！？", 1, 102201, 0, 0, 804);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "楽しいゲームって\nやめどきが\n見つからないわ", 1, 102201, 0, 0, 805);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "もっと女の子らしく\nなったらアイツも\n嬉しいかな…って、\n何考えてるの！？", 1, 102201, 0, 0, 806);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "うぅ…最近、\nアイツを見るとなんか\nドキドキするのよね", 1, 102201, 0, 0, 807);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ゲームに負けた罰\nだからって、\nくすぐるのは…\nあはは…ダメだって！", 1, 102201, 0, 0, 808);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "アンタと話すのは割と\n緊張しないのよね\n…なんでかな", 1, 102201, 0, 0, 809);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "待ちきれない…\n新作ゲームの発売日が\n待ちきれない…", 1, 102201, 0, 0, 810);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "アンタは人見知り\nしないタチよね？\nいいなあ～…", 1, 102201, 0, 0, 811);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ア、アンタってさ\n好きな人とかい…\nなな、何でもない！", 1, 102201, 0, 0, 812);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "アンタと…そ、その\nこうして話してるのも\nわわ、悪くないわね！", 1, 102201, 0, 0, 813);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おおおおはよう！\n…よし！　ちゃんと\nあいさつできたわ！", 1, 102201, 0, 1, 814);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "一緒にごはんとか…\nううん、やっぱいい！\nなんでもないからっ！", 1, 102201, 0, 2, 815);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜はこれからよ！\n朝まで\nゲームするからね！", 1, 102201, 0, 3, 816);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "アカリみたいに\n可愛くなるのは\n難しいかな", 1, 102201, 0, 0, 817);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "寝っ転がりながら\nゲームができれば\n気分が良さそう", 1, 102201, 0, 0, 818);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "可愛い…けど、\n私には似合わないかな", 1, 102201, 0, 0, 819);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "はあ、リラックスして\nゲームができるわ", 1, 102201, 0, 0, 820);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ん…暖かくて、\n寝落ちしちゃいそう", 1, 102201, 0, 0, 821);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "ゲーム感覚でやると、\n体動かすのも\n楽しいわね", 1, 102201, 0, 0, 822);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ゲームは頭使うから\nそのぶん\n栄養がいるのよ", 1, 102201, 0, 0, 823);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ、なるほど\n友だちを作るには\n笑顔が大事っと…", 1, 102201, 0, 0, 824);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "さあ、今日は\n何のゲームで\n遊ぼうかな？", 1, 102202, 0, 0, 826);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "一緒にゲームができる\n人がいるっていうのも\n新鮮だな…", 1, 102202, 0, 0, 827);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "レアカードをゲット！\nすごいでしょ！？", 1, 102202, 0, 0, 828);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "アカリってどうやって\n友達作ってるんだろ？\nコツがあるのかな…", 1, 102202, 0, 0, 829);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "楽しいゲームって\nやめどきが\n見つからないわ", 1, 102202, 0, 0, 830);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "うぅ…最近\nアイツを見るとなんか\nドキドキするのよね", 1, 102202, 0, 0, 831);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ね、ねえ\nもう少しその…\n一緒にゲームしない？", 1, 102202, 0, 0, 832);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ねえ、人見知りを\n治すための練習に\n付き合ってくれない？", 1, 102202, 0, 0, 833);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "欲しいゲームが\n見つからなくて…\n探すの手伝って！", 1, 102202, 0, 0, 834);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ねえ、見て！\n新しいゲームを\n買って来たの！", 1, 102202, 0, 0, 835);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ゲームに負けた罰\nだからって、くすぐる\nのは…あ、あはは！\nだ、ダメだって！", 1, 102202, 0, 0, 836);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "ア、アンタってさ\n好きな人とかい…\nなな、何でもない！", 1, 102202, 0, 0, 837);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あ、あのさ…\nもう少し、そこに\nいてくれてもいいわよ", 1, 102202, 0, 0, 838);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おおおおはよう！\n…よし！　ちゃんと\nあいさつできたわ！", 1, 102202, 0, 1, 839);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "一緒にごはんとか…\nううん、やっぱいい！\nなんでもないからっ！", 1, 102202, 0, 2, 840);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜はこれからよ！\n朝まで\nゲームするからね！", 1, 102202, 0, 3, 841);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "もっと女の子らしく\nなったらアイツも\n嬉しいかな…って、\n何考えてるの！？", 1, 102202, 0, 0, 842);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふああ…\n徹夜明けには\n辛い誘惑だな…", 1, 102202, 0, 0, 843);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "可愛い…けど、\n私には似合わないかな", 1, 102202, 0, 0, 844);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "こういうのに詳しいと\n女の子っぽく\n見えたりするのかな", 1, 102202, 0, 0, 845);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "寒い日は\nここでゲームするのが\n最高のぜいたくよね", 1, 102202, 0, 0, 846);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "最近ゲームばかりだし\nたまにはいいかな？", 1, 102202, 0, 0, 847);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ゲームは頭使うから\nそのぶん\n栄養がいるのよ", 1, 102202, 0, 0, 848);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ、なるほど\n友だちを作るには\n笑顔が大事っと…", 1, 102202, 0, 0, 849);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "じゃんけんぽん！\nあっち向いてほい！\nあ～ん、負けたぁ\n　『勝ったぜ！』", 1, 102301, 0, 0, 851);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ぷうきちがいれば、\nなんでも出来ちゃうよ", 1, 102301, 0, 0, 852);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "発声練習しよっと\nぷうきち\nフルスイ～ング！", 1, 102301, 0, 0, 853);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ここで、ぷうきち\nフルスイングは、\nまずいかな～？", 1, 102301, 0, 0, 854);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "この部屋、ぷうきちを\n置く場所はないのかな", 1, 102301, 0, 0, 855);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お兄ちゃんって…\nちょっとぷうきちに\n似てるかも♪", 1, 102301, 0, 0, 856);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "お兄ちゃんにも、\nぷうきちのこと\n好きになって\nもらいたいな～", 1, 102301, 0, 0, 857);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おやつは、\n私とぷうきちの\n二人分用意してね♪", 1, 102301, 0, 0, 858);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ぷうきちが、お腹\nペコペコだって～\n何かちょうだい！", 1, 102301, 0, 0, 859);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "『アヤネに手出したら\n…坊ちゃんでも、\n分かってんな？』", 1, 102301, 0, 0, 860);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ぷうきちとの\n連携を磨いてるの！\nもっと仲良くなるよ！", 1, 102301, 0, 0, 861);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "特別だからね？\nもっと触っていいよ\n…ぷうきちのこと", 1, 102301, 0, 0, 862);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お兄ちゃんのこと、\n「ぷう兄」って\n呼ぼうかな？", 1, 102301, 0, 0, 863);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お兄ちゃんって\n朝早いんだね～\n私はまだ眠いよ～", 1, 102301, 0, 1, 864);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ふぁ～…ぷうきちと\nお昼寝してくるね…", 1, 102301, 0, 2, 865);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ぷうきちと\nおしゃべりしてたら\nもうこんな時間…", 1, 102301, 0, 3, 866);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "『座り心地がいいな』\nぷうきちは座れない\nでしょ？", 1, 102301, 0, 0, 868);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい～！\nぷうきちのお友達に\nしちゃおうかな？", 1, 102301, 0, 0, 869);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いいニオイ～♪\nぷうきちも\n気に入ったみたい！", 1, 102301, 0, 0, 870);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ぽわぽわする～\nぷうきちも\n気持ちいい？", 1, 102301, 0, 0, 871);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいしい～\nぷうきちも\n食べてみる？", 1, 102301, 0, 0, 873);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ぷうきち！\nこの本、読んで～！", 1, 102301, 0, 0, 874);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "どうして失敗ばっかり\nこうなったら\n腹を切るしか～！", 1, 102501, 0, 0, 901);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "あれ？　あれ？\nお部屋の中で迷子に\nなっちゃいました～", 1, 102501, 0, 0, 902);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "どうしたら転ばなく\nなるんでしょうか？", 1, 102501, 0, 0, 903);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "わわわわ～～っ\nふう…\nきゃ、きゃあっ！", 1, 102501, 0, 0, 904);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "私のドジで、\nこのお部屋を\n壊しちゃったら\nどうしましょう～～", 1, 102501, 0, 0, 905);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "おいしい料理で\nお出迎えしなくちゃ！", 1, 102501, 0, 0, 906);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "一生懸命\nご奉仕しますよ～♪", 1, 102501, 0, 0, 907);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "耳かきしましょうか？\nえ？　こわい？", 1, 102501, 0, 0, 908);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お疲れでしたら、\nお昼寝しませんか？\n膝枕もしますよ？", 1, 102501, 0, 0, 909);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おかえりなさいませ\nご主人さま♪", 1, 102501, 0, 0, 910);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "すみません\nすみません\nすみません～～", 1, 102501, 0, 0, 911);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "メイドの私が、\nこんな気持ちを持って\nいいんでしょうか…", 1, 102501, 0, 0, 912);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "私のこと、\n専属メイドと思って\n頼ってくださいね", 1, 102501, 0, 0, 913);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます♪\n今日も一日がんば…\nきゃ、きゃあ！", 1, 102501, 0, 1, 914);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ごはん…\n失敗しちゃいましたぁ\nお、おやつでリベンジします！", 1, 102501, 0, 2, 915);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "明日の目標は\nドジをしないです！\nき、昨日の目標も\nドジをしないでした", 1, 102501, 0, 3, 916);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "あ、メイド服が\nほつれてる\n後でお裁縫しなくちゃ", 1, 102501, 0, 0, 917);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "休憩が終わったら\nお洗濯にお料理に\nお掃除もしないと！", 1, 102501, 0, 0, 918);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい♪\nあとでお洗濯\nしてあげますね", 1, 102501, 0, 0, 919);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り…\nお嬢様のお部屋にも\n置いてあげたいです", 1, 102501, 0, 0, 920);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ここでお洗濯ものを\n乾かしましょうか", 1, 102501, 0, 0, 921);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "あわわわっ…\nこ、転びそうです～！", 1, 102501, 0, 0, 922);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "これくらい\nおいしいものを\n作ってみたいです～", 1, 102501, 0, 0, 923);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "物語のメイドさんって\n御主人さまを好きに\nなるんですよね…", 1, 102501, 0, 0, 924);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "失敗したら、この\nお部屋追い出され\nちゃうかも～？", 1, 102502, 0, 0, 926);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "あれ？　あれ？\nお部屋の中で迷子に\nなっちゃいました～", 1, 102502, 0, 0, 927);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "どうやったら、立派な\nメイドになれるのかな", 1, 102502, 0, 0, 928);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "塩にはＳマーク\n砂糖にはＳマーク\n…あ、あれ！？", 1, 102502, 0, 0, 929);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ご用があれば\nなんでも言って\nくださいね", 1, 102502, 0, 0, 930);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "迷惑をかけすぎて…\n嫌われちゃったら\nどうしましょう", 1, 102502, 0, 0, 931);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "メイドの私が\nこんな気持ちを持って\nいいんでしょうか…　", 1, 102502, 0, 0, 932);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おでかけですか？\nいってらっしゃいませ\nご主人さま♪", 1, 102502, 0, 0, 933);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "どうして失敗ばっかり\nこうなったら\n腹を切るしか～！", 1, 102502, 0, 0, 934);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "私、またなにか\nやっちゃいましたか？", 1, 102502, 0, 0, 935);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "おいしいお茶っ葉が\n手に入りました～♪\n一緒に飲みませんか？", 1, 102502, 0, 0, 936);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "転んだふりであの人に\n…って！\nなんでもないですよ！", 1, 102502, 0, 0, 937);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "私、できることなら\nなんでもやりますよ\nあなたのためですから", 1, 102502, 0, 0, 938);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます♪\n今日も一日がんば…\nう、うわあ！", 1, 102502, 0, 1, 939);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ごはん…\n失敗しちゃいましたぁ\nお、おやつでリベンジします！", 1, 102502, 0, 2, 940);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "明日の目標は\nドジをしないです！\nき、昨日の目標も\nドジをしないでした", 1, 102502, 0, 3, 941);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "あ、メイド服が\nほつれてる\n後でお裁縫しなくちゃ", 1, 102502, 0, 0, 942);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "いい座り心地です～\nこれならお嬢さまも\nゆったりできますね♪", 1, 102502, 0, 0, 943);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい♪\nあとでお洗濯\nしてあげますね", 1, 102502, 0, 0, 944);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り…\nお嬢様のお部屋にも\n置いてあげたいです", 1, 102502, 0, 0, 945);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "暖かいですけど\n…私が火に近づいて\n大丈夫でしょうか！？", 1, 102502, 0, 0, 946);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "運動しようとすると\nいつも怪我するん\nですよね…", 1, 102502, 0, 0, 947);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "こんなに美味しいもの\nメイドの私には\nもったいないです～！", 1, 102502, 0, 0, 948);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "物語のメイドさんって\n御主人さまを好きに\nなるんですよね…", 1, 102502, 0, 0, 949);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "あの方と私だけの\n部屋にしたいですわ", 1, 102701, 0, 0, 951);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "あの方は私のもの…\n眼も耳も鼻も口も髪も\n首も胸も腰も手も脚も\nぬくもりも心も…！", 1, 102701, 0, 0, 952);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "運命とは決して\n抗えないもの…\nクスクス…クスクス", 1, 102701, 0, 0, 953);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "部屋からあの方の\n香りが…\nああ、至福ですわ", 1, 102701, 0, 0, 954);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "毒にも薬にもならない\n存在なんて嫌ですわ\nどうせならとびきりの\n毒でありたい…", 1, 102701, 0, 0, 955);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "クスクス…\nあの方とデートする\nイメトレ中ですわ\nクスクスクスクス…", 1, 102701, 0, 0, 956);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "記憶を戻す研究より\n記憶をねつ造する研究\nのほうが良いかしら？\n伴侶という設定で…", 1, 102701, 0, 0, 957);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "運命を信じますか？\nもちろん絶対当然\n信じますわよね？", 1, 102701, 0, 0, 958);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "この薬は起床時就寝前\n食前食後食間に、毎日\n服用してください。\n惚れ薬ですわ", 1, 102701, 0, 0, 959);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お願いがあるのです。\n新しい研究の実験台に\n…", 1, 102701, 0, 0, 960);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "こっそり栽培している\n毒きのこが毒々しく\n育ちましたわ…", 1, 102701, 0, 0, 961);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あなた様の前では\n普通の女の子…\n少し毒薬づくりが\n得意なだけの…", 1, 102701, 0, 0, 962);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "私の身も心も、全てが\nあなた様のもの。\nあなた様の全ても…", 1, 102701, 0, 0, 963);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\n一晩中、あなた様の\n寝顔を見ていましたわ", 1, 102701, 0, 1, 964);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼を用意しましたの\n何も入れていませんわ\nクスクス…", 1, 102701, 0, 2, 965);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あなた様が眠るまで\nお傍で見守りますわ。\n…あの、どうして\n眠らないのですか？", 1, 102701, 0, 3, 966);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "いっそ鏡の中に\n閉じ込めてしまえたら\n私だけのものに…", 1, 102701, 0, 0, 967);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "はっ！\nリラックスしたら\n閃きましたわ！", 1, 102701, 0, 0, 968);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "あら、キメラの素体に\nぴったりですわ", 1, 102701, 0, 0, 969);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "このお部屋は\n良い香りがしますわ。\nはっ、あなた様の匂い\nなのでは…！？", 1, 102701, 0, 0, 970);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あたたかい…\n加熱調合にも\n使えそうですわね", 1, 102701, 0, 0, 971);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "この運動エネルギー\n何かにうまく\n利用できないかしら？", 1, 102701, 0, 0, 972);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "美味しい。あの方にも\n差し上げましょう…\n薬を入れて…", 1, 102701, 0, 0, 973);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "あの方を虜にする\n方法がどこかに\n載ってるはずですわ", 1, 102701, 0, 0, 974);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "あの方と私だけの\n部屋にしたいですわ", 1, 102702, 0, 0, 976);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "こっそり栽培している\n毒きのこが毒々しく\n育ちましたわ…", 1, 102702, 0, 0, 977);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "新しい薬\nどうやってあの方に\n飲ませようかしら", 1, 102702, 0, 0, 978);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "部屋からあの方の\n香りが…\nああ、至福ですわ", 1, 102702, 0, 0, 979);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "記憶を戻す研究より\n記憶をねつ造する研究\nのほうが良いかしら？\n伴侶という設定で…", 1, 102702, 0, 0, 980);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "クスクス…\nあの方とデートする\nイメトレ中ですわ\nクスクスクスクス…", 1, 102702, 0, 0, 981);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "魔法も科学も錬金術も\n全て駆使して\nあの方のために…", 1, 102702, 0, 0, 982);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "この部屋には雌犬…\n失礼、女の方がとても\n沢山いますのね", 1, 102702, 0, 0, 983);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あなた様には私の伴侶\nとして高い教養を…\nあ、逃げられてしまい\nましたわ…！", 1, 102702, 0, 0, 984);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お願いがあるのです\n新しい研究の\n実験台に…", 1, 102702, 0, 0, 985);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あなた様が寝ている時\n私は…クスクス\nこれ以上は言えません", 1, 102702, 0, 0, 986);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "想像の中のあなた様は\nすっかり私の虜なのに\n現実は…\nもどかしいですわね", 1, 102702, 0, 0, 987);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あなた様の前では\n普通の女の子…\n少し毒薬づくりが\n得意なだけの…", 1, 102702, 0, 0, 988);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\n一晩中、あなた様の\n寝顔を見ていましたわ", 1, 102702, 0, 1, 989);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "さあ、お食事ですよ\n味は保証しますわ\n特製ソースで少しだけ\n体が痺れますけど…", 1, 102702, 0, 2, 990);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あなた様が眠るまで\nお傍で見守りますわ\n…あの、どうして\n眠らないのですか？", 1, 102702, 0, 3, 991);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "私ももう少し\n外見に気を配る\nべきでしょうか…", 1, 102702, 0, 0, 992);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "はっ！\nリラックスしたら\n閃きましたわ！", 1, 102702, 0, 0, 993);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "この私を差し置いて\nあなた様に媚びるなど\n言語道断…っ！", 1, 102702, 0, 0, 994);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "このお部屋は\n良い香りがしますわ\nはっ、あなた様の匂い\nなのでは…！？", 1, 102702, 0, 0, 995);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "素敵なぬくもり…\nまるであの方に\n抱きしめられたような", 1, 102702, 0, 0, 996);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "この運動エネルギー\n何かにうまく\n利用できないかしら？", 1, 102702, 0, 0, 997);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "美味しい。あの方にも\n差し上げましょう…\n薬を入れて…", 1, 102702, 0, 0, 998);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "あの方を虜にする\n方法がどこかに\n載ってるはずですわ", 1, 102702, 0, 0, 999);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "子供たちの遊びって\nあたしが子供の頃と\nあまり変わらないのね", 1, 102801, 0, 0, 1001);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "使えるものは\n再利用しないと\n…あ、これとか\nまだ使えるわね", 1, 102801, 0, 0, 1002);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "贅沢は敵！　とはいえ\n気持ちに余裕のない\n暮らしはダメよね", 1, 102801, 0, 0, 1003);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お腹空いたわね、\n残り物で\n何か作ろうかしら", 1, 102801, 0, 0, 1004);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "商売はノンゼロサムが\n理想だなぁ。誰も損を\nしないってことだもの", 1, 102801, 0, 0, 1005);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あんたが手伝って\nくれるから、仕事も\n前より楽しいのよね♪", 1, 102801, 0, 0, 1006);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "焼きそばパンが\n食べたいな～\nあいつと…", 1, 102801, 0, 0, 1007);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ねぇあんた、どこか\n安いお店知らない？", 1, 102801, 0, 0, 1008);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あたし、エレガントに\n振る舞えてる？\n…そう？　嬉しい♪", 1, 102801, 0, 0, 1009);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "いっぱい働いて遊んで\nよく休んでまた働く。\nそれが健全な生活よね", 1, 102801, 0, 0, 1010);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "一緒に部屋の\n整頓でもする？\nハマると楽しいわよ♪", 1, 102801, 0, 0, 1011);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あんたがいると\n子供たちも喜ぶわ♪\nもちろんあたしもね！", 1, 102801, 0, 0, 1012);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ね、あんた今、幸せ？\n何びっくりしてるのよ\n大事なことじゃないの", 1, 102801, 0, 0, 1013);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "面倒な用事は午前中に\n片づけてしまうのが、\n時間の使い方のコツよ", 1, 102801, 0, 1, 1014);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "午後のティータイム\nとかどう？\n良いカフェがあるの♪", 1, 102801, 0, 2, 1015);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "さ、エレガントな夜を\n楽しみましょ。\nモダンな音楽でも\nかけましょうか？", 1, 102801, 0, 3, 1016);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "レディたるもの\n身嗜みはしっかりとね\n見本にならないと♪", 1, 102801, 0, 0, 1017);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "これで仕事は一段落ね\nちょっと休憩…", 1, 102801, 0, 0, 1018);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "うふふ、\nかわいいものを\n見るのは幸せね～", 1, 102801, 0, 0, 1019);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "部屋中がいい香り…\nなんだかすごい贅沢\nしてる気分♪", 1, 102801, 0, 0, 1020);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "風邪を引かないように\n身体を温めなくちゃ", 1, 102801, 0, 0, 1021);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "さっ！　家の中でも\n効率的に\nトレーニングよ！", 1, 102801, 0, 0, 1022);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…はっ、\n口の周り、\n汚れてないわよね？", 1, 102801, 0, 0, 1023);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "知識から過去を学んで\n未来に活かすわよ", 1, 102801, 0, 0, 1024);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "安売りのお店の情報\n整理しないと…", 1, 102802, 0, 0, 1026);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "どんなに苦労してても\nそう見せないのが真の\nエレガントなレディよ", 1, 102802, 0, 0, 1027);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "安く済んであいつが\n喜ぶ料理とか…\nないかしら", 1, 102802, 0, 0, 1028);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "子供たちの遊びって\nあたしが子供の頃と\nあまり変わらないのね", 1, 102802, 0, 0, 1029);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "商売はノンゼロサムが\n理想だなぁ。誰も損を\nしないってことだもの", 1, 102802, 0, 0, 1030);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "焼きそばパンが\n食べたいな～\nあいつと…", 1, 102802, 0, 0, 1031);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あいつと一緒に…\n色々なところに\nいきたいな", 1, 102802, 0, 0, 1032);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今度買い物に\n付き合いなさい\nセールがあるのよ", 1, 102802, 0, 0, 1033);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あんたがいると子供\nたちも喜ぶわ♪\nもちろんあたしもね♪", 1, 102802, 0, 0, 1034);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "いっぱい働いて遊んで\nよく休んでまた働く\nそれが健全な生活よね", 1, 102802, 0, 0, 1035);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あんたとこうして\nのんびりするのも\nいいものね", 1, 102802, 0, 0, 1036);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "ねえ、今度遊びに\n行きたいな\nもちろん一緒に、よ", 1, 102802, 0, 0, 1037);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あんたが手伝って\nくれるから、仕事も\n前より楽しいのよね♪", 1, 102802, 0, 0, 1038);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "面倒な用事は午前中に\n片づけてしまうのが\n時間の使い方のコツよ", 1, 102802, 0, 1, 1039);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ランチにして午後の\n仕事に備えましょ！\nやることは一杯よ♪", 1, 102802, 0, 2, 1040);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふわあ～\nもうこんな時間\n子供たちは\nもう寝たかしら", 1, 102802, 0, 3, 1041);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "忙しい時こそ\n身だしなみは隙なく\nぴしっとね！", 1, 102802, 0, 0, 1042);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "これで仕事は一段落ね\nちょっと休憩…", 1, 102802, 0, 0, 1043);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふふふ\nずっと眺めてたく\nなっちゃうわね", 1, 102802, 0, 0, 1044);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "部屋中がいい香り…\nなんだかすごい贅沢\nしてる気分♪", 1, 102802, 0, 0, 1045);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "風邪を引かないように\n身体を温めなくちゃ", 1, 102802, 0, 0, 1046);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "さっ！　家の中でも\n効率的に\nトレーニングよ！", 1, 102802, 0, 0, 1047);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "しっかり食べて\n栄養補給、栄養補給！", 1, 102802, 0, 0, 1048);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "知識から過去を学んで\n未来に活かすわよ", 1, 102802, 0, 0, 1049);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "可愛い子が\nいっぱいいるなぁ…\n誰か私とユニット\n組んでくれないかな？", 1, 102901, 0, 0, 1051);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "今度のライブ会場、\nいつもより大きいから\n楽しみなんだ～！", 1, 102901, 0, 0, 1052);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "新曲の衣装、もうすぐ\n出来あがるんだって！\n楽しみだな～", 1, 102901, 0, 0, 1053);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "彼とデュエット\nしてみたいな～♪", 1, 102901, 0, 0, 1054);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "キラキラ無病息災、\nドキドキ一日一善…\n作詞って難しい～", 1, 102901, 0, 0, 1055);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ファンはもちろん\n大事だけど…\n彼のことは、もっと\n大切にしたいな…", 1, 102901, 0, 0, 1056);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "写真集見なくても、\n本物がここに\nいるのにな～", 1, 102901, 0, 0, 1057);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "握手会の練習、\n付き合ってくれない？", 1, 102901, 0, 0, 1058);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "写真集のポーズ\n練習中～！\nど、どうかな？", 1, 102901, 0, 0, 1059);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "何て書いてあるか\n読めないって？\nもー！\nこれは私のサイン！", 1, 102901, 0, 0, 1060);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ね、次のライブ\n観に来てくれる？\nいい席とっとくから！", 1, 102901, 0, 0, 1061);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ねぇ、台本読むの\nつきあってくれる？\n恋人役に\nなってほしいんだ", 1, 102901, 0, 0, 1062);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "新曲、聞いてくれた？\nキミとのことを\nテーマにしたんだよ。\nどこかは秘密だけど♪", 1, 102901, 0, 0, 1063);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝の発声練習に\n行くけど、キミも\n一緒に来ない？", 1, 102901, 0, 1, 1064);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "この時間は\nお腹すくけど…\n水着撮影があるから\nお昼抜いてるんだ", 1, 102901, 0, 2, 1065);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜の帳が二人を包み\n…こういう方向性の\n歌詞も悪くないなぁ。", 1, 102901, 0, 3, 1066);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "身だしなみオッケー！\nアイドルはいつでも\n完璧でいなくちゃ！", 1, 102901, 0, 0, 1067);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふぅ…\nこんな姿、ファンには\n見せられないな～", 1, 102901, 0, 0, 1068);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい～♪\nこれは強力な\nライバル登場かな！", 1, 102901, 0, 0, 1069);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ステキな香り～♪\n歌詞のイメージが\n浮かんできそう！", 1, 102901, 0, 0, 1070);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "体も暖まったし！\nダンスレッスンに\n行こうかな♪", 1, 102901, 0, 0, 1071);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "ベストタイム更新！\nライブに向けて\n体力つけないと…", 1, 102901, 0, 0, 1072);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "太っちゃったら\nどうしよう…？\nでも手が止まらない～", 1, 102901, 0, 0, 1073);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ステキなお話…\n新曲の作詞の\n参考になりそう♪", 1, 102901, 0, 0, 1074);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "このお部屋すてき！\nファンに追われた時の\n隠れ家にピッタリね！", 1, 102902, 0, 0, 1076);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "そろそろイメチェン\nしてみようかな…\nそれともこの路線で\nもう少し…？", 1, 102902, 0, 0, 1077);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "みんながくれた\nファンレター…\n私の大事な宝物…", 1, 102902, 0, 0, 1078);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "彼とデュエット\nしてみたいな～♪", 1, 102902, 0, 0, 1079);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "疾風怒濤、威風堂々\n獅子奮迅、唯我独尊…\nラブソングの作詞って\n難しいな～", 1, 102902, 0, 0, 1080);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "ファンはもちろん\n大事だけど…\n彼のことは、もっと\n大切にしたいな…", 1, 102902, 0, 0, 1081);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "トップアイドルの\nさらに先…\n彼とならその景色も\n見られるかな", 1, 102902, 0, 0, 1082);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "新曲の衣装、もうすぐ\n出来あがるんだって！\n楽しみだな～", 1, 102902, 0, 0, 1083);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "アイドルノゾミだけ\nじゃなくて、私の事も\nちゃんと見てね？", 1, 102902, 0, 0, 1084);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "キミに響かないなら\nファンにも響くわけ\nないよ！　練習練習！", 1, 102902, 0, 0, 1085);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "衣装のスカートは\n鉄壁なんだよ！\n残念でした～", 1, 102902, 0, 0, 1086);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "新曲、聞いてくれた？\nキミとのことを\nテーマにしたんだよ\nどこかは秘密だけど♪", 1, 102902, 0, 0, 1087);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ねぇ、私がトップ\nアイドルになっても\nちゃんと隣にいてね\n遠くに行かないでね？", 1, 102902, 0, 0, 1088);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝の発声練習に\n行くけど、キミも\n一緒に来ない？", 1, 102902, 0, 1, 1089);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ごはん行かない？\n誰にも知られてない\nお店があるんだけど！", 1, 102902, 0, 2, 1090);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜の帳が二人を包み\n…こういう方向性の\n歌詞も悪くないなぁ", 1, 102902, 0, 3, 1091);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "身だしなみオッケー！\nアイドルはいつでも\n完璧でいなくちゃ！", 1, 102902, 0, 0, 1092);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふぅ…\nこんな姿、ファンには\n見せられないな～", 1, 102902, 0, 0, 1093);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい～♪\nこれは強力な\nライバル登場かな！", 1, 102902, 0, 0, 1094);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "みんなのイメージする\nアイドルの香りは\nこんな感じかな～", 1, 102902, 0, 0, 1095);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "体も暖まったし！\nダンスレッスンに\n行こうかな♪", 1, 102902, 0, 0, 1096);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "ベストタイム更新！\nライブに向けて\n体力つけないと…", 1, 102902, 0, 0, 1097);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "太っちゃったら\nどうしよう…？\nでも手が止まらない～", 1, 102902, 0, 0, 1098);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "この恋愛小説ステキ！\n私もアイドルじゃ\nなかったら…", 1, 102902, 0, 0, 1099);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "手裏剣の数が\n合わないデス！\nどこかに落とした\nデスか…？", 1, 103001, 0, 0, 1101);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "クセモノ、隠れても\nむだデス！\n…気のせいデシタ", 1, 103001, 0, 0, 1102);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "金は天下の\nマワリモノ！\nところで、\nどういう意味デス？", 1, 103001, 0, 0, 1103);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "むむ、アクダイカンの\n気配がするデース", 1, 103001, 0, 0, 1104);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "クニトリ合戦、\n楽しみデース！", 1, 103001, 0, 0, 1105);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ショーグンと\n出会えて、\nワタシは果報者デス！", 1, 103001, 0, 0, 1106);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "最近、ショーグンの\nそばにいると\nドキドキするデス…", 1, 103001, 0, 0, 1107);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "なんでも\n命令するデス！\nショーグンの命は\n絶対デス！", 1, 103001, 0, 0, 1108);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あっ、ショーグン、\n出陣はいつで\nゴザルデス！？", 1, 103001, 0, 0, 1109);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "さ、さすが\nショーグンデス…\nいつの間に背後を！？", 1, 103001, 0, 0, 1110);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "出陣の合図に\n備えるデス！\nほら貝は\nどこデスか！？", 1, 103001, 0, 0, 1111);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "見つめられると\nドキドキするデス…\n新しい忍法デスか？", 1, 103001, 0, 0, 1112);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ショーグン！\nえへへ…これからも\nおそばに置いて\nクダサイね？", 1, 103001, 0, 0, 1113);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようデス！\n今日も一日\n忍法日和デス！", 1, 103001, 0, 1, 1114);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "そろそろお腹\n空いてきたデス。\n昼ごはんにするデス！", 1, 103001, 0, 2, 1115);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "明日もきっと\nいい日デスよ、\nショーグン！", 1, 103001, 0, 3, 1116);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "ちょんまげに\nしてみるのも\n面白いかもデス！", 1, 103001, 0, 0, 1117);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "心地よくて\n眠くなってきマス…\nもしやテキコクの\n罠デスか！？", 1, 103001, 0, 0, 1118);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "これを変わり身の\n術に…かわいそう\nだから止めるデス", 1, 103001, 0, 0, 1119);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ワビサビというもの\nデスね！\n素晴らしいデス！", 1, 103001, 0, 0, 1120);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "身体を暖めて\nイクサに向かうデス！", 1, 103001, 0, 0, 1121);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "アクロバットな忍法を\n使うには、体を\n鍛えないと危険デス！", 1, 103001, 0, 0, 1122);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "うーん、\n美味しいデス…\n幸せデス～", 1, 103001, 0, 0, 1123);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "これは…\nＢＵＳＨＩＤＯ…\nデスか？", 1, 103001, 0, 0, 1124);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ふんふんふ～ん\n武器の手入れは\n念入りにしマスよ～", 1, 103002, 0, 0, 1126);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "クセモノ、隠れても\nむだデス！\n…気のせいデシタ", 1, 103002, 0, 0, 1127);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "金は天下の\nマワリモノ！\nところで\nどういう意味デス？", 1, 103002, 0, 0, 1128);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "むむ、アクダイカンの\n気配がするデース", 1, 103002, 0, 0, 1129);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "クニトリ合戦\n楽しみデース！", 1, 103002, 0, 0, 1130);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "最近、ショーグンの\nそばにいると\nドキドキするデス…", 1, 103002, 0, 0, 1131);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ショーグンの身は\n何があってもワタシが\n守るデス！", 1, 103002, 0, 0, 1132);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あっ、ショーグン\n出陣はいつで\nゴザルデス！？", 1, 103002, 0, 0, 1133);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "イクサの前に\nホネ休めも大事デスよ\nゆっくりするデース！", 1, 103002, 0, 0, 1134);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "さ、さすがショーグン\nデス…いつの間に\n背後を！？", 1, 103002, 0, 0, 1135);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "一緒に忍法考える\nデス！\nショーグン用の\n忍法も必要デスね！", 1, 103002, 0, 0, 1136);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "見つめられると\nドキドキするデス…\n新しい忍法デスか？", 1, 103002, 0, 0, 1137);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ショーグン！\nえへへ…これからも\nおそばに置いて\nクダサイね？", 1, 103002, 0, 0, 1138);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "いい朝デス！\nトーゴク風の朝ゴハン\n作るデス！", 1, 103002, 0, 1, 1139);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "もうお昼デス\nお昼寝するデスか？", 1, 103002, 0, 2, 1140);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろおネム\nデース…\n一緒に寝るデス？", 1, 103002, 0, 3, 1141);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "服の乱れは心の乱れ\nデス！　きっちり\nしないといけないデス", 1, 103002, 0, 0, 1142);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "心地よくて眠く\nなってきマス…\nもしやテキコクの\n罠デスか！？", 1, 103002, 0, 0, 1143);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "これを変わり身の\n術に…かわいそう\nだから止めるデス", 1, 103002, 0, 0, 1144);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ワビサビというもの\nデスね！\n素晴らしいデス！", 1, 103002, 0, 0, 1145);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "身体を暖めてイクサに\n向かうデス！", 1, 103002, 0, 0, 1146);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "ショーグンのお役に\n立つため、修行\nあるのみデス！", 1, 103002, 0, 0, 1147);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "美味しいデス…\n酢昆布を和えて\nみたいデス", 1, 103002, 0, 0, 1148);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "物事を知って\n来たるべきイクサに\n活かすデス", 1, 103002, 0, 0, 1149);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "お父さん、そろそろ\n子離れを…しない？\nそうですか…", 1, 103101, 0, 0, 1151);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "父は、いつも男性に\nきびしいですね", 1, 103101, 0, 0, 1152);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "占ってほしい人は、\nいつでも言って\nください", 1, 103101, 0, 0, 1153);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "あなたの手相は…\nて、手を握るのって\n緊張しますね", 1, 103101, 0, 0, 1154);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "この部屋、風水的にも\n運気が上がりそうです", 1, 103101, 0, 0, 1155);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あの人とのこと占って\nみようかな…\n好き…嫌い…\n好き♪…き、嫌い", 1, 103101, 0, 0, 1156);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "私との相性ですか？\nそれなら占う必要は\nありませんよ…\nふふっ♪", 1, 103101, 0, 0, 1157);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "女難の相が\n出ていますね…\n気をつけてください", 1, 103101, 0, 0, 1158);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今日のあなたの運勢は\n大きょ…\n大吉です", 1, 103101, 0, 0, 1159);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "父と散歩中です。\n毎日決まったコースを\n散歩させないと、\nストレスが溜まるので", 1, 103101, 0, 0, 1160);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "小僧！\nシノブに触るとは\nいい度胸じゃねぇか！", 1, 103101, 0, 0, 1161);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あなたに触られると、\n動悸が早くなります\nもしかして心霊現象？", 1, 103101, 0, 0, 1162);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "今日もたくさんの幽霊\nに慕われていますね。\n素敵です", 1, 103101, 0, 0, 1163);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\n今日の運勢を\n占いましょうか？", 1, 103101, 0, 1, 1164);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今日のラッキー\nアイテムはドクロです\n良ければ父を\nお貸ししましょうか？", 1, 103101, 0, 2, 1165);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日のあなたの運気は\n最高潮でした。\nもうすぐ今日は\n終わりますが", 1, 103101, 0, 3, 1166);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "お父さん。\nいつも、身だしなみに\n気を使ってるけど、\nあまり変わってないよ", 1, 103101, 0, 0, 1167);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "一休みしましょう。\n憑かれて疲れました", 1, 103101, 0, 0, 1168);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい…\n付喪神が宿らないかな", 1, 103101, 0, 0, 1169);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "お父さん、\nリラックスし過ぎると\n成仏しちゃうよ？", 1, 103101, 0, 0, 1170);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "気持ちいいです…\n極楽浄土みたい…", 1, 103101, 0, 0, 1171);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "はぁはぁ…\nお、お父さん、\n代わりに運動して…", 1, 103101, 0, 0, 1172);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "お父さんも\n食べたいの？\n死んでるのに？", 1, 103101, 0, 0, 1173);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "この本…\nもしかして予言書？", 1, 103101, 0, 0, 1174);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ここにいる幽霊は\nみんな幸せそうです", 1, 103102, 0, 0, 1176);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "お父さんが\n女の子ばかりに\n声をかけるので\n困っています", 1, 103102, 0, 0, 1177);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "成仏はうれしいこと\nです…でも友達が\n減るのは寂しいですね", 1, 103102, 0, 0, 1178);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "幽霊に好かれる人は\n素敵な方です\nもちろん、あなたも", 1, 103102, 0, 0, 1179);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "お父さん、そろそろ\n子離れを…しない？\nそうですか…", 1, 103102, 0, 0, 1180);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "生きている人に\n好かれるには、\nどうすればいい\nのでしょう？", 1, 103102, 0, 0, 1181);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "お父さん、どうしたら\nあの人のことを\n認めてくれますか？", 1, 103102, 0, 0, 1182);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "この部屋、風水的にも\n運気が上がりそうです", 1, 103102, 0, 0, 1183);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "シノブには指一本\n触れさせん！\nガブッ！！", 1, 103102, 0, 0, 1184);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あなたの手相は…\nて、手を握るのって\n緊張しますね", 1, 103102, 0, 0, 1185);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ラップ音？\nいえ、父のいびきです", 1, 103102, 0, 0, 1186);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "私との相性ですか？\nそれなら占う必要は\nありませんよ…\nふふっ♪", 1, 103102, 0, 0, 1187);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "前世って信じますか？\n私とあなたは\nもしかすると…", 1, 103102, 0, 0, 1188);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日のラッキー\nアイテムはドクロです\n良ければ父を\nお貸ししましょうか？", 1, 103102, 0, 1, 1189);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "明るい時間は\nあまり得意では\nないんです…", 1, 103102, 0, 2, 1190);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜のお散歩に\n行きませんか？\n知り合いの幽霊に\n挨拶して回るんです", 1, 103102, 0, 3, 1191);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "お父さん\nいつも、身だしなみに\n気を使ってるけど\nあまり変わってないよ", 1, 103102, 0, 0, 1192);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "うとうと…\nあれ…\n走馬灯が見える…", 1, 103102, 0, 0, 1193);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい…\nお父さんみたい…", 1, 103102, 0, 0, 1194);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "お父さん\nリラックスし過ぎると\n成仏しちゃうよ？", 1, 103102, 0, 0, 1195);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "快適です…\n幽霊もどんどん\n集まってきますね…", 1, 103102, 0, 0, 1196);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "はぁはぁ…\nお、お父さん、\n代わりに運動して…", 1, 103102, 0, 0, 1197);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "お父さんの分も、\n私が食べるね", 1, 103102, 0, 0, 1198);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "この本の占い\n私の占いと違う…", 1, 103102, 0, 0, 1199);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "私だって、一人で\n買い物ぐらい\nできますわ…きっと", 1, 103201, 0, 0, 1201);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "そろそろ新しい\n案件を始めないと\nいけませんわね", 1, 103201, 0, 0, 1202);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "一日も早く、\n一人前の商人に\nなりたいものです", 1, 103201, 0, 0, 1203);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "平和を買うのには\nどれほどのお金が\n必要なのかしら？", 1, 103201, 0, 0, 1204);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ここももう少し広いと\n落ち着くのですけど。\n改築しませんこと？", 1, 103201, 0, 0, 1205);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あの方はお金で雇った\nわけではないのに\n私といてくださる…", 1, 103201, 0, 0, 1206);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "たとえ私が間違っても\nきっとあの方が\n正してくれますわ…", 1, 103201, 0, 0, 1207);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "私と、庶民向けの\nお店へ一緒に\n参りませんか？", 1, 103201, 0, 0, 1208);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "資産運用？\nお幾らほど\n増やしたいのです？", 1, 103201, 0, 0, 1209);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "どんぶり勘定だとよく\n言われるのですが…\n例えが小さすぎます！", 1, 103201, 0, 0, 1210);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お金で解決するのは\n悪いことでは\nありませんわよね？", 1, 103201, 0, 0, 1211);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "その、よろしければ\n私とお散歩など\nいかがです？", 1, 103201, 0, 0, 1212);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "もしあなたさまが\n道に迷われるなら、\n私もお供いたします！", 1, 103201, 0, 0, 1213);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "早起きは三ルピの徳と\n申しますが…\nもっとお得ですわね", 1, 103201, 0, 1, 1214);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼食は町の屋台で\n立ったまま食べて\nみたいですわ！", 1, 103201, 0, 2, 1215);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "よろしければ\nお休み前のミルクを\n御一緒にいかが？", 1, 103201, 0, 3, 1216);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "だらしない身なりでは\n取引相手に信用して\nいただけませんものね", 1, 103201, 0, 0, 1217);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "この感触と安らぎ…\n素晴らしい\n費用対効果ですわ…", 1, 103201, 0, 0, 1218);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "何の見返りも求めず\nただひたすら愛でて\nいたいのです！", 1, 103201, 0, 0, 1219);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "目に見えないものに\nお金をかけるのが\n真の贅沢ですわ！", 1, 103201, 0, 0, 1220);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "誰ひとり寒い思いを\nしない町にするために\n私にできる事は…", 1, 103201, 0, 0, 1221);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "健康はお金では\n買えませんが\n運動器具は別ですわ！", 1, 103201, 0, 0, 1222);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "なかなか\n美味ですわ\nシェフはどちらに？", 1, 103201, 0, 0, 1223);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "経済の仕組みを\nしっかりと\n学ばなくては…", 1, 103201, 0, 0, 1224);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "そろそろ新しい\n案件を始めないと\nいけませんわね", 1, 103202, 0, 0, 1226);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ええと、これは\nおいくらで買ったん\nでしたっけ？", 1, 103202, 0, 0, 1227);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "お金を見せたら\n態度が変わる人は\n信用できませんわ", 1, 103202, 0, 0, 1228);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "地図が読めずとも\n道に迷わない方って\nいらっしゃるのですね", 1, 103202, 0, 0, 1229);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "この狭さも\n慣れれば\n快適ですわ♪", 1, 103202, 0, 0, 1230);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "あの方はお金で雇った\nわけではないのに\n私といてくださる…", 1, 103202, 0, 0, 1231);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "たとえ私が間違っても\nきっとあの方が\n正してくれますわ…", 1, 103202, 0, 0, 1232);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "一人前の商人に\n相応しい居振る舞いを\nしたいものですわ", 1, 103202, 0, 0, 1233);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "幼い頃\nお店屋さんごっこを\nなさいましたか？", 1, 103202, 0, 0, 1234);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "資産運用？\nお幾らほど\n増やしたいのです？", 1, 103202, 0, 0, 1235);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "今度一緒に…\nパーティにでも\n行きませんこと？", 1, 103202, 0, 0, 1236);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "その、よろしければ\n私とお散歩など\nいかがです？", 1, 103202, 0, 0, 1237);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あなたさまの優しさは\nお金には\n代えられませんわね", 1, 103202, 0, 0, 1238);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "なぜだか\n眠り足りないような\n感じがしますわ…", 1, 103202, 0, 1, 1239);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼食は町の屋台で\n立ったまま食べて\nみたいですわ！", 1, 103202, 0, 2, 1240);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "よろしければ\nお休み前のミルクを\n御一緒にいかが？", 1, 103202, 0, 3, 1241);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "ドレスは汚れていない\nようですが…やだ\n髪がほつれてますわ！", 1, 103202, 0, 0, 1242);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "こういったものに\n腰を沈めると…\nき、気が緩んで…", 1, 103202, 0, 0, 1243);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "何の見返りも求めず\nただひたすら愛でて\nいたいのです！", 1, 103202, 0, 0, 1244);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "香りは質のいいものと\nそうでないものが\nはっきり分かりますわ", 1, 103202, 0, 0, 1245);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "誰ひとり寒い思いを\nしない町にするために\n私にできる事は…", 1, 103202, 0, 0, 1246);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "目標は遠くに\n置いた方が励みに\nなりますわ！", 1, 103202, 0, 0, 1247);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "なかなか\n美味ですわ\nシェフはどちらに？", 1, 103202, 0, 0, 1248);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "商人って、物語では\n悪役にされやすいの\nですね…", 1, 103202, 0, 0, 1249);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "家の中のものを使って\n物ボケ、考えるべ！", 1, 103301, 0, 0, 1251);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "毎日の日課…それは\n炊事、洗濯、大喜利\nだべ！", 1, 103301, 0, 0, 1252);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "うちに塀ができたら、\nへー、って言いたい！", 1, 103301, 0, 0, 1253);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "オラが作る料理は\nこの後スタッフで\n美味しくいただくべよ", 1, 103301, 0, 0, 1254);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "エリザベスも\n連れてきてぇ～", 1, 103301, 0, 0, 1255);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あんちゃんも、\nエリザベスと同じ位\nめんこいべ♪", 1, 103301, 0, 0, 1256);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "オラとあんちゃん、\n息がぴったりに\nなってきたべ…！", 1, 103301, 0, 0, 1257);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おぉ！　そんな急に\nツッコまれたら、\nびっくらこくべやー！", 1, 103301, 0, 0, 1258);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ネタはオラが書くけど\nあんちゃんが\n書きたかったら\n書いてもいいんだぞ？", 1, 103301, 0, 0, 1259);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あんちゃん、オラには\n容赦なんかせずに\nツッコんでくれて\nいいから！", 1, 103301, 0, 0, 1260);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "押すなよ、\n絶対押すなよ\n…なんて\n言ってないべさ？", 1, 103301, 0, 0, 1261);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "うう…あんちゃんに\nツッコまれたくて\nうずうずしてきたべ～", 1, 103301, 0, 0, 1262);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "将来的には夫婦漫才\nってのも…あ、ひ、\nひとりごとだべさ～！", 1, 103301, 0, 0, 1263);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう！　一緒に\n牛の乳しぼりいくべ？", 1, 103301, 0, 1, 1264);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼だ～腹が減っては\n笑いはできぬ～！", 1, 103301, 0, 2, 1265);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日もよく働いたべ！\nさ、今からは\nお笑いの練習だ～！", 1, 103301, 0, 3, 1266);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "舞台に上がる前に\n身なりは整えねぇと\nだめだべ～！", 1, 103301, 0, 0, 1267);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ナイスなイスに\n座りたい、\nなんちゃって！", 1, 103301, 0, 0, 1268);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "めんこいのは、\nスベっても許される\nからずるいべな～？", 1, 103301, 0, 0, 1269);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "必要以上に\n癒されちまうべや～", 1, 103301, 0, 0, 1270);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ぽかぽかだ…\nウケた会場みてぇだ", 1, 103301, 0, 0, 1271);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "お笑い芸人は、\n体が資本だべさ～！", 1, 103301, 0, 0, 1272);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…\nボケることも\n忘れちまう美味さだ～", 1, 103301, 0, 0, 1273);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ネタ作りのヒントが\n載ってねぇか探すべ", 1, 103301, 0, 0, 1274);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "さぁ今日も張り切って\n漫才の練習するべさ！", 1, 103302, 0, 0, 1276);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "この部屋でも、商品\n売っていいんだべか？", 1, 103302, 0, 0, 1277);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "眼鏡を頭の上に乗せて\n「メガネメガネ～」\nって言う練習した方が\nいいべか？", 1, 103302, 0, 0, 1278);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "漫才を持ち時間に\n収めるには、何度も\n練習するしかねぇべ", 1, 103302, 0, 0, 1279);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "エリザベスも\n連れてきてぇ～", 1, 103302, 0, 0, 1280);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "うう…あんちゃんに\nツッコまれたくて\nうずうずしてきたべ～", 1, 103302, 0, 0, 1281);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あんちゃんに\n採れたての食材を\n食わしてやりてぇ～", 1, 103302, 0, 0, 1282);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "押すなよ\n絶対押すなよ\n…なんて\n言ってないべさ？", 1, 103302, 0, 0, 1283);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あんちゃん、百連\nツッコミ特訓だ～！", 1, 103302, 0, 0, 1284);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あんちゃん、オラには\n容赦なんかせずに\nツッコんでくれて\nいいから！", 1, 103302, 0, 0, 1285);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "「なんでだべ～！」\nって言いながら\nツッコむといいべ！", 1, 103302, 0, 0, 1286);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "あはは～あんちゃんの\nツッコミはやっぱり\n気持ちいいなぁ～", 1, 103302, 0, 0, 1287);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "将来的には夫婦漫才\nってのも…あ、ひ\nひとりごとだべさ～！", 1, 103302, 0, 0, 1288);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう！\n今日もいい\nネタ作り日和だ！", 1, 103302, 0, 1, 1289);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼だな\nご飯を食べたら、\nネタの練習するべ！", 1, 103302, 0, 2, 1290);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もうこんな時間だべ\nネタ作りは\n明日にするべ…", 1, 103302, 0, 3, 1291);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "うーん…衣装、\nずれてねぇべか？", 1, 103302, 0, 0, 1292);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ナイスなイスに\n座りたい\nなんちゃって！", 1, 103302, 0, 0, 1293);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "はう～\nなまらめんこいべや～", 1, 103302, 0, 0, 1294);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "必要以上に\n癒されちまうべや～", 1, 103302, 0, 0, 1295);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "笑いをとることを\n忘れるほど\nあったけぇべ～", 1, 103302, 0, 0, 1296);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "たくさん運動して\n動きでも笑いがとれる\nように頑張るべ～！", 1, 103302, 0, 0, 1297);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…\nボケることも\n忘れちまう美味さだ～", 1, 103302, 0, 0, 1298);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "幅広く教養を\n身につけて\nいいネタ作るべ！", 1, 103302, 0, 0, 1299);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "通りにいる\nカップル…爆発\nすればいいのに…", 1, 103401, 0, 0, 1301);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "う～ん、仕事なんて\nしないで、\n飲んでたいな～", 1, 103401, 0, 0, 1302);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "今日は一日、\n外に出ない！\nもう決めたわ！", 1, 103401, 0, 0, 1303);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お腹空いた…\nけど、外に出るのは\n面倒だなぁ", 1, 103401, 0, 0, 1304);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "うぅ…頭がガンガン\nする…昨日、\n飲み過ぎたかな…", 1, 103401, 0, 0, 1305);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "デートとか…\n誘っても嫌がられ\nないかな…？", 1, 103401, 0, 0, 1306);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "もしかして運命の\n相手だったり…\nするのかな", 1, 103401, 0, 0, 1307);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "やっぱり一杯目が\n一番おいしいわ～！\n…え、見てた！？", 1, 103401, 0, 0, 1308);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "頼れるお姉さんだって\nところ、もっと見せて\nあげるからね", 1, 103401, 0, 0, 1309);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ねえ、一緒に買い物に\n行かない？　その…\nの、飲み物とか…", 1, 103401, 0, 0, 1310);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ひっく、うふふ…\nもっとお姉さんと\nお話しようよ～", 1, 103401, 0, 0, 1311);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "極力人付き合いは\nしない主義なんだけど\nキミは例外かも…", 1, 103401, 0, 0, 1312);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "いつか…\nキミと一緒に飲めたら\n楽しいだろうな", 1, 103401, 0, 0, 1313);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう…朝は\nちょっとつらいな…\n低血圧なのよ…", 1, 103401, 0, 1, 1314);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おっひるー♪\nなに食べよっかな～♪", 1, 103401, 0, 2, 1315);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふわあ…\n眠る前にちょっと\n一杯…冗談よ", 1, 103401, 0, 3, 1316);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "うう…\n髪がボサボサ…\nちゃんとしなきゃ…", 1, 103401, 0, 0, 1317);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "自然体でゴロゴロ\nするのって\n幸せだなぁ…", 1, 103401, 0, 0, 1318);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "こういうの男の子に\nプレゼントして\nもらいたいな…", 1, 103401, 0, 0, 1319);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "うわあ、\nこれ、私の好きな\n香りだー！", 1, 103401, 0, 0, 1320);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ぽっかぽか…\nあとは熱い一杯が\nあれば…！", 1, 103401, 0, 0, 1321);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "家でゴロゴロして\n付いちゃったお肉を\n落とさないと…！", 1, 103401, 0, 0, 1322);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…\nおーいしー！\n…太らないよね？", 1, 103401, 0, 0, 1323);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "大人の女らしく\n色んなことを学んで\nおかなくっちゃ", 1, 103401, 0, 0, 1324);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "仕事終わりの一杯の\nために、今日も\n頑張らないと", 1, 103402, 0, 0, 1326);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "今日は\nのんびり\n過ごそうかな～", 1, 103402, 0, 0, 1327);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "あ…\nお皿、洗って\nなかった…", 1, 103402, 0, 0, 1328);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "もう少し、大人の\n魅力が出せるように\nなりたいな", 1, 103402, 0, 0, 1329);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "素敵な彼氏…\n欲しいなぁ…", 1, 103402, 0, 0, 1330);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "彼と私\n釣り合うかな…\n大丈夫よね？", 1, 103402, 0, 0, 1331);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "今後のために\nちょっとは花嫁修業\nしてみようかな…？", 1, 103402, 0, 0, 1332);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "何事も\nお姉さんと一緒に\n楽しく頑張りましょ？", 1, 103402, 0, 0, 1333);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ね、ねえ！\nキミは年上と年下\nどっちが好きかな？", 1, 103402, 0, 0, 1334);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もう…\n構ってくれないと\n泣いちゃうぞ～？", 1, 103402, 0, 0, 1335);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お姉さんが～\n可愛がって\nあげようか～？", 1, 103402, 0, 0, 1336);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "極力人付き合いは\nしない主義なんだけど\nキミは例外かも…", 1, 103402, 0, 0, 1337);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お姉さんとチュー\nする？　ふふふ～\n冗談で～す！", 1, 103402, 0, 0, 1338);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "さーて、今日も\nいっちょやるぞー！", 1, 103402, 0, 1, 1339);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "後でのんびり\nストレッチでも\nしようっと♪", 1, 103402, 0, 2, 1340);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "一日よく働いた～！\n自分にごほうび\nあげたいなー♪", 1, 103402, 0, 3, 1341);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "仕事の前に、髪とか\n整えないと…", 1, 103402, 0, 0, 1342);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "自然体でゴロゴロ\nするのって\n幸せだなぁ…", 1, 103402, 0, 0, 1343);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "もう大人だし…\nあんまり可愛いのは\n似合わないかな…？", 1, 103402, 0, 0, 1344);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "うわあ\nこれ、私の好きな\n香りだー！", 1, 103402, 0, 0, 1345);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかーい…\nだ、だらけ\nちゃいそう…", 1, 103402, 0, 0, 1346);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "地道な努力が\nリア充への\n第一歩！", 1, 103402, 0, 0, 1347);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おーいしっ♪\nこのために\n生きてるわねえ", 1, 103402, 0, 0, 1348);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "大人の女らしく\n色んなことを学んで\nおかなくっちゃ", 1, 103402, 0, 0, 1349);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "大切な人に\n本をすすめるのって\nけっこう難しいなぁ", 1, 103801, 0, 0, 1351);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "き、きらーん☆\nお姉ちゃんに\n似てるかな…？", 1, 103801, 0, 0, 1352);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "そろそろ好きな\n作家さんの新刊が\n出るから楽しみ…", 1, 103801, 0, 0, 1353);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ちょっと、休憩…\n本でも読もうかな", 1, 103801, 0, 0, 1354);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "もっとたくさんの本に\n囲まれて生活したいな", 1, 103801, 0, 0, 1355);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "むかしむかしある所に\nシオリと\nあの人が…", 1, 103801, 0, 0, 1356);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "この本の主人公、\nあの人に\n似ているかも…\nかっこいいな", 1, 103801, 0, 0, 1357);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ケホケホ…\nコンコン…\nゴホッゴホッ…\nへ、平気ですよ？", 1, 103801, 0, 0, 1358);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あ…お姉ちゃんと\n約束があったんだ…", 1, 103801, 0, 0, 1359);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "しおりを探している？\nあ、本に挟む方ですね\nドキドキしました…", 1, 103801, 0, 0, 1360);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "最近調子がいいのは\n牧場の牛乳やチーズの\nおかげでしょうか？", 1, 103801, 0, 0, 1361);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "読みたい本も\nあなたと行きたい所も\n増えるばっかりです", 1, 103801, 0, 0, 1362);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "私の病気、\n悪化してるのかも！？\nすごく胸がドキドキ\nするんです…", 1, 103801, 0, 0, 1363);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "えっと、朝食の前には\nこの薬を飲んで…\n食後にはこの薬を…", 1, 103801, 0, 1, 1364);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ふぅ…午前中\n動いたので体力が…\nすこし休みますね", 1, 103801, 0, 2, 1365);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "早く寝ないと\n体に良くないですよね\nでも気になっている\n本があって…", 1, 103801, 0, 3, 1366);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "寝てばかりなので、\n髪が乱れてないかな\n…？", 1, 103801, 0, 0, 1367);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "少し休もう\n…やっぱり\nたくさん休もう", 1, 103801, 0, 0, 1368);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいものが\n枕元にあると\n安心できるんですよ", 1, 103801, 0, 0, 1369);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り…\n病は気からと言うので\n雰囲気も大事ですね", 1, 103801, 0, 0, 1370);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "こうして温まって\nいると、病気も\n治る気がします", 1, 103801, 0, 0, 1371);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "運動…イメージ\nトレーニングだけじゃ\nだめでしょうか…", 1, 103801, 0, 0, 1372);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "少食ですけど\nこれならたくさん\n食べられそうです", 1, 103801, 0, 0, 1373);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "続きが気になって\n読むのを止める\nタイミングが…", 1, 103801, 0, 0, 1374);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "しっかり休まないと\n早く回復するように", 1, 103802, 0, 0, 1376);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "き、きらーん☆\nお姉ちゃんに\n似てるかな…？　", 1, 103802, 0, 0, 1377);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "病室よりも…\nずっとこの部屋に\nいたいですね…　", 1, 103802, 0, 0, 1378);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "そろそろ好きな\n作家さんの新刊が\n出るから楽しみ…", 1, 103802, 0, 0, 1379);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "大切な人に\n本をすすめるのって\nけっこう難しいなぁ", 1, 103802, 0, 0, 1380);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "むかしむかしある所に\nシオリと\nあの人が…", 1, 103802, 0, 0, 1381);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あの人の\nためにも早く\n病気を治さないと…", 1, 103802, 0, 0, 1382);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ケホケホ…\nコンコン…\nゴホッゴホッ…\nへ、平気ですよ？", 1, 103802, 0, 0, 1383);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "新記録です！\n一週間連続、\n平熱を保ちました！", 1, 103802, 0, 0, 1384);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あ…お薬の時間…\n苦いけど我慢しなきゃ　", 1, 103802, 0, 0, 1385);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "最近調子がいいのは\n牧場の牛乳やチーズの\nおかげでしょうか？", 1, 103802, 0, 0, 1386);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "しおりを探している？\nあ、本に挟む方ですね\nドキドキしました…", 1, 103802, 0, 0, 1387);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "私の病気\n悪化してるのかも！？\nすごく胸がドキドキ\nするんです…", 1, 103802, 0, 0, 1388);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "えっと、朝食の前には\nこの薬を飲んで…\n食後にはこの薬を…", 1, 103802, 0, 1, 1389);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "…お昼の薬？\nあ、飲み忘れてました\nありがとうございます", 1, 103802, 0, 2, 1390);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "この薬を飲むと\n眠くなっちゃうんです\nでもまだ、あなたと\nお話したいし～", 1, 103802, 0, 3, 1391);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "寝てばかりなので、\n髪が乱れてないかな\n…？　", 1, 103802, 0, 0, 1392);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "少し休もう\n…やっぱり\nたくさん休もう", 1, 103802, 0, 0, 1393);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "この子がいれば\n病室に一人でも\n寂しくないですね", 1, 103802, 0, 0, 1394);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いろんな効能が？\n健康になる香りも\nあるのでしょうか？", 1, 103802, 0, 0, 1395);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "こうして温まって\nいると、病気も\n治る気がします", 1, 103802, 0, 0, 1396);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "私も、少しは\n体力をつけないと\nいけませんよね　", 1, 103802, 0, 0, 1397);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いっぱい食べて\n健康な体にならないと", 1, 103802, 0, 0, 1398);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "続きが気になって\n読むのを止める\nタイミングが…", 1, 103802, 0, 0, 1399);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "友達ができたら、\n山の上でお弁当…\n夢が広がります…", 1, 104001, 0, 0, 1401);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "あ、忘れずに\nお花に水を\nあげなきゃ…", 1, 104001, 0, 0, 1402);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "お菓子を作って、\nみなさんに振る舞って\n友達作戦！　とか…", 1, 104001, 0, 0, 1403);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "そろそろ新しい\n草人形を作って\n友達作りの特訓を…", 1, 104001, 0, 0, 1404);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "植物のお世話って、\nぼっちにとっては、\n救い…なんです…", 1, 104001, 0, 0, 1405);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ＢＢ団の活動日…\nまだかな…\nうふふふっ", 1, 104001, 0, 0, 1406);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "もっともっとあの人の\nそばで、一緒に友達を\n作っていきたいな…", 1, 104001, 0, 0, 1407);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あ、こんにちは！\n今日もＢＢ団で\nお世話になります！", 1, 104001, 0, 0, 1408);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あの…私の友達作りの\n練習方法、間違って\nませんよね…？", 1, 104001, 0, 0, 1409);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そうだ、今度、\n森に一緒に木の苗を\n植えに行きませんか？", 1, 104001, 0, 0, 1410);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "人とお話するのって、\n私、大好きです！\n友達ふやすぞ～！", 1, 104001, 0, 0, 1411);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あなたと話してると、\nまるで私がぼっちじゃ\nないみたいです！", 1, 104001, 0, 0, 1412);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "友達もほしいけど…\nあなたに会えたことが\n私の一番の幸せです", 1, 104001, 0, 0, 1413);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます！\n今日もＢＢ団、\nがんばるぞー！", 1, 104001, 0, 1, 1414);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "なんだか、お腹が\n空いてきました。\nお昼ごはんー♪", 1, 104001, 0, 2, 1415);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もう眠いかもです…\n明日は友達、\nできるといいなあ…", 1, 104001, 0, 3, 1416);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "私がもっと\n可愛ければ、\n友達できるかなあ？", 1, 104001, 0, 0, 1417);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふわあ…のんびり\nしすぎないように\n気を付けなきゃです", 1, 104001, 0, 0, 1418);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいなあ。\nこの子とも\n友達になりたい…", 1, 104001, 0, 0, 1419);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りです…\n精神統一して\n友達のイメトレ…", 1, 104001, 0, 0, 1420);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "灯りを見てると、\n心がなごみます～", 1, 104001, 0, 0, 1421);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "もぐもぐ…\nおいしいです…！\nみなさんもぜひ！", 1, 104001, 0, 0, 1422);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいしいです…\n私に友達がいたら、\n分けてあげたいな", 1, 104001, 0, 0, 1423);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "友達作りの\n参考になりそうなこと\n書いてないかな～？", 1, 104001, 0, 0, 1424);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "友達作りは、焦らず\n慌てず、じっくりと…", 1, 104002, 0, 0, 1426);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ひとつ屋根の下\nって感じ…\nいいですねえ…", 1, 104002, 0, 0, 1427);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "煮汁、煮汁が\n噴きこぼれて\nいませんか～", 1, 104002, 0, 0, 1428);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "今度、みなさんと\nピクニックとか…\nいってみたいな", 1, 104002, 0, 0, 1429);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ぼっちでもいい\nたくましく育てば\n…なんて", 1, 104002, 0, 0, 1430);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "最近、毎日あの人の\nこと考えちゃいます\nどうしてだろう…", 1, 104002, 0, 0, 1431);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "もっともっとあの人の\nそばで、一緒に友達を\n作っていきたいな…", 1, 104002, 0, 0, 1432);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あ！　ＢＢ団の活動\nですか？　嬉しくて\n飛び跳ねちゃいます！", 1, 104002, 0, 0, 1433);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あなたとのお話で友達\n作りの練習になるなら\n一石二鳥です！", 1, 104002, 0, 0, 1434);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "私少しは人と話しても\nテンパらなくなって\nきましたかね…？", 1, 104002, 0, 0, 1435);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あの、友達作りの\n新しい作戦\n考えてみたんですっ！", 1, 104002, 0, 0, 1436);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "あなたとお話する時の\nこの気持ち、私の宝物\nなんです…えへへ", 1, 104002, 0, 0, 1437);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "友達もほしいけど…\nあなたに会えたことが\n私の一番の幸せです", 1, 104002, 0, 0, 1438);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝ですね！\nこんないい朝は\n友達作りのチャンス！", 1, 104002, 0, 1, 1439);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あの…そろそろお腹\nすきませんか？\nお昼ごはんは…", 1, 104002, 0, 2, 1440);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もう眠いかもです…\n明日は友達\nできるといいなあ…", 1, 104002, 0, 3, 1441);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "私…見た目\nそこまで変じゃ\nないですよね…？", 1, 104002, 0, 0, 1442);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ほわあ～…\nふかふかって\nいいものですね～", 1, 104002, 0, 0, 1443);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "この子みたいな\nあいくるしさを\n目指したいです！", 1, 104002, 0, 0, 1444);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "灯りを見てると\n心がなごみます～", 1, 104002, 0, 0, 1445);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ぬくぬくで、なんだか\n眠くなっちゃいますね", 1, 104002, 0, 0, 1446);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "身体を鍛えて\nみなさんを\n守ります！", 1, 104002, 0, 0, 1447);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…\nおいしいです…！\nみなさんもぜひ！", 1, 104002, 0, 0, 1448);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "友達作りの\n参考になりそうなこと\n書いてないかな～？", 1, 104002, 0, 0, 1449);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "唱喚の歌は、みだりに\n歌っていいものでは\nないんです", 1, 104201, 0, 0, 1451);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ここでアイドルの\n練習は、さすがに\n迷惑ですよね？", 1, 104201, 0, 0, 1452);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "練習してもあんまり\n疲れなくなった…\nアイドルのおかげかな", 1, 104201, 0, 0, 1453);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "人々の平和を守る旅に\n同行してくれる人を\n探していて…", 1, 104201, 0, 0, 1454);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "あとで曲を復習して\nおかないと…", 1, 104201, 0, 0, 1455);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "踊りを見られるのは\nまだ恥ずかしいけど\nあの人になら…", 1, 104201, 0, 0, 1456);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "浜辺で曲を書こうと\n思うんですけど…\n一緒に行きませんか？", 1, 104201, 0, 0, 1457);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "いつも応援ありがとう\nございます♪　これは\nあ、握手の練習です！", 1, 104201, 0, 0, 1458);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "え、もう練習の時間？\nごめんなさい\nすぐ準備します！", 1, 104201, 0, 0, 1459);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "守るべき人たちに\n笑顔でいてもらうのも\n大切なんですね", 1, 104201, 0, 0, 1460);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "歌える曲を増やそうと\n思って。どんな曲が\n聞きたいですか？", 1, 104201, 0, 0, 1461);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "～～♪　あれ？\n今私、歌ってました？\n気づきませんでした", 1, 104201, 0, 0, 1462);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "…歌って欲しい？\n喜んで♪\nどの歌にしましょう？", 1, 104201, 0, 0, 1463);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます♪\n少し歌の練習を\nしてきますね", 1, 104201, 0, 1, 1464);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "もうお昼なんですか？\n練習に夢中で\n気づきませんでした", 1, 104201, 0, 2, 1465);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "明日の予定は…\nアイドルはやることが\n多いみたいで…", 1, 104201, 0, 3, 1466);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "見た目については\n前よりも気をつけてと\nノゾミに言われてます", 1, 104201, 0, 0, 1467);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "歌の調子をよくする\nためには休息も\n必要ですよね…", 1, 104201, 0, 0, 1468);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "この子たちを\n相手に練習して\nみようかな…♪", 1, 104201, 0, 0, 1469);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "…疲れてるのかな\n落ち着けているのが\n自分でもわかります", 1, 104201, 0, 0, 1470);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ここにいると\n穏やかな旋律が\n浮かんできます…", 1, 104201, 0, 0, 1471);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "歌うためには\n体力づくりは\n欠かせません", 1, 104201, 0, 0, 1472);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "歌った後は\nお腹が空いて\nしまうんです", 1, 104201, 0, 0, 1473);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "音楽について\n理論も勉強\nしないと…", 1, 104201, 0, 0, 1474);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "歌うことの楽しさ\n分かってきました\nもっと歌いたいな…", 1, 104202, 0, 0, 1476);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "練習してもあんまり\n疲れなくなった…\nアイドルのおかげかな", 1, 104202, 0, 0, 1477);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "精霊も強くなったし\nもっとたくさんの人を\n守りたいです", 1, 104202, 0, 0, 1478);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "最近、よく頭の中に\n歌が浮かんできます\n不思議な感覚…", 1, 104202, 0, 0, 1479);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "楽譜を買いました\n思いついた歌を\n書き留めておくために", 1, 104202, 0, 0, 1480);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "浜辺で曲を書こうと\n思うんですけど…\n一緒に行きませんか？", 1, 104202, 0, 0, 1481);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "私の中にある\n私だけの歌…\n作ってみようかな？", 1, 104202, 0, 0, 1482);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "守るべき人たちに\n笑顔でいてもらうのも\n大切なんですね", 1, 104202, 0, 0, 1483);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "歌える曲を増やそうと\n思って。どんな曲が\n聞きたいですか？", 1, 104202, 0, 0, 1484);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "魔物退治ですか！？\n…違います？\n良かった…", 1, 104202, 0, 0, 1485);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "いつも応援ありがとう\nございます♪　これは\nあ、握手の練習です！", 1, 104202, 0, 0, 1486);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "…歌って欲しい？\n喜んで♪\nどの歌にしましょう？", 1, 104202, 0, 0, 1487);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "～～♪　あれ？\n今私、歌ってました？\n気づきませんでした", 1, 104202, 0, 0, 1488);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "呼吸を深く、大きく…\nこれでちゃんと\n目が覚めますよ", 1, 104202, 0, 1, 1489);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "少し休んだら\n午後の練習に\n行ってきますね", 1, 104202, 0, 2, 1490);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "曲を作っていたら\nもうこんな時間…\nおやすみなさい", 1, 104202, 0, 3, 1491);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "見た目については\n前よりも気をつけてと\nノゾミに言われてます", 1, 104202, 0, 0, 1492);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "あ～…♪\nよく体がほぐれます…\nいい歌が歌えそうです", 1, 104202, 0, 0, 1493);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいと思う\n気持ちを、歌にしても\nいいかも知れませんね", 1, 104202, 0, 0, 1494);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "…疲れてるのかな\n落ち着けているのが\n自分でもわかります", 1, 104202, 0, 0, 1495);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ここにいると\n穏やかな旋律が\n浮かんできます…", 1, 104202, 0, 0, 1496);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "もっと体力をつけて\n最高のライブを\nファンに届けます！", 1, 104202, 0, 0, 1497);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "これでも一応\n体形には気をつけて\n食べてるんですよ？", 1, 104202, 0, 0, 1498);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "読書は歌に\n新しい風を\n吹き込んでくれます", 1, 104202, 0, 0, 1499);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "店の新メニューでも\n考えるかな", 1, 104301, 0, 0, 1501);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "あたしの店から、\n出前を届けようか？", 1, 104301, 0, 0, 1502);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "パトロール、\nパトロール…\nここは異常なしかな？", 1, 104301, 0, 0, 1503);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "腹へったら食う！\n悩んだら寝る！\nそれが一番だろ？", 1, 104301, 0, 0, 1504);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "のんびりし過ぎるのも\n…性に合わねぇな", 1, 104301, 0, 0, 1505);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "そろそろあいつ、\n腹すかしてるん\nじゃないかな？", 1, 104301, 0, 0, 1506);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "今日の献立は…\nあいつの好きなものに\nしてやるか", 1, 104301, 0, 0, 1507);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "強くなりたいなら、\nあたしがビシバシ\n鍛えてやるよ", 1, 104301, 0, 0, 1508);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "天気がいい日は\n外で運動したく\nならねぇか？", 1, 104301, 0, 0, 1509);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "腹減ったか？　なんか\n作ってやろうか？", 1, 104301, 0, 0, 1510);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ん？　なんだよ、\n相談事か？\nなんでも言ってくれ", 1, 104301, 0, 0, 1511);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お前が好きな飯って\nなんだ？\n今度、作ってやるよ", 1, 104301, 0, 0, 1512);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お前って不思議だよな\n一緒にいるとなんだか\n…なんでもねーよ", 1, 104301, 0, 0, 1513);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "気持ちいい朝だな！\n体を動かしたい気分だ\n付き合ってくれるか", 1, 104301, 0, 1, 1514);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼飯もう食ったか？\nまだなら、あたしが\nなんか作ってやるよ", 1, 104301, 0, 2, 1515);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "日中たっぷり動いたら\nそのぶん夜はしっかり\n休んどけよな", 1, 104301, 0, 3, 1516);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "た、たまにはその…\nかわいい格好とか\nしても…", 1, 104301, 0, 0, 1517);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふわぁ、\n一休みすっかなぁ～", 1, 104301, 0, 0, 1518);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "うっ！　か、かわいい\nじゃねぇか", 1, 104301, 0, 0, 1519);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "へー　いい匂いだな\nあいつもこういうの\n好きなのかな…", 1, 104301, 0, 0, 1520);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ふわぁ〜！\n温かいと、つい\nウトウトしちまうな", 1, 104301, 0, 0, 1521);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "オラオラオラーーー！\n燃えるぜーーー！", 1, 104301, 0, 0, 1522);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いい味してるぜ！\nうちの店でも\n出してみたいな", 1, 104301, 0, 0, 1523);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "文字を読んでると\nどうしても眠く\nなっちまうんだよなぁ", 1, 104301, 0, 0, 1524);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "パトロール終了～\n本日も異常なしっと！", 1, 104302, 0, 0, 1526);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "あたしの店から\n出前を届けようか？", 1, 104302, 0, 0, 1527);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "あいつ、早く\n帰ってこないかな", 1, 104302, 0, 0, 1528);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "あいつ\n腹すかせてないと\nいいんだけど…", 1, 104302, 0, 0, 1529);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "のんびりし過ぎるのも\n…性に合わねぇな", 1, 104302, 0, 0, 1530);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "あいつの事を思うと\n胸があったかくなる？\nなんだコレ…？", 1, 104302, 0, 0, 1531);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "今日の献立は…\nあいつの好きなものに\nしてやるか", 1, 104302, 0, 0, 1532);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ん？　なんだよ\n相談事か？\nなんでも言ってくれ", 1, 104302, 0, 0, 1533);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "天気がいい日は\n外で運動したく\nならねぇか？", 1, 104302, 0, 0, 1534);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "腹減ったか？　なんか\n作ってやろうか？", 1, 104302, 0, 0, 1535);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "腹へったら食う！\n悩んだら寝る！\nそれが一番だろ？", 1, 104302, 0, 0, 1536);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "あのさ…できれば\nもっとそばに…いや\nなんでもねぇ忘れろ！", 1, 104302, 0, 0, 1537);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お前って不思議だよな\n一緒にいるとなんだか\n…なんでもねーよ", 1, 104302, 0, 0, 1538);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "気持ちいい朝だな！\n体を動かしたい気分だ\n付き合ってくれるか？", 1, 104302, 0, 1, 1539);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼飯もう食ったか？\nまだなら、あたしが\nなんか作ってやるよ", 1, 104302, 0, 2, 1540);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あんま夜更しすんなよ\n明日に響いたら\n大変だろ？", 1, 104302, 0, 3, 1541);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "た、たまにはその…\nかわいい格好とか\nしても…", 1, 104302, 0, 0, 1542);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふぅ～♪\n疲れがとれるな～", 1, 104302, 0, 0, 1543);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "うっ！　か、かわいい\nじゃねぇか", 1, 104302, 0, 0, 1544);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "へー　いい匂いだな\nあいつもこういうの\n好きなのかな…", 1, 104302, 0, 0, 1545);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ふわぁ～！\n温かいと、つい\nウトウトしちまうな", 1, 104302, 0, 0, 1546);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "オラオラオラーーー！\n燃えるぜーーー！", 1, 104302, 0, 0, 1547);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いい味してるぜ！\nうちの店でも\n出してみたいな", 1, 104302, 0, 0, 1548);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "料理だけじゃなく\n経営術とかも\n学んどかねぇと…", 1, 104302, 0, 0, 1549);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "最近なにも\nしてくれません…\n焦らしてるんですね", 1, 104501, 0, 0, 1551);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ぐふふ、じゅるり…\nい、いけない、また\nいつの間にかよだれが", 1, 104501, 0, 0, 1552);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "好きな武器といえば\n剣より槍より\nやっぱり鞭…ぐふふ", 1, 104501, 0, 0, 1553);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "「無数の触手が\nクウカの柔肌に\n食い込み」…ぐふふ", 1, 104501, 0, 0, 1554);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "もしドＳさんが\nＭに転じたらと思うと\n身の毛がよだちます！", 1, 104501, 0, 0, 1555);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ドＳさんを登場\nさせるだけで、妄想に\n無限の広がりが！", 1, 104501, 0, 0, 1556);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あっ…\nジロジロ見てたの\n気づいちゃいました？", 1, 104501, 0, 0, 1557);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "視線を感じると\n思ったら…やはり\nドＳさんでしたか", 1, 104501, 0, 0, 1558);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今日は\nどんなヒドイことを\nしてくれるんですか？\nぐふふふ", 1, 104501, 0, 0, 1559);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "いつの間にそこに！？\nまさかクウカを監視\nしていたのですか！？", 1, 104501, 0, 0, 1560);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "クウカに触るつもり\nですか？　触るつもり\nなのですねっ！？", 1, 104501, 0, 0, 1561);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "クウカにナニをする\nつもりですか…\n期待してしまいます！", 1, 104501, 0, 0, 1562);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ドＳさんの視界に入る\nだけでドキドキが…\nこれが恋！？", 1, 104501, 0, 0, 1563);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます。\n朝からお盛んですね？\nぐふふ…", 1, 104501, 0, 1, 1564);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "こんなにも日の高い\nうちからドＳさんは…\nじゅるり", 1, 104501, 0, 2, 1565);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜はこれから、\nですよ…\nぐふ、ぐふふふ…", 1, 104501, 0, 3, 1566);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "キレイにおめかし\nしたのに力ずくで…\nぐふふふ", 1, 104501, 0, 0, 1567);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ソファの背にクウカを\n押し付けて…ぐふふ\nいいですね\nソファドン", 1, 104501, 0, 0, 1568);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "「見た目とは裏腹に\nそれは激しく攻め\nたてて」…ぐふふふ", 1, 104501, 0, 0, 1569);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "香りを吸ったクウカの\n頬は紅潮し目はうるみ\nもはや抗う力も…！", 1, 104501, 0, 0, 1570);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ああ、身体が\n火照って…\nぐふ、ぐふふ…", 1, 104501, 0, 0, 1571);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "はぁ、はぁ、こうして\nクウカの体力を\n奪ってから…ぐふふ", 1, 104501, 0, 0, 1572);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食欲が満たされたら\nつ、次はやはり…！\nそうなのですね！？", 1, 104501, 0, 0, 1573);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "この本の下に、\nそういう本を\nカムフラージュ？", 1, 104501, 0, 0, 1574);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "「ドＳさんと踊り子\n乱舞の一夜」…\n次の日記はこれで…", 1, 104502, 0, 0, 1576);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "最近なにも\nしてくれません…\n焦らしてるんですね", 1, 104502, 0, 0, 1577);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "も、妄想が\n足りません…\n禁断症状がっ…！", 1, 104502, 0, 0, 1578);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "もしドＳさんが\nＭに転じたらと思うと\n身の毛がよだちます！", 1, 104502, 0, 0, 1579);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "次はどんなドＳを\nされるのか、想像する\nだけで…ぐふふふ", 1, 104502, 0, 0, 1580);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "じっとしてると\nドＳさんのことばかり\n考えてしまいますね", 1, 104502, 0, 0, 1581);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "妄想が止まらなくて\nクウカどうにかなって\nしまいそうです！", 1, 104502, 0, 0, 1582);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ドＳさんといると体が\n火照って…クウカは\nいやらしい子です！", 1, 104502, 0, 0, 1583);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あっ…\nジロジロ見てたの\n気づいちゃいました？", 1, 104502, 0, 0, 1584);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ドＳさんのおかげで\n新しい扉が開けそう\nです…じゅるり", 1, 104502, 0, 0, 1585);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "いやー！　ドＳさんに\n襲われ…襲って\nくれないんですか？", 1, 104502, 0, 0, 1586);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "クウカはドＳさんに\n身も心も堕とされて\nしまったのですね", 1, 104502, 0, 0, 1587);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ドＳさんがお望みなら\nクウカは\nどんなことだって！", 1, 104502, 0, 0, 1588);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝だからこそ\nできる妄想が\nあります…ぐふふ", 1, 104502, 0, 1, 1589);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "こんな日の高いうち\nからドＳさんは…\nじゅるり", 1, 104502, 0, 2, 1590);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今夜は一晩中…\nなんですね？\nぐふふ…", 1, 104502, 0, 3, 1591);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "意外と難しいんですよ\n正しい亀甲縛りと\nいうものは…", 1, 104502, 0, 0, 1592);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "くつろいで油断\nしているスキに何を\nされるのでしょう！？", 1, 104502, 0, 0, 1593);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "「見た目とは裏腹に\nそれは激しく攻め\nたてて」…ぐふふふ", 1, 104502, 0, 0, 1594);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "これは禁断の香り…\nああっ一段階上の\n妄想が開花するうぅ！", 1, 104502, 0, 0, 1595);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ああっ、暖気がまるで\nロウソクのように\nクウカを攻めますっ！", 1, 104502, 0, 0, 1596);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "激しい攻めを受けきる\nためには、鍛えないと\nいけないのですね", 1, 104502, 0, 0, 1597);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "こんなにいっぱい\n入りません…\nお腹にっ！", 1, 104502, 0, 0, 1598);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "どんな本も\nよく見ると\nいやらしいです…！", 1, 104502, 0, 0, 1599);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この前遊んだ猫、\nモッフモフ\nだったにゃあ…♪", 1, 104601, 0, 0, 1601);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ほっぺやお腹が、\n肉球ぐらいぷにぷに…\nこれはまずいにゃ…", 1, 104601, 0, 0, 1602);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "大きな仕事が\n決まったにゃ！\n腕が鳴るにゃ～♪", 1, 104601, 0, 0, 1603);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "おやつのたい焼き、\nつぶあんとこしあん、\nどっちに\nしようかにゃ？", 1, 104601, 0, 0, 1604);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "うにゃー…\nもうちょっとお昼寝\nしたかったにゃ…\nむにゃむにゃ…", 1, 104601, 0, 0, 1605);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "キミに呼ばれると、\n猫まっしぐらな気分に\nなっちゃうにゃ♪", 1, 104601, 0, 0, 1606);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "キミのおかげで\nギルドの仕事も\n大成功だにゃ♪\nありがとにゃ♪", 1, 104601, 0, 0, 1607);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "うずうず…その指、\nじゃれついても\nいいかにゃ？", 1, 104601, 0, 0, 1608);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "にゃ？　あたしに何か\nご入り用かにゃ？\nお安くしとくにゃ～♪", 1, 104601, 0, 0, 1609);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "うーん、なんだか\n退屈にゃ～\n遊んで、遊んで～？", 1, 104601, 0, 0, 1610);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "素早い動きのコツ？\nタダじゃ教えて\nあげられないにゃ～♪", 1, 104601, 0, 0, 1611);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "そんなにあたしを\nなでたいにゃ？\nキミならなでさせて\nあげてもいいかにゃー", 1, 104601, 0, 0, 1612);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ふにゃあ、ねえねえ、\n一緒にゴロゴロ\nしようにゃあ？", 1, 104601, 0, 0, 1613);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "いい朝にゃ！\n顔を洗ってくるにゃ！", 1, 104601, 0, 1, 1614);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "むーん、そろそろ\nお昼…猫たちにも\n猫缶を…", 1, 104601, 0, 2, 1615);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふわあ…眠いにゃ…\n猫は布団で\n丸くなるにゃ", 1, 104601, 0, 3, 1616);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "客商売では、\n外見のチェックも\n欠かせないのにゃ！", 1, 104601, 0, 0, 1617);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "うにゃ～！\nお昼寝に\nぴったりにゃ", 1, 104601, 0, 0, 1618);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "これ…量産したら\n子どもにバカ売れ\nしそうだにゃ！", 1, 104601, 0, 0, 1619);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この灯り、まるで\n猫みたいな\n癒し効果にゃ！", 1, 104601, 0, 0, 1620);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ふにゃあ、\nあったかいと猫は丸く\nなっちゃうのにゃあ…", 1, 104601, 0, 0, 1621);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "本当は外で\n運動したいん\nだけどにゃ", 1, 104601, 0, 0, 1622);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "むーん、\n美味しいにゃー！\nたい焼きに\n匹敵するにゃ！", 1, 104601, 0, 0, 1623);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ…猫の\nしつけ方は、と…", 1, 104601, 0, 0, 1624);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "かわいいネコの置物を\nゲットしたにゃ！\nどこに飾ろうか\nにゃ～♪", 1, 104602, 0, 0, 1626);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "仕事の交渉がうまく\n行ったにゃ～♪\nいい気分だにゃ～♪", 1, 104602, 0, 0, 1627);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ねこじゃらしには\n食いついちゃうにゃ\nびしっ！　びしっ！", 1, 104602, 0, 0, 1628);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ほっぺやお腹が、肉球\nぐらいぷにぷに…\nこれはまずいにゃ…", 1, 104602, 0, 0, 1629);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "さっきのたいやき\nおいしかったにゃ♪\nごろごろごろ…", 1, 104602, 0, 0, 1630);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "手作りのたい焼き\nあいつは食べて\nくれるかにゃ…？", 1, 104602, 0, 0, 1631);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あいつには、いつか\nたっぷり恩返しが\nしたいにゃ…", 1, 104602, 0, 0, 1632);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "にゃーに？　あたしの\nことがそんなに気に\nなるのかにゃ？", 1, 104602, 0, 0, 1633);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あたしのこと…\nしっかり捕まえ\nといてにゃ？", 1, 104602, 0, 0, 1634);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あたしの力が\n必要かにゃ？　猫の手\n貸してあげるにゃ♪", 1, 104602, 0, 0, 1635);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "たいやきとクレープを\n合わせれば…\n新しい商売のニオイが\nするにゃ…！", 1, 104602, 0, 0, 1636);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "ふにゃあ、ねえねえ\n一緒にゴロゴロ\nしようにゃあ？", 1, 104602, 0, 0, 1637);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "キミと一緒にいると\n楽しくなってつい\nじゃれちゃうにゃ！", 1, 104602, 0, 0, 1638);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "いい朝にゃ！\n顔を洗ってくるにゃ！", 1, 104602, 0, 1, 1639);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "そろそろおっひる～\nにゃーんか\n食べたい…", 1, 104602, 0, 2, 1640);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "うーん、眠くなって\nきたにゃ。あたしは\n夜行性じゃないのにゃ", 1, 104602, 0, 3, 1641);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "にゃにゃ…\n髪が乱れてるにゃ", 1, 104602, 0, 0, 1642);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふっかふかにゃ～\n猫がねころん\nじゃうにゃ", 1, 104602, 0, 0, 1643);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "これ、猫と匹敵する\nぐらいかわいいにゃ！", 1, 104602, 0, 0, 1644);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "猫でもこわくない\n優しい灯りにゃ！", 1, 104602, 0, 0, 1645);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ぽっかぽか\nしあわせな気分にゃ～", 1, 104602, 0, 0, 1646);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "雨の日でも運動\nできるのは、濡れ\nなくて便利だにゃ！", 1, 104602, 0, 0, 1647);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "美味しいにゃ～！\nこれ、朝昼晩\n食べたいにゃ！", 1, 104602, 0, 0, 1648);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "本を読んで\n猫の気持ちを\n勉強するのにゃ！", 1, 104602, 0, 0, 1649);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "内職手伝える人\nいないかしら？", 1, 104801, 0, 0, 1651);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "次の依頼は、\nこういう計画で…\nうん、完璧ね！", 1, 104801, 0, 0, 1652);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "次の特売セールに\n向けて、しっかり\n準備しないと！", 1, 104801, 0, 0, 1653);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "配達の後に売り子\n次に採取のバイト…\nうん、効率的ね", 1, 104801, 0, 0, 1654);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "一日に受ける\nバイトの数、もう少し\n増やしたいわね", 1, 104801, 0, 0, 1655);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "師匠として\n頼りにされたいし\nもっと頑張らなきゃ！", 1, 104801, 0, 0, 1656);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "男の子と効率的に\n仲良くなる方法…\nこればっかりは難題ね", 1, 104801, 0, 0, 1657);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あら、\nちょうどよかった\n今から一緒に\nバイトでもどう？", 1, 104801, 0, 0, 1658);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "相談事かしら？\nそれくらいなら\n無料でいいわよ", 1, 104801, 0, 0, 1659);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "背後の気配なら\nすぐ分かるわ\n試してみる？", 1, 104801, 0, 0, 1660);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "道具やお金の管理は\n大丈夫？　手伝うから\nいつでも言って", 1, 104801, 0, 0, 1661);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "暇ができたから\n働きたいけど…\nキミとの時間も大切ね", 1, 104801, 0, 0, 1662);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ねえ、あの…\n私はキミにとって…\nいや、何でもないわ", 1, 104801, 0, 0, 1663);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう！\n今日も朝から\nバイトよ！", 1, 104801, 0, 1, 1664);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼時ね。\n少し休憩したら、\nまた働くわよ！", 1, 104801, 0, 2, 1665);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もうこんな時間！\n明日もバイトで\n朝早いのよ…", 1, 104801, 0, 3, 1666);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "接客業の依頼が\nある時は、外見も\nキレイにしないとね", 1, 104801, 0, 0, 1667);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "はぁ～バイトで\n疲れたから癒される～", 1, 104801, 0, 0, 1668);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "これを内職で\n作ったら\n儲かるかしら？", 1, 104801, 0, 0, 1669);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "リフレッシュできたわ\nこれでまた、バリバリ\n働けるわね！", 1, 104801, 0, 0, 1670);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "風邪を引いたら効率が\n落ちちゃうから、\n暖めないと！", 1, 104801, 0, 0, 1671);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "働き続けるには\n健康第一！　それには\n運動が一番よ", 1, 104801, 0, 0, 1672);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…\n腹が減っては\n戦ができぬ、よ！", 1, 104801, 0, 0, 1673);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "日々絶えず学んで、\n生活に活かすのよ！", 1, 104801, 0, 0, 1674);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "家計簿をつけなきゃ！\n覚えている時に\nやっておかないとね", 1, 104802, 0, 0, 1676);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "次の依頼は\nこういう計画で…\nうん、完璧ね！", 1, 104802, 0, 0, 1677);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ギルドの経費\nあとちょっとだけ\n削れそうね…", 1, 104802, 0, 0, 1678);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "少しでも時給のいい\nバイトがしたいけど\nなかなか\n出会えないのよ", 1, 104802, 0, 0, 1679);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "今度のバイトも\nなかなか大変そう\nね…腕が鳴るわ", 1, 104802, 0, 0, 1680);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "男の子と効率的に\n仲良くなる方法…\nこればっかりは難題ね", 1, 104802, 0, 0, 1681);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "私、どうしたんだろ？\n仕事中もずっと\n彼のこと考えてる…", 1, 104802, 0, 0, 1682);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "この間はヘルプに\n来てくれてありがとう\n頼んで正解だったわ", 1, 104802, 0, 0, 1683);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "見つけた！　ちょうど\n頼みたいことが\nあるんだけど、いい？", 1, 104802, 0, 0, 1684);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今から\n休憩するところなの\n一緒にどう？", 1, 104802, 0, 0, 1685);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ん？　どうしたの？\n私のことが\n気になるの？", 1, 104802, 0, 0, 1686);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "…たまには甘えても\nいい？　私だって\n弱る時はあるのよ", 1, 104802, 0, 0, 1687);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "暇ができたから\n働きたいけど…\nキミとの時間も大切ね", 1, 104802, 0, 0, 1688);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう！\nいい朝ね。一緒に\nランニングでもいく？", 1, 104802, 0, 1, 1689);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼時ね\n少し休憩したら\nまた働くわよ！", 1, 104802, 0, 2, 1690);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もうこんな時間！\n明日もバイトで\n朝早いのよ…", 1, 104802, 0, 3, 1691);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "女の子らしく…\nどうも忘れちゃう\nのよね", 1, 104802, 0, 0, 1692);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ここで少し\n休んだら\nまたバイトよ！", 1, 104802, 0, 0, 1693);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "これを内職で\n作ったら\n儲かるかしら？", 1, 104802, 0, 0, 1694);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "仕事から帰ってきて\nこういうのがあると\n素敵ね", 1, 104802, 0, 0, 1695);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "しっかり身体を\n温めて、血流を\nよくしなくっちゃ", 1, 104802, 0, 0, 1696);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "これで休憩中も\n無駄なく\n鍛えられるわ♪", 1, 104802, 0, 0, 1697);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…よく\n食べて、よく働く！\nそれが私のモットーよ", 1, 104802, 0, 0, 1698);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "日々絶えず学んで\n生活に活かすのよ！", 1, 104802, 0, 0, 1699);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "暇だし、お料理と\nお掃除とお洗濯と\n買い物しようかな？", 1, 104901, 0, 0, 1701);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "こうして歩いていれば\n弟くんが声をかけて\nくれるはず…", 1, 104901, 0, 0, 1702);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "弟くんがどんな生活を\nしてるのか調べるのも\nお姉ちゃんの務め！", 1, 104901, 0, 0, 1703);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "くんくん、\n弟くんのにおい…\n近くにいるね？", 1, 104901, 0, 0, 1704);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "お姉ちゃんの痕跡を\n部屋中に\n残しちゃおっと♪", 1, 104901, 0, 0, 1705);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "この部屋を、\n私と弟くんの\n愛の巣に…", 1, 104901, 0, 0, 1706);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "はぁ～…弟くん\n禁断症状だよ～", 1, 104901, 0, 0, 1707);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "弟くんの部屋は\nお姉ちゃんの\n部屋だよね～", 1, 104901, 0, 0, 1708);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "いいこいいこ～♪\nどう、お姉ちゃんの\nナデナデは？", 1, 104901, 0, 0, 1709);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "姉と弟の外出は\nデートって\nいうのかな？", 1, 104901, 0, 0, 1710);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "もう！\nイタズラする子には\nお姉ちゃんチョップ！", 1, 104901, 0, 0, 1711);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お姉ちゃんが\nぎゅ～ってして\nあげるね♪", 1, 104901, 0, 0, 1712);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あ、あのね…\nたまにはお姉ちゃんも\n甘えていい？", 1, 104901, 0, 0, 1713);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "着替えは？　荷物は？\nお出かけの準備は\nお姉ちゃんが手伝うね", 1, 104901, 0, 1, 1714);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "出かけるなら\n明るいうちに\n帰ってくるんだよ！", 1, 104901, 0, 2, 1715);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "まだ起きてるの？\nそれじゃあ、\nお姉ちゃんも\n夜更かししちゃお☆", 1, 104901, 0, 3, 1716);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "きれいなお姉ちゃん\n好きだよね♪", 1, 104901, 0, 0, 1717);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ここにお姉ちゃんの\n匂いを、た～っぷり\n残しておこうっと♪", 1, 104901, 0, 0, 1718);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい♪\nお姉ちゃんチョップ！", 1, 104901, 0, 0, 1719);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この香り、\n弟くん好きかな？", 1, 104901, 0, 0, 1720);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "これ、弟くんみたいに\nあったかいね～", 1, 104901, 0, 0, 1721);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "ダイエットダイエット\nきれいなお姉ちゃんに\nならなくちゃ", 1, 104901, 0, 0, 1722);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "あ、これ\n弟くんが好きな\n味付けだね！", 1, 104901, 0, 0, 1723);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "弟くんが読んでいいか\nお姉ちゃんが先に\n中を確認しなくちゃ！", 1, 104901, 0, 0, 1724);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "暇だし、お料理と\nお掃除とお洗濯と\n買い物しようかな？", 1, 104902, 0, 0, 1726);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "こうして歩いていれば\n弟くんが声をかけて\nくれるはず…", 1, 104902, 0, 0, 1727);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "弟くんのお友達は\nみんな私の妹だよ♪", 1, 104902, 0, 0, 1728);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "弟くんがどんな生活を\nしてるのか調べるのも\nお姉ちゃんの務め！", 1, 104902, 0, 0, 1729);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "はっ！\n弟くんが困ってる\n気がする！", 1, 104902, 0, 0, 1730);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "はぁ～…弟くん、\n禁断症状だよ～", 1, 104902, 0, 0, 1731);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "お姉ちゃんの痕跡を\n部屋中に\n残しちゃおっと♪", 1, 104902, 0, 0, 1732);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お姉ちゃん\nキミのお願いなら\nなんでも聞いて\nあげちゃうぞっ", 1, 104902, 0, 0, 1733);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "弟くんの部屋は\nお姉ちゃんの\n部屋だよね～", 1, 104902, 0, 0, 1734);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お姉ちゃんの胸に\n飛び込んでおいでっ♪", 1, 104902, 0, 0, 1735);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "いいこいいこ～♪\nどう、お姉ちゃんの\nナデナデは？", 1, 104902, 0, 0, 1736);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "あ、あのね…\nたまにはお姉ちゃんも\n甘えていい？", 1, 104902, 0, 0, 1737);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お風呂にする？\nごはんにする？\nそれとも…うふふ♪", 1, 104902, 0, 0, 1738);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "着替えは？　荷物は？\nお出かけの準備は\nお姉ちゃんが手伝うね", 1, 104902, 0, 1, 1739);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お姉ちゃんが\nお昼ごはん\n作ってあげようか？", 1, 104902, 0, 2, 1740);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "眠れないの？\nお姉ちゃんが子守歌\n歌ってあげるね！", 1, 104902, 0, 3, 1741);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "弟くんを\n誘惑しちゃうぞ～♪", 1, 104902, 0, 0, 1742);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ここにお姉ちゃんの\n匂いを、た～っぷり\n残しておこうっと♪", 1, 104902, 0, 0, 1743);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい♪\nお姉ちゃんチョップ！", 1, 104902, 0, 0, 1744);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "お肌に潤いが\nでてきたみたい～♪", 1, 104902, 0, 0, 1745);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "これ、弟くんみたいに\nあったかいね～", 1, 104902, 0, 0, 1746);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "ダイエットダイエット\nきれいなお姉ちゃんに\nならなくちゃ", 1, 104902, 0, 0, 1747);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "弟くんの手作りなら\nもっとおいしくなると\n思うんだけどなぁ～", 1, 104902, 0, 0, 1748);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "弟くんをきちんと\n教育するために\nお姉ちゃんは勉強を\nかかさないのだ☆", 1, 104902, 0, 0, 1749);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ん～、エレガントで\n大人なお部屋ね！\nアタシにぴったり！", 1, 105001, 0, 0, 1751);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "身長とバスト以外は\n完璧な大人\nなのになぁ～", 1, 105001, 0, 0, 1752);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "アタシの大人コーデで\nあいつも夢中ね♪", 1, 105001, 0, 0, 1753);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "朝顔の観察したら\n理系女子になれる\nかしら？", 1, 105001, 0, 0, 1754);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "レディは、どんな時も\nおしとやかに…って\nアタシも騒ぎたいー！", 1, 105001, 0, 0, 1755);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "大人っぽい子が\n多いわね…アタシも\n負けてられないわ！", 1, 105001, 0, 0, 1756);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "アタシが待ってる\nなんて、アイツは\n幸せものよねー", 1, 105001, 0, 0, 1757);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "わーい、アメだー♪\n食べる食べるー♪", 1, 105001, 0, 0, 1758);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "熱いハニーラテが\n飲みたーい！\n淹れてー淹れてー！", 1, 105001, 0, 0, 1759);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "なによ？　もしかして\n好きな子にイタズラ\nしたくなるってやつ？", 1, 105001, 0, 0, 1760);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "アタシに合う服\n雑誌で探そうっと！\nサイズじゃないわ、\nデザインとかの話よ！", 1, 105001, 0, 0, 1761);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ねーねー！\nアタシ、かわいい？\nかわいいわよね？", 1, 105001, 0, 0, 1762);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "これから出かけるの？\nしっかりアタシを\nエスコートしてね！", 1, 105001, 0, 0, 1763);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝のスキンケアは\n大事なの！", 1, 105001, 0, 1, 1764);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹すいたー\nダイエット\nやめちゃおうかなー", 1, 105001, 0, 2, 1765);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "エイジングケアを\nしないとねー", 1, 105001, 0, 3, 1766);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "この角度のほうが\n大人っぽく見えるかな\nそれともこっちかしら", 1, 105001, 0, 0, 1767);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "あ！　これ雑誌で\n見たことあるわ～\nだからきっと\nオシャレなのよ！", 1, 105001, 0, 0, 1768);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "か、かわいい♪　けど\n大人はこんなもの…\nでも、かわいいし～！", 1, 105001, 0, 0, 1769);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "オシャレ～♪\n大人なレディって\n感じよね♪", 1, 105001, 0, 0, 1770);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかーい♪\nここで宿題\nしようかしら？", 1, 105001, 0, 0, 1771);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "運動したら成長\nしないかしら？\n背とか胸とか…", 1, 105001, 0, 0, 1772);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食べすぎると\n太っちゃうな…\nでも、おいしいし～っ", 1, 105001, 0, 0, 1773);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "おもしろーい！\n…でも絵本って\n子供っぽいかしら？", 1, 105001, 0, 0, 1774);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "レディは、どんな時も\nおしとやかに…って\nアタシも騒ぎたいー！", 1, 105002, 0, 0, 1776);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "恋人にするなら\nイケメンか\nただイケよね～", 1, 105002, 0, 0, 1777);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "もう少し背が欲しいな\n…もっと牛乳を\n飲まなくちゃ！", 1, 105002, 0, 0, 1778);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "朝顔の観察したら\n理系女子になれる\nかしら？", 1, 105002, 0, 0, 1779);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "こ、これは補習の\nお知らせプリント！\nアイツに見つかる前に\n隠さなくちゃ！", 1, 105002, 0, 0, 1780);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "アイツおっそいなー\n別に会いたいわけじゃ\nないけど…\n来ないと気になる…", 1, 105002, 0, 0, 1781);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "アタシが待ってる\nなんて、アイツは\n幸せものよねー ", 1, 105002, 0, 0, 1782);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "なーに？\nアタシに甘えたいの？", 1, 105002, 0, 0, 1783);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "アタシに合う服\n雑誌で探そうっと！\nサイズじゃないわ\nデザインとかの話よ！", 1, 105002, 0, 0, 1784);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "頭撫でないで！\nお子様みたいに\nあつかわないでって\n言ってるのに～！", 1, 105002, 0, 0, 1785);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "壁ドンの練習…\nあれ？　壁ドンって\n男がするんだっけ？", 1, 105002, 0, 0, 1786);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "ねーねー！\nアタシ、かわいい？\nかわいいわよね？", 1, 105002, 0, 0, 1787);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "これから出かけるの？\nしっかりアタシを\nエスコートしてね！", 1, 105002, 0, 0, 1788);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "レディの朝は\n忙しいのよ", 1, 105002, 0, 1, 1789);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹すいたー\nダイエット\nやめちゃおうかなー", 1, 105002, 0, 2, 1790);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "エイジングケアを\nしないとねー", 1, 105002, 0, 3, 1791);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "身だしなみチェック\nオッケー！　これで\nいつアイツが来ても\n大丈夫ね！", 1, 105002, 0, 0, 1792);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "あ！　これ雑誌で\n見たことあるわ～\nだからきっと\nオシャレなのよ！", 1, 105002, 0, 0, 1793);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "あたしがもっと\nオシャレにかわいく\nしてあげようか？", 1, 105002, 0, 0, 1794);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "オシャレ～♪\n大人なレディって\n感じよね♪", 1, 105002, 0, 0, 1795);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかーい♪\nここで宿題\nしようかしら？", 1, 105002, 0, 0, 1796);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "運動したら成長\nしないかしら？\n背とか胸とか…", 1, 105002, 0, 0, 1797);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "レディは、食べ物にも\n気を使うのよ", 1, 105002, 0, 0, 1798);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "おもしろーい！\n…でも絵本って\n子供っぽいかしら？", 1, 105002, 0, 0, 1799);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "魔法と科学\nどっちも極めて\nみせるわ", 1, 105101, 0, 0, 1801);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "仕事も片付いたし\n部屋で\n実験実験…♪", 1, 105101, 0, 0, 1802);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "たまった治療代の\n請求書を\nまとめないと…", 1, 105101, 0, 0, 1803);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "新薬が出来たし\nすぐに試したいけど…\n実験台がいないわ", 1, 105101, 0, 0, 1804);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "部屋にこもりすぎると\n曜日の感覚が\nなくなるわね", 1, 105101, 0, 0, 1805);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あの子の記憶を\n取り戻せる薬…\n作れないものかしら", 1, 105101, 0, 0, 1806);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "好意に気づいて貰える\n薬って、どうすれば\n作れるのかしら", 1, 105101, 0, 0, 1807);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あら、ヒマなら\n薬草の整理を\n手伝って", 1, 105101, 0, 0, 1808);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "もしかして実験に\n付き合ってくれるの？\nえ？　違う？", 1, 105101, 0, 0, 1809);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "具合が悪い？\nなら診てあげる\nまずは触診から…", 1, 105101, 0, 0, 1810);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "植物に興味あるの？\nなら教えてあげるわ\n色々とね…", 1, 105101, 0, 0, 1811);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "キミの傍にいるだけで\n高揚しちゃうのは\n何故かしら…？", 1, 105101, 0, 0, 1812);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "私はおしおきする\n側のことが多いけど…\nキミにはされたいかも", 1, 105101, 0, 0, 1813);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お昼までに調合用の\n花を集めたいの\n手伝ってくれる？", 1, 105101, 0, 1, 1814);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あら、もうお昼？\nそろそろ一息\n入れましょうか", 1, 105101, 0, 2, 1815);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜も更けて来たわね\n私は朝まで実験だけど\n見学していく？", 1, 105101, 0, 3, 1816);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "医者たるもの\nいつだって\n清潔に…♪", 1, 105101, 0, 0, 1817);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "いいわねこれ\n仮眠の時に\n使わせてもらうわ", 1, 105101, 0, 0, 1818);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ぬいぐるみなら\n動物も…", 1, 105101, 0, 0, 1819);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り…\n仕事場にも\n置いてみようかしら", 1, 105101, 0, 0, 1820);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ここにいると\nついウトウト\nしちゃうわ…", 1, 105101, 0, 0, 1821);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "座ってる時間が多いと\n運動不足になるし\nたまにはいいわね", 1, 105101, 0, 0, 1822);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "研究していると\nつい食べるのを\n忘れちゃうのよね", 1, 105101, 0, 0, 1823);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "実験もいいけど\nいつか成果を\n本にしないと…", 1, 105101, 0, 0, 1824);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "徹夜はツラいけど\n集中すると時間の\n感覚がなくなって…", 1, 105102, 0, 0, 1826);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "痛みに悶える顔って\nどうしてあんなに\n興奮するのかしら？", 1, 105102, 0, 0, 1827);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "彼に罵られたら\nどんな気分かしら\n意外と快感かも？", 1, 105102, 0, 0, 1828);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "毒を薄めると\n薬になるのって\n今でも不思議だわ", 1, 105102, 0, 0, 1829);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "綺麗なバラには\nトゲがあるけど\n魅力の一つよね", 1, 105102, 0, 0, 1830);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "カレをさりげなく\n惚れさせる方法を\n研究するわよ…♪", 1, 105102, 0, 0, 1831);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "好意に気づいて貰える\n薬って、どうすれば\n作れるのかしら", 1, 105102, 0, 0, 1832);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "構って欲しいの？\nじゃあ、君の体を\n調べさせて？", 1, 105102, 0, 0, 1833);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "実験に付き合って\n大丈夫よ、試すのは\nただの栄養剤だから", 1, 105102, 0, 0, 1834);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "欲しい薬が\nあったら言ってね\n調合してみるから", 1, 105102, 0, 0, 1835);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "おしおきされたいの？\nキミにだったら\nいつでもしてあげる", 1, 105102, 0, 0, 1836);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "キミの傍にいるだけで\n高揚しちゃうのは\n何故かしら…？", 1, 105102, 0, 0, 1837);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "私はおしおきする\n側のことが多いけど…\nキミにはされたいかも", 1, 105102, 0, 0, 1838);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝しか取れない\n植物があるの\n採取しに行くわよ", 1, 105102, 0, 1, 1839);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼時ってやけに\n眠たくなるわよね\n…調べたくなるわ", 1, 105102, 0, 2, 1840);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日くらいは\nゆっくり眠りたいわ\n…キミと一緒にね", 1, 105102, 0, 3, 1841);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "身なりについて\n研究するのも\n楽しそうね", 1, 105102, 0, 0, 1842);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "休息に必要な道具は\n妥協せずに選ぶ！\nこれだけは譲れないわ", 1, 105102, 0, 0, 1843);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "たまにはこういう\n可愛らしいものに\n触れないとね♪", 1, 105102, 0, 0, 1844);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り…\n仕事場にも\n置いてみようかしら", 1, 105102, 0, 0, 1845);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "仕事がなかったら\nこのまますーっと\n眠りたいのに…", 1, 105102, 0, 0, 1846);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "運動しないと\n体型の維持が…", 1, 105102, 0, 0, 1847);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "適度な食事も\n大切よね", 1, 105102, 0, 0, 1848);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "まさか私が\n恋愛読本を読む\n日が来るなんて…", 1, 105102, 0, 0, 1849);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ぺっぺっ！\n…い、いけないっ！", 1, 105201, 0, 0, 1851);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "いっけな～い！\nひづめで床に傷が！", 1, 105201, 0, 0, 1852);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "太っちゃったかも～！\n伐採でダイエット\nしなくっちゃ！", 1, 105201, 0, 0, 1853);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "きちんと生活すると\n毛づやが良くなる\nみたいなのよね～", 1, 105201, 0, 0, 1854);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "みんな、体重\nどれくらいなのかな？", 1, 105201, 0, 0, 1855);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "体力なら自信\nあるんだけど…\n恋にはちょっぴり\n臆病になっちゃう", 1, 105201, 0, 0, 1856);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "いつか人間の女の子\nみたいなデート、\nしてみたいな～♪", 1, 105201, 0, 0, 1857);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "私ね「どこにでもいる\n普通の女の子」って\n言葉が憧れなんだ～♪", 1, 105201, 0, 0, 1858);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "チャームポイント？\n自分では分からない\nけど…まつげかなぁ？", 1, 105201, 0, 0, 1859);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "リマリマ～♪\nはっ！？\nわ、私ったら今何を？", 1, 105201, 0, 0, 1860);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "力仕事ならまかせて！", 1, 105201, 0, 0, 1861);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "人間になりたいな～\nそれか、あなたが\n私みたいな姿に…♪", 1, 105201, 0, 0, 1862);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "しょうがないなあ、\nこんなにモフらせるの\nあなただけだよ？", 1, 105201, 0, 0, 1863);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今朝は寝癖がひどいわ\nしっぽの辺りとか～", 1, 105201, 0, 1, 1864);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ランチは\nおしゃれなカフェで\nしてみたいな～♪", 1, 105201, 0, 2, 1865);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お肌のケアに\nパックしながら\n寝ようかな～", 1, 105201, 0, 3, 1866);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "やだっ、\nまた寝ぐせついてる！\n直さないと！", 1, 105201, 0, 0, 1867);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ミシッっていった！\n私、重すぎるかも！？", 1, 105201, 0, 0, 1868);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "あ！　あなたも\n美人さんね～♪", 1, 105201, 0, 0, 1869);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "はぁ、まったり…\n四足歩行しちゃい\nそうだわ…", 1, 105201, 0, 0, 1870);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったか～い♪\n…私、毛皮だから\n暑すぎるかも", 1, 105201, 0, 0, 1871);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "な、なんだか野生に\n帰っちゃいそう！", 1, 105201, 0, 0, 1872);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ぱくぱく、もぐもぐ、\nぺっぺっ…\nやだ、はしたない！", 1, 105201, 0, 0, 1873);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "きゃーーー！\nこの恋愛小説\nとっても\nドキドキしちゃう～", 1, 105201, 0, 0, 1874);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "素敵ね～、居るだけで\n女子力があがりそうな\nお部屋だわ～", 1, 105202, 0, 0, 1876);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "私、大丈夫かしら？\n他の子に怖がられたり\nしないかな…？", 1, 105202, 0, 0, 1877);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "動物苑…って\n嫌なギルド名ね…", 1, 105202, 0, 0, 1878);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "好き、嫌い、好き…\nあっ！　うっかりして\n花占いのお花\n食べちゃった！", 1, 105202, 0, 0, 1879);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ここ、女の子らしい\nものでいっぱいね～！\nときめいちゃうわ～♪", 1, 105202, 0, 0, 1880);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "体力なら自信\nあるんだけど…\n恋にはちょっぴり\n臆病になっちゃう", 1, 105202, 0, 0, 1881);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あの人が\n来てくれるまで薪割り\nでもしてよっかな？", 1, 105202, 0, 0, 1882);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "一緒にお出かけ？\nうれしいけど…\n心の準備が！\nはわわわ！", 1, 105202, 0, 0, 1883);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "どうしたの？\n急に抱きついてきて…\n癒されたいの？", 1, 105202, 0, 0, 1884);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ぺっぺっ！\n…い、いけないっ！", 1, 105202, 0, 0, 1885);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "メタモルアップルを\nここで食べたら、\nみんな驚くわよね", 1, 105202, 0, 0, 1886);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "しょうがないなあ、\nこんなにモフらせるの\nあなただけだよ？", 1, 105202, 0, 0, 1887);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "人間になりたいな～\nそれか、あなたが\n私みたいな姿に…♪", 1, 105202, 0, 0, 1888);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今朝は寝癖がひどいわ\nしっぽの辺りとか～", 1, 105202, 0, 1, 1889);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ダイエット中だから\nお昼は抜いてるの～", 1, 105202, 0, 2, 1890);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お肌のケアに\nパックしながら\n寝ようかな～", 1, 105202, 0, 3, 1891);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "ちゃんとかわいく\nしてないと刈られ…\n狩られちゃうもんね！", 1, 105202, 0, 0, 1892);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ミシッっていった！\n私、重すぎるかも！？", 1, 105202, 0, 0, 1893);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "あ！　あなたも\n美人さんね～♪", 1, 105202, 0, 0, 1894);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り～\n森の中にいるみたいに\nとっても落ち着く～", 1, 105202, 0, 0, 1895);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "素敵～♪　…\nきゃっ！　私の毛が\nたいへんなことに～！", 1, 105202, 0, 0, 1896);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "な、なんだか野生に\n帰っちゃいそう！", 1, 105202, 0, 0, 1897);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "何を食べるかより\n誰と食べるかが\n大事なのよね", 1, 105202, 0, 0, 1898);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "きゃーーー！\nこの恋愛小説\nとっても\nドキドキしちゃう～", 1, 105202, 0, 0, 1899);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ヴァイスフリューゲル\nを盛り上げる方法、\n共に語らおう！", 1, 105301, 0, 0, 1901);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "私は子供ではない…！\nが、お菓子は\nいただこう！", 1, 105301, 0, 0, 1902);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "部屋はきちんと\n片づけておかなくては\n部屋の汚れは\n心の汚れだ", 1, 105301, 0, 0, 1903);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "むむむ…明日\n目が覚めたら、身長が\n伸びていないものか…", 1, 105301, 0, 0, 1904);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "お菓子が常備されて\nいる部屋。そんな\nものが、私の好みだ…", 1, 105301, 0, 0, 1905);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あいつとの新たな\n鍛錬が\n待ち遠しいな…！", 1, 105301, 0, 0, 1906);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "最近、あいつと\n過ごしていて、毎日が\n充実しているな…", 1, 105301, 0, 0, 1907);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "軍人の本分は日々の\n研鑽にあるからな。\n今日も鍛錬に\n行かないか？", 1, 105301, 0, 0, 1908);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "毎日牛乳を飲んでいる\nのだが、なかなか背が\n伸びないものだな…", 1, 105301, 0, 0, 1909);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "貴公にも、飴をくれて\nやろうか？\nあまいぞ～！\n美味しいぞ～！", 1, 105301, 0, 0, 1910);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "私ともっと高く、\n共に飛ぼう！", 1, 105301, 0, 0, 1911);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "貴公は、本当に頼りに\nなる男だな…いや、\nふとそう思っただけだ", 1, 105301, 0, 0, 1912);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "貴公と共にいられる\nことは私の喜びだ。\nこれからも\nよろしく頼むぞ", 1, 105301, 0, 0, 1913);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "うむ、いい朝だ。\n本国の夜明けを\n思い出してしまうな！", 1, 105301, 0, 1, 1914);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "そろそろ昼食に\nするか。腹が減っては\n戦はできないからな", 1, 105301, 0, 2, 1915);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふわああ…私は子供\nではないが…眠い時は\n眠いのだ…", 1, 105301, 0, 3, 1916);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "身だしなみは、心の\n在りようを映すから\n気をつけなくてはな", 1, 105301, 0, 0, 1917);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふう…軍人たるもの\n常日頃、油断は\nできないのだが…\nお、落ち着くな…", 1, 105301, 0, 0, 1918);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "うむ…このかわいさ…\n本国に持って\n帰りたい…", 1, 105301, 0, 0, 1919);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "このともし火、戦いに\n明け暮れる我らの心を\n癒すものだな…", 1, 105301, 0, 0, 1920);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "はあ～、ぽかぽか…\nい、いや！\n気を緩めないぞっ！", 1, 105301, 0, 0, 1921);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "うおおおおおっ！\n鍛錬、鍛錬、\n鍛錬っ！！", 1, 105301, 0, 0, 1922);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いつ戦いになっても\n困らぬように、\n腹八分目に\nしておくのだ！", 1, 105301, 0, 0, 1923);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "これを読んで、新たな\n戦術を編み出すぞっ！", 1, 105301, 0, 0, 1924);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "たまには掃除でも\nするか。部屋が\n綺麗になるのは\n喜ばしいことだ", 1, 105302, 0, 0, 1926);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "部屋の中では\n剣を振り回せないのが\n玉に瑕だな…", 1, 105302, 0, 0, 1927);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "お菓子が常備されて\nいる部屋。そんな\nものが、私の好みだ…", 1, 105302, 0, 0, 1928);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "毎日牛乳を飲んでいる\nのだが、なかなか背が\n伸びないものだな…", 1, 105302, 0, 0, 1929);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "家庭を守れない者が\n国を守れるはずが\nない。この部屋も\n私が守るぞ！", 1, 105302, 0, 0, 1930);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "あいつは今頃、何を\nしているのだろうな…\nふふっ", 1, 105302, 0, 0, 1931);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あいつと会える日が\nこんなにも待ち遠しく\nなるとはな…", 1, 105302, 0, 0, 1932);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "軍人の本分は日々の\n研鑽にあるからな\n今日も鍛錬に\n行かないか？", 1, 105302, 0, 0, 1933);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おお、今日も鍛錬の\n時間だったか！\nすまないな\nすぐ行く！", 1, 105302, 0, 0, 1934);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "私は子供ではない！\nが…たまには童心に\n帰りたい時もある…", 1, 105302, 0, 0, 1935);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "貴公にも、飴を\nくれてやろうか？\nあまいぞ～！\n美味しいぞ～！", 1, 105302, 0, 0, 1936);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "私と歩きたいのか…？\nそうだな。二人で\n散歩でも行こうか", 1, 105302, 0, 0, 1937);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "貴公と共にいられる\nことは私の喜びだ\nこれからも\nよろしく頼むぞ", 1, 105302, 0, 0, 1938);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "うむ、いい朝だ\n本国の夜明けを\n思い出してしまうな！", 1, 105302, 0, 1, 1939);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "そろそろ昼時だな\n鍛錬の手を緩めて\n昼食にするか", 1, 105302, 0, 2, 1940);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "寝る前に…あと少し\nだけ、鍛錬を…", 1, 105302, 0, 3, 1941);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "ヴァイス\nフリューゲルの一員と\nして恥ずかしくないよう\n身なりを整えなくては", 1, 105302, 0, 0, 1942);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふう…軍人たるもの\n常日頃、油断は\nできないのだが…\nお、落ち着くな…", 1, 105302, 0, 0, 1943);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "うむ…このかわいさ…\n本国に持って\n帰りたい…", 1, 105302, 0, 0, 1944);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "このともし火\n戦いに明け暮れる\n我らの心を\n癒すものだな…", 1, 105302, 0, 0, 1945);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "はあ～、ぽかぽか…\nい、いや！\n気を緩めないぞっ！", 1, 105302, 0, 0, 1946);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "うおおおおおっ！\n鍛錬、鍛錬\n鍛錬っ！！", 1, 105302, 0, 0, 1947);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いつ戦いになっても\n困らぬように\n腹八分目に\nしておくのだ！", 1, 105302, 0, 0, 1948);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "うむ…脳細胞が\n活性化してきたぞ\n読書は大事だな", 1, 105302, 0, 0, 1949);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "私たちの騎空艇\nどんなデザインに\nしよう…？", 1, 105701, 0, 0, 1951);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "団員募集の\nポスター\n作ろうっと♪", 1, 105701, 0, 0, 1952);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "父さん…\n今頃どこで\n何してるんだろ？", 1, 105701, 0, 0, 1953);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "騎空艇に乗って、\n誰もいったことがない\n場所を見つけたいな", 1, 105701, 0, 0, 1954);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "父さん以上の\n世界一の\n騎空士になりたい！", 1, 105701, 0, 0, 1955);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "仲間と行く空の旅…\n何度想像しても\nドキドキするなぁ", 1, 105701, 0, 0, 1956);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "父さん…\n私にもね、大切な\n仲間ができたよ", 1, 105701, 0, 0, 1957);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "仕事の依頼？\nすぐに支度\nしてくるね！", 1, 105701, 0, 0, 1958);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ねえねえ！\n団員募集のポスター\n一緒に作ろうよ！", 1, 105701, 0, 0, 1959);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "なーにー？\nどうしたの？\n今呼んだよね？", 1, 105701, 0, 0, 1960);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "今は休憩中だよ？\nだからあなたも\nゆっくりしてて", 1, 105701, 0, 0, 1961);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "私にとってあなたは\nとっても頼りになる、\n自慢の団員だよ！", 1, 105701, 0, 0, 1962);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お父さんに会えたら、\n大切な仲間として\nあなたを紹介するね！", 1, 105701, 0, 0, 1963);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう！\n体の調子はどう？\n今日は頑張れそう？", 1, 105701, 0, 1, 1964);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ねえねえ、お昼\n食べに行こうよ！\nお腹空いちゃった", 1, 105701, 0, 2, 1965);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "…あれ？\nおしゃべりしてたら\nもうこんな時間？", 1, 105701, 0, 3, 1966);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "どうせならオシャレな\n騎空士って\n呼ばれたいな", 1, 105701, 0, 0, 1967);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふぅ、疲れた～…\nちょっとだけ\n休んじゃおっと", 1, 105701, 0, 0, 1968);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "よし！　キミは\n今から団長代理だ！\n…なんてね♪", 1, 105701, 0, 0, 1969);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り～♪\n気持ちが\n落ち着く～…", 1, 105701, 0, 0, 1970);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "これって\n騎空艇に\n置けるかな…？", 1, 105701, 0, 0, 1971);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "どんな仕事でも\nこなせるような\n体力がないとね…！", 1, 105701, 0, 0, 1972);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "あむっ…うん！\n美味しい～！\n今度作ってみよう♪", 1, 105701, 0, 0, 1973);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "空を冒険するには\n色んなことを\n知っておかないと…", 1, 105701, 0, 0, 1974);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "…戻らなくなったよ\nどうすれば元に\n戻る…？", 1, 105702, 0, 0, 1976);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "暇だよ…\nどこかに強い人は\nいないか？", 1, 105702, 0, 0, 1977);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ジョブチェンジ！\n…叫んでも\n戻らないよ", 1, 105702, 0, 0, 1978);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "今のうちに、\n魔物退治の\n仕事に行くね！", 1, 105702, 0, 0, 1979);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ハァ～…\nうん、気の巡りは\n問題ないね！", 1, 105702, 0, 0, 1980);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "私の力の源は\n仲間との\n絆だよ！", 1, 105702, 0, 0, 1981);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "いつかこの拳を\n空を越えた、星まで\n届かせたいね", 1, 105702, 0, 0, 1982);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "功夫が足りない人は\nどうすればいいか？\nもちろん修行だよ！", 1, 105702, 0, 0, 1983);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "私はいつも通りに\n喋ってるつもり\nだよ？", 1, 105702, 0, 0, 1984);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "どうした？\nもしかして手合せ\nしたいか？", 1, 105702, 0, 0, 1985);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "騎空士としても\n拳法家としても\n目指すは世界一ね！", 1, 105702, 0, 0, 1986);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "背中はあなたに\n預けたよ！\nよろしくね！", 1, 105702, 0, 0, 1987);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あなたと一緒なら\nきっと、今よりもっと\n強くなれるよ！", 1, 105702, 0, 0, 1988);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ちゃんと起きてるか？\n寝ぼけてたら\nダメよ？", 1, 105702, 0, 1, 1989);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "腹減ったね…\nなにか食べに\n行くよ！", 1, 105702, 0, 2, 1990);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "修行のしすぎは\n良くないよ？\n気をつけるね", 1, 105702, 0, 3, 1991);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "美しい技は\n美しい体が\nあってこそ！", 1, 105702, 0, 0, 1992);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "よいしょっと…\nちょっとのんびり\nさせてもらうよ", 1, 105702, 0, 0, 1993);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "…練習に\n使うのはさすがに\n可哀そうね", 1, 105702, 0, 0, 1994);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "これは…\n瞑想の時にも\n使ってみたいね", 1, 105702, 0, 0, 1995);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "出来ればもっと\n熱いほうが\n嬉しいよ", 1, 105702, 0, 0, 1996);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "ここでも\n修行出来るなんて\n最高だよ！", 1, 105702, 0, 0, 1997);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "気力の源は体力！\n体力の源は\n健康とご飯！", 1, 105702, 0, 0, 1998);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "んー…\n難しいことは\nわかんないよ！", 1, 105702, 0, 0, 1999);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "わたしたちの\nギルドハウスへ\nようこそ～！", 1, 105801, 0, 0, 2001);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ぐるるる～…\nあ、お腹が\n鳴っちゃいました…", 1, 105801, 0, 0, 2002);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ん？\n食べ物のにおい？", 1, 105801, 0, 0, 2003);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "みんなと仲良く食卓を\n囲みたいですね～", 1, 105801, 0, 0, 2004);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "この部屋が、わたしの\n帰る場所です♪", 1, 105801, 0, 0, 2005);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あの人を見ると\n胸が満たされます～\nお腹は空いてますが！", 1, 105801, 0, 0, 2006);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あの人、\n大食いの子って\n嫌いかな？", 1, 105801, 0, 0, 2007);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "食べもの、くれるん\nですか？　わーい！\n恋しちゃいそう♪", 1, 105801, 0, 0, 2008);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "つ、つまみ食いなんて\nしてませんよ？\nこれは味見です！", 1, 105801, 0, 0, 2009);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おやつは別腹、\nごはんも別腹、\n魔物も別腹～", 1, 105801, 0, 0, 2010);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "好きなものを、\n好きな人達と食べる！\n最高の贅沢ですね☆", 1, 105801, 0, 0, 2011);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あなたは、\nごはん王子ですね～", 1, 105801, 0, 0, 2012);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "大好きです～\n愛してます～\nえへへ～♪", 1, 105801, 0, 0, 2013);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝ごはんも終わったし\n早速ブランチを\n食べませんか？", 1, 105801, 0, 1, 2014);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ご飯、\nおいしかったですね～\nそれじゃあ、そろそろ\nおやつにしましょう☆", 1, 105801, 0, 2, 2015);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お夕飯も、晩ごはんも\n食べたし…さぁ！\nお夜食の時間ですよ☆", 1, 105801, 0, 3, 2016);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "身だしなみ、\n身だしなみ…\nきちんとしないとね♪", 1, 105801, 0, 0, 2017);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふい～\n消化中です～", 1, 105801, 0, 0, 2018);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "おいしそ…\nか、かわいいです～", 1, 105801, 0, 0, 2019);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りですね～\n空気までおいしそう～\nじゅるり♪", 1, 105801, 0, 0, 2020);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ほっかほか～♪\n魔物の丸焼きが\n作れちゃいますね！", 1, 105801, 0, 0, 2021);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "走って食べて！\n走って食べて！\n\この無限ループです！", 1, 105801, 0, 0, 2022);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いくつでも\n食べられますよ！\n幸せ～☆", 1, 105801, 0, 0, 2023);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "料理の絵を\n見ているだけで、\nよ、よだれが～", 1, 105801, 0, 0, 2024);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この部屋が、わたしの\n帰る場所です♪", 1, 105802, 0, 0, 2026);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ギルドハウス\nどんどん素敵に\nなっていくな～♪", 1, 105802, 0, 0, 2027);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "「やばい」とか\n「おいっす」とか…\n民の言葉って難しい", 1, 105802, 0, 0, 2028);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お菓子の家に\n住みたいな～", 1, 105802, 0, 0, 2029);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "あ、頼んでた出前が\n届いたかな？", 1, 105802, 0, 0, 2030);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "大切な人がいて\n大切な場所がある\nすごく幸せです♪", 1, 105802, 0, 0, 2031);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あの人\n大食いの子って\n嫌いかな？", 1, 105802, 0, 0, 2032);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ごはんに行きますか？\n作りましょうか？\n店屋物もいいですね～", 1, 105802, 0, 0, 2033);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "モグモグ…\nあげませんよ～", 1, 105802, 0, 0, 2034);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おやつは別腹\nごはんも別腹\n魔物も別腹～", 1, 105802, 0, 0, 2035);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "好きなものを\n好きな人達と食べる！\n最高の贅沢ですね☆", 1, 105802, 0, 0, 2036);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "大好きです～\n愛してます～\nえへへ～♪", 1, 105802, 0, 0, 2037);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "わたし食べても\n太らないんです♪\nほらほら～触って\nみてくださいよ～", 1, 105802, 0, 0, 2038);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝ごはんも終わったし\n早速ブランチを\n食べませんか？", 1, 105802, 0, 1, 2039);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ご飯\nおいしかったですね～\nそれじゃあ、そろそろ\nおやつにしましょう☆", 1, 105802, 0, 2, 2040);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お夕飯も、晩ごはんも\n食べたし～。さぁ！\nお夜食の時間ですよ☆", 1, 105802, 0, 3, 2041);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "お姫さまみたいに\nきれいに\nならないと…", 1, 105802, 0, 0, 2042);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "のんびりしていても\nお腹がすいちゃうん\nですよね～", 1, 105802, 0, 0, 2043);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "おいしそ…\nか、かわいいです～", 1, 105802, 0, 0, 2044);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "アップル系、ピーチ系\nオレンジ系…\n香りも色々ですね～", 1, 105802, 0, 0, 2045);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ここでお魚を\n焼けたら\n最高ですね～♪", 1, 105802, 0, 0, 2046);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "身体も鍛えなきゃ～！\nお腹がすいちゃいます\nけど…", 1, 105802, 0, 0, 2047);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐもぐもぐもぐ\nもぐもぐもぐもぐもぐ\nもぐもぐもぐもぐ…", 1, 105802, 0, 0, 2048);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "流行語発表…\nこんな言葉遣いが！\nやばいですね", 1, 105802, 0, 0, 2049);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "いろいろ美味しいもの\n食べられるし…\nけっこう幸せかも", 1, 106001, 0, 0, 2051);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "んーー、あたし\nなんで、このギルドに\n入っちゃったんだろ？", 1, 106001, 0, 0, 2052);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "あいつが来たら、\n尾行しなくちゃ♪", 1, 106001, 0, 0, 2053);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "この部屋のどこかに、\nあいつの秘密が\n隠されてるかも？", 1, 106001, 0, 0, 2054);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ま、まずいわ…\nギルド活動、\nけっこう楽しい♪", 1, 106001, 0, 0, 2055);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あいつを監視してる\nと…な、なんか\n変な気分", 1, 106001, 0, 0, 2056);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "主さま…\nだ、誰も聞いてない\nわよね！？", 1, 106001, 0, 0, 2057);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "気まぐれは\nチャームポイント\nみたいなもんよ", 1, 106001, 0, 0, 2058);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "うひゃっ！？\nど、どうしてあんたは\nいつも驚かせるのよ！", 1, 106001, 0, 0, 2059);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ぎゃー！\n虫もって近づくなー！", 1, 106001, 0, 0, 2060);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "この部屋って、\n野良猫を拾ってきたら\nだめかな？", 1, 106001, 0, 0, 2061);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "遊びにいくわよ！\nあんたはあたしの\n言うとおりにすれば\nいいの♪", 1, 106001, 0, 0, 2062);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あんた、あたしに\n操られてみない？", 1, 106001, 0, 0, 2063);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "美食殿としては、\n朝食もこだわらないと\nねぇ～", 1, 106001, 0, 1, 2064);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ギルド活動だもん！\n美味しいランチを\n食べましょ♪", 1, 106001, 0, 2, 2065);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ディナーに行くわよ！\nギルドの目的、\n食べ歩きだもんね♪", 1, 106001, 0, 3, 2066);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "今日もしっぽが\nいい感じ♪", 1, 106001, 0, 0, 2067);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "こういう所だと、\n丸くなっちゃうのよね\nうにゃぁ～～", 1, 106001, 0, 0, 2068);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "これ、あたしの能力で\n操れないかな？", 1, 106001, 0, 0, 2069);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "うにゃぁ～♪\nにゃん、にゃお～ん♪", 1, 106001, 0, 0, 2070);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "はぁ～ゴロゴロ\nしたくなるわね", 1, 106001, 0, 0, 2071);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "特訓特訓！\nあたしは\nやればできる！", 1, 106001, 0, 0, 2072);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいしいものを\nたくさん食べる…\nギルド活動って\n楽しい～♪", 1, 106001, 0, 0, 2073);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "魔法を使うにも、\n知識が必要だものね", 1, 106001, 0, 0, 2074);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ま、まずいわ…\nギルド活動\nけっこう楽しい♪", 1, 106002, 0, 0, 2076);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "いろいろ美味しいもの\n食べられるし…\nけっこう幸せかも", 1, 106002, 0, 0, 2077);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "主さま…\nだ、誰も聞いてない\nわよね！？", 1, 106002, 0, 0, 2078);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "監視監視…\nうん！　あたしは\nなまけてないわよね", 1, 106002, 0, 0, 2079);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "へ、陛下に\nみつからないように\nしなくっちゃ…", 1, 106002, 0, 0, 2080);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "あいつが来たら、\n尾行しなくちゃ♪", 1, 106002, 0, 0, 2081);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あいつと会ってから\n調子くるったな…\n楽しいけどさ", 1, 106002, 0, 0, 2082);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "食わず嫌いって\nあるのよね\n食べ物もだけど\n人も…", 1, 106002, 0, 0, 2083);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "うひゃっ！？\nど、どうしてあんたは\nいつも驚かせるのよ！", 1, 106002, 0, 0, 2084);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "話し相手になって\nやるわよ…情報\n聞き出せるかもだし", 1, 106002, 0, 0, 2085);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "この部屋って\n野良猫を拾ってきたら\nだめかな？", 1, 106002, 0, 0, 2086);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "遊びにいくわよ！\nあんたはあたしの\n言うとおりにすれば\nいいの♪", 1, 106002, 0, 0, 2087);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あんた、あたしに\n操られてみない？", 1, 106002, 0, 0, 2088);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "美食殿としては\n朝食もこだわらないと\nねぇ～", 1, 106002, 0, 1, 2089);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ギルド活動だもん！\n美味しいランチを\n食べましょ♪", 1, 106002, 0, 2, 2090);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ディナーに行くわよ！\nギルドの目的\n食べ歩きだもんね♪", 1, 106002, 0, 3, 2091);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "今日もしっぽが\nいい感じ♪", 1, 106002, 0, 0, 2092);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "うにゃ～\nどんどん眠く\nなる～", 1, 106002, 0, 0, 2093);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "これ、あたしの能力で\n操れないかな？", 1, 106002, 0, 0, 2094);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "あたし、みんなや\nあいつと同じ香りを\n身に着けてるんだ…", 1, 106002, 0, 0, 2095);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "うっ、のんびり\nしたくなる…\n特訓しなきゃ\nいけないのに～", 1, 106002, 0, 0, 2096);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "特訓特訓！\nあたしは\nやればできる！", 1, 106002, 0, 0, 2097);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいしいものを\nたくさん食べる…\nギルド活動って\n楽しい～♪", 1, 106002, 0, 0, 2098);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "魔法を使うにも\n知識が必要だものね", 1, 106002, 0, 0, 2099);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この空間は主さまの\n香りがします\n…ふふふ♪", 1, 105901, 0, 0, 2101);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "炊事、洗濯、お掃除、\nお買いものもしなくて\nはいけませんね", 1, 105901, 0, 0, 2102);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "アメスさまへの、\nお祈りができそうな\n場所は…", 1, 105901, 0, 0, 2103);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "さすが都会…\nおいしいものが\nたくさんあるのですね", 1, 105901, 0, 0, 2104);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "主さまが不自由なく\n使える部屋に\nしなくては…", 1, 105901, 0, 0, 2105);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "できるなら…\n主さまと二人だけの\n部屋の方が…", 1, 105901, 0, 0, 2106);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "主さまの隣には\nわたくしが…\nわたくしの隣には、\n主さまが…幸せです", 1, 105901, 0, 0, 2107);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "わたくし、背が伸び\nましたでしょうか？\n…そうですか", 1, 105901, 0, 0, 2108);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "もしお疲れでしたら\n肩でも\nお揉みしましょうか？", 1, 105901, 0, 0, 2109);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "主さま、なにか\nしてほしいことは\nありませんか？\n欲しいものは？", 1, 105901, 0, 0, 2110);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "今日のおこづかいです\n何かおいしいものを\n召し上がってください", 1, 105901, 0, 0, 2111);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "主さまのおてて\n温かいですね…♪", 1, 105901, 0, 0, 2112);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "主さまのおそばに\nいられて、わたくし、\n嬉しいです…", 1, 105901, 0, 0, 2113);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます。\n洗濯をしなければ…", 1, 105901, 0, 1, 2114);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "そろそろお昼ですね。\nおいしいものを\n食べましょう", 1, 105901, 0, 2, 2115);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おやすみになる時は、\nお声をかけてください\nお供致します", 1, 105901, 0, 3, 2116);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "もう少し…\nおっきくなりたい\nです", 1, 105901, 0, 0, 2117);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "このふかふかの優しさ\n主さまのようです", 1, 105901, 0, 0, 2118);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい♪\n主さまにそっくり♪", 1, 105901, 0, 0, 2119);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "故郷の香りとは\n違いますが、これも\n心地よいものです…", 1, 105901, 0, 0, 2120);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ここで洗濯物を\n乾かせるでしょうか", 1, 105901, 0, 0, 2121);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "都会の人々は\nこんなふうに\n運動を…！？", 1, 105901, 0, 0, 2122);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "これは…主さまにも\n食べさせて\n差し上げたい…\nあーんって♪", 1, 105901, 0, 0, 2123);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "よく学んで、\n主さまのお役に\n立たなければ", 1, 105901, 0, 0, 2124);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "主さまがいつ戻って\n来ても平気なよう\n部屋を綺麗に保たねば", 1, 105902, 0, 0, 2126);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "節約のためにも\n自家菜園などするのは\nどうでしょう…　", 1, 105902, 0, 0, 2127);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "アメスさまへの\nお祈りができそうな\n場所は…", 1, 105902, 0, 0, 2128);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "瞑想をすると\n心が安らぎます…", 1, 105902, 0, 0, 2129);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "都会の方の身なりを\n勉強した方が\n良いのでしょうか？", 1, 105902, 0, 0, 2130);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 1, "わたくしの居場所は\n主さまのお傍です\nずっと、ずっと…♪", 1, 105902, 0, 0, 2131);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "主さまの隣には\nわたくしが…\nわたくしの隣には\n主さまが…幸せです", 1, 105902, 0, 0, 2132);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "主さま、なにか\nしてほしいことは\nありませんか？\n欲しいものは？", 1, 105902, 0, 0, 2133);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "わたくし、背が伸び\nましたでしょうか？\n…そうですか", 1, 105902, 0, 0, 2134);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お出かけですか？\nわたくしもお供\nいたします", 1, 105902, 0, 0, 2135);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ひゃん！\n主さま…\nいじわるです", 1, 105902, 0, 0, 2136);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 101, 2, "主さま、なにか御用は\nありませんか？\nわたくし、主さまの\nお役にたちたいのです", 1, 105902, 0, 0, 2137);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "主さまの優しさに\nわたくしはいつも\n癒されています…", 1, 105902, 0, 0, 2138);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます♪\n主さまの可愛らしい\n寝顔、堪能致しました", 1, 105902, 0, 1, 2139);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "のんびりした時間帯\nですね…ふぁ～…\nし、失礼致しました", 1, 105902, 0, 2, 2140);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふむ、都会は夜でも\nこんなにも、にぎやか\nなのですね", 1, 105902, 0, 3, 2141);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "主さまに会う前に\n身なりを整えなくては\nいけませんね", 1, 105902, 0, 0, 2142);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "このふかふかの優しさ\n主さまのようです", 1, 105902, 0, 0, 2143);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい♪\n主さまにそっくり♪", 1, 105902, 0, 0, 2144);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この心地よさ…\n主さまのようです♪", 1, 105902, 0, 0, 2145);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ここで洗濯物を\n乾かせるでしょうか　", 1, 105902, 0, 0, 2146);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "はぁっはぁっはぁっ\n…すべては\n主さまのため…", 1, 105902, 0, 0, 2147);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "都会の味…\nとてもおいしいです\n…もぐもぐもぐ", 1, 105902, 0, 0, 2148);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "都会のことを\n学ばないと…\nふむふむ", 1, 105902, 0, 0, 2149);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふぁ～…あっ\n見られちゃい\nましたか？", 1, 190801, 0, 0, 2151);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ギルドハウスの\n使い心地は\nどうですか？", 1, 190801, 0, 0, 2152);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ご用があれば\nなんでも言って\nくださいね～♪", 1, 190801, 0, 0, 2153);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ときどきみなさんと\nクエストに行きたいな\nって思っちゃいます", 1, 190801, 0, 0, 2154);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます！\nお掃除の方、\nはじめていきますね", 1, 190801, 0, 1, 2155);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "皆さん、お昼ごはんの\nご要望がありましたら\n用意致しますよ♪", 1, 190801, 0, 2, 2156);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ここは夜でも\nにぎやかですね", 1, 190801, 0, 3, 2157);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "…\n少しうとうと\nしてしまった", 1, 104701, 0, 0, 2158);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "室内だし兜を脱ぐか\n…いや\nやはりやめておこう", 1, 104701, 0, 0, 2159);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "部屋にいると\n鎧が蒸し暑くなるが\n我慢せねば…", 1, 104701, 0, 0, 2160);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "仕事が門番だからか\n部屋にいても\nじっとしてしまう…", 1, 104701, 0, 0, 2161);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "少年と会話したことを\n思いだすと\n自然と楽しくなるな", 1, 104701, 0, 0, 2162);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "少年のことを考えると\n顔がにやけてしまう", 1, 104701, 0, 0, 2163);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "少年は今頃\n平和に過ごせて\nいるかな…", 1, 104701, 0, 0, 2164);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ん？　悪いが\n兜は脱がないぞ", 1, 104701, 0, 0, 2165);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "私と遊びたいのか？\nそう言われても\n何をしていいやら…", 1, 104701, 0, 0, 2166);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "鎧が重くないかって？\n大丈夫。けっこう\n鍛えているからな", 1, 104701, 0, 0, 2167);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "少年、寒くはないか？\nいや自分がこうなので\n人が薄着に見えてね", 1, 104701, 0, 0, 2168);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "君といると、兜の中が\nいつもより暑いんだ", 1, 104701, 0, 0, 2169);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "私としゃべりたい？\n物好きだな\nでも、嬉しいよ", 1, 104701, 0, 0, 2170);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "早いな少年\nえ？　私の仕事に\n合わせてくれたのか", 1, 104701, 0, 1, 2171);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼食の誘い？\n嬉しいけど\n人前では食べないんだ", 1, 104701, 0, 2, 2172);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "王宮騎士団の\n日報を書かなければ…\n『何事もなし』、と", 1, 104701, 0, 3, 2173);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "鎧を着ているから\n感触が分かりづらい\nのが残念だ…", 1, 104701, 0, 0, 2175);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "か、かわいいな…\n私には似合わないが\nぎゅ…ってしよう", 1, 104701, 0, 0, 2176);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "良い香りだ…\n普段はどうしても\n鉄くさくなるからな", 1, 104701, 0, 0, 2177);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "わかっていたけど\n鎧を着たまま暖炉に\nあたると暑い…", 1, 104701, 0, 0, 2178);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "兜を脱がずに食べる\nうん、段々コツが\n掴めてきた…", 1, 104701, 0, 0, 2180);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "兜があっても\n意外と本くらいは\n難なく読めるんだ", 1, 104701, 0, 0, 2181);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "居心地よくて\nゴロゴロしちゃうよ～\n…いつも通りだね", 1, 102601, 0, 0, 2183);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ドングリの木\n近くに生えてない？", 1, 102601, 0, 0, 2184);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "快適な寝床があれば\nそれだけで幸せだねぇ", 1, 102601, 0, 0, 2185);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "あたしと一緒に\nだらけてくれる人が\nいそうだねぇ", 1, 102601, 0, 0, 2186);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ここなら牧場よりも\n速く配達が\n届きそうだね～", 1, 102601, 0, 0, 2187);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あんパン買ったし\nあいつにも\n分けてあげよう", 1, 102601, 0, 0, 2188);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あいつと一緒に\nだらけられたら\n最高に幸せだね", 1, 102601, 0, 0, 2189);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ドングリでも\nつまみながら\n一緒にゲームしようよ", 1, 102601, 0, 0, 2190);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "横になりたいから\n枕になっておくれよ～\nあんたあったかいしさ", 1, 102601, 0, 0, 2191);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ドングリあげるから\nあんパン買ってきて～", 1, 102601, 0, 0, 2192);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "う～\n疲れちゃったよ～\nおんぶして運んで～", 1, 102601, 0, 0, 2193);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あんたといると\nリア充って\n感じがするよ", 1, 102601, 0, 0, 2194);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あんたが一生\n世話してくれたら\n人生安泰なんだけどね", 1, 102601, 0, 0, 2195);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふわ～っ…\nおはよう…あたしは\nまだ眠いよ", 1, 102601, 0, 1, 2196);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "そろそろお昼寝でも\nしたい気分だねぇ", 1, 102601, 0, 2, 2197);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "徹夜でゲームするけど\nあんたもどうだい？\nあたしは強いよ", 1, 102601, 0, 3, 2198);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "あ…だめだこれ。\n気持ち良くて\n落ちそう…", 1, 102601, 0, 0, 2200);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいものに\n囲まれて寝るのも\nよさそうだねぇ…", 1, 102601, 0, 0, 2201);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "心身ともに\nリラックスした状態で\nぐうたら出来そうだね", 1, 102601, 0, 0, 2202);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ふい～…\nごくらくごくらく…\n暖かいねぇ", 1, 102601, 0, 0, 2203);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食べてすぐ寝ると\n牛になるって\n本当なのかな？", 1, 102601, 0, 0, 2205);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "おー！　この本なら\nあたしも居眠りせずに\n読めそうだよ", 1, 102601, 0, 0, 2206);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ランドソル…\nおっきな街だなぁ…", 1, 106301, 0, 0, 2208);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ロザリア…\nきっと、いるよね？", 1, 106301, 0, 0, 2209);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "最近、弓の練習\nサボっちゃってるな…", 1, 106301, 0, 0, 2210);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "今日の私は\n森番じゃなくて\n家番だよ！", 1, 106301, 0, 0, 2211);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ちょっとだけ\n慣れてきたかも？", 1, 106301, 0, 0, 2212);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "いつか、\nあの人と一緒に…", 1, 106301, 0, 0, 2213);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "…なんか最近、\nあの人のこと\nばっかり…", 1, 106301, 0, 0, 2214);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "もしよかったら\n街に出かけない？", 1, 106301, 0, 0, 2215);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "この部屋、\n妖精さんも\n気に入るかも！", 1, 106301, 0, 0, 2216);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日は\nなににしよっか？", 1, 106301, 0, 0, 2217);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "今日はどこ行く？", 1, 106301, 0, 0, 2218);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "たまには二人で…\nな、なんちゃって！", 1, 106301, 0, 0, 2219);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "最近、\nずっと楽しいんだ！\nあなたのおかげかな", 1, 106301, 0, 0, 2220);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう！\n今日も一緒に\n頑張ろうね！", 1, 106301, 0, 1, 2221);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼はどうする？\nあなたのオススメに\n連れて行って欲しいな", 1, 106301, 0, 2, 2222);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ランドソルは\n夜でも賑やかだね！", 1, 106301, 0, 3, 2223);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "わぁっ！\nすっごく\nふわふわだよ！", 1, 106301, 0, 0, 2225);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわい～！\nぎゅってしたく\nなっちゃうかも！", 1, 106301, 0, 0, 2226);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "くんくん\nなんか…いい匂い？", 1, 106301, 0, 0, 2227);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "すっごいなー\nあったかいなー！", 1, 106301, 0, 0, 2228);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "わぁっ、おいしい！\nもっと食べたい\nかも…！", 1, 106301, 0, 0, 2230);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "も、文字は苦手…\nでも、頑張らないと\nだよね…！", 1, 106301, 0, 0, 2231);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "にんじんとピーマンを\n食べないでいい方法\nないかな…", 1, 103601, 0, 0, 2233);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "カップケーキが\n食べたいな…", 1, 103601, 0, 0, 2234);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "予習が終わりました！\nさて、次は復習を\nしないと…", 1, 103601, 0, 0, 2235);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "あの人の部屋にいる\n私って…もしかして\nふしんしゃなんじゃ？", 1, 103601, 0, 0, 2236);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "男の人は、みんな\nへんたいだと\n聞きました…", 1, 103601, 0, 0, 2237);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あの人に、一緒に\n遊んでほしいけど…\nな、なんていえば？", 1, 103601, 0, 0, 2238);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "早く大人になりたいな\n…あの人と同じくらい", 1, 103601, 0, 0, 2239);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ぼ、防犯魔石を\n鳴らしますよ！？", 1, 103601, 0, 0, 2240);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "へんたい！？　…\nあ、あなたでしたか～\nやっぱりへんたーい！", 1, 103601, 0, 0, 2241);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "これ宿題です\nやっておいて\nくださいね", 1, 103601, 0, 0, 2242);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あ、遅刻ですよ\n待っていたんですから", 1, 103601, 0, 0, 2243);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "にらめっこですか？\nあ、あなたの前で変顔\nするのはちょっと…", 1, 103601, 0, 0, 2244);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あの…何歳まで\n子供だと思いますか？", 1, 103601, 0, 0, 2245);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "顔を洗って、着替えて\n朝ごはんを食べて、\n歯を磨いて…", 1, 103601, 0, 1, 2246);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "て、鉄棒の練習！？　\nほ、他のことを\nしませんか？", 1, 103601, 0, 2, 2247);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ね、眠くないです\n子供ではありません\nから…ふわぁ", 1, 103601, 0, 3, 2248);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ひと休みしよっと\n………うん、\nひと休みおしまい♪", 1, 103601, 0, 0, 2250);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "つ、つぶらな瞳には\n弱いんです", 1, 103601, 0, 0, 2251);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "リラックスできますね\n集中力も\n上がりそうです", 1, 103601, 0, 0, 2252);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかいと\n眠くなっちゃうな…\n勉強しなくちゃなのに", 1, 103601, 0, 0, 2253);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ピーマンもこれくらい\nおいしければ\nいいのに…", 1, 103601, 0, 0, 2255);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "この本、むずかしい\n…もっと勉強\nがんばらなくちゃ", 1, 103601, 0, 0, 2256);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "今日はみんなに\nなにを読んで\nあげようかしら", 1, 101501, 0, 0, 2258);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "子どもたちと同じ\n目線で考えるのが\n大事よね", 1, 101501, 0, 0, 2259);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "お天気が良い日は\nみんなでお散歩に\n行きたいわね～", 1, 101501, 0, 0, 2260);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "鬼ごっこにかくれんぼ\n…みんなは\nどっちが好きかしら", 1, 101501, 0, 0, 2261);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "お遊戯会の配役、\n考え出すと\n大変だわ～", 1, 101501, 0, 0, 2262);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "彼は優しいから、\nきっと良い\nお父さんになるわね", 1, 101501, 0, 0, 2263);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "彼には私がいないと\n…っていうのは少し\n過保護すぎるかしら？", 1, 101501, 0, 0, 2264);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "保育園の行事を\n考えてるんだけど…\n良い案ないかしら？", 1, 101501, 0, 0, 2265);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今度、子どもたちと\nおやつを作るから、\n食べに来てね", 1, 101501, 0, 0, 2266);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "よかったら一緒に\n絵本を作らない？", 1, 101501, 0, 0, 2267);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あなたはいつも元気ね\n先生も見習わないと♪", 1, 101501, 0, 0, 2268);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "先生は\nずーっと、ずーっと、\nあなたの味方だからね", 1, 101501, 0, 0, 2269);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あなたみたいな\nいい子をお世話できて\n先生は幸せものだわ", 1, 101501, 0, 0, 2270);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう～\nちゃんと朝ごはんは\n食べた？", 1, 101501, 0, 1, 2271);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼寝の時間ね♪\nあなたも一緒に\n寝ましょうか", 1, 101501, 0, 2, 2272);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "すっかり真っ暗ね。\n今日も一日、\nよくできました♪", 1, 101501, 0, 3, 2273);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふかふかねぇ♪\n年甲斐もなく、\n飛び跳ねちゃいそう", 1, 101501, 0, 0, 2275);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "あらあら、かわいい！\n保育園のみんなに\n見せてあげたいわ", 1, 101501, 0, 0, 2276);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りね～\n保育園にも\n置こうかしら", 1, 101501, 0, 0, 2277);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "寒い日は、ここで\n子どもたちに絵本を\n読んであげましょ♪", 1, 101501, 0, 0, 2278);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "美味しい～♪\n遠足に持っていったら\nみんな喜びそう", 1, 101501, 0, 0, 2280);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "みんなが\n楽しめる読み聞かせの\n方法特集♪　素敵ねぇ", 1, 101501, 0, 0, 2281);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "世界の前に、\nこの部屋を征服\nしてやろう♪", 1, 104401, 0, 0, 2283);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "拠点とはやはり\n斯くあるべきじゃの", 1, 104401, 0, 0, 2284);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "眷属の物はわらわの物\n故に、この部屋は\nわらわの部屋じゃな！", 1, 104401, 0, 0, 2285);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "永く眠っている間に\n随分と世界は変わった\nようじゃな…", 1, 104401, 0, 0, 2286);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "うるさいのう～\nまったく、近頃の\n若いもんは…", 1, 104401, 0, 0, 2287);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あやつが来てから\n動悸が治まらぬ…\n如何ような病で\nあろうかの…", 1, 104401, 0, 0, 2288);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "眷属よ、どこに行った\nのじゃ？\nわらわの世話を\n許可するのじゃ", 1, 104401, 0, 0, 2289);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "いずれ世界は\n我が手中に収まる\nふふふ、\n楽しみじゃのう", 1, 104401, 0, 0, 2290);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "眷属よ、わらわから\n離れてはならんぞ！\n子供に戻ってしまう\nではないか！", 1, 104401, 0, 0, 2291);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "トマトジュースが\n欲しいのじゃ！\n野菜ジュースでは\nダメだぞ！", 1, 104401, 0, 0, 2292);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "蚊にくわれたぞ！\nわらわの血を吸う\nとは～！", 1, 104401, 0, 0, 2293);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "こら、頭をなでるな\nお主はこの姿でも\n子供扱いするのか？", 1, 104401, 0, 0, 2294);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お主が望むなら世界の\n半分をくれてやっても\n良いのじゃぞ？", 1, 104401, 0, 0, 2295);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝早くから感心じゃの\nさすがわらわの\n眷属じゃ", 1, 104401, 0, 1, 2296);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "太陽は苦手じゃ…\nこの部屋の中で\n過ごそうぞ", 1, 104401, 0, 2, 2297);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜も更けてきた！\nわらわ達の時間は\nこれからじゃ～♪", 1, 104401, 0, 3, 2298);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "よい座り心地じゃ\nわらわの玉座としよう", 1, 104401, 0, 0, 2300);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "可愛いではないか\nわらわの眷属に\nしてやろうかのう", 1, 104401, 0, 0, 2301);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "うむ、良い気持ちじゃ\nこれを作った者、\n褒めてつかわすぞ", 1, 104401, 0, 0, 2302);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あたたかい…\n身も心も\n浄化されるようじゃ", 1, 104401, 0, 0, 2303);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "吸血鬼のわらわが、\nこのようなもの…\nうまい♪", 1, 104401, 0, 0, 2305);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "このまま大人の姿を\n保つ方法…どこかに\n書いてないかのう", 1, 104401, 0, 0, 2306);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "いろんな人がいて\nいろんな服を着てて…\n目の保養になります♪", 1, 105401, 0, 0, 2308);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "レイ様への新作\nどんな服にしよう…\n方向性が絞れない～！", 1, 105401, 0, 0, 2309);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "忘れないうちに\n隠し糸のメンテナンス\nやっておこうっと！", 1, 105401, 0, 0, 2310);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "むっ！　あの人の\nスリーサイズは…\nほほう…なるほど♪", 1, 105401, 0, 0, 2311);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ノゾミさんの\n衣装はああして\nチカさんのは…", 1, 105401, 0, 0, 2312);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "私がアイドル…\n…実感ないけど\n精一杯やってみよう", 1, 105401, 0, 0, 2313);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "まさか私が\nアイドルになるなんて\n思ってなかったです", 1, 105401, 0, 0, 2314);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "なんですかぁ？\n衣装作りで疲れて\n眠いんですぅ…", 1, 105401, 0, 0, 2315);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あーっ！　また\n服がほつれてる…\nしょうがないですね", 1, 105401, 0, 0, 2316);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "はっ！　ちょうど今\n新しいデザインが\n思い浮かびました！", 1, 105401, 0, 0, 2317);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "暇そうですね？\n時間あるなら仕事\n手伝ってください！", 1, 105401, 0, 0, 2318);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "どうしました？\n新しい服が\n欲しくなりましたか？", 1, 105401, 0, 0, 2319);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "騎士さんのおかげで\nカルミナでも\n頑張れてますよ！", 1, 105401, 0, 0, 2320);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます…\nなんで朝って毎日\nやってくるんでしょう", 1, 105401, 0, 1, 2321);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹空きましたね\n騎士さんはちゃんと\n御飯食べましたか？", 1, 105401, 0, 2, 2322);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜の方が\n作業が捗るのは\n私だけですかね？", 1, 105401, 0, 3, 2323);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "このふかふか具合\nいい素材を\n使ってますね", 1, 105401, 0, 0, 2325);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "小さくて可愛い♪\nそうだ！　レイ様の\nぬいぐるみを…！", 1, 105401, 0, 0, 2326);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "こういう時くらい\n何も考えずに\nリラックスしないと♪", 1, 105401, 0, 0, 2327);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "炎を使った服って\nカッコ良いかも…\nでも材料がな～…", 1, 105401, 0, 0, 2328);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "何をするにも\n食事は大切！\n体力が資本です！", 1, 105401, 0, 0, 2330);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "私もいつか\nデザインを\nまとめて本に…", 1, 105401, 0, 0, 2331);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "またお魚を\n捕りにいこうかな♪", 1, 107501, 0, 0, 2333);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "そろそろみんなも\nお腹が空くころ\nじゃないですか～？", 1, 107501, 0, 0, 2334);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ここなら、\n日焼けの心配は\nありませんね！", 1, 107501, 0, 0, 2335);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お刺身に焼き貝…\nお腹が魚介類を\n求めてますっ！", 1, 107501, 0, 0, 2336);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "泳ぐのも食べるのも\n大得意です！", 1, 107501, 0, 0, 2337);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あの人と二人で\n浜辺を散歩…\n素敵ですねぇ", 1, 107501, 0, 0, 2338);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あの人に水着を\n褒めてもらえたら、\nすごく嬉しいなぁ", 1, 107501, 0, 0, 2339);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "たまには釣りじゃなく\n一緒に素潜りでも\n行きませんか？", 1, 107501, 0, 0, 2340);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "男の子に水着を\n見られるのって\n少し緊張しちゃいます", 1, 107501, 0, 0, 2341);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ギルドハウスの\nみんなとも、\n海に行きたいですね！", 1, 107501, 0, 0, 2342);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あなたの水着、\n私が選んであげます！", 1, 107501, 0, 0, 2343);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "泳ぎの練習なら\n付き合いますよ！\n手取り足取り♪", 1, 107501, 0, 0, 2344);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "水着姿が好きなら\nいくらでも\n着てあげますよぉ♪", 1, 107501, 0, 0, 2345);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝の海も\n幻想的で\nいいですよねぇ～！", 1, 107501, 0, 1, 2346);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼はみんなで、\n海鮮バーベキューとか\nどうでしょう！", 1, 107501, 0, 2, 2347);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜の海は星が\nきれいですよ！\n見に行きましょう！", 1, 107501, 0, 3, 2348);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "泳ぎ疲れたので\nちょっと休憩です～", 1, 107501, 0, 0, 2350);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "あなたにも、\n可愛い水着を\n着せてあげたいです", 1, 107501, 0, 0, 2351);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "なんだか、\nリゾート気分です…", 1, 107501, 0, 0, 2352);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ふい～、泳ぎで冷えた\n身体を暖めましょう～", 1, 107501, 0, 0, 2353);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいひ～です～\nこれ、海水浴にも\n持っていきたいですね", 1, 107501, 0, 0, 2355);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "南国のフルーツ図鑑\n…じゅるり…", 1, 107501, 0, 0, 2356);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "わ～♪　おいしそ…\nか、かわいいですね～", 1, 107501, 0, 0, 2358);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "これくらい大きな貝…\n食べたいな～\n食べたいな～～", 1, 107501, 0, 0, 2359);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この格好で\n部屋をうろつくのは\n不思議な感じがします", 1, 107601, 0, 0, 2360);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "南国の果実を使って\n主さまにデザートを\nお作りしましょう", 1, 107601, 0, 0, 2361);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "せっかくの水着ですし\nこれから定期的に\n海水浴に行きたいです", 1, 107601, 0, 0, 2362);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "海の生き物も、\n森の生き物に負けず\n可愛かったです…", 1, 107601, 0, 0, 2363);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "クロールの練習なら、\n部屋でもできそうです", 1, 107601, 0, 0, 2364);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "主さまに、水着姿を\n褒めていただけた…\nえへへ♪", 1, 107601, 0, 0, 2365);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "水着で主さまの\nお世話をしたら、\n喜びますでしょうか…", 1, 107601, 0, 0, 2366);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お疲れでしたら\nわたくしの膝を\nお使いくださいね", 1, 107601, 0, 0, 2367);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "主さま、海の家で\nつかうおこづかいを\n渡しておきますね", 1, 107601, 0, 0, 2368);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "海の美しさは、\n森とはちがう\n魅力がありました", 1, 107601, 0, 0, 2369);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "この髪飾りですか？\n造花ですから\n水の中も平気です", 1, 107601, 0, 0, 2370);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "水着でくっついて\n眠ると、いつもより\n密着して暖かいです", 1, 107601, 0, 0, 2371);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "はじめての海が、\n主さまと一緒で\n幸せです♪", 1, 107601, 0, 0, 2372);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます。\n泳ぎに行く準備は\n万端です", 1, 107601, 0, 1, 2373);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "午後は泳ぐのをやめて\nスイカ割りなど\nいかがでしょう？", 1, 107601, 0, 2, 2374);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜も更けてきました…\n波の音を聞きながら\n少しお話しませんか？", 1, 107601, 0, 3, 2375);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "あぅ…この家具には、\n人をダメにする魔法が\nかけられています…", 1, 107601, 0, 0, 2377);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふふっ♪\nあなたも、海水浴に\n行きますか？", 1, 107601, 0, 0, 2378);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この香り…\nきっと主さまも\n気に入ります", 1, 107601, 0, 0, 2379);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "これは暖かいです…\n後ほど主さまと一緒に\nあたりましょう", 1, 107601, 0, 0, 2380);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "泳いだ後の食事は\n一段と美味しく\n感じます", 1, 107601, 0, 0, 2382);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "深海魚の生態…\nこれは主さまにも\nお伝えしなくては…", 1, 107601, 0, 0, 2383);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "顔立ちが、主さまに\n似ております…\nかわいらしい♪", 1, 107601, 0, 0, 2385);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "ふかふかですね\n主さまのようです♪", 1, 107601, 0, 0, 2386);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "お掃除、お掃除\nふんふふ～ん☆\nあ、聞かれてました？", 1, 107701, 0, 0, 2387);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "日焼けには回復魔法が\n効きますよ。どうして\n逃げるんですか～！", 1, 107701, 0, 0, 2388);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "今日はドジを\nしませんように！", 1, 107701, 0, 0, 2389);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "接客業を極めれば\nメイドとして\n成長できるかも？", 1, 107701, 0, 0, 2390);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "水着って\n動きやすいんですけど\n人の目が気になります", 1, 107701, 0, 0, 2391);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あの人の気持ちを知る\n魔法とかあれば…\nな、なんでもないです", 1, 107701, 0, 0, 2392);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "水着でご奉仕したら、\nあの人は喜ぶかな？", 1, 107701, 0, 0, 2393);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "暑いのでしたら、\n私が魔法で涼しく…\nえ？　いらない？", 1, 107701, 0, 0, 2394);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "何か御用ですか？\n特にないのでしたら、\nお話ししましょう♪", 1, 107701, 0, 0, 2395);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "水着姿でも\nメイドはメイドです\nご奉仕しますよ！", 1, 107701, 0, 0, 2396);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ひゃっ！　あ、危うく\n転ぶところでした…\n…きゃうっ！", 1, 107701, 0, 0, 2397);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "どうかしましたか？\nあなたの御用なら、\n喜んでお受けしますよ", 1, 107701, 0, 0, 2398);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "水着姿をあなたに\n見られると、\nドキドキしちゃいます", 1, 107701, 0, 0, 2399);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝は暑くてやる気が\n出ない？　でしたら、\nえぇい、元気になぁれ", 1, 107701, 0, 1, 2400);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹がぺこぺこなら、\nお昼は海の家で\n食べましょう♪", 1, 107701, 0, 2, 2401);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜の浜辺でお散歩も\nいいですね。たくさん\n転びそうですけど…", 1, 107701, 0, 3, 2402);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "休憩しながら、\nお掃除すれば\n一石二鳥です！", 1, 107701, 0, 0, 2404);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "きれいにすれば\nかわいさも倍増\nですよ～♪", 1, 107701, 0, 0, 2405);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "素敵な香りです～\n救護院に置けば、\nみんな喜ぶかも～", 1, 107701, 0, 0, 2406);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかいですね…\nはっ！　いけません！\nメイドがサボるなんて", 1, 107701, 0, 0, 2407);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "料理のできない\nメイドなんて…\nはぐはぐ、おいしい♪", 1, 107701, 0, 0, 2409);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "水着姿で接客をすると\n売り上げが倍になる\n…本当ですか、これ", 1, 107701, 0, 0, 2410);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "えへへ♪\n南の島まで\n乗せてください！", 1, 107701, 0, 0, 2412);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "なんだか、\n人魚姫に\nなった気分です♪", 1, 107701, 0, 0, 2413);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "みんなで過ごす\n休日っていいわよね…\nずっと続かないかな", 1, 107801, 0, 0, 2414);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "海に浮輪でぷかぷか\n浮かぶのって\n癖になりそう", 1, 107801, 0, 0, 2415);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ビーチにいると\n日焼けが心配だわ", 1, 107801, 0, 0, 2416);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "水着姿って楽よね。\n室内だとちょっと\n落ち着かないけど…", 1, 107801, 0, 0, 2417);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "お、泳ぎの練習なんて\nしないからね！", 1, 107801, 0, 0, 2418);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "楽しすぎて立場を\n忘れそう…あんたの\nせいなんだから！", 1, 107801, 0, 0, 2419);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "みんなで遊んで\n美味しいもの食べて\nほんっとに楽しいっ♪", 1, 107801, 0, 0, 2420);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "マジであっついわね…\nよっし！　海に入って\n涼みましょ！", 1, 107801, 0, 0, 2421);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "シャワー浴びたばかり\nなのに…また、遊び\nたくなってきたわ！", 1, 107801, 0, 0, 2422);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "遊び足りないって？\nしょうがないわね…\n付き合ってあげるわ♪", 1, 107801, 0, 0, 2423);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "一応伝えておくけど\n猫って水が苦手なの！\nわかった！？", 1, 107801, 0, 0, 2424);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あたしと話したいの？\nふふ。\nまぁ、いいわよ。\nほら隣に座りなさい", 1, 107801, 0, 0, 2425);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "こんなに楽しいの\n初めてかも…\nずっと続けばいいのに", 1, 107801, 0, 0, 2426);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "は、早起きしたのは、\n楽しみで眠れなかった\nからじゃないわよ！", 1, 107801, 0, 1, 2427);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼食後のストレッチ\n終わり！　さあ、\nビーチが待ってるわ！", 1, 107801, 0, 2, 2428);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜の海に散歩に\n行こうかな～\nあんたも来なさいよ☆", 1, 107801, 0, 3, 2429);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "海ではしゃぎすぎて\n疲れたわ…ちょっと\n休もうかしら？", 1, 107801, 0, 0, 2431);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "こんな魔物がいたら\n操るのも楽しいかも", 1, 107801, 0, 0, 2432);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "にゃう～♪\nまるで南国にいる\n気分ね♪", 1, 107801, 0, 0, 2433);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかぁい♪\n身体が冷えてきたから\n丁度いいわ！", 1, 107801, 0, 0, 2434);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "運動後のご飯って\nなんでこんなに\n美味しいんだろ♪", 1, 107801, 0, 0, 2436);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "どんなカナヅチでも、\n絶対必ず泳げる方法、\n書いてないかしら？", 1, 107801, 0, 0, 2437);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "あんたもあたしが\n操ってあげる！\nなんてね～♪", 1, 107801, 0, 0, 2439);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "リゾートリゾートっ\nのんびりしましょ♪", 1, 107801, 0, 0, 2440);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ここなら思う存分\nデスクワークに\n励めるわね！", 1, 108001, 0, 0, 2441);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "武器のメンテナンスも\nしっかりしないと\n最高効率は望めないわ", 1, 108001, 0, 0, 2442);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "準備をしっかり整えて\nもっともっと\n稼がなくちゃね！", 1, 108001, 0, 0, 2443);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "少し休んだら\n次のバイトに\n行ってくるわね！", 1, 108001, 0, 0, 2444);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "この格好でここに\nいるのって\n気恥ずかしいわね…", 1, 108001, 0, 0, 2445);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "キミが望むなら\n今日のバイト\n休んでもいいわよ？", 1, 108001, 0, 0, 2446);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "キミだけね…\n私のことをここまで\n理解してくれるのは", 1, 108001, 0, 0, 2447);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "普段と違う格好\nだからって\nそんなに見ないでよ…", 1, 108001, 0, 0, 2448);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "キミを立派な\nバイト戦士にするのが\n師匠としての役目よね", 1, 108001, 0, 0, 2449);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ次のバイトに\n行かないと…\nキミも一緒に来る？", 1, 108001, 0, 0, 2450);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "効率は大事だけど\nゆっくりするのも\n悪くないわね", 1, 108001, 0, 0, 2451);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "一緒の時間が楽しくて\nバイトのことを\n忘れちゃいそうね", 1, 108001, 0, 0, 2452);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "キミと一緒なら\nどんなミッションも\n楽勝ね！", 1, 108001, 0, 0, 2453);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう、いい朝ね！\n今日もめいっぱい\n稼ぐわよ！", 1, 108001, 0, 1, 2454);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "もうお昼だったのね…\n内職のバイトに\n集中しすぎちゃったわ", 1, 108001, 0, 2, 2455);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "スケジュールは、と…\nこういう管理の徹底が\n効率を生み出すのよ♪", 1, 108001, 0, 3, 2456);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "しっかり働いて休む…\n最高効率にまた一歩\n近づいたわね", 1, 108001, 0, 0, 2458);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "なごんじゃうわね…\nよぉし、次のバイトも\n頑張らないと！", 1, 108001, 0, 0, 2459);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りね…\n働く意欲が\n湧いてくるわ", 1, 108001, 0, 0, 2460);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "身体が冷えたから\n助かるわ…冷えは\n女の天敵だもの", 1, 108001, 0, 0, 2461);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "海のバイトは\n体力勝負よ\nエネルギーはしっかり\n摂取しないとね！", 1, 108001, 0, 0, 2463);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "座学も大切ね\nもっと知識を\n身につけないと…", 1, 108001, 0, 0, 2464);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "海の楽園みたいね…\n今だけは効率を\n忘れちゃいそう…", 1, 108001, 0, 0, 2466);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "落ち着くわ…\n海とひとつになった\n気分ね！", 1, 108001, 0, 0, 2467);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ちょっと休憩にゃ～\n潮風は体に\n良くないにゃ～", 1, 107901, 0, 0, 2468);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "猫グッズで\n海の家を飾りたいにゃ", 1, 107901, 0, 0, 2469);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "海の幸は美味しいけど\n水はイヤだにゃ…", 1, 107901, 0, 0, 2470);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "開店にゃ！\nこのたい焼きなら\nきっと大繁盛にゃ！", 1, 107901, 0, 0, 2471);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "海と言えば水着にゃ\n似合ってるかにゃ？", 1, 107901, 0, 0, 2472);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "キミが頼むなら\n手伝ってあげても\nいいにゃ", 1, 107901, 0, 0, 2473);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あたしの宝は\nここにあるにゃ～", 1, 107901, 0, 0, 2474);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "にゃ？\nそんなに見つめても\n何も出ないにゃ", 1, 107901, 0, 0, 2475);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今からキミを\nあたしの相棒に\n任命するにゃ！", 1, 107901, 0, 0, 2476);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "これから\n開店の準備にゃ\nキミも手伝って\nくれるのかにゃ？", 1, 107901, 0, 0, 2477);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "海の家で出す\n新しいメニューを\n考え中なのにゃ～", 1, 107901, 0, 0, 2478);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "キミと一緒なら\n売上げナンバーワンに\nなれるにゃ！", 1, 107901, 0, 0, 2479);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "キミと一緒にいると\n楽しくて、もっと\nいたくなるにゃ", 1, 107901, 0, 0, 2480);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようにゃ！\n今日も頑張って\nいくにゃー！", 1, 107901, 0, 1, 2481);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹すいたにゃ～…\nお魚、ちょっとだけ、\nつまみ食いするにゃ", 1, 107901, 0, 2, 2482);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "明日の準備は万端にゃ\nいつでも\n出発できるにゃ", 1, 107901, 0, 3, 2483);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "このふかふか具合\nまるで子猫の\n毛並みのようにゃ～", 1, 107901, 0, 0, 2485);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "にゃにゃ～\nなんてかわいさにゃ～", 1, 107901, 0, 0, 2486);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この匂い…\nもう少し香ばしいと\nいいかもしれないにゃ", 1, 107901, 0, 0, 2487);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "にゃ～…\nあったかくて\nぬくぬくだにゃ～", 1, 107901, 0, 0, 2488);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "働くにはまず体力にゃ\nしっかり食べて\nスタミナアップ\nだにゃ!", 1, 107901, 0, 0, 2490);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ…\nここにお宝が\n眠ってるんだにゃ", 1, 107901, 0, 0, 2491);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "シードレイクにゃ！\n本物は怖かったけど、\nぬいぐるみなら\nかわいいにゃ～", 1, 107901, 0, 0, 2493);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "貝なのにふかふかの\nクッションにゃ！\n屋台の前にも\n置いてみたいにゃあ", 1, 107901, 0, 0, 2494);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "人の家って、道場とは\n違った香りがするね", 1, 103701, 0, 0, 2495);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ちょっと退屈だね…\nあの人をからかいに\n行こうかな♪", 1, 103701, 0, 0, 2496);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "普通の女の子みたいに\n遊びたいって思う\nこともあるんだよね", 1, 103701, 0, 0, 2497);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "剣の手入れを怠らない\nようにしないと。\nいざという時、困るし", 1, 103701, 0, 0, 2498);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "もっと\n上手く立ち回って\n出世したいな", 1, 103701, 0, 0, 2499);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "おかえりなさい！\nふふ、なんだか奥さん\nになった気分だよ♪", 1, 103701, 0, 0, 2500);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "恥ずかしくて、あなた\nを見られないよ…\n私らしくないなぁ…", 1, 103701, 0, 0, 2501);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "私、お話好きなんだ。\nどうせなら楽しい話を\nしたいな♪", 1, 103701, 0, 0, 2502);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "女の子っぽい子と、\n男勝りな子、あなたは\nどっちが好き？", 1, 103701, 0, 0, 2503);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ見回りの\n時間かな。あなたも\n一緒に行く？", 1, 103701, 0, 0, 2504);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "構って欲しいのかな？\nそれじゃ一緒に\nランニングに行こうか", 1, 103701, 0, 0, 2505);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "二人で出かけるなら、\n手を繋がないとね。\nあはは、冗談冗談♪", 1, 103701, 0, 0, 2506);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ねえ、あなた♪\nおや、顔が真っ赤だ！\n…ふふ、私も、かな？", 1, 103701, 0, 0, 2507);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "私は朝から鍛錬だよ。\n慣れてるけど大変だ。\nお互いに頑張ろうね", 1, 103701, 0, 1, 2508);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "鍛錬でお腹ぺこぺこ。\nお昼ごはんが\n楽しみだね", 1, 103701, 0, 2, 2509);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日も一日見回りと\n鍛錬を頑張ったよ。\nあなたもお疲れさま", 1, 103701, 0, 3, 2510);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "いざという時のため\nにも、休憩は大事だね", 1, 103701, 0, 0, 2512);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "こういうものには\n今まで\n縁がなかったけど。\nうん、可愛いね♪", 1, 103701, 0, 0, 2513);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "精神統一に通じる\nものがあるね。\nふぅ、癒されるなぁ", 1, 103701, 0, 0, 2514);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかいなぁ。\nたまにはのんびり\nしようか", 1, 103701, 0, 0, 2515);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "鍛錬後はすごくお腹が\n空くんだよね。\nう～ん、おいしい♪", 1, 103701, 0, 0, 2517);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "剣術書だけで強くなる\nには飛びぬけた才能と\n努力が必要だよね", 1, 103701, 0, 0, 2518);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "正義の刃で\n悪を挫く！\n…キマったッス♪", 1, 100501, 0, 0, 2520);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ヒーローの\n秘密特訓を\n始めるッスよ～！", 1, 100501, 0, 0, 2521);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "正義の味方目指して\n今日も明日も\n全力ッスよ♪", 1, 100501, 0, 0, 2522);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "一日一善！\nヒーローだったら\n当たり前ッス♪", 1, 100501, 0, 0, 2523);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "どうッスか\nこのポーズ！\nイイ感じッスか？", 1, 100501, 0, 0, 2524);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "た、たまには\nよく頑張ったねって\n褒めてほしいッス…", 1, 100501, 0, 0, 2525);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "自分を信じてくれる\nあんたと一緒なら\n何でもやれるッス！", 1, 100501, 0, 0, 2526);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おつかれッス♪\n冒険の準備は\nばっちりッスよ！", 1, 100501, 0, 0, 2527);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "どうしたんッスか？\n…はっ！　もしや敵が\n迫ってるんスかっ！？", 1, 100501, 0, 0, 2528);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "べ、別に\n頭を撫でてほしいとか\n思ってないッスよ？", 1, 100501, 0, 0, 2529);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "スーパーヒーロー\nトラタイガーは\n絶対無敵ッス！", 1, 100501, 0, 0, 2530);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あんたと自分で\n正義の心を燃やして\n悪を一網打尽ッス！", 1, 100501, 0, 0, 2531);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あんたと一緒だと\n幸せな気持ちに\nなるんッス…♪", 1, 100501, 0, 0, 2532);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お、早いッスね～♪\n今日も一日一善\nよろしくッス！", 1, 100501, 0, 1, 2533);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "一休みしながら\nヒーローについて\n語り合うッスよ～！", 1, 100501, 0, 2, 2534);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜のパトロールで\n一緒に平和を\n守るッス！", 1, 100501, 0, 3, 2535);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふぅぅ…\n落ち着くッスね\n戦士の休息ッス♪", 1, 100501, 0, 0, 2537);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "くぅぅ、可愛いッス…\nヒーローが守るべき\n愛らしさッスね！", 1, 100501, 0, 0, 2538);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "なんスかこの香り？\nすぅぅ…ふぅぅ…\n力がみなぎるッス！", 1, 100501, 0, 0, 2539);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "優しい光ッスね…\nヒーローの優しさ\nそのものッス！", 1, 100501, 0, 0, 2540);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "あむあむあむ…\nんぅう、元気が溢れて\n止まらないッス！", 1, 100501, 0, 0, 2542);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "トラタイガーのお話は\n笑いあり涙ありで\n超おすすめッス！", 1, 100501, 0, 0, 2543);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ハッピーハロウィン\nお父さん、お菓子は…\n食べられないね", 1, 108101, 0, 0, 2545);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "トリックオアトリート\nお菓子をくれないと\n不吉な占いをします", 1, 108101, 0, 0, 2546);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ふふ、あなたの後ろで\n霊のみなさんが\n踊り始めました", 1, 108101, 0, 0, 2547);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "霊感がいつも以上に\n冴えているので\n占いの調子も良好です", 1, 108101, 0, 0, 2548);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "父はハロウィンが\n大好きだそうです\n大胆な格好をする子が\n多いので…", 1, 108101, 0, 0, 2549);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あなたは霊たちにも\n大人気ですよね\n私も見てほしいな…", 1, 108101, 0, 0, 2550);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ハロウィンの賑やかさ\n今は好きです…\nあなたといられるので", 1, 108101, 0, 0, 2551);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "霊のみなさんとの\nダンスパーティー…\n楽しみです", 1, 108101, 0, 0, 2552);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お父さん、元気だね\nえ？　ここは色んな\n女の子に会えて幸せ？", 1, 108101, 0, 0, 2553);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ハロウィンのお菓子\n食べすぎちゃったな…\nでも、美味しかった…", 1, 108101, 0, 0, 2554);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あなたの女難の相…\n悪化していますね\nお祓いが必要かも", 1, 108101, 0, 0, 2555);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あの、霊のみなさんが\nあなたと踊りたいと…\nえっと、私も…", 1, 108101, 0, 0, 2556);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あなたと手を繋ぐと\n胸が苦しくなります\nでも、繋ぎたいな…", 1, 108101, 0, 0, 2557);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ハッピーハロウィン…\n父が元気なので\n今日の運気は良好です", 1, 108101, 0, 1, 2558);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "父はお昼寝中です\n本当に寝ているかは\n私にも分かりませんが", 1, 108101, 0, 2, 2559);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お父さん、\nもう眠っちゃったの？\n…眠れるんだったっけ", 1, 108101, 0, 3, 2560);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "落ち着きますね…\n霊のみなさんも\n喜んでいます", 1, 108101, 0, 0, 2562);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "つん、つん。ふふっ♪\n癒やされます…", 1, 108101, 0, 0, 2563);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "精神が研ぎ澄まされる\n香りですね…\n占いが捗ります", 1, 108101, 0, 0, 2564);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかいね\nお父さん…\nえ？　分からない？", 1, 108101, 0, 0, 2565);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "霊のみなさんは\n食べられないので…\n私がいただきます", 1, 108101, 0, 0, 2567);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "お父さんを元に戻す\n手掛かり…\n書かれていないかな？", 1, 108101, 0, 0, 2568);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 12, 3, "わぁ、お菓子が沢山…", 1, 108101, 0, 0, 2570);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "無料でプリンが\nもらえるなんて、\nハロウィンはすごいの", 1, 108201, 0, 0, 2572);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "生きてるときも、\nミヤコはハロウィンが\n好きだった気がするの", 1, 108201, 0, 0, 2573);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "みんなに仮装を\n見せつけて、\nプリンをもらうの～", 1, 108201, 0, 0, 2574);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "この仮装で、\nみんなに恐怖を\n教えてやるの！", 1, 108201, 0, 0, 2575);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "アオーン、アオーン！\nミヤコ、狼女に\nなりきってるの～", 1, 108201, 0, 0, 2576);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "アイツに秘密で、\nパーティーの\n飾り付けをするの♪", 1, 108201, 0, 0, 2577);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "アイツが狼男の\n仮装をすれば、\nおそろいなの～", 1, 108201, 0, 0, 2578);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "プリンをくれなきゃ、\nオマエをカボチャに\nしてやるの～", 1, 108201, 0, 0, 2579);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ハロウィンは幽霊でも\n参加できるから\n楽しいの～！", 1, 108201, 0, 0, 2580);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "プリンがないなら\nカボチャプリンを\n食べればいいの！", 1, 108201, 0, 0, 2581);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "プリンの可能性は\n無限大なの～", 1, 108201, 0, 0, 2582);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "オマエの隣で\nプリンを食べると、\nいつもより美味しいの", 1, 108201, 0, 0, 2583);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "オマエが死んでも、\nミヤコはずーっと\n一緒にいてやるの～", 1, 108201, 0, 0, 2584);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝ごはんは\nカボチャプリンなの！\nハロウィンっぽいの～", 1, 108201, 0, 1, 2585);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ランチは豪華に\nプリンアラモードなの", 1, 108201, 0, 2, 2586);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜は幽霊たちと\nハロウィンするの！\nオマエも来るの！", 1, 108201, 0, 3, 2587);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "幽霊にも休息は\n必要なの！\nプリンもってこいなの", 1, 108201, 0, 0, 2589);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "オマエもミヤコの\nパーティーに\n招待してあげるの～", 1, 108201, 0, 0, 2590);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "癒されるの～\nまるで天国なの～", 1, 108201, 0, 0, 2591);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ここでなら、\n焼きプリンが\n作れるの！", 1, 108201, 0, 0, 2592);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "腹が減っては\nハロウィンは\nできぬなの！", 1, 108201, 0, 0, 2594);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "丸ごとカボチャ\nプリン特集！？\n美味しそうなの～♪", 1, 108201, 0, 0, 2595);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 12, 3, "お菓子がたくさんで、\nミヤコはとっても\nハッピーなの♪", 1, 108201, 0, 0, 2597);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "魔女以外にも、\n色々な仮装を\nしてみたいわね", 1, 108301, 0, 0, 2599);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "チョコやアメよりも、\nアタシに相応しい\nスイーツがあるはず…", 1, 108301, 0, 0, 2600);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "お菓子の食べ過ぎは、\nお母さんに\n怒られるかも…", 1, 108301, 0, 0, 2601);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "この格好で学院に\n行ったら、\nみんな驚くかしら", 1, 108301, 0, 0, 2602);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "大人のレディは、\nどういうハロウィンを\n過ごすべきかしら…？", 1, 108301, 0, 0, 2603);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お菓子、アイツの分も\nとっといてあげよ！\n大人の余裕ってやつね", 1, 108301, 0, 0, 2604);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "アイツを魅了する\n魔法とかないかしら？", 1, 108301, 0, 0, 2605);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おしゃれスイーツを\nくれなきゃ\nイタズラするわよ！", 1, 108301, 0, 0, 2606);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "アタシの大人センスで\nアンタに似合う仮装を\n選んであげるわ！", 1, 108301, 0, 0, 2607);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "不気味よねぇ…\nジャックオーランタン\nこ、怖くないわよ？", 1, 108301, 0, 0, 2608);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ハロウィンが楽しくて\n宿題やり忘れてたわ…\nて、手伝って～！", 1, 108301, 0, 0, 2609);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お菓子をもらうのも\nアンタと一緒なら\n恥ずかしくないわ！", 1, 108301, 0, 0, 2610);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "アタシのエスコートを\n任せられるのは、\nアンタだけなんだから", 1, 108301, 0, 0, 2611);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝食はオシャレに\nグリーンスムージー！\n…に、にがぁ", 1, 108301, 0, 1, 2612);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼下がりはカフェで\n優雅なティータイム\n…憧れるわ～", 1, 108301, 0, 2, 2613);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ハロウィンナイトの\nはじまりよ！\n街に繰り出しましょ！", 1, 108301, 0, 3, 2614);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "あう～、お菓子の\n食べすぎで\n動けな～い", 1, 108301, 0, 0, 2616);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "アンタも仮装する？\nいまよりもーっと\nかわいくなるわよ！", 1, 108301, 0, 0, 2617);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "大人な香りに\n包まれてる～♪", 1, 108301, 0, 0, 2618);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ポカポカね～♪\n…ああー！\nチョコが溶けてる！", 1, 108301, 0, 0, 2619);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいしい～♪\n…じゃなくて！\nび、美味ですわ～", 1, 108301, 0, 0, 2621);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "この服かわい～♪\nって、なにこの値段！\nお小遣い何年分よ！？", 1, 108301, 0, 0, 2622);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 12, 3, "お、お菓子なんかで\n喜ぶほど、子供じゃ…", 1, 108301, 0, 0, 2624);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "次はどんな策で団長を\nからかってみようか…", 1, 107101, 0, 0, 2626);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "む？\n血の臭いがするな\n祭りの時間か☆", 1, 107101, 0, 0, 2627);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "平和に飼い殺される\n前に、混沌の愛を\n育みたいね", 1, 107101, 0, 0, 2628);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "本気を出した団長と\nいつか手加減なしに\n殺り合いたいな", 1, 107101, 0, 0, 2629);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "おばさん呼ばわりする\n新米騎士の小娘を\n懲らしめてやろうか", 1, 107101, 0, 0, 2630);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "胸を触られるまで\n誓約のことなど\nすっかり忘れていたな", 1, 107101, 0, 0, 2631);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "まさかこのワタシが\nプロポーズするとはな\n…笑えるじゃないか", 1, 107101, 0, 0, 2632);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "面白い暇つぶしを\n思いついたんだ\n戯れに付き合え☆", 1, 107101, 0, 0, 2633);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "退屈で死にそうだ\n愉しい話題を\nワタシに提供してくれ", 1, 107101, 0, 0, 2634);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "なんだ、暇なのか？\n心躍ることでも探しに\n出かけようではないか", 1, 107101, 0, 0, 2635);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "このワタシを愉快に\nさせてくれる事でも\nあったのか？", 1, 107101, 0, 0, 2636);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ワタシに求婚した男の\n数だと？\nいちいち覚えてないな", 1, 107101, 0, 0, 2637);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "最強無敵の女と\n結婚できるんだ\n誇りに思えよ☆", 1, 107101, 0, 0, 2638);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "なにか愉快なことが\n起こりそうな朝だ☆\nワクワクするね", 1, 107101, 0, 1, 2639);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "うーむ、腹がすいたな\n愉快なことで\nこの空腹を満たしたい", 1, 107101, 0, 2, 2640);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "これからは大人の\n時間だ。愉しみ方を\n知りたいのかい？", 1, 107101, 0, 3, 2641);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "このワタシとした事が\n穏やかな気分に\nなってしまうとは…", 1, 107101, 0, 0, 2643);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "可愛い姿をしたものが\n惨たらしい\n醜態を晒すのを\n想像してしまう", 1, 107101, 0, 0, 2644);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "悪くはない香りだ\nだが、ワタシは血の\n臭いを嗅ぎたいぞ☆", 1, 107101, 0, 0, 2645);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ぬるい、ぬるすぎる！\n地獄の業火には\nほど遠い熱さだ！", 1, 107101, 0, 0, 2646);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ワタシの腕前に\n勝るとも劣らない\nなかなかの味だ", 1, 107101, 0, 0, 2648);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "意中の男性を絶対に\n落とす方法…？\nく、下らんっ！", 1, 107101, 0, 0, 2649);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "明日はあの釣り場に\n行くとしようかな\nあの子も誘ってみるか", 1, 105601, 0, 0, 2651);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ぷはーっ！\n体を動かしたあとの\n一杯は格別だね", 1, 105601, 0, 0, 2652);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "天気が良いと\n昼寝か釣りかで\n迷っちまうな…", 1, 105601, 0, 0, 2653);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "大物が釣れたときの\n快感は、他じゃ\n味わえないね", 1, 105601, 0, 0, 2654);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ふあぁ～…\n昼寝でもするか", 1, 105601, 0, 0, 2655);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ふふっ…\nあの子、見た目より\n根性あるんだね", 1, 105601, 0, 0, 2656);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あの子が強くなるには\nどんな魚を食べさせて\nあげればいいのやら…", 1, 105601, 0, 0, 2657);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "姉御って呼ぶんじゃ\nないよ。からかうと\nタダじゃおかないよ", 1, 105601, 0, 0, 2658);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "釣りのコツ？\n何事も経験が大事だ\n今から行くかい？", 1, 105601, 0, 0, 2659);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "どうしたのさ？\n助太刀が必要かい？\nアタシにまかせときな", 1, 105601, 0, 0, 2660);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "困ってる人がいたら\nまた力を貸しておくれ\n頼りにしてるよ", 1, 105601, 0, 0, 2661);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "なにか困りごとかい？\nどうやら昼寝は\nまた今度だね", 1, 105601, 0, 0, 2662);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "よしよし！\nお人好しのお前さんを\n労ってあげるよ", 1, 105601, 0, 0, 2663);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう、お前さん\n魚屋は早起きでなきゃ\nつとまらないよ？", 1, 105601, 0, 1, 2664);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼飯かい？　今朝\n仕入れた魚があるんだ\n食べてみるかい？", 1, 105601, 0, 2, 2665);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜釣りにぴったりの\n月が出てるよ\nいい釣りが出来そうだ", 1, 105601, 0, 3, 2666);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "コイツに座って\nのんびり釣りが\nできりゃいいのにな", 1, 105601, 0, 0, 2668);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "よしよし…♪\nおっと、かわいい物も\nつい抱きしめちまうな", 1, 105601, 0, 0, 2669);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "これで魚の臭いを\n消せれば、猫も\n寄らなくなるのかね", 1, 105601, 0, 0, 2670);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "冬場の釣りも\nこれくらい暖かけりゃ\nいいんだけどね", 1, 105601, 0, 0, 2671);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "腹が減っては\n釣りもできぬ、ってな\nまずは腹ごしらえだ", 1, 105601, 0, 0, 2673);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "へぇ…こんな魚が\nいたとは…いつか\n釣りたいもんだね", 1, 105601, 0, 0, 2674);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "流石に室内で\n魔法ぶっぱしたら\n怒られるよねぇ", 1, 101301, 0, 0, 2676);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "可愛い女の子が\nたくさんいる！\nここは楽園か！？", 1, 101301, 0, 0, 2677);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "みんなに漫画とか\n勧めてみようかな！\n布教用のがあるし！", 1, 101301, 0, 0, 2678);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "わ、私一人の\n部屋じゃないから\n色々自重せねば！", 1, 101301, 0, 0, 2679);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "「ぬるぽ」\n…くっ、\n誰も反応なしか！", 1, 101301, 0, 0, 2680);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "次はどの漫画を\n貸そうかなー♪", 1, 101301, 0, 0, 2681);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "次の定期巡回で\nとっておきの店に\n連れてってあげよう！", 1, 101301, 0, 0, 2682);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "君に似合いそうな\n衣装を買ったよ！\n君もいざ魔法少女に！", 1, 101301, 0, 0, 2683);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "さあ！\n暇なら定期巡回に\nレッツラゴー！", 1, 101301, 0, 0, 2684);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "戦闘だけじゃなくて、\n日常にも役立つ\n魔法を習得したいね！", 1, 101301, 0, 0, 2685);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "新魔法思いついた！\n私って天才！？", 1, 101301, 0, 0, 2686);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "決め台詞は超大事！\n君の決め台詞も\n私が考えてあげよう！", 1, 101301, 0, 0, 2687);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "私ってもしやリア充？\n…そんなバカな！\n非リア代表のはずが！", 1, 101301, 0, 0, 2688);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよー…\n徹夜で本読んでたから\nまだ眠い～", 1, 101301, 0, 1, 2689);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼飯食べて、\n午後の定期巡回も\n頑張りましょー！", 1, 101301, 0, 2, 2690);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜からが、\nオタ活本番でしょ！", 1, 101301, 0, 3, 2691);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふいー！\nくつろいで本を読む！\n最高だねー！", 1, 101301, 0, 0, 2693);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "君、可愛いね～♪\n魔法少女の\n使い魔みたい！", 1, 101301, 0, 0, 2694);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "良い匂いに\n釣られてしまった…\nまさか、孔明の罠！？", 1, 101301, 0, 0, 2695);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "暖かいけど、\nここで本を読むのは\nちょっち危ないかな", 1, 101301, 0, 0, 2696);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ウマ―！\nこれの詳細きぼんぬ！", 1, 101301, 0, 0, 2698);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "こ、古代語の本！？\n現代語でおk…", 1, 101301, 0, 0, 2699);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ふふふっ♪\n次はどんな悪戯を\nしてやろうかしら♪", 1, 190901, 0, 0, 2701);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "幻影湖の霧を吸った\n人間たちの\nリアクションって、\nサイコーよねぇ～♪", 1, 190901, 0, 0, 2702);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "室内だけとはいえ…\n自由に動けるって、\nやっぱりいいわ～♪", 1, 190901, 0, 0, 2703);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "改めて見ると良い\n部屋ね…悪戯とか\nしやすそうだしぃ♪", 1, 190901, 0, 0, 2704);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "私を封じていた部屋\nなのに…急に居心地が\n良くなったわね♪", 1, 190901, 0, 0, 2705);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あんたの頭、座り心地\n良いわね…私専用の\n椅子にしてあげる♪", 1, 190901, 0, 0, 2706);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "外は大変みたいねぇ…\nまあ、私は好き勝手に\nやらせてもらうわ♪", 1, 190901, 0, 0, 2707);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "顔に落書された？\n誰か知らないけど、\n悪いことする奴も\nいるものねぇ～♪", 1, 190901, 0, 0, 2708);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "フィオのやつ…\nどこをウロチョロ\nしてるのかしら？", 1, 190901, 0, 0, 2709);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "人間の朝は大変ねぇ…\n私はその様を見ながら\nゆっくりするわね♪", 1, 190901, 0, 1, 2710);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "う～私も、お日様を\n浴びながら、お外を\nお散歩したーい！", 1, 190901, 0, 2, 2711);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "この暗さ…閉じ込め\nられていた時を\n思い出すわね…", 1, 190901, 0, 3, 2712);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "悪戯しすぎて\n疲れたから、ちょっと\n休憩しよっと♪", 1, 190901, 0, 0, 2714);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ガイド妖精たる私が、\nこんな造形物に\n惹かれる…わけが……\nかわいい♪", 1, 190901, 0, 0, 2715);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この香りを囮にして、\n周りに悪戯を仕込む…\n完璧ね♪", 1, 190901, 0, 0, 2716);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "不思議ねぇ…私は\n温度とか関係ないのに\n離れられないわ", 1, 190901, 0, 0, 2717);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食事の必要がない体…\nつまり、食べたければ\n食べていいのよね～♪", 1, 190901, 0, 0, 2719);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "へぇ…最近はこんな\n悪戯もあるのねぇ…\nあいつで試さないと♪", 1, 190901, 0, 0, 2720);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "メリークリスマス！\n歌で幸せを\n届けます…！", 1, 108401, 0, 0, 2722);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "あなたと出会えたのは\n偶然ではなくて…\nクリスマスの奇跡だと\n思うんです", 1, 108401, 0, 0, 2723);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "クリスマスは華やかで\nつい子供のように\nはしゃいでしまいます", 1, 108401, 0, 0, 2724);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "曲が書けるのは\nあなたが側に\nいてくれるからです…", 1, 108401, 0, 0, 2725);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "感動を与えられる歌…\nあなたと一緒になら\n生み出せるはず…", 1, 108401, 0, 0, 2726);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "クリスマスの幸せを\nあなたと\n感じ合えたらな…", 1, 108401, 0, 0, 2727);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あなたの幸せを願った\nクリスマスソング…\nいつか披露しますね", 1, 108401, 0, 0, 2728);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "みなさんの笑顔を\n守りたいから…\n私は歌い続けます", 1, 108401, 0, 0, 2729);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "歌を届ける\nサンタさんに\nなりたいな…", 1, 108401, 0, 0, 2730);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お暇でしたら\nクリスマスのお祝いを\nしませんか？", 1, 108401, 0, 0, 2731);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ステージに立つ前に\n喉を整えないと…\n発声練習は念入りに…", 1, 108401, 0, 0, 2732);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "まわりはかわいい子\nばっかりだけど…\nこの服なら\nアピールになるかな？", 1, 108401, 0, 0, 2733);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "歌でならいくらでも\nあの人への気持ちを\n込められるのに…", 1, 108401, 0, 0, 2734);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日も一日\n幸せな歌で世界が\n包まれますように…", 1, 108401, 0, 1, 2735);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お茶を飲みながら\n好きな音楽を\n語り合いませんか？", 1, 108401, 0, 2, 2736);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふふ、寝かしつけの\n子守唄を\nお望みですか？", 1, 108401, 0, 3, 2737);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふかふかですね\n心地良すぎて\n眠ってしまいそう…", 1, 108401, 0, 0, 2739);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "素敵…\n優しい歌みたいに\n気持ちが落ち着く…", 1, 108401, 0, 0, 2740);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "インスピレーションが\n溢れてくる…\nいい曲が書けそう…", 1, 108401, 0, 0, 2741);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "この光みたいに\n灯火になるような\n歌を歌いたい…", 1, 108401, 0, 0, 2742);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "喉の健康のためにも\n食事はしっかり\nとるようにしています", 1, 108401, 0, 0, 2744);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "物語には\n曲作りのヒントが\n詰まっているんです", 1, 108401, 0, 0, 2745);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 14, 3, "絵が飛び出してくる\nなんて…精霊が宿って\nいるのでしょうか？", 1, 108401, 0, 0, 2747);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 15, 3, "か、可愛い…♪\nちょっとだけ触っても\nいいですよね…？", 1, 108401, 0, 0, 2748);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "クリスマスでも、\n演劇の練習は\nしっかりやらないと！", 1, 108501, 0, 0, 2749);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "あうぅ…\nクリスマスの準備が\n終わらないよぅ…", 1, 108501, 0, 0, 2750);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "アヤネちゃんが\n摘み食いしないように\n見ておかないと…", 1, 108501, 0, 0, 2751);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "サンタさんみたいに、\n皆に笑顔で接する…\nうぅ…私には無理ぃ…", 1, 108501, 0, 0, 2752);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "新しいお洋服～♪\nスズメお姉ちゃんに\nお礼をいわないと♪", 1, 108501, 0, 0, 2753);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お兄ちゃんの為に、\nプレゼントを\n用意しないと♪", 1, 108501, 0, 0, 2754);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "クリスマス…\n恋人の日…ひゃわっ！\nわ、私ってば何を…！", 1, 108501, 0, 0, 2755);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "メリー\nクリスマスです、\nお兄ちゃん♪", 1, 108501, 0, 0, 2756);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "そ、そんなに\n見られると…\n恥ずかしいよぉ…", 1, 108501, 0, 0, 2757);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ひゃわぁっ！？\n急に触られると、\n驚くからやめてぇ…", 1, 108501, 0, 0, 2758);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あ…クリスマスの\n準備を手伝って\nくれるんですか？", 1, 108501, 0, 0, 2759);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お兄ちゃんと\n過ごすクリスマス、\n楽しみですぅ…♪", 1, 108501, 0, 0, 2760);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "クリスマスはその…\n二人で…あうぅ…\nなんでもないですぅ…", 1, 108501, 0, 0, 2761);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "うう…パーティーが\n楽しみで、あんまり\n眠れなかったよぅ…", 1, 108501, 0, 1, 2762);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ケーキを食べられなく\nなっちゃうから、\nお昼は軽めにしないと", 1, 108501, 0, 2, 2763);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ちょっと眠いけど…\n今日は少しだけ\n夜更かししたいです♪", 1, 108501, 0, 3, 2764);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふかふかぁ…\nクリスマスの準備中に\n眠くなっちゃいますぅ", 1, 108501, 0, 0, 2766);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "この子と一緒に\nおままごとしたいな♪", 1, 108501, 0, 0, 2767);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい匂い…♪\nみんなで\nアロマパーティー\nしたいなぁ…♪", 1, 108501, 0, 0, 2768);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ぬっくぬく…♪\nもう、ここから\n離れたくないよぉ…♪", 1, 108501, 0, 0, 2769);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "はむはむ…♪\nクリスマスのお料理\nより美味しいかも～♪", 1, 108501, 0, 0, 2771);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "すごい…\nクリスマスの\n演劇って、\nこんなにあるんだ…", 1, 108501, 0, 0, 2772);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 14, 3, "すごい…まるで、\nクリスマスの演劇を\n観てるようですぅ…♪", 1, 108501, 0, 0, 2774);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 15, 3, "とっても可愛いです♪\nお芝居の相手役に\nしたいなぁ…♪", 1, 108501, 0, 0, 2775);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "甘ぁいケーキも、\nデッカイ七面鳥も、\nぜーんぶ私のだー♪", 1, 108601, 0, 0, 2776);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "毎日が\nクリスマスだったら\nいいのにな～♪", 1, 108601, 0, 0, 2777);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "プレゼントはあるし、\n料理は美味しいし、\nクリスマス最高ー♪", 1, 108601, 0, 0, 2778);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ここでぷうきちの\nクリスマス一発芸♪\n『無茶ぶりするな！』", 1, 108601, 0, 0, 2779);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ぷうきちがいつもより\n重いかも…太ったの？\n『衣装の重さだよ！』", 1, 108601, 0, 0, 2780);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お兄ちゃんが\n一緒にいてくれると\nクリスマス楽しいね♪", 1, 108601, 0, 0, 2781);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "お兄ちゃんに抱きつく\nと、なんだかドキドキ\nする…なんでかな？", 1, 108601, 0, 0, 2782);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "メリークリスマス♪\nプレゼントは、\nいつでも受付中だよ♪", 1, 108601, 0, 0, 2783);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "このクマさん耳\n可愛いでしょ♪\nぷうきちと\nお揃いなんだー♪", 1, 108601, 0, 0, 2784);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お兄ちゃん…私、\n甘ぁいケーキが\n食べたいなぁ…♪", 1, 108601, 0, 0, 2785);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "クリスマスぷうきちは\nぬくぬく感が凄いよ！\nお兄ちゃんもさわる？", 1, 108601, 0, 0, 2786);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "えへへ…お兄ちゃんの\n手は、大きくて、\n暖かくて大好き～♪", 1, 108601, 0, 0, 2787);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "来年のクリスマスも、\nこうやって\nお兄ちゃんに\n甘えていたいな～♪", 1, 108601, 0, 0, 2788);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あれぇ…\n私のケーキはぁ…？\n『ちゃんと起きろ』", 1, 108601, 0, 1, 2789);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼はデッカイ\n七面鳥が食べたーい♪\n『夜まで我慢しろ』", 1, 108601, 0, 2, 2790);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "『もう寝る時間だぞ』\nサンタさんが来る\nまで起きてるぅ…", 1, 108601, 0, 3, 2791);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "このふかふか具合…\nぷうきち！\n負けてられないよ！", 1, 108601, 0, 0, 2793);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "この子、\nすっごくかわいい～♪\n『ライバル登場か！』", 1, 108601, 0, 0, 2794);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "良い匂い…あっ！\nぷうきちにこの\n匂いを移せば…！\n『匂い袋にするな』", 1, 108601, 0, 0, 2795);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったか～い♪\nえへへ、ぷうきちも\nあっためてあげる♪", 1, 108601, 0, 0, 2796);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ぷうきち！　これ、\nとってもおいしいよ♪\n『食べすぎるなよ』", 1, 108601, 0, 0, 2798);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "お、大人の私なら、\nこれぐらい…読め…\n『無理するな…』", 1, 108601, 0, 0, 2799);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 14, 3, "絵が飛び出す…\nぷうきちに絵本を\n入れれば、イタズラに\n使えるかも…♪", 1, 108601, 0, 0, 2801);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 15, 3, "か、可愛いけど…\nぷうきちサンタの方が\n可愛いんだからぁ…！", 1, 108601, 0, 0, 2802);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "着物も慣れると\n動きやすいものさ", 1, 108901, 0, 0, 2803);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "鼻緒が緩んでしまった\n下駄で修業は\n無理があったかな…", 1, 108901, 0, 0, 2804);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "小腹が空いた…\nユイが作った餅、\nまだ食べられるかな？", 1, 108901, 0, 0, 2805);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "服装も変わったし\nいつもと違う戦い方を\n想定しないと…", 1, 108901, 0, 0, 2806);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "…ヒヨリは動きすぎて\n着崩れしてないか\n心配だ", 1, 108901, 0, 0, 2807);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "これからもずっと\n仲間と、彼と\n一緒に…", 1, 108901, 0, 0, 2808);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "願いを叶えるために\nもっと自分を\n鍛えていかないと！", 1, 108901, 0, 0, 2809);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "頭の飾りがずれてた？\nそうか、直してくれて\nありがとう", 1, 108901, 0, 0, 2810);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "着物がそんなに\n珍しい？\nキミも着てみる？\n…冗談だよ", 1, 108901, 0, 0, 2811);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "肩掛けの触り心地が\n気に入った？\nならもっと触る？", 1, 108901, 0, 0, 2812);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ああ、この刀？\n釣り仲間に見繕って\nもらったんだ", 1, 108901, 0, 0, 2813);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "キミといると\n気持ちが段々と\n安らいでいくよ", 1, 108901, 0, 0, 2814);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "キミは私の行く先を\n照らしてくれる\n光のような存在だよ", 1, 108901, 0, 0, 2815);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう\n朝の修行を始めるけど\nキミもどう？", 1, 108901, 0, 1, 2816);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "この時間に軽く\n休憩をとるといい\n能率がよくなるよ", 1, 108901, 0, 2, 2817);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もう夜か…\n明日もまた頑張ろう\nそれじゃ、おやすみ", 1, 108901, 0, 3, 2818);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "…疲れていたのかな\nもう少しで眠る\nところだった…", 1, 108901, 0, 0, 2820);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふふっ、正月衣装を\n着せてやるのも\nよさそうだ", 1, 108901, 0, 0, 2821);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ふぅ…いい香りだ\n慌ただしい日々から\n心が解放される", 1, 108901, 0, 0, 2822);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "この心地よさ…\n寝てしまわないよう\n気をつけないと", 1, 108901, 0, 0, 2823);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいしいけど\n帯がきつくなる前に\n手を止めよう…", 1, 108901, 0, 0, 2825);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "外を出歩くのも\nいいけど、中で\n読書もありだな", 1, 108901, 0, 0, 2826);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "…騎士クンって\nおせち料理で\n何が好きなんだろう？", 1, 108801, 0, 0, 2828);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "着物でお掃除や\nお洗濯するの\n慣れてきた♪", 1, 108801, 0, 0, 2829);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "今年は\nどんな福袋を\n買おうかな…♪", 1, 108801, 0, 0, 2830);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お餅に使う調味料\nみんなで違うから\n色々用意しなきゃ", 1, 108801, 0, 0, 2831);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ほっぺがお餅みたいに\nぷにぷに…\n食べ過ぎちゃった…", 1, 108801, 0, 0, 2832);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "来年も、再来年も\nみんなで一緒に\n新年を迎えたいな", 1, 108801, 0, 0, 2833);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "お願いです…\nいつかこの気持ちが\n伝わりますように…", 1, 108801, 0, 0, 2834);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "髪飾りが落ちそう？\nじゃあ…騎士クン\nつけ直してくれる？", 1, 108801, 0, 0, 2835);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "着物が着たいの？\nじゃあ今度一緒に\n買いに…行く？", 1, 108801, 0, 0, 2836);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あっ、騎士クン\nお雑煮のお餅\nいくつ入れたい？", 1, 108801, 0, 0, 2837);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "外、寒かったよね？\nはいこれ。熱い甘粥\n飲むと温まるよ", 1, 108801, 0, 0, 2838);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "今年は騎士クンと…\nえっ？　騎士クン！？\nな、なんでもないよ！", 1, 108801, 0, 0, 2839);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "騎士クンの願い事\nわたしが\n叶えてあげたいな…", 1, 108801, 0, 0, 2840);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう\n太陽の光に当たると\n元気が出るよ", 1, 108801, 0, 1, 2841);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ごはん\n作らなきゃ…\n騎士クンも食べる？", 1, 108801, 0, 2, 2842);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "一日が終わるのは\nあっという間だよね\n一年も同じなのかな？", 1, 108801, 0, 3, 2843);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふぅ…\n帯も少し\nゆるめちゃおう…", 1, 108801, 0, 0, 2845);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "お正月用に\n着物を縫って\nあげたいな", 1, 108801, 0, 0, 2846);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "これでお肌が\n保湿出来たら\nいいのになぁ", 1, 108801, 0, 0, 2847);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ん～…\nぬくぬくしてて\n動きたくないよ～", 1, 108801, 0, 0, 2848);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "…冬眠しないのに\n熊さんみたいに\n食べちゃいそう", 1, 108801, 0, 0, 2850);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "年末年始は\n告白のチャンス…\nむ、無理無理！", 1, 108801, 0, 0, 2851);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "みんな忙しそう…\n待っててね、\nすぐ助けるから！", 1, 108701, 0, 0, 2853);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ユイちゃんと\nレイさん…よし！\nどっちも手伝おう！", 1, 108701, 0, 0, 2854);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "あっ、着崩れてる！\nわわっ、どうしよ！\n帯が結べないよー！", 1, 108701, 0, 0, 2855);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "初詣楽しみー！\n出店はどこから\n行こうかな？", 1, 108701, 0, 0, 2856);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "お正月だし\nみんなで楽しく\n遊んじゃおー！", 1, 108701, 0, 0, 2857);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "うーん…\n騎士くんはお正月\n何してるんだろ…", 1, 108701, 0, 0, 2858);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ううぅー…\n騎士くんを見てると\nドキってなっちゃう…", 1, 108701, 0, 0, 2859);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あたしから\nおいしそうな匂い？\nくんくん…ソースだ！", 1, 108701, 0, 0, 2860);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ヘアピンが…\n拾ってくれたんだ！\nありがとう騎士くん！", 1, 108701, 0, 0, 2861);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "髪飾りがかわいい？\n耳の近く触りたい？\n…優しくね？　", 1, 108701, 0, 0, 2862);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "グローブで食べるの\n大変そう？　特訓して\n今はお箸も使えるよ！", 1, 108701, 0, 0, 2863);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "えっ、ほっぺが赤い？\nそうかな…？\n気のせい気のせい！", 1, 108701, 0, 0, 2864);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "騎士くんといるとね…\nなんでもない！\nまだ内緒っ！", 1, 108701, 0, 0, 2865);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよー！\n今日も明るく元気に\nがんばろー！", 1, 108701, 0, 1, 2866);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹すいてない？\n一緒にご飯食べよ！\n何にしようかなー♪", 1, 108701, 0, 2, 2867);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日もいっぱい\nがんばったー！\nいつも？　…そう？", 1, 108701, 0, 3, 2868);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "休憩休憩♪\nちょっと休んで\nガンガン動くぞー！", 1, 108701, 0, 0, 2870);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい♪\nでも、壊しそうで\nちょっと怖い…", 1, 108701, 0, 0, 2871);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "はぁー♪\nいい香りー…\n気分スッキリ♪", 1, 108701, 0, 0, 2872);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ほっこりしてて\nぬくぬく…\n丸まりたい…", 1, 108701, 0, 0, 2873);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ど、どうしよう…！\n手が、止まんないよ！", 1, 108701, 0, 0, 2875);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "へー…お年玉って\n昔はお餅だったんだ\n…今のほうがいいね", 1, 108701, 0, 0, 2876);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "甘いチョコの香りを\n漂わせて…ふふっ\nこれで準備万端ですわ", 1, 109001, 0, 0, 2878);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ここを私のチョコで\n埋め尽くしますわ", 1, 109001, 0, 0, 2879);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "エプロンを着て\nあの方を待つ私…\nまるで…クスクス", 1, 109001, 0, 0, 2880);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "キッチンはどこかしら\n今のうちに作って\nおきたいものが…", 1, 109001, 0, 0, 2881);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "あのお方を私のチョコ\nなしでは生きられない\n体に…ふふっ\n冗談ですわ…", 1, 109001, 0, 0, 2882);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "このチョコは運命の味\n一口食べれば私の虜…\nそれも運命ですわ…", 1, 109001, 0, 0, 2883);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "私ともあろうものが\nなんだかドキドキして\nきましたわ…", 1, 109001, 0, 0, 2884);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あなた様。私に\n隠しているものなど\nありませんよね…？", 1, 109001, 0, 0, 2885);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "私の手作りチョコです\n味の方にも自信\nありますのよ？", 1, 109001, 0, 0, 2886);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "少し苦いのは\nチョコがビターなだけ\nお気になさらず…", 1, 109001, 0, 0, 2887);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "解毒薬はどこに\nいれたかしら…？", 1, 109001, 0, 0, 2888);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "運命で結ばれている\nあなた様と私…\nチョコも特別でないと\nいけませんわ", 1, 109001, 0, 0, 2889);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "チョコを食べた後は\nメインディッシュ…\nさぁ、私を召し上がれ", 1, 109001, 0, 0, 2890);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "目覚めのチョコですわ\nすっきり目が覚めます\nしばらく眠れなく\nなりますけど…", 1, 109001, 0, 1, 2891);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おやつのチョコですわ\nデザートにどうぞ\n空腹を感じなく\nなりますわ…クスクス", 1, 109001, 0, 2, 2892);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お夜食のチョコですわ\nとてもよく眠れます\nさ、溶けてしまう前に", 1, 109001, 0, 3, 2893);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "この心地良さ…\n参考になりますわ\n次の薬は…クスクス", 1, 109001, 0, 0, 2895);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "この中、何か\n入りそうですわね\n…チョコレート、とか", 1, 109001, 0, 0, 2896);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り…この香りと\n同じものを調合して\n私も持っていたい", 1, 109001, 0, 0, 2897);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "この暖かさ…\nチョコが溶けないよう\n気を付けなくては", 1, 109001, 0, 0, 2898);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いい味をしていますわ\n私も腕を磨きましょう\n料理と、調合の腕を…", 1, 109001, 0, 0, 2900);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "勉強になりますわ\n知識はいくらあっても\n困りませんもの\n特に、人体の知識は…", 1, 109001, 0, 0, 2901);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "弟くんのことを\n考えると\nあっという間に時間が\n過ぎちゃう…", 1, 109101, 0, 0, 2903);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "お姉ちゃんの\n元気の源は、弟くんの\n喜ぶ顔なんだから♪", 1, 109101, 0, 0, 2904);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "弟くんと会ったら\nまずは抱きしめて\nそれからそれから…", 1, 109101, 0, 0, 2905);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "今日のお姉ちゃんは\n昨日のお姉ちゃんより\nいいお姉ちゃんだよ♪", 1, 109101, 0, 0, 2906);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "弟くん、もっと\nお姉ちゃんに\n甘えてもいいのに♪", 1, 109101, 0, 0, 2907);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お姉ちゃんのチョコ\n食べさせてあげたい…", 1, 109101, 0, 0, 2908);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ドキドキしてきた…\nお姉ちゃんなのに\nどうしてかなぁ…", 1, 109101, 0, 0, 2909);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お姉ちゃんを\n好きなだけ\n触っていいよ♪", 1, 109101, 0, 0, 2910);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "そんなにお姉ちゃんの\nチョコが欲しいの？\n食いしん坊さん♪", 1, 109101, 0, 0, 2911);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ナデナデするのは\nお姉ちゃんの仕事！", 1, 109101, 0, 0, 2912);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ありがとうなんて…\nお姉ちゃんとして\n当たり前だよ♪", 1, 109101, 0, 0, 2913);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "どうしたのかなっ？\nお姉ちゃんはいつでも\n弟くんのそばにいるよ", 1, 109101, 0, 0, 2914);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "チョコを作ったよ\n隠し味は、たくさんの\n弟くんへの愛情♪", 1, 109101, 0, 0, 2915);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよ。お姉ちゃんが\n顔を洗うの\n手伝ってあげるね♪", 1, 109101, 0, 1, 2916);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ご飯を食べたら\n眠たくなるよね…\nお姉ちゃんと寝る？", 1, 109101, 0, 2, 2917);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ眠くなった？\nお姉ちゃんが添い寝\nしてあげるね♪", 1, 109101, 0, 3, 2918);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "この気持ちよさは\nお姉ちゃんも太鼓判♪", 1, 109101, 0, 0, 2920);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "このかわいさは\nお姉ちゃんも大満足♪", 1, 109101, 0, 0, 2921);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この香り、チョコに\n使えるかな…？", 1, 109101, 0, 0, 2922);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "弟くんと一緒に\nぬくぬくしたいな…♪", 1, 109101, 0, 0, 2923);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "すごくおいしいねっ♪\nあとで運動しなきゃ…", 1, 109101, 0, 0, 2925);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "本を読んでる\n知的なお姉ちゃん\n素敵でしょ♪", 1, 109101, 0, 0, 2926);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "アタシって…\nここにいても\nいいのか…？", 1, 106101, 0, 0, 2928);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ちゃんとした建物に\nいるのが久しぶりで\nそわそわする…", 1, 106101, 0, 0, 2929);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ここで天楼覇断剣\n出す練習したら\nアイツら怒るかな？", 1, 106101, 0, 0, 2930);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ギルドハウスか…\nこういう隠れ家\n欲しかったんだよな", 1, 106101, 0, 0, 2931);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "めちゃくちゃ暇だ…\n…なんかやること\nないのか？", 1, 106101, 0, 0, 2932);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "みんなが早く\nアタシのこと\n思い出さないかな", 1, 106101, 0, 0, 2933);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "アイツはいいヤツだし\n戦う時はアタシも\n協力してやるか！", 1, 106101, 0, 0, 2934);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ちゃんはいらん！\nノウェムでいい！\n分かったか？", 1, 106101, 0, 0, 2935);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "どうした？\n戦うのか！？\n…なんだ、違うのか", 1, 106101, 0, 0, 2936);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "身長のことは\nあんまり言うな！\n気にしてるからな！", 1, 106101, 0, 0, 2937);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "アタシの戦い方は\nなんでもアリだ！\nだから見習うなよ？", 1, 106101, 0, 0, 2938);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "オマエとの思い出か…\n敵として戦ってばっか\nだったな！", 1, 106101, 0, 0, 2939);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "オマエやオクトーと\n一緒に、あちこち\nいってみたいんだ！", 1, 106101, 0, 0, 2940);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "よっ！　おはよう！\n朝だぞー！\n起きてるかー？", 1, 106101, 0, 1, 2941);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "腹減ったー！\n飯食うぞ、飯！\nオマエも行くよな？", 1, 106101, 0, 2, 2942);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふわぁ…\nまだ起きてんのか？\n元気だなオマエ…", 1, 106101, 0, 3, 2943);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふぃ～…\n極楽極楽…", 1, 106101, 0, 0, 2945);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "おいオマエ！\n寝技の練習に\n付き合ってもらうぞ", 1, 106101, 0, 0, 2946);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "くんくん…\nたまにはこういうのも\n悪くないかもな", 1, 106101, 0, 0, 2947);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あー…\nもっと前にコイツと\n出会いたかった…", 1, 106101, 0, 0, 2948);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "VRでも飯はうまい！\n腹が減るのはちゃんと\n生きてる気がするな", 1, 106101, 0, 0, 2950);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "勉強は大事だな！\nうん！…だめだ！\n全然わからん！", 1, 106101, 0, 0, 2951);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "探偵というのは\n謎を追い求める\n生き物なのさっ！", 1, 101401, 0, 0, 2953);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "事件のオチは\n往々にして\n取るに足らないものさ", 1, 101401, 0, 0, 2954);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "読書で得る知識が\n探偵の\n血肉になるんだよ", 1, 101401, 0, 0, 2955);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "この前の\n捜査資料…\nどこにあったかな？", 1, 101401, 0, 0, 2956);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "どんな小さな謎も\n私にとっては\n宝石みたいなものさ！", 1, 101401, 0, 0, 2957);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "助手くんと一緒だと\nよい発想が浮かぶ…\nどうしてだろうね？", 1, 101401, 0, 0, 2958);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "助手くんの好きな\nタイプって…\nす、推理してみるっ！", 1, 101401, 0, 0, 2959);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "珈琲、淹れたてだよ\n一杯どうだい？", 1, 101401, 0, 0, 2960);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "事件の考察を\nまとめてみたんだけど\n聞いてくれるかな？", 1, 101401, 0, 0, 2961);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "小さな違和感を\n見逃さない…\n探偵の心得だよ", 1, 101401, 0, 0, 2962);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "機能的な手帳とペン…\nこの仕事には\n欠かせないね！", 1, 101401, 0, 0, 2963);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "助手くんに\n珈琲…\n淹れてほしいなぁ～", 1, 101401, 0, 0, 2964);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "助手くんは\n私にとって\n最高の相棒だよ☆", 1, 101401, 0, 0, 2965);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝はいいひらめきが\n得られるんだ…\nさあ捜査を始めよう！", 1, 101401, 0, 1, 2966);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "一休みしたら\n推理の答え合わせを\nしてみようか？", 1, 101401, 0, 2, 2967);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜の張りこみかい？\nなら私も\n同行させてほしいな！", 1, 101401, 0, 3, 2968);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "脳を酷使した後は\nゆっくり休む…\nこれも仕事だよ？", 1, 101401, 0, 0, 2970);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "この愛らしさ…\n要捜査対象だね！", 1, 101401, 0, 0, 2971);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "思考が活性化される\n素敵な香りだね…", 1, 101401, 0, 0, 2972);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "くぅ、心地よすぎる…\n今だけは捜査も\n一休みだね♪", 1, 101401, 0, 0, 2973);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いっぱい食べて\nいっぱい考える\n探偵の本分だね！", 1, 101401, 0, 0, 2975);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "探偵だからね\nミステリには\n一家言あるんだ", 1, 101401, 0, 0, 2976);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "先輩、素敵だなぁ…\nもっと近づければ\nいいのに…", 1, 105501, 0, 0, 2978);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "せ、先輩がいた部屋！\n私には刺激が強い…", 1, 105501, 0, 0, 2979);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "先輩を観察しやすい\n場所はあるかな…", 1, 105501, 0, 0, 2980);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "バ、バイト代出たし、\nせ、先輩をご飯とかに\n誘いたい…な", 1, 105501, 0, 0, 2981);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "今頃先輩は\nあの辺かな…？\n見に行ってみよう！", 1, 105501, 0, 0, 2982);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "私と先輩の出会いって\n思い返すと少女漫画\nみたい…えへへ", 1, 105501, 0, 0, 2983);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "せ、先輩になら\n観察されてもいいなぁ", 1, 105501, 0, 0, 2984);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "バイト先に新しい子が\n入って来たんです…\nわ、私、先輩です♪", 1, 105501, 0, 0, 2985);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "せ、先輩…？\nえっと、あの、その、\nあわわわわ…！", 1, 105501, 0, 0, 2986);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "えへへ…えへへ～\nせ、先輩から\n話しかけてくれました", 1, 105501, 0, 0, 2987);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ま、また…\n先輩と一緒に\nバイトしたい…です", 1, 105501, 0, 0, 2988);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "私と先輩が同じ空間に\n…ゆ、夢みたいです", 1, 105501, 0, 0, 2989);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "せ、先輩のそばに\n居られて、私\n今、とっても\n幸せです…", 1, 105501, 0, 0, 2990);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "せ、先輩…！\nおひゃっ！\nおはようございます！", 1, 105501, 0, 1, 2991);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "先輩ランチに\n行きましょう！\nよし、練習はバッチリ", 1, 105501, 0, 2, 2992);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あ、せ、先輩。\nえと、そ、外…\nもう真っ暗ですねぇ", 1, 105501, 0, 3, 2993);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "こ、ここで先輩も\n休んだり…はっ！\nわ、私ったらなにを！", 1, 105501, 0, 0, 2995);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいですねー\n君も一緒に、\n先輩を観察する？", 1, 105501, 0, 0, 2996);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ここから先輩の\n香りがすればなあ", 1, 105501, 0, 0, 2997);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "先輩と一緒に\nぬくぬくできたら\n最高なんだけどなぁ", 1, 105501, 0, 0, 2998);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいし～\nこれは\n先輩も好きな味かな", 1, 105501, 0, 0, 3000);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "す、好きな人に\n近づく方法…", 1, 105501, 0, 0, 3001);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "私の力は、大切な\n人たちを護るために\n役立てたいんだ", 1, 109201, 0, 0, 3003);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "きれいな景色と\n美味しいご飯！\nこの世界も素敵だね", 1, 109201, 0, 0, 3004);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "この世界のみんなとも\nもっと仲良く\nなりたいな！", 1, 109201, 0, 0, 3005);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "わー！\nあれもこれも\n気になっちゃうな！", 1, 109201, 0, 0, 3006);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "しっかりしなきゃって\n思ってても、\nグレアといるとつい\n甘えちゃうんだよね～", 1, 109201, 0, 0, 3007);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "違う世界でも\n友だちができて、\nすごくうれしいよ！", 1, 109201, 0, 0, 3008);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "みんなとも一緒に\n授業とか受けたいな～\n絶対楽しそうだもん！", 1, 109201, 0, 0, 3009);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "歩き方がきれい？\nえへへ、そうかな…？", 1, 109201, 0, 0, 3010);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "勉強は好きだよ！\n知識が増えていくのは\nやっぱり楽しいから", 1, 109201, 0, 0, 3011);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "私たちの国マナリアは\n人々の間に魔法が\n伝えられた、その\n始まりの地なんだ！", 1, 109201, 0, 0, 3012);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "この部屋にも、\nもっとたくさん本棚が\n増えないかな～…？", 1, 109201, 0, 0, 3013);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あなたも魔法、\n覚えてみる？\n私、教えるよ！", 1, 109201, 0, 0, 3014);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お茶の時間に\nしたいな～…\n一緒にどう？", 1, 109201, 0, 0, 3015);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようっ！\n今日も素敵な\n一日にしようね！", 1, 109201, 0, 1, 3016);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ご飯は\nちゃんと食べた？\n午後も頑張ろうね！", 1, 109201, 0, 2, 3017);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "つい本の続きが\n気になって、夜更かし\nしちゃうんだよね～…", 1, 109201, 0, 3, 3018);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "はぁ、気持ちいい～…\nちょっとだけ\n眠っちゃおうかな…", 1, 109201, 0, 0, 3020);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "わあ、これ可愛い！\nグレアにも見せて\nあげたいな", 1, 109201, 0, 0, 3021);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り～！\nなんだか気持ちが\n落ち着くね", 1, 109201, 0, 0, 3022);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あぁ、あったかくて\n幸せ～♪　身体が\nポカポカしてきたよ！", 1, 109201, 0, 0, 3023);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "こ、これ美味し～！\n止められないよー！", 1, 109201, 0, 0, 3025);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふんふん…\n…はっ！　む、夢中に\nなっちゃってた…", 1, 109201, 0, 0, 3026);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "新しい建物に入ると\n必ず一度は迷子に\nなっちゃうですよ…", 1, 109301, 0, 0, 3028);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "おやつはどこですか？\nお腹が空いて\nきちゃったですぅ", 1, 109301, 0, 0, 3029);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "宿題、７つぐらい\n出しそびれたですけど\nまあ大丈夫ですぅ！", 1, 109301, 0, 0, 3030);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "不思議なこと\nばかりですけど…\nまぁ大丈夫です！\nこれもせいしゅんです", 1, 109301, 0, 0, 3031);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "なにか面白そうなもの\nないですかね～？", 1, 109301, 0, 0, 3032);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ここのみんなとも\nもうお友だちですぅ！", 1, 109301, 0, 0, 3033);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "おなかが減ったです…", 1, 109301, 0, 0, 3034);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ごはんも美味しいし\nここはいいところです\nルゥは幸せですぅ！", 1, 109301, 0, 0, 3035);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "魔法の話ですか？\nそれはアンせんぱいに\n聞いてほしいですぅ…", 1, 109301, 0, 0, 3036);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あなたもお勉強\n苦手ですか？", 1, 109301, 0, 0, 3037);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ルゥの帽子、\nかわいいです？\nお気に入りですぅ♪", 1, 109301, 0, 0, 3038);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お友だちいっぱいで、\nルゥはうれしいです♪", 1, 109301, 0, 0, 3039);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "一緒にお勉強…！？\nぐえぇ、イヤですぅ！", 1, 109301, 0, 0, 3040);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝ですねぇ…ふわわ…\nルゥはまだ夢の中に\nいたいですぅ…", 1, 109301, 0, 1, 3041);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "午後もいっぱい\n遊ぶですよ～！", 1, 109301, 0, 2, 3042);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜ふかしって\nドキドキするです！\nせいしゅんですぅ！", 1, 109301, 0, 3, 3043);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふかふかですぅ～♪\nおひるねが\nしたくなるですぅ！", 1, 109301, 0, 0, 3045);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "これふかふかですぅ！\n机でうとうとする時の\n枕によさそうですぅ", 1, 109301, 0, 0, 3046);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ふぁぁ、いいにおい…\nなんだか気持ちが\nよくなってきたですぅ", 1, 109301, 0, 0, 3047);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ぽっかぽかですぅ～！\nあったまったら\nまた遊びにいくですぅ", 1, 109301, 0, 0, 3048);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "お、おいしいですぅ！\n全部ルゥに\nくださいですぅ！", 1, 109301, 0, 0, 3050);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "本は…読むと、\nすぐ眠気がぁ…\n…ぐぅ…", 1, 109301, 0, 0, 3051);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ピアノ…\nどこかにないかな？", 1, 109401, 0, 0, 3053);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ふぅ…\n落ち着くな…", 1, 109401, 0, 0, 3054);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "マナリアはいつも\n賑やかなんだ…", 1, 109401, 0, 0, 3055);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "みんな…\n今頃何してるかな？", 1, 109401, 0, 0, 3056);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "まさか違う世界に\n来ちゃうなんて…\nびっくりだよね…", 1, 109401, 0, 0, 3057);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "人と話すのは\n得意じゃないな…", 1, 109401, 0, 0, 3058);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ここのみんなと一緒に\n学院に通えたら…\nちょっと面白いかも", 1, 109401, 0, 0, 3059);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "やっぱり、私の翼や\n尻尾…気になる？", 1, 109401, 0, 0, 3060);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "一番得意なのは、\nやっぱり炎魔法かな…\n加減は難しいけど…", 1, 109401, 0, 0, 3061);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "私の故郷は竜の国…\n険しい山脈を\n越えた先にあるんだ", 1, 109401, 0, 0, 3062);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "アン…？\nあっ、ご、ごめんね！\n間違えちゃった…", 1, 109401, 0, 0, 3063);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ふん…ふん…♪\n…わっ！\n今の、聞いてた…？\nは、恥ずかしい…", 1, 109401, 0, 0, 3064);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "私に手伝えること、\nなにかある…？\nなんでも言ってね", 1, 109401, 0, 0, 3065);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝の空気って\nすごく\n静かで透き通ってて…\nなんだか落ち着くよね", 1, 109401, 0, 1, 3066);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "学院食堂のランチも\n美味しいけど…\nここのご飯も好きかな", 1, 109401, 0, 2, 3067);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろベッドに\n行かないとだね\n…寝相、今夜こそ\n気を付けよう…！", 1, 109401, 0, 3, 3068);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "羽を伸ばしたく\nなっちゃうね…ふふ", 1, 109401, 0, 0, 3070);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "わ、私が持つには\nかわいすぎるかな…\nでも、素敵だね", 1, 109401, 0, 0, 3071);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り…\nこれ、\nアンも好きそう…", 1, 109401, 0, 0, 3072);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "火を見ていると\n少し落ち着くんだ…\nへ、変かな？", 1, 109401, 0, 0, 3073);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "わ、美味しい…！\nこれ、どうやって\n作ったのかな…？", 1, 109401, 0, 0, 3075);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "この本…アンにも\n見せてあげたら\n喜ぶかな、ふふっ", 1, 109401, 0, 0, 3076);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "着物はきれいですが\n歩きにくいです…\nいっそ脱いで…ぐふふ", 1, 109501, 0, 0, 3078);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "あっ、いけません\n着物がはだけて…はっ\nもしやドＳさんが…！", 1, 109501, 0, 0, 3079);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "この部屋は妄想する\nのにうってつけです…\nぐふふ…じゅるり", 1, 109501, 0, 0, 3080);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "扇をゆっくりと開く\nこの感触…なぜだか\n艶めかしさを感じます", 1, 109501, 0, 0, 3081);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "「マッサージをすると\n言いながらドＳさんの\n手は次第に」…ぐふふ", 1, 109501, 0, 0, 3082);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "…ドＳさんの視線を\n思い出しながら踊りの\n練習です…イイ！", 1, 109501, 0, 0, 3083);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "よいではないか\nよいではないか～\nいけませんご堪忍を～", 1, 109501, 0, 0, 3084);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あ～れ～～～！\nドＳさんもお好きな人\nですねぇ…ぐふふ", 1, 109501, 0, 0, 3085);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "どこにいてもドＳさん\nの気配を感じ取れる\nようになりました…", 1, 109501, 0, 0, 3086);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "こんな場所で\nなんというプレイを！\n…妄想でした", 1, 109501, 0, 0, 3087);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "クウカを押し倒して\nそのまま…じゅるり\nああっ、着物が…！", 1, 109501, 0, 0, 3088);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ドＳさんは優しいです\n優しいのにドＳとは\nさすが人格破綻者…！", 1, 109501, 0, 0, 3089);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ドＳさんの考えている\nことが伝わってきます\nはい…クウカ脱ぎます", 1, 109501, 0, 0, 3090);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "眩しい朝日がクウカの\n体を焦がします\n…それもイイ！", 1, 109501, 0, 1, 3091);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼のランチは\nクウカがいいだなんて\n大胆過ぎです…じゅる", 1, 109501, 0, 2, 3092);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "…今夜のドＳさんは\n大胆です…ぐふふ…\nはっ、視線が…！？", 1, 109501, 0, 3, 3093);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "この心地良さ、\n心が休まりすぎて\n体が疼いてきます…！", 1, 109501, 0, 0, 3095);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "すごく愛らしいです…\n妄想も出てこない\nくらい…じゅるり", 1, 109501, 0, 0, 3096);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この香りに包まれて\nいると、いい気持ちに\nなって…いきますぅ…", 1, 109501, 0, 0, 3097);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "「熱を帯びた体は\nどうしようもなく\n誰かを求め…」ぐふふ", 1, 109501, 0, 0, 3098);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "お腹が膨らんで\nいきます…それは\nまるで…ぐふふ", 1, 109501, 0, 0, 3100);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "クウカの探している\nジャンルはどこに\nありますかね？", 1, 109501, 0, 0, 3101);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "カチョーフーゲツは\nトーゴクの心を\n表した言葉デスね", 1, 109601, 0, 0, 3103);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "オー！　新しい忍法を\n思いついたデス！\nさっそく試すデス！", 1, 109601, 0, 0, 3104);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "トーゴクの天気には\n槍が降る日も\nあるそうデス…", 1, 109601, 0, 0, 3105);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "我がショーグンは\n永遠にフメツデース\nいざ出陣デース！", 1, 109601, 0, 0, 3106);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "壁に耳あり\n障子に…ん？\nメアリーって誰デス？", 1, 109601, 0, 0, 3107);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ショーグンがいれば\nワタシはどんな\n忍法も使いこなせマス", 1, 109601, 0, 0, 3108);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "不届き者はどこで\nゴザルデス？　忍法で\n退治してくれヨウ！", 1, 109601, 0, 0, 3109);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ショーグン！　新しい\n忍法を覚えたデス！\n見てほしいデース！", 1, 109601, 0, 0, 3110);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "レッツ手裏剣道デス！\n投げてソウロウで\nゴザルデース！", 1, 109601, 0, 0, 3111);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふりかかる火の粉は\nワタシが払うデス！\nバンバン！", 1, 109601, 0, 0, 3112);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "とっておきの忍法が\n吹き荒れるデス！\nよそ見はダメデスヨ？", 1, 109601, 0, 0, 3113);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ショーグンは\n何階建てのお城を\n建てたいデスか？", 1, 109601, 0, 0, 3114);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "テンシュカクから\n平和な城下町を\n眺めてみたいデス…", 1, 109601, 0, 0, 3115);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございマス！\n本日はオヒガラモヨク\n良い日になりそうデス", 1, 109601, 0, 1, 3116);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹すいたデース…\nショーグンもご飯に\nしまショウ！", 1, 109601, 0, 2, 3117);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "闇討ちに遭わぬよう\n夜は気を付けて\n歩くデスよー？", 1, 109601, 0, 3, 3118);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "天下分け目の\n戦いに備えて…\nマッタリデース", 1, 109601, 0, 0, 3120);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "口寄せの術で\n召喚したいくらい\nかわいいデース", 1, 109601, 0, 0, 3121);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい匂いデ～ス\n香り玉の開発の\n参考になりそうデスね", 1, 109601, 0, 0, 3122);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ワタシの懐よりも\nゾーリが暖まりマス…\nライバル出現デス…！", 1, 109601, 0, 0, 3123);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "腹が減っては\n戦はできぬデース！\n天下統一に向けて\n腹ごしらえデス！", 1, 109601, 0, 0, 3125);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ムム、暗号文デス！？\n解読には時間が\nかかりそうデース…", 1, 109601, 0, 0, 3126);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "掃除も終わりましたし\nそろそろ、食事の\n準備をしなくては", 1, 109701, 0, 0, 3128);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "異世界の演劇…\n許されるならば、\n観てみたいです", 1, 109701, 0, 0, 3129);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "こちらの世界には、\nマヨネーズが普通に\n存在するのですね…", 1, 109701, 0, 0, 3130);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "こちらの世界は食材も\n面白い物が多いですね\nなにかレシピを\n考えてみましょうか", 1, 109701, 0, 0, 3131);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "みょんみょんみょん…\n魔法の練習は\nこれぐらいですね", 1, 109701, 0, 0, 3132);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "倒木の撤去で思わぬ\n収入となりました\nサレン様に\nお渡ししておかないと", 1, 109701, 0, 0, 3133);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "料理を美味しく\n召し上がって頂けると\nメイド冥利につきます", 1, 109701, 0, 0, 3134);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お出かけでしたら、\nレムも同行\nさせてくださいね", 1, 109701, 0, 0, 3135);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "レムにできること\nでしたら、なんでも\nお申し付けください", 1, 109701, 0, 0, 3136);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "じーー。いえ、\nその髪の長さが少し、\nとても少し、かなり\n少し気になったもので", 1, 109701, 0, 0, 3137);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "鉄球ですか？\nあれは護身用ですので\n問題はありませんよ？", 1, 109701, 0, 0, 3138);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "計算の勉強は\n進んでおりますか？\nレムでよろしければ、\nいつでもお教えします", 1, 109701, 0, 0, 3139);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "次はもっと、大きな\n魔物料理に挑戦します\nワイバーンの姿焼き\nなんてどうでしょうか", 1, 109701, 0, 0, 3140);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\n朝食の準備が\nできておりますので、\n食卓におこしください", 1, 109701, 0, 1, 3141);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼食の時間ですね\n何か食べたいものは\nありますか？", 1, 109701, 0, 2, 3142);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "寝ないのか、ですか？\nメイドの就寝は、\n屋敷で最後と\n決まっておりますので", 1, 109701, 0, 3, 3143);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふんわり…\nこのふんわりさは、\n鬼をも黙らせます…", 1, 109701, 0, 0, 3145);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふふっ…異世界でも\nかわいいものは\n共通なのですね", 1, 109701, 0, 0, 3146);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "よい香りですね\n魔女教の悪臭とは\n大違いです", 1, 109701, 0, 0, 3147);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ぬくぬくです…はっ！\nこれはいけません！\n人を…いえ、\n鬼をだめにします！", 1, 109701, 0, 0, 3148);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "はむはむ…美味しい！\nこの味を再現できたら\n褒めてもらえる\nかもしれません…！", 1, 109701, 0, 0, 3150);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "絵がいっぱい…\n異世界の本は\nとても面白いですね", 1, 109701, 0, 0, 3151);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "異世界であろうと、\nラムのやるべきことは\n変わらないわ\nまずは休憩するわよ", 1, 109801, 0, 0, 3153);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "マヨネーズがある\nということは、\nバルスの故郷が近い\nのかもしれないわね", 1, 109801, 0, 0, 3154);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "この世界では、バルス\nの言う言葉が使われる\nときがあるのね\n忌々しいかぎりだわ", 1, 109801, 0, 0, 3155);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ラムたち以外にも\nメイドが居るのね\nラムが…いえ、\n仕事を押しつけるわ", 1, 109801, 0, 0, 3156);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "…千里眼で視るかぎり\n周囲に異変はないわね\n危険がないなら、\nあとはレムに任せるわ", 1, 109801, 0, 0, 3157);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "…ラムもまた、\n「お姉ちゃん」って\n呼ばれる日が\nくるのかしらね", 1, 109801, 0, 0, 3158);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ハッ！　ラムが作る\n蒸かし芋は完璧ね\n…気が向いたら、また\n作ってやろうかしら", 1, 109801, 0, 0, 3159);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ラムに構う暇が\nあるなら働きなさい\nそうすれば、\nラムが楽をできるわ", 1, 109801, 0, 0, 3160);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ラムに何かを\n期待しても無駄よ\nラムに命令できるのは\nロズワール様だけだわ", 1, 109801, 0, 0, 3161);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "暇なら買い物に\n付き合いなさい\n荷物を\n持たせてあげるわ", 1, 109801, 0, 0, 3162);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ラムになんの用？\nふざけた内容なら\nねじ切るわよ", 1, 109801, 0, 0, 3163);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "そういえば、あなたは\n記憶喪失だったわね…\n思い出す努力をなさい\n…家族が悲しむわよ", 1, 109801, 0, 0, 3164);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "蒸かし芋が欲しい？\n随分と厚かましいわね\n…まだ残りがあるから\n好きに食べなさい", 1, 109801, 0, 0, 3165);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "だらしない顔ね\n顔を洗って\nしゃんとなさい", 1, 109801, 0, 1, 3166);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹が空く時間ね\nラムの昼食を\n用意させてあげるわ", 1, 109801, 0, 2, 3167);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "メイドが寝るのは\n屋敷で最後…\nラムが寝るために、\nさっさと寝なさい", 1, 109801, 0, 3, 3168);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "…ここから動かない\nという、誓いを\n立てたくなるわね", 1, 109801, 0, 0, 3170);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "これは…かわいいわね\nもちろん、\nラムほどではないけど", 1, 109801, 0, 0, 3171);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "…香炉かしら？\nこちらの世界にも\n質のよい物があるのね", 1, 109801, 0, 0, 3172);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "見つけてしまったの\nかもしれないわ…\nラムの楽園を！", 1, 109801, 0, 0, 3173);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "…はむっ\nラムの蒸かし芋ほど\nではないけど、\nなかなかいけるわね", 1, 109801, 0, 0, 3175);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "異世界ならではの\n面白い内容もあるわね\nとても興味深いわ", 1, 109801, 0, 0, 3176);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ねえパック、\nにゃんにゃか\nにゃかにゃんしよっか", 1, 109901, 0, 0, 3178);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "時間もあるし、\nこっちの世界の石で\n石積みしようかな", 1, 109901, 0, 0, 3179);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "私もお姉さんだし、\nサレンさんを\n見習わないと…うん！\n私、すごーく頑張る！", 1, 109901, 0, 0, 3180);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "この世界は、銀髪で\nハーフエルフでも受け\n入れてくれるのね…\nなんだか嬉しいな", 1, 109901, 0, 0, 3181);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "今日のご飯…\nピーマルは\n入ってないわよね…？", 1, 109901, 0, 0, 3182);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "また、みんなで\n一緒に買い物に\n行きたいな", 1, 109901, 0, 0, 3183);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "パック以外から\n家族って呼ばれたの\n初めて…ふふっ♪\nちょっと嬉しいかも！", 1, 109901, 0, 0, 3184);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今からパックの\n毛繕いをするけど…\n一緒にする？", 1, 109901, 0, 0, 3185);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "私も何かお手伝いを…\nあ、そうだ！\n料理とかどうかな！", 1, 109901, 0, 0, 3186);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ねえ、ここで\n歌の練習って、\nしてもいいかな？", 1, 109901, 0, 0, 3187);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "…あ、ごめんなさい！\n話しかけられるのって\nあまり慣れてなくて…", 1, 109901, 0, 0, 3188);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "すごーく頑張るから、\nこれからも勉強を\n手伝ってね", 1, 109901, 0, 0, 3189);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "せーの、びくとりー！\nふふっ…また、一緒に\nラジーオタイソー\nしようね♪", 1, 109901, 0, 0, 3190);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ちゃんと起きてる？\nふふっ…よかった。\nあ、べ、別に心配した\nわけじゃないからね？", 1, 109901, 0, 1, 3191);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ご飯が楽しみね♪\nあ、こっちの世界って\nまよねーずはあるの？", 1, 109901, 0, 2, 3192);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ寝る時間よ。\n夜更かししたら、\nめっ！　だからね！", 1, 109901, 0, 3, 3193);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "勉強も終わったし…\nちょっ、ちょっとだけ\n休んでもいいよね…？", 1, 109901, 0, 0, 3195);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "か、かわいい…！\nパックのかわいさに\n匹敵するかも…！", 1, 109901, 0, 0, 3196);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "良い香り…\nロズワールの屋敷にも\nこういうのって\nあるのかな？", 1, 109901, 0, 0, 3197);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかい…\nずっとここに…はっ！\nダメダメ！　王選の\nために勉強しないと！", 1, 109901, 0, 0, 3198);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "あ…これ美味しい！\nこっちの世界は色んな\n食べ物があるのね。", 1, 109901, 0, 0, 3200);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "知らないことが\nいっぱい書いてある…\n異世界の本って、\n面白いのね", 1, 109901, 0, 0, 3201);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "海ってマジ最高！\nビーチの撮影も\n超楽しいしー♪", 1, 110001, 0, 0, 3203);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "20パーって何パ？\n今度ヒデサイに\n聞いてみよっ！", 1, 110001, 0, 0, 3204);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "夏の思い出を\nヒデサイと一緒に\n作りたいな～", 1, 110001, 0, 0, 3205);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "テンションあがる\n水着ゲットして\n超ラッキーだよ～♪", 1, 110001, 0, 0, 3206);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "休憩が終わったら\n撮影にもどらないと！\n気合入れてこ♪", 1, 110001, 0, 0, 3207);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ヒデサイとビーチで\nパーティーしたいな～\n超楽しそうだよね！", 1, 110001, 0, 0, 3208);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ヒデサイといると\n楽しくてうれしくて…\nカレシってこんな感じ\nなのかなぁ？", 1, 110001, 0, 0, 3209);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "見て見て～！\n夏らしいネイルに\nしてみたんだ～♪", 1, 110001, 0, 0, 3210);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ヒデサイ～\nこの水着どうかな？\nイケてるっしょ♪", 1, 110001, 0, 0, 3211);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "水着姿の写真？\nもちいいよ！\nかわいく撮ってね！", 1, 110001, 0, 0, 3212);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "うちだって\n夏の海みたいに\nキラキラしちゃうよ！", 1, 110001, 0, 0, 3213);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ヒデサイとうちの\nフィーリングって\nめっちゃエモいよね♪", 1, 110001, 0, 0, 3214);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ねーねーヒデサイ！\n一緒に泳ぎにいこっ！\nほら、手繋いで♪", 1, 110001, 0, 0, 3215);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "水着オッケー！\nネイルもばっちり！\n朝から遊んじゃおー♪", 1, 110001, 0, 1, 3216);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼食べたら\n昼寝して\nリフレッシュしよー♪", 1, 110001, 0, 2, 3217);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "水着ってマジで\n最強かも…このまま\nお風呂にも入れるし♪", 1, 110001, 0, 3, 3218);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "マジ気持ちいいー♪\nおに癒やされるん\nですけど～！", 1, 110001, 0, 0, 3220);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "やばばばばー！\nかわいすぎだってば！\nマジらぶだよ～♪", 1, 110001, 0, 0, 3221);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "あ、この香り超好き！\nモデル仲間に\n教えたげよ～♪", 1, 110001, 0, 0, 3222);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったか～い♪\n夏の太陽みたい！", 1, 110001, 0, 0, 3223);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "マジ美味しいねこれ♪\nビーチで\n流行っちゃうかも！", 1, 110001, 0, 0, 3225);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "夏のために\n最新ファッションを\n勉強ちう！", 1, 110001, 0, 0, 3226);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "なにコレもにカワ～♪\nなんて生き物？\nヒデサイ知ってる？", 1, 110001, 0, 0, 3228);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "うわっ超フカフカ～\nなんかうち眠く\nなってきちゃった…", 1, 110001, 0, 0, 3229);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "海の家でのんびり\n過ごしましょう\n熱中症には注意してね", 1, 110101, 0, 0, 3230);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "はぁ、どうやったら\n泳げるように\nなれるのかしら～", 1, 110101, 0, 0, 3231);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "海で日焼け止めを\n塗らないと、あとで\n大変なことになるわよ", 1, 110101, 0, 0, 3232);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "久しぶりに水着を\n着たんだけど\n変じゃなかったかな…", 1, 110101, 0, 0, 3233);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "波の音って落ち着くわ\n授業中に聞いたら\nみんな寝ちゃうかも？", 1, 110101, 0, 0, 3234);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "海が楽しいって\n思えたのも\nあの子のおかげね", 1, 110101, 0, 0, 3235);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あの子と二人で海に\n来られてよかったわ\n一日があっという間ね", 1, 110101, 0, 0, 3236);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "男の子と海だなんて\n少女漫画みたいで\n憧れてたの～", 1, 110101, 0, 0, 3237);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "夏休みの宿題は\nちゃんとやった？\n遊んでばかりではダメ", 1, 110101, 0, 0, 3238);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "昼の海と夜の海\nどっちが好き？　私は\n君といる海が一番よ", 1, 110101, 0, 0, 3239);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ふう、疲れたわ～\n冷たいジュースで\n元気回復ね！", 1, 110101, 0, 0, 3240);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "海で見た君の背中\nすごく大きく見えたわ\nやっぱり男の子なのね", 1, 110101, 0, 0, 3241);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "君と一緒に見た\n夜の海…\n忘れられそうにないわ", 1, 110101, 0, 0, 3242);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "準備ができたら\n海に出かけようよ\n今日も楽しみましょう", 1, 110101, 0, 1, 3243);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あら、もうお昼？\n海の家でランチに\nしましょ♪", 1, 110101, 0, 2, 3244);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜の海岸についてきて\nくれる？　暗がりは\n一人じゃ怖くて…", 1, 110101, 0, 3, 3245);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "泳ぐ練習をしたら\n疲れちゃったわ～\nちょっと一休み…", 1, 110101, 0, 0, 3247);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいわね～\n浮き輪に乗せて\n海に浮かべたいわ～", 1, 110101, 0, 0, 3248);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この匂い…\nなんだか夏の海を\n思い出すわ～", 1, 110101, 0, 0, 3249);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "夜の海風で冷えない\nように、しっかりと\n身体を暖めましょうね", 1, 110101, 0, 0, 3250);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "海で遊ぶ前に\nしっかり食べて\n体力つけましょう", 1, 110101, 0, 0, 3252);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "夏休み中でも\nしっかりお勉強\nしないと！", 1, 110101, 0, 0, 3253);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "この子に乗れば\n海の上でも\nすいすい進めるかしら", 1, 110101, 0, 0, 3255);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "ビーナスの誕生！\n…なんちゃって\nはしゃぎすぎかしら？", 1, 110101, 0, 0, 3256);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "夏の海には商機が\nあるはず…\nのがす手はないわね♪", 1, 110301, 0, 0, 3257);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "あたしが作った\n日焼け止め…\nこれは売れそうね！", 1, 110301, 0, 0, 3258);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "子どもたちのために\n浮き輪を用意して\nおかないと…", 1, 110301, 0, 0, 3259);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "海っていいわよね！\nみんなで羽を伸ばしに\n行きたいわ！", 1, 110301, 0, 0, 3260);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "波の音を聞いて\nのんびりするのも\n悪くないわね…", 1, 110301, 0, 0, 3261);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ただの砂遊びも\nあんたと一緒なら\n楽しいから不思議ね…", 1, 110301, 0, 0, 3262);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あんたがあたしの\nなんであれ、大切な\n存在ではあるのよね…", 1, 110301, 0, 0, 3263);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "夏の海って\nすごい人よね…\n迷子にならないでよ？", 1, 110301, 0, 0, 3264);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ぼんやり海に浮かんで\n波に揺られるのも\n悪くないわよ？", 1, 110301, 0, 0, 3265);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ビーチで子どもたちと\n一緒に砂のお城を\n作りたいわ♪", 1, 110301, 0, 0, 3266);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "海で食べる\n焼きそばパン…\nいいかもしれないわね", 1, 110301, 0, 0, 3267);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あたしの水着\n似合ってる？\nそう、ありがとう♪", 1, 110301, 0, 0, 3268);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あんたが居ると\nうれしい…って、\n子どもたちが\n言ってたわ！", 1, 110301, 0, 0, 3269);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝の浜辺って\nいいわよね\n散歩しに行きたいわ", 1, 110301, 0, 1, 3270);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "海の家のご飯って\nなんであんなに\nおいしいのかしら♪", 1, 110301, 0, 2, 3271);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜の海って、\nロマンチックよね。\nずっと眺めてたいわ…", 1, 110301, 0, 3, 3272);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "やわらかくて\n気持ちいい…\nこのまま寝ちゃいそう", 1, 110301, 0, 0, 3274);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "海に一緒に入れる\nぬいぐるみとか\nないかしら？", 1, 110301, 0, 0, 3275);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "夏らしい\nいい香りね…\nなんの香りかしら？", 1, 110301, 0, 0, 3276);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかい…\n濡れた体を乾かすには\nちょうどいいわね♪", 1, 110301, 0, 0, 3277);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "泳いだ後の食事は\n普段の何倍も\nおいしく感じるわね！", 1, 110301, 0, 0, 3279);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "海に行く前にいろいろ\n調べなきゃね。備え\nあれば憂いなしよ！", 1, 110301, 0, 0, 3280);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "海の守り神？\nずいぶんかわいらしい\n神様ね♪", 1, 110301, 0, 0, 3282);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "このぐらい\n大きな貝があったら\n食費も浮くかしら？", 1, 110301, 0, 0, 3283);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "浜辺で食うものって\nなんであんなに\nうまいのかな～", 1, 110401, 0, 0, 3284);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "いてて…\nちょっと日焼け\nしすぎたかな", 1, 110401, 0, 0, 3285);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "砂浜で走ると\nいいトレーニングに\nなるんだぜ", 1, 110401, 0, 0, 3286);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "夏ならではの\n料理…か\n何がいいかな…", 1, 110401, 0, 0, 3287);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "やっぱりここは\n涼しくて快適だな", 1, 110401, 0, 0, 3288);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "泳ぎの練習だったら\nいつでも付き合って\nやるからな！", 1, 110401, 0, 0, 3289);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "水着で部屋の中に\nいるのって\n変な感じだな…", 1, 110401, 0, 0, 3290);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "うおっ！\nきゅ、急に\n触るなって…\nびっくりした", 1, 110401, 0, 0, 3291);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "え、砂がついてた？\n払ってくれたのか\nありがとよ", 1, 110401, 0, 0, 3292);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夏バテしてないか？\nここで休んでけよ", 1, 110401, 0, 0, 3293);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "…そう見られると\n照れるっていうか…", 1, 110401, 0, 0, 3294);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "カキ氷とか\n食いたくないか？\n氷、削ってやるよ", 1, 110401, 0, 0, 3295);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "おまえと\n夏の思い出ができて\nよかったよ", 1, 110401, 0, 0, 3296);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふう…\n朝一番で泳ぐの\nやっぱ気持ちいいな", 1, 110401, 0, 1, 3297);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "一番あちぃ時間だ\n水分補給は\nこまめにな！", 1, 110401, 0, 2, 3298);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日もお疲れ\n明日のパトロールも\nよろしくな", 1, 110401, 0, 3, 3299);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "泳ぎ疲れたからな\n少し休憩だ…", 1, 110401, 0, 0, 3301);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "か、かわいい…\nいや、なんでもねぇ！", 1, 110401, 0, 0, 3302);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この香り落ち着くな\nこういうのも\n悪くねーかも…", 1, 110401, 0, 0, 3303);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったけえ…！\n泳ぎ終わった後って\nけっこう体冷えてよ…", 1, 110401, 0, 0, 3304);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "海で食べると\nまた一味違うよな", 1, 110401, 0, 0, 3306);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "夏のサバイバル特集…\nちょっと読んでみるか", 1, 110401, 0, 0, 3307);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "へー！　こいつ、\nよくできてんな！\nいいなあ、実物も\n乗れたらいいのに", 1, 110401, 0, 0, 3309);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "か、かわ…！\nいや、じゃなくて\nあ、あたしがここに\n寝ていいのか…？", 1, 110401, 0, 0, 3310);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "故郷の花を飾っても\nいいかな～？\n部屋が楽しくなるよ～", 1, 110501, 0, 0, 3311);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "水着で歩いてると\n泳ぎたくなるさ～\n我慢できないさ～！", 1, 110501, 0, 0, 3312);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "夏が眩しいのは\nてぃーだがにこにこ\n笑ってるからさ～！", 1, 110501, 0, 0, 3313);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "泳ぎ疲れたら\n涼しい木陰で\nお昼寝するさ～", 1, 110501, 0, 0, 3314);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "クロールも\n犬かきも\n大得意さ～！", 1, 110501, 0, 0, 3315);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "なんだか歌いたい\n気分さ～\nキミもどう～？", 1, 110501, 0, 0, 3316);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "海の近くに住んで\nキミと歌って踊って\nそれが理想さ～！", 1, 110501, 0, 0, 3317);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "私とキミ\nどっちがたくさん\n泳げるか\n競争するさ～！", 1, 110501, 0, 0, 3318);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "キミも三線に興味が\nあるのかな～？\n私が教えるさ～！", 1, 110501, 0, 0, 3319);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "嫌なことがあっても\n私と歌って踊れば\nなんくるないさー！", 1, 110501, 0, 0, 3320);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "たまには時間を忘れて\n私とのーんびり\n海を眺めるさ～", 1, 110501, 0, 0, 3321);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ぶるぶるぶるっ！\n毛が濡れちゃっても\nへっちゃらさ～！", 1, 110501, 0, 0, 3322);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "泳ぐ前は準備体操～！\n背中押してあげるから\nしっかりやるさ～！", 1, 110501, 0, 0, 3323);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝の浜辺は\nちゅらさんよ～\n一緒に歩こうよー！", 1, 110501, 0, 1, 3324);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ご飯は\n決まったかな～？\n私はタコライスさ～！", 1, 110501, 0, 2, 3325);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "星と波音の中で\n三線鳴らすのも\nオツなものさ～", 1, 110501, 0, 3, 3326);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ちょうどよかったさー\nゆっくり休んだら\nまた泳ぎに行くさ～！", 1, 110501, 0, 0, 3328);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "砂浜に飾って\nおきたいさ～\nきっとかわいいさ～！", 1, 110501, 0, 0, 3329);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "くんくん…はあ\n癒されるさ…\n故郷の夏の匂いさ～", 1, 110501, 0, 0, 3330);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "おおー…！\n濡れた髪が\nみるみる乾いてくさ～", 1, 110501, 0, 0, 3331);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ん～！　これ、\n海で食べたら\nもっとおいしいさ～", 1, 110501, 0, 0, 3333);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "海の生物図鑑ね～\nこの前みかけた魚も\n載ってるかな～？", 1, 110501, 0, 0, 3334);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "わぁ～！　みてみて！\n背中に乗れるさー！\nキミと一緒に\n乗りたいさ～！", 1, 110501, 0, 0, 3336);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "ふかふかさ～\n海の底の\n人魚になった気分さ～", 1, 110501, 0, 0, 3337);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "あの人が\nわたしの騎士だったら\nいいのにな…", 1, 105801, 0, 0, 3338);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "あなたのおかげで\nわたしの心はいつも\nお腹いっぱいです♪", 1, 105801, 0, 0, 3339);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "許されるのならば、\n今すぐにでも、\n主さまのおそばに\n行きたいです…", 1, 105901, 0, 0, 3340);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "主さま…\nお慕いしております…\nいつまでも、おそばに\n居させてください…", 1, 105901, 0, 0, 3341);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "なんか最近、\nあいつのことしか\n考えてない…\nあたし…どうしよう…", 1, 106001, 0, 0, 3342);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "そ、外に行くなら、\n連れていきなさいよね\nその…あたしが\n守ってあげるから…", 1, 106001, 0, 0, 3343);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "部屋の中は涼しくて\n気持ちええどすなぁ\n天国やわぁ", 1, 110601, 0, 0, 3344);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "クラゲはんって\nフリルいっぱいの\nドレスみたいやねぇ", 1, 110601, 0, 0, 3345);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "外でセミはんが\n元気に鳴いてはるねぇ\n今日もええ天気やわぁ", 1, 110601, 0, 0, 3346);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "こないに暑いと\n海に入って\n涼みたくなるわぁ", 1, 110601, 0, 0, 3347);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "いつか\nマホマホ王国にも\n海の家作りまひょ♪", 1, 110601, 0, 0, 3348);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "うちも\n付き合いますえ\n泳ぎの練習しまひょ♪", 1, 110601, 0, 0, 3349);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "うちの里帰り\n王子はんも一緒に\n来まへんか？", 1, 110601, 0, 0, 3350);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "王子はんは日焼けより\n色白美人の方が\n好きでっしゃろか？", 1, 110601, 0, 0, 3351);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "うちと一緒に\n浮き輪で海、\nプカプカしまへん？", 1, 110601, 0, 0, 3352);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "日が落ちたら\n線香花火\nやりたいわぁ♪", 1, 110601, 0, 0, 3353);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "木陰でのんびり\nお昼寝…\n最高やね～", 1, 110601, 0, 0, 3354);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お祭ではぐれても\n王子はんなら見つけて\nくれはります？", 1, 110601, 0, 0, 3355);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "楽しい夏やわぁ\nずっとこんな日が\nつづくとええね", 1, 110601, 0, 0, 3356);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "うちにしては早起き？\n暑くて目が早う\n覚めてもうたんどす", 1, 110601, 0, 1, 3357);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼は冷たい\nおそうめんとか\nどうでっしゃろ", 1, 110601, 0, 2, 3358);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜は星がきれいやね\n二人で浜辺でも\n行きまへんか？", 1, 110601, 0, 3, 3359);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "うーん、遊び疲れた\n身体にちょうどええ\nほっこり具合やわぁ", 1, 110601, 0, 0, 3361);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かいらしい子は\nみーんな\nマホマホ王国の\n住人どすえ♪", 1, 110601, 0, 0, 3362);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この香り…\n南国にいる気分やねぇ\n癒されるわぁ～", 1, 110601, 0, 0, 3363);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "これで\n冷えた身体も\nポカポカやねぇ", 1, 110601, 0, 0, 3364);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "外はまだ暑いやろうし\nバテんよう\nしっかり食べんとね", 1, 110601, 0, 0, 3366);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "海の中にもお城が\nあるんやねぇ\n行ってみたいわぁ", 1, 110601, 0, 0, 3367);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "この子、ふかふかやね\nこのままマホマホ王国\n乗せてってくれはる？", 1, 110601, 0, 0, 3369);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "人魚姫になっても\n最後は王子はんと\nハッピーエンド\nどすえ～", 1, 110601, 0, 0, 3370);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "真似したくなる\n人がここには\n大勢いますね", 1, 107001, 0, 0, 3371);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "偽物を一人\n紛れこませました\n…冗談です", 1, 107001, 0, 0, 3372);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "動物に変身して\nその辺りを\n散歩してきます", 1, 107001, 0, 0, 3373);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "失った記憶は\nどの程度回復するの\nでしょうね", 1, 107001, 0, 0, 3374);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "人や物だけでなく\nいずれは世界すら\n真似てみせます", 1, 107001, 0, 0, 3375);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "次は彼に\nどんなことを\n教えましょうか…", 1, 107001, 0, 0, 3376);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "知識はともかく\n私の力はまだ\n必要なようですね", 1, 107001, 0, 0, 3377);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "どうしました？\n…何でもない？\n…そうですか", 1, 107001, 0, 0, 3378);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "退屈しています\n芸でもして\n楽しませなさい", 1, 107001, 0, 0, 3379);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "研究のためです\n少し話し相手に\nなりなさい", 1, 107001, 0, 0, 3380);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "何か真似して欲しい？\n私の能力を何だと\n思っているのですか", 1, 107001, 0, 0, 3381);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "貴方にはまだ色々と\n教えるべきことが\nありますね", 1, 107001, 0, 0, 3382);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "随分多くの女性と\n知り合いなのですね\n驚きました", 1, 107001, 0, 0, 3383);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "…\nおはようございます\n…まだ朝ですよ", 1, 107001, 0, 1, 3384);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "食事にします\n…どうしました？\n早く持ってきなさい", 1, 107001, 0, 2, 3385);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "早く寝なさい\n夜更かしすると\n背が伸びませんよ？", 1, 107001, 0, 3, 3386);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "マサキより\n座り心地は\nいいですね", 1, 107001, 0, 0, 3388);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "意外に複雑な\n構造ですね", 1, 107001, 0, 0, 3389);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "真似るなら\n香りまで\n再現しなくては", 1, 107001, 0, 0, 3390);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "発火現象の\n模倣…なかなか\n難しいものです", 1, 107001, 0, 0, 3391);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "偽物や分身を作るには\nエネルギーが\n必要不可欠なのです", 1, 107001, 0, 0, 3393);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "暇つぶしには\nちょうどよさそうです\n…", 1, 107001, 0, 0, 3394);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "学院かぁ…\n友達の作り方の\n授業はないかな？", 1, 110701, 0, 0, 3396);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "学院でぼっちに\nなったときのために、\n避難場所を\n探しておかないと…", 1, 110701, 0, 0, 3397);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ぼっちの私が学院…\nな、なんだか\n目まいがしてきました", 1, 110701, 0, 0, 3398);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "クラスメイトに\n話しかける練習…\nむ、難しすぎます…！", 1, 110701, 0, 0, 3399);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "目指せ友達100人…\n無理かな…10人…\nや、やっぱり一人！", 1, 110701, 0, 0, 3400);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あなたと学院生活が\n送れるなんて、\nとっても\nうれしいです！", 1, 110701, 0, 0, 3401);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "えへへ…\n学院でも、\nあなたと一緒に\n居られてうれしいな♪", 1, 110701, 0, 0, 3402);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "が、学院ってあんなに\n人が居るんですね…\n友達作りのイメトレを\nやり直さないと！", 1, 110701, 0, 0, 3403);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "私にとって\n部活動とはＢＢ団！\n今日もたくさん\n活動しましょうね！", 1, 110701, 0, 0, 3404);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "休み時間は寝たふり…\nご飯はおトイレ…\nぼっち対策は完璧です", 1, 110701, 0, 0, 3405);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "学院で友達を作る\n勉強は完璧ですよ！\n購買部でパンを買って\n渡すんですよね！", 1, 110701, 0, 0, 3406);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "学院でも、\nＢＢ団の活動を\nしていきましょうね♪", 1, 110701, 0, 0, 3407);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ぼっちに学院生活は\n厳しいですね…でも、\nあなたと一緒なら\n乗りこえられそうです", 1, 110701, 0, 0, 3408);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "もうこんな時間…\nあの…一緒に学院に\n行ってくれませんか？", 1, 110701, 0, 1, 3409);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ですね！\n言ってくれれば、\nパンでもお握りでも\n買ってきますよ！", 1, 110701, 0, 2, 3410);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日もぼっち…\nいつか友達と一緒に、\nパジャマパーティー\nしたいなぁ…", 1, 110701, 0, 3, 3411);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "森とは違う\n心地良さが…このまま\n眠っちゃいそうです…", 1, 110701, 0, 0, 3413);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい…この子を、\n話す練習の相手役に\nしてみようかな？", 1, 110701, 0, 0, 3414);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り…\nいつ友達ができても\nいいように、私の\n部屋にも置こうかな", 1, 110701, 0, 0, 3415);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "こ、これは…\nぼっちで\n日陰者の私には\n暖かすぎます！", 1, 110701, 0, 0, 3416);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいしい…！\nお弁当にして、学院に\n持っていけないかな？", 1, 110701, 0, 0, 3418);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "学院の授業に\nついていくためにも、\n勉強しておこうかな…", 1, 110701, 0, 0, 3419);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "あんた、何してんの。\nいいけど、なんでも", 1, 110801, 0, 0, 3421);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "邪魔。どいて。\nいや怒ってないし。\nコレがフツーだから", 1, 110801, 0, 0, 3422);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "いいけど、\n散らかしめの部屋だと\n片付けたくなるよね…", 1, 110801, 0, 0, 3423);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "暇なときは明日の\nコーデ考えてるよ。\n考えるのはタダだし", 1, 110801, 0, 0, 3424);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "昔よくシオリン\n構いすぎてハツネに\n文句言われたなァ…", 1, 110801, 0, 0, 3425);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "なんかさ。あんたって\n謎に女子トモ多いよね\n…いいけど、べつに", 1, 110801, 0, 0, 3426);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ねえ。あのさあ。\nあんた弁当で好きな\n具とかってあんの", 1, 110801, 0, 0, 3427);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あ？　何。なんか用。\nや、ないならないで\nいいけど、べつに", 1, 110801, 0, 0, 3428);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ごめ、ちょっと\n黙っててくんない。\n明日の試験ヤバだから", 1, 110801, 0, 0, 3429);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "歩き方が静か？\n癖になってるんだよね\n足音を殺すの", 1, 110801, 0, 0, 3430);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "うちの血液型？\n大雑把のОだけど。\nなんか文句あんの", 1, 110801, 0, 0, 3431);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ひゃんっ！\nや、だからさ…急に\n話しかけんなっての", 1, 110801, 0, 0, 3432);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "な、何…あんまジッと\n見ないでくんない…\nなんか、その、ハズい", 1, 110801, 0, 0, 3433);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "早起きは得意な方だと\n思うけど。昔から\nそれがデフォだったし", 1, 110801, 0, 1, 3434);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "こんな時間か…\n昼ごはん\nサクッと作っちゃお", 1, 110801, 0, 2, 3435);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あ？　夜遊び？\nはッ…そんなん\n５歳で卒業したっての", 1, 110801, 0, 3, 3436);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "あーヤバじゃんコレ…\nふかついてる場合\nじゃないっつーのに…", 1, 110801, 0, 0, 3438);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "なんだこれ\nかわいいかよ", 1, 110801, 0, 0, 3439);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ふーん。\nこの匂い…\nなんかいいじゃん", 1, 110801, 0, 0, 3440);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "暖炉はアドじゃん。\n煮物、焼き物、蒸し物\nいろいろ作れそう", 1, 110801, 0, 0, 3441);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "何コレ\n食べ物困んないじゃん\nうちにも一台くんない", 1, 110801, 0, 0, 3443);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "本かァー…んー\n学校の勉強だけで\nいいかなァ…", 1, 110801, 0, 0, 3444);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "イタズラってなにを\nしたらいいのかな？", 1, 111101, 0, 0, 3446);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "カップケーキ\n上手に作れました\n食べてくれるかな…", 1, 111101, 0, 0, 3447);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "あの人、\nお菓子くれるかな？\nくれなかったら…ふふ", 1, 111101, 0, 0, 3448);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "オバケ…いないよね？\n怖くなんてないけど！", 1, 111101, 0, 0, 3449);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ハロウィンは\n楽しいけどオバケの\nお祭りなんだよね…", 1, 111101, 0, 0, 3450);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "にゃ～、にゃお～！\nちゃんと怖いかな？\n早く帰ってこないかな", 1, 111101, 0, 0, 3451);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あの人のことだから\nお菓子欲しがるよね…\n準備はバッチリです♪", 1, 111101, 0, 0, 3452);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "えへへ。猫さんのお耳\nよく出来てるでしょ？", 1, 111101, 0, 0, 3453);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "触りましたね？\nイタズラしましたね？\nへんた～い！", 1, 111101, 0, 0, 3454);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "フー！　頭を撫でたら\n怒りますよ！　あれ？\n猫みたいでした？", 1, 111101, 0, 0, 3455);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "きゃっ！　も、もう、\n脅かさないでください\n怖くありませんけど！", 1, 111101, 0, 0, 3456);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お菓子ですか？\nありがとうございます\nハッピーハロウィン♪", 1, 111101, 0, 0, 3457);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ゴロゴロ…\nね、猫さんの真似です\n…似てましたか？", 1, 111101, 0, 0, 3458);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "さぁ、お菓子作りを\n始めますよ。下準備は\n大事ですからね！", 1, 111101, 0, 1, 3459);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今、つまみ食い\nしましたね！？　あっ\nおやつの時間でしたか", 1, 111101, 0, 2, 3460);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "さぁ、ハロウィンの\n始まりです…ふぁ…\nね、眠くありません！", 1, 111101, 0, 3, 3461);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ちょっと疲れたかも…\nパーティの時間まで\nひと休みしなきゃ", 1, 111101, 0, 0, 3463);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "私も今、こんな感じ\nなのかな？　こんなに\nかわいいといいなぁ", 1, 111101, 0, 0, 3464);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "甘い匂いがいっぱい…\nお菓子の香りかな？", 1, 111101, 0, 0, 3465);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "温かくなると、\n丸まりたくなって…\n…猫になっちゃう！？", 1, 111101, 0, 0, 3466);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ニンジンもこれくらい\nおいしければ\nいいのに…", 1, 111101, 0, 0, 3468);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ハロウィンの本、\nオバケがたくさん\n載ってて怖いかも…", 1, 111101, 0, 0, 3469);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 12, 3, "美味しそうなお菓子が\nいっぱい…これなら\nイタズラされませんね", 1, 111101, 0, 0, 3471);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "たくさんいたずら\nできるから\nハロウィン大好き！", 1, 111201, 0, 0, 3473);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ハロウィンだから\nいつもよりすごい\nいたずらしたいな～！", 1, 111201, 0, 0, 3474);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "カボチャを綺麗に\nくり抜いてすごく怖い\nランタン作っちゃお！", 1, 111201, 0, 0, 3475);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お菓子がたくさんで\nどれから食べるか\n迷っちゃうな～！", 1, 111201, 0, 0, 3476);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "どうすればみんなを\nびっくりさせられる\nかな～？", 1, 111201, 0, 0, 3477);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "カボチャ見てたら\nお腹空いて来たな～\nお菓子食べちゃお♪", 1, 111201, 0, 0, 3478);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "にいちゃんには\n特別ないたずらを\n用意してあげるね！", 1, 111201, 0, 0, 3479);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "カボチャにクラッカー\nを仕掛けて…わっ！？\nみ、見ちゃダメだよ！", 1, 111201, 0, 0, 3480);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ん？　なぁに？\nお菓子ほしいの？\nもう、しかたないな～", 1, 111201, 0, 0, 3481);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "にいちゃんの\n面白い仮装が\n見てみたいな～！", 1, 111201, 0, 0, 3482);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お菓子くれたお礼に\nとびっきりの\nいたずらしちゃうね！", 1, 111201, 0, 0, 3483);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "にいちゃんは\nハロウィンでも最高の\nいたずら相手だよ！", 1, 111201, 0, 0, 3484);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "にいちゃんと一緒に\nハロウィンパレード\n歩きたいな～！", 1, 111201, 0, 0, 3485);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようにいちゃん！\n仮装して出かける\n準備しなきゃ！", 1, 111201, 0, 1, 3486);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹すいたな～\nもらったお菓子\n食べちゃだめかな？", 1, 111201, 0, 2, 3487);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "たくさんいたずらして\nもうクタクタ～\nミソギもう寝るね…", 1, 111201, 0, 3, 3488);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "やわらか～い…\nここでひと休みして\nまたいたずらしよう！", 1, 111201, 0, 0, 3490);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいもので\n油断させてわっ！\nってするのどうかな？", 1, 111201, 0, 0, 3491);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いいにお～い！\nいたずらのアイデアが\nわいてくるよ！", 1, 111201, 0, 0, 3492);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "もらったお菓子\nあったかくしたら\nおいしいかな～？", 1, 111201, 0, 0, 3493);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "お菓子ばっかりじゃ\n飽きちゃうもんね！\nご飯も食べよう！", 1, 111201, 0, 0, 3495);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "本のなかに\nいたずらのヒント\nないかな～？", 1, 111201, 0, 0, 3496);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 12, 3, "お菓子がたくさん！\n一人で食べていいの？\nやっぱりだめか～！", 1, 111201, 0, 0, 3498);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "お勉強は順調ですよ\nやっぱりお兄ちゃんの\nおかげなんでしょうか", 1, 101101, 0, 0, 3500);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "お兄ちゃんとの\n思い出の場所\nまた行きましょうね", 1, 101101, 0, 0, 3501);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "えへへ～♪\nハロウィンの\nミイラさんうさぎさん\nぴょんぴょ～ん！", 1, 111301, 0, 0, 3502);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "るんたった～\nハロウィンハロウィン\n楽しいな～♪", 1, 111301, 0, 0, 3503);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ハロウィンって\nどんなお菓子を\nもらえるのかな～？", 1, 111301, 0, 0, 3504);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お菓子をもらう\n練習をしなくちゃ！\nトリックオア\nトリート～♪", 1, 111301, 0, 0, 3505);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "おにいちゃんと\nハロウィンするの\nミミ楽しみだな～♪", 1, 111301, 0, 0, 3506);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "おにいちゃんと\nいっしょにお菓子を\n食べたいな～", 1, 111301, 0, 0, 3507);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "おにいちゃんと\n毎日ハロウィン\nできたらいいな～♪", 1, 111301, 0, 0, 3508);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "えへへ～\nおにいちゃん！\nハッピーハロウィン♪", 1, 111301, 0, 0, 3509);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おにいちゃんも\nいっしょに\nハロウィンパレード\nしようね～！", 1, 111301, 0, 0, 3510);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ミイラさんうさぎさん\nだぞ～…えへへ\nミミこわかったかな？", 1, 111301, 0, 0, 3511);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "おにいちゃん！\nハロウィンのお菓子\nおいしいね～♪", 1, 111301, 0, 0, 3512);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "おにいちゃんと\nいっしょなら\nおばけさんも\nこわくないよ！", 1, 111301, 0, 0, 3513);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ミミね\nハロウィンも\nおにいちゃんも\nだ～いすき♪", 1, 111301, 0, 0, 3514);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おひさまさんも\nハロウィンの\nおようふく\n着たいかな～？", 1, 111301, 0, 1, 3515);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ねえねえおにいちゃん\nお昼ごはんはもらった\nお菓子でもい～い？", 1, 111301, 0, 2, 3516);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "まだハロウィン…？\nうぅん…眠くないよぅ\nでもちょっと…ふぁ～", 1, 111301, 0, 3, 3517);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふかふか～♪\nおばけさんが\n中にいるのかな～？", 1, 111301, 0, 0, 3519);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "わぁ、かわいい～♪\nミミといっしょに\nあそぼ～！", 1, 111301, 0, 0, 3520);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ふわぁ～\nミミ、このにおい\nだ～いすき♪", 1, 111301, 0, 0, 3521);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかいね～♪\nおばけさんも\nポカポカしてるかな？", 1, 111301, 0, 0, 3522);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいしい～♪\nおにいちゃんも\n食べようよー！", 1, 111301, 0, 0, 3524);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "この本\nおにいちゃんと\nいっしょに\n読みたいな～", 1, 111301, 0, 0, 3525);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 12, 3, "ハッピーハロウィン♪\nえへへ、お菓子が\nいっぱいだね～！", 1, 111301, 0, 0, 3527);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ここ、好きだよ。\nみんな優しいから…", 1, 111401, 0, 0, 3529);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "なんかさみしいな", 1, 111401, 0, 0, 3530);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "知らない人怖いな", 1, 111401, 0, 0, 3531);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お部屋おっきいねー", 1, 111401, 0, 0, 3532);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ルナね…\nお昼寝したいかも", 1, 111401, 0, 0, 3533);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "おにいさん！\n今日は何して遊ぶの？", 1, 111401, 0, 0, 3534);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あのね、\nお料理教えてほしい！", 1, 111401, 0, 0, 3535);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あっ、おにいさんだ！", 1, 111401, 0, 0, 3536);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ルナは元気だよ！\nいいこだもん！", 1, 111401, 0, 0, 3537);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日は何しようかな", 1, 111401, 0, 0, 3538);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ルナと遊んでよ！", 1, 111401, 0, 0, 3539);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ねーねー、\nルナとお出かけして！", 1, 111401, 0, 0, 3540);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "おにいさんと、\n遊びたいなー！", 1, 111401, 0, 0, 3541);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふふっ！\nなんかまぶしいね！", 1, 111401, 0, 1, 3542);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ルナ、お腹空いたな", 1, 111401, 0, 2, 3543);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "どこに行こうかな？", 1, 111401, 0, 3, 3544);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ルナ、これ好きだな", 1, 111401, 0, 0, 3546);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい！　好き！", 1, 111401, 0, 0, 3547);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "なんかいい匂い！", 1, 111401, 0, 0, 3548);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかいねー", 1, 111401, 0, 0, 3549);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ふふっ\nおいしいね", 1, 111401, 0, 0, 3551);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ルナ、\n眠くなっちゃう…", 1, 111401, 0, 0, 3552);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "えへへ。あの人と\nランドソルでデート\nできたらうれしいな♪", 1, 105201, 0, 0, 3554);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "あなたとなら\nどんなことだって\nできる気がするわ♪", 1, 105201, 0, 0, 3555);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "あーあ、退屈だな\nカレでも探しに\nいこうかな", 1, 106501, 0, 0, 3556);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "この前のケンカは\n最高に燃えたなぁ\n…拳が疼いてきたぜ", 1, 106501, 0, 0, 3557);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "一体、この世界は\nどうなっちまったって\nいうんだ…？", 1, 106501, 0, 0, 3558);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "もう仕事の時間か\nボスも人使いが荒いぜ\n…ま、いいけどさ！", 1, 106501, 0, 0, 3559);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "オレたち以外に\nドラゴン族はあと何人\nいるんだろうな…", 1, 106501, 0, 0, 3560);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "カレの真剣な顔\n面白かったな\nまた遊びたいぜ", 1, 106501, 0, 0, 3561);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "どうしてカレがそばに\nいると、腹の底から\n力が湧いてくるんだ？", 1, 106501, 0, 0, 3562);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "よっす！\nなんかオイシイ話でも\nあったりしない？", 1, 106501, 0, 0, 3563);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "なあ、オレと遊ぼうぜ\n心配すんなよ。危ない\nことはよしとくからさ", 1, 106501, 0, 0, 3564);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "どうした。オレに\nケンカ売ろうってか？\n…ははは、冗談だよ！", 1, 106501, 0, 0, 3565);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ちょうど退屈してた\nところだ、特訓に\n付き合ってくれよ", 1, 106501, 0, 0, 3566);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ったくよぉ…\nオレがかわいいなんて\n冗談はもうよせよ？", 1, 106501, 0, 0, 3567);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "次の仕事も一緒に\n来るだろ？　断っても\n連れて行くけどな！", 1, 106501, 0, 0, 3568);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう！　今日の\n予定はまずケンカして\nで、その後もケンカだ", 1, 106501, 0, 1, 3569);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "よっす！\n腹ごしらえが済んだら\nオレと遊ぼうぜ！", 1, 106501, 0, 2, 3570);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜は危ないから\nあんま出歩くな？\n…だから面白えんだろ", 1, 106501, 0, 3, 3571);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "次のケンカに備えて\n今は休んでおくか…\n全力で暴れたいからな", 1, 106501, 0, 0, 3573);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ボスの飼ってる\nラーゴが、中に\n入ってるんじゃ？", 1, 106501, 0, 0, 3574);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ああ、たぎる匂いが\nする…ひと暴れ\nしたくなってきた！", 1, 106501, 0, 0, 3575);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "おおぉ…\nオレの拳もなんだか\n熱くなってきたぜ…！", 1, 106501, 0, 0, 3576);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いつでも全力で\nケンカするために\n力を蓄えないとな", 1, 106501, 0, 0, 3578);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "やっぱりな…オレが\n知ってる地図とは\nまるで違ってやがる", 1, 106501, 0, 0, 3579);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "さぁプレゼントで\n埋め尽くしてやろう！\n大いに喜ぶがいいよ！", 1, 111501, 0, 0, 3581);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "メリークリスマス☆\n聖夜の宴だ\n派手に楽しむとしよう", 1, 111501, 0, 0, 3582);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "煙突から入る？\nいいや、ワタシは\nいつでも正面からさ♪", 1, 111501, 0, 0, 3583);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "サンタクロースの\nお出ましだ！\n歓迎するがいいよ♪", 1, 111501, 0, 0, 3584);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "飾り付けが足りん！\nワタシが演出して\nやろうじゃないか！", 1, 111501, 0, 0, 3585);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "人の喜ぶ顔を見るのも\n悪くはないな…おっと\nワタシらしくないな☆", 1, 111501, 0, 0, 3586);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "プレゼントはまだか？\nワタシを喜ばせたら\nお返しは弾むぞ♪", 1, 111501, 0, 0, 3587);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ワタシを呼んだか？\n退屈な要件だったら\n覚悟しておくことだ", 1, 111501, 0, 0, 3588);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "なんだ？\nワタシへの挑戦か？\nよし、受けた♪", 1, 111501, 0, 0, 3589);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おっと、当たらんよ\nワタシの乱数聖域は\n絶対だからな…♪", 1, 111501, 0, 0, 3590);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "なんだ、オマエも\n暇なのか？\n奇遇だな、ワタシもさ", 1, 111501, 0, 0, 3591);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "なにか愉しいことでも\nしようじゃないか\nさぁ、何をする？", 1, 111501, 0, 0, 3592);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "こうもワタシに\n気安く触れるのは\nオマエくらいだよ…♪", 1, 111501, 0, 0, 3593);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝だろうと関係ない！\nさぁ愉しく苛烈に\n騒ごうじゃないか♪", 1, 111501, 0, 1, 3594);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "調子の出てくる時間だ\nしっかりワタシを\n愉しませてくれよ♪", 1, 111501, 0, 2, 3595);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "眠いなどと言わせんぞ\nまだまだ一日は\n終わらんからな！", 1, 111501, 0, 3, 3596);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "いい具合じゃないか\nこのまま持って帰って\nしまおうか…♪", 1, 111501, 0, 0, 3598);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "なかなか愛らしい\n造形をしているな？\nワタシには負けるがな", 1, 111501, 0, 0, 3599);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ほう、悪くない香りだ\n戦いの匂いをうまく\n隠してくれそうだ…♪", 1, 111501, 0, 0, 3600);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "体が温まってくると\nひと暴れしたくなるな", 1, 111501, 0, 0, 3601);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ワタシの舌は厳しいぞ\n…ふーむ、なるほど\n認めざるをえんな", 1, 111501, 0, 0, 3603);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "クリスティーナさんは\n知識の収集も\n欠かさないんだよ", 1, 111501, 0, 0, 3604);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 14, 3, "これは驚いたな\nだがもっと、もっとだ\nワタシを退屈させるな", 1, 111501, 0, 0, 3606);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 15, 3, "こんな戯れだって\n軽くこなしてしまう\nクリスティーナさんさ", 1, 111501, 0, 0, 3607);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "メリークリスマス！\nさあ、パーティーを\n盛り上げるよ！", 1, 111601, 0, 0, 3608);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "衣装一つで全然\n気分が違うね！\n最高のクリスマスに\nなりそうだよ！", 1, 111601, 0, 0, 3609);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ツリーのてっぺんの\n星って、なんだか\n欲しくなるんだよね", 1, 111601, 0, 0, 3610);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "めいっぱい\nクリスマスを楽しむよ\n遊びだって本気\nなんだからね！", 1, 111601, 0, 0, 3611);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "赤、白、緑、金\nクリスマスカラー\nってお洒落だよね", 1, 111601, 0, 0, 3612);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "雪、降らないかな？\nホワイトクリスマス\nってちょっと\n憧れるなぁ", 1, 111601, 0, 0, 3613);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "キミと過ごすこの\n楽しい時間がずーっと\n続けばいいのにな", 1, 111601, 0, 0, 3614);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "クリスマスライブ\nチケット用意するから\n絶対来てよね！", 1, 111601, 0, 0, 3615);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "カンパーイ！\nジュースだけど\nちょっと大人の\n気分だね", 1, 111601, 0, 0, 3616);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "クリスマス衣装どう？\nかわいいでしょ\nあっ、どこ見てるの！", 1, 111601, 0, 0, 3617);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ねえ、後で街に\n行こうよ\n大きなツリーを\n一緒に見たいんだ♪", 1, 111601, 0, 0, 3618);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ねえ、ダンスの練習に\n付き合ってくれない？\n大丈夫、手取り足取り\n教えてあげるから♪", 1, 111601, 0, 0, 3619);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "来年のクリスマスも\n隣にキミが\nいてくれたら\nうれしいのにな", 1, 111601, 0, 0, 3620);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "クリスマスって朝から\nドキドキしちゃうね\nなんだか子どもみたい", 1, 111601, 0, 1, 3621);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "パーティーの準備も\n大分進んだね\n一息ついて\nランチにしよっか", 1, 111601, 0, 2, 3622);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "静かな夜だね\n心臓の音まで\n聞こえちゃいそう…", 1, 111601, 0, 3, 3623);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "あ～、この絶妙な\n柔らかさ…\nいい仕事してるなぁ…", 1, 111601, 0, 0, 3625);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "アイドル顔負けの\nかわいさ、ズルい！\nでもかわいい！", 1, 111601, 0, 0, 3626);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ん～、落ち着くなぁ\n今日はゆっくり\n眠れそうだよ", 1, 111601, 0, 0, 3627);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ぬくぬく～\nどうしよう、ここから\n動きたくないなぁ", 1, 111601, 0, 0, 3628);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ダンスの練習もしたし\nちょっとくらいなら\nいいよね！", 1, 111601, 0, 0, 3630);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "アイドルといえど\nかわいいだけじゃダメ\n知識も必要だよね", 1, 111601, 0, 0, 3631);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 14, 3, "面白ーい！\nこの演出、ライブでも\nできないかな？", 1, 111601, 0, 0, 3633);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 15, 3, "もふもふ～♪\n寒い日には最高の\n抱き心地だね！", 1, 111601, 0, 0, 3634);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "彼ともっとお話し\nしたいな…もう少し\n補習を増やそうかしら", 1, 101801, 0, 0, 3635);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "君のこともっともっと\n教えて欲しいな。私に\n補習授業してくれる？", 1, 101801, 0, 0, 3636);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この姿ならあやつも\n子ども扱いできまい！\n…じゃがなぜか、少し\n物足りないような…", 1, 111701, 0, 0, 3637);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "時間もあるし、\n聖夜の宴の\n準備をするかのう♪", 1, 111701, 0, 0, 3638);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "…わらわの知る聖夜と\n随分違うが、宴は宴\n楽しませて\nもらおうかのう♪", 1, 111701, 0, 0, 3639);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "大人の姿で\nできること…ふむ\n少しあやつを\nからかってやるか♪", 1, 111701, 0, 0, 3640);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "…クリスマスは\n恋人たちの夜！？\nち、近頃の若いもんは\n破廉恥なのじゃ！", 1, 111701, 0, 0, 3641);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "…あやつがおらんと、\n宴も物足りぬな\n…馬鹿者が\n早く帰ってこい…", 1, 111701, 0, 0, 3642);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "誰も見ておらぬな…？\n…よし、あやつへの\nプレゼントを\n準備するとしようか！", 1, 111701, 0, 0, 3643);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "クリスマスの\nチキンにケーキ…\nべ、別に楽しみになど\nしておらぬぞ！", 1, 111701, 0, 0, 3644);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "この姿では、わらわの\n頭をなでるのは\n難しかろう…べ、\n別に残念ではないわ！", 1, 111701, 0, 0, 3645);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "メリー\nクリスマスじゃ！\nさあ、わらわのために\n宴の準備をするのじゃ", 1, 111701, 0, 0, 3646);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "そんなにこの衣装が\n気になるのか？\n…だったら、直に\n触ってみるがよい♪", 1, 111701, 0, 0, 3647);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "いつもと逆に、お主を\n子ども扱いしてやるか\nほれ、膝枕をしてやる\nからそばに来い♪", 1, 111701, 0, 0, 3648);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "…せ、聖夜の予定は\n空けておくのじゃぞ？\nなんでって…\nな、なんでもじゃ！", 1, 111701, 0, 0, 3649);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "もう朝か…聖夜の宴が\n楽しみで…ではなく！\n準備のせいで、\nあまり眠れんかったぞ", 1, 111701, 0, 1, 3650);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "…ずっと雪が\n降っておれば、\n陽光が強いこの時間も\n怯えずにすむのにのう", 1, 111701, 0, 2, 3651);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "時は来た…\nさあ眷属よ！\nわらわと共に、\n聖夜の宴を楽しもうぞ", 1, 111701, 0, 3, 3652);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "良い椅子ではないか\nここから聖夜の宴を\n眺めるのもよいかもな", 1, 111701, 0, 0, 3654);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "か、かわい…こほん\nなかなか良い\nデザインをしておるな", 1, 111701, 0, 0, 3655);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ふむ、良い香りじゃ\n聖夜の宴でも\nこれを使うとしよう", 1, 111701, 0, 0, 3656);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "これが癒し…はっ！\nあやうく浄化される\nところであった…", 1, 111701, 0, 0, 3657);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ニ、ニンニクは\n入っておらぬよな？\n…うむ、美味じゃ♪", 1, 111701, 0, 0, 3659);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "聖夜は恋人たちの夜…\n…き、気になるわけ\nではないが、\n少し調べてみるか", 1, 111701, 0, 0, 3660);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 14, 3, "ほう…これは面白い\n魔法の使い方じゃな\nまるで本物の\n演劇のようじゃ", 1, 111701, 0, 0, 3662);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 15, 3, "こ、この程度の\nかわいさに誘惑される\nわらわでは…\nふわもこなのじゃ～♪", 1, 111701, 0, 0, 3663);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "おせち料理も\n魔物尽くしだったり\nしないわよね！", 1, 112001, 0, 0, 3664);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "初詣で何をお祈り\nしようかしら…\n定番でいいわよね？", 1, 112001, 0, 0, 3665);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "初日の出って\n特別な感じがして\nいいわよね…", 1, 112001, 0, 0, 3666);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "寒い中並んで飲む\n甘酒って不思議なほど\nおいしいわよね", 1, 112001, 0, 0, 3667);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "羽根つきで勝負…\nあいつにだったら\n勝てるかしら？", 1, 112001, 0, 0, 3668);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "年賀状になんて書こう\n…いろいろと\n恥ずかしくなるのよね", 1, 112001, 0, 0, 3669);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "今年もあいつと\n居られること…\n結構うれしいわ", 1, 112001, 0, 0, 3670);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "何じっと\n見てんのよ？\nお年玉はあげないわよ", 1, 112001, 0, 0, 3671);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おせち料理一緒に\n食べる？\n結構おいしいわよ", 1, 112001, 0, 0, 3672);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "羽根つきで負けたら\n顔に墨塗られるのよ\n覚悟しなさい！", 1, 112001, 0, 0, 3673);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "門松飾るから\nちょっと手伝って\nくれる？", 1, 112001, 0, 0, 3674);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あんたと一緒に\n初詣行くのも悪くない\n…かも", 1, 112001, 0, 0, 3675);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "初詣で何をお祈り\nしたか？　うっさい！\n内緒よ！内緒！", 1, 112001, 0, 0, 3676);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "もう朝なの…\n正月くらいゆっくり\n寝ていたいわよね…", 1, 112001, 0, 1, 3677);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おせちに飽きたら\n次は何を食べよう\nかしら…", 1, 112001, 0, 2, 3678);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ寝ましょ\nいい初夢が見られると\nいいわね", 1, 112001, 0, 3, 3679);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "この格好でいるのも\nなかなか疲れるわね\n休憩～", 1, 112001, 0, 0, 3681);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "か、かわいい…う～ん\n鏡餅も顔を描けば\nかわいくなるかしら？", 1, 112001, 0, 0, 3682);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい匂いね\n落ち着いて\n眠れそう…", 1, 112001, 0, 0, 3683);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ここでお餅焼いたら\n一段とおいしく\nなりそうね", 1, 112001, 0, 0, 3684);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "正月に食べるものは\nなんでもおいしく\n感じちゃうわね！", 1, 112001, 0, 0, 3686);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "魔物を使わない\nおせちを\n調べておかなきゃ…", 1, 112001, 0, 0, 3687);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "新年を気持ちよく\n過ごせるように\nお掃除がんばります！", 1, 112101, 0, 0, 3689);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "神殿に通っていたら\nいつの間にか足腰が\n鍛えられたような…", 1, 112101, 0, 0, 3690);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "神殿付近は屋台も\nあるので、良い香りが\n漂ってくるんですよ～", 1, 112101, 0, 0, 3691);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "おせちを作れるように\nなれば、子どもたちも\n喜んでくれるかな…？", 1, 112101, 0, 0, 3692);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "コホォォォォォ…！\nふぅ、深呼吸すると\n落ち着きますね♪", 1, 112101, 0, 0, 3693);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お仕事以外の時も\nあなたと…い、いえ！\nなんでもないです！", 1, 112101, 0, 0, 3694);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あなたと一緒だと\nなんだかポカポカ\nしてくるんです…", 1, 112101, 0, 0, 3695);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "この格好をしていると\nなんだか神殿にいる\n気分になりますね", 1, 112101, 0, 0, 3696);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "そういえば神殿で\n甘酒をもらったんです\nあなたも飲みますか？", 1, 112101, 0, 0, 3697);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あっ、髪飾りが\nズレちゃってました！\nいけないいけない…", 1, 112101, 0, 0, 3698);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ひゃわっ！？\nく、くすぐったり\nしないでください～", 1, 112101, 0, 0, 3699);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "そ、そんなに\n見つめられると\nて、照れちゃいます…", 1, 112101, 0, 0, 3700);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "今度、私が考えた\n運気上昇のおまじない\nかけてあげますね♪", 1, 112101, 0, 0, 3701);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\n神殿のお手伝いに行く\n準備もしなきゃですね", 1, 112101, 0, 1, 3702);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼になりましたし\nご飯は私が作…\nえっ、ダメですか！？", 1, 112101, 0, 2, 3703);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "明日も早いですし\nそろそろ寝る支度を…\nふわぁ…", 1, 112101, 0, 3, 3704);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "お掃除も終わったので\n少し休憩を…ふわぁ…\n急に眠気が…", 1, 112101, 0, 0, 3706);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "新年を気持ちよく\n過ごせるようこの子も\nきれいにしましょう♪", 1, 112101, 0, 0, 3707);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "神殿のお香のような\n香りだと落ち着いて\n過ごせそうですよね", 1, 112101, 0, 0, 3708);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ぽかぽかですね～…\n甘酒も飲んで体の\n芯から温めましょう", 1, 112101, 0, 0, 3709);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "今年こそ\n料理も上手に…\nもぐもぐもぐもぐ…", 1, 112101, 0, 0, 3711);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "失敗続きだと\n逆に運が良くなる…\nほ、本当ですかぁ…？", 1, 112101, 0, 0, 3712);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "キミにならもう\nどんな私を見られても\n大丈夫かな…♪", 1, 103401, 0, 0, 3714);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "なになにどしたのぉ？\nお姉さんが撫でたげる\nこっちにきなさぁい♪", 1, 103401, 0, 0, 3715);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "わたくしの舞を\n主さまは喜んで\nくださるでしょうか…", 1, 111901, 0, 0, 3716);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "年を越したあとに\n食べるおそばも\nおいしいです", 1, 111901, 0, 0, 3717);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "甘酒を飲むと\n心まで温まる\n気がいたします", 1, 111901, 0, 0, 3718);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "主さまのために\n真心を込めたおせちを\nご用意しなくては", 1, 111901, 0, 0, 3719);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "おみくじを引くのは\nドキドキしつつも\n楽しいものです", 1, 111901, 0, 0, 3720);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "主さまの温もりは\n心まで温めてくれる\nようです", 1, 111901, 0, 0, 3721);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "うまくできなくとも\n心を込めて精いっぱい\n舞いましょう", 1, 111901, 0, 0, 3722);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "主さま、この晴れ着は\n似合っている\nでしょうか？", 1, 111901, 0, 0, 3723);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お餅はゆっくりと\n召し上がって\nくださいまし", 1, 111901, 0, 0, 3724);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "主さまのお顔の\n福笑いなら、完璧に\nできる気がいたします", 1, 111901, 0, 0, 3725);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "主さまはどのような\n初夢をご覧になった\nのでしょう？", 1, 111901, 0, 0, 3726);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "甘酒の飲み過ぎは\nいけませんよ？\nめっ、でございます", 1, 111901, 0, 0, 3727);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "二人羽織とは\nあんなにも暖かい\nものなのですね…", 1, 111901, 0, 0, 3728);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\n寒い季節の朝日は\nとても美しいですね", 1, 111901, 0, 1, 3729);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おいしくとも\n食べ過ぎは正月太りの\nもとでございます", 1, 111901, 0, 2, 3730);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "いい夢が見られるよう\n暖かくして\n眠るといたしましょう", 1, 111901, 0, 3, 3731);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふかふか…\nこのまま\n寝てしまいそうです", 1, 111901, 0, 0, 3733);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "あなたと一緒に\nお正月遊びを\n楽しんでみたいです", 1, 111901, 0, 0, 3734);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "神殿の独特な香りを\nおうちに持ち込むのは\nどうでしょうか", 1, 111901, 0, 0, 3735);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "風邪をひきませんよう\n暖かくいたしましょう", 1, 111901, 0, 0, 3736);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食べ過ぎは\n正月太りの\nもとだというのに…", 1, 111901, 0, 0, 3738);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "主さまのために\n参拝の作法を\n予習しておきましょう", 1, 111901, 0, 0, 3739);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "…この杖、変身前には\n無いパーツがあるけど\nこれはどこから…うん\n考えないようにしよう", 1, 112201, 0, 0, 3741);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "フ、フリフリの\nかわいい衣装…はっ！\n素に戻ってはダメだ！", 1, 112201, 0, 0, 3742);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "魔法探偵\nミスティ★カスミ！\n魔法の力で捜査開始！\n…練習終わりっと", 1, 112201, 0, 0, 3743);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "怪しい視線を感じる…\nまさか、近くに\n闇の力を持つ人が！？", 1, 112201, 0, 0, 3744);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "時間もあるし、\n魔法少女の修行を…\nじゃ、じゃなくて！\n探偵の仕事をしよう！", 1, 112201, 0, 0, 3745);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "助手くんとずっと\n一緒に居られるし、\n魔法少女も\n案外悪くないかも♪", 1, 112201, 0, 0, 3746);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "魔法少女の訓練のため\n助手くんの所に行こう\nかな…あ、あくまで\n訓練のためにね！", 1, 112201, 0, 0, 3747);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "…髪型が急に\n変わって驚いた？\nき、気になるなら…\n少し触ってみるかい？", 1, 112201, 0, 0, 3748);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "助手くんは魔法少女に\nなりたいのかい？\nその場合は魔法騎士…\nいや、魔法助手とか？", 1, 112201, 0, 0, 3749);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "頭に浮かぶ呪文…\n強制変身…助手くん\n魔法少女とは\n呪いか何かなのかな？", 1, 112201, 0, 0, 3750);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あ、あまり触らないで\nくれ…魔法少女になる\nと感覚が鋭くなって、\n耳も敏感に…ひゃう！", 1, 112201, 0, 0, 3751);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "や、やっぱりこの\n格好は変かな…え、\nかわいい？　じゃあ…\nいや、でも、う～ん", 1, 112201, 0, 0, 3752);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "…この変身は助手くん\nのせいでもあるんだよ\nだから…せ、責任を\n取ってもらうからね！", 1, 112201, 0, 0, 3753);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう助手くん\nさあ、そろそろ\n街のパトロールに\n行こうじゃないか！", 1, 112201, 0, 1, 3754);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "もうお昼…助手くん、\nそろそろ本業に戻ろう\n…その顔は何かな？\n私の本業は探偵だぞ！", 1, 112201, 0, 2, 3755);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜だけど、私は\nもう少し仕事をするよ\n魔法少女の強い体は\nこんなときに便利だね", 1, 112201, 0, 3, 3756);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "気持ちいい…\nこの癒しを、魔法と\n論理の二つの観点から\n解明したいね…", 1, 112201, 0, 0, 3758);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ダ、ダメ！！\nここで感情のままに\n飛びついたら、私の\nイメージがぁ～！", 1, 112201, 0, 0, 3759);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "心が安らぐ香りだね…\n…今なら、魔法少女も\nすんなりと受け入れ…\nてはダメだっ！", 1, 112201, 0, 0, 3760);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかい…\n魔法少女だろうと\n休息は必要だし、少し\n休んでいこうかな", 1, 112201, 0, 0, 3761);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "魔法少女も探偵も、\nやっぱり体が資本！\n食べられるときに\n食べておかないとね♪", 1, 112201, 0, 0, 3763);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "…魔法少女\nセリイちゃんの本は\nどこにあるのかな？", 1, 112201, 0, 0, 3764);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "魔法少女かぁ…\nせっかくだし思う存分\n体を動かしてみたいな", 1, 112301, 0, 0, 3766);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ニャットちゃん…\nこの格好を見て\n私って気づくかな？", 1, 112301, 0, 0, 3767);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ふふ…\n今日はなんだか\n調子がいいかも", 1, 112301, 0, 0, 3768);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "魔法は便利だけど\nあまり頼りすぎちゃ\nダメだよね", 1, 112301, 0, 0, 3769);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "さっき街で小さな子に\n声かけられちゃった\n照れるけどうれしいな", 1, 112301, 0, 0, 3770);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あの人がいると\nなんだかホッとする\n不思議…", 1, 112301, 0, 0, 3771);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "魔法少女になっても\nあの人への気持ちは\nずっと同じ…", 1, 112301, 0, 0, 3772);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日の私…ですか？\nはいとっても元気です\n…あなたのおかげかも", 1, 112301, 0, 0, 3773);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "よかったら魔法の\n練習に付き合って\nくれませんか？", 1, 112301, 0, 0, 3774);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あの…\nこの格好どうですか？\n似合ってると…いいな", 1, 112301, 0, 0, 3775);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "…な、なんですか？\nあまり見られると\n恥ずかしいです…", 1, 112301, 0, 0, 3776);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "私、あなたのそばに\nいられたら、それで…", 1, 112301, 0, 0, 3777);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "想い人と結ばれる\n魔法は…ひゃっ！？\n今の聞いてましたか？", 1, 112301, 0, 0, 3778);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\n今日も街の平和の\nために頑張らなきゃ", 1, 112301, 0, 1, 3779);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹すきましたね。\nあの…一緒にランチは\nいかがですか？", 1, 112301, 0, 2, 3780);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あ、もうこんな時間…\nふふ、まだこんなに\n体力が余ってるのに", 1, 112301, 0, 3, 3781);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "気持ちいい…\nこの気持ち良さは\nどんな魔法も勝てない", 1, 112301, 0, 0, 3783);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "何これ、かわいい…\nお姉ちゃんにも\n見せてあげたいな", 1, 112301, 0, 0, 3784);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ん～、いい香り\n…これ、魔法で\n出せたりしないかな？", 1, 112301, 0, 0, 3785);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったか～い\nえへへ…なんだか\nお姉ちゃんみたい", 1, 112301, 0, 0, 3786);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいしいなぁ、これ\n魔法少女になってから\n食欲旺盛かも…", 1, 112301, 0, 0, 3788);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふふ…\n魔法少女になっても\n読書はやめられないな", 1, 112301, 0, 0, 3789);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "みらくるまほりん\nくるりんぱ～♪\n王子はんのために\n花嫁修業や～♪", 1, 101001, 0, 0, 3791);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "あ、あのな王子はん\nできたらその…\nお姫さまだっこを\nお願いしてもええ…？", 1, 101001, 0, 0, 3792);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "やっぱりわたしたちの\nギルドハウスの\n居心地は最高ですね☆", 1, 180401, 0, 0, 3793);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "王宮じゃできないこと\nやっちゃいましょう♪\n例えば、えっと～…", 1, 180401, 0, 0, 3794);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "そうだ、隠しておいた\nおやつがありました！\nまだ食べられますね☆", 1, 180401, 0, 0, 3795);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ごはんはみんなで\n楽しく食べましょう！\nそれが一番の\n調味料です♪", 1, 180401, 0, 0, 3796);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "やっぱりここが、\nわたしの帰る場所です\n…ただいま☆", 1, 180401, 0, 0, 3797);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "なんだか物足りません\nきっと、あの人が隣に\nいないからですね…", 1, 180401, 0, 0, 3798);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "どこを見ても、大切な\n思い出がたくさん\n詰まっていますね♪", 1, 180401, 0, 0, 3799);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "無礼者～、なんて\n冗談です♪　どんどん\n触っちゃってください", 1, 180401, 0, 0, 3800);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ぷにぷにでしょう～？\nい～っぱい食べるのが\nぷにぷにの秘訣です！", 1, 180401, 0, 0, 3801);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "握手したいんですか？\nはい、にぎにぎ～！\nもう離しませんよ♪", 1, 180401, 0, 0, 3802);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "どうかしましたか？\n退屈してるんでしたら\nお散歩に行きましょう", 1, 180401, 0, 0, 3803);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ごはん王子♪\nわたしは王女ですから\nこれでピッタリですね", 1, 180401, 0, 0, 3804);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "大好きです～\n愛してます～\n…ほんと、ですよ♪", 1, 180401, 0, 0, 3805);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝ごはんは大事です！\n山盛りごはんを食べて\n元気いっぱいですよ☆", 1, 180401, 0, 1, 3806);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹ぺこぺこになる\n時間ですね～！\nごはん特盛、一つ！", 1, 180401, 0, 2, 3807);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お腹いっぱい、今日は\nよく眠れそうですね♪\n明日もおいしい一日を", 1, 180401, 0, 3, 3808);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "休憩休憩～♪\nお腹を休めて、次の\nごはんに挑みます…☆", 1, 180401, 0, 0, 3810);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいらしい\nぬいぐるみですね～\nキャルちゃんみたい☆", 1, 180401, 0, 0, 3811);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "すんすん…この匂い\n食欲増進の効果が\nありそうですね…？", 1, 180401, 0, 0, 3812);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "体温が上がってくると\n眠くなっちゃいます…\nほわぁ～", 1, 180401, 0, 0, 3813);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐもぐもぐもぐ\nむぐむぐむぐむぐむぐ\nはぐはぐはぐはぐはぐ", 1, 180401, 0, 0, 3815);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "教養を身に着けるには\n読書が一番です！\nえっと次のレシピは～", 1, 180401, 0, 0, 3816);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "アイドルらしくなる\nコツって、何か\nあるんでしょうか？", 1, 112401, 0, 0, 3818);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "色んな人と話すのが\n好きなんです。つい\n長くなっちゃって…", 1, 112401, 0, 0, 3819);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "アイドルを目指すって\n決めてから、毎日が\nワクワクなんです♪", 1, 112401, 0, 0, 3820);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ちゃんとストレッチ\nしておかなくっちゃ\nよいしょ、よいしょ…", 1, 112401, 0, 0, 3821);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "リンちゃんミオちゃん\n二人に負けないように\n私、頑張ります！", 1, 112401, 0, 0, 3822);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "私の笑顔は素敵だって\n誰かに褒められた…\nそんな気がするんです", 1, 112401, 0, 0, 3823);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "私たちを支えてくれる\n誰かが、ずっと一緒に\nいてくれたような…", 1, 112401, 0, 0, 3824);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "どうかしましたか？\n何か困ってるのなら\nお手伝いしますよ！", 1, 112401, 0, 0, 3825);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "みなさん個性的で\n普通じゃない人ばかり\nいるような気が…", 1, 112401, 0, 0, 3826);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日はポカポカした\nいい天気ですね～\nお散歩日和です！", 1, 112401, 0, 0, 3827);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "今、ミルクティーを\n淹れてたんです♪\nあなたも飲みますか？", 1, 112401, 0, 0, 3828);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "私の得意なこと？\nうーんなんでしょう…\nあっ、肩たたきです！", 1, 112401, 0, 0, 3829);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "生・ハム・メローン！\nあ、ライブの掛け声を\n練習してたんですよ♪", 1, 112401, 0, 0, 3830);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます！\n今日も一日\n頑張りましょうね！", 1, 112401, 0, 1, 3831);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "しっかりお昼を食べて\n午後からも張り切って\nいきましょうね♪", 1, 112401, 0, 2, 3832);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ぐっすり眠れるよう\n早めに用事を済ませて\nお休みしましょうね", 1, 112401, 0, 3, 3833);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ちょっと休んだら\nレッスンの続きも\n頑張ります！", 1, 112401, 0, 0, 3835);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "えへへ～\nふわふわもこもこで\nかわいいです～♪", 1, 112401, 0, 0, 3836);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "リラックスできる\nいい香りですね～♪", 1, 112401, 0, 0, 3837);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "わぁ、ポカポカです♪\n温かい飲み物も\nほしくなりますね", 1, 112401, 0, 0, 3838);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "レッスンしたら\nお腹が空いちゃって…\nぱくぱくもぐもぐ…", 1, 112401, 0, 0, 3840);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "レッスンに役立つ\n運動の情報とか\n載ってるでしょうか…", 1, 112401, 0, 0, 3841);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "きらきらーん☆\nよし、次のステージは\nこれで行けるかも！", 1, 112601, 0, 0, 3843);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "私の元気でみんなも\n元気になってくれたら\nうれしいな～", 1, 112601, 0, 0, 3844);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ちょっとレッスンで\n疲れちゃったかも…\nでも頑張るぞっ！", 1, 112601, 0, 0, 3845);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "晩ごはん何にしよう？\nそーだ、しぶりんにも\n聞いてみよっと！", 1, 112601, 0, 0, 3846);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "元気だから笑顔になる\nじゃなくて\n笑顔だから\n元気になるんだよね～", 1, 112601, 0, 0, 3847);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "声援を聞いてる時ね\nすごく懐かしいって\n思うことがあるんだ", 1, 112601, 0, 0, 3848);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "私を応援してくれる\n一番大事な人が\n隣にいた気がする…", 1, 112601, 0, 0, 3849);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "なになにー？\nミオちゃんに\n何か用かな～？", 1, 112601, 0, 0, 3850);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おっ、やっほー！\n元気そうだね～、キミ\n私？\nもちろん元気～！", 1, 112601, 0, 0, 3851);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ねぇねぇ、ちょっと\n遊びに行かない？\nたまには息抜きで！", 1, 112601, 0, 0, 3852);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ね、この魔物料理さ\nプリンって言い張れば\n食べてもらえそうかな", 1, 112601, 0, 0, 3853);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "えへへ\nいつもありがとねっ！\nパワーもらってるよ～", 1, 112601, 0, 0, 3854);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "どうしたどうした～\nミオちゃんの魅力に\nメロメロなのかい？", 1, 112601, 0, 0, 3855);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おっはよ～！\n一日の始まりだし\nテンション上げてこ！", 1, 112601, 0, 1, 3856);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹空いた～…\nねぇねぇ、一緒に\nお昼食べようよ～", 1, 112601, 0, 2, 3857);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふわぁ～…\n眠くなってきちゃった\nそろそろ休もっかなぁ", 1, 112601, 0, 3, 3858);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "わぁ、ふっかふか～！\nレッスンの疲れも\n吹っ飛んじゃうね☆", 1, 112601, 0, 0, 3860);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "何これ…かわいーっ！\n早くしまむーに\n教えてあげなきゃ！", 1, 112601, 0, 0, 3861);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "すぅ～…\nうんっ、これ私の\n好きな香りだな～♪", 1, 112601, 0, 0, 3862);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ポッカポカだね～♪\n…あ～ん、ここから\n動きたくないーっ！", 1, 112601, 0, 0, 3863);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "わっ、おーいしー！\nこれはテンション\n上がっちゃうね♪", 1, 112601, 0, 0, 3865);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ…\nふむふむふむ…！\n勉強になった、ブイ☆", 1, 112601, 0, 0, 3866);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "なんでドキドキが\n止まらないの…？\n騎士くんのせいだー！", 1, 100101, 0, 0, 3868);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "ドキドキしてるの\nあたしだけ、かな…\n騎士くんはどう…？", 1, 100101, 0, 0, 3869);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "騎士クンの前で\n好きって言えるように\n練習しないと…", 1, 100201, 0, 0, 3870);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "騎士クン…大好き\n…き、騎士クン！？\nなんでここに！？", 1, 100201, 0, 0, 3871);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "困ったな…\n彼が居ないだけで、\nここまで\n寂しいと思うなんて…", 1, 100301, 0, 0, 3872);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "えっと…\n今日は訓練じゃなくて\nその…二人でゆっくり\n過ごしたいな…", 1, 100301, 0, 0, 3873);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "アイドルの心構え…\nどういう風に考えると\nしっくりくるのかな", 1, 112501, 0, 0, 3874);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "何か始めるのって\nドキドキするよね\nだから最近楽しいんだ", 1, 112501, 0, 0, 3875);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "冒険者の時って毎日\nバタバタしてたけど…\n目標ができると違うね", 1, 112501, 0, 0, 3876);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "少しお腹が空いた…\nチョコレート一粒だけ\n食べようかな", 1, 112501, 0, 0, 3877);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ウヅキもミオも\n頑張ってるし\n私も負けられないね", 1, 112501, 0, 0, 3878);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "レッスンしてる時さ\n何か、誰かが足りない\nそう思うことがあるの", 1, 112501, 0, 0, 3879);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "大事なのは笑顔…\n誰か、大切な人から\n言われた気がするんだ", 1, 112501, 0, 0, 3880);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "どうしたの、何か用？\n手伝えることがあれば\nすぐに言ってね", 1, 112501, 0, 0, 3881);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "姿勢がいい？\n普段から鍛えてるし\n自然とそうなるのかも", 1, 112501, 0, 0, 3882);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "さっき散歩してたら\n犬を見かけたんだ\n人懐っこい子だったよ", 1, 112501, 0, 0, 3883);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "今から冒険？\nなら私も一緒に行くよ\n前衛は任せておいて", 1, 112501, 0, 0, 3884);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "今からレッスンに\n行くつもりだったんだ\n少し手伝ってくれる？", 1, 112501, 0, 0, 3885);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "蒼の剣を受けよ！\nえ、何してるのって？\nただの発声練習だけど", 1, 112501, 0, 0, 3886);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう、早いね\n今日は依頼もないし\nゆっくりしようかな", 1, 112501, 0, 1, 3887);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "そろそろお昼だね\nうーん、今日は\n何を食べよう…", 1, 112501, 0, 2, 3888);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もうこんな時間…\n明日も早いし\nそろそろ寝なくちゃ", 1, 112501, 0, 3, 3889);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "レッスンで疲れたし\nちょっとだけ\n休んでおこうかな", 1, 112501, 0, 0, 3891);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふふっ、かわいい\nふわふわしたものって\n撫でたくなるんだよね", 1, 112501, 0, 0, 3892);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "うん、いい香り…\nこういうものがあると\n落ち着くからいいよね", 1, 112501, 0, 0, 3893);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "温かい場所って\n居心地がいいから\nのんびりしちゃうよ", 1, 112501, 0, 0, 3894);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "レッスン頑張ったら\nすぐお腹が空くし\n食べておかないと…！", 1, 112501, 0, 0, 3896);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "アイドルのことを\nもっと勉強して\n成長しなくちゃ", 1, 112501, 0, 0, 3897);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ああ、知りたい…\nなんでもかんでも\nとにかく知りたい…", 1, 111001, 0, 0, 3899);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ああ、眠い…\nいつでもどこでも\nとにかく眠い…", 1, 111001, 0, 0, 3900);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "君、気を付けたまえ\nぼーっと歩いていると\nほわっ！　転んだ…", 1, 111001, 0, 0, 3901);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ミツキ師にいただいた\n新作サプリ…丁度よい\n被験体はいないものか", 1, 111001, 0, 0, 3902);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "サレンディア救護院に\nユニちゃん８歳として\n潜入済みだが何か？", 1, 111001, 0, 0, 3903);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "君がユニちゃんズの\n同志であること、\nぼくは誇りに思うぞ", 1, 111001, 0, 0, 3904);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ぼくは青春がしたい\nおい、君\nぼくと青春しないか", 1, 111001, 0, 0, 3905);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ああ、そうだな。\nぼくもそう思う。\n……えっ、何が？", 1, 111001, 0, 0, 3906);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "待て、話しかけるな。\n今の閃きをメモに…\n…ああっ、忘れた！", 1, 111001, 0, 0, 3907);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "歩き方が綺麗？\n何を今更なこと\n言っとるんだ君は", 1, 111001, 0, 0, 3908);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ぼくの血液型？\n大らかのОだ。\n何か異論あるかね", 1, 111001, 0, 0, 3909);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "君の声は精神に\n高揚をもたらすな…\n波形を分析したいぞ", 1, 111001, 0, 0, 3910);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "妙だな…最近\n君に話しかけられると\n心拍に乱れを覚える", 1, 111001, 0, 0, 3911);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おっと、朝だな。\nそろそろ寝るか、\n朝更かしは体に悪い", 1, 111001, 0, 1, 3912);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ふむ、昼餉時か…\n今日のランチは\nサプリ定食にしよう", 1, 111001, 0, 2, 3913);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もう夜だな、\nそろそろ起きるか。\n最高の一日にするぞ！", 1, 111001, 0, 3, 3914);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ほわぁ～\n副交感神経が…\n優位に…ふふっひ", 1, 111001, 0, 0, 3916);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいすぎるな…\nセクシーユニには\nミスマッチか…", 1, 111001, 0, 0, 3917);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ほぁあアあァぁー…\nいい香りー…\nあアァあ…イイ…", 1, 111001, 0, 0, 3918);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "炎はいいぞ\nそこには人類発展の\nドラマがある", 1, 111001, 0, 0, 3919);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "フオオー！\n次から次へと固形食物\n原理気になるー！", 1, 111001, 0, 0, 3921);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "良書は時間を忘れる\n…ふむ、今度\n布団を持ってこよう", 1, 111001, 0, 0, 3922);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "きらーん☆\nハツネちゃんに\n不可能はないのだ☆", 1, 101201, 0, 0, 3924);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "キミと一緒だと\n寝ちゃうのが\nもったいないよ～", 1, 101201, 0, 0, 3925);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ちぇるーん☆", 1, 192101, 0, 0, 3933);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ちぇる～ん☆\n今日もチエルは\nかわいいですよね～？", 1, 110901, 0, 0, 3951);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "どこかに楽しいもの\n落ちてないかにゃー", 1, 110901, 0, 0, 3952);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "チエルのオキニは\n甘々カフェラテ！\nシクヨロでぇ～す☆", 1, 110901, 0, 0, 3953);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "先輩、ひまですよね？\nチエル遊んであげても\nいいですけど？", 1, 110901, 0, 0, 3954);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "はぁー…しゅき…\nカルミナ尊い…\n一生すこれる…", 1, 110901, 0, 0, 3955);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "先輩、ひまー\nちょっとは構えよーう\nデュクシ！デュクシ！", 1, 110901, 0, 0, 3956);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "先輩なんか\nおごって～！\nてか…おごらなくても\nいいから遊んでよ…", 1, 110901, 0, 0, 3957);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "え、なんですか？\n告白だったら\n間に合ってますけど", 1, 110901, 0, 0, 3958);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ちょっと静かに！\n今ヤバかわポーズの\nイメトレ中なんです！", 1, 110901, 0, 0, 3959);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "足取りが軽やか？\nあー…ダンスとか\n習ってるからですかね", 1, 110901, 0, 0, 3960);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "チエルの血液型？\n大型新人のОです\n何か問題でも？", 1, 110901, 0, 0, 3961);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "先輩って何気に\nいい声してますよね\n言うことは変だけど", 1, 110901, 0, 0, 3962);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "え、なんですか？\nたまにだったら\n告白してもいいですよ", 1, 110901, 0, 0, 3963);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはちぇる～ん☆\nハイ、ご一緒に～？", 1, 110901, 0, 1, 3964);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今日のランチは\nどこで\n映えよっかにゃー", 1, 110901, 0, 2, 3965);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "こんばんちぇるるん☆\nハイ、ご一緒に～？", 1, 110901, 0, 3, 3966);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふかふかチエルン\n略して、ふかルン♪", 1, 110901, 0, 0, 3968);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいこの子と\nかわいいチエル！\n映ぁ～え～る～！", 1, 110901, 0, 0, 3969);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "かわいい香り～！\n持って帰ろっと！\nすぅーっ…", 1, 110901, 0, 0, 3970);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "マシュマロは\n焼かない方のが\nかわいくないです？", 1, 110901, 0, 0, 3971);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "チエル食べても\n太らない体質\nなんでぇ～！", 1, 110901, 0, 0, 3973);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "読書は好きですよ\nシンプルに楽しいし\nギャップ萌えでしょ？", 1, 110901, 0, 0, 3974);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "みんなのあたしを\n見る目が違うね\nま、気にしないけどね", 1, 112701, 0, 0, 3976);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "今日も疲れた～\nやる気ゼロだし\nもう寝ちゃおうかな", 1, 112701, 0, 0, 3977);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "あたしの代わりに誰か\n働いてくれないかね", 1, 112701, 0, 0, 3978);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "労働の後に食べる\nあんパン最高～", 1, 112701, 0, 0, 3979);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "仕事の合間に\nちょっと一息いれよ\nあ～ドングリ美味し～", 1, 112701, 0, 0, 3980);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "報酬も入ったことだし\nあいつに何か\n買ってあげようかな", 1, 112701, 0, 0, 3981);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "次の休みはあいつと\n一日中だらだら\nしたいな～", 1, 112701, 0, 0, 3982);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あたしは褒められて\n伸びるタイプなんだ\nだから褒めて褒めて", 1, 112701, 0, 0, 3983);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お、差し入れ？\n気が利くねぇ\nあんがと", 1, 112701, 0, 0, 3984);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "新しい依頼？\n今日はもう無理～\n閉店で～す", 1, 112701, 0, 0, 3985);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "サ、サボってないよ！\nちょっと休憩してた\nだけだから！", 1, 112701, 0, 0, 3986);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ねえ、一緒に\nサボろうよ？\n働き過ぎはよくないよ", 1, 112701, 0, 0, 3987);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あんたが近くにいると\n仕事の疲れも\n和らぐんだよね～", 1, 112701, 0, 0, 3988);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "はぁ…もう起きなきゃ\nつらい労働の\nはじまりだ～", 1, 112701, 0, 1, 3989);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "うぅ、お昼に\nあんパン食べ過ぎた…\n苦しい…眠い…", 1, 112701, 0, 2, 3990);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "明日は仕事ないし\nガッツリ夜ふかし\nしちゃうよ～", 1, 112701, 0, 3, 3991);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "猫みたいに\n丸くなっちゃうよ～\nあたしリスだけどね", 1, 112701, 0, 0, 3993);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふかふか～\nあたしの尻尾と\n互角とはやるね～", 1, 112701, 0, 0, 3994);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "あんパンの香りの\nアロマとか\nあればいいのにな～", 1, 112701, 0, 0, 3995);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "これは危険な\nあたたかさだね～\n労働意欲が\nなくなるよ～", 1, 112701, 0, 0, 3996);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いっぱい働いたから\nいっぱい食べても\nカロリー０だよ", 1, 112701, 0, 0, 3998);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "あたしだってたまには\n本くらい読むって\n全然似合わないけどね", 1, 112701, 0, 0, 3999);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "あたしの作った\nオリジナルたい焼き…\nあいつ、\n喜んでくれるかにゃ？", 1, 104601, 0, 0, 4001);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "あ、お帰りにゃー♪\nえへへ…キミに\nお帰りって言えるのが\nなんかうれしいにゃ♪", 1, 104601, 0, 0, 4002);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "フロンティア\nスピリッツを\nお見せするべ！", 1, 112801, 0, 0, 4003);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "この鎧を着ると\n気が引き締まる\n感じがするべ", 1, 112801, 0, 0, 4004);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "搾りたての牛乳飲んで\n今日も一日\nがんばるべ！", 1, 112801, 0, 0, 4005);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "みんなに牧場の\n乳製品を\n味わってもらいてぇべ", 1, 112801, 0, 0, 4006);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ここはいいとこだべ\nうちの動物たちも\n連れてきてやりてぇな", 1, 112801, 0, 0, 4007);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "みんなオラより\n若ぇのに働いてて\n立派だべな", 1, 112801, 0, 0, 4008);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "牧場もギルドの\nみんなもオラが\nまとめて面倒見るべ！", 1, 112801, 0, 0, 4009);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "さあ、今日も\n忙しくなるべよ\n気合入れてくべ！", 1, 112801, 0, 0, 4010);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お、あんちゃん\n丁度いいとこに！\n一緒に街に\n行商しに行くべ！", 1, 112801, 0, 0, 4011);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "牧場仕事で培った力が\n戦いでも役立つなら\n一石二鳥だべさ！", 1, 112801, 0, 0, 4012);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "疲れた時は牧場産の\nミルク菓子で\n糖分補給だべ", 1, 112801, 0, 0, 4013);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "これ、牧場の\n新製品だべ\n一番最初に味見\nしてほしいべさ", 1, 112801, 0, 0, 4014);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "働きづめはよくねぇベ\n膝枕してやっから\nこっち来るべさ", 1, 112801, 0, 0, 4015);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふぁあ…\n酪農家の朝は\n早ぇんだべ…", 1, 112801, 0, 1, 4016);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ごはんの時間だべ！\n腹が減っては酪農も\n戦いもできねえべ！", 1, 112801, 0, 2, 4017);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ寝るべ！\n健全なお笑いは\n健全な肉体に宿るべ！", 1, 112801, 0, 3, 4018);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "牧草みたいに\nふっかふかだべ～", 1, 112801, 0, 0, 4020);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "この子、目の感じが\nエリザベスに似てるべ", 1, 112801, 0, 0, 4021);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい匂いだべ～\n疲れた体に\nしみるべな～", 1, 112801, 0, 0, 4022);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったけぇな～\n牧場にも\n置いてみっかな～", 1, 112801, 0, 0, 4023);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "うまいべ！\n生産者のこだわりを\n感じるべさ", 1, 112801, 0, 0, 4025);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "酪農も戦いも\nまずは知識だべ！", 1, 112801, 0, 0, 4026);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ぴょん、ぴょん♪\nこの服のおかげで、\n体が軽いなぁ…♪", 1, 113001, 0, 0, 4028);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "今の内に部屋の\n掃除をしておこっと…\nみんな喜んで\nくれるといいなぁ", 1, 113001, 0, 0, 4029);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "耳と尻尾…この服、\n本当にウサギさん\nみたいだなぁ", 1, 113001, 0, 0, 4030);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "なんだか先輩の\n気配がするような…\n気のせいかな？", 1, 113001, 0, 0, 4031);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ウサギさんの真似を\nしたら、存在感が薄い\nとか言われないかな？\nア、アユミだぴょん♪", 1, 113001, 0, 0, 4032);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "えへへ…\nいつもとは違う先輩が\nたくさん見られて、\nうれしいな♪", 1, 113001, 0, 0, 4033);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "本の中の世界で先輩と\n旅をするなんて…\n幸せすぎて、罰が\n当たりそうだよぉ…", 1, 113001, 0, 0, 4034);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "じ～…はっ！？\nす、すみません！\n話しかけてもらえる\nなんて思ってなくて！", 1, 113001, 0, 0, 4035);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "先輩がすぐそばに…\nし、幸せすぎて\n倒れそうですぅ！", 1, 113001, 0, 0, 4036);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "え、えっと…あの…！\nうう…いざ先輩と\n向き合うと\n緊張しちゃうよぉ…", 1, 113001, 0, 0, 4037);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "はうっ！？\nしょ、正面から見る\n先輩は、私にとって\n神々しすぎますぅ…！", 1, 113001, 0, 0, 4038);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "先輩…その…\nい、一緒にご飯でも\nどうでひゅか！\nうう…またかんだぁ…", 1, 113001, 0, 0, 4039);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "せ、先輩…\nハーブティーを\n入れたんですが、\n一緒にどうですか…？", 1, 113001, 0, 0, 4040);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "せ、先輩！\nおはようございます！\nえへへ、練習通りに\nバッチリ言えたぁ♪", 1, 113001, 0, 1, 4041);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あ、もうお昼ですね\n時計を持ってて\n良かったです", 1, 113001, 0, 2, 4042);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もうこんな時間…\nお休みする\n準備をしちゃいますね", 1, 113001, 0, 3, 4043);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "あ…ちょっとだけ\n先輩の匂いがする…\nえへへ、幸せだなぁ♪", 1, 113001, 0, 0, 4045);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "…私もウサギさんの\nぬいぐるみとして、\n先輩のそばに…はっ！\n私ったら何を…！", 1, 113001, 0, 0, 4046);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "あ、いい香り…\n先輩もこういうのが\n好きなのかな？", 1, 113001, 0, 0, 4047);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "先輩が隣に\n居たら、もっと\n暖かいのになぁ…♪", 1, 113001, 0, 0, 4048);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいしい…でも、\n先輩と一緒に\n食べたら、もっと\nおいしいだろうな…", 1, 113001, 0, 0, 4050);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ウサギさんって、穴を\n掘ったりするんだ…\n私も、隠れたいときに\n掘ってみようかな？", 1, 113001, 0, 0, 4051);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ネビアさまのように\n普段からパタパタと\n飛んでみるのも…", 1, 180501, 0, 0, 4053);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ご立派になられた\n主さまと並べるように\nもっと精進しなくては", 1, 180501, 0, 0, 4054);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "月々の食費が\n増えてしまいました\n申し訳ございません…", 1, 180501, 0, 0, 4055);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ワンワンのほうの\n主さまは、この姿に\n驚くでしょうか…？", 1, 180501, 0, 0, 4056);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "主さまと離れていても\n主さまとの絆は\n胸に感じております…", 1, 180501, 0, 0, 4057);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "このギルドハウスは\nみなさまの帰る場所…\nわたくしが守ります", 1, 180501, 0, 0, 4058);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "どんな未来が\n待ち受けようとも\n主さまと添い遂げます", 1, 180501, 0, 0, 4059);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おでかけですか？\nではわたくしも\nお供いたします", 1, 180501, 0, 0, 4060);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "もう二度と主さまと\n離れたくはありません\nいつ何時も…", 1, 180501, 0, 0, 4061);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "なにかお困りごと\nでございますか？\nわたくしに何なりと…", 1, 180501, 0, 0, 4062);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "どうぞゆっくりと\n心ゆくまでくつろいで\nくださいまし、主さま", 1, 180501, 0, 0, 4063);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "この羽で主さまを\nどこまでも遠く…\n高くへと導きます", 1, 180501, 0, 0, 4064);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "主さま、主さま…♪\nおそばにいられるのが\nうれしくて、つい…", 1, 180501, 0, 0, 4065);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\n今日も一日、主さまの\nサポートをいたします", 1, 180501, 0, 1, 4066);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今日も頑張っている\n主さまに、スタンプを\nもう一つ…ポン！", 1, 180501, 0, 2, 4067);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "寝付けないのでしたら\nわたくしが子守唄を\n歌ってさしあげます", 1, 180501, 0, 3, 4068);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふかふか…\nまるで主さまのような\n柔らかさでございます", 1, 180501, 0, 0, 4070);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "あなたも一緒に\n主さまと遊びますか？\n至福の時間ですよ♪", 1, 180501, 0, 0, 4071);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "主さまの優しくて\nくすぐったい匂いが\nたまらなく恋しいです", 1, 180501, 0, 0, 4072);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "主さまの心と\n繋がったときのような\n温もりを感じます", 1, 180501, 0, 0, 4073);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いけませんっ…！\n元の姿に戻ると、また\n食べてしまうのに…！", 1, 180501, 0, 0, 4075);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "主さまに読み聞かせる\n絵本は…妖精が主役の\n物語にいたしましょう", 1, 180501, 0, 0, 4076);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "…彼のこと弟みたいに\n思ってきたのに…私、\nどうしたらいいの…？", 1, 104801, 0, 0, 4078);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "よ、予定がなかったら\nでいいんだけど…\nその、ふ、二人で\n訓練とか…どうかな？", 1, 104801, 0, 0, 4079);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "おめかしもしたし\nあとはお兄ちゃんを\n待つだけですね～♪", 1, 112901, 0, 0, 4080);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "お兄ちゃんの身の回り\nをお片付け～、これぞ\nデキる妹アピール！", 1, 112901, 0, 0, 4081);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "あ、衣装がほつれてる\nこれくらいなら自分で\n繕えますね…！", 1, 112901, 0, 0, 4082);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "この格好で歩いてると\n見慣れた景色も\n違うものに見えますね", 1, 112901, 0, 0, 4083);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "勉強もちゃんとします\n…でも、一人だと\n集中力がもちません～", 1, 112901, 0, 0, 4084);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お兄ちゃんを大好きな\n妹が待ってますよ～\n…まだですかね～", 1, 112901, 0, 0, 4085);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "お兄ちゃんのために\n掃除洗濯をする私って\nお嫁さんみたい…\n…えへへ～", 1, 112901, 0, 0, 4086);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おに～いちゃん！\n縫い物、一緒に\nやりましょうよ！", 1, 112901, 0, 0, 4087);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "かわいい妹を\n愛でたくなりました？\n思う存分、どうぞ♪", 1, 112901, 0, 0, 4088);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "わっ、ビックリした～\nもう、お兄ちゃんてば\nイタズラっ子ですね～", 1, 112901, 0, 0, 4089);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "一緒にお買い物\n行きませんか？\n妹とデートですよっ♪", 1, 112901, 0, 0, 4090);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お兄ちゃん…頭を\n撫でてくれませんか？\nえへへ、これが一番♪", 1, 112901, 0, 0, 4091);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お兄ちゃん大好き♪\n何度でも言いますよ！\nお兄ちゃん大好きっ♪", 1, 112901, 0, 0, 4092);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよ～お兄ちゃん！\n妹モーニングコールの\n時間ですよっ♪", 1, 112901, 0, 1, 4093);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "そろそろ休憩ですね！\n甘いお菓子で\n元気回復しましょ～！", 1, 112901, 0, 2, 4094);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜更かし厳禁！\nでも、もう少しだけ\nお話ししたいなぁ～", 1, 112901, 0, 3, 4095);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふっかふかですよ！\nお兄ちゃんと一緒に\n座りたいなぁ…♪", 1, 112901, 0, 0, 4097);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "このぬいぐるみの\nかわいさ…う～ん\n負けられません…！", 1, 112901, 0, 0, 4098);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "香りにも気をつかって\nパーフェクトな妹に\nなっちゃいますから！", 1, 112901, 0, 0, 4099);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "はぁ～ぬくぬくです～\nお兄ちゃんと一緒に\n温まりたいなぁ…♪", 1, 112901, 0, 0, 4100);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "これは止まりませんね\nもぐもぐ…いくらでも\n食べられちゃいます", 1, 112901, 0, 0, 4102);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "これ、デザインの\n参考になりそう！\n私にも作れるかなぁ", 1, 112901, 0, 0, 4103);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "退屈です…\nなにか楽しいことは\nないですか？", 1, 106601, 0, 0, 4105);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ギャングの仕事は\n今日はお休みです\nのんびりするですよ", 1, 106601, 0, 0, 4106);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ひうっ！　あたしの\n尻尾なんて食べても\nおいしくないですよ？", 1, 106601, 0, 0, 4107);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ふう…どうやら\n例の件はまだボスに\nバレてないですね…", 1, 106601, 0, 0, 4108);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "下克上…いい言葉です\nって、ボスに聞かれて\nないですよね…？", 1, 106601, 0, 0, 4109);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "いつか絶対ビッグに\nなってやるです！\nあたしを信じるです！", 1, 106601, 0, 0, 4110);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あたしが覚醒したら\nきっと誰よりも\n強くなるはずです！", 1, 106601, 0, 0, 4111);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "なんですか？\n貢ぎ物なら\nいつでも歓迎ですよ！", 1, 106601, 0, 0, 4112);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あたしだって\nやる時はやるですよ！\nその時がこないだけ！", 1, 106601, 0, 0, 4113);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "しりとり勝負ですか？\nいい度胸ですね、\nかかってくるです！", 1, 106601, 0, 0, 4114);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お兄さんは\nヒマそうですね…\nうらやましいです", 1, 106601, 0, 0, 4115);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "かまってほしいです？\nまったく…いいですよ\nしょうがないですね", 1, 106601, 0, 0, 4116);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お兄さんのことは\nこのあたしが\n守ってやるですよ！", 1, 106601, 0, 0, 4117);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "デキるギャングの\n朝は早いのです…\nふぁあ…", 1, 106601, 0, 1, 4118);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹がすいたですね\nなにか食べにいくです\nお兄さんのおごりで！", 1, 106601, 0, 2, 4119);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふぁあ…むにゅう…\nまだ起きてるですよぉ", 1, 106601, 0, 3, 4120);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "はぁ～…\nもうここから一歩も\n動きたくないです", 1, 106601, 0, 0, 4122);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "なかなかいいモフりを\nしてやがるです…\n舎弟にしてやるですよ", 1, 106601, 0, 0, 4123);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "なんかおしゃれな\n匂いがするですね…", 1, 106601, 0, 0, 4124);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ふふーん！\nあたしのブレスの方が\n火力は上ですね！", 1, 106601, 0, 0, 4125);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "あたしに貢ぎ物とは\nよく分かってるですね\n食べてやるですよ", 1, 106601, 0, 0, 4127);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふーむ…\nもっと楽しい本は\nないですかね？", 1, 106601, 0, 0, 4128);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "海に眠る秘宝…\n心躍る響きだ！\n早く見つけたい…！", 1, 113201, 0, 0, 4130);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "うう～、暑いぃ…\nかき氷を食べて\nすっきりしたいぃ…", 1, 113201, 0, 0, 4131);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "アターック！\nいや、もっとこう…\nアタァーック！", 1, 113201, 0, 0, 4132);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "スイカ割りで\n目を回さない\nコツはなんだろうか…", 1, 113201, 0, 0, 4133);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "せっかく海に来たのだ\n泳ぎも上手に\nなりたいものだな", 1, 113201, 0, 0, 4134);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ふっふっふ…\n疼く…疼くぞ！\n日焼けの痕が…", 1, 113201, 0, 0, 4135);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "シグルドと私は\n来世でも共にある…\nつまり我らはずっと…\nはわわ…！", 1, 113201, 0, 0, 4136);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "シグルド、私と共に\n日光浴に行かないか？\n光の力を集めよう！", 1, 113201, 0, 0, 4137);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "この格好だからできる\n必殺技を考えている\n何か案はないか？", 1, 113201, 0, 0, 4138);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "シグルド～！\nスイカを貰ったから\n一緒に食べよう！", 1, 113201, 0, 0, 4139);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "こう日差しが強いと\n日焼けしそうだな\n跡になってないか…？", 1, 113201, 0, 0, 4140);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "我らの夏の黙示録\nしっかりと記録\nしておかねばな", 1, 113201, 0, 0, 4141);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ちゃんと日焼けどめを\n塗ってもらうべき\nだったかな…？\nシ、シグルドに…！", 1, 113201, 0, 0, 4142);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝だぞシグルド！\nさぁ、日光を浴びて\n光の加護を得るのだ！", 1, 113201, 0, 1, 4143);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "もう昼食の時間か…\n私の魔力も減ったし\n早く補給しなければ", 1, 113201, 0, 2, 4144);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜でも我らの活動は\n終わることはない！\nさぁ準備を…ふわぁ…", 1, 113201, 0, 3, 4145);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "海で遊んでいると\n疲れてしまうからな\n少し休まるとしよう", 1, 113201, 0, 0, 4147);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "えへへ～、君の名前は\n何にしまちょうかね♪\n…はっ、見たのか！？", 1, 113201, 0, 0, 4148);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "心地よい香りで\n我が精神も安らぐ…", 1, 113201, 0, 0, 4149);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "別に寒くなどないぞ！\n寒くないが、ちょっと\n暖まりたくなってな！", 1, 113201, 0, 0, 4150);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐ…食べ過ぎた分は\n魔力に変換されるのだ\n…たぶん", 1, 113201, 0, 0, 4152);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "…なな、なんだ！？\nシグルドはこういう\n趣味なのか…！？", 1, 113201, 0, 0, 4153);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "むむ、この乗り心地…\nいざゆかん、\nシードラゴンよ！", 1, 113201, 0, 0, 4155);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "疾風の冥姫の名に\nふさわしき\n深海の玉座よ…\nふああ…柔らかい～", 1, 113201, 0, 0, 4156);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この姿でいると\nわたしもお姫様に\nなれた気がする…♪", 1, 180201, 0, 0, 4157);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "お腹空いてきちゃった\nまずは買い出しに…\n…変身解かなくちゃ！", 1, 180201, 0, 0, 4158);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "胸のところが空いてて\nスースーするの\nまだ慣れないな…", 1, 180201, 0, 0, 4159);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "治癒魔法に使ってた\n魔力を攻撃魔法に…\n頭の中でも練習練習", 1, 180201, 0, 0, 4160);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "何もできなかった\nわたしから、少しは\n変われたのかな…？", 1, 180201, 0, 0, 4161);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "騎士クン…\n今どこにいるの…？\n…会いたいな", 1, 180201, 0, 0, 4162);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "離れてても分かるよ…\n温かい力で騎士クンに\n守られてるの", 1, 180201, 0, 0, 4163);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "わたしが戦えてるのは\n騎士クンのおかげだよ\nいつもありがとう！", 1, 180201, 0, 0, 4164);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹空いてそう…？\n…内緒で作ったおやつ\n騎士クンも食べる？", 1, 180201, 0, 0, 4165);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ひゃうっ！　え！？\nせ、背中はダメ～！\n言ってから触って～！", 1, 180201, 0, 0, 4166);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "この格好、どうかな？\nえ？　似合ってる…？\n本当？　…うれしい！", 1, 180201, 0, 0, 4167);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "かわいい？　そうだね\nひらひらが…わたし？\nええっ、そ、そんな！", 1, 180201, 0, 0, 4168);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "騎士クン、これからも\nずっと…わたしの\nそばにいてください", 1, 180201, 0, 0, 4169);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝からこんなに\n食べる日が来るなんて\n思ってなかったよ…", 1, 180201, 0, 1, 4170);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼を作らなくちゃ\n騎士クン、一緒に\nお料理してみる？", 1, 180201, 0, 2, 4171);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "騎士クン、もう眠い？\n眠るまで、わたしが\nずっとそばにいるね", 1, 180201, 0, 3, 4172);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "攻撃参加するからこそ\n適度に体を休めるのは\n大切だよね！", 1, 180201, 0, 0, 4174);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい…騎士クンと\nシェフィちゃんにも\nプレゼントしたいな", 1, 180201, 0, 0, 4175);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り～…\nあれ？　お腹が空いて\nきちゃった…！？", 1, 180201, 0, 0, 4176);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "温かい…\n騎士クンがくれる\n力みたい…", 1, 180201, 0, 0, 4177);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ぱくっ、\nあむ、はむっ…\nううぅ～…やっぱり\n手が止まらないよぉ～", 1, 180201, 0, 0, 4179);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "新しく覚えたいな…\nみんなで食べられる\n大皿向けの料理♪", 1, 180201, 0, 0, 4180);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "お姉ちゃんの愛\nこのままじゃ\nあふれちゃうよ…♪", 1, 104901, 0, 0, 4182);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "弟くん♪\n弟くんっ♪\nおっとうっとくんっ♪", 1, 104901, 0, 0, 4183);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "泳ぐのもいいけど\n今日は砂浜で\nのんびりしようかね", 1, 113101, 0, 0, 4184);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "さてと\nちょっくらひと泳ぎ\n行ってくるかね", 1, 113101, 0, 0, 4185);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "あっついねぇ…\nうちわがないと\nしんどいったらないよ", 1, 113101, 0, 0, 4186);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "冷たすぎる飲み物で\n体を冷やさないよう\n気をつけないと…", 1, 113101, 0, 0, 4187);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "夏はあっという間だし\n悔いがないように\n楽しまないとね", 1, 113101, 0, 0, 4188);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "きっとこの夏は\nアタシにとって大事な\n想い出になるね…", 1, 113101, 0, 0, 4189);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "…前に比べたら\nアタシたちの距離も\n近づいたみたいだね", 1, 113101, 0, 0, 4190);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "もし暇なら\n今日も笹舟釣り\n一緒にどうだい？", 1, 113101, 0, 0, 4191);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お前さん、釣りに\n興味が湧いたなら今度\n道具を見に行こうよ", 1, 113101, 0, 0, 4192);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今から砂浜に行くんだ\nお前さんも一緒に\n散歩するかい？", 1, 113101, 0, 0, 4193);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "え、日焼け跡？\nおや…本当だ\nすぐ焼けちまうねえ", 1, 113101, 0, 0, 4194);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ひゃっ！？\nちょっと！\n日焼け跡をいきなり\n触らないでおくれ！", 1, 113101, 0, 0, 4195);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お前さんは、その…\nアタシと一緒にいて\n楽しかったかい？", 1, 113101, 0, 0, 4196);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようさん\n今日も砂浜に行って\nゆっくりしようか", 1, 113101, 0, 1, 4197);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼か…\nそうだ、よかったら\n刺身定食、作ろうか？", 1, 113101, 0, 2, 4198);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜の空を見てるとさ\nなつかしい気持ちに\nなるんだよね", 1, 113101, 0, 3, 4199);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "適度に休憩して\n夏バテしないよう\n気をつけないとね", 1, 113101, 0, 0, 4201);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "あんたたちも\n海を楽しみたいって\n思っているのかね", 1, 113101, 0, 0, 4202);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ん～…香りでも\nバカンスらしさを\n楽しめるもんだね", 1, 113101, 0, 0, 4203);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "こういう格好だと\n少し冷えちまうんだよ", 1, 113101, 0, 0, 4204);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐもぐ…\n遊んだ分、お腹が\n空いちまってねぇ", 1, 113101, 0, 0, 4206);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "…ん、なんだいこの本\n催眠…うーん読めない\nナナカに聞いてみるか", 1, 113101, 0, 0, 4207);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "へえ…\nなかなかいい\n乗り心地じゃないか", 1, 113101, 0, 0, 4209);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "そうそうハマグリって\n竿でも釣れるんだよ\n知ってたかい？", 1, 113101, 0, 0, 4210);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "海を満喫しなきゃね\nちょっとひと泳ぎ\n行ってこようかな？", 1, 113301, 0, 0, 4211);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "う～ん…♪\nいつもと違った\n開放感～\nなんちゃって！", 1, 113301, 0, 0, 4212);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "今のナナカちゃんは\nたぶん水属性！", 1, 113301, 0, 0, 4213);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "水着もバッチリ！\nサイカワサイツヨ\nナナカちゃ～ん☆", 1, 113301, 0, 0, 4214);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "んっふっふ\nドキ！　水着だらけの\nギルドハウス！\nとかどうかな？", 1, 113301, 0, 0, 4215);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "そんなに見られると\nちょ～っと\n恥ずかしいかも…\nなんてねなんてね！", 1, 113301, 0, 0, 4216);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ちょっとくらい\nドキッとしてくれても\nいいのにな～、もう…", 1, 113301, 0, 0, 4217);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "水着魔法少女の\n相方がほしいなぁ～…\nね、君やってみない？", 1, 113301, 0, 0, 4218);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "いつもの格好と同じ？\nも～、わかってない！\nセクスィー度が違う！", 1, 113301, 0, 0, 4219);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "どうかなどうかな？\nこのひらひらのとこが\nかわいーかなー\nとか思うんだけど！", 1, 113301, 0, 0, 4220);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "せっかくだから\nギャルゲーイベント\nごっことか\nやってみる？", 1, 113301, 0, 0, 4221);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ナナカちゃんの\n好感度を上げたい？\nならおでかけだー！", 1, 113301, 0, 0, 4222);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "おうちで水着って\nなんだかコスプレ\nみたいで楽しいかも♪", 1, 113301, 0, 0, 4223);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おっはよーう！\n今日はバカンス日和！\n海へゴーですぞ～♪", 1, 113301, 0, 1, 4224);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ご飯どうしよ～…\nあ、ナナカちゃんと\nどっか食べに行く？", 1, 113301, 0, 2, 4225);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜は本を読むのが\n捗りまくりですな～！\n今日はなに読もっかな", 1, 113301, 0, 3, 4226);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "次のイベントもあるし\nちょっと休んで体力を\n回復しなきゃね～", 1, 113301, 0, 0, 4228);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "こういうマスコット\n私にもいたらなぁ\nいっそ作っちゃう…？", 1, 113301, 0, 0, 4229);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "水着魔法少女に\n似合う香りってのも\n考えてみよっかな♪", 1, 113301, 0, 0, 4230);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "夜になると急に冷えて\n肌寒いんだよね～…", 1, 113301, 0, 0, 4231);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "あんまり食べると\nお腹が出て…でも…\nうう、止まらない～！", 1, 113301, 0, 0, 4233);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "この催眠魔法の本\n誰にもばれないように\n保管しとかなきゃね…", 1, 113301, 0, 0, 4234);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "ゴーゴーゴーゴーゴー\nナナカちゃーん♪", 1, 113301, 0, 0, 4236);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "ナナカちゃんの\n誕生～\nなんちゃって", 1, 113301, 0, 0, 4237);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ファイトファイト☆\n一生懸命\n応援するね！", 1, 113401, 0, 0, 4238);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "みんながんばってる！\n私も応援でみんなを\n盛り上げなきゃ！", 1, 113401, 0, 0, 4239);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "もし元気のない人が\nいたら…応援で少し\nでも元気にしたいな！", 1, 113401, 0, 0, 4240);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "がんばれ～☆\nよし、発声練習OK！\n応援は、声も大事！", 1, 113401, 0, 0, 4241);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "せっかく水着なんだし\n泳いだり潜ったりして\n遊びたいな～！", 1, 113401, 0, 0, 4242);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "チアリーダーとして\nキミを精一杯\n応援したいな…！", 1, 113401, 0, 0, 4243);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "キミへの応援\nちゃんと\n届いてるかな…", 1, 113401, 0, 0, 4244);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "えへへ…今ね、\nキミへの応援歌を\n考えてたのだ～♪", 1, 113401, 0, 0, 4245);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "どうしたの？\n元気がないなら\n私が応援するよ☆", 1, 113401, 0, 0, 4246);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "がんばったあとは休憩\nしなきゃね！　私と\n一緒にお昼寝する？", 1, 113401, 0, 0, 4247);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "シオリンとおそろいの\n水着で応援…\nしてみたいなぁ～", 1, 113401, 0, 0, 4248);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "次はなにして遊ぶ？\nキミがしたいことを\n教えてよ！", 1, 113401, 0, 0, 4249);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "キミを応援\nすることができて…\n私、すごく幸せ…", 1, 113401, 0, 0, 4250);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "キミって早起き\nなんだね！　私も\n見習わなきゃ！", 1, 113401, 0, 1, 4251);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ちょっとお疲れかな？\nそれじゃあ\n応援してあげるね♪", 1, 113401, 0, 2, 4252);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "遅い時間まで\nがんばってえらいね！\nでも無理はダメだよ♪", 1, 113401, 0, 3, 4253);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ちょっとだけ休憩…\n…あう、座り心地が\n良すぎて…眠気が…", 1, 113401, 0, 0, 4255);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ここにいるみんなを\n私の応援でもっと\n元気にするのだ～！", 1, 113401, 0, 0, 4256);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "元気の出る香り～♪\nこれもうまく応援に\n活かせないかな～？", 1, 113401, 0, 0, 4257);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ぽかぽかあったまって\n元気をチャージ\nするのだ～☆", 1, 113401, 0, 0, 4258);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いっぱい食べて、\nみんなを応援する\nパワーをつけなきゃ！", 1, 113401, 0, 0, 4260);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "みんなを元気にする\n方法は…どこかに\n書いてないかなぁ…？", 1, 113401, 0, 0, 4261);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "わぁ、この子\n怪獣さんみたいで\nかわいいね～♪", 1, 113401, 0, 0, 4263);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "水着でこれに\n乗ってると海にいる\n気分になれるね！", 1, 113401, 0, 0, 4264);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "すごく忙しいけど\nとても充実した気分\nこれが青春なのかしら", 1, 113501, 0, 0, 4265);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "森の静かな雰囲気も\n海の開放的な空気も\nどちらも素敵ね～", 1, 113501, 0, 0, 4266);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "汚れたお洗濯物は\nみんなが頑張った証\nなんだか愛おしいわ", 1, 113501, 0, 0, 4267);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "みんなを見てると\n何だか私も\n走りたくなっちゃうわ", 1, 113501, 0, 0, 4268);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "せっかくの水着だし\n泳ぐ練習でも\nしてみようかしら", 1, 113501, 0, 0, 4269);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "みんな～ファイト～！\n応援するのも大事よね\n練習しておかなきゃ♪", 1, 113501, 0, 0, 4270);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "先生に教えられること\nまだまだい～っぱいね\n次は何がいいかしら♪", 1, 113501, 0, 0, 4271);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日も暑くなりそうね\nこまめな水分補給を\n忘れないでね", 1, 113501, 0, 0, 4272);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "手伝ってくれるの？\nありがとう♪\n先生、頼りにしてるわ", 1, 113501, 0, 0, 4273);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "休憩はこまめに\nとりましょうね\n無理は厳禁よ", 1, 113501, 0, 0, 4274);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "海の遊びって\nどんなのがあるの？\n先生に教えてね", 1, 113501, 0, 0, 4275);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "水着は初めてだけど\nどう？　変じゃない？\nふふ、ありがとう", 1, 113501, 0, 0, 4276);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あなたと過ごした\nこの夏は、きっと…\n忘れられない思い出ね", 1, 113501, 0, 0, 4277);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう～\n朝練前にちゃんと\nごはん食べましょうね", 1, 113501, 0, 1, 4278);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お弁当作ってきたの\n栄養いっぱい摂って\n午後も頑張ろうね", 1, 113501, 0, 2, 4279);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もうお休みしなきゃね\n先生が子守唄を歌って\nあげましょうか？", 1, 113501, 0, 3, 4280);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふふ、いい気持ちねぇ\n先生、少しだけ\n休憩しちゃおうかしら", 1, 113501, 0, 0, 4282);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "あらかわいい♪\nチームにもこういう\nマスコットが欲しいわ", 1, 113501, 0, 0, 4283);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "あら、海の香り？\n波の音まで聞こえて\nきちゃいそうだわ", 1, 113501, 0, 0, 4284);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "うふふ\nこれなら濡れた水着を\n乾かすのも簡単ね♪", 1, 113501, 0, 0, 4285);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "これ、美味しいわね♪\nでも、食べ過ぎは\n禁物よ", 1, 113501, 0, 0, 4287);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "先生だって日々勉強よ\n新しいことを知るのは\nとても楽しいわ♪", 1, 113501, 0, 0, 4288);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "あらあら、楽しいわね\nみんなもきっと\nおおはしゃぎね", 1, 113501, 0, 0, 4290);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "ふふ、これで\n夏らしい気分を\n満喫するわよ♪", 1, 113501, 0, 0, 4291);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "サンドイッチも\n作ったし、\nお兄ちゃんのお出迎え\n準備は完璧だね♪", 1, 102301, 0, 0, 4292);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "えへへ、お兄ちゃんと\nぷうきちが居てくれる\nだけで、なんだか\nうれしくなっちゃう♪", 1, 102301, 0, 0, 4293);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "少し赤くなっているな\n日焼けなんてしたのは\nいつ以来だろう", 1, 113601, 0, 0, 4294);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "この格好で\n過ごすのは\n少し勇気がいるな…", 1, 113601, 0, 0, 4295);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "暑いのは平気だが\n肌が外気に触れるの\nにはまだ慣れないな…", 1, 113601, 0, 0, 4296);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "この格好でも\n堂々としていれば\n恥ずかしくはない…\nのかな？", 1, 113601, 0, 0, 4297);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "おっと…鎧姿の時と\n重心が違うせいか\nちょっと不安定だな", 1, 113601, 0, 0, 4298);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "この水着…\n私に似合って\nいるのだろうか…？\n少年には聞きづらいな", 1, 113601, 0, 0, 4299);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "少年との\n海のバカンス…\nまた行きたい\nものだな", 1, 113601, 0, 0, 4300);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あまり見るのは\nよしてくれ…\n恥ずかしいじゃ\nないか…", 1, 113601, 0, 0, 4301);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "どうかしたのかい？\n私でよければ\n話し相手くらいには\nなろうじゃないか", 1, 113601, 0, 0, 4302);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ひゃっ！\nす、すまない\nちょっと過敏に\nなっているようだ", 1, 113601, 0, 0, 4303);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "…っくしゅん！\nすまない\n薄着には慣れて\nないものでね", 1, 113601, 0, 0, 4304);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "まあ、少年になら\n見られても…\nい、いや！\nなんでもない！", 1, 113601, 0, 0, 4305);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "私がこうして\nゆっくりできるのは\n少年がそばにいて\nくれるからだよ", 1, 113601, 0, 0, 4306);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "この時間なら\nビーチにも人は\n少ないだろうね…\n遊びに行くかい？", 1, 113601, 0, 1, 4307);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼食のお誘いかい？\nいいよ、付き合おう", 1, 113601, 0, 2, 4308);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もう夜か…\n一日が経つのは\nはやいものだね", 1, 113601, 0, 3, 4309);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "これは楽でいいな…\nいつもは鎧姿で\n家具を傷つけないか\n気を使っているからね", 1, 113601, 0, 0, 4311);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "うん…ふわふわの\n感触が\nよくわかるな…", 1, 113601, 0, 0, 4312);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いつもは\n鎧に匂いが\n移ってしまうのが\n悩みなんだよ…", 1, 113601, 0, 0, 4313);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "うーむ…\n涼しいのに暖かい\nなんだか奇妙な気分だ", 1, 113601, 0, 0, 4314);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "兜を気にせず\n食べられるのは\n楽でいいな…", 1, 113601, 0, 0, 4316);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむ…鎧がないと\nページがめくりやすい", 1, 113601, 0, 0, 4317);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "身軽でいいな…\n鎧を着ていると\n騎乗訓練の時\n馬に申し訳がなくてね", 1, 113601, 0, 0, 4319);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "貝をうまく使えば\n水中でも\n守りを固められそうだ", 1, 113601, 0, 0, 4320);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "どこをアジトと\nつなげようかな～…\nこのへんにしよっと♪", 1, 106801, 0, 0, 4321);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ここってちょっと\n変わった建物だね\n妖精がいるでしょ？", 1, 106801, 0, 0, 4322);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "色んな人を観察できて\n眼福眼福…♪", 1, 106801, 0, 0, 4323);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "家具の配置変更なら\nアタシにおまかせあれ\n…家の形は変えない？", 1, 106801, 0, 0, 4324);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "新メニューどうしよう\n思いついた人がいたら\nアタシに教えてね！", 1, 106801, 0, 0, 4325);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "少年、早く帰って\nこないかな…\nよし、迎えに行こう！", 1, 106801, 0, 0, 4326);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "結局またあちこち\n移動する日々だし…\n少年に会いたいな～", 1, 106801, 0, 0, 4327);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "どしたの少年？\nお姉さんに何でも\n相談してみな～？", 1, 106801, 0, 0, 4328);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あれをああして…\nおや少年！　ごめんね\nすぐに気づけなくて！", 1, 106801, 0, 0, 4329);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "何？　クリスが\nアタシを探してる？\n…いないって言って！", 1, 106801, 0, 0, 4330);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "よければリノちゃんと\nシズルちゃんにも\n顔を見せてあげて", 1, 106801, 0, 0, 4331);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "少年～！\nもうヘトヘトだよ～！\nお願い癒して～！", 1, 106801, 0, 0, 4332);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "…アタシが素直に\n助けてって言えるのは\n少年だけだよ", 1, 106801, 0, 0, 4333);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝だよ少年！\n爽やかな朝の\nクレープはいかが？", 1, 106801, 0, 1, 4334);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹空いたな～\nお昼のクレープ\n少年は食べる？", 1, 106801, 0, 2, 4335);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜までクレープは\nやめとけ？　ごめん\nそれだけは無理…！", 1, 106801, 0, 3, 4336);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "アタシこんなに\nゆっくりしちゃって\nいいんだっけ～？", 1, 106801, 0, 0, 4338);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "…これ\nネネカが変身\nしてないよね？", 1, 106801, 0, 0, 4339);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りだ…\n解析完了\n今度生成しようっと♪", 1, 106801, 0, 0, 4340);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "安心するな～…\nアジトに置けないから\n羨ましいよ", 1, 106801, 0, 0, 4341);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食べ物を消化するって\n仕組み、どんなものか\n気になる…", 1, 106801, 0, 0, 4343);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "速読できるけど\n本を読む時くらい\n文字にじっくり\n浸かりたいんだよね…", 1, 106801, 0, 0, 4344);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "エンジェルとして\nみんなを元気に…！\nアカリ、頑張ります♪", 1, 113701, 0, 0, 4346);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "お姉ちゃんと一緒に\nお兄ちゃんを…えへへ\nまだかな、お兄ちゃん", 1, 113701, 0, 0, 4347);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "エンジェルの音色を\n目指して、今日も\nサックスの練習です♪", 1, 113701, 0, 0, 4348);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お兄ちゃんとの特訓も\n頑張らないと…\n厳しくしてくださいね", 1, 113701, 0, 0, 4349);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "かわいいエンジェルの\n格好、お兄ちゃんなら\n喜んでくれますよね♪", 1, 113701, 0, 0, 4350);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "エンジェルの力で\nお兄ちゃんのハートも\nイチコロですよ♪", 1, 113701, 0, 0, 4351);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "アカリが一番\n元気にしたいのは\nお兄ちゃんですよ♪", 1, 113701, 0, 0, 4352);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お兄ちゃん？\n触りたいなら…\nこことかどうですか♪", 1, 113701, 0, 0, 4353);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "特訓の時間ですか？\nアカリ、楽しみに\nしてたんですよ♪", 1, 113701, 0, 0, 4354);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あ、お兄ちゃん！\nそろそろアカリと\n休憩…しませんか♪", 1, 113701, 0, 0, 4355);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "この羽、触り心地\nいいですか？　あんっ\nくすぐったいですよぉ", 1, 113701, 0, 0, 4356);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お兄ちゃんも元気に\nなりたいんですか？\nアカリにお任せです♪", 1, 113701, 0, 0, 4357);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "やんっ♪\nお兄ちゃんったら\nダイタンですね♪", 1, 113701, 0, 0, 4358);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お兄ちゃん、朝ですよ\nすっごく気持ちのいい\nお天気ですよ…♪", 1, 113701, 0, 1, 4359);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼寝しませんか\nお兄ちゃん？\nアカリの膝枕で…♪", 1, 113701, 0, 2, 4360);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜ですね、お兄ちゃん\nアカリ、なんだか胸が\nドキドキしちゃいます", 1, 113701, 0, 3, 4361);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "フカフカですね…\n隣にお兄ちゃんが\nいてくれたらなぁ…♪", 1, 113701, 0, 0, 4363);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "えへへ、アカリも\nこんな風にかわいく\nなりたいな～", 1, 113701, 0, 0, 4364);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "お兄ちゃんが好きな\n匂いなのかな？\n参考にしますね！", 1, 113701, 0, 0, 4365);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "体が火照ってきて\nなんだかアカリ…\nクラクラしちゃう…", 1, 113701, 0, 0, 4366);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "はむ、んぐ…あっ\nほっぺについちゃった\nベトベトですよぉ～", 1, 113701, 0, 0, 4368);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "エンジェルって色んな\n物語に出てきますよね\nもっと調べなくちゃ！", 1, 113701, 0, 0, 4369);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "あの方の前では\n常に気高く\nありたいですわね", 1, 103201, 0, 0, 4371);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "どんなに道に迷っても\nあなたさまの元には\n絶対に辿り着く\n自信がありますわ", 1, 103201, 0, 0, 4372);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "あんたと一緒に\nいるときが一番楽しい\n一時かもしれないわ", 1, 102801, 0, 0, 4373);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "いつかあんたと一緒に\nサレンディア救護院を\n切り盛り…なんてね♪", 1, 102801, 0, 0, 4374);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "今日も\nエンジェルとして、\nみんなの幸せの\nために頑張らないと", 1, 113801, 0, 0, 4375);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "せっかく羽が\nついてるのに\n飛べないのが残念だわ", 1, 113801, 0, 0, 4376);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "この格好、子供たちに\n妙にウケがいいわね\nま、悪くないけど", 1, 113801, 0, 0, 4377);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "や、やっぱりみんな\n注目してくるわね…\nエンジェルって珍しい\nからしかたないか", 1, 113801, 0, 0, 4378);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "エンジェルになると\n人見知りがなおる！\n…わけないか", 1, 113801, 0, 0, 4379);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "エンジェルの活動は\n大変だけど、自分が\n成長してるって\n実感がうれしいわね", 1, 113801, 0, 0, 4380);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "もし誰かの願いを\nかなえられるなら\n私はアイツの…\nって何考えてるのよ！", 1, 113801, 0, 0, 4381);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "何ボサっとしてるの！\nさあ、街に出て\n人助けするわよ！", 1, 113801, 0, 0, 4382);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "エンジェリック\nアロー！\nなんてね…え、アンタ\nいつから見てたのよ！", 1, 113801, 0, 0, 4383);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "コラ！\n羽は触らないで！\n壊れたらどうするのよ", 1, 113801, 0, 0, 4384);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "エンジェルじゃなく\nても、アンタはいつも\n人助けしてるわよね\n…ちょっと尊敬するわ", 1, 113801, 0, 0, 4385);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "この服なら他の子より\n私を見てくれるかも…\nって、な、何\n見てるのよ！", 1, 113801, 0, 0, 4386);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ね、ねえ、もし私が\n困ってたら、一番に\n駆けつけて…やっぱり\n何でもないわ！", 1, 113801, 0, 0, 4387);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう…あ、あの、\nエンジェルとして\n町に行くんだけど…\n一緒に行かない？", 1, 113801, 0, 1, 4388);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ふぅ、いいことした\n後のランチは\nおいしいわね", 1, 113801, 0, 2, 4389);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もうこんな時間…\n夜更かししてないで\n早く寝なさいよね", 1, 113801, 0, 3, 4390);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "いい座り心地ね～\nまさに天にも昇る\n心地よさだわ～", 1, 113801, 0, 0, 4392);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふふ、かわいい…\nあ、羽付けたら\nもっとかわいく\nなるんじゃないかな？", 1, 113801, 0, 0, 4393);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "はぁ～落ち着くわ～\n回復アイテムみたいで\n癒やされちゃうわ～", 1, 113801, 0, 0, 4394);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "わっ、とと…\n危ない、羽が\nこげちゃうところ\nだったわ", 1, 113801, 0, 0, 4395);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "人の役に立つのって\nすごく大変だから、\nこれでライフ回復よ！", 1, 113801, 0, 0, 4397);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "エンジェルに関する\n本はあるかしら…あ！\nこれ探してた攻略本！", 1, 113801, 0, 0, 4398);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ふっふっふ\n吸血鬼らしく\n驚かせてあげましょう", 1, 113901, 0, 0, 4400);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "獲物はどこですか～！\nう～ん、もうちょっと\n迫力が欲しいですね", 1, 113901, 0, 0, 4401);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "トリックオアトリート\n…返事がないので\nイタズラしておきます", 1, 113901, 0, 0, 4402);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ハロウィンですし\nたまには騎士さんでも\n誘ってあげますかね", 1, 113901, 0, 0, 4403);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "マントは動きに\nメリハリがついて\nいいですね", 1, 113901, 0, 0, 4404);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "色んな仮装が見られて\nやっぱりハロウィンは\n最高ですね", 1, 113901, 0, 0, 4405);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "吸血鬼らしい行動って\n噛みついたり…いや\nそれは大胆過ぎです！", 1, 113901, 0, 0, 4406);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "呼びましたか？\n手短にお願いしますよ\n忙しいんですから！", 1, 113901, 0, 0, 4407);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "え？　衣装に穴が？\nありがとうございます\n…よく見てるんですね", 1, 113901, 0, 0, 4408);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふわあ…吸血鬼の\n姿でも、眠い時は\n眠いんですよね…", 1, 113901, 0, 0, 4409);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ハロウィンってライブ\nとは違った賑やかさが\nあってワクワクします", 1, 113901, 0, 0, 4410);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "私を驚かそうとしても\n無駄ですよ！\nすぐ分かるんですから", 1, 113901, 0, 0, 4411);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "騎士さん、一緒に\nハロウィンを…いいえ\nなんでもないですっ！", 1, 113901, 0, 0, 4412);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "仕事で寝不足だから\n太陽がまぶしいです…\n私、吸血鬼っぽいかも", 1, 113901, 0, 1, 4413);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ご飯は真っ赤な…\nトマト尽くしのお弁当\nにしてみました", 1, 113901, 0, 2, 4414);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜はハロウィンが\n盛り上がる時間…\n行きますよ騎士さん！", 1, 113901, 0, 3, 4415);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "このフィット感\nどうにか服作りにも\n活かせれば…！", 1, 113901, 0, 0, 4417);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "よく出来てますね…！\nぬいぐるみの服を作る\nのも楽しそうですね！", 1, 113901, 0, 0, 4418);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい感じですね…\n服に合わせた香りって\nいうのも、いいかも…", 1, 113901, 0, 0, 4419);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "はぁ、温まりますね…\nおっと、マントに火が\n点いちゃいそうです！", 1, 113901, 0, 0, 4420);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "あぁ、美味しい～\n食べた分は、働いて\n燃焼しますからね！", 1, 113901, 0, 0, 4422);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "伝説の吸血鬼…\n夜を統べる者…\nほうほう…", 1, 113901, 0, 0, 4423);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 12, 3, "やっぱりハロウィンと\nいえばお菓子です！\nさぁ配りましょうか！", 1, 113901, 0, 0, 4425);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この格好…\nカッコイイのに\n動きやすくて\n着心地も最高ッス！", 1, 114101, 0, 0, 4427);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "キメポーズはこう…\nいやこっちのほうが…\nなやましいッス…！", 1, 114101, 0, 0, 4428);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "トリックオア\nジャスティス！\nって言ったら何か\nもらえるッスかね？", 1, 114101, 0, 0, 4429);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "新しい必殺技の\n特訓もしなくちゃ\nいけないッスね…\n忙しいッス！", 1, 114101, 0, 0, 4430);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "自分のこの姿\nトモね～ちゃんにも\nみせてあげるッス！", 1, 114101, 0, 0, 4431);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ホワイトタイガー\n参上ッス！\n今のポーズは\nキマったッス！", 1, 114101, 0, 0, 4432);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あの人と一緒だと\nほんとにヒーローに\nなれる気がするッス！", 1, 114101, 0, 0, 4433);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "どうッスか？\nこの色、自分に\n似合ってるッスかね？", 1, 114101, 0, 0, 4434);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ヒマだったら\n必殺技の特訓に\n付き合ってもらって\nいいッスか？", 1, 114101, 0, 0, 4435);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ちょうどいいところに\n来たッスね！\nこのキメポーズ\nどうッスか？", 1, 114101, 0, 0, 4436);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お！　この格好、\n気になるッスか？\nじっくり見ても\nいいッスよ♪", 1, 114101, 0, 0, 4437);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あんたも一緒に\n新しい技の練習\nどうッスか？", 1, 114101, 0, 0, 4438);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "今日もあんたと一緒に\nランドソルの平和を\n守るッスよ！", 1, 114101, 0, 0, 4439);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝ッス！\n一緒に早朝特訓\nやるッスよ！", 1, 114101, 0, 1, 4440);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼休憩ッス！\nヒーローにも\n休息は必要ッス！", 1, 114101, 0, 2, 4441);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "闇夜に映える\n白い衣装で\n平和を守るッスよ！", 1, 114101, 0, 3, 4442);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "トラも狩りの時以外は\nごろごろしてるって\n本で読んだッスよー", 1, 114101, 0, 0, 4444);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "もこもこッスね♪\nこのかわいらしさを\n守ってあげるのも\nヒーローの役目ッス！", 1, 114101, 0, 0, 4445);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい匂いッスね…\nリラックスして\n瞑想するッス！", 1, 114101, 0, 0, 4446);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "燃える炎は\nヒーローの心意気ッス\nいつまでも\n見てられるッスよ", 1, 114101, 0, 0, 4447);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…\nいっぱい食べて\n強いヒーローに\nなるッスよ！", 1, 114101, 0, 0, 4449);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ちゃんと勉強の本も\n読んでるッスよ…！\nヒーローには賢さも\n必要らしいッス！", 1, 114101, 0, 0, 4450);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 12, 3, "わわっ、お菓子が\nいっぱいッス！\nみんなで\n食べるッスよ！", 1, 114101, 0, 0, 4452);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "ワタシがチューシンと\nなった今、天下統一は\n目の前デス！", 1, 103001, 0, 0, 4454);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "もうショーグンってば\nそれはセイシツに\nすることデ～ス…", 1, 103001, 0, 0, 4455);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "女幽霊…うらめしや…\nうーん、これは\nちょっと違う気が\nするな…", 1, 114001, 0, 0, 4456);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "何だか寒気がする…\nま、まさか\nこの部屋にも幽霊が？", 1, 114001, 0, 0, 4457);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ハロウィンは楽しいね\n童心に帰ったような\n気分だよ", 1, 114001, 0, 0, 4458);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "今度のハロウィンは\nユイとヒヨリを\n誘ってみようかな", 1, 114001, 0, 0, 4459);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ハロウィンのお菓子は\nどれもかわいいね\n…一つくらいなら\nいいかな？", 1, 114001, 0, 0, 4460);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "次は彼と\nどんなハロウィンを\n過ごそうかな…", 1, 114001, 0, 0, 4461);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "こんな賑やかさも\nいいものだね\n彼といられるのなら\nなおさら…", 1, 114001, 0, 0, 4462);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "…いたずらしようと\nしてない、キミ？\nふふ、お見通しだよ", 1, 114001, 0, 0, 4463);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "え、私にもお菓子を？\nありがとう…ふふ\nうれしいものだね\nハッピーハロウィン！", 1, 114001, 0, 0, 4464);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "どうしたの？\n出かけるなら\n私も同行しようか", 1, 114001, 0, 0, 4465);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "この格好、舞踏会にも\n出られそうだね\n一曲、踊ってみる？", 1, 114001, 0, 0, 4466);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "やるからには本気で\nやらせてもらおう\nトリックオア\nトリート！", 1, 114001, 0, 0, 4467);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "他の子に目移りする\nのも分かるが、その…\nせっかくの特別な衣装\n見てほしいな", 1, 114001, 0, 0, 4468);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "寝起きの体を\n慣らしておこうか\nほら、剣を取って", 1, 114001, 0, 1, 4469);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お菓子もいいけど\nちゃんと昼食も\nとるんだよ", 1, 114001, 0, 2, 4470);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "さあ、行こうか！\nハロウィンは\nこれからが本番だよ", 1, 114001, 0, 3, 4471);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ハロウィンはまだ\nこれからだ\n一休みしようか", 1, 114001, 0, 0, 4473);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "キミたちも\n仮装に興味は\nあるかな？　…ふふ", 1, 114001, 0, 0, 4474);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りだけど\n幽霊が集まったり\nしないだろうか…？", 1, 114001, 0, 0, 4475);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "暖かい…一息ついたら\nハロウィンの\nパレードを\n見に行こうかな", 1, 114001, 0, 0, 4476);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ハロウィンを本気で\n楽しむなら\n食事もしっかり\nとっておかないとね", 1, 114001, 0, 0, 4478);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ハロウィンの\nホラー小説か…\nけ、結構\n怖いものだね…？", 1, 114001, 0, 0, 4479);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 12, 3, "お菓子がいっぱいだ…\nこういうのって\n見ているだけで心が\n躍ってしまうね", 1, 114001, 0, 0, 4481);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "こんなにかわいい\n武器で戦えるとは…\nすごいものだな\n魔法少女は", 1, 114201, 0, 0, 4483);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "決めポーズの訓練も\nしっかりやっておくか\n…誰も見ていないな？", 1, 114201, 0, 0, 4484);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "こういう格好は\nユキあたりがすごく\n似合いそうだな", 1, 114201, 0, 0, 4485);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "子どもたちにサインを\n求められてしまった…\nこれもまた私の使命！", 1, 114201, 0, 0, 4486);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "この格好は目立つな…\nいや、提督とは人々の\n視線を集めるものだ！", 1, 114201, 0, 0, 4487);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あいつと作戦会議を\nしておくか。あれで\nなかなか頼れるからな", 1, 114201, 0, 0, 4488);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あいつには私の勇姿を\nちゃんと見ていて\nほしいものだな", 1, 114201, 0, 0, 4489);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "一仕事終えたことだし\n一緒に甘いものでも\n食べに行くか？", 1, 114201, 0, 0, 4490);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "怪しげな気配がするな\n貴公も警戒を\n怠るなよ！", 1, 114201, 0, 0, 4491);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "シオリに魔法少女の\n本を借りたんだ\n一緒に読まないか？", 1, 114201, 0, 0, 4492);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "巡回の時間まで\nお茶にでもするか\n貴公も付き合うがいい", 1, 114201, 0, 0, 4493);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "貴公がサポートして\nくれるのなら心強いな\n頼りにしているぞ", 1, 114201, 0, 0, 4494);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "頭を撫でるな～！\n…まったく、貴公だけ\nだぞ、こんな風に私を\n撫でてくるのは…", 1, 114201, 0, 0, 4495);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "起きろ貴公！\n魔法少女の朝は\n早いぞ！", 1, 114201, 0, 1, 4496);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ほら、食後の\nデザートだ\nて、適度な糖分は\n体に必要なんだ！", 1, 114201, 0, 2, 4497);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふわぁ…魔法少女も…\n眠気、には…い、いや\n寝てないぞ！？", 1, 114201, 0, 3, 4498);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "任務や訓練で\n疲れた体に\nこれは効くなぁ…", 1, 114201, 0, 0, 4500);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "うむ、かわいいな\nモーラのやつを隣に\n並べようか", 1, 114201, 0, 0, 4501);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ああ、身も心も\n安らぐ…\nまるで魔法だな…", 1, 114201, 0, 0, 4502);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "この温かさ…\n愛と希望に\n通じるものがある…", 1, 114201, 0, 0, 4503);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食事の大切さは\n魔法少女も軍人も\n変わりない\nしっかり食べるんだ！", 1, 114201, 0, 0, 4505);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "魔法少女の本を\n読んでるのだが\nわ、私もこんななのか", 1, 114201, 0, 0, 4506);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "オラとあんちゃんは\nボケもツッコミも\nあうんの呼吸だべ♪", 1, 103301, 0, 0, 4508);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "あんちゃんと二人で\nネタ合わせ…初めての\n共同作業だべ♪", 1, 103301, 0, 0, 4509);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ぴっぷる！", 1, 192501, 0, 0, 4510);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ぴっぷるぴっぷる♪", 1, 192501, 0, 0, 4511);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ぴっ！", 1, 192501, 0, 0, 4512);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ぷっぷー", 1, 192501, 0, 0, 4513);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ぴぃ？", 1, 192501, 0, 0, 4514);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ぴっぷるんるん♪", 1, 192501, 0, 0, 4515);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ぷぅ！", 1, 192501, 0, 0, 4516);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ぴぴっ♪", 1, 192501, 0, 0, 4517);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ぷぅー…", 1, 192501, 0, 0, 4518);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ちゅ！", 1, 192501, 0, 1, 4519);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ぷはー", 1, 192501, 0, 2, 4520);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ぴぇー", 1, 192501, 0, 3, 4521);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "魔法少女になったら\n髪型も変わるんだね\n色々試してみようかな", 1, 114301, 0, 0, 4531);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "…煌く剣技で、\n悪を断つ！\nうん、今日も\n完璧なポーズだね♪", 1, 114301, 0, 0, 4532);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ミクマ流剣術で、\n魔法少女の技に使え\nそうなものは…よし、\n早速試してみよっと♪", 1, 114301, 0, 0, 4533);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "魔法少女になったから\nには、サインの練習も\nしないと…\nよし、頑張るぞ！", 1, 114301, 0, 0, 4534);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "魔法少女の姿はすごく\nかわいいけど…この\n姿はジュンさんたちに\n見せられないなぁ…", 1, 114301, 0, 0, 4535);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あの人は魔法少女\nのこと好きなのかな？\n…好きだったら\nうれしいな♪", 1, 114301, 0, 0, 4536);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "…やっぱり、\nあの人がいないと\n特訓に身が入らない…\n早く帰ってこないかな", 1, 114301, 0, 0, 4537);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "もし時間があるなら、\n私と街の見回りに\n行かない？", 1, 114301, 0, 0, 4538);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あ、いいところに！\n新しい魔法剣術を\n編み出したから、\n見てくれないかな？", 1, 114301, 0, 0, 4539);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "魔法少女の姿が気に\nなるのは分かるけど…\nず、ずっと見られる\nのは照れるからやめて", 1, 114301, 0, 0, 4540);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "変身ポーズ中の動き、\n少し変えた方が\nいいかな…\nあなたはどう思う？", 1, 114301, 0, 0, 4541);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "よければ、\n魔法少女の特訓に\n付き合ってくれない？\nその…二人きりでさ…", 1, 114301, 0, 0, 4542);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "私…あなただけの\n魔法少女になっても…\nふふっ、な～んてね♪", 1, 114301, 0, 0, 4543);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日もいい朝だね\nさあ、一緒に\n街の見回りに行こうか", 1, 114301, 0, 1, 4544);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "もう昼か…なにか\n食べたいものある？\n簡単なのでいいなら、\n私が作ってあげるよ", 1, 114301, 0, 2, 4545);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ休もうか\n…なんなら、添い寝\nしてあげようか？\nふふっ、冗談だよ♪", 1, 114301, 0, 3, 4546);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "これは…\n心身ともに安らぐね\nなんだか\n眠くなっちゃいそう", 1, 114301, 0, 0, 4548);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "か、かわいい…これ、\n魔法で動かせたり\nしないかな？", 1, 114301, 0, 0, 4549);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りだね\nなんだか頭が冴えて\nきたし、新しい技でも\n考えようかな", 1, 114301, 0, 0, 4550);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかいな…\nこの温もりは、\n魔法少女の魔法でも\n再現不可能だね…", 1, 114301, 0, 0, 4551);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "こ、これは…\nおいしすぎて手が\n止まらないかも", 1, 114301, 0, 0, 4553);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "この本の\nキャラの動き、\n変身ポーズの\n参考にできるかも！", 1, 114301, 0, 0, 4554);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "メリークリスマス！\nさあ、素敵な\nパーティーを始めると\nいたしましょう！", 1, 114401, 0, 0, 4556);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ふふっ、\nいくつになっても、\nやはりクリスマスは、\nワクワクしますわね♪", 1, 114401, 0, 0, 4557);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "自分で料理をしてみて\nシェフたちのすごさが\n改めて分かりましたわ", 1, 114401, 0, 0, 4558);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "何事も自分で\n体験してみると\n新しい発見が\nあるものですわね♪", 1, 114401, 0, 0, 4559);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "やはり、クリスマスは\n街が活発になり\nますわね…これは、\n絶好の商機ですわ♪", 1, 114401, 0, 0, 4560);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "他のクリスマス料理も\n作れるようになったら\nあのお方は食べて\nくださるかしら…？", 1, 114401, 0, 0, 4561);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あのお方に贈る\nプレゼント…\nこれはかなりの\n難題ですわね…", 1, 114401, 0, 0, 4562);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "メリークリスマス！\nよろしければ、一緒に\nクリスマスの準備を\nいたしませんか？", 1, 114401, 0, 0, 4563);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "まあ、クリスマスの\n飾りつけを手伝って\nいただけるのですか？\nありがとうございます", 1, 114401, 0, 0, 4564);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "クリスマスに合わせて\nあつらえた自慢の衣装\nなのですが…その、\nいかがでしょうか？", 1, 114401, 0, 0, 4565);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "幼い頃はサンタさんが\nいらっしゃるのを\n待ちわびたものです\n今は…内緒ですわ♪", 1, 114401, 0, 0, 4566);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "も、もしお時間が\nあるようでしたら、\nクリスマスの街を\n一緒に歩きませんか？", 1, 114401, 0, 0, 4567);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "来年のクリスマスも\nあのお方と一緒に\n迎えられたら…", 1, 114401, 0, 0, 4568);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "時は金なり…\nせっかくの朝ですもの\n時間を有効活用\nいたしましょう！", 1, 114401, 0, 1, 4569);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼になりましたわね\nさあ、\nパーティーの準備を\n進めますわよ！", 1, 114401, 0, 2, 4570);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "静かな夜ですわね…\nもうちょっとだけ、\nあなたさまとお話を\nしていたい気分です", 1, 114401, 0, 3, 4571);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "適度な休息は\n成功の秘訣ですわ！", 1, 114401, 0, 0, 4573);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "このかわいらしさ…\nいつまでも見て\nいられそうですわ♪", 1, 114401, 0, 0, 4574);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "人をもてなすには\nこうしたところにも\n気を配らないと\nいけませんわね", 1, 114401, 0, 0, 4575);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "暖かい…\nこういう憩いの\nひと時こそ、大事に\nしたいものですわね", 1, 114401, 0, 0, 4576);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "この奥深い味わい…\n何か隠し味など\n使われていまして？", 1, 114401, 0, 0, 4578);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "クリスマス料理の\nレシピも、\nこれだけあると\n迷ってしまいますわね", 1, 114401, 0, 0, 4579);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 14, 3, "この絵本、とっても\n面白いつくりですわね\nうちの商品に\nしたいぐらいですわ", 1, 114401, 0, 0, 4581);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 15, 3, "これだけ大きな\n着ぐるみ…\n職人の技術が\n光りますわね", 1, 114401, 0, 0, 4582);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "クリスマスといえば\nパーティーよね！\nいっぱい飲むわよ～♪", 1, 114601, 0, 0, 4583);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "私を麦しゅわだけの\n女と思ったら\n大間違いなんだから♪", 1, 114601, 0, 0, 4584);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "クリスマスらしい\n飲み物も結構いいわね\n私も今度\n作ってみようかしら", 1, 114601, 0, 0, 4585);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "暖かい部屋で飲む\n麦しゅわも\nまた格別なのよね…", 1, 114601, 0, 0, 4586);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "今日はオフの日だし\n朝から飲んでも\n怒られないわよね？", 1, 114601, 0, 0, 4587);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "クリスマスの\nデートスポットで\n彼と一緒に…ってなに\n考えてるのユカリ！？", 1, 114601, 0, 0, 4588);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "背伸びしなくても\nありのままの自分を\n受け入れてくれるって\nすごく…幸せ…", 1, 114601, 0, 0, 4589);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "大丈夫よ～\n飲んでない\n飲んでないひゃら～", 1, 114601, 0, 0, 4590);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "クリスマスは\n特別だもの\n特別な一杯を\n飲まないとね♪", 1, 114601, 0, 0, 4591);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "メリークリスマース！\nほらほらぁ\n乾杯しましょ♪", 1, 114601, 0, 0, 4592);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お姉さんの\n頼れるところ\n見せてあげるわね", 1, 114601, 0, 0, 4593);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "何かあったら\n頼ってくれても\nいいんだからね？", 1, 114601, 0, 0, 4594);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ふふ…これからも\nキミのこと…\n頼りにしちゃうからね", 1, 114601, 0, 0, 4595);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "さわやかな朝ね\n…二日酔いがないと\n朝ってこんなに\n気持ちいいのね", 1, 114601, 0, 1, 4596);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼間から飲むのって\nまた格別よね…って\nガマン、ガマンよ…", 1, 114601, 0, 2, 4597);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もうこんな時間かあ…\nあとは寝るだけだし\nちょっとくらいは…", 1, 114601, 0, 3, 4598);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ゴロゴロするのって\n最高ね～\nあとは麦しゅわが\nあればなぁ", 1, 114601, 0, 0, 4600);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "私だって…\nかわいいものは\n好きでいいわよね？", 1, 114601, 0, 0, 4601);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "んっ～…いい香りね\n日頃の疲れが\n取れる気がするわ", 1, 114601, 0, 0, 4602);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ポカポカする～\n…なんだかのどが\nかわいてきたわね", 1, 114601, 0, 0, 4603);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…労働の\n後のご飯はやっぱり\nおいしいわぁ…", 1, 114601, 0, 0, 4605);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "クリスマスデート\n完全攻略マニュアル？\n…読んでおかなくちゃ", 1, 114601, 0, 0, 4606);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 14, 3, "あら、絵が飛び出して\n見えるけど…\n酔っ払ってるせいじゃ\nないわよね…？", 1, 114601, 0, 0, 4608);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 15, 3, "いい手触りね～\nウチにもほしいけど\n麦しゅわをこぼしたら\n大変そうだわ…", 1, 114601, 0, 0, 4609);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "ヒデサイの視線\nずっと独り占め\nしてたいな～", 1, 101601, 0, 0, 4610);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "ヒデサイといるだけで\nうち、おに楽しいし！\nヒデサイもっしょ～？", 1, 101601, 0, 0, 4611);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "メリークリスマス！\nふふ、口にするだけで\n何だか楽しくなるわね", 1, 114501, 0, 0, 4612);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "いつもは子どもたちを\n見守る方だけど\n今ははしゃいでも\nいいわよね？", 1, 114501, 0, 0, 4613);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ツリーや料理\nそしてプレゼント！\nいくつになっても\nやっぱり心躍るわね♪", 1, 114501, 0, 0, 4614);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "飾り付けも料理も\nいいセンスしてるわね\n救護院のパーティーの\n参考にさせてもらうわ", 1, 114501, 0, 0, 4615);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "焼きそばパンを\nクリスマスの定番に\nするにはどうすれば…", 1, 114501, 0, 0, 4616);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "これ、あいつの\n好きそうな料理だわ\n取っといて食べさせて\nあげようかしら♪", 1, 114501, 0, 0, 4617);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あいつのプレゼント\nちょっとだけ奮発\nしたのよね…\n喜んでくれるかしら", 1, 114501, 0, 0, 4618);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "このドレス\n似合ってるかしら？\n今だけは見とれても\n許してあげるわ♪", 1, 114501, 0, 0, 4619);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "見て、このケーキ！\nおいしそうでしょ\nたまにはこんな贅沢も\nいいわよね♪", 1, 114501, 0, 0, 4620);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "料理も飲み物も\nおいしいわね！\nいっぱい食べて\n元を取らないと♪", 1, 114501, 0, 0, 4621);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "子どもたちと一緒に\n雪遊び、楽しそうね\nあんたもどう？", 1, 114501, 0, 0, 4622);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "せっかくの\nクリスマスなんだもの\nエスコート\nよろしくね♪", 1, 114501, 0, 0, 4623);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "寒い？　そう…\nなら、もっとこっち\n来ていいわよ…？", 1, 114501, 0, 0, 4624);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ほら、早く起きて？\nパーティー用の\n買い出しに\n付き合ってちょうだい", 1, 114501, 0, 1, 4625);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "パーティーの料理の\n準備をしながらお昼も\n作っておいたわ\n我ながらいい手際ね", 1, 114501, 0, 2, 4626);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "にぎやかなパーティー\nもいいけど、聖夜の\n余韻を感じるのも\n結構素敵ね", 1, 114501, 0, 3, 4627);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "いい座り心地だわ～\n腕のいい職人の仕事ね\nうちでも扱いたいわ", 1, 114501, 0, 0, 4629);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい！\n子どもたちに\nプレゼントしたら\n喜んでくれるかも", 1, 114501, 0, 0, 4630);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "華やかな香りね\nクリスマスに\nピッタリだわ", 1, 114501, 0, 0, 4631);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "寒い日にはやっぱり\nこれよね…\nはぁ、極楽極楽♪", 1, 114501, 0, 0, 4632);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "んー、おいしいわ！\n焼きそばパン味の\nものも、作れない\nかしら？", 1, 114501, 0, 0, 4634);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "たまにはのんびり\n読書でも…なんだか\nラブロマンスばかりね\nクリスマスだから？", 1, 114501, 0, 0, 4635);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 14, 3, "これ、面白いわね！\n子どもたちの\nプレゼントに\nピッタリだわ", 1, 114501, 0, 0, 4637);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 15, 3, "こんないい毛並み\n初めて見るわ…\n一体どこで手に\n入るのかしら？", 1, 114501, 0, 0, 4638);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "アタシもみんなと\n一緒に正月を\n楽しんでいいのか？", 1, 114701, 0, 0, 4639);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "今年こそ、もう少し\n身長が伸びます\nように…", 1, 114701, 0, 0, 4640);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "げっ！　お年玉が\n全然残ってないぞ！？\nそんな、嘘だろ…？", 1, 114701, 0, 0, 4641);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "大勢で過ごす\n正月か…初めてだけど\n悪くないもんだな", 1, 114701, 0, 0, 4642);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "んー…ここじゃ\n天楼覇断剣の\n出番はなさそうだな", 1, 114701, 0, 0, 4643);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "アイツらと作る\n戦い以外の思い出も\nもっと増やしたいな", 1, 114701, 0, 0, 4644);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "こんなに賑やかな\n正月は初めてだ\n…温かくて、いいな", 1, 114701, 0, 0, 4645);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "記憶がなくったって\n楽しい思い出は\n新しく作れるよな？", 1, 114701, 0, 0, 4646);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "早くでかけるぞ！\nアタシはもっと\n正月を楽しみたい！", 1, 114701, 0, 0, 4647);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "なあ、オマエはもう\nノウェムって名前\n覚えてくれたよな？", 1, 114701, 0, 0, 4648);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "この服、アタシに\n似合ってるのか？\n…そっか。\nありがとな！", 1, 114701, 0, 0, 4649);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "オマエらと見た朝日は\nきっと忘れないぞ！\n思い出ができたな！", 1, 114701, 0, 0, 4650);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "いつかオクトーも\n一緒に、みんなで\n正月を過ごせたらな…", 1, 114701, 0, 0, 4651);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝から元気だな！\nアタシもいっちょ\n見習ってみるか！", 1, 114701, 0, 1, 4652);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼飯は何にする？\n正月はうまいものが\n多くて迷うよな！", 1, 114701, 0, 2, 4653);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "いい夜だな！\nアタシと一緒に\n夜更かしを楽しむか？", 1, 114701, 0, 3, 4654);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "正月らしく、たまには\nゆっくりするのも\nいいかもな…", 1, 114701, 0, 0, 4656);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "なんだ？\nオマエも初詣に\n行きたいのか？", 1, 114701, 0, 0, 4657);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "すーはー…\n神殿のニオイがするな\nいい事ありそうだ！", 1, 114701, 0, 0, 4658);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "コイツがあれば\nうまい魚が\n焼けそうだな…", 1, 114701, 0, 0, 4659);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ううー\n食べ過ぎて帯が\nきつくなってきたぞ…", 1, 114701, 0, 0, 4661);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "おみくじって\n書いてあることが\nむずかしいんだよな…", 1, 114701, 0, 0, 4662);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "困ってる人は\nいないみたいだし…\nちょっとここで、\n特訓しようかな♪", 1, 180101, 0, 0, 4664);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "空が飛べるんだから\nもっとたくさんの人を\n助けにいけちゃう！\n…ここじゃ飛べないや", 1, 180101, 0, 0, 4665);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "炎の翼\nかっこいいなー！\nこれ、もっと大きく\nできないのかな？", 1, 180101, 0, 0, 4666);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "やっぱり変身すると\nお腹すくんだね…\n…今ならペコさんの\n食欲の理由が分かるよ", 1, 180101, 0, 0, 4667);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "色なんかは違うけど…\nマントがあるから\n騎士くんとお揃いに\nなったみたい♪", 1, 180101, 0, 0, 4668);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "…騎士くんがいないと\nなんか調子でない…\n早く会いたいよぉ…", 1, 180101, 0, 0, 4669);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "この姿になると、\n騎士くんを近くに\n感じる…なんだろ\nドキドキしちゃう…", 1, 180101, 0, 0, 4670);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "騎士くん騎士くん！\n今大丈夫？\nトレーニングメニュー\n考えるの手伝って！", 1, 180101, 0, 0, 4671);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "…うにゃっ！？\nこ、この姿になっても\n尻尾は触っちゃ\nダメー！", 1, 180101, 0, 0, 4672);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もしかして、この服が\n気になってるの？\nだったら、もっと\n近くで見ていいよ♪", 1, 180101, 0, 0, 4673);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あ、騎士くん！\n困ってる人がいないか\n見回りに行くんだけど\nついてきて欲しいな！", 1, 180101, 0, 0, 4674);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "耳に触りたいの？\nだったら頭もなでて！\nそしたら、好きなだけ\n触っていいよ♪", 1, 180101, 0, 0, 4675);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "…あたし、強くなって\n騎士くんを守るよ！\nだから…これからも\n一緒にいていい？", 1, 180101, 0, 0, 4676);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おっはよー！\nさあさあ騎士くん！\n今日も一緒に\nはりきっていこー♪", 1, 180101, 0, 1, 4677);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼、お昼～♪\n今日のご飯は何かな～\nあ、騎士くん！\n早くお昼食べ行こ！", 1, 180101, 0, 2, 4678);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日もお疲れ様ー！\n騎士くん、あたしが\nマッサージしよっか？\n結構評判なんだよ！", 1, 180101, 0, 3, 4679);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "うにゃぁ…\nこの気持ちよさ…\n溶けちゃいそう…\nにゃぁ…", 1, 180101, 0, 0, 4681);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "か、かわいい～\nこれ、なでなで\nしていいんだよね…？\nよしよし…♪", 1, 180101, 0, 0, 4682);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "とってもいい香り！\n気分も落ち着くし、\n特訓の後なんかに\nいいかもー！", 1, 180101, 0, 0, 4683);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ぬくぬくだぁ…\nなんだか、\nふにゃふにゃに\nなっちゃうよぉ…", 1, 180101, 0, 0, 4684);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "お、おいひぃ…！\nこの姿になると\nお腹すくし、すっごく\n助かっちゃった！", 1, 180101, 0, 0, 4686);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "この本で勉強して、\nぶんぶりょーどーの\n超ウルトラヒヨリに\nなっちゃうぞー！", 1, 180101, 0, 0, 4687);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "今年もみんなで\nおいしいものを\nたくさん食べたいです", 1, 111801, 0, 0, 4689);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "挑戦は大切ですよね☆\nというわけで\nおせちに魔物を…", 1, 111801, 0, 0, 4690);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "おせちは縁起物です！\n食べれば食べるほど\n幸せになるはずです！", 1, 111801, 0, 0, 4691);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "食べ物がたくさん\n入った福袋は\nないんでしょうか…？", 1, 111801, 0, 0, 4692);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "初詣で何を\nお願いしましょう…\n五穀豊穣？", 1, 111801, 0, 0, 4693);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ずっとこうして\n年の始まりを\n過ごしたいですね", 1, 111801, 0, 0, 4694);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "いつか二人きりで\n初日の出を\n見たいです", 1, 111801, 0, 0, 4695);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お餅おかわりです！\nいくらでも\n食べられますよ！", 1, 111801, 0, 0, 4696);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おせちの食材を\n取りに行きませんか？\nいい運動です☆", 1, 111801, 0, 0, 4697);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "凧揚げって\n難しいですね～\n糸が絡まっちゃいます", 1, 111801, 0, 0, 4698);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "一年の計は元旦にあり\n今年一年分の\n献立を作りましょう！", 1, 111801, 0, 0, 4699);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ほらほら！\nもっと近くで着物を\n見ていいんですよ☆", 1, 111801, 0, 0, 4700);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あなたはどんな\n初夢を見ましたか？\nわたしは…内緒です☆", 1, 111801, 0, 0, 4701);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "年明けの朝は\n心なしか\n気持ちいいですね☆", 1, 111801, 0, 1, 4702);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お雑煮のあとは\nおしるこで\nおやつタイムです！", 1, 111801, 0, 2, 4703);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あたたかくして\n幸せな初夢を\n見ましょうね", 1, 111801, 0, 3, 4704);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "はぁ～屋台巡りを\n満喫しました☆\n一休み一休み", 1, 111801, 0, 0, 4706);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "縁起のいい\nぬいぐるみを並べて\n福を呼びましょう！", 1, 111801, 0, 0, 4707);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "おしるこのアロマって\nないんでしょうか？\nそれなら作るしか…", 1, 111801, 0, 0, 4708);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ここでお餅を\n焼いたらおいしく\nなりそうですね～♪", 1, 111801, 0, 0, 4709);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいしすぎて\n食べる手が\n止まりません～", 1, 111801, 0, 0, 4711);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "新しいおせち料理の\nヒントは…なるほど…\nふむふむ…", 1, 111801, 0, 0, 4712);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "お兄ちゃんとあんな\n特訓やこんな特訓が\nしたいなぁ、えへへ♪", 1, 100601, 0, 0, 4714);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "お兄ちゃんに褒めて\nもらうと、身体が\nじぃーんと\n熱くなっちゃいます♪", 1, 100601, 0, 0, 4715);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "見目麗しい衣装に\n身を包むのも\n悪い気分では\nありませんね", 1, 115001, 0, 0, 4716);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "縁起物で\n験を担ぐというのも\nたまにはよいでしょう", 1, 115001, 0, 0, 4717);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "非効率なので\nあまり行いませんが\n私も手料理くらいは\n作れるのですよ", 1, 115001, 0, 0, 4718);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "研究のためなら\n時に遠路を超え\n実地へ赴くことも\n必要なのです", 1, 115001, 0, 0, 4719);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "トゥンヌスの\n突然変異…\n大いに興味を\nそそられますね", 1, 115001, 0, 0, 4720);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "漁師の技法も\n再現できたことで\nまた一つ、仮説が\n実証できました", 1, 115001, 0, 0, 4721);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "正月くらいは\n私ものんびりしたい\n気持ちなのですよ\n意外ですか？", 1, 115001, 0, 0, 4722);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "模倣に頼らずとも\n衣装に合わせた\n所作程度は\nできて当然です", 1, 115001, 0, 0, 4723);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お年玉の使い道は\n思いつきましたか\nゆっくり考えても\nいいのですよ", 1, 115001, 0, 0, 4724);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "トランプでも花札でも\n相手をしましょう\n手心が必要なら\nいつでも言いなさい", 1, 115001, 0, 0, 4725);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "初詣でお祈りする\n内容ですか\n…ヒミツ、として\nおきましょう", 1, 115001, 0, 0, 4726);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "私たちでオーマ中の\nトゥンヌスを\n釣り上げましょうか\n…冗談ですよ", 1, 115001, 0, 0, 4727);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "見返りを求めない願い\nそれは祈りに通じるの\nかもしれませんね", 1, 115001, 0, 0, 4728);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "…貴方がその眠たげな\n顔を洗ってくる間に、\n温かいお茶でも\n淹れておきましょう", 1, 115001, 0, 1, 4729);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "さて、本格的に\n活動を再開します\n貴方も同行しなさい\n昼食は済みましたか？", 1, 115001, 0, 2, 4730);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "私はもう少し\n作業を片付けてから\n寝ることにします\n早く眠りなさい", 1, 115001, 0, 3, 4731);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "少し休みます…\n時間が来たら\n起こすように", 1, 115001, 0, 0, 4733);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "贈り物を模倣して\n潜入…試してみる\n価値はありそうですね", 1, 115001, 0, 0, 4734);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "嗅覚から得られる\n情報量は侮れません\n動物の模倣において\n注意すべき点ですよ", 1, 115001, 0, 0, 4735);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "穏やかな炎による\nリラックス効果は\n本能によるものかも\nしれませんね", 1, 115001, 0, 0, 4736);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いかなる強者でも\n兵站、補給は\n必要なものです", 1, 115001, 0, 0, 4738);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "あらゆる学問は\n完璧な模倣のための\n大きな礎となります", 1, 115001, 0, 0, 4739);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "新たに得たこの力で\n仲間と目指す未来を\n切り拓いてみせます", 1, 115501, 0, 0, 4741);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ここは、みなさまと…\nわたくしの\n帰る場所でございます", 1, 115501, 0, 0, 4742);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "主さまも精霊の召喚を\n試してみますか？", 1, 115501, 0, 0, 4743);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "主さま、おこづかいは\n足りていますか？\n遠慮は無用ですよ", 1, 115501, 0, 0, 4744);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "この装束をまとうと\n自然と背筋が伸びる\n思いがいたします", 1, 115501, 0, 0, 4745);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "進化した精霊に\n負けぬよう\n修行に励みます", 1, 115501, 0, 0, 4746);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "仲間たちといられる\nこの幸せが、末永く\n続きますように…", 1, 115501, 0, 0, 4747);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "主さまのお手手は\n大きくて温かいですね\nぎゅっぎゅっ…ふふ♪", 1, 115501, 0, 0, 4748);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今度、主さまにも\n里に伝わる昔話を\nお話しいたしましょう", 1, 115501, 0, 0, 4749);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "里で採れた果物を\n持って参りました\n召し上がってください", 1, 115501, 0, 0, 4750);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "里のお土産を\nここのみなさまに\nお配りいたしましょう", 1, 115501, 0, 0, 4751);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "仲間と囲む食卓…この\n温もりは、みなさまの\n心の温かさなのですね", 1, 115501, 0, 0, 4752);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "主さまに名前を\n呼んでいただくと\n心が温かくなります♪", 1, 115501, 0, 0, 4753);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふふっ…主さま\n寝癖がついて\nおりますよ？", 1, 115501, 0, 1, 4754);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今日の昼食は\n里の伝統料理です\nお口に合うでしょうか", 1, 115501, 0, 2, 4755);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "主さまが眠れるよう\n安らぎの風を…\nおやすみなさいませ", 1, 115501, 0, 3, 4756);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "この癒し…\n主さまにも味わって\nいただきたい…", 1, 115501, 0, 0, 4758);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "この愛らしさ…\n精霊たちと似たものを\n感じます…♪", 1, 115501, 0, 0, 4759);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "精霊よ…この安らぐ\n香りを、隅々まで\n届けてくださいまし", 1, 115501, 0, 0, 4760);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "瞑想するのに\nちょうどよい暖かさで\nございます", 1, 115501, 0, 0, 4761);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "進化した精霊を\n使役するためにも\nよく食べて体力を…！", 1, 115501, 0, 0, 4763);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "風の精霊について\nもっと詳しく知って\nおかなければ…", 1, 115501, 0, 0, 4764);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "儀式の時を思い出して\n精霊に呼びかける…\n出ておいで～♪", 1, 115601, 0, 0, 4766);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ひゃうっ！　もう…\n急に背中を触るなんて\nいたずら好きな精霊に\n育てた覚えはないのに", 1, 115601, 0, 0, 4767);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "儀式用の衣装…\nあんまり激しい動きは\nできないよね…でも\n戦う時は気にしない！", 1, 115601, 0, 0, 4768);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "そうだ…精霊に\n騎士クンのそばで\n見守っていてって\n頼んでみようかな…", 1, 115601, 0, 0, 4769);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ふふっ、こうやって、\n楽しく精霊とお話し\nしていられる、平穏な\n日々が続くといいな", 1, 115601, 0, 0, 4770);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "き、きき、騎士クン！\nわたしと、あの…！\nうう…練習ですら\n上手く誘えないよぉ…", 1, 115601, 0, 0, 4771);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あっ、精霊が…\nふふ、応援ありがとう\nわたしの想い…いつか\n必ず伝えるね", 1, 115601, 0, 0, 4772);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "新しく覚えた料理\n作ってみたんだけど\n騎士クンも食べない？", 1, 115601, 0, 0, 4773);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "騎士クン、\n疲れてない？\nわたしと精霊で\n治療するよ？", 1, 115601, 0, 0, 4774);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もう、いたずらしない\n…騎士クン！？\nご、ごめんなさい！\n精霊だと思って！", 1, 115601, 0, 0, 4775);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "騎士クン！\n時間が合ったら、\n精霊と一緒に\nお話しない？", 1, 115601, 0, 0, 4776);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "…こういう服着るの\n初めてなんだけど…\nえっ、かわいい…？\nあ、ありがとう…！", 1, 115601, 0, 0, 4777);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "困ったことがあったら\n相談してね。わたし、\n騎士クンのためなら…\n色々できるよ、色々！", 1, 115601, 0, 0, 4778);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう騎士クン！\n今からお外で\n瞑想するんだけど…\n騎士クンもどうかな？", 1, 115601, 0, 1, 4779);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼の時間だ\nご飯ならわたしが\n用意するから\nゆっくりしてて", 1, 115601, 0, 2, 4780);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もうこんな時間…\n騎士クン、はいどうぞ\n寝る前の温かいミルク\nぐっすり眠れるよ♪", 1, 115601, 0, 3, 4781);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "…うん、落ち着く\n精霊との魔法で\nこんな風に誰かを\n安心させたいな", 1, 115601, 0, 0, 4783);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい…\n精霊も気に入ってる…\nそうだ、同じ物\n作ってあげようかな？", 1, 115601, 0, 0, 4784);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り…これ、\nうちに置いたら、\nお母さん喜ぶかも！", 1, 115601, 0, 0, 4785);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかい…\nまるで誰かが\n抱きしめてくれた\nみたい…", 1, 115601, 0, 0, 4786);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "自然の恵みに\n感謝して…\nいただきます♪", 1, 115601, 0, 0, 4788);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "もっと精霊について\n勉強して、みんなを\n守れるように\nなりたいな…", 1, 115601, 0, 0, 4789);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "アイツといると胸が\nぎゅーっとなる…\nこれってもしかして…", 1, 102201, 0, 0, 4791);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "アンタとならきっと\nどんなゲームでも…\nそ、その、たた、\n楽しいって思えるわ！", 1, 102201, 0, 0, 4792);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "色んな人と話したら\n記憶探しの手がかりが\n見つかるかも…？", 1, 106401, 0, 0, 4793);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "アイスクリームでも\n作ろうかしら？\nバニラにミントに…", 1, 106401, 0, 0, 4794);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ネビアに話しかけると\n逃げられるのよね…\nもう、襲わないのに…", 1, 106401, 0, 0, 4795);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "「コッコロさん」、\n「コッコロさん」…\n…間違えないように…", 1, 106401, 0, 0, 4796);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "最近少し太ったかも？\nきっとおいしいもの、\n食べ過ぎね…", 1, 106401, 0, 0, 4797);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ここにいると、\nとても落ち着くわ…\n自分の家、だものね", 1, 106401, 0, 0, 4798);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "みんなと一緒の時間、\nずっと記憶に残したい\n…そう思っているのよ", 1, 106401, 0, 0, 4799);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ドラゴン族って、\nそんなに珍しいの？\nあまり実感ないけど…", 1, 106401, 0, 0, 4800);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "料理、練習してるのよ\n…味見してもらえる？\n期待はしないでね", 1, 106401, 0, 0, 4801);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "頭を叩いたら、\n記憶が戻ったり\nしないかしら…？\nやらなくていいわよ？", 1, 106401, 0, 0, 4802);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "赤ちゃんみたいだった\n時のことは、忘れて…\nお願いだから…", 1, 106401, 0, 0, 4803);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ひゃんっ！？\nし、しっぽを掴むのは\nダメよ？", 1, 106401, 0, 0, 4804);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "記憶が戻っても…\n私は、あなたたちと\n一緒にいたいわ", 1, 106401, 0, 0, 4805);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう。\n寝ぐせついてるわよ？\n…ふふっ、これでよし", 1, 106401, 0, 1, 4806);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "そろそろお昼かしら？\nおいしいごはんを、\nみんなで一緒に…ね", 1, 106401, 0, 2, 4807);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もうこんな時間ね。\nそろそろ休みましょ？\n…ふわぁ…", 1, 106401, 0, 3, 4808);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふかふか、ぎゅう～…\n…あっ、これはその…\nストレッチしててっ…", 1, 106401, 0, 0, 4810);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "あまり、興味ないわ。\nけど…けど…\n…か、かわいい…", 1, 106401, 0, 0, 4811);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りね。\nとっても落ち着くわ…\n…っくしゅっ", 1, 106401, 0, 0, 4812);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "冷やす方が得意だけど\nあったかいのも、\nキライじゃないのよ", 1, 106401, 0, 0, 4813);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "別に、食いしん坊\nじゃないのよ？\nでも、もう一口だけ…", 1, 106401, 0, 0, 4815);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ん…なるほどね。\n勉強になるわ…", 1, 106401, 0, 0, 4816);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "水着の探偵か…\nちょっと恥ずかしい\n気がしてきたよ…", 1, 115701, 0, 0, 4818);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "依頼があれば\n海でも山でも\n赴くさ！", 1, 115701, 0, 0, 4819);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "今のうちに\n助手くんの秘密を…\nわ…私はなにをっ！？", 1, 115701, 0, 0, 4820);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "休暇も時には必要さ\n海でゆっくりと…\nむっ？　事件の気配！", 1, 115701, 0, 0, 4821);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "探偵の秘密道具…\n水着だと隠す\n場所がない…！", 1, 115701, 0, 0, 4822);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "そろそろ助手くんが\n現れる時間かな？\nふふっ、楽しみだね", 1, 115701, 0, 0, 4823);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "真実は私と助手くん\n二人だからこそ\n解き明かせるのさ", 1, 115701, 0, 0, 4824);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ひゃああっ！？\nわ、私の不意を突く\nとは…やるね助手くん", 1, 115701, 0, 0, 4825);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "さて、なにか気づいた\nことはあるかな？\n言ってごらん♪", 1, 115701, 0, 0, 4826);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "この感触…分かった！\n助手くんだね！\nふふっ、やっぱり♪", 1, 115701, 0, 0, 4827);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "水着…どうかな？\n探偵らしさは\n残してるつもりだけど", 1, 115701, 0, 0, 4828);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ん？　依頼かな？\n助手くんの頼みなら\nなんでもお安い御用さ", 1, 115701, 0, 0, 4829);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "助手くん、私と海に\n行かないかな\n…事件じゃないよ？", 1, 115701, 0, 0, 4830);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "珈琲でも淹れて\n目を覚ますとしよう\n一緒に飲むかい？", 1, 115701, 0, 1, 4831);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼食は済ませた？\nなにを食べたか\n当ててあげよう！", 1, 115701, 0, 2, 4832);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜は謎が深まる時間…\n闇に覆い隠された真実\n必ず暴いてみせる！", 1, 115701, 0, 3, 4833);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "さて、推理の時間だ\n…サボってないよ？\n考えてるんだからね？", 1, 115701, 0, 0, 4835);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "これはもしや、中に\n秘密のメッセージが？\n…かわいいだけだね", 1, 115701, 0, 0, 4836);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ふむ、なんだか\n頭がスッキリするね\n…閃いた！", 1, 115701, 0, 0, 4837);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ポカポカするね…\n助手くん\n君もおいでよ", 1, 115701, 0, 0, 4838);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "はむ、はむ…んぐっ\nた、食べてるところを\n見つめられると～…", 1, 115701, 0, 0, 4840);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "秘密の依頼とか\nこういう場所に\n隠したりするよね…♪", 1, 115701, 0, 0, 4841);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "これはいい乗り心地だ\n事件現場にこれで登場\n…は、やめておこう", 1, 115701, 0, 0, 4843);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "不思議な感触だね…\nでも、いい発想が\n生まれてきそうだ…♪", 1, 115701, 0, 0, 4844);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "これはあたしが\n前へ進むために\nあいつがくれた\n大切な力…！", 1, 180601, 0, 0, 4845);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "チェンジ・\nプリンセスフォーム！\n練習練習、っと", 1, 180601, 0, 0, 4846);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "もうあいつに助けて\nもらいっぱなしの\nあたしは…\n卒業しなきゃね", 1, 180601, 0, 0, 4847);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "気ままに、お気楽に\nあいつと冒険する…\nそれって幸せよね", 1, 180601, 0, 0, 4848);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "プリンセスフォーム…\nお姫様みたいね\nあたしがお姫様か…\nそっかぁ…ふふ♪", 1, 180601, 0, 0, 4849);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あいつと繋がって\n生まれたこの絆は\nあたしの宝物だわ", 1, 180601, 0, 0, 4850);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あたしの命の使い方…\n全て受け止めてくれた\nあいつにだったら…", 1, 180601, 0, 0, 4851);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふふ～ん♪\nプリンセスフォームの\n天才魔法使い\nキャル様に用かしら？", 1, 180601, 0, 0, 4852);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "これからは\nあたしの力で\nなんでもパパっと\n解決してあげるわね！", 1, 180601, 0, 0, 4853);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "魔力がみなぎってる…\nねえ、もしかして\n今のあたしって本気で\nすごいんじゃない？", 1, 180601, 0, 0, 4854);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "変身の反動で\nお腹が空いても\n魔物料理だけは\nいやだからね！？", 1, 180601, 0, 0, 4855);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ねぇ、あんたになら\nあたしの心…\n全部預けていいかも", 1, 180601, 0, 0, 4856);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あいつと一緒に\nいられたら、他には\n何も…って、あああ\nあんたいつの間に！？", 1, 180601, 0, 0, 4857);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "早起きも悪くないわね\n読みかけの魔導書\n今のうちに\n読んじゃおうかしら", 1, 180601, 0, 1, 4858);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ねぇ～お腹すいたー\nあんたなんか\n作りなさいよ\n魔物料理以外でね！", 1, 180601, 0, 2, 4859);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふぁぁ…眠すぎて\n今なら変身しても\nお腹が減らない\n自信があるわ…", 1, 180601, 0, 3, 4860);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "あー♪　最っ高！\n休んで魔力を高めて…\nあいつの役に\n立ってあげなきゃね", 1, 180601, 0, 0, 4862);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "なにこれかわいい…！\nコレクションにしたく\nなっちゃうじゃない", 1, 180601, 0, 0, 4863);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この香り…すごく\nリラックスできるわ…\nあ、いい感じの魔法\n思いついちゃったかも", 1, 180601, 0, 0, 4864);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかい…\n落ち着くわ…\nあいつの手の\nぬくもりみたいね", 1, 180601, 0, 0, 4865);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "プリンセスフォーム…\nこ、こんなに\nお腹が減るのね\n甘く見てたわ…！", 1, 180601, 0, 0, 4867);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ま、魔物料理の本！？\n誰よこんな本\n買ったの！　って…\n一人しかいないか", 1, 180601, 0, 0, 4868);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "憧れの舞踏会…\n私、きちんと\n踊れるかしら", 1, 115801, 0, 0, 4870);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "アン・ドゥ・トロワ\nアン・ドゥ・トロワ\n練習はばっちりね♪", 1, 115801, 0, 0, 4871);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "こんなにすてきな\nドレスを着られて\n本当に夢みたいだわ♪", 1, 115801, 0, 0, 4872);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "魔法はいつか解ける…\nでも、その時間は心に\n残り続けるわ♪", 1, 115801, 0, 0, 4873);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ガラスの靴は夢へ\n踏み出す魔法の道具…\n私、がんばっちゃう！", 1, 115801, 0, 0, 4874);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "舞踏会であなたと\n一緒に踊れたら\nいいのにな", 1, 115801, 0, 0, 4875);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "舞踏会に行く前に\n運命の王子様には\n出会ってるのよね", 1, 115801, 0, 0, 4876);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "どうかしら？\n私、きちんとドレス\n着られてる？", 1, 115801, 0, 0, 4877);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あなたも一緒に\n踊ってみる？\nしゃなりしゃなり♪", 1, 115801, 0, 0, 4878);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あなたにエスコート\nされてきれいなお城を\n歩いてみたいわ♪", 1, 115801, 0, 0, 4879);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "どう？　レッスンの\n成果はきちんと\n出てるかしら？", 1, 115801, 0, 0, 4880);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あなたが隣にいれば\n私も立派なお姫様に\n見えるかしら♪", 1, 115801, 0, 0, 4881);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "私にとって\n一番の魔法はあなたが\nくれる勇気よ♪", 1, 115801, 0, 0, 4882);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "さぁ！　今日も一日\n立派な淑女を目指して\nいきましょう♪", 1, 115801, 0, 1, 4883);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ごはん代わりに\nメタモルアップルを\n食べておきましょう", 1, 115801, 0, 2, 4884);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ魔法が解ける\n時間…でも淑女の\n心得は忘れないわ♪", 1, 115801, 0, 3, 4885);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "淑女にも休息は\n必要よね…少しだけ\n休ませてもらおっと", 1, 115801, 0, 0, 4887);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいものに\n囲まれた部屋も\n女の子の夢よね…", 1, 115801, 0, 0, 4888);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "すてきな香り…\nお花かしら？\n森で探してみようかな", 1, 115801, 0, 0, 4889);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "暖かい…暖炉のそばで\nおとぎ話を聞くのも\nいいわよね♪", 1, 115801, 0, 0, 4890);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "レッスンのために\n栄養補給して\nおかないと！", 1, 115801, 0, 0, 4892);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "教養を身に着ける\nことも大切よね！\nなになに…", 1, 115801, 0, 0, 4893);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "や、やっぱスカートは\n落ち着かねえな…\nなんか、\nスースーするしよ…", 1, 115901, 0, 0, 4895);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "せっかくこんな格好\nしてるし、いつもとは\n違う剣術の訓練を\nしてみるかな", 1, 115901, 0, 0, 4896);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "さて、他の連中が\n帰ってくる前に、\nなんか料理でも\n作っといてやるか", 1, 115901, 0, 0, 4897);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "こ、こんな服着てる\nわけだし、紅茶とか\n楽しんじゃっても\n変じゃないよな！", 1, 115901, 0, 0, 4898);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "暇だし運動でも…\nあ、あぶねえ！\nスカートなの忘れてた\n…誰も見てねえよな？", 1, 115901, 0, 0, 4899);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "紅茶が切れてるな…\nよし、あいつと一緒に\n買い物にでも行くか♪", 1, 115901, 0, 0, 4900);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "…あいつがいねえと、\nつまんねえな…ったく\n飯用意してやるから、\n早く帰ってこいよな…", 1, 115901, 0, 0, 4901);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あ、あんまり\nジロジロ見んなよ\n…結構、\n恥ずかしいんだからな", 1, 115901, 0, 0, 4902);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ダンスの相手は\n無理だが、\n剣の訓練なら\nいつでも付き合うぜ！", 1, 115901, 0, 0, 4903);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "この服に\n触りたいのか？\nすごい作りだし、\n気持ちは分かるぜ", 1, 115901, 0, 0, 4904);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お、いいところに！\nクッキーを焼く\nところだったんだが、\nおまえも食うか？", 1, 115901, 0, 0, 4905);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "おまえにもこういう服\n似合うんじゃねえか？\n今度あたしが\n選んでやるよ♪", 1, 115901, 0, 0, 4906);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "…おまえの前でなら、\nこういう格好を\nすんのも…\nな、なんでもねえよ！", 1, 115901, 0, 0, 4907);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝の訓練を始めるか\n時間あるなら、\nおまえも付き合えよな", 1, 115901, 0, 1, 4908);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "もうこんな時間か…\n昼飯作るけど、\nなんか\n食いたいものあるか？", 1, 115901, 0, 2, 4909);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "眠れないなら、\nホットミルク飲むか？\n体あったまって、\n眠くなると思うぜ", 1, 115901, 0, 3, 4910);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ちょっと休憩して…\nおっと、服にしわが\nできないように\nしねえとな", 1, 115901, 0, 0, 4912);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "だ、誰も\n見てねえよな？\n…よ～しよしよし、\nかわいいなおまえー♪", 1, 115901, 0, 0, 4913);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "すげぇいい香りだな\nうちの居酒屋にも…\nいや、合わねえか", 1, 115901, 0, 0, 4914);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったけぇ…\nちょっとだけなら、\n寝ちまっても\nいいよな…？", 1, 115901, 0, 0, 4915);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "これうめえな！\nたぶん材料は…よし！\nあたしも作ってみるか", 1, 115901, 0, 0, 4917);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "この本は…\n誰でも分かる作法…か\n最低限このぐらいは\n勉強しとくか…", 1, 115901, 0, 0, 4918);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "ミミがおとなに\nなっても\nおにいちゃんとは\nずーっといっしょ♪", 1, 102001, 0, 0, 4920);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "ミミとくべつなだっこ\nしてほしいな…うん！\nおひめさまだっこ～♪", 1, 102001, 0, 0, 4921);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "次はにいちゃんに\nどんなイタズラしよう\n早く会いたいな～", 1, 100401, 0, 0, 4922);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "ミソギの特別な\nイタズラ見てくれる？\nいいよねっ♪", 1, 100401, 0, 0, 4923);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "大人になったら、\nあの人と何しようかな\n…楽しみだなぁ", 1, 103601, 0, 0, 4924);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "頭を撫でないで\nください！　もう、\n少しだけ、ですからね", 1, 103601, 0, 0, 4925);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "くるくる〜♪\nうちのドレス\nかわええなぁ", 1, 116001, 0, 0, 4926);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "日差しは苦手やけど\nたまにはひなたの下で\nぽかぽかしたいわぁ", 1, 116001, 0, 0, 4927);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "外はお花が咲いてる\n久しぶりにお花を\n活けたいなぁ", 1, 116001, 0, 0, 4928);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お花をたくさん集めて\nギルドハウスに飾れば\n喜んでくれはるかな", 1, 116001, 0, 0, 4929);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "あたたかい日は\n紅茶を飲みながら\nゆっくりしたいなぁ", 1, 116001, 0, 0, 4930);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お稽古事を始めるなら\nうちに言ってな\nどんなことも教えたる", 1, 116001, 0, 0, 4931);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "うちにいろんな夢を\n見せてくれはって\nほんま、おおきにな♪", 1, 116001, 0, 0, 4932);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "王子はん\n一緒におとぎの国へ\nお散歩にいきまひょ♪", 1, 116001, 0, 0, 4933);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ふんふんふ〜ん♪\n今な、王子はんに\n花冠を作ってるんよ", 1, 116001, 0, 0, 4934);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "王子はんは\nお菓子好きどす？\nうち、作りますわ", 1, 116001, 0, 0, 4935);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "うーん。ドレスの柄は\nお花とお星さま\nどっちにしまひょか", 1, 116001, 0, 0, 4936);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "王子はんとの\n思い出が増えるたび\nうちの宝物も増えます", 1, 116001, 0, 0, 4937);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "王子はんと一緒なら\nどんな場所でも\n夢の国になりますわ", 1, 116001, 0, 0, 4938);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "夢の中におりたいけど\n王子はんに会いたくて\n起きてもうたわ♪", 1, 116001, 0, 1, 4939);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "王子はん一緒に\nアフタヌーンティー\nいかがやろか？", 1, 116001, 0, 2, 4940);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜の舞踏会…\n夢が広がるわぁ\nもちろんお相手は…♪", 1, 116001, 0, 3, 4941);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふわふわや〜\nなんや心地よぉて\n眠ってしまいそうや…", 1, 116001, 0, 0, 4943);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かいらしいなぁ\n新しいお洋服でも\n作ってあげまひょか♪", 1, 116001, 0, 0, 4944);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "お花やろうか…\nリラックスできて\nええ香りやねぇ", 1, 116001, 0, 0, 4945);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "こういう場所で\n絵本を読むと\n気分が出てええなぁ♪", 1, 116001, 0, 0, 4946);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "舞踏会を楽しむなら\nたくさん食べて\nたくさん踊りまひょ", 1, 116001, 0, 0, 4948);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "うち、この本好きや\n王子さまと結ばれる\nお姫さまのお話なんよ", 1, 116001, 0, 0, 4949);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "はぁ、宿題めんどい…\nこれは楽しくない…\nこんな青春いらない…", 1, 116301, 0, 0, 4951);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "奨学金の道は遠いなぁ\nメルクリちゃんたちが\nお金くれればいいのに", 1, 116301, 0, 0, 4952);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "アオイちゃん元気かな\nチエルに会いたくて\n泣いてるんだろうな…", 1, 116301, 0, 0, 4953);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "暇だし鏡でも見るか…\nうわ、顔良っ！\nえ誰この超絶美少女！", 1, 116301, 0, 0, 4954);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ワンツーワンツー♪\nうーん…カルミナの\n振りコピ難しいにゃー", 1, 116301, 0, 0, 4955);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "先輩も運動してます？\nチエルが一緒に走って\nあげてもいいですよ？", 1, 116301, 0, 0, 4956);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "来年のテレフェスも\n今から楽しみだなあ…\nまた一緒にお化け屋敷\n入ってくださいね", 1, 116301, 0, 0, 4957);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ちぇる～ん☆\nフェス仕様でも\nかわいいちえるん！", 1, 116301, 0, 0, 4958);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "いま話しかけないで！\n来年の聖学祭ライブの\nイメトレ中なんです！", 1, 116301, 0, 0, 4959);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "クロエ先輩のウェア姿\nめっちゃカッコよ！\n思わずおへそ触ったら\nぶたれましたけど", 1, 116301, 0, 0, 4960);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ユニ先輩の体操着姿…\nあれはあれで実に良き\n一生見てられますよね", 1, 116301, 0, 0, 4961);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "先輩って体操着持って\nないんですか？　ハ？\nチエルのを貸せと…？\nえっ…変態かな？", 1, 116301, 0, 0, 4962);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "テレフェスでは先輩も\n地味に頑張ってました\nね。まあ格好よかった\nんじゃないですか…", 1, 116301, 0, 0, 4963);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはちぇる～ん☆\nさあ今日も楽しいを\n探しに行きますよー！", 1, 116301, 0, 1, 4964);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "先輩ビッグニュース！\n今からお昼ごはん\nおごらせてあげます！", 1, 116301, 0, 2, 4965);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "こんばんちぇるるん☆\nさあ朝まで楽しいを\n探しに行きますよー！", 1, 116301, 0, 3, 4966);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "はぁ…ふかふか～…\n運動の後は…眠たく…\nなり…ま…", 1, 116301, 0, 0, 4968);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ユニ先輩に似合いそ！\nいやクロエ先輩かな？\nチエルは当然すぎて…", 1, 116301, 0, 0, 4969);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "やん、いい香り～！\nまるでチエルのために\n存在するみたい！", 1, 116301, 0, 0, 4970);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "この火を使って\n聖火リレーしましょう\n先輩、一本抜いて！", 1, 116301, 0, 0, 4971);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "あむあむ…ちゃんと\n食べないとユニ先輩\nみたいになっちゃう！", 1, 116301, 0, 0, 4973);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ…ちゃんと\n読まないとクロエ先輩\nみたいになっちゃう！", 1, 116301, 0, 0, 4974);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "今なら書ける気がする\n私の本当の\n想いを込めた\nラブソングを！", 1, 102901, 0, 0, 4976);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "輝きを増した私を\nいっぱい見てね！\n…ちょ、ちょっと\n見つめすぎだよ！", 1, 102901, 0, 0, 4977);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "テレフェスかぁー…\nあんまいい記憶ないな\nよし、忘れとこ", 1, 116201, 0, 0, 4978);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "暇だし鏡でも見るか…\nふふ～ん…いいじゃん\nあ？　何見てんだコラ", 1, 116201, 0, 0, 4979);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ワンツー、ワンツー♪\nああクソ、難しいな…\nあ？　何見てんだコラ", 1, 116201, 0, 0, 4980);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "アオイ元気してるかな\nまた絶叫したり白目\n剥いたりしてんのかな", 1, 116201, 0, 0, 4981);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ミフユねえさんが\nバイトリーダーしてる\n工場…うちも行くか…", 1, 116201, 0, 0, 4982);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "うーん…今日の晩御飯\n何にすっかなァ…\nあんたも食べてく？", 1, 116201, 0, 0, 4983);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "来年のテレフェスは\nどーなンだかねえ？\nま、一緒にまた弟の\n相手してやってよ", 1, 116201, 0, 0, 4984);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "体操着なんてフツーに\n着てもつまんないし？\nその辺センス出るよね", 1, 116201, 0, 0, 4985);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "奨学金の道、遠くね？\nアキノ先輩と仲良く\nなった方が早いかも…", 1, 116201, 0, 0, 4986);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あんた体操着は持って\nないの。ハ？　うちの\n貸せって？　いいけど\n…いや、よくねえよ", 1, 116201, 0, 0, 4987);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "にゃんっ！\nや、だからさ…急に\n話しかけんなっての", 1, 116201, 0, 0, 4988);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "え、なに？　この服？\nハ？　似合ってる？\n…え、聞こえなかった\nちょ、もっかい言って", 1, 116201, 0, 0, 4989);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あんたもテレフェスで\n一応は頑張ってたよね\nま格好よかったんじゃ\nないの。知んないけど", 1, 116201, 0, 0, 4990);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふぁ～あ…おはーす\n昨日も寝たの遅くて\nまだ目がショボだよ…", 1, 116201, 0, 1, 4991);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "なに。あんた昼御飯\nまだなの。じゃ、うち\n適当になんか作ろうか", 1, 116201, 0, 2, 4992);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜っていいよね。色々\n見えすぎない感じとか\n…この話したっけ？", 1, 116201, 0, 3, 4993);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "あ、ヤバ…運動の後に\nこのフカついたのは…\n秒でスヤれる…すやぁ", 1, 116201, 0, 0, 4995);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "へーこんなんチエルに\n似合いそうじゃん。\n…いやユニ先輩かな？", 1, 116201, 0, 0, 4996);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "お、なんか良さげな\n香りじゃん。これは\n何の…いや分かんね", 1, 116201, 0, 0, 4997);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "熱ッ！　この野郎なに\n爆ぜてンだコラァ！\n濡らすぞ木、てめえ！", 1, 116201, 0, 0, 4998);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "何コレよく分かんない\nけど、今日モヤシしか\n食ってないから助かる", 1, 116201, 0, 0, 5000);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "今日、体操着だしね。\n読書には逆アドかな。\nうん帰ろ。いやあ残念", 1, 116201, 0, 0, 5001);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ビッグボス・イノリ様\nふっふっふ…\nしびれる響きです！", 1, 116501, 0, 0, 5003);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "いつかお兄さんを\nあたしの側近に\nしてやるですよ！", 1, 116501, 0, 0, 5004);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ビッグボスになったら\nみんなからたくさん\nお菓子をもらうです！", 1, 116501, 0, 0, 5005);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ふふん！\nこの服はあたしにしか\n着こなせませんよ！", 1, 116501, 0, 0, 5006);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ばーんと立って\nどーんと腕を組む！\nこれがボスのポーズ！", 1, 116501, 0, 0, 5007);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "イノリ様の側近に\n選ばれるなんて\n名誉なことですよ！", 1, 116501, 0, 0, 5008);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "未来の側近として\nあたしをしっかり\n甘やかすですよ！", 1, 116501, 0, 0, 5009);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あたしがお兄さんを\n立派なギャングに\nしてあげますからね！", 1, 116501, 0, 0, 5010);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "側近たるもの\nボスを甘やかなさいと\nだめですよ！", 1, 116501, 0, 0, 5011);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "なに見てやがるです…\nくぅ、分かりました！\nお菓子は半分こです！", 1, 116501, 0, 0, 5012);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お兄さんも\nあたしがボスなら\nうれしいですよね！", 1, 116501, 0, 0, 5013);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お兄さんが側近なら\nあたしも安心して\n夜眠れるですよ！", 1, 116501, 0, 0, 5014);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ビッグボスになったら\nお兄さんにいい思い\nさせてあげますから！", 1, 116501, 0, 0, 5015);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ボスたるもの\n早起きは鉄則ですよ！\nふぁあ…", 1, 116501, 0, 1, 5016);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹が空きました…\nご飯食べにいきますよ", 1, 116501, 0, 2, 5017);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ボスたるものぉ〜…\n夜更かしぐらい当然…\nぐー…", 1, 116501, 0, 3, 5018);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "は〜これは人をだめに\nしやがるやつですね\nあたし専用です", 1, 116501, 0, 0, 5020);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "これはけしからん\nかわいらしさですね\nあたしにぴったりです", 1, 116501, 0, 0, 5021);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "高級な香りがするです\nボスになったら\n部屋に置いてやるです", 1, 116501, 0, 0, 5022);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかいですねぇ\nちょっとこのまま\n一休憩です…", 1, 116501, 0, 0, 5023);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "はむはむ♪\nボスたるもの食べねば\n戦はできませんよ！", 1, 116501, 0, 0, 5025);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ボスなら経済書ぐらい\n…う。難しくて\n読めねーです…", 1, 116501, 0, 0, 5026);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "あなたはドジな私を\n受け入れてくれる…\nだから、頑張れます！", 1, 102501, 0, 0, 5028);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "何でも仰ってください\nちょっぴり大胆な\nことでも…な～んて♪", 1, 102501, 0, 0, 5029);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "あーあー、よし\nのどの調子もいいし\nはりきってガイド\nしてくるか！", 1, 116601, 0, 0, 5030);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "さあ、そろそろ行くか\nガイドが\n遅刻したんじゃ\n話になんないからな", 1, 116601, 0, 0, 5031);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "しれっとドラゴン族が\n旅行に来たり\nしてくれないかな", 1, 116601, 0, 0, 5032);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "たぎるガイド先…\n火山、魔物の巣…\nダメだ、そんなとこ\nオレしか行けないや", 1, 116601, 0, 0, 5033);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "この前行った絶景\nスポットよかったな\nキレイな景色を見る\nのもいいもんだぜ", 1, 116601, 0, 0, 5034);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お、今日はカレと\n一緒か。なんだか\nやる気出てきたぜ！", 1, 116601, 0, 0, 5035);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "カレにガイドして\nもらったら\nどこに行っても\n楽しいだろうな", 1, 116601, 0, 0, 5036);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "よっしゃあ！\nどっちが上手く\nガイドできるか\n勝負しようぜ！", 1, 116601, 0, 0, 5037);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "飯でも食いがてら\nおススメの店の\n下調べでもしようぜ！", 1, 116601, 0, 0, 5038);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "なかなかいいだろ？\nこの格好。キミも\n作ってもらったら\nどうだ？", 1, 116601, 0, 0, 5039);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "普通は行けない\n場所とか行きたいよな\nキミならどんな\nとこがいい？", 1, 116601, 0, 0, 5040);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ガイドの仕事は\nキミの方が得意そうだ\n参考にさせてもらうぜ\nよろしくな！", 1, 116601, 0, 0, 5041);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "キミの探してきた店\n結構よさそうじゃん\nそうだ、今度二人で\n下見に行こうぜ！", 1, 116601, 0, 0, 5042);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "いい朝だな。絶好の\n仕事日和だぜ！\n今日もよろしくな！", 1, 116601, 0, 1, 5043);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "よし、昼飯にしよう\nこの後も激務だし\n飯抜きじゃあ\nぶっ倒れちまうからな", 1, 116601, 0, 2, 5044);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お疲れさん！　さーて\n次はオレと遊んで\nくれよ。まだまだ\nいけるだろ？", 1, 116601, 0, 3, 5045);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ガイドは一日\n歩きっぱなしだからな\nゆっくり休ませて\nもらうぜ", 1, 116601, 0, 0, 5047);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "これ、どこで\n売ってるんだろ？\n土産の情報も\n仕入れとかなきゃな", 1, 116601, 0, 0, 5048);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "アロマとかよく\n分かんねえけど\n土産にはいいかもな\n覚えておくぜ", 1, 116601, 0, 0, 5049);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "体が温まると心も\n熱くなるんだよな\nいい仕事が\nできそうだぜ", 1, 116601, 0, 0, 5050);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食べ放題か\nこれはお客さんも\n喜んでくれそうだな！", 1, 116601, 0, 0, 5052);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "へえ、こんなスポット\nあったんだ。やっぱ\nたまには勉強も\nしとくもんだな", 1, 116601, 0, 0, 5053);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "バイト先になじめる\nように笑顔の練習を！\nに、にへぇ〜…", 1, 116701, 0, 0, 5055);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "働いて働いて働いて\n…いつかその先に\nぼっちの出口が\n見えるのかも…！", 1, 116701, 0, 0, 5056);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "バイトのイメトレを\n始めます。ポーズを\n決めて…よし！\n角度を変えて…よし！", 1, 116701, 0, 0, 5057);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "バイト仲間に入る\nためには厳しい修業が\n必須と聞きました…！", 1, 116701, 0, 0, 5058);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "どんどん技術を磨いて\nバイト仲間として\n認めてもらうんです！\n目指せ職人技…！", 1, 116701, 0, 0, 5059);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あの人が応援して\nくれる…だから必ず\nバイト仲間の輪に\n入ってみせます…！", 1, 116701, 0, 0, 5060);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あの人がいてくれると\n勇気が湧いてきます…\nぼっち卒業を夢見ても\nいいんだ、って…♪", 1, 116701, 0, 0, 5061);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "緊張するけど\n思い切って声をかけて\nみます…バイト仲間に\n入るために…！", 1, 116701, 0, 0, 5062);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ぼっちの私が\nおもちゃ作りで\n人と共同作業…！\nか、感動です…！", 1, 116701, 0, 0, 5063);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "好きなおもちゃって\nありますか？　私は\nもちろんマイフレンド\nくんです！", 1, 116701, 0, 0, 5064);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "私が作ったおもちゃも\n誰かの友達に\nなってたら\nいいなぁ…♪", 1, 116701, 0, 0, 5065);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "今日も明日もバイト\nですね！　バイト\n仲間ができる日が\n楽しみです…♪", 1, 116701, 0, 0, 5066);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "脱ぼっちを目指して\nこれからも一緒に\n頑張りましょう！\n目指せ、バイト仲間！", 1, 116701, 0, 0, 5067);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\n今日も気合いを入れて\nおもちゃ作りします！", 1, 116701, 0, 1, 5068);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ランチの時間です…♪\nもちろん工場の隅で\nぼっち飯です…！", 1, 116701, 0, 2, 5069);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふわぁ…今日も\nお疲れさまでした\n明日も働きます～！", 1, 116701, 0, 3, 5070);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "バイトで頑張った日は\nふわふわの誘惑に\n勝てません…", 1, 116701, 0, 0, 5072);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "こういうおもちゃの\nアイデアも\n素敵かも…♪", 1, 116701, 0, 0, 5073);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りがする\nおもちゃはどうかな…\n森の薬草を使って…", 1, 116701, 0, 0, 5074);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ぽかぽか…\n幸せなひとときですね", 1, 116701, 0, 0, 5075);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…たくさん\n食べて厳しいバイトを\n乗り切ります…！", 1, 116701, 0, 0, 5077);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ…おもちゃの\n設計図を見るのも\n勉強になりますね！", 1, 116701, 0, 0, 5078);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "う～ん\n次はどんなたい焼きを\n作ろうかにゃぁ…", 1, 116801, 0, 0, 5080);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "あたしが売る\nたい焼きには\n夢が詰まってるにゃ！", 1, 116801, 0, 0, 5081);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "いつか絶対に\nたい焼き工場を\n建て直してみせるにゃ", 1, 116801, 0, 0, 5082);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "たまにたい焼き以外の\nおやつも食べるにゃ\nたとえば煮干しとか！", 1, 116801, 0, 0, 5083);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "悪い商売人がいたら\nファントムキャッツに\n知らせるにゃ！", 1, 116801, 0, 0, 5084);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "キミと一緒にいると\nたい焼きのアイデアが\n次々出てくるにゃ♪", 1, 116801, 0, 0, 5085);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "出来ないことも\nキミと一緒にいれば\n出来る気がするにゃ♪", 1, 116801, 0, 0, 5086);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "なんにゃ～？\nお姉さんにかまって\nほしいのかにゃ♪", 1, 116801, 0, 0, 5087);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "キミ、いいところに！\nあたしとライバル店へ\n視察にいくにゃ！", 1, 116801, 0, 0, 5088);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "くんくん…この匂い！\nたい焼き持ってるなら\nちょうだいにゃ♪", 1, 116801, 0, 0, 5089);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "次はどんなたい焼きを\n売ろうかにゃ～\nキミの案も欲しいにゃ", 1, 116801, 0, 0, 5090);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ファントムキャッツに\n相棒が必要にゃ\nたとえばキミとか…", 1, 116801, 0, 0, 5091);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "相棒！\n…ってキミのこと\n呼んでいいかにゃ？", 1, 116801, 0, 0, 5092);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "早起きは三文の徳にゃ\n今日もたい焼き\n売れますよーににゃ！", 1, 116801, 0, 1, 5093);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹空いたにゃ…\n賄いのたい焼きを\nいただくにゃ！", 1, 116801, 0, 2, 5094);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "猫は夜が本番にゃ\nでもあたしは…\nふわぁ～眠いにゃ…", 1, 116801, 0, 3, 5095);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふかふかにゃ～\nここで体を丸めて\n一眠りしたいにゃ", 1, 116801, 0, 0, 5097);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "これは…！\n猫にも負けない\nかわいさだにゃ…！", 1, 116801, 0, 0, 5098);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りにゃ～\nゴロゴロのどが\n鳴りそうだにゃ～", 1, 116801, 0, 0, 5099);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ふにゃ～…\nこのまま働かずに\nまるまってたいにゃ…", 1, 116801, 0, 0, 5100);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "商売は戦いにゃ\nたくさん食べて\nたくさん働くにゃ！", 1, 116801, 0, 0, 5102);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ。たい焼きの\nアレンジレシピ集…\nためになるにゃ…", 1, 116801, 0, 0, 5103);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "お芝居の前に\nお兄ちゃんの顔を\n見ると、とっても\n落ち着きますぅ…♪", 1, 102101, 0, 0, 5105);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "お兄ちゃんにもっと\n見てもらいたい…\nだから私…\n強くなりたいです…！", 1, 102101, 0, 0, 5106);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "さらなる効率化で\nみんなといい仕事を\nしたいわね！", 1, 116901, 0, 0, 5107);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "他のバイトとの\nスケジュールを\n調整しないと…", 1, 116901, 0, 0, 5108);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "時給がアップしたわ！\n働きが認められると\nやる気が出るわね", 1, 116901, 0, 0, 5109);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "効率的に動ければ\n業務を追加できる…\n燃えてきたわ！", 1, 116901, 0, 0, 5110);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "帳簿付けのコツ…\nユカリさんに教わって\nみようかしら", 1, 116901, 0, 0, 5111);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "バイトリーダーとして\nみんなをビシバシ\n鍛えていくわ！", 1, 116901, 0, 0, 5112);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "戦いでもバイトでも\nキミなら安心して\n背中を預けられるわね", 1, 116901, 0, 0, 5113);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "どうしたの？\n仕事のことなら\nなんでも相談してね！", 1, 116901, 0, 0, 5114);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "さすがは私の弟子ね\nこれなら安心して\n仕事を任せられるわ", 1, 116901, 0, 0, 5115);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "みんなのお手本になる\n働きぶりを見せないと\nいけないわね！", 1, 116901, 0, 0, 5116);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "キミのこと…もっと\n頼りにしちゃっても\nいいのかしら…？", 1, 116901, 0, 0, 5117);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ふふ、キミも一人前の\nバイト戦士として\n立派に成長したわね！", 1, 116901, 0, 0, 5118);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "新しいおもちゃの\n企画書を作ってみたの\nちょっと見てくれる？", 1, 116901, 0, 0, 5119);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝は一番効率がいい\n時間帯よ！\nバリバリ働くわよ！", 1, 116901, 0, 1, 5120);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "さ、お昼に行きましょ\n今日の日替わり定食は\n何かしら…楽しみね♪", 1, 116901, 0, 2, 5121);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もうこんな時間…\nちゃんと寝て明日に\n備えなくちゃね", 1, 116901, 0, 3, 5122);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "適度な労働と休息の\nサイクルが最大効率を\n生み出すのよ…ふぅ…", 1, 116901, 0, 0, 5124);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "はぁ～なんて素敵な\n抱き心地なのかしら…\n最高効率の癒やしね♪", 1, 116901, 0, 0, 5125);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "落ち着く香りね…\nなんだか集中力が\nアップした気がするわ", 1, 116901, 0, 0, 5126);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ふぅ…癒されるわね…\n仕事のオンオフの\n切り替えは重要よね", 1, 116901, 0, 0, 5127);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "働くためには\nエネルギーをちゃんと\n摂っておかないと", 1, 116901, 0, 0, 5129);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "効率を上げるため\n生産管理の勉強も\nしておきたいわね", 1, 116901, 0, 0, 5130);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "変身している間に\n色々と試しておこう\nまずは…", 1, 180301, 0, 0, 5132);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "飛べるというのは\n便利だな。料理が\n暖かいうちに\n持ち帰れる", 1, 180301, 0, 0, 5133);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "プリンセスか…\n柄ではないけれど\n嫌な気はしないな", 1, 180301, 0, 0, 5134);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "この力で\n何を成すべきなのか…\n剣に聞いてみよう", 1, 180301, 0, 0, 5135);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "変身したとて私は私\n一時的に強くなろうと\n元が弱くてはだめだ", 1, 180301, 0, 0, 5136);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "変身していない時でも\n彼がそばにいると\n力が湧いてくる…", 1, 180301, 0, 0, 5137);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "私の思い…\nいつか伝えてみせるよ\n…きっといつか！", 1, 180301, 0, 0, 5138);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "何者かと戦うの？\nそれとも修行？\nどちらだとしても\n付き合うよ", 1, 180301, 0, 0, 5139);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "変身し続けたら\nどれだけ空腹に…\n私は試さないからね？", 1, 180301, 0, 0, 5140);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "本物のプリンセスに\nなるのは御免だが\nナイトがいて\nくれるのは頼もしいよ", 1, 180301, 0, 0, 5141);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "いつかこの力を\n誰かを救うために…\n戦い以外に使える時が\nくることを願うよ", 1, 180301, 0, 0, 5142);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "キミに感じてほしいな\n私に流れてくる\nキミからの力を…\nその…私の、思いも…", 1, 180301, 0, 0, 5143);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "思いを告げる…\nそれがこんなにも\n難しいなんて…\nでも、いつか必ず…！", 1, 180301, 0, 0, 5144);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう！\nいい変身日和だ！\n…ふふっ、冗談だよ", 1, 180301, 0, 1, 5145);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "いつもより多く\n昼食を用意しよう\n変身が解けたら大変だ", 1, 180301, 0, 2, 5146);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "一日お疲れ様\n私もそろそろ変身を\n解いて休むとするよ", 1, 180301, 0, 3, 5147);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "変身してしまうと\n動かずにいても\n空腹になるのかな…？", 1, 180301, 0, 0, 5149);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "私もキミたちくらい\n可愛げがある姿に\nなっているかな？", 1, 180301, 0, 0, 5150);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "香りに対する感覚も\nいつもより鋭く\nなっているみたいだ…", 1, 180301, 0, 0, 5151);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ありがたいな\n少し足元が\n冷えていたところだ", 1, 180301, 0, 0, 5152);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "これは…！\n持ち運べるように\n改良できないかな？", 1, 180301, 0, 0, 5154);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "祖父に貰った\n技法書を読んで\n初心に帰ろう", 1, 180301, 0, 0, 5155);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "最強の惚れ薬を作って\nあのおかたの心を\n私の思いのままに…", 1, 117001, 0, 0, 5157);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "夏といえば海にスイカ\n花火に水着…\nそして惚れ薬ですわ…", 1, 117001, 0, 0, 5158);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "あのおかたの心を\n手に入れるための\n準備を進めましょう\nこの夏こそ確実に…", 1, 117001, 0, 0, 5159);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "あのおかたに近づく\n虫どもを、どうやって\n片付けようかしら…\nまったく忌々しいこと", 1, 117001, 0, 0, 5160);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "…クスクス\n薬の調合を考えるのは\n至福の時間ですわ…", 1, 117001, 0, 0, 5161);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あのおかたの全てが\n早く私のものに\nなりますように…", 1, 117001, 0, 0, 5162);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "かき氷も花火も海も…\nあなた様がいてこそ…\nそう、あなた様は\n私の全てなのですわ", 1, 117001, 0, 0, 5163);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "二人だけの夏を\n楽しみましょう…？\n…クスクス", 1, 117001, 0, 0, 5164);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あら、あなた様\n私に秘密でどこに\n行こうとして\nいますの…？", 1, 117001, 0, 0, 5165);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "海に行きませんか？\nあなた様と一緒に\n過ごすには\n最高の場所ですから…", 1, 117001, 0, 0, 5166);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ちょうどいいところに\nいらっしゃいました\nできたての薬を…\nさぁどうぞ…クスクス", 1, 117001, 0, 0, 5167);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "夏の海のきらめきも\nあなた様の存在が\nなければ色あせて\nしまいますわ…", 1, 117001, 0, 0, 5168);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "私とあなた様は\n結ばれる運命に\nあるのです…\n逃がしませんわ…", 1, 117001, 0, 0, 5169);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "起きてすぐに会いに\n来てくださるなんて\nようやく私の伴侶たる\n自覚が…クスクス", 1, 117001, 0, 1, 5170);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お食事はまだですか？\n特製の薬草ランチを\n召し上がれ…クスクス", 1, 117001, 0, 2, 5171);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "私の夢を見られる薬を\n差し上げますわ…\nおやすみなさいませ\nあなた様…クスクス", 1, 117001, 0, 3, 5172);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "いい肌触りですわ…\n考え事にもぴったり\n眠くなるのが\n玉に瑕ですが…", 1, 117001, 0, 0, 5174);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "こういったものに\n揮発性の薬を仕込む\nのも一つの手ですわね", 1, 117001, 0, 0, 5175);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この香り…開発中の\n薬に使えそうな気が\nしますわ…クスクス", 1, 117001, 0, 0, 5176);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あのおかたの\nぬくもりを\n思い出しますわ…", 1, 117001, 0, 0, 5177);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "美味しい…この味なら\n薬を混ぜても違和感は\nなさそうですわ…", 1, 117001, 0, 0, 5179);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "この薬の調合法…\n今度試してみましょう\nもちろんあのおかたに\n飲んでいただいて…", 1, 117001, 0, 0, 5180);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "二人乗りができると\nいいですわね…", 1, 117001, 0, 0, 5182);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "ふかふかですわ…\nあのおかたの分も\n欲しくなります…", 1, 117001, 0, 0, 5183);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "今日はキミと\nいつまでも歌って\n踊りたい気分さ～♪", 1, 101701, 0, 0, 5184);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "あは～♪\nキミの隣は、故郷より\n落ち着くかも～…♪", 1, 101701, 0, 0, 5185);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この水着…\n一番に弟くんに\n見せたいな♪", 1, 117101, 0, 0, 5186);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "弟くんをこっそり\n海に運んで…\nサプライズしちゃお♪", 1, 117101, 0, 0, 5187);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "いつもと違う髪型に\nしてみたけど…\n気に入ってくれるかな", 1, 117101, 0, 0, 5188);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "海は楽しみだけど\n日焼けしないように\n気を付けなきゃね", 1, 117101, 0, 0, 5189);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "まだかな、弟くん\n水着のお姉ちゃんが\nお出迎えだよっ♪", 1, 117101, 0, 0, 5190);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "海が見えるおうちで\n弟くんと一緒に\n暮らしたいなぁ～", 1, 117101, 0, 0, 5191);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "弟くんの水着…\nどんな感じかなぁ\n…あ、想像してたら\nドキドキして…えへへ", 1, 117101, 0, 0, 5192);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "こーら、水着の\nお姉ちゃんは\nおさわり禁止♪\n…なんてね？", 1, 117101, 0, 0, 5193);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "なぁに？\nふふっ、何回でも\n呼んでいいんだよ♪", 1, 117101, 0, 0, 5194);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "海で迷子に\nならないように\n手を繋ごうね♪", 1, 117101, 0, 0, 5195);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お姉ちゃんが\n海の楽しみ方を\n教えてあげるねっ！", 1, 117101, 0, 0, 5196);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "わっ、弟くん\nどこ触ってるの？\nも～驚いちゃったぞ♪", 1, 117101, 0, 0, 5197);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お姉ちゃん、海でも\nずっとキミを見てるよ\n…安心してね", 1, 117101, 0, 0, 5198);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "まだ眠そうだね？\nほら、海が待ってるよ\n早く起きて起きて♪", 1, 117101, 0, 1, 5199);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "大丈夫、疲れてない？\n海で遊び疲れた時は\n素直に休憩しようね", 1, 117101, 0, 2, 5200);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ほら、早く寝ないと\n明日もお姉ちゃんと\n遊べないぞ♪", 1, 117101, 0, 3, 5201);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "だらけたお姉ちゃんは\n弟くんには\n見せられないな～", 1, 117101, 0, 0, 5203);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふふっ、かわいいね♪\n弟くんが持つと\nもっとかわいいよっ♪", 1, 117101, 0, 0, 5204);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りだね…\n一味違うお姉ちゃんに\nなれそう…♪", 1, 117101, 0, 0, 5205);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったか～い♪\nほら、弟くんも\nおいでよ♪", 1, 117101, 0, 0, 5206);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "よく食べて、いつでも\n弟くんの呼び声に\n応える準備を…！", 1, 117101, 0, 0, 5208);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "弟くんの水着の写真\nこの辺りに隠して\nおこうかな", 1, 117101, 0, 0, 5209);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "この子の背に乗って\nお姉ちゃんと弟くんの\n楽園へ…な～んて♪", 1, 117101, 0, 0, 5211);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "海を感じる感触だね\n弟くんとの楽しい夏を\n思い出しちゃうな…♪", 1, 117101, 0, 0, 5212);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この夏、誰よりも\nキラキラしてみせる！\nだって私は\nアイドルだから！", 1, 117201, 0, 0, 5213);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "日傘にアームカバー\n帽子にサングラス…\n紫外線対策は完璧！", 1, 117201, 0, 0, 5214);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "とっておきの\nサマーソングを\nみんなに届けるよ！", 1, 117201, 0, 0, 5215);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "なんにもしないのって\n苦手かも…\n彼、早く来ないかな？", 1, 117201, 0, 0, 5216);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ラムネって\n夏って感じするよね\n後で彼と飲もっと♪", 1, 117201, 0, 0, 5217);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "夏は恋の季節！\n燃えるような恋…\nいつかしたいな", 1, 117201, 0, 0, 5218);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "今年の夏の目標は\n…彼との思い出を\nいっぱい作ること！", 1, 117201, 0, 0, 5219);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "私の水着写真集\n見てくれたんだ！\nどう、かわいかった？", 1, 117201, 0, 0, 5220);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "スイカ割りしたいの？\nいいね、楽しそう！\nみんなも誘おうよ♪", 1, 117201, 0, 0, 5221);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ねぇ、見て見て！\n水着の映える\nポーズ考えたんだ！", 1, 117201, 0, 0, 5222);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ライブ中に\n花火を打ち上げたら\n絶対盛り上がるよね！", 1, 117201, 0, 0, 5223);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "最近、忙しいけど…\nキミの顔見たら\n疲れなんて\n消えちゃった！", 1, 117201, 0, 0, 5224);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "この夏もいーっぱい\nドキドキさせるから！\n覚悟しててよね♪", 1, 117201, 0, 0, 5225);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "外は朝から暑いね\nけど、負けないから！\nお仕事、頑張るぞー！", 1, 117201, 0, 1, 5226);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "自分へのご褒美に、\nアイス食べちゃお♪\nキミも一緒に食べよ！", 1, 117201, 0, 2, 5227);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夏の夜って\nワクワクするね♪\nホタル見に行こうよ！", 1, 117201, 0, 3, 5228);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふわぁ…眠い…\n仕事とかの疲れ、\nたまってるのかな…？", 1, 117201, 0, 0, 5230);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "私のぬいぐるみが\nグッズになったら…\n彼にかわいがって\nもらえるかな？", 1, 117201, 0, 0, 5231);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この香り…\n夏限定のやつでしょ？\nいいセンスしてるね♪", 1, 117201, 0, 0, 5232);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "暑～い！\nけど…汗かいて\n気持ちいいかも！", 1, 117201, 0, 0, 5233);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "レッスンの後のご飯は\n特別おいしい♪\n…もうひとつだけ\n食べちゃおっかな", 1, 117201, 0, 0, 5235);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "あ、この前撮影した\n水着グラビアだ\nうんうん、いい感じ！", 1, 117201, 0, 0, 5236);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "この子、もふもふだね\n触るのクセになりそう\nもふもふもふもふ…", 1, 117201, 0, 0, 5238);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "わ、かわいい♪\n今度のグラビア撮影で\nこれ使ってもいい？", 1, 117201, 0, 0, 5239);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "水着っていいですよね\n海に浮かぶ一輪の花\nって感じがして！", 1, 117401, 0, 0, 5240);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "自分の水着を作るのも\n誰かの水着を作るのも\n楽しいですね♪", 1, 117401, 0, 0, 5241);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "水着の最終チェック！\n伸縮性や動きやすさは\n…いい感じですね！", 1, 117401, 0, 0, 5242);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "振り付けや衣装作りに\n歌や踊りの練習…\n…やることがいっぱい", 1, 117401, 0, 0, 5243);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "はぁ…レイ様の水着…\n私に作らせて\nもらえないかなぁ～…", 1, 117401, 0, 0, 5244);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "騎士さんのことは\n気に入らないですけど\n別に嫌いという\nわけじゃなくて…", 1, 117401, 0, 0, 5245);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "騎士さん暇そうですね\nに、荷物持ちとして\n誘ってみようかな…", 1, 117401, 0, 0, 5246);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "騎士さんいいところに\nこの衣装\nどう思います？", 1, 117401, 0, 0, 5247);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "何見てるんですか？\nもしかしてこの水着の\n良さが分かります！？", 1, 117401, 0, 0, 5248);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "真夏でも涼しい…\nそれも水着の良さの\n一つですね", 1, 117401, 0, 0, 5249);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "仕立て屋も\nアイドルも\n諦めません！", 1, 117401, 0, 0, 5250);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "夏と言えば\nバカンスですけど…\n予定、あるんですか？", 1, 117401, 0, 0, 5251);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "う～ん…騎士さんを\n海へ誘うには…って\nなんでもないですよ！", 1, 117401, 0, 0, 5252);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふー…夏はやっぱり\n朝が一番過ごしやすい\nですね～！", 1, 117401, 0, 1, 5253);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "暑い時こそ海です！\n体力づくりのためにも\n泳ぎにいきますよ！", 1, 117401, 0, 2, 5254);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "外で虫が鳴いてる…\n夏って感じがして\n風流ですねぇ…", 1, 117401, 0, 3, 5255);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "少し休憩です…\nこのまま寝ないよう\n気をつけないと…", 1, 117401, 0, 0, 5257);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "か、かわいい…！\nこの感動を次の\nステージ衣装にも…！", 1, 117401, 0, 0, 5258);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りですね～\n波の音が聞こえて\nきそうです…", 1, 117401, 0, 0, 5259);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "泳いだ後は\n少し寒いので\nちょうどいいですね", 1, 117401, 0, 0, 5260);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "夏バテしないように\n栄養はしっかり\n取らないと！", 1, 117401, 0, 0, 5262);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "次のトレンドは…\nふむふむ、やっぱり\nこう来ましたか…", 1, 117401, 0, 0, 5263);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "デザインはもちろん\n触り心地も\n最高ですね♪", 1, 117401, 0, 0, 5265);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "夏の撮影スポットに\n活用できそうですね\nさっそく衣装考えて…", 1, 117401, 0, 0, 5266);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "えへへ…♪\n団長さんが初めての\n友達で本当に良かった", 1, 104001, 0, 0, 5267);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "あっ、団長さん！\n今日のＢＢ団の活動\nなんですけど…二人で\n大縄跳びしませんか！", 1, 104001, 0, 0, 5268);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この衣装で\nライブするのは\n恥ずかしいな…", 1, 117301, 0, 0, 5269);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "せっかくの夏だし\n肝試しに\n行ってみたいかも…", 1, 117301, 0, 0, 5270);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "歌もダンスも\nより上を目指すために\n夏合宿をしよう…！", 1, 117301, 0, 0, 5271);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "夏の暑さにも負けない\n熱いライブに\nしてみせる…！", 1, 117301, 0, 0, 5272);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "新曲のアイデア\nまとめたいな…\n少し海辺を散歩しよう", 1, 117301, 0, 0, 5273);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "かき氷、食べたいな\n…あの人は何味が\n好きなんだろう？", 1, 117301, 0, 0, 5274);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "水着、似合ってるって\n言ってもらえるかな…", 1, 117301, 0, 0, 5275);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "サインして、ですか？\nいいですけど…\n少し照れますね…", 1, 117301, 0, 0, 5276);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "少し待ってください\n今、新曲の楽譜を\n書いているので…", 1, 117301, 0, 0, 5277);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "なんでしょう？\nもしかして…\nボイトレに興味が？", 1, 117301, 0, 0, 5278);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "今度のライブでは\n夏らしい爽やかな歌を\nファンにお届けします", 1, 117301, 0, 0, 5279);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "…水鉄砲で遊ぼう？\nふふ。楽しそうですね\nお手柔らかに…♪", 1, 117301, 0, 0, 5280);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あなたの声を\n聴いていると、\n何だか落ち着きます…", 1, 117301, 0, 0, 5281);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日も暑くなりそう…\nお互いしっかりと\n水分補給しましょうね", 1, 117301, 0, 1, 5282);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹空きましたよね\n海の家で、\nなにか買ってきます", 1, 117301, 0, 2, 5283);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜の海で月明かりと\n波の音を楽しもうかと\n…一緒に行きますか？", 1, 117301, 0, 3, 5284);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "レッスンだけでなく\nリラックスすることも\n大事、ですよね", 1, 117301, 0, 0, 5286);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふふ、かわいい\n精霊も負けないくらい\nかわいいですけどね", 1, 117301, 0, 0, 5287);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "夏らしい爽やかで\nいい匂い…あなたに\nピッタリな香りですね", 1, 117301, 0, 0, 5288);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "海に入った後は、\n体が冷えてしまいます\n一緒に温まりましょう", 1, 117301, 0, 0, 5289);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "アイドルとして、\n食べすぎには\n気をつけないと…", 1, 117301, 0, 0, 5291);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "夏は恋の季節…\nガンガン攻めるべし…\nなるほど…", 1, 117301, 0, 0, 5292);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "この子に乗りながら\nライブをする…\nというのはどうですか", 1, 117301, 0, 0, 5294);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "まるで人魚になった\n気分…なんて、ふふ", 1, 117301, 0, 0, 5295);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "お姉ちゃんとして\nシオリンにかっこいい\nとこ見せなくっちゃ☆", 1, 118301, 0, 0, 5296);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "いつかシオリンと\n一緒に空を飛んで\n空中散歩してみたいな", 1, 118301, 0, 0, 5297);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "すこし眠くなってきた\nかも…シオリンと\nお昼寝しようかな", 1, 118301, 0, 0, 5298);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お散歩してこよっと！\nシオリンとお出かけ\nするのにいい場所\n探さなくっちゃ！", 1, 118301, 0, 0, 5299);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "シオリンに過保護って\n言われちゃった…♪\nそれでも心配しちゃう\nのが姉心…だよね？", 1, 118301, 0, 0, 5300);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "気持ちいい日差し！\nシオリンと彼と、\nお昼寝したら\n気持ちよさそ～♪", 1, 118301, 0, 0, 5301);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "今度天気がいい日には\nシオリンと彼を誘って\n一緒にお出かけ\nしたいな～♪", 1, 118301, 0, 0, 5302);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日はご機嫌なんだ♪\nだって、シオリンの\n調子がいいんだもん☆", 1, 118301, 0, 0, 5303);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今からシオリンと\nピクニックに\n行くんだ♪　そうだ！\nキミも一緒にどう？", 1, 118301, 0, 0, 5304);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "わっ、びっくりした！\nシオリンから借りた本\n読むのに集中\nしてたから…", 1, 118301, 0, 0, 5305);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "うん？　どうしたの？\nあっ、もしかして\nこの服、気になる？", 1, 118301, 0, 0, 5306);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "シオリンもキミも元気\nいっぱいだと、私も\n元気になっちゃうよ☆", 1, 118301, 0, 0, 5307);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "シオリンの前だけ\nじゃなくて、キミにも\nかっこいい私の姿を\n見てほしいな☆", 1, 118301, 0, 0, 5308);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう！　えへへっ\n今日は早起きなんだ♪\nシオリンにかっこ悪い\nとこ見せたくないから", 1, 118301, 0, 1, 5309);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おなかすいたなぁ～…\nシオリンと一緒に\nおいしいもの食べに\n行こうかな！", 1, 118301, 0, 2, 5310);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もうこんな時間！？\nシオリンと一緒だと\n時間が早く\n過ぎていっちゃうね！", 1, 118301, 0, 3, 5311);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "この快適な寝心地…！\nシオリンにもおすすめ\nしなきゃ…！", 1, 118301, 0, 0, 5313);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "わあ、かわいい！\nそれにさわり心地も\nいいし、抱き枕に\nちょうどいいかも！", 1, 118301, 0, 0, 5314);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いいにおい…♪\nなんだかリラックス\nできて…すやぁ…", 1, 118301, 0, 0, 5315);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ぽかぽか～☆\nシオリンと一緒に\nぬくぬくしたら\n気持ちよさそう♪", 1, 118301, 0, 0, 5316);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "仲のいい人が一緒だと\nつい食が進んじゃうね\nえへへ…♪", 1, 118301, 0, 0, 5318);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ…この本…\nシオリンが好きかも！\n今度おすすめしよっと", 1, 118301, 0, 0, 5319);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "お姉ちゃん、\n私のために無理は\nしてないかな…？", 1, 118401, 0, 0, 5322);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "新しく買った絵本…\nこういうのなら\nお姉ちゃんと楽しく\n読めるよね", 1, 118401, 0, 0, 5323);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ニャットちゃんを\nここに連れてきて\nみんなで遊べないかな", 1, 118401, 0, 0, 5324);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "本屋さんに行こうかな\nみんなで読める\n面白い本が\nあるといいなぁ", 1, 118401, 0, 0, 5325);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "たまには…読むだけ\nじゃなくて、自分で\nお話を書いて\nみようかな…？", 1, 118401, 0, 0, 5326);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "時々…お姉ちゃんと\nあの人が似てるって\n思うことがあります…", 1, 118401, 0, 0, 5327);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "お姉ちゃんとあの人…\n優しくて頼もしい\n二人に囲まれて…\n私、幸せ者だなぁ…", 1, 118401, 0, 0, 5328);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "どうかしましたか？\nもしかして…あなたも\n一緒にこの本を\n読みたい…とか？", 1, 118401, 0, 0, 5329);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "けほっ…けほっ…\nあっ、心配いりません\n飲み物を飲んで\nむせただけですから", 1, 118401, 0, 0, 5330);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "この格好…\n似合ってますか…？\nえへへ、照れますね…", 1, 118401, 0, 0, 5331);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "なぁに、お姉ちゃん？\n…あっ、すみません\n読書に集中していて…\n間違えちゃいました…", 1, 118401, 0, 0, 5332);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お姉ちゃん、時々無理\nしちゃうから…\nあなたも一緒だと\n安心できます", 1, 118401, 0, 0, 5333);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お姉ちゃんとあなたと\n頼れる人に囲まれて\n私は幸せものですね", 1, 118401, 0, 0, 5334);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "なんだか朝から\n調子がいい…今日は\nいい日になりそうです", 1, 118401, 0, 1, 5335);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "せっかくだから、\nお姉ちゃんを誘って\nお外でランチも\nいいかも", 1, 118401, 0, 2, 5336);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お姉ちゃんに心配\nかけないように…もう\nちょっと本を読んだら\n寝なくちゃね", 1, 118401, 0, 3, 5337);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふんわり柔らかくて\n気持ちいい手触り…\nお姉ちゃんが寝るのに\nちょうどよさそう", 1, 118401, 0, 0, 5339);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふふっ、かわいい♪\n絵本の物語みたいに\nおしゃべりできない\nかな…？", 1, 118401, 0, 0, 5340);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "素敵な落ち着く香り♪\nなんだかお姉ちゃん\nみたい、ふふっ", 1, 118401, 0, 0, 5341);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかくてほっと\nするなぁ\nここでゆっくり\n読書しようかな", 1, 118401, 0, 0, 5342);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "この味…\nお姉ちゃんが好きそう\n少しもらって、\n持って行こうかな…？", 1, 118401, 0, 0, 5344);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "この本みたいな、\n心躍る大冒険も\nお姉ちゃんと一緒なら\nできちゃいそう", 1, 118401, 0, 0, 5345);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "いい部屋ね\nここを私の分院に\nするのもいいかも\nしれないわね…♪", 1, 117501, 0, 0, 5348);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "珍しいカンポーが\n手に入ったから\n色々試してみたいわ\n色々と、ね♪", 1, 117501, 0, 0, 5349);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "この服を着ると\n自分が医者だって\nより実感するわね\nまあ、闇医者だけどね", 1, 117501, 0, 0, 5350);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "新薬開発のために\n薬草を採取して\nおこうかしら", 1, 117501, 0, 0, 5351);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "いつ急患が来ても\n対応できるように\nしておきましょうか", 1, 117501, 0, 0, 5352);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あの子の研究資料も\nだいぶ増えてきたわね\nちゃんとまとめて\nおかないと♪", 1, 117501, 0, 0, 5353);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あの子は大事な\n研究対象。だから\nいつまでも健康で\nいてもらわないとね♪", 1, 117501, 0, 0, 5354);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "薬に興味があるの？\nなら、今度ゆっくりと\n教えてあげるわね", 1, 117501, 0, 0, 5355);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "少し時間があいたから\n一緒に新薬の実験を\nしましょうか♪", 1, 117501, 0, 0, 5356);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "どうしたの？\nまさか急患…！？\nあら、違うのね\nならよかったわ", 1, 117501, 0, 0, 5357);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "具合が悪い時はすぐに\n言うのよ。君には\nいつでも健康でいて\nほしいから", 1, 117501, 0, 0, 5358);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "少し仮眠したいわね\n肩…いいえ、膝を\n貸してもらえる？", 1, 117501, 0, 0, 5359);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "たまには…君の隣なら\n闇医者も悪い研究者も\nお休みにするのも\n悪くないわね♪", 1, 117501, 0, 0, 5360);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "たまには朝の陽ざしを\n浴びるのも…\n悪くないわね", 1, 117501, 0, 1, 5361);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "天気がいい日は\nいい薬草が採れるの\n君も集めるの、\n手伝ってくれる？", 1, 117501, 0, 2, 5362);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "いけない、もうこんな\n時間なのね\n診察に没頭すると\n時間感覚がなくなるわ", 1, 117501, 0, 3, 5363);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "もう少し固い方が\n私好みだけど…\n悪くない寝心地ね", 1, 117501, 0, 0, 5365);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "このぬいぐるみ…\n闇医者として\n興味深いわね…", 1, 117501, 0, 0, 5366);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "落ち着く香りね\n私も診察室で\n使ってみようかしら", 1, 117501, 0, 0, 5367);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "冷えは病につながるわ\nしっかり温めて\n体をいたわりましょ", 1, 117501, 0, 0, 5368);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいしい♪\n研究のお供に\nもってこいの\n味だわ", 1, 117501, 0, 0, 5370);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "医学は日進月歩…\n闇医者とはいえ\n最新の論文には\n目を通しておかないと", 1, 117501, 0, 0, 5371);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "白衣の天使かあ\nまさにボクのための\n呼び方だね", 1, 117601, 0, 0, 5400);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "美しさとは\n日々の努力が\n作るものなんだよ", 1, 117601, 0, 0, 5401);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "大変だ…\nボクは美しく\nなりすぎたかも", 1, 117601, 0, 0, 5402);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ボクのかわいさで\n癒やされて\nみんな健康に\nなっちゃうね", 1, 117601, 0, 0, 5403);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "どんな服装をしても\nボクの美しさは\n変わらないね", 1, 117601, 0, 0, 5404);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "これからはボクも\n美の伝道師として\nがんばらないとね♪", 1, 117601, 0, 0, 5405);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ボクのかわいい笑顔を\n近くで見る以上の\n癒やしはないよね♪", 1, 117601, 0, 0, 5406);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "どう？　看護師姿の\nボクもかわいいでしょ\nもっと近くで見る？", 1, 117601, 0, 0, 5407);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ほら！　美しいボクの\n看護師姿を見たら\n元気でちゃうでしょ？", 1, 117601, 0, 0, 5408);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "白衣の天使のボクも\n最高に美しいね\n存分に癒されてよ♪", 1, 117601, 0, 0, 5409);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "具合が悪いの？\nならボクの美しい顔を\n処方してあげる♪", 1, 117601, 0, 0, 5410);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "さあ今日もボクと\n一緒に美の追求に\n付き合ってもらうよ♪", 1, 117601, 0, 0, 5411);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "かわいい天使のボクが\nいつもそばにいるんだ\nキミって幸せ者だね♪", 1, 117601, 0, 0, 5412);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "さすがボク\n目が覚めるような\n美しさでしょ？", 1, 117601, 0, 1, 5413);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "美は食で作られる\n美容にいいものを\n食べようよ！", 1, 117601, 0, 2, 5414);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふああ…早く寝よ？\n夜更かしは美容の\n大敵だからね", 1, 117601, 0, 3, 5415);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふう～…\nリラックスする\nボクも美しい", 1, 117601, 0, 0, 5417);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ボクが抱きしめると\n普段よりかわいく\n見えちゃうね♪", 1, 117601, 0, 0, 5418);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "美しいボクは\n常にいい香りを\nしていなくちゃね", 1, 117601, 0, 0, 5419);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "光がボクを照らしてる\nんじゃなくて、ボクが\n光を輝かせてるのさ", 1, 117601, 0, 0, 5420);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "バランスのいい食事が\n美しいボクを\n作るのさ", 1, 117601, 0, 0, 5422);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ…なるほど\nこうすればより美しく\nなれるかもしれない", 1, 117601, 0, 0, 5423);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "仲間のためなら\nきっと…どこまでも\n強くなれるよね", 1, 105701, 0, 0, 5425);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "プリンセスフォーム？\n私と同じような力を\n持ってる人がいるの？\n会ってみたいな～！", 1, 105701, 0, 0, 5426);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ここの空気は、\nどうもゆるすぎて…\n落ち着きませんわね", 1, 118001, 0, 0, 5427);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "陛下のお越しになる\n別宅としては、\n少し警備が\n甘すぎでは？", 1, 118001, 0, 0, 5428);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "あらあら？\nサッシにホコリが！\nちょっとネコ助！\n掃除は念入りに！", 1, 118001, 0, 0, 5429);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "いつまで入り浸って\nいるのかと、\n秘書に叱られて\nしまいましたわ…", 1, 118001, 0, 0, 5430);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "もういっそ、\nここに間借りして\n仕事しようかしら…？", 1, 118001, 0, 0, 5431);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "邪魔している身ですし\n家事くらい\nお手伝いさせなさいな", 1, 118001, 0, 0, 5432);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "本当は、意外と\n居心地が良いのかも…\n陛下の気持ち、\n少し分かりましたわ", 1, 118001, 0, 0, 5433);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ちょっ…わたくしを\n叩いても、ホコリなど\nあまり出ませんわよ！", 1, 118001, 0, 0, 5434);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "陛下っ？\nなんだ…貴方でしたの\n用件は手短にお願いね", 1, 118001, 0, 0, 5435);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "別に、好き嫌いは\nありませんけれど…\n魔物料理って、意外と\n美味なものですわね", 1, 118001, 0, 0, 5436);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "言っておきますけれど\nわたくしは商売人です\n荒事は専門外ですわよ", 1, 118001, 0, 0, 5437);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "プリンセスナイトの\n能力…なにか儲け話に\n使えませんかしらね", 1, 118001, 0, 0, 5438);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "貴方がたのことも、\n少しくらいは\n信用してないことも\nありませんでしてよ", 1, 118001, 0, 0, 5439);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\nさ、今日もバリバリ\n働きますわよ！", 1, 118001, 0, 1, 5440);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ですわね\n栄養補給をしつつ\n働きますわよ！", 1, 118001, 0, 2, 5441);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "定時ですって？\n関係ありません！\nわたくし、まだまだ\n働きますわよ～っ！", 1, 118001, 0, 3, 5442);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "うっ…いけませんわ\n日頃の疲れが…\nふわぁ…", 1, 118001, 0, 0, 5444);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "もふもふ…ふふっ♪\n…なんですのっ、\nなにかおかしくて！？", 1, 118001, 0, 0, 5445);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りですわね\nわたくしの執務室にも\n置きたいくらいですわ", 1, 118001, 0, 0, 5446);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "いけませんわ…\nこんなに暖かいと\n日頃の疲れが…ふわぁ", 1, 118001, 0, 0, 5447);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もう一つ食べたら\n仕事に戻りますわよ？\nあと一つだけ…", 1, 118001, 0, 0, 5449);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "商人にとって\n知識は武器ですわ\n陛下のため、貴方も\nもっと勉強なさい？", 1, 118001, 0, 0, 5450);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "故郷のお菓子を\nいろいろ作ったんだ～\nみんなに\n配ってくるさ～♪", 1, 117701, 0, 0, 5452);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "彼ってどんな仮装が\n似合うかな～？\nシーサーとか？", 1, 117701, 0, 0, 5453);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "カボチャチャンプルー\n作ってみよっと！\nきっとおいしいさ～♪", 1, 117701, 0, 0, 5454);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "視線を感じるさ～\nもしかして幽霊？\nおしゃべりするさ～♪", 1, 117701, 0, 0, 5455);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "さっき作った\nサーターアンダギー、\n早く彼に\n食べてほしいさ～♪", 1, 117701, 0, 0, 5456);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "彼のために、\n特別なイタズラを\n考えとくさ～♪", 1, 117701, 0, 0, 5457);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "いつか彼と、\n故郷のハロウィンを\n楽しみたいさ～♪", 1, 117701, 0, 0, 5458);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ハロウィンは\n私たちが守るさ～♪\nさ、見回りに行こ！", 1, 117701, 0, 0, 5459);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "この制服、\nハロウィンらしくて\n大好きさ～♪", 1, 117701, 0, 0, 5460);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "イタズラする気ね～？\nどんなことされるのか\n楽しみさ～♪", 1, 117701, 0, 0, 5461);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "カボチャのランタン、\n一緒に作ろ！\n絶対楽しいよ～♪", 1, 117701, 0, 0, 5462);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お菓子くれるの？\nあは～、ありがとー♪\nもぐもぐ…\n優しい味がするさ～♪", 1, 117701, 0, 0, 5463);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "キミと一緒に過ごす\nハロウィンは、\nドキドキとワクワクが\n止まらないさ～♪", 1, 117701, 0, 0, 5464);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ハロウィンは\n朝から大忙しさ～！\nお菓子作り、\n手伝ってほしいさ～", 1, 117701, 0, 1, 5465);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お化け屋敷に行こ！\n一緒にいっぱい\nドキドキしようね～♪", 1, 117701, 0, 2, 5466);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ここからが\nハロウィン本番さ～！\n幽霊たちと\nいっぱい遊ぶさ～♪", 1, 117701, 0, 3, 5467);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ちょっと休んだら、\nお菓子作りを\n再開するさ～♪", 1, 117701, 0, 0, 5469);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "でーじかわいいね～♪\nこの子に仮装させたら\nきっと似合うさ～♪", 1, 117701, 0, 0, 5470);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "お菓子みたいに\n甘い匂い…\nハロウィンらしい\nいい香りさ～♪", 1, 117701, 0, 0, 5471);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ランドソルの秋って\n冷えるけど…\nこれがあれば\n体も心もぽかぽかさ～", 1, 117701, 0, 0, 5472);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "故郷のご飯も\nおいしいけど、\nこっちのご飯も\nでーじおいしいさ～♪", 1, 117701, 0, 0, 5474);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "パンプキンパイの\nレシピは…なるほど～\n勉強になるさ～♪", 1, 117701, 0, 0, 5475);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 12, 3, "全部おいしそうで\nどれから食べるか\n迷っちゃうさ～♪", 1, 117701, 0, 0, 5477);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ムっ！　幽霊の気配を\n感じるデス！\nさあ姿を現すデス！", 1, 117801, 0, 0, 5479);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ムムム…\n妖魔の力を忍法に\n使えないでショウか…", 1, 117801, 0, 0, 5480);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "怪しい妖魔を\n成敗するデス！\nハロウィンの平和は\nワタシが守りマスよ！", 1, 117801, 0, 0, 5481);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ワタシの祭囃子が\n聞こえマスかー？\nさあ集まるデース！\n陽気に踊りまショウ！", 1, 117801, 0, 0, 5482);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "お祭りは\n楽しんだ者勝ちデス！\n踊らにゃ\nソンソンデス！", 1, 117801, 0, 0, 5483);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "幽霊になる前に\n天下統一を\n果たしたいデスね", 1, 117801, 0, 0, 5484);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あの世に行っても\nショーグンは\nワタシの大事な\nショーグンデス！", 1, 117801, 0, 0, 5485);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ショーグン！\n悪霊退治に\n出かけるデース！", 1, 117801, 0, 0, 5486);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "妖魔を家来に\nしてみるのは\nどうデス？", 1, 117801, 0, 0, 5487);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "マントを使って\nウツセミの術の精度を\n高めるデス！", 1, 117801, 0, 0, 5488);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ハロウィンにちなんだ\n新しい忍法…\nすなわち妖忍法の\n開発を急ぐデス！", 1, 117801, 0, 0, 5489);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あの世でも\nショーグンに\nお仕えしマスよー！", 1, 117801, 0, 0, 5490);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ショーグンもワタシと\nハロウィンパレードを\n踊り明かしまセンか？", 1, 117801, 0, 0, 5491);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございマス！\n天下統一に向けて\n急いで準備するデス！", 1, 117801, 0, 1, 5492);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹減ってまセンか？\nハロウィンスイーツで\n休憩するデ〜ス", 1, 117801, 0, 2, 5493);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜更かしすると幽霊が\nでるかもしれまセン…\nヒュ〜ドロロロ〜…", 1, 117801, 0, 3, 5494);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "もふもふなところが\nわたあめちゃんに\n似ていマス。わんっ！", 1, 117801, 0, 0, 5496);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ぬいぐるみや人形には\n魂が宿るという\n言い伝えがありマス…\nマカフシギデ〜ス", 1, 117801, 0, 0, 5497);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ウ〜ム…\nなんとも怪しい\n香りがしマスね！", 1, 117801, 0, 0, 5498);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "パレードの熱気に\n負けないくらい\n熱いデス！", 1, 117801, 0, 0, 5499);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ついつい食べすぎて\nしまうのは\n妖魔のせいデスか！？", 1, 117801, 0, 0, 5501);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "トーゴク妖怪の\n図鑑デス！　個性的な\n妖怪ばかりデスね！", 1, 117801, 0, 0, 5502);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 12, 3, "ハロウィンの甘味を\n集めまシタよ！\nショーグンへの\n貢ぎ物デス！", 1, 117801, 0, 0, 5504);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "彼と二人で\n買い物に…って…\nこれってデートに\nなっちゃうのかな！？", 1, 101301, 0, 0, 5531);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "とうっ！　どうどう？\n今の決めポーズ！\nかっこいいよね♪", 1, 101301, 0, 0, 5532);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ヒデサイとおそろの\nハロウィンコスとか\nしてみたいな～", 1, 117901, 0, 0, 5533);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "カボチャ料理かぁ…\n作ったらヒデサイ\n食べてくれるかな～", 1, 117901, 0, 0, 5534);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ハロウィンスイーツ…\nどれもおいしすぎて\n激ヤバなんですけど！", 1, 117901, 0, 0, 5535);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "霊界ってどんなとこ\nなんだろ～\nわりと近所だったり？", 1, 117901, 0, 0, 5536);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "服をハロウィンっぽく\nアレンジするのも\nたのしーよね♪", 1, 117901, 0, 0, 5537);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ヒデサイと一緒に\nハロウィンパーティー\n…えへへ、楽しみ～", 1, 117901, 0, 0, 5538);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ヒデサイといると\nドキドキする…\nなんでだろ～？", 1, 117901, 0, 0, 5539);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ねねね、うちらも\nハロウィンパレード\n見に行こー？", 1, 117901, 0, 0, 5540);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ハロウィンセイバーズ\nしゅつどーう！\nヒデサイも行こ～♪", 1, 117901, 0, 0, 5541);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "マントのロゴ\nかっこいいっしょ～？\nカボきちってゆーんだ", 1, 117901, 0, 0, 5542);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "トリックオア\nトリート！\nねえねえヒデサイ\nお菓子ちょうだい♪", 1, 117901, 0, 0, 5543);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ヒデサイも\nメイクしてみる？\nハロウィンぽいやつ♪", 1, 117901, 0, 0, 5544);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ヒデサイのこと\nうちがいつでも\nあっためたげるね！\n…あ！　手、手の話！", 1, 117901, 0, 0, 5545);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ハロウィンのイベント\n朝からでも\nやってるかな～？", 1, 117901, 0, 1, 5546);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "カボチャでおやつ\n作ってみたんだ～\nヒデサイ食べてみて！", 1, 117901, 0, 2, 5547);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ハロウィンの夜って\nやっぱテンション\n上がるよね～♪", 1, 117901, 0, 3, 5548);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "超ふかふかしてる～\nちょっと休憩させて\nもらっちゃお", 1, 117901, 0, 0, 5550);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "はぁ…\nもにカワすぎて\nつらいんですけど～！", 1, 117901, 0, 0, 5551);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ハロウィン限定の\nフレグランスじゃん！\nいい匂いする～♪", 1, 117901, 0, 0, 5552);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "やばばば…\nあったかくて\n眠くなっちゃう～", 1, 117901, 0, 0, 5553);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "これ食べて\nもうひとがんばり\nしよーっと！", 1, 117901, 0, 0, 5555);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ハロウィンっぽい\nファッションとか\n載ってないかなぁ？", 1, 117901, 0, 0, 5556);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 12, 3, "お菓子いっぱいだ～！\nあとでヒデサイにも\n持ってってあげよ～", 1, 117901, 0, 0, 5558);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "お掃除が終わったら\n次は書類を片付けて…\nその次は…", 1, 118501, 0, 0, 5560);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "皆さんが冒険している\n間の留守は私に\nお任せください♪", 1, 118501, 0, 0, 5561);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "美食殿の皆さんが\n持ってきてくれる\nお土産が楽しみです♪", 1, 118501, 0, 0, 5562);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ネビアさんとは\nときどき一緒にお茶\nする仲なんです", 1, 118501, 0, 0, 5563);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ギルドハウスの乱れは\nギルドの乱れ\n整理整頓が大切です", 1, 118501, 0, 0, 5564);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "素敵なギルドハウスの\n管理人ができて\nとっても幸せです♪", 1, 118501, 0, 0, 5565);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "皆さんをほんの少し\n特別扱いしちゃう\n私がいます", 1, 118501, 0, 0, 5566);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "何かわからないことが\nあるときは私に\n聞いてくださいね", 1, 118501, 0, 0, 5567);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "書類を書いていると\n落ち着きます…\n一緒にどうですか？", 1, 118501, 0, 0, 5568);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あなたのまわりは\nいつも賑やかで\n楽しいですね♪", 1, 118501, 0, 0, 5569);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あっ！　お頼みしたい\nことがあって\n探してたんです♪", 1, 118501, 0, 0, 5570);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ギブアンドテイクは\n大切です。たまには\nお礼させてください♪", 1, 118501, 0, 0, 5571);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "陰に日向にあなたを\n支えていきます♪\n期待していてください", 1, 118501, 0, 0, 5572);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日も一日\n管理人として\nがんばります♪", 1, 118501, 0, 1, 5573);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹がすきました…\nそろそろお昼に\nしませんか？", 1, 118501, 0, 2, 5574);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もうこんな時間…\n皆さんといると一日が\nあっという間です", 1, 118501, 0, 3, 5575);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "良質なお仕事は\n良質な休憩から\nです♪", 1, 118501, 0, 0, 5577);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいものに\n囲まれてお仕事できる\nのは幸せですね♪", 1, 118501, 0, 0, 5578);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "お仕事に集中できる\nアロマを設置するのも\nよさそうですね♪", 1, 118501, 0, 0, 5579);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ポカポカ温まりながら\n書類仕事をするのも\nいいものですね…", 1, 118501, 0, 0, 5580);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "栄養補給しないと\n頭が回りませんからね\nきちんと食べましょう", 1, 118501, 0, 0, 5582);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "新条例はこのように\n活用されている、と…\nふむふむ…", 1, 118501, 0, 0, 5583);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "会合用の資料と\n連載のネーム…\nどっちを片付けよう？", 1, 106701, 0, 0, 5585);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "イノリちゃん、また\nお金くすねてる…\n帰ってきたら\nお尻ペンペンだ♪", 1, 106701, 0, 0, 5586);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "カヤちゃんの装備\n傷むの早いなぁ〜\nメンテしてあげないと", 1, 106701, 0, 0, 5587);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "そうだ、ラーゴのご飯\n買いに行かないと\n今日は何がいいかな？", 1, 106701, 0, 0, 5588);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ここの人たちは見てて\n飽きない人ばっかり♪\n漫画の参考にしよ〜", 1, 106701, 0, 0, 5589);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "また一緒に買い物にも\n行きたいし、冒険も\nしたいな〜…♪", 1, 106701, 0, 0, 5590);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "…君は見てるだけで\n満足なの？ ちゃんと\n触って欲しいな…♪", 1, 106701, 0, 0, 5591);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "私の目が見たいの？\nいいけど…魅了されて\n魂が壊れちゃうよ…？\n…冗談で〜す☆", 1, 106701, 0, 0, 5592);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ラーゴがね、君に\n遊んで欲しいって☆\n仲良くしてあげてね", 1, 106701, 0, 0, 5593);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "アシスタントの仕事\n気に入ってくれたなら\nまたお願いしていい？", 1, 106701, 0, 0, 5594);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "私が覚醒できるか？\n見せてあげたいけど…\nすごいことになるから\nまた今度で♪", 1, 106701, 0, 0, 5595);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "楽しいトラブルが\nあったら、とりあえず\n声はかけて欲しいな♪", 1, 106701, 0, 0, 5596);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "マッサージお願い♪\n変なところは…\n少しだけなら☆", 1, 106701, 0, 0, 5597);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう〜♪\n今日も一日、一緒に\nがんばっていこうね", 1, 106701, 0, 1, 5598);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹空いちゃった…\n一緒にお昼行かない？\nいいお店があるんだ〜", 1, 106701, 0, 2, 5599);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "君、眠れないの？\n誰かに見られてる？\n…きっと気のせいだよ", 1, 106701, 0, 3, 5600);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ちょっと休憩〜…\nこのまま原稿すれば\n疲れなくなるのかな？", 1, 106701, 0, 0, 5602);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい〜♪\nラーゴのお友達に\nなってくれる？", 1, 106701, 0, 0, 5603);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り〜♪\nこの目でどう見えるか\n伝えられたらいいのに", 1, 106701, 0, 0, 5604);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ほどほどなのが\nちょうどいい時も\nあるよね…♪", 1, 106701, 0, 0, 5605);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "この味付け…\nあっちでも再現\nできるかな？", 1, 106701, 0, 0, 5607);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふふっ、面白い♪\nイノリちゃんの買う\n漫画にハズレなし☆", 1, 106701, 0, 0, 5608);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "私…23歳だもん\n魔法少女だなんて\n名乗れないわ…", 1, 119001, 0, 0, 5610);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "あん、どぅ、とろわ〜\nみんなイイ子に\nな〜る♪", 1, 119001, 0, 0, 5611);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "あっ！　イケナイ子の\n気配がするわ！\n風紀の乱れは\n先生が許しませんっ！", 1, 119001, 0, 0, 5612);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ここで闇の力が\n発動したら大変だわ！\nやだっ…そう思ったら\n緊張して…ダメぇ〜！", 1, 119001, 0, 0, 5613);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "オイタした子はみんな\nどうしてうれしそうに\n私の愛のムチを\n欲しがるのかしら…？", 1, 119001, 0, 0, 5614);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あの子に次は何を\n教えてあげようかしら\n愛？　希望？\nそれとも…♪", 1, 119001, 0, 0, 5615);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あの子のことを\n考えると、愛と希望で\n胸がいっぱいになるの", 1, 119001, 0, 0, 5616);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "先生なのに闇の力を\n持ってるのは秘密よ？\n他の子には\n知られたくないから…", 1, 119001, 0, 0, 5617);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "秘密の授業の内容？\nそれは…あんなことや\nこんなことよ♪\nそれから、それから…", 1, 119001, 0, 0, 5618);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "しーっ！　私の正体が\nルーセント学院の\n先生だって、ここでは\n秘密にしててね？", 1, 119001, 0, 0, 5619);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あら？　補習して\nほしいの？　いいわよ\n君のお願いなら\nなんでも聞いちゃう♪", 1, 119001, 0, 0, 5620);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "イイ子にはごほうびを\nあげなくちゃ！\n君はなにが欲しい？\n遠慮しちゃダメよ？", 1, 119001, 0, 0, 5621);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "君との秘密が\nまた一つ\n増えちゃったね♪", 1, 119001, 0, 0, 5622);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日も一日\n元気に過ごしましょう\n先生が指導してあげる", 1, 119001, 0, 1, 5623);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "夜まで頑張れるように\nお昼ご飯はしっかり\n食べましょう〜！", 1, 119001, 0, 2, 5624);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜更かしはダメよ？\nイケナイ子が\nすることです！", 1, 119001, 0, 3, 5625);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "闇の力に振り回されて\nもうヘトヘトよ〜\n心も体も\n癒されたいわ〜", 1, 119001, 0, 0, 5627);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "『秘密の学び舎』に\nこっそり連れて\n行っちゃおうかしら♪", 1, 119001, 0, 0, 5628);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "イケナイ甘い香り…\nなんだか胸の奥が\n熱くなってきたわ…♪", 1, 119001, 0, 0, 5629);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "やんっ♪\n燃え上がる愛みたい♪\n火照ってきちゃった♪", 1, 119001, 0, 0, 5630);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "生徒の見本に\nなれるように\n好き嫌いはしないの", 1, 119001, 0, 0, 5632);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "『学び舎に咲く禁断の\n愛』？　気になるわ…\nううん、ダメよっ！\nでも…ちょっとだけ…", 1, 119001, 0, 0, 5633);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "次に会う時は、\nまたあそこに一緒に…\nえへへ…！", 1, 106301, 0, 0, 5635);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "横顔見てるの、\nバレてないよね…？\n…ちらっ", 1, 106301, 0, 0, 5636);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "背が少し伸びたか！？\nあ、あいつのところへ\n報告に行かねばっ！", 1, 105301, 0, 0, 5637);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "私も貴公の隣に\n立っていられるよう\n日々精進していくぞ！", 1, 105301, 0, 0, 5638);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ああ～\nドＭミストが\nあふれてしまいます～", 1, 119101, 0, 0, 5639);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "魔法少女として\nクウカ頑張ります～！\n愛と希望の妄想を…！", 1, 119101, 0, 0, 5640);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "決めポーズの練習より\nやられポーズの練習を\nしておきます…♪", 1, 119101, 0, 0, 5641);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "快感を溜めに溜めて\n放つドＭビームは\n最高ですよ～", 1, 119101, 0, 0, 5642);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "はっ！\nこれは闇の気配！\n…クウカ自身でした", 1, 119101, 0, 0, 5643);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ドＳさん…ぐふふ…\nクウカを縛りあげ…\nじゅるりぃ～♪", 1, 119101, 0, 0, 5644);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ドＳさんに攻められる\nことで、クウカは進化\nしてゆくのです～！", 1, 119101, 0, 0, 5645);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "はぅっ！\nもっと激しく…！\n情熱的に～～～！", 1, 119101, 0, 0, 5646);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "クウカの変身シーンを\nじっくり眺めたい！？\nは、恥ずかしいです～", 1, 119101, 0, 0, 5647);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "「本当に魔法少女か\n確かめてやるよ…！」\nドＳさんはそう言って\nクウカを…ぐふふ…♪", 1, 119101, 0, 0, 5648);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "愛と希望の力が\nクウカの中に…\nこの胸の高鳴りが…？", 1, 119101, 0, 0, 5649);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ひゃあんっ！\nそこです～っ！\nもっと、もっと～♪", 1, 119101, 0, 0, 5650);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "クウカをこんなに\n悦ばせるのは\nドＳさんだけです…♪", 1, 119101, 0, 0, 5651);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "明るい時間に出歩くと\n目立ちますね\n魔法少女の衣装…", 1, 119101, 0, 1, 5652);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼の見回りです～♪\nああ～うっかりドＭを\n増やしてしまいました", 1, 119101, 0, 2, 5653);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜！　それはクウカが\n活性化する時間です！\n闇の活動開始です～♪", 1, 119101, 0, 3, 5654);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "気の緩んだクウカを\nドＳさんの鋭い牙が\n狙っています～♪", 1, 119101, 0, 0, 5656);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "魔法少女のマスコット\nにいいかもしれません\nもっと鎖とか飾りを…", 1, 119101, 0, 0, 5657);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "魅惑的な香りです～\nドＭミストの香りに\n似て…いや違いますね", 1, 119101, 0, 0, 5658);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "火照る体…紅潮した\nクウカの肢体を熱く\n見つめるドＳさん…", 1, 119101, 0, 0, 5659);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食欲を満たした次は\n何を満たせば\nいいですかねぇ～♪", 1, 119101, 0, 0, 5661);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "魔法少女がひどい目に\n遭う物語は…\nなさそうですね…", 1, 119101, 0, 0, 5662);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ケーキも悪くないけど\nプリンが一番なの\nでもせっかくだから\n両方もらってやるの！", 1, 119901, 0, 0, 5664);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "クリスマスって聞くと\nなんだかあったかい\n気分になるの～", 1, 119901, 0, 0, 5665);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "煙突がなくても\nミヤコはどこからでも\nおうちに入れるの♪", 1, 119901, 0, 0, 5666);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "イブもプリン！\nクリスマスもプリン！\nプレゼントもプリン！", 1, 119901, 0, 0, 5667);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "クリスマスツリーの\n高いところの\n飾りつけは、ミヤコに\nまかせろなの～！", 1, 119901, 0, 0, 5668);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "アイツのプレゼント\n楽しみなの～\nきっと最っ高に特別な\nプリンなの～♪", 1, 119901, 0, 0, 5669);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ミヤコがサンタなら\nアイツはトナカイなの\nつまりお似合いって\nことなの～♪", 1, 119901, 0, 0, 5670);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ミヤコ、プレゼントを\n配りにいくの～♪\nオマエも手伝えなの！", 1, 119901, 0, 0, 5671);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "オマエにも飾りつけ\nしてやるの！\n頭にプリンを乗せると\nかわいいの♪", 1, 119901, 0, 0, 5672);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "幽霊のミヤコが\nいるなら、サンタも\nいて当たり前なの～！", 1, 119901, 0, 0, 5673);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "靴下にプリンを\n入れたらつぶれるの\nだからプリンは直接\nミヤコによこすの～！", 1, 119901, 0, 0, 5674);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "今日はプリンだけじゃ\n満足してやらないの！\nミヤコをたくさん\n甘やかせなの！", 1, 119901, 0, 0, 5675);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ミヤコのプリン\nオマエになら一個…\nうう～、一口だけ\nあげてもいいの！", 1, 119901, 0, 0, 5676);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "サンタの朝は早いの～\nミヤコも早起きして\nプレゼント準備したの\nとってもえらいの♪", 1, 119901, 0, 1, 5677);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今日は一日中\nみんなと遊ぶの～！\nオマエも来いなの！", 1, 119901, 0, 2, 5678);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "みんなが寝たら\nチャンスなの～\nこっそりプレゼント\n配りにいくの♪", 1, 119901, 0, 3, 5679);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "むふー、気持ちいいの\nこういうプレゼントも\nいいかもしれないの", 1, 119901, 0, 0, 5681);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "これ気に入ったの～\nプリンとアイツの\n次くらいなの♪", 1, 119901, 0, 0, 5682);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いいにおいなの～\nうっかり成仏\nしちゃいそうなの…", 1, 119901, 0, 0, 5683);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ここに飾っといた\n雪だるま\nなくなっちゃったの\nきっと成仏したの～", 1, 119901, 0, 0, 5684);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "これはオマエがくれる\nプリンとは\n別腹なの～", 1, 119901, 0, 0, 5686);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "プリンケーキ…\nこれならミヤコにも\n作れそうなの！\nさっそく作るの！", 1, 119901, 0, 0, 5687);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 14, 3, "びっくりしたの～！\n幽霊のミヤコを\n驚かすなんて…\nなかなかやるの！", 1, 119901, 0, 0, 5689);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 15, 3, "コイツの中…\nあったかいの～♪\n昼寝にぴったりなの～", 1, 119901, 0, 0, 5690);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "メリークリスマス！\n聖夜に笑顔を\nお届けするべ♪", 1, 119201, 0, 0, 5691);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "クリスマス前は\n乳製品がよく売れて\nありがてぇけんど…\n目が回る忙しさだ～", 1, 119201, 0, 0, 5692);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "牧場で売る\nクリスマスリースを\n作っておかねぇと…", 1, 119201, 0, 0, 5693);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "うちの動物たちにも\nクリスマスプレゼント\n用意しなきゃなぁ", 1, 119201, 0, 0, 5694);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "クリスマスに向けた\n限定商品とか\n作ってみるべか？", 1, 119201, 0, 0, 5695);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あんちゃんへの\nプレゼント選び…\nここでボケるか…？\nやめておくべか…？", 1, 119201, 0, 0, 5696);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "オラ、あんちゃんから\n本当にたくさんの物を\nもらってんなぁ…", 1, 119201, 0, 0, 5697);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "雪遊びがしたいべか？\nへへっ、あんちゃん\nには負けねぇど！", 1, 119201, 0, 0, 5698);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ディナーと一緒に\n聖夜のお笑いライブを\nすんのはどうだべか？\nツッコミは任せたべ！", 1, 119201, 0, 0, 5699);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "寒くなってくると\n鍋が食べたくなるべや\nあんちゃんはどうだ？", 1, 119201, 0, 0, 5700);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あんちゃんは\nサンタさんのこと\n信じてるだか？", 1, 119201, 0, 0, 5701);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "どでかいクリスマス\nケーキをこさえるべ\nあんちゃんも作るの\n手伝ってくんろ♪", 1, 119201, 0, 0, 5702);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あんちゃんが\nオラの旦那だったら…\nって、あんちゃん！\n今の聞いてただか！？", 1, 119201, 0, 0, 5703);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "牧場の朝は早いど！\nさぁてと、まずは\n雪かきしに行くべや", 1, 119201, 0, 1, 5704);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あんちゃんも一緒に\nお昼食べてくか？\n採れたての冬野菜は\nうんまいど～♪", 1, 119201, 0, 2, 5705);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "よい子は早く寝ねぇと\nサンタさんが\n来てくれねぇべよ？", 1, 119201, 0, 3, 5706);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "こういうのリンリンが\n好きそうだな…\nプレゼント候補に\n入れておくべ！", 1, 119201, 0, 0, 5708);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "もふもふしてて\nなまらめんこくて…\nあぁ…癒されるべや…", 1, 119201, 0, 0, 5709);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この匂い…\n気持ちが和むべや\n夢心地になっちまうな", 1, 119201, 0, 0, 5710);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったけぇところは\n落ち着くなぁ…\nつい眠くなっちまう", 1, 119201, 0, 0, 5711);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "こ、この味は…！\n…うーん、もっと\nリアクション芸も\n練習しねぇとな", 1, 119201, 0, 0, 5713);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "シオシオって\nどんな本読んでんだ？\n…難しい字が\nぎっしりだべや…", 1, 119201, 0, 0, 5714);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 14, 3, "この仕掛け…\nオラのコントに\n活かせるかも\nしんねぇな", 1, 119201, 0, 0, 5716);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 15, 3, "この着ぐるみで\nリマリマのモノマネを\n練習してみるべか…？", 1, 119201, 0, 0, 5717);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "もっとキレイになって\nアイツにぎゃふんと\n言わせてやるんだから", 1, 105001, 0, 0, 5718);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "アタシのこと\nどう思う？\nかわいいって…そこは\nキレイって言ってよね", 1, 105001, 0, 0, 5719);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ハートマークの刺繍…\nは、やりすぎですかね\nいやちょっとくらい\nアピールしてみても…", 1, 119301, 0, 0, 5720);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "雪降らないかな～\nそしたらお兄ちゃんと\n雪だるま作ったり\nできるのに～", 1, 119301, 0, 0, 5721);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "プレゼントを入れる\n靴下…いくつ編んでも\n足りません～！", 1, 119301, 0, 0, 5722);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お兄ちゃんとの\nクリスマスデートは\n早い者勝ちですからね\n負けませんよ～！", 1, 119301, 0, 0, 5723);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "クリスマスだし…\n受験勉強は今日だけ\nお休みです♪", 1, 119301, 0, 0, 5724);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お兄ちゃんと\nおそろいのコーデで\nクリスマスデート…\nしたいなぁ～！", 1, 119301, 0, 0, 5725);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "お兄ちゃんに\nプレゼントする編み物\nこれで３着目～と♪\nあれ、作りすぎ？", 1, 119301, 0, 0, 5726);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "えへへ、もっと近くで\n見たくありませんか？\n私のとっておきの\nクリスマスコーデ♪", 1, 119301, 0, 0, 5727);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お兄ちゃんが風邪を\n引いたら一大事です！\n私の編み物で暖かく\nしてあげます♪", 1, 119301, 0, 0, 5728);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お兄ちゃん、ほっぺに\nケーキのクリームが\nついちゃってますよ♪\n私がとってあげます！", 1, 119301, 0, 0, 5729);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お兄ちゃん！\nケーキ、あーんって\nしてあげます！\nほら、あーん♪", 1, 119301, 0, 0, 5730);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "クリスマスは大切な\n人と過ごすものっ！\nお兄ちゃん…妹の予定\n空いてますよっ！", 1, 119301, 0, 0, 5731);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "クリスマスはずっと、\nお兄ちゃんと一緒に\nいたい…って言ったら\n欲張り…すぎですか？", 1, 119301, 0, 0, 5732);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "早起きは３本お得！\n…クリスマスなら\n追加で10本ぐらい\nもらえちゃうかも！？", 1, 119301, 0, 1, 5733);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼はケーキ？\nそれとも七面鳥？\nごちそういっぱいで\n迷っちゃいますね～♪", 1, 119301, 0, 2, 5734);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お兄ちゃんと\nクリスマスに夜更かし\n…えへへ、ちょっぴり\nドキドキしちゃう♪", 1, 119301, 0, 3, 5735);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "編み物をするには\n絶好のくつろぎ空間\nですね～♪", 1, 119301, 0, 0, 5737);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "なんというかわいさ…\nクリスマス\nプレゼントに\nもってこいですね！", 1, 119301, 0, 0, 5738);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "これがお兄ちゃんの\nお部屋の香り…？\nんん～！　ずっと\nかいでいたいです～♪", 1, 119301, 0, 0, 5739);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ふぁ、あったか～い…\n冬場はこういうのが\nありがたいですね～♪", 1, 119301, 0, 0, 5740);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ごちそうだぁ～♪\nほら、お兄ちゃんも\n食べて食べてっ！", 1, 119301, 0, 0, 5742);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "クリスマスデートの\n必勝法…こ、これは\n読むしかないです！", 1, 119301, 0, 0, 5743);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 14, 3, "わっ、すごいです～！\nこれを飾っておけば\nクリスマスが一層\n賑やかになりますね♪", 1, 119301, 0, 0, 5745);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 15, 3, "さぷらーいずっ！\nリマちゃんじゃなくて\nリノちゃんでした～！", 1, 119301, 0, 0, 5746);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ミミにもミソギにも\nあの人にも頼りに\nしてもらえるように\nしっかりしなきゃ！", 1, 120601, 0, 0, 5747);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ミミはにんじんを\n食べられてすごいな…\n私も見習わなきゃ\nがんばろう…！", 1, 120601, 0, 0, 5748);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ミソギから怖い話\n聞いちゃった…\nうぅ…誰か一緒に\nいてくれないかな", 1, 120601, 0, 0, 5749);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "立派な大人に\nなれるように\nいっぱい勉強\nしておかなくっちゃ！", 1, 120601, 0, 0, 5750);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "なんだか…あの人の\nあやしい視線を\n感じるような…？", 1, 120601, 0, 0, 5751);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あの人に勉強を\n教えられるように\nしっかり予習を\nしておこうっと…！", 1, 120601, 0, 0, 5752);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "今日はあの人と\n一緒に冒険できる…\nなんだかワクワク\nしてきちゃった…！", 1, 120601, 0, 0, 5753);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あ、いいとこに来て\nくれましたね！\nあなたに頼みたい\nことがあるんです！", 1, 120601, 0, 0, 5754);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "きゃあっ！？\nへ、変なところを\n触らないでください！", 1, 120601, 0, 0, 5755);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "どうですかこの格好？\nかわいい、ですか…？\nそ、そうですか…\nありがとうございます", 1, 120601, 0, 0, 5756);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ひゃあっ…！\nすみません、勉強に\n集中してたので\n驚いちゃいました", 1, 120601, 0, 0, 5757);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "一緒に勉強して立派な\n大人になりましょうね\n私がそばで見張ってて\nあげます", 1, 120601, 0, 0, 5758);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "まだ立派ではないかも\nですけど、私よりも\n大人なあなたのことは\n頼りにしてますからね", 1, 120601, 0, 0, 5759);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "立派な大人は\n朝の時間の使い方が\n上手だと聞きました\nあなたはどうですか？", 1, 120601, 0, 1, 5760);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ミミとミソギと\nあなたと…大事な人と\n一緒のお昼ごはんは\nやさしい味がしますね", 1, 120601, 0, 2, 5761);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "うぅ…怖い話を\n思い出しちゃいました\n寝るまで一緒に\nいてくれますか…？", 1, 120601, 0, 3, 5762);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "すごい座り心地…！\nとっても勉強が\nはかどりそう…！", 1, 120601, 0, 0, 5764);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "この子…なんだか\nミミに似てるような\n気がする…ふふっ♪", 1, 120601, 0, 0, 5765);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り…♪\n勉強で疲れた\n頭がリフレッシュ\nできそうです", 1, 120601, 0, 0, 5766);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ぽかぽかだ…♪\nミミとミソギと\nあの人と一緒に\nいるときみたい", 1, 120601, 0, 0, 5767);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いっぱい食べたら\n早く大人になれたり\nしないかな…？", 1, 120601, 0, 0, 5769);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "あう…\n知らない単語が…\nちゃんと調べて\n覚えなくっちゃ…！", 1, 120601, 0, 0, 5770);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "うさぎさんが\nぴょ～んぴょん♪\nみんなえがおで\nるんたった～♪", 1, 120401, 0, 0, 5773);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "キョウカちゃんも\nいつかにんじんさんを\n好きになってくれたら\nうれしいな～♪", 1, 120401, 0, 0, 5774);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "今日のミソギちゃんの\nイタズラ、びっくり\nしちゃったけど\nおもしろかったな～♪", 1, 120401, 0, 0, 5775);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "このおうち、いつも\nいろんな人がいて\nドキドキぴょんぴょん\nって楽しいな～♪", 1, 120401, 0, 0, 5776);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "いいお天気～♪\nお外でみんなと\nいっぱい遊びたいな♪", 1, 120401, 0, 0, 5777);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ミソギちゃんも\nキョウカちゃんも\nおにいちゃんがいると\nずっと笑顔だね～♪", 1, 120401, 0, 0, 5778);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "おにいちゃんにはやく\nあいたいな～♪\nまだかな、まだかな♪", 1, 120401, 0, 0, 5779);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "えへへ♪\nおにいちゃんに\nなでなでされると\nぽかぽかするね♪", 1, 120401, 0, 0, 5780);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "聞いて、おにいちゃん\nさっきね、かわいい\nちょうちょさんに\n会ったんだよ～♪", 1, 120401, 0, 0, 5781);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふわっ…！\nおにいちゃんの顔を\nお絵かきしてたから\nびっくりしちゃった♪", 1, 120401, 0, 0, 5782);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "おにいちゃんも\n遊びたいの？\nそれじゃあ二人も\n呼んで遊ぼう♪", 1, 120401, 0, 0, 5783);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "おにいちゃんも\nみんなも、優しい人\nばっかりで\nミミ幸せ～♪", 1, 120401, 0, 0, 5784);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "おにいちゃん♪\n高い高いしてほしいな\nすっごくぴょんぴょん\nできて、好きなんだ♪", 1, 120401, 0, 0, 5785);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう～♪\nおにいちゃん、今日は\nおひさまみたいに\nきらきら元気だね～♪", 1, 120401, 0, 1, 5786);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おひるごはんだね～♪\nにんじんさんを\nいっぱい食べて\n元気いっぱい♪", 1, 120401, 0, 2, 5787);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふわあ…\n眠くなってきちゃった\nおにいちゃん、\n一緒に寝よう～？", 1, 120401, 0, 3, 5788);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふわぁ、気持ちいい♪\nずっとこうやって\n座ってたくなるね～♪", 1, 120401, 0, 0, 5790);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "わあ、かわいい～\nぎゅ～っ、ぎゅ～っ♪\nこれで仲よしだね\nえへへ♪", 1, 120401, 0, 0, 5791);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "気持ちいいにおい～♪\nぴょんぴょんしたく\nなってきちゃった♪", 1, 120401, 0, 0, 5792);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかぽかぽか♪\nおにいちゃんも\nきてくれたら、もっと\nあったかくなりそう♪", 1, 120401, 0, 0, 5793);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…ごっくん♪\nおっきくなりたいから\nいっぱい食べるよ～♪", 1, 120401, 0, 0, 5795);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "えへへ、おもしろ～い\nこの絵本ね、\nキョウカちゃんから\n教えてもらったんだ♪", 1, 120401, 0, 0, 5796);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この部屋…探索の\nしがいがありそう！\nついでにイタズラも\nしかけちゃお♪", 1, 120501, 0, 0, 5799);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ミミってああ見えて\n実は大胆で度胸も\nあるよね…ちょっと\nかっこいいな…！", 1, 120501, 0, 0, 5800);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "怖い話を聞いた時の\nキョウカって\n面白いんだよね～♪", 1, 120501, 0, 0, 5801);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "にいちゃんが\n慣れちゃわないように\nまた新しいイタズラを\n考えなきゃ！", 1, 120501, 0, 0, 5802);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "イタズラもいいけど\nミミとキョウカと\nにいちゃんと、普通に\n遊ぶのも楽しいなぁ♪", 1, 120501, 0, 0, 5803);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ミミにキョウカ、\nそれににいちゃん！\nみんなそろえば愉快な\n冒険が始まりそう！", 1, 120501, 0, 0, 5804);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "次はどんなイタズラを\nしたら、にいちゃんは\n喜んでくれるかな？", 1, 120501, 0, 0, 5805);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今ミソギに触ったね？\nヤバいよにいちゃん…\n逃げないとトラップが\n発動しちゃうよ…！", 1, 120501, 0, 0, 5806);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "わわっ！？　びっくり\nしたあ…！　新しい\nトラップを作ってて\n気づかなかったよ～", 1, 120501, 0, 0, 5807);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お？　にいちゃん、\nイタズラする側にも\n興味があるの？", 1, 120501, 0, 0, 5808);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "にいちゃんなにか用？\nあ、もしかして…\nミソギと遊びたく\nなっちゃった？", 1, 120501, 0, 0, 5809);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ベストタイミングだよ\nにいちゃん！\n今からみんなで探検に\n行くところなんだ！", 1, 120501, 0, 0, 5810);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "にいちゃんってさ\nホントに優しいよね\nなにしても怒らないし\n…ありがとね♪", 1, 120501, 0, 0, 5811);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "にいちゃんおはよー！\n景気づけに本日\n一発目のイタズラ、\nやっちゃうよ～♪", 1, 120501, 0, 1, 5812);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ごはんはロシアン\nサンドイッチだよ！\nさあ、にいちゃん！\n好きなの選んでよ！", 1, 120501, 0, 2, 5813);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜ってなんだか\nワクワクしてなかなか\n眠れないんだよね\nにいちゃんはどう？", 1, 120501, 0, 3, 5814);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "この座り心地のよさ…\nなにかのトラップに\nうまく使えないかな？", 1, 120501, 0, 0, 5816);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "こういうのに細工して\nミミやキョウカを\n驚かせると、いい反応\nするんだよね♪", 1, 120501, 0, 0, 5817);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "においをうまく使った\nイタズラって…\nなにかないかな？", 1, 120501, 0, 0, 5818);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったまりながら\n新しいイタズラを\n考えると、いい案が\n出て来たりするんだ♪", 1, 120501, 0, 0, 5819);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいしくてついつい\n食べ過ぎちゃうなぁ…\nはっ…！？　これって\nまさかトラップ…！？", 1, 120501, 0, 0, 5821);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "このキョウカから\n借りた冒険物語\nすっごく\nおもしろいんだよね！", 1, 120501, 0, 0, 5822);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "晴れ着を着ると\nなんだか心が躍るね\n足取りも軽く\nなるってもんさ", 1, 120801, 0, 0, 5825);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "正月の食べ物ってのは\n美味いもんだね\nいくらでも\n食べれちまうよ", 1, 120801, 0, 0, 5826);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "普段は好き勝手してる\nアタシらも\n正月くらいは\n大人しくするさ", 1, 120801, 0, 0, 5827);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "年越しそばに雑煮\nこの季節は\n温かいものが\n体に沁みるね", 1, 120801, 0, 0, 5828);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "正月だからって\nのんびりしすぎたね\nちょっと釣りにでも\n行こうかね", 1, 120801, 0, 0, 5829);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "いい正月だね\nいつかあの子と\n一杯やりたいもんだよ", 1, 120801, 0, 0, 5830);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "大事な人と過ごす\n正月ってのがこんなに\n楽しいもんだとはね", 1, 120801, 0, 0, 5831);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "部屋があったかくて\n顔が火照っちまったよ\nちょいと外に涼みに\n行かないか？", 1, 120801, 0, 0, 5832);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "餅ってのは\n何をつけてもうまいね\nお前さんは\nどの味が好きだい？", 1, 120801, 0, 0, 5833);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お祝いの鯛が\n足りないって？\nそれじゃあアタシが\n釣ってきてやるよ", 1, 120801, 0, 0, 5834);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "おせちが美味いのは\n分かるけど\n食べ過ぎには\n気を付けるんだよ", 1, 120801, 0, 0, 5835);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お前さんのおかげで\nいい正月を\n迎えられたよ\nありがとさん！", 1, 120801, 0, 0, 5836);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "慣れない晴れ着も\nお前さんに見て\nもらえたなら\n着たかいがあったね", 1, 120801, 0, 0, 5837);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようさん\n寒いのは分かるけど\nいい加減布団から\n出て顔洗ってきな", 1, 120801, 0, 1, 5838);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今日の昼飯は雑煮だ\nアタシの郷土の味\nしっかり味わって\nおくれよ", 1, 120801, 0, 2, 5839);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おや、お前さんも\n夜ふかしかい？\n退屈してたところさ\n付き合っておくれよ", 1, 120801, 0, 3, 5840);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "晴れ着だと座り方にも\n気を遣うね\nしわになったら大変さ", 1, 120801, 0, 0, 5842);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "せっかくだし\nこの子にも晴れ着を\n着せてあげたいね", 1, 120801, 0, 0, 5843);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "これは冬の花の香り…\n風情があって\nいいじゃないか", 1, 120801, 0, 0, 5844);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかいねぇ…\nこんな寒い日には\nまさに天国だよ", 1, 120801, 0, 0, 5845);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いつも食べてる\nものでも正月に\n食べると\n新鮮な気がするね", 1, 120801, 0, 0, 5847);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "せっかくの正月休みだ\nたまにはゆっくりと\n本でも読もうかね", 1, 120801, 0, 0, 5848);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "新年のあいさつ…\n私も街のみんなに\nしてみようかしら…", 1, 120701, 0, 0, 5850);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "正月はゆっくり過ごす\nのよね…ゆっくりって\n何したらいいのかしら", 1, 120701, 0, 0, 5851);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "この格好も\n慣れてくれば\n動きやすいわ", 1, 120701, 0, 0, 5852);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "う～ん、今年の抱負…\nやりたいことが\nたくさんあるのよね", 1, 120701, 0, 0, 5853);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "おせち料理\nネビアの分も\n用意しなくちゃね", 1, 120701, 0, 0, 5854);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ふふっ\n正月っていいわね\nみんな楽しそうだもの", 1, 120701, 0, 0, 5855);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "新年の思い出…\nこれからもっと作るわ\nそれが私の抱負よ", 1, 120701, 0, 0, 5856);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日は家で過ごすの？\nあなたと一緒なら\nきっと楽しいわね", 1, 120701, 0, 0, 5857);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "どう？　この格好？\nコッコロさんは\n褒めてくれたけど…", 1, 120701, 0, 0, 5858);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ちょうど良かったわ\nあなたも大掃除\n手伝ってくれる？", 1, 120701, 0, 0, 5859);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "これから料理するけど\nお雑煮と焼き餅\nどっちが好きかしら？", 1, 120701, 0, 0, 5860);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "『今の私』にとって\n初めての正月だもの\nあなたと楽しまないと", 1, 120701, 0, 0, 5861);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "去年よりも今年…\nもっと成長するからね\n…お兄ちゃん♪", 1, 120701, 0, 0, 5862);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう\nせっかくの正月だもの\n朝から楽しまないとね", 1, 120701, 0, 1, 5863);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ねぇ…\n良かったら正月の遊び\n教えてくれるかしら？", 1, 120701, 0, 2, 5864);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふわぁ～…今日が\n終わっちゃうのが…\nもったいないわね…", 1, 120701, 0, 3, 5865);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふぅ…お参り後だから\n心地よすぎて眠って\nしまいそうだわ…", 1, 120701, 0, 0, 5867);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふふっ\nかわいいものって\n癒されるわね…", 1, 120701, 0, 0, 5868);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "…ん\nこれが梅の香り？\n…いい匂いね", 1, 120701, 0, 0, 5869);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "キャルじゃないけど…\nこのまま丸く\nなりたいところね…", 1, 120701, 0, 0, 5870);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "はむはむっ…♪\nせっかくの正月だもの\n堪能しなくちゃね♪", 1, 120701, 0, 0, 5872);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "…ふんふん\n帯の結び方って\nこんなにあるのね…", 1, 120701, 0, 0, 5873);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "今の私が作れる\n最高の一曲…\nあの人に届くといいな", 1, 104201, 0, 0, 5875);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "あの、歌を…\n聞いてくれませんか？\nあなたに贈る\n特別な歌を", 1, 104201, 0, 0, 5876);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ひい、ふう…\nむむ、みなに配る\nお年玉のポチ袋が\n残りわずかなのじゃ…", 1, 120901, 0, 0, 5877);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "宴の準備はわらわに\n任せておくのじゃ！\n支配者の手腕、\n見せつけてくれる！", 1, 120901, 0, 0, 5878);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "新年の願掛けなら\nわらわにすればよい\n支配者に頼むほうが\n確実じゃろう？", 1, 120901, 0, 0, 5879);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "みなからもらった\nこの年賀状とやら…\nわらわも\n書いてみようかの♪", 1, 120901, 0, 0, 5880);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "正月飾りにもいろいろ\n種類があるんじゃの～\nどれも華々しくて\nわらわ好みじゃ♪", 1, 120901, 0, 0, 5881);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あやつへのお年玉は\nちと多めにしておくか\n…日ごろの感謝も\n込めてのう", 1, 120901, 0, 0, 5882);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あやつのことを想うと\nそれだけで行く年\n来る年が楽しみになる\nふふ、愉快なやつじゃ", 1, 120901, 0, 0, 5883);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "みなに晴れ着を\n褒められて、とても\nよい気分なのじゃ♪\n次はお主の番じゃぞ？", 1, 120901, 0, 0, 5884);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お主へのお年玉は\nいちばん最後じゃ！\n残り物には福が宿る\nそうじゃからのう", 1, 120901, 0, 0, 5885);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "この季節は手が\nかじかむのう…ほれ、\nお主！　わらわの手を\nあたためるのじゃ！", 1, 120901, 0, 0, 5886);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お主のために雑煮を\n手作りしてみたのじゃ\n食べていくがよい♪", 1, 120901, 0, 0, 5887);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "眷属のお主に\n正月休みはまだ早い！\nずっとわらわのそばに\n控えておくのじゃ♪", 1, 120901, 0, 0, 5888);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ふふ、これほど楽しい\n正月は初めてじゃ…\nお主と過ごす時間は\nいつだって特別じゃな", 1, 120901, 0, 0, 5889);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "早起きしてわらわを\n待っておったのか？\nさすがはわらわの眷属\n殊勝な心がけじゃな♪", 1, 120901, 0, 1, 5890);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "食事どきじゃな\n正月の宴会料理が\nわらわたちを\n待っておるぞ♪", 1, 120901, 0, 2, 5891);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜も更けてきたのう\n冬の夜は長い…\n心ゆくまでお主と\n過ごせるわけじゃな♪", 1, 120901, 0, 3, 5892);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "実に心地がよい♪\nこのまま寝正月も\n悪くないかも\nしれぬのう", 1, 120901, 0, 0, 5894);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "愛いやつじゃのう\nわらわのそばに置いて\nやってもよいぞ♪", 1, 120901, 0, 0, 5895);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "品のある香りじゃのう\n寝室に置いておけば\nなにかご利益に\nあずかれそうじゃな", 1, 120901, 0, 0, 5896);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "心地よい…\nわらわはしばらく\nここから動かぬぞ\nお主も付き合うがよい", 1, 120901, 0, 0, 5897);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "舌鼓が鳴るのう♪\n正月の宴には\n持ってこいの品じゃ！", 1, 120901, 0, 0, 5899);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ほう、新春にはそんな\n習わしが…正月を\n制するには、まだまだ\n勉強が必要じゃのう", 1, 120901, 0, 0, 5900);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "久しぶりの我が家って\n感じです！　やっぱり\nここが一番ですね〜！", 1, 121001, 0, 0, 5902);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "さあ食べましょう！\nみんなで囲める食卓を\n心から味わいますよ☆", 1, 121001, 0, 0, 5903);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ランドソルに\n帰ってきた途端に\nお腹が空きました〜！", 1, 121001, 0, 0, 5904);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ただいま☆\n幸せ特盛りの\nわたしの日常！", 1, 121001, 0, 0, 5905);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ようやくランドソルに\n帰ってきたことですし\nやっぱり魔物料理を\nいただきましょう☆", 1, 121001, 0, 0, 5906);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あの人との絆を\n守るために\nもっともっと食べて\n強くならなくちゃ☆", 1, 121001, 0, 0, 5907);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "いつもありがとうって\nあの人を思いっきり\n抱きしめたいです☆", 1, 121001, 0, 0, 5908);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あなたの想いは\nこの身をかけて\n全力で受け止めます！", 1, 121001, 0, 0, 5909);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おかえりなさい☆\nここにいるみんなも\nあなたの帰りをずっと\n待っていましたよ！", 1, 121001, 0, 0, 5910);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "このギルドハウスで\n冒険の疲れを\n癒しましょう〜！", 1, 121001, 0, 0, 5911);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あなたの想いが\n全力全開を超える\n力をくれました！", 1, 121001, 0, 0, 5912);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "日常が続く幸せを\nあなたと一緒に\nかみしめたいです☆", 1, 121001, 0, 0, 5913);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ぎゅ〜っ！\nわたしたちは\nどんなことがあっても\nずっと一緒ですよ？", 1, 121001, 0, 0, 5914);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます！\nあなたと過ごせる\n幸せを、今日も\n味わいますよ〜！", 1, 121001, 0, 1, 5915);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ご飯の時間ですよー！\nあなたも一緒に\n食べましょうね！", 1, 121001, 0, 2, 5916);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "明日もあなたが隣に\nいてくれることを\n心から願ってますよ\nおやすみなさい☆", 1, 121001, 0, 3, 5917);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふい〜…\n安心できる場所で\nくつろげるって\n幸せですね〜…", 1, 121001, 0, 0, 5919);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "じゅるり…\n食べたくなっちゃう\nくらい、かわいい☆", 1, 121001, 0, 0, 5920);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "くんくん…おおー！\nステーキの香り！\nやばいですね☆", 1, 121001, 0, 0, 5921);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "体がぽかぽかしてきて\nわたしの食欲も\n燃えてきましたよー！", 1, 121001, 0, 0, 5922);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "わたしの食欲に\nついてこられますか？\nまだまだ食べますよ！", 1, 121001, 0, 0, 5924);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "これがキャルちゃんの\n言っていた、キスで\n目覚める王子様の\nおとぎ話ですか〜☆", 1, 121001, 0, 0, 5925);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "自分で自分を\n分析するのも、これは\nこれで面白い…♪", 1, 121201, 0, 0, 5927);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "強過ぎる力の扱いには\n注意しないと…\n七冠がいい例だね", 1, 121201, 0, 0, 5928);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "少年の交友関係は\n計り知れないな…\nアタシも含むのか！", 1, 121201, 0, 0, 5929);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "原理を徹底解明して\n再発を防ぐぞー！\n…誰か手伝って～！", 1, 121201, 0, 0, 5930);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "これは祝福にも\n呪いにもなる…\n忘れずにいよう", 1, 121201, 0, 0, 5931);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "少年が\n目を覚ましてくれて\n本当によかった…", 1, 121201, 0, 0, 5932);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "彼以外を選んでいたら\n今回の事態は\n乗り切れなかったな…\nさすがだよ、少年", 1, 121201, 0, 0, 5933);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "少年！　調子はどう？\nクレープ食べられる？\nっていうか食べて？", 1, 121201, 0, 0, 5934);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "元気そうで何よりだ\nまた店を手伝いに\nきてよ。二人もキミに\n会いたがってたしさ", 1, 121201, 0, 0, 5935);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "キミの診察もあるし\n今はなるべくそばに\nいるよ。迷惑じゃ\nなければだけど", 1, 121201, 0, 0, 5936);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "やっぱり少年は\nあちこちで人を\n助けてる時が\n一番輝いてるよ", 1, 121201, 0, 0, 5937);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "アタシは大したこと\nしてないけど\nみんなのことは\n褒めてあげてね", 1, 121201, 0, 0, 5938);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "みんなを笑顔に\nできるのは\nやっぱり少年だね", 1, 121201, 0, 0, 5939);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "やあ少年\n朝寝坊はしてない？\nそれじゃ、よい１日を", 1, 121201, 0, 1, 5940);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おや、少年！\nまかないのクレープ\n作ったけど、食べる？", 1, 121201, 0, 2, 5941);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふわぁ…もう夜か…\n研究してたら\nあっという間だね…\nおやすみ、少年", 1, 121201, 0, 3, 5942);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "体がなまってたのか\n前線に出ると疲れる…\nまさか…年のせい！？", 1, 121201, 0, 0, 5944);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "キミたちも今の\nアタシと同じ感じに\nアレンジしてあげよう", 1, 121201, 0, 0, 5945);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "誰が置いたんだろう？\nいい香りだねぇ…\nうん、気に入った♪", 1, 121201, 0, 0, 5946);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "何も考えてない時間も\n実は思考にとって\n大事なんだよね～…", 1, 121201, 0, 0, 5947);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食の大切さは\nいつの食事からも\n感じられるね♪", 1, 121201, 0, 0, 5949);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむ…面白い！\n今度全巻\n借りにこようっと", 1, 121201, 0, 0, 5950);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "聖学祭か…\n良い記憶はないな\nよし忘れよう", 1, 116401, 0, 0, 5952);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "健全なる精神は\n健全なる肉体に宿る…\nはっ、知ったことかよ", 1, 116401, 0, 0, 5953);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "暇だし鏡でも見るか…\nえへへ、ユニだよ♪\nよし子供料金いけるな", 1, 116401, 0, 0, 5954);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "アオイ君は元気に\nしているだろうか…\n彼女は人一倍ぼくに\n懐いていたからな…", 1, 116401, 0, 0, 5955);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "そろそろシズル君は\n姉という幻想から\n目覚めただろうか…", 1, 116401, 0, 0, 5956);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ぼくは来年も聖学祭に\n行くさ…卒業しても\n君らとは永遠だ", 1, 116401, 0, 0, 5957);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "最近同志の登校率が\n減少傾向だな…\nまあ仕方ないのだが…\nないのだが…", 1, 116401, 0, 0, 5958);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ほわあああ！\nおい急に話しかけるな\n学びがこぼれる", 1, 116401, 0, 0, 5959);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "この体操着、周囲から\n大層評判が良いのだよ\nたいそうだけにな\nどやっ！", 1, 116401, 0, 0, 5960);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "何を着ていようと\nぼくはぼくさ\n外見など所詮は\n魂の識別符に過ぎん", 1, 116401, 0, 0, 5961);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "救護院のアヤネ君が\n最近ぼくの自称年齢に\n疑念を持ち始めてな…\nあの熊…殺るか…", 1, 116401, 0, 0, 5962);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "うん？　なんだね？\nなに、用は無い？\n用も無いのに呼ぶとは\nもしや…これが友達！", 1, 116401, 0, 0, 5963);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "この服が似合ってる？\nな、なんだね突然…\nやめたまえよでゅふふ", 1, 116401, 0, 0, 5964);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふぁ～あ…\n朝も更けてきたな…\nそろそろ寝るか…", 1, 116401, 0, 1, 5965);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ふぁ～あ…もう昼だ…\n人間の起きている\n時間ではないな…\n早く寝なくては…", 1, 116401, 0, 2, 5966);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "うーん、よく寝た！\n気持ちのいい夜だな\n今日も一日がんばるぞ", 1, 116401, 0, 3, 5967);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ほわぁ～…\nもしやこれは都で噂の\n人を駄目にするやつ…", 1, 116401, 0, 0, 5969);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふむ、愛くるしいな\nだが似合い過ぎる…\nぼくが持つと我ながら\n子供にしか見えん", 1, 116401, 0, 0, 5970);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "アロマか、興味深いな\nミツキ印ポーションも\n気化させて鼻腔から\n吸入してみるか…", 1, 116401, 0, 0, 5971);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "んふ、んふふ…\n火ってイイよね…\nずっと見てられるね…", 1, 116401, 0, 0, 5972);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "や、やめろ…\nとめどなく固形食物を\n生産するのはやめろ…", 1, 116401, 0, 0, 5974);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "この可愛げのない筆致\nやはり作者は理系か！\nぐああ目が理系になる", 1, 116401, 0, 0, 5975);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "…あいつのためなら\n無理くらいいくらでも\nしてやるわよ", 1, 121101, 0, 0, 5977);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "この姿、\n魔力の制御ムズ過ぎ…\nま、あたしは優秀だし\nどうとでもなるけど！", 1, 121101, 0, 0, 5978);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "あいつのこと、\n全部受け入れるって\n決めたから！", 1, 121101, 0, 0, 5979);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "今なら誰だろうと\n負ける気がしないわ\nドラゴンでもなんでも\nかかってこいっての！", 1, 121101, 0, 0, 5980);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "散々助けられた分、\n今度はあたしが\nあいつのこと助けるわ", 1, 121101, 0, 0, 5981);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あいつとの\nこれまでの冒険は\nどれも、あたしの\n大切な思い出…", 1, 121101, 0, 0, 5982);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "もしまたあいつが\n寝たままになったら\nなんだってするわ\nキ…キスでも…", 1, 121101, 0, 0, 5983);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "なに、お腹空いたの？\nなら、おいしいご飯を\n食べに行きましょ♪", 1, 121101, 0, 0, 5984);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "やっぱ、\nあんたのアホ面見ると\n安心するわ♪", 1, 121101, 0, 0, 5985);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "【美食殿】はあんたと\nぺコリーヌがいなきゃ\n始まんないっての", 1, 121101, 0, 0, 5986);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ひゃあっ！？\n急に声かけないで！？\n魔力が暴発しても\n知らないわよ！", 1, 121101, 0, 0, 5987);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "…あんたとこうして\nぼーっと過ごす時間、\nまあ…嫌いじゃないわ", 1, 121101, 0, 0, 5988);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あんたが信じて\n見守っててくれれば…\nあたし、\nなんだってできるわ", 1, 121101, 0, 0, 5989);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよ\n早く顔洗いなさいよ、\nこのねぼすけ♪", 1, 121101, 0, 1, 5990);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今日のお昼は\nどこで食べる？\nあんたが\n決めていいわよ", 1, 121101, 0, 2, 5991);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もしあんたがまた\n夢に囚われても\nあたしが助けるわ\n安心して寝なさいよ", 1, 121101, 0, 3, 5992);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "気持ちいい～…♪\nあいつもたまには\nこうして休ませなきゃ", 1, 121101, 0, 0, 5994);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "一目惚れしたかも…！\nこの子、\n部屋に飾りたいわー♪", 1, 121101, 0, 0, 5995);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "へぇ、あいつって\nこういう匂いが\n好きなのかしら…？", 1, 121101, 0, 0, 5996);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "暖かくて最高…♪\n丸くなっちゃいそう…\nうにゃあ…♪", 1, 121101, 0, 0, 5997);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "イケるわね、これ！\nやっぱり食べるって\n大事よねー♪", 1, 121101, 0, 0, 5999);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ファーストキスは\nどんな味、ね…\nふ、ふ～ん…？\nなるほど…", 1, 121101, 0, 0, 6000);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "お友だち…\nできるかしら…？\nこんなわたしでも…", 1, 118101, 0, 0, 6002);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "あまり、きょろきょろ\nしちゃダメよね…\n変な子だと、\n思われてしまうわ…", 1, 118101, 0, 0, 6003);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "広い場所、\n落ち着かない…\nはぅ…どこにいれば…", 1, 118101, 0, 0, 6004);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "～♪", 1, 118101, 0, 0, 6005);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "【レイジ・レギオン】\n…またいつか、\nみんなと…", 1, 118101, 0, 0, 6006);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "…一度でいいから、\nわたしもママって…\nあっ、その…\n…な、なんでもないわ", 1, 118101, 0, 0, 6007);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ここが、今のわたしに\nとっての帰る場所…\n…そう思っても、\nいいのかしら…？", 1, 118101, 0, 0, 6008);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ええと…\nお腹、空いてる？\nおねむじゃない？", 1, 118101, 0, 0, 6009);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ここにいると\n邪魔かしら…？\nならもっと隅っこに…", 1, 118101, 0, 0, 6010);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お喋り…？\nわたしでいいの…？\nうれしい…", 1, 118101, 0, 0, 6011);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あなたの好きな歌…\n教えて…？\n練習、するから…", 1, 118101, 0, 0, 6012);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ここは賑やかだけど…\nうるさいとは感じない\nむしろ、心地いい…", 1, 118101, 0, 0, 6013);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "安心、して…\nわたしの歌で、\nあなたを守るから…", 1, 118101, 0, 0, 6014);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ちょっとだけ…\n朝は、苦手…\n…ふぁ…", 1, 118101, 0, 1, 6015);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼は、食べた？\n良かったら、一緒に…\n少し…焦げてるけど…", 1, 118101, 0, 2, 6016);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "眠れないのかしら…\nじゃ、じゃあ…\n子守歌…聴く？", 1, 118101, 0, 3, 6017);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "こんな特等席…\n恐縮、です…", 1, 118101, 0, 0, 6019);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "い、今のうちに、\nこの子でお世話の\n練習を…", 1, 118101, 0, 0, 6020);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り…\n…つらい気持ちも\n癒してくれる", 1, 118101, 0, 0, 6021);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかい…\nいつまでも、\nこうしていられそう…", 1, 118101, 0, 0, 6022);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいしく出来てる…\nすごいわ…\n見習わなくっちゃ…", 1, 118101, 0, 0, 6024);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "『赤ちゃんとママの\nスキンシップ入門』…\n…べ、勉強になるわ…", 1, 118101, 0, 0, 6025);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "きれいなお部屋…！\n立派な舞台の\nセットみたい…♪", 1, 121301, 0, 0, 6027);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "お芝居では私が先輩\nなんだから、しっかり\n私がミサキちゃんを\nエスコートしなきゃ", 1, 121301, 0, 0, 6028);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "～～♪\n歌うお芝居も多いから\nもっと上手く\nなりたいな…！", 1, 121301, 0, 0, 6029);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ここにいる人たちと\n仲良くなりたいな…\nそしたらきっと演技の\n幅も広げられるよね", 1, 121301, 0, 0, 6030);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "機会があったら\nアヤネちゃんとも\nお芝居してみたいな♪", 1, 121301, 0, 0, 6031);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お兄ちゃんに褒めて\nもらえるように\nお芝居の練習\nいっぱいしなきゃ…♪", 1, 121301, 0, 0, 6032);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あう…お兄ちゃんを\n意識したら、台詞が\n飛んじゃったよぅ…！", 1, 121301, 0, 0, 6033);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あっ、お兄ちゃん…♪\nお芝居の練習を\n見てくれませんか…？", 1, 121301, 0, 0, 6034);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "いまの発声練習\nどうでしたか？\nひゃん…！？\n頭は撫でないでぇ～", 1, 121301, 0, 0, 6035);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ミサキちゃんも\nお芝居、とっても\n上達してるんですよ\n私も負けられません♪", 1, 121301, 0, 0, 6036);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "また物語を聞かせて\nほしい、ですか…？\n私なんかでよければ\nもちろんよろこんで♪", 1, 121301, 0, 0, 6037);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "新しいお話を\n考えてみました\n聞いてくれますか…？\nよかった…♪", 1, 121301, 0, 0, 6038);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "いつか…舞台上じゃ\nなくても、照れずに\nお兄ちゃんに気持ちを\n伝えてみせますね…♪", 1, 121301, 0, 0, 6039);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます♪\nマヒルさんにもらった\nミルク、一緒に\n飲みませんか？", 1, 121301, 0, 1, 6040);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "牧場のみなさんに\nドングリパンを\nいただきました～\nおひとつどうぞ♪", 1, 121301, 0, 2, 6041);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "寝る前にまたココアを\n飲みながら、お話を\n聞いてもらえますか？\nえへへ、うれしいな♪", 1, 121301, 0, 3, 6042);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "お芝居の練習の\nあとは、ここで\nお兄ちゃんと\nゆっくりしたいな♪", 1, 121301, 0, 0, 6044);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "今日も演技の\n練習に付き合ってね♪", 1, 121301, 0, 0, 6045);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "素敵な香り…\nこのイメージも\nお芝居に\n活かせないかな…？", 1, 121301, 0, 0, 6046);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "私もお芝居で\nみんなの心を\nぽかぽか温められる\nようになりたいな…♪", 1, 121301, 0, 0, 6047);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "舞台に立つんだから\n食べ過ぎないように\n気をつけないと。\nでも…おいしいなぁ♪", 1, 121301, 0, 0, 6049);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "このお話、面白い…\n脚本を書く\n参考にもなりそう…♪", 1, 121301, 0, 0, 6050);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "えへへ…♪\n二人で見た夕日…\nキレイでしたね…", 1, 107501, 0, 0, 6052);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "これから泳ぎの\n練習ですか？\n付き合いますよ♪", 1, 107501, 0, 0, 6053);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "主さまを導くことで\nわたくしも未知なる\n領域へと辿り着けます", 1, 107601, 0, 0, 6054);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "主さまとなら\n海よりも深く\n空よりも高い場所へも\n目指せそうです", 1, 107601, 0, 0, 6055);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "あいつと二人で\n夏の遠い海に…って\nあたしってば\nなに考えてるのよ！", 1, 107801, 0, 0, 6056);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "あたしが楽しく\n過ごせるのはあんたが\nいてくれたからよ\nか、感謝してるわ", 1, 107801, 0, 0, 6057);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "はぁ…アタシってば\nこんなにかわいくって\nキレイなんて罪よね～", 1, 121401, 0, 0, 6058);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "舞台の衣装を\nクリーニング\nしとかなくちゃ…", 1, 121401, 0, 0, 6059);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "舞台映えするメイク…\nスズナなら\n知ってるかしら？", 1, 121401, 0, 0, 6060);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "物産展の会計係と\n山盛りの算数の宿題…\nどっちが簡単かしら…", 1, 121401, 0, 0, 6061);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "牧場と温泉の仕事に\nお芝居の練習に…\nちょ、ちょっと休憩～", 1, 121401, 0, 0, 6062);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お客さんの視線も\nうれしいけど…\nあいつも見てて\nくれてるかしら？", 1, 121401, 0, 0, 6063);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "もっともっと\nセクシーになって\nあいつをビックリ\nさせてやるわ♪", 1, 121401, 0, 0, 6064);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "アンタも休憩？\nしっかり働くために\n休むのも大事よね", 1, 121401, 0, 0, 6065);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ふふん♪　アタシも\n料理ができるように\nなったんだから！\n簡単なのだけだけど…", 1, 121401, 0, 0, 6066);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "温泉ってお肌に\nいいのよね？\nもっとキレイに\nなったらどうしよう〜", 1, 121401, 0, 0, 6067);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "物産展の荷物は\nこれでよし…っと\nそれじゃアンタも\n運ぶの手伝ってよね♪", 1, 121401, 0, 0, 6068);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "いつもと違うアタシに\n見とれちゃった？\n仕方ないわね～♪", 1, 121401, 0, 0, 6069);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お花見って風流で\n大人って感じ♪\n…でもお団子も\n忘れないでよね！", 1, 121401, 0, 0, 6070);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "みんなに朝ごはんを\n作ってみたら\n喜んでくれるかしら？", 1, 121401, 0, 1, 6071);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お客さんがいっぱい\n来る時間帯ね！\n元気出していくわ！", 1, 121401, 0, 2, 6072);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ寝ないと…\n睡眠不足はお肌の\n大敵なんだから", 1, 121401, 0, 3, 6073);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふかふかしてて\n気持ちいい～♪\n疲れが癒されるぅ…", 1, 121401, 0, 0, 6075);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "この子もアタシと\nおそろいの衣装に\nしてあげようかしら♪", 1, 121401, 0, 0, 6076);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "素敵な衣装で\nいい香りを\n身にまとう…ふふ、\n大人のたしなみよね♪", 1, 121401, 0, 0, 6077);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったか～い♪\nここでお昼寝したら\n気持ちよさそう…", 1, 121401, 0, 0, 6078);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "お仕事がんばると\nいつもよりお腹\n空いちゃう～！", 1, 121401, 0, 0, 6080);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "最新のトレンド\n載ってないかしら？\n物産展の売り物に\n取り入れなくちゃ！", 1, 121401, 0, 0, 6081);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "怪盗のこと…\nお父さんお母さんに\nもし知られたら\nなんて説明しよう…", 1, 121501, 0, 0, 6083);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "たとえ怪盗でも、人の\n家にお邪魔するときは\n身だしなみをしっかり\nしないと…", 1, 121501, 0, 0, 6084);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "鍵開けって難しい…\nうーん、もっと\n練習しておかなくちゃ", 1, 121501, 0, 0, 6085);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "姿が見えない\n怪盗の噂…？\nわ、私のことじゃ\nありませんように…！", 1, 121501, 0, 0, 6086);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "予告状って…\n切手はどこに貼れば\nいいんだろう…？", 1, 121501, 0, 0, 6087);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "怪盗活動にも\n慣れてきたけど…\nやっぱり先輩が\nいないと心細いなぁ…", 1, 121501, 0, 0, 6088);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "せ、先輩の心も\nいつか盗めるかな…？\n…わわわ、私ってば\nなに言ってるんだろ…", 1, 121501, 0, 0, 6089);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "怪盗が大活躍って\n新聞で読んだ…？\nだっ、誰のこと\nでしょうね…あはは", 1, 121501, 0, 0, 6090);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "尾行に潜入…\n存在感がないのって\n意外と役立つことも\nあるんですね", 1, 121501, 0, 0, 6091);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "せせせ、先輩っ！\n帽子をぎゅーって\nかぶったら、抜けなく\nなっちゃいました…！", 1, 121501, 0, 0, 6092);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ぬ、盗み聞きなんて\nしてませんよ？\nみんなが私に気づかず\n話し始めるだけで…", 1, 121501, 0, 0, 6093);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "秘密道具が見たい？\nそ、それは内緒です！\n秘密道具ですから…\nで、でも先輩になら…", 1, 121501, 0, 0, 6094);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "えへへ\n見つかっちゃいました\n先輩はいつも私を\n見つけてくれますね…", 1, 121501, 0, 0, 6095);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございまふ…\n秘密道具のお手入れで\n夜更かししちゃって…\nちょっと眠たいです～", 1, 121501, 0, 1, 6096);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "怪盗が昼に活動する…\n案外そのほうが\n意外性が\nあるのかも…？", 1, 121501, 0, 2, 6097);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "外が暗くなりましたね\n…そろそろ怪盗の活動\n始めましょうか？", 1, 121501, 0, 3, 6098);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ここでくつろぐと\n疲れが取れます～\n…今日も怪盗\nがんばろっと", 1, 121501, 0, 0, 6100);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "わぁ、かわいい…！\n心を盗まれるって\nこういうことかな…？", 1, 121501, 0, 0, 6101);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "素敵な香り…でも\n服に香りがついたら\n隠れてるときに\n見つかっちゃうかな…", 1, 121501, 0, 0, 6102);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ぽかぽかで\nいい気持ち…\n夜道を歩く前に\n温まっておこうっと…", 1, 121501, 0, 0, 6103);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "怪盗活動に備えて\n今のうちにしっかり\n食べておかなきゃ…！", 1, 121501, 0, 0, 6105);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "女の子は秘密が\n多いほうが魅力的…？\nそ、そうなんだ…", 1, 121501, 0, 0, 6106);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "ドＳさんはいつも\nクウカの妄想の中に…\nぐふふ、じゅるり～♪", 1, 104501, 0, 0, 6108);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "やさしい触り方も\n嫌いじゃありません…\nは…恥ずかしいですが", 1, 104501, 0, 0, 6109);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この大怪盗さまに\n盗めないものなんて\nないです！　たぶん！", 1, 121601, 0, 0, 6110);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "あたしにふさわしい\nビッグなお宝は\nどこにあるですかね～", 1, 121601, 0, 0, 6111);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "そろーりそろーり…\n気配を消せばお菓子も\n食べ放題…にやり", 1, 121601, 0, 0, 6112);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "またサボってたのが\nバレたです…\nボスの地獄耳～！", 1, 121601, 0, 0, 6113);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ギャングで大怪盗…！\nこの肩書の多さ！\nまさに有能の証です！", 1, 121601, 0, 0, 6114);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お兄さんだったら…\nお宝を山分けして\nあげてもいいですよ", 1, 121601, 0, 0, 6115);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "お兄さんはアレですよ\n大怪盗イノリさまの\n相棒みたいなものです", 1, 121601, 0, 0, 6116);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "何事も用心深さが\n大切ですよ。ビ…\nビビりじゃないです！", 1, 121601, 0, 0, 6117);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ぬ、盗み聞き？\nしてないですよっ？\nぴゅーぴゅーぴゅー", 1, 121601, 0, 0, 6118);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "情報が欲しければ\nお菓子と交換ですよ\nさぁ、交換交換っ♪", 1, 121601, 0, 0, 6119);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "しーっ！\n今、尾行中なんです\n話はあとで…", 1, 121601, 0, 0, 6120);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お兄さんと話してると\n時間が速いような…？\nこの時間泥棒！", 1, 121601, 0, 0, 6121);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ちょうどよかった！\nいい話があるんです\n一口乗りませんか？", 1, 121601, 0, 0, 6122);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おてんとうさまが\n出てやがるですね…\n悪事がやりにくいです", 1, 121601, 0, 1, 6123);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "もうこんな時間ですか\nご飯にお昼寝…\nいやー忙しいです♪", 1, 121601, 0, 2, 6124);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふっふっふ！　夜こそ\n大怪盗の時間です！\n……ふぁあ", 1, 121601, 0, 3, 6125);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "うーん…\n警備の目がないと\n気楽でいいですねぇ", 1, 121601, 0, 0, 6127);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "くう…！\nこのかわいさは\n盗めないです…♪", 1, 121601, 0, 0, 6128);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "犯行現場に残ったのは\n香水の匂いだけ…\nふふ、おしゃれ大怪盗", 1, 121601, 0, 0, 6129);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "意外とこういう場所に\n隠し扉があったり…\nしないです？", 1, 121601, 0, 0, 6130);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…\nこの美味しさ…\nとんでもない罠ですね", 1, 121601, 0, 0, 6132);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "むむむ…ちっとも\n分からないです…\nほとんど暗号ですよ", 1, 121601, 0, 0, 6133);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "あら、サレンさんは\nどこに行かれた\nのかしら？", 1, 121701, 0, 0, 6135);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ふんふんふーん♪\nなんだか華やいだ\n気分ですわ♪", 1, 121701, 0, 0, 6136);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "さて…次の事業は\nどうしましょう\n何か面白いことは…", 1, 121701, 0, 0, 6137);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "おーっほっほっほ！\nあら…楽しくて、つい\n笑ってしまいましたわ", 1, 121701, 0, 0, 6138);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "センスがあって\nいいお部屋ですわね\n私も見習いたいですわ", 1, 121701, 0, 0, 6139);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "サレンさんとあのお方\n仲がいいですわね\nも、もちろん仲がいい\nのはよいことですわ！", 1, 121701, 0, 0, 6140);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "どんなときでも\n正々堂々！\nそれが私の\n誇りですわ！", 1, 121701, 0, 0, 6141);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふふ、ごきげんよう\n私、絶好調でしてよ", 1, 121701, 0, 0, 6142);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "どうかされましたか？\n何かお困りごと\nでしたら\n是非力になりますわよ", 1, 121701, 0, 0, 6143);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "たまにはこうして\nゆっくりと\nお話しするのも\nいいものですわね", 1, 121701, 0, 0, 6144);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "次の事業に関して\n考え事をしてましたの\nよければ相談に乗って\nくださるかしら？", 1, 121701, 0, 0, 6145);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "よろしければ\nお話しませんこと？\nサレンさんのお話を\n聞かせてほしいですわ", 1, 121701, 0, 0, 6146);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ふふっ…\n先ほどサレンさんと\nあなたさまのお話を\nしていたところですわ", 1, 121701, 0, 0, 6147);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "さあ！\n今日も一日\n全力で参りますわ！", 1, 121701, 0, 1, 6148);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼はどうしましょう\nサレンさんをお誘い\nしてみようかしら", 1, 121701, 0, 2, 6149);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もう少しだけ…\n明日の準備をして\nおかないと…", 1, 121701, 0, 3, 6150);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "はぁ～…いいですわね\nはっ、私としたことが\nはしたないですわね", 1, 121701, 0, 0, 6152);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいらしいですわ\nいくつになっても\nぎゅっと\nしたくなりますわね", 1, 121701, 0, 0, 6153);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "落ち着きますわね\nサレンさんはどんな\n香りが好きなのかしら", 1, 121701, 0, 0, 6154);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ふふっ、燃え盛る\n情熱の炎…\nいいですわね", 1, 121701, 0, 0, 6155);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "このおいしさで\n元手がゼロ…\nすばらしい\n商品ですわ！", 1, 121701, 0, 0, 6157);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "これは…ふむふむ\n新しい事業のヒントに\nなりそうですわ", 1, 121701, 0, 0, 6158);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "さて、と…\n今日は何をしなくちゃ\nいけないんだっけ？", 1, 121801, 0, 0, 6161);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "やることは山積み\nだけど、手を動かす\nのは嫌いじゃないわ♪", 1, 121801, 0, 0, 6162);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "あら？　アキノさんの\n声が聞こえたような\n気がしたんだけど…", 1, 121801, 0, 0, 6163);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "アキノさんといると\nついこっちまで笑顔に\nなっちゃうのよね", 1, 121801, 0, 0, 6164);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "弱音なんか\nはいてられないわ\nアキノさんに\n笑われちゃうもの", 1, 121801, 0, 0, 6165);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "気が付けばアキノさん\nのペースだけど…\n不思議と嫌では\nないのよね", 1, 121801, 0, 0, 6166);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あたしを好敵手って\n言ってくれる\nアキノさんのためにも\nしっかりしなくちゃ", 1, 121801, 0, 0, 6167);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "どうしたの？\nアキノさんなら\nさっきそこに\nいなかった？", 1, 121801, 0, 0, 6168);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あたしなら大丈夫\n救護院だって\nみんなが助けて\nくれるからね", 1, 121801, 0, 0, 6169);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "さっきアキノさんが\nあんたを探してたわよ\nなにかしたの？", 1, 121801, 0, 0, 6170);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "こう見えてヒマじゃ\nないんだけど…\n少しくらいなら\n付き合ってあげるわ", 1, 121801, 0, 0, 6171);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ねえ、あんたと\nアキノさんって…\nううん、やっぱり\nなんでもないわ…", 1, 121801, 0, 0, 6172);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "アキノさんも誘って\nお茶でもしない？\n話したいことが\nたくさんあるの♪", 1, 121801, 0, 0, 6173);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "早起きは三文の得よ\nいい一日を迎えるため\n目を覚まさなきゃ", 1, 121801, 0, 1, 6174);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今日のお昼は…\nアキノさんと同席する\n予定だったわね\nあんたもどう？", 1, 121801, 0, 2, 6175);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふぁ…っと、だめね\nたるんだところを\nアキノさんに\n見せるわけには", 1, 121801, 0, 3, 6176);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ん～…\n落ち着くわね\nこのまま\n寝ちゃいそう…", 1, 121801, 0, 0, 6178);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "救護院の皆も\nぬいぐるみが\n大好きなのよ", 1, 121801, 0, 0, 6179);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りね…\nこれはアキノさんの\n趣味かしら？", 1, 121801, 0, 0, 6180);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "こんなに激しく\n燃えているのに\nあったかくて落ち着く\nまるでアキノさんね", 1, 121801, 0, 0, 6181);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "どんどん出てくる…\nこれ、救護院にも\nほしいわね…", 1, 121801, 0, 0, 6183);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ…\n前にアキノさんが\n言ってたのは\nこのことかしら？", 1, 121801, 0, 0, 6184);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この衣装、私には\nちょっとかわい過ぎて\n恥ずかしいな…", 1, 122001, 0, 0, 6187);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "一部の人からは\n海賊より海賊らしいと\n評判の父です", 1, 122001, 0, 0, 6188);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "潮風で錆びないよう\n武器の手入れを\nしておきましょうか", 1, 122001, 0, 0, 6189);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "宝探しのお手伝いなら\n力になれると思います\n父のやる気次第ですが", 1, 122001, 0, 0, 6190);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "除霊は気を遣います\n一歩間違えると父まで\n成仏させてしまうので", 1, 122001, 0, 0, 6191);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あの人と見た\n海の景色を…ずっと\n忘れずにいたいな", 1, 122001, 0, 0, 6192);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "幽霊になっても\n一目会えるなら…\n私はきっとあの人に…", 1, 122001, 0, 0, 6193);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ボートを漕ぐの、少し\n上手になったんですよ\n今度お見せしますね", 1, 122001, 0, 0, 6194);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "航海に向けた\n買い出しが必要ですね\n予定は空いていますか", 1, 122001, 0, 0, 6195);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "呪われた財宝の\n解呪依頼が多くて…\nふぅ…えっと次は…", 1, 122001, 0, 0, 6196);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "夜の航海では\n父が明かり代わりに\nなってくれるんです", 1, 122001, 0, 0, 6197);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "船の上では食材が\n限られるので料理の\nいい練習になります", 1, 122001, 0, 0, 6198);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "この先もずっと\nあなたと一緒に\nたくさんの思い出を\n作っていきたいです", 1, 122001, 0, 0, 6199);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あの人の寝顔…\nもう少しだけ\n眺めていたいな…", 1, 122001, 0, 1, 6200);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "船の上では\n規則正しい生活が\n重要ですから", 1, 122001, 0, 2, 6201);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜の海は幽霊が\n見分けやすいんです\n青白く光るので", 1, 122001, 0, 3, 6202);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "海に揺られるような\n心地よさですね\n気が休まります…", 1, 122001, 0, 0, 6204);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "あなたも一緒に\n海を見に行きますか？\n…なんて。ふふっ", 1, 122001, 0, 0, 6205);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "爽やかな香りですね…\n一面の青い海が\n目に浮かぶようです", 1, 122001, 0, 0, 6206);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "温かい…\n潮風で冷えた体に\n沁みますね", 1, 122001, 0, 0, 6207);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "あ、おいしい…\n日持ちするなら船旅に\n持っていこうかな…", 1, 122001, 0, 0, 6209);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "アンナさんに教えて\nもらった小説は…\nあ、これですね", 1, 122001, 0, 0, 6210);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "なにもしないを\nしてるんだよ\nあ～いそがしいそがし", 1, 102601, 0, 0, 6212);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "はぁ～あんたといると\nどこまでも気持ちよく\nダラダラできるね～", 1, 102601, 0, 0, 6213);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "暗黒騎士にして、\n伝説の海賊でもある\n私に不可能はないっ！", 1, 121901, 0, 0, 6214);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "海賊団の船員、\n随時募集中です…と\nこれで新たな盟友が\n増えるはずだ…！", 1, 121901, 0, 0, 6215);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "肩に乗せるペットが\nほしいな。今のうちに\nペット用品を買いに\n行かなくては…！", 1, 121901, 0, 0, 6216);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "財宝の地図はどこで\n売っているのだろう…\n古本屋？　古物商？", 1, 121901, 0, 0, 6217);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "この海賊衣装に\n身を包んでいると\n前世の新たな記憶が\nよみがえってくるな！", 1, 121901, 0, 0, 6218);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "いずれはシグルドと\n海原への冒険に\n繰り出したいな…\nきっと楽しいぞ！", 1, 121901, 0, 0, 6219);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "待ちわびたぞ盟友よ！\n私と貴様あっての\n海賊団…だからその…\n今日はそばにいてくれ", 1, 121901, 0, 0, 6220);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "シグルド！　港町で\nお魚のおすそ分けを\nもらったんだ！\n一緒に食べよう！", 1, 121901, 0, 0, 6221);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "シグルドもこのコート\n羽織ってみないか？\nふふっ、きっとすごく\n似合うと思うぞ！", 1, 121901, 0, 0, 6222);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "海賊船の新たな\n秘密兵器を作ったぞ！\nシグルド、これから\n見に来ないか！？", 1, 121901, 0, 0, 6223);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "私は伝説の海賊だから\n泳ぐのだって得意だ！\nふ、深いところは\n少し怖いが…", 1, 121901, 0, 0, 6224);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ふふ、いつ無人島に\n漂着してもいいように\n非常食は準備済みだ\nシグルドの分もある！", 1, 121901, 0, 0, 6225);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "冥風戦記の新章が\n完成したぞ…！\nシグルド、まずは\n貴様に読んでほしい！", 1, 121901, 0, 0, 6226);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふっ、天気明朗\n絶好の航海日和だ！\n早速海に繰り出そう！", 1, 121901, 0, 1, 6227);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼食用に魚を\n釣っておいたぞ！\nふふ、いかにも\n海賊っぽいだろう？", 1, 121901, 0, 2, 6228);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜の海は真っ黒で\n少しだけ怖いな…\nシグルド、私の\nそばを離れるなよ…！", 1, 121901, 0, 3, 6229);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "大海賊がくつろぐのに\n相応しい逸品だ…！\nえっと…これ、どこの\nお店で買えますか？", 1, 121901, 0, 0, 6231);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "わわ、かわいい…！\n船室のベッドに\n置いておきたいな…\n連れてってはダメか？", 1, 121901, 0, 0, 6232);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "おぉ、この香りは…！\n集中力が上がりそうだ\n海賊船の船長室に\nぜひ置きたいな！", 1, 121901, 0, 0, 6233);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "これが船乗りの\n伝承に聞く、海原を\nさまよう神秘の火か！\n…暖まるな！", 1, 121901, 0, 0, 6234);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "腹が減っては\n海賊はできぬ！\n…小説も書けぬ！", 1, 121901, 0, 0, 6236);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "女海賊と騎士はその後\n恋に落ち…？　恋愛\nモノではないかっ！？\nき、興味深くはあるが", 1, 121901, 0, 0, 6237);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "いつもの山籠もりが\nブームになるなんて…\n人生、なにが起きるか\n分からないなぁ", 1, 122101, 0, 0, 6239);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "キャンプ道具…\nいえ、キャンプギア！\nカッコいい響き…♪", 1, 122101, 0, 0, 6240);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "レッツ、ＢＢキャン！\nこのフレーズ\n流行るかも…？", 1, 122101, 0, 0, 6241);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "キャンプ仲間…\n募集してみようかな？\n友達も兼任で…", 1, 122101, 0, 0, 6242);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ユカリさんと\nジュンさん…元気かな\nまた一緒に\nキャンプしたいなぁ…", 1, 122101, 0, 0, 6243);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "私の取材が載った本…\n【フォレスティエ】に\n送らなくちゃ…♪", 1, 122101, 0, 0, 6244);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "もし、あの人が\n落ち込むことが\nあったら…その時は\n私が力になりたいな", 1, 122101, 0, 0, 6245);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ブッシュクラフトは\nマイフレンドくんの\nカスタムにも\n活かせる技術です！", 1, 122101, 0, 0, 6246);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "会話に花が咲く…\nって言いますよね\n私の場合、会話相手が\nお花そのものですけど", 1, 122101, 0, 0, 6247);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "この服、実は…\n昔ミサト先生に\nこしらえてもらった\n物なんです！", 1, 122101, 0, 0, 6248);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "昔はやまびこで会話の\n練習をしてたんです\nほとんどオウム返しで\n気まずかったなぁ～", 1, 122101, 0, 0, 6249);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "どうもマイスターです\n…あ、すみません\nみなさんの期待に\n応えようと練習中で…", 1, 122101, 0, 0, 6250);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "たとえぼっちを\n卒業しても…\n私は一生ＢＢ団です！", 1, 122101, 0, 0, 6251);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "小鳥さんのさえずりで\n目が覚める…\n心地いいものですね", 1, 122101, 0, 1, 6252);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "キャンプといえば\nおいしいご飯です！\n腕を振るいますよ！", 1, 122101, 0, 2, 6253);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "すっかり夜ですね…\nおやすみの前に\n星でも見ませんか？", 1, 122101, 0, 3, 6254);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "都会でくつろぎ…\n自然の中でくつろぐ…\nくつろぎ無限ループ…", 1, 122101, 0, 0, 6256);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "しっかり観察すれば\nブッシュクラフトで\n再現できるかも…？", 1, 122101, 0, 0, 6257);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "はぁ～…やっぱり\n木の香りを嗅ぐと\n肩の力が抜けますねぇ", 1, 122101, 0, 0, 6258);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ああ…あったまります\nなんだか心に\nゆとりがでますね…", 1, 122101, 0, 0, 6259);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "このおいしさ…！\n今度はキャンプに\n持っていこうかな…", 1, 122101, 0, 0, 6261);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ…\nいろんな知識があると\nキャンプはもっと\n楽しくなりますよね", 1, 122101, 0, 0, 6262);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "部屋がキャンプ用品で\n埋まっていく…\nキャンプ…なんて\n恐ろしい趣味なの…？", 1, 122201, 0, 0, 6264);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "仕事でも\nアウトドアでも\n頼れるお姉さんに\nなれたらいいなぁ…", 1, 122201, 0, 0, 6265);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "この服、かわいい上に\n本当に快適ね～♪\nおしゃれにキャンプを\n楽しめて最高だわ！", 1, 122201, 0, 0, 6266);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ん〜次はどんな\nキャンプ飯を\n作ろうかしら？\n彼の好物は、っと…", 1, 122201, 0, 0, 6267);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "早く週末が\n来ないかしら…\n仕事を忘れてパーっと\nキャンプ飲みを…！", 1, 122201, 0, 0, 6268);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "新しいキャンプ飯の\nレシピを覚えたわ！\n彼も喜んで\nくれるはず…よね♪", 1, 122201, 0, 0, 6269);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "彼の分の食器も\nこっそり買い揃えちゃ\nおうかな…そ、それは\nさすがにまだ早いか…", 1, 122201, 0, 0, 6270);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今度、財団主催で\n大規模なキャンプを\nやってみるのも\nいいかもしれないわね", 1, 122201, 0, 0, 6271);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ソロキャンプも\n悪くはないけど\n私はやっぱりキミと…\nな、なんでもない！", 1, 122201, 0, 0, 6272);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "キャンプのことなら\n私に聞いて。なんでも\n教えてあげるから！\n…調べた上でね！", 1, 122201, 0, 0, 6273);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "キャンプ場で飲む\n最高の一杯は\n他じゃ味わえないわ！\nさあ、乾杯っ！", 1, 122201, 0, 0, 6274);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "うん、決めた！　次は\n禁しゅわキャンプ！\nだってキミとゆっくり\n話したいんだもん♪", 1, 122201, 0, 0, 6275);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "キミのおかげで\n本当の最高の一杯が\n味わえたわ…\nありがとう♪", 1, 122201, 0, 0, 6276);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "んー、気持ちいい！\nキャンプが趣味に\nなってから、寝覚めが\nよくなったわ♪", 1, 122201, 0, 1, 6277);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼は私がごちそう\nするわ。キャンプ飯で\n鍛えた料理の腕前を\n披露しちゃうわよ～！", 1, 122201, 0, 2, 6278);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ寝ましょ？\n明日も朝日を眺める\nためにね。もちろん\nコーヒー付きで♪", 1, 122201, 0, 3, 6279);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "くつろぐのに\n持ってこいね～\nテントの中に置いても\nよさそうだわ！", 1, 122201, 0, 0, 6281);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふふ、かわいいわね～\n…今度キャンプ場に\n連れていこうかしら？", 1, 122201, 0, 0, 6282);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "うん、いい匂い…♪\nキャンプ場を思い出す\n自然の香りだわ〜", 1, 122201, 0, 0, 6283);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "はぁ、温まるぅ～\n冬のキャンプで\n使ってみたいわね", 1, 122201, 0, 0, 6284);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいしい～♪\nキャンプ飲みの\nおつまみに\nぴったりね！", 1, 122201, 0, 0, 6286);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "へえ…こんなキャンプ\n飯もあるんだ？\n彼、好きだったり\nするかな…", 1, 122201, 0, 0, 6287);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "一生ついててやるの\n幽霊の一生は\nなっが～～～いの！", 1, 100701, 0, 0, 6289);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "む～…あんまり触ると\nすり抜けてやるの！\nウソなの。むふふ♪", 1, 100701, 0, 0, 6290);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "んー…\n今日はベスちゃんと\nなにして遊ぼーかなー", 1, 122301, 0, 0, 6291);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ヴァンピィちゃんも\nけんぞくの友だちと\n仲良くなりたいな♪", 1, 122301, 0, 0, 6292);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "けんぞくのお部屋は\nヴァンピィちゃんが\n守ってあげなくちゃ！", 1, 122301, 0, 0, 6293);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お掃除するなら\nヴァンピィちゃんも\n手伝ってあげよー♪", 1, 122301, 0, 0, 6294);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ふーん、ふーん♪\nけんぞくってこーゆー\nお部屋が好きなんだー", 1, 122301, 0, 0, 6295);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ひまだなー\nけんぞくをさそって\nお散歩いこっかな♪", 1, 122301, 0, 0, 6296);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "今日のスープに\nけんぞくの大好物を\n入れてあげよっと♪", 1, 122301, 0, 0, 6297);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "けんぞくー！\nヴァンピィちゃんと\nお出かけしよ♪", 1, 122301, 0, 0, 6298);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "よしよし！\n今日のけんぞくも\nいい子だね♪", 1, 122301, 0, 0, 6299);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "んんー…\nやっぱりけんぞくと\nベスちゃんは似てる？", 1, 122301, 0, 0, 6300);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "いーい？\nヴァンピィちゃんの\nいうこと聞くのよ？", 1, 122301, 0, 0, 6301);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ヴァンピィちゃんの\nけんぞくだもん！\n大切にするからね！", 1, 122301, 0, 0, 6302);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "えへへっ！\nやっぱりけんぞくって\nやさしー匂いがする♪", 1, 122301, 0, 0, 6303);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよー…\nヴァンピィちゃんは\nもうちょっと眠るねー", 1, 122301, 0, 1, 6304);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ヴァンピィちゃん\nひなたぼっこ\nだーいすき！", 1, 122301, 0, 2, 6305);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "んー！　夜だ♪\nヴァンピィちゃん\n絶好調だよ！", 1, 122301, 0, 3, 6306);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "わー！\nふかふかだ！\nきもちぃー♪", 1, 122301, 0, 0, 6308);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいー♪\nベスちゃんに負けない\n抱き心地！", 1, 122301, 0, 0, 6309);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この香り…なんだろ？\nヴァンピィちゃん\n気に入っちゃった♪", 1, 122301, 0, 0, 6310);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかいねー…\nヴァンピィちゃん\nずっとここにいるー…", 1, 122301, 0, 0, 6311);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "はむはむ…\nんー！\nおいしー♪", 1, 122301, 0, 0, 6313);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ヴァンピィちゃん\nこの本\n好きなんだよねー♪", 1, 122301, 0, 0, 6314);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "夏といえば\nかき氷だよね\n近くにお店は…", 1, 122501, 0, 0, 6316);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "この格好でいるのも\nなじんできたし\nちょっと鍛錬でも…", 1, 122501, 0, 0, 6317);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "動きやすいけれど…\nいつもと違う服装は\n少し落ち着かないな", 1, 122501, 0, 0, 6318);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "夏の空気に\n当てられると思わず\n気が緩んでしまうね", 1, 122501, 0, 0, 6319);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "砂浜で走ると\nいい具合に体幹を\n鍛えられそうだ", 1, 122501, 0, 0, 6320);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "終わらない夏は\nないけれど…\nつい願ってしまうな", 1, 122501, 0, 0, 6321);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "胸を張って彼と\n並び立てるよう\n私も、もっと強く…！", 1, 122501, 0, 0, 6322);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "どうしたの？\n行きたい場所が\nあるなら付き合おうか", 1, 122501, 0, 0, 6323);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "快晴で風は穏やか…\n絶好の釣り日和だね\nさあ、出かけようか", 1, 122501, 0, 0, 6324);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日の予定を\n立ててるんだけど…\nキミの希望も\n聞きたいな", 1, 122501, 0, 0, 6325);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ビーチスポーツか…\nキミとなら\nいい勝負ができそうだ", 1, 122501, 0, 0, 6326);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "私たちの夏に\n遠慮は無用だよ\n思いきり楽しもう！", 1, 122501, 0, 0, 6327);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "いつかまた一緒に\n花火を見に行こう\n…約束だよ？", 1, 122501, 0, 0, 6328);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "潮騒の音で\n目覚めるのも\nいいものだね", 1, 122501, 0, 1, 6329);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今朝釣ってきた魚が\nあるんだ。これで\nお昼ご飯にしようか", 1, 122501, 0, 2, 6330);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜にもイベントが\nあるみたいなんだ\n一緒に見に行かない？", 1, 122501, 0, 3, 6331);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "気持ちが安らぐね…\nうっかり眠って…\nしまい…そうだ…", 1, 122501, 0, 0, 6333);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "肌触りのよさが\nこの格好だと\nよく分かるよ", 1, 122501, 0, 0, 6334);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "海をイメージさせる\n香りだね…\n爽やかで落ち着くよ", 1, 122501, 0, 0, 6335);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "濡れたままだと\n風邪を引いてしまうよ\nほら、キミもおいで", 1, 122501, 0, 0, 6336);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "夏を楽しみきるには\nエネルギーが\n必要だからね", 1, 122501, 0, 0, 6338);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "大切な人と過ごせる\n観光スポット紹介…\n…こ、このページは\nもういいかな！", 1, 122501, 0, 0, 6339);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "濡らしてもいいなら\n海に持っていって\n乗るのもよさそうだ", 1, 122501, 0, 0, 6341);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "こういう名画を\n見た気がするな…\nこんな視点なんだね", 1, 122501, 0, 0, 6342);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "水着って\n動きやすくて\nいいよねー♪\nいっちにーさんしー♪", 1, 122401, 0, 0, 6343);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ユイちゃんにもらった\n日焼け止め\n塗っておいて\nよかった～", 1, 122401, 0, 0, 6344);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "なんだか暑いなあ…\nせっかくだし\nプールで泳いで\nこようかな？", 1, 122401, 0, 0, 6345);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "この格好で\n出かけようとしたら\nレイさんに\n怒られちゃった…", 1, 122401, 0, 0, 6346);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "たとえ水着姿でも\n困ってる人を見たら\n助けに行くからね！", 1, 122401, 0, 0, 6347);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "バカンス楽しかった～\nまた騎士くんと\n一緒に行きたいな♪", 1, 122401, 0, 0, 6348);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "この水着、あたしに\n似合ってるかなあ？\n騎士くんはどう\n思ってるんだろ…", 1, 122401, 0, 0, 6349);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "騎士くん！\n海に行くなら\n準備運動\n忘れずにね！", 1, 122401, 0, 0, 6350);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "泳ぐ練習がしたいの？\nいいよ！　水着だから\nなにかあったらすぐに\n助けてあげるね！", 1, 122401, 0, 0, 6351);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "騎士くんの水着姿も\nかっこよかったよ！\nまた遊びに行こ！\n約束ね！", 1, 122401, 0, 0, 6352);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "このグローブの向日葵\nかわいいでしょ？\nユイちゃんが\n選んでくれたんだ♪", 1, 122401, 0, 0, 6353);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "実はこの水着\nいつも着てる\n服とおなじなんだ…\nって、冗談だよ？", 1, 122401, 0, 0, 6354);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "変な日焼けしてないか\n見てもらってもいい？\n…なし！　今のなし！\nやっぱりなしー！", 1, 122401, 0, 0, 6355);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "夏のお日様に\n負けないよう\n今日も元気いっぱい\nがんばるぞー！", 1, 122401, 0, 1, 6356);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹減ってきちゃった\n騎士くんはお腹\n空いてない？\n…聞こえちゃった♪", 1, 122401, 0, 2, 6357);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日も一日\n楽しかったー！\n明日もまた\n楽しもうね！", 1, 122401, 0, 3, 6358);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふわあ…\nふわふわなのが\nいつもより\nよくわかるよー…", 1, 122401, 0, 0, 6360);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "そうだ！　水着なら\n濡れてもいいし\n今度洗ってあげるね♪", 1, 122401, 0, 0, 6361);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "んー…いい匂い♪\nなんだか\n身体がぽかぽか\nしてきちゃった！", 1, 122401, 0, 0, 6362);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "水着だから、えっと…\n暖か涼しい…！\n不思議な感じー", 1, 122401, 0, 0, 6363);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "思いっきり身体を\n動かした後だから\nいくらでも\n食べちゃえるよー！", 1, 122401, 0, 0, 6365);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ…\nなるほどー\n水着の種類って\nそんなにあるんだぁ…", 1, 122401, 0, 0, 6366);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "乗り心地バッチリだね\nしゅっぱつしんこー！\nなんちゃって♪", 1, 122401, 0, 0, 6368);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "わっ、ぽよんぽよん！\nトランポリンみたいで\nた～のし～！", 1, 122401, 0, 0, 6369);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "彼のことを考えてると\n幸せで胸が温かくなる\n…私ったら、もう", 1, 101501, 0, 0, 6370);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "うふふふふ\nくすぐったいわ～♪\nもう、イタズラっ子ね\n次は先生の番よ～♪", 1, 101501, 0, 0, 6371);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "騎士クンの汗\n拭いてあげたいな…\n余計なお世話かな…？", 1, 122601, 0, 0, 6372);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "夏バテ気味かも…\nそうだ、今夜は\nかば焼きにしよう♪", 1, 122601, 0, 0, 6373);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "青い空、白い雲\n眩しい日差し…！\n夏って好きだな…", 1, 122601, 0, 0, 6374);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ヒリヒリする…？\n日に焼けちゃったかな\nふー…ふー…", 1, 122601, 0, 0, 6375);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "花火大会があるんだ…\n夜、浜辺…2人きり…\nむ、無理だよ〜！", 1, 122601, 0, 0, 6376);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "水着って不思議…\n引っ込み思案が少し\nおさまる…気がする", 1, 122601, 0, 0, 6377);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "騎士クンとまた\n海に行きたいな…\nまた、一緒に…", 1, 122601, 0, 0, 6378);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ダ、ダイエット！？\nしてないよ！？\n元々これ位だよ…？", 1, 122601, 0, 0, 6379);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "スイカ割りのコツ？\nわたしは、騎士クンに\n教わりたいな…", 1, 122601, 0, 0, 6380);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "騎士クン。うちわで\n扇いであげるね\nどこに置いたかな…", 1, 122601, 0, 0, 6381);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "うぅ…暑いね…\n騎士クン、温度計は\n見ない方がいいよ～", 1, 122601, 0, 0, 6382);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "じ、じっと見ないで…\nええっと…ちょっと！\nちょっとならいいよ…", 1, 122601, 0, 0, 6383);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "え、肝試し？\nう〜ん、うう〜ん…\n…騎士クンとなら！", 1, 122601, 0, 0, 6384);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう騎士クン\n見て、あっちの空\nもう入道雲が出てる", 1, 122601, 0, 1, 6385);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "夕立、来るかなぁ…\nもし雷が鳴ったら\nそばにいてくれる…？", 1, 122601, 0, 2, 6386);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "しー。…ほら、虫の声\n…わ、わたしの心臓の\n音は気にしないで…！", 1, 122601, 0, 3, 6387);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふふ、水着でゴロゴロ\nするのってなんだか…\nいけないことみたい", 1, 122601, 0, 0, 6389);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいい～♪\n日光浴させて\nあげたいな♪", 1, 122601, 0, 0, 6390);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ほんのり潮の香りが…\n香ばしくて塩辛くて…\nあ…おなか鳴っちゃう", 1, 122601, 0, 0, 6391);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "水着、乾かせるかも…\nそうだ、みんなの分も\n持ってこよう！", 1, 122601, 0, 0, 6392);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "夏バテなんてしてたら\nみんなの足を\n引っ張っちゃうよね\nいただきます！", 1, 122601, 0, 0, 6394);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "騎士クンの、どうして\n海はしょっぱいの？\nって質問の答えは…\n分かんないよぉ～", 1, 122601, 0, 0, 6395);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "顔は怒ってるのに\nなんだかかわいい…\n誰かに似てる…？", 1, 122601, 0, 0, 6397);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "これを枕に、ビーチで\n騎士クンと…なんて…\nなんて…なんて…！", 1, 122601, 0, 0, 6398);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "夏休み、\n毎日たのしいな～♪\nつぎはなにしよう？", 1, 122901, 0, 0, 6399);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "自由研究、\nなににしよっかな～？\nプチグリフォンさんの\nかんさつにっきとか？", 1, 122901, 0, 0, 6400);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "夏休みって、\n給食ないから…\nそれはちょっぴり\nさみしいかも…？", 1, 122901, 0, 0, 6401);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "砂浜をはだしで歩くの\nきもちいいよね♪\nくすぐったいけど\nミミ、好きなんだ～♪", 1, 122901, 0, 0, 6402);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "きれいな貝がら\n見つけちゃった♪\nミミのたからもの！", 1, 122901, 0, 0, 6403);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ミミ、浴衣を\n買ってもらったんだ♪\n今度、おにいちゃんに\n見せてあげたいな！", 1, 122901, 0, 0, 6404);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ミミ、おにいちゃんと\nいっぱい夏休みの\n思い出つくりたいな♪", 1, 122901, 0, 0, 6405);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ねえ、おにいちゃん…\n夏休みの宿題、\nわかんないとこ\nおしえてくれる…？", 1, 122901, 0, 0, 6406);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おかあさんにね、\n麦茶つくるの上手って\nほめられたんだ～♪\n飲んでみて♪", 1, 122901, 0, 0, 6407);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夏休みの宿題で\nポスターかくんだ～♪\nおにいちゃんを\nかいてもいい？", 1, 122901, 0, 0, 6408);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "線香花火やりたいな♪\nミミ、長持ちさせるの\n上手なんだよ♪", 1, 122901, 0, 0, 6409);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "おにいちゃんの\n好きな本ってなあに？\nその本で読書感想文\n書こうかな♪", 1, 122901, 0, 0, 6410);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "海であそんだ後ね、\nおにいちゃんに\n髪を拭いてもらうの\nすきなんだ～♪", 1, 122901, 0, 0, 6411);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "夏休みって、\nワクワクして\n早起きしちゃうよね♪", 1, 122901, 0, 1, 6412);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "わぁ♪　お昼は、\n流しそうめんなんだ？\nミミ、流してみたい♪", 1, 122901, 0, 2, 6413);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "こわい話聞いて、\nねむれないの…\nねえ、おにいちゃん、\nいっしょに寝ていい？", 1, 122901, 0, 3, 6414);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ちょっぴりやすんだら\nまた、いっしょに\n海であそぼうね♪", 1, 122901, 0, 0, 6416);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "すっごくかわいいね♪\nこの子のこと、\n絵日記にかこうっと♪", 1, 122901, 0, 0, 6417);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "くんくん…\nスイカのにおいだね♪\nこのにおいだいすき！", 1, 122901, 0, 0, 6418);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "およいだあとは、\nちゃんと体を\nあっためなくちゃね！", 1, 122901, 0, 0, 6419);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "夏休みのご飯って\nなんだかとくべつ\nおいしい気がするね♪", 1, 122901, 0, 0, 6421);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "夏の星座って\nすっごくきれいだね♪\nいつかみんなと\nいっしょに見たいな♪", 1, 122901, 0, 0, 6422);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "わぁ♪　この子、\nとってもかわいいね！\nおともだちに\nなりたいな♪", 1, 122901, 0, 0, 6424);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "ミミ、人魚姫に\nなったみたい！\nおにいちゃん、\nとなりにすわって♪", 1, 122901, 0, 0, 6425);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "水着姿になると\nバカンス気分を\n味わえちゃうね！", 1, 122801, 0, 0, 6426);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "海に行くの待ちきれ\nなくて、もう水着に\n着替えちゃった！", 1, 122801, 0, 0, 6427);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "海に行ったら\nずぶぬれ系のイタズラ\nたくさんしかけよう！", 1, 122801, 0, 0, 6428);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "部屋の中で泳ぎの練習\nしよう！　にいちゃん\nも水着に着替えて！", 1, 122801, 0, 0, 6429);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "お日さまとお揃いの\n水着なんだ～♪\n似合ってるかなぁ？", 1, 122801, 0, 0, 6430);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "海といえば冒険！\n海底に眠る財宝を\n見つけちゃおう！", 1, 122801, 0, 0, 6431);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "にいちゃんと一緒だと\n部屋にいても海気分♪\nスイカわりしよっか！", 1, 122801, 0, 0, 6432);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "にいちゃん！\n早く海に行く準備\nしなよ～！", 1, 122801, 0, 0, 6433);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ねーにいちゃん\n何秒息止められるか\n勝負しよーよ！", 1, 122801, 0, 0, 6434);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "にいちゃんはアイスと\nかき氷どっちが好き？\nミソギは…どっちも！", 1, 122801, 0, 0, 6435);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "日焼け止めクリーム\nキョウカに\nもらったんだ～", 1, 122801, 0, 0, 6436);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "水中メガネがあれば\n水鉄砲くらっても\n平気だね！", 1, 122801, 0, 0, 6437);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "水着なら、毎日夏休み\n気分！　にいちゃんも\n着てみなよ～！", 1, 122801, 0, 0, 6438);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "にいちゃんおはよー！\n早く顔洗って、\nいっぱい遊んじゃお！", 1, 122801, 0, 1, 6439);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "にいちゃんデザートは\nイチゴのかき氷だよ！\n…激辛ってバレた？", 1, 122801, 0, 2, 6440);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日は楽しかった～！\n明日もイタズラ日和に\nなるといいな！", 1, 122801, 0, 3, 6441);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "落とし穴の下に\nやわらかいの置けば\nケガしないよね！", 1, 122801, 0, 0, 6443);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいね～！\nこの子も海に\n連れてっちゃおうよ！", 1, 122801, 0, 0, 6444);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "このにおいを利用して\nイタズラするには…\nにいちゃんどう思う？", 1, 122801, 0, 0, 6445);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "水着を着て暖炉で\nあったまるのって、\n変でおもしろいね～！", 1, 122801, 0, 0, 6446);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "海辺で食べる\nお昼ごはんって最高♪\nってことで海行こう！", 1, 122801, 0, 0, 6448);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "いつか海を越えて、\n地図にも載ってない\n場所を見つけたいな！", 1, 122801, 0, 0, 6449);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "この口から水が出たら\nみんな驚くよね！\nぷぷ…細工しちゃお！", 1, 122801, 0, 0, 6451);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "変な音がするイタズラ\nを仕込んどいて…\n誰か座らないかな～♪", 1, 122801, 0, 0, 6452);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "あなた様と私の愛を\n周りに見せつけて\n差し上げましょう♪", 1, 102701, 0, 0, 6453);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "呼びましたか？\n呼びましたね？\nでは愛を語りましょう\nそうしましょう", 1, 102701, 0, 0, 6454);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "水着で歩き回るのは\n恥ずかしいな…\n誰も見てないよね？", 1, 122701, 0, 0, 6455);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "夏はやっぱり\nかき氷ですよね\n何色がいいかなぁ…♪", 1, 122701, 0, 0, 6456);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "あの人、泳げないって\n聞きました！\n私が教えてあげないと", 1, 122701, 0, 0, 6457);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "夏休みの宿題は\n計画的に進めましょう\n当たり前のことです！", 1, 122701, 0, 0, 6458);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "防犯魔石、どこに\n着けておこうかなぁ\n…ここにしようかな", 1, 122701, 0, 0, 6459);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "海の楽しみ方は\n予習済みです！\nあとは実践ですね♪", 1, 122701, 0, 0, 6460);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "水着…きっとあの人に\n見られちゃいますよね\n…褒めてくれるかな…", 1, 122701, 0, 0, 6461);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "触りたいんですか？\n…いいですよ\n帽子くらいなら", 1, 122701, 0, 0, 6462);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "夏は体調管理に\n気をつけましょう\n私が管理してあげます", 1, 122701, 0, 0, 6463);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "海に行くのが楽しみで\nたまらないんですか？\n私はそこまで…嘘です", 1, 122701, 0, 0, 6464);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "いつもより薄着だから\nなんだか恥ずかしい…\nみ、見ないでください", 1, 122701, 0, 0, 6465);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "へんたいふしんしゃ～\nえっ？　ああ、これは\n海に叫ぶ練習です", 1, 122701, 0, 0, 6466);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あなたと一緒に\n海に行くなんて…\nなんだか大人…えへへ", 1, 122701, 0, 0, 6467);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\nさぁ、海に行って\n私と運動しましょう", 1, 122701, 0, 1, 6468);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あっつ～い…\nはっ！？　ダメですよ\nシャキッとしないと！", 1, 122701, 0, 2, 6469);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "明日も海で\n遊ぶために、しっかり\nお休みしましょうね", 1, 122701, 0, 3, 6470);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "夏を楽しむときは\n休憩も大事ですよね\n計画的に、計画的に！", 1, 122701, 0, 0, 6472);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいなぁ～\n海のお土産屋さんに\n売ってるかなぁ？", 1, 122701, 0, 0, 6473);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "大人な香りがします\n私も違いが分かる\n素敵な女性になります", 1, 122701, 0, 0, 6474);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "濡れた体を\n乾かしましょう\nタオル、タオル…", 1, 122701, 0, 0, 6475);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "泳いだ後は\n栄養補給…だけど\n…おなか膨らんじゃう", 1, 122701, 0, 0, 6477);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "遊ぶだけじゃなくて\nお勉強もしてますよ\nあなたもどうですか？", 1, 122701, 0, 0, 6478);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "ミミが喜びそう…♪\nわ、私ははしゃいだり\nしませんけど…っ！", 1, 122701, 0, 0, 6480);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "ミソギがいたずらに\n使いそう…しっかりと\n試しておかないと！", 1, 122701, 0, 0, 6481);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "あたしがまさか\nここにいるなんて…\n自分でも不思議だわ", 1, 123001, 0, 0, 6482);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "昔みたいにあちこち\n飛び回れないのって\nちょっと不便かも", 1, 123001, 0, 0, 6483);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "こうして誰かと一緒に\n暮らせるのもあいつや\nみんなのおかげね", 1, 123001, 0, 0, 6484);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ここで厄介になるなら\nあたしも家事とか\n手伝わないと…", 1, 123001, 0, 0, 6485);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "…だめ！　誰かの\n世話をせずには\nいられないわ！", 1, 123001, 0, 0, 6486);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あいつたちが\n帰ってくるところだし\n綺麗にしないと…", 1, 123001, 0, 0, 6487);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "せっかくあたしが\nいるっていうのに\n少しは構いなさいよ…", 1, 123001, 0, 0, 6488);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おいしい店とか\n知らないの？\n食べに行きましょ", 1, 123001, 0, 0, 6489);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あんた暇でしょ？\nあたしのやること\n手伝いなさい", 1, 123001, 0, 0, 6490);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "コッコロたんと\n遊んでくるから\n留守番よろしく♪", 1, 123001, 0, 0, 6491);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あらおかえり…って\nボロボロじゃない！\nまた人助けしてたの？", 1, 123001, 0, 0, 6492);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "やっぱりあたしは\nあんたのそばが\n一番落ち着くみたい", 1, 123001, 0, 0, 6493);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "どこまでだって\nあんたと一緒に\nいてやるんだから", 1, 123001, 0, 0, 6494);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふわぁ…おはよう\n…大きくなったせいか\n朝は特に体が重いわ", 1, 123001, 0, 1, 6495);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ご飯が食べたい？\nしょうがないわね…\nなんか作って\nあげるから", 1, 123001, 0, 2, 6496);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あんたまだ成長期だし\nさっさと寝なさい\n大きくなれないわよ？", 1, 123001, 0, 3, 6497);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "たまにはあたしも\nゆっくりしないと\nもたないのよ…", 1, 123001, 0, 0, 6499);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいじゃな～い♪\nコッコロたんに\nプレゼントしたいわ", 1, 123001, 0, 0, 6500);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りね\n塔にもこういうの\n置いておこうかしら", 1, 123001, 0, 0, 6501);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "炎か…前は\n羽が焼けそうで\n怖かったっけ", 1, 123001, 0, 0, 6502);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "あむ…妖精に\n体重増減の設定って\nあったっけ…？", 1, 123001, 0, 0, 6504);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "記憶のデータと違って\n物語はいいわね\n結末が読めなくて", 1, 123001, 0, 0, 6505);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "冒険のお土産\nみんなにおすそわけ\nせなあきまへんな", 1, 123101, 0, 0, 6507);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "おとぎ話よりも\n不思議なことが\nあるもんやねぇ", 1, 123101, 0, 0, 6508);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "冒険しに出かけるなら\n動きやすい服装に\nせななぁ", 1, 123101, 0, 0, 6509);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "地図に水筒に…\n他に忘れもんは\nあらへんやろか？", 1, 123101, 0, 0, 6510);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "これまでの冒険のこと\nノートに書いて\nまとめてますんよ", 1, 123101, 0, 0, 6511);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "王子はんとの冒険は\nどれもマホマホ王国の\n大事な歴史や♪", 1, 123101, 0, 0, 6512);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "どこへ冒険するときも\nうちと王子はんは\n一緒どす♪", 1, 123101, 0, 0, 6513);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "魔法で火ぃつける\n練習してますんよ～\nよう爆発しますけど…", 1, 123101, 0, 0, 6514);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "うちと王子はんで\n冒険道具をお揃いに\nするんもええなぁ♪", 1, 123101, 0, 0, 6515);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "テント張りも随分\n上達したんよ\n王子はんのおかげやね", 1, 123101, 0, 0, 6516);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ランスロットたちの\n新しい冒険衣装\n思いついたんよ♪", 1, 123101, 0, 0, 6517);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "迷子になっても\n王子はんと一緒なら\nきっと大丈夫やね♪", 1, 123101, 0, 0, 6518);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "王子はんのこと、\nきっちり守れるように\nなってみせますえ", 1, 123101, 0, 0, 6519);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お寝坊さんは\n布団めくって\n起こしにいきますえ～", 1, 123101, 0, 1, 6520);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "支度が終わったら\n今日の冒険に\n出かけまひょか", 1, 123101, 0, 2, 6521);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もうちょっと\nおしゃべりしたいん？\nあと少しだけやで♪", 1, 123101, 0, 3, 6522);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "冒険で疲れた体に\nこの癒しぱわーは\nあきまへん…すや…", 1, 123101, 0, 0, 6524);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふふ、あんさんも\nうちと一緒に\n冒険します？", 1, 123101, 0, 0, 6525);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "虫除けのアロマは\n冒険の必需品どす\n忘れんようにせんと", 1, 123101, 0, 0, 6526);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "うちも魔法使わんでも\n火ぃ起こせるよう\n練習せんとあかんなぁ", 1, 123101, 0, 0, 6527);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "この料理…\n冒険するときに\n作ってみまひょか", 1, 123101, 0, 0, 6529);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "王子はんとの\n愛と冒険のおとぎ話…\nはぁ…素敵やわぁ♪", 1, 123101, 0, 0, 6530);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "あの人との\n最良の未来のために\n占いも霊能力ももっと\n精進しなきゃ", 1, 103101, 0, 0, 6532);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "あなたともっと深く\nつながりたいです\n絆も、そして魂までも", 1, 103101, 0, 0, 6533);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "絆の契約…\nあやつが望むのなら\n考えぬでもないがのう", 1, 104401, 0, 0, 6534);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "なんじゃ？\nわらわの姿に\n見惚れたかの？", 1, 104401, 0, 0, 6535);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "旅の荷物って多いな…\nねぇぷうきち～\nすこしは持ってよぉ～", 1, 123201, 0, 0, 6536);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "傘はなくてもいっか\nぷうきちがいるし♪\n『おいなんだと…？』", 1, 123201, 0, 0, 6537);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "旅先で人見知りなんか\nしてちゃだめだよね…\nまずはあいさつだ…！", 1, 123201, 0, 0, 6538);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "おみやげはやっぱり\nご当地ぬいぐるみ\nだよね♪　ワクワク…", 1, 123201, 0, 0, 6539);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "知らない場所かぁ…\nうぅ…考えただけで\nすでにホームシック…", 1, 123201, 0, 0, 6540);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "野宿するってことは…\nお兄ちゃんのマントで\n寝るチャンスかも…！", 1, 123201, 0, 0, 6541);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "どんなに危険な冒険も\nお兄ちゃんと一緒なら\n大丈夫！　…だよね？", 1, 123201, 0, 0, 6542);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ぷうきちのアイマスク\nも腹巻も持ってくの！\n旅の必需品なの～！", 1, 123201, 0, 0, 6543);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "これ全部背負うのって\nけっこうむずかしいの\n順番まちがえると大変", 1, 123201, 0, 0, 6544);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "えへへ～\nなでなでして？　帽子\nの上からでもいいよ♪", 1, 123201, 0, 0, 6545);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "『悪いが絆創膏の部分\nはアンタッチャブルだ\n綿が飛び出ちまう』", 1, 123201, 0, 0, 6546);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お兄ちゃんと一緒に\nもっともっといろんな\n景色が見たいな！", 1, 123201, 0, 0, 6547);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "旅って、終わる時は\nきっとさびしいよね…\nお兄ちゃん、帰り道は\n手をつないでもいい？", 1, 123201, 0, 0, 6548);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "出発が楽しみすぎて\n寝られなかった…\n『旅行のお約束だな』", 1, 123201, 0, 1, 6549);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "わぁ　いいお天気！\n旅の間もずーっと\nぴーかんだといいな♪", 1, 123201, 0, 2, 6550);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "知らない場所で寝るの\n怖いな…寝る時だけ\n帰ってこようかな…", 1, 123201, 0, 3, 6551);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "旅先にはクッションも\nソファもないよね…\n『俺でいいだろ』", 1, 123201, 0, 0, 6553);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ぬいぐるみのみんな\n旅の無事を\n祈ってて…！", 1, 123201, 0, 0, 6554);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "旅先の香りも\n思い出に持って\n帰れたらいいのにな～", 1, 123201, 0, 0, 6555);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "旅行用に携帯用暖炉\nがあるといいかも…！\n『まだ荷物増やす？』", 1, 123201, 0, 0, 6556);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "『もう出発だぜ？』\nえーまってまって！\n腹ごしらえがまだ…", 1, 123201, 0, 0, 6558);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "世界ってこんなに広い\nんだ…！　はやく自分\nの目で見てみたいな～", 1, 123201, 0, 0, 6559);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "はちゃめちゃヒマ～\nなーんか楽し～コト\nないかなー", 1, 123301, 0, 0, 6561);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ここ、いートコだねー\nこんどカリザきゅんも\nつれてこよー", 1, 123301, 0, 0, 6562);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "かわゆいショタが\n見た～い♪\n触りた～～～い♪", 1, 123301, 0, 0, 6563);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "なんか服きっついなー\nちょい太ったかー？\nん～\nま・気のせーっしょ♪", 1, 123301, 0, 0, 6564);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "あ～やべ\nおねえちゃんに\nメッセすんの忘れたー\nまいっかー", 1, 123301, 0, 0, 6565);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "パンケーキ食いてー\n騎士きゅん\n誘ってみよーっと♪", 1, 123301, 0, 0, 6566);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "きょーも～\n好きぴに囲まれて～\nシ・ア・ワ・セ♪", 1, 123301, 0, 0, 6567);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "アタシと遊ばな～い？\nってなんか\nナンパみスゴー\nウケる～", 1, 123301, 0, 0, 6568);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "んー？\n今はだるいからパース\nあとでねー", 1, 123301, 0, 0, 6569);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "カリザきゅん\n見なかった～？\nおねえちゃんから\n逃げるとかオシオキー", 1, 123301, 0, 0, 6570);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ネイルしたいけど\n無理なんよねー\n爪の間にめっちゃ\nスライム入っからさー", 1, 123301, 0, 0, 6571);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "おねえちゃんに\nかまってほし～の？\nかわゆ～い♪", 1, 123301, 0, 0, 6572);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "な～に騎士きゅん♪\nここでイチャイチャ～\nし・ちゃ・う～？", 1, 123301, 0, 0, 6573);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ねんむ～\nけど外から\nショタの声したんで～\nつい起きちった～", 1, 123301, 0, 1, 6574);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ランチの後はやっぱ\nデザートっしょー\nベツバラってヤツ～♪", 1, 123301, 0, 2, 6575);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "こんな時間まで\n起きてるコは～\n食べちゃうぞ～♪", 1, 123301, 0, 3, 6576);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "あーラクー\nいっしょーここで\nキューケーできるわー", 1, 123301, 0, 0, 6578);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "なにこれ～\nかわいいじゃ～ん\nショタの次くらいに～", 1, 123301, 0, 0, 6579);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いーニオイする～\nなんのニオイとかー\nよくわかんないけどー", 1, 123301, 0, 0, 6580);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったか～♪\n溶けてスライム\n戻りそ～", 1, 123301, 0, 0, 6581);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ン・ン・ン～♪\nお・い・し～♪\nも～っと食べるぅ～♪", 1, 123301, 0, 0, 6583);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "わ～なんかムズー\n読めなー\nウケるー", 1, 123301, 0, 0, 6584);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "あんパンって\nお菓子に入るのかな？\nハロウィンで\nもらえたりしない？", 1, 123501, 0, 0, 6586);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "お菓子をくれなきゃ\nぐうたらするぞ～！\nハロウィン以外でも！", 1, 123501, 0, 0, 6587);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "お化けになったら\n仕事しないで\nゴロゴロし放題\nなのかな？", 1, 123501, 0, 0, 6588);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "おっと…この仮装\n袖がすごく長いからさ\n引っ掛けないように\n気を付けないとね～", 1, 123501, 0, 0, 6589);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "イタズラするのも\n体力がいるよね～\n楽にできそうなの\n何かないかな？", 1, 123501, 0, 0, 6590);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あいつって\n仮装とかするのかな？\n似合いそうなのは\nどんなお化けだろ？", 1, 123501, 0, 0, 6591);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ずっとハロウィンなら\nあいつと遊び放題\nなんだけどな～", 1, 123501, 0, 0, 6592);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今の街はハロウィン\n一色だからね～\n人混みが大変だよ", 1, 123501, 0, 0, 6593);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "この仮装、どうかな？\n気に入ったなら\n来年もしてあげるよ～", 1, 123501, 0, 0, 6594);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "実はこの長い袖\nドングリとかを\nため込めるんだよね…", 1, 123501, 0, 0, 6595);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "カボチャランタンが\nあるんなら\nドングリランタンも\nあっていいよね～♪", 1, 123501, 0, 0, 6596);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ハロウィンでも\nやる気があれば\nぐうたらできる…\nうん、いいこと言った", 1, 123501, 0, 0, 6597);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "一緒にお菓子食べよ？\n寝転びながら堪能する\nハロウィンスイーツは\n最高だからね～", 1, 123501, 0, 0, 6598);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お化けは寝る時間…\n今のあたしはお化け…\nだから、おやすみ～…", 1, 123501, 0, 1, 6599);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼か～…\n食後のデザートは\nハロウィンのお菓子で\n決まりだね～♪", 1, 123501, 0, 2, 6600);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふぁ～、寝よ…\nお化けは夜に\n出るものだけど\nあたしはリスだからね", 1, 123501, 0, 3, 6601);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ハロウィンを楽しむ\nためにも、ぐっすり\n寝とかないとね～", 1, 123501, 0, 0, 6603);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "…袖から手が\n出せないから\nこのまま撫でよう\nよしよし", 1, 123501, 0, 0, 6604);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "リラックスできる\n素敵な香りだね～\n成仏しそうだよ～", 1, 123501, 0, 0, 6605);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかいね～\nここで寝てもいい？\n…着替えないとダメか", 1, 123501, 0, 0, 6606);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…\nお化けもリスも\nお腹は空くんだよ", 1, 123501, 0, 0, 6608);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "キョンシーって\nどんなお化けなのか\n本で調べようかな？", 1, 123501, 0, 0, 6609);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 12, 3, "より取り見取りだね～\nとりあえず、これと\nこのお菓子はキープで", 1, 123501, 0, 0, 6611);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "よし、衣装もばっちり\nハロウィンパレードへ\n出かけよう♪", 1, 123601, 0, 0, 6613);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "仮装してても\n剣は手放せないね\nほとんど体の一部だよ", 1, 123601, 0, 0, 6614);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "見回りに誘うふりして\n二人でパレードに\n参加しちゃおうかな♪", 1, 123601, 0, 0, 6615);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "…あれ？　手錠の鍵\n落としちゃった…？\nやば、出かける前に\n見つけないと…！", 1, 123601, 0, 0, 6616);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "お家でコスプレも\nこれはこれで楽しいな\n決めポーズの練習\nたくさんしておこう！", 1, 123601, 0, 0, 6617);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "他にも、お姫様に\nメイドさんに学生服…\nやりたいコスプレが\n多すぎるよ～", 1, 123601, 0, 0, 6618);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "漫画もゲームも好き！\n仮装するのも大好き！\n…好きを言葉にすると\nもっと好きになる♪", 1, 123601, 0, 0, 6619);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ずっと目が合ってるね\n見つめてくれるのは\nいいんだけど、今日は\n衣装を見てほしいな♪", 1, 123601, 0, 0, 6620);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "トリックオアトリート\nお菓子をくれなきゃ\n逮捕しちゃうぞ♪", 1, 123601, 0, 0, 6621);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あなたにだけはこの姿\nいつでも見せてあげる\nふふ、なんちゃって♪", 1, 123601, 0, 0, 6622);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "どうしたの？\nイタズラするなら\n隙を突かなきゃ\nこんなふうに、ね♪", 1, 123601, 0, 0, 6623);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "コスプレしてても\n剣の稽古は休まないよ\nちょっと相手になって\nくれるかな？", 1, 123601, 0, 0, 6624);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ひゃっ、びっくりした\n急に触らないでよ～\nハロウィンだからって\nイタズラしないでね？", 1, 123601, 0, 0, 6625);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう！\n今日も朝から\nパトロールに行こう！", 1, 123601, 0, 1, 6626);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "カボチャのケーキを\n用意してるよ！\nデザートを食べて\n午後も頑張ろう！", 1, 123601, 0, 2, 6627);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "暗くなってきたね\nカボチャのランタンに\n火を灯そうよ♪", 1, 123601, 0, 3, 6628);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふかふか気持ちいい～\nあっでも衣装がシワに\nなっちゃうかも…？\n…でも気持ちいい～", 1, 123601, 0, 0, 6630);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "…かわいい\nこの子もパレードに\n連れて行きたいな", 1, 123601, 0, 0, 6631);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "はぁ～癒される♪\nハロウィンの見回りが\n終わった後は、\nまったりくつろごう", 1, 123601, 0, 0, 6632);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ここで二人寄り添って\nカボチャスープ飲もう\n…なんて想像したら\nポカポカしてきた…", 1, 123601, 0, 0, 6633);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "パレードに参加すると\n体力を使うから、\nいっぱい食べておこう", 1, 123601, 0, 0, 6635);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "この絵本のお姫様\nかわいいね\nこの仮装もいいな♪", 1, 123601, 0, 0, 6636);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 12, 3, "わあ、おいしそう！\n見回りに行く前に\n少しつまんじゃおう♪", 1, 123601, 0, 0, 6638);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "今日こそは、あの人に\n気持ちを打ち明けて…\nそのあとは…うう\nど、どうしよう？", 1, 103701, 0, 0, 6640);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "私が剣なら、あなたは\nさしずめ私の鞘…\nふふ、私の帰る\n場所ってことだよ♪", 1, 103701, 0, 0, 6641);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "やっぱり\nコスプレしてると\nテンションあがる～♪", 1, 123701, 0, 0, 6642);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "キャラコスにも\n興味あるけど…\nマジカル、ラブリー\nどっちにしよっかな～", 1, 123701, 0, 0, 6643);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "キャラコスといえば\nミスティーシャイニー\nもいいんだよねえ…\nうはー！　悩むー！", 1, 123701, 0, 0, 6644);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ギルドハウスで\n宅コスしてる人\n実は結構\nいるんじゃないかな～", 1, 123701, 0, 0, 6645);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "コスプレだけど普段着\nって言いはれそう…\nって、ダメダメ！\nオタクは節度が大事！", 1, 123701, 0, 0, 6646);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "フェスで買ってきた\n薄い本～♪\nギルドハウスに持って\nきちゃおっかな～", 1, 123701, 0, 0, 6647);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ようこそ\nコスプレ沼へ～\nなんちゃって♪", 1, 123701, 0, 0, 6648);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "どうどう？\nナナカちゃんの\nハロウィンコスプレ\n似合ってる？", 1, 123701, 0, 0, 6649);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ハロウィン魔法少女\n参上カボ～！\n…やっぱ今の語尾\nナシで！", 1, 123701, 0, 0, 6650);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ハロウィンといえば\nトリックオア～…\nコスプレ！\nなんちゃって", 1, 123701, 0, 0, 6651);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ランフェスの\n戦利品～♪\nねえねえ\n見たい？　見たい？", 1, 123701, 0, 0, 6652);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "私にしてほしい\nコスプレがあったら\n教えて♪　君のために\nや～ってやるぜぇ！", 1, 123701, 0, 0, 6653);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "一緒にコスプレしたい\nならナナカちゃんは\nいつでも大歓迎だよ♪", 1, 123701, 0, 0, 6654);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふぁあ…ねむ\nって、ありゃりゃ　\n昨日コスプレしたまま\n寝ちゃってたかあ…", 1, 123701, 0, 1, 6655);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今日のお昼は\nなんにしよ？\nカボチャ料理に\nしよっかな～", 1, 123701, 0, 2, 6656);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もうこんな時間かあ\nそういえばオタクって\n夜行性の人が多い\n気がするぜぇ…", 1, 123701, 0, 3, 6657);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふっふっふ\nこのパニエは\n座るときはちゃんと\nふにゃってなるのさ！", 1, 123701, 0, 0, 6659);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "いや～\nかわいいものをみると\n癒されますな～", 1, 123701, 0, 0, 6660);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "新しい薄い本の匂いの\nアロマとか…ダメ？\n私はあの匂い、なんか\n好きなんだよね～", 1, 123701, 0, 0, 6661);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "暖か～い…\nけど近づきすぎて\n衣装が燃えないように\n気を付けなきゃ", 1, 123701, 0, 0, 6662);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "コス衣装のために\n体型維持は必須だけど\nついつい\n食べちゃうんだよね～", 1, 123701, 0, 0, 6664);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "おっ、次はこの本に\nのってるキャラのコス\nしてみよっかな？", 1, 123701, 0, 0, 6665);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 12, 3, "おおっ！\nお菓子がいっぱい！\nベルルちゃんチョコ\n入ってないかな～？", 1, 123701, 0, 0, 6667);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "むっ…\nこの耳の手触り…\n驚嘆に値する…！", 1, 123801, 0, 0, 6669);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "獲物を狩りまくる…\nそんなウサギがいても\nいいだろう？", 1, 123801, 0, 0, 6670);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ワナなど怖くないぞ？\nむしろ積極的に\n踏んでいく性分だ", 1, 123801, 0, 0, 6671);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "一匹狼ならぬ\n一匹ウサギか\nどっちでもかまわん♪", 1, 123801, 0, 0, 6672);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "人間とて本を正せば獣\n本能に従えばよいのだ\n遠慮は無用さ☆", 1, 123801, 0, 0, 6673);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "脱兎のごとく…\n逃げるものか\n坊やを追い回すのさ♪", 1, 123801, 0, 0, 6674);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "獣の道は険しいが…\n坊やめ、音を上げずに\nちゃんとついてきたな\n褒めてやるとしよう♪", 1, 123801, 0, 0, 6675);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ニンジンはいらん\n好物は好敵手だ\nさぁどんどんおくれ♪", 1, 123801, 0, 0, 6676);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "尻尾に触りたいだと？\nワタシの乱数聖域を\n崩せたらな…☆", 1, 123801, 0, 0, 6677);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "頭で考えるな\n体に率直になれ\n己を野放しにするのさ", 1, 123801, 0, 0, 6678);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "そうさモコフワさ♪\nなで心地は最高だが\n意外にどう猛だぞ…？", 1, 123801, 0, 0, 6679);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ワタシにピョンピョン\n跳ねてほしいのか？\nあとでじっくり、な♪", 1, 123801, 0, 0, 6680);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ワタシと番になるか？\nオマエさえよければ\nいつでもかまわんぞ☆", 1, 123801, 0, 0, 6681);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "太陽と共に目覚め\n活動する\nそれが獣の生き方さ☆", 1, 123801, 0, 1, 6682);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼寝をすればいい\nワタシが周囲を\n警戒していてやる", 1, 123801, 0, 2, 6683);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "暗くなれば眠るだけさ\nそうすれば余計な\nストレスなどたまらん", 1, 123801, 0, 3, 6684);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "むむっ！？\n尻尾がつっかえて\nうまく座れんな…", 1, 123801, 0, 0, 6686);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "愛らしさでワタシに\n張り合おうというのか\n５億年後に出直せ☆", 1, 123801, 0, 0, 6687);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "野生の芳香か…\n本能が呼び覚まされる\nいいセンスだ♪", 1, 123801, 0, 0, 6688);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "寒さも野生のうちだ\n…とはいえ\n温まっていくか♪", 1, 123801, 0, 0, 6689);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "悪くはないが物足りん\nこう見えて肉食なのだ\n肉はないのか肉は☆", 1, 123801, 0, 0, 6691);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ウサギ族は地獄耳？\nワタシとの共通点だな", 1, 123801, 0, 0, 6692);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "ここが私の家…\nそれはこれからも\nずっと変わらないわ…", 1, 106401, 0, 0, 6694);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "ええと、その…今から\nデート…じゃなくって\n散歩でもどうかしら？\n…ふ、二人きりで…", 1, 106401, 0, 0, 6695);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ギルドハウスに\nヒーロー参上！\nみんな仲良くッスよ！", 1, 123901, 0, 0, 6696);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "料理もできて\n鎧も作れる！\nお母さんはすごいッス", 1, 123901, 0, 0, 6697);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ううう…\nまたマントをドアに\n挟んじゃったッス…", 1, 123901, 0, 0, 6698);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ずっと鎧を着ていれば\nジュンさんに近づける\nかも？　燃えるッス！", 1, 123901, 0, 0, 6699);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "サインの練習…\nもっとしておいた\nほうがいいッスかね～", 1, 123901, 0, 0, 6700);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "半人前でも\n胸を張るッス！\nそのうち似合う日が\nくるッスから！", 1, 123901, 0, 0, 6701);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "種族の違いも\n強い魂があれば\n超えられるッス！\n信じてるッスよ！", 1, 123901, 0, 0, 6702);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "困ったときは\n自分を呼ぶッス！\nあと楽しいときにも\n呼んでほしいッス！", 1, 123901, 0, 0, 6703);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "特訓でも行くッスか？\n望むところッス！\n目指せ、一人前！", 1, 123901, 0, 0, 6704);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "新しいショーの台本を\n読みこんでるッス！\nところで…この言葉の\n意味、分かるッスか？", 1, 123901, 0, 0, 6705);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ヒミツがなくなると\nなんか恥ずかしいッス\nあんたはどうッスか？", 1, 123901, 0, 0, 6706);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ヒーローは遅れて\nやってくる…\nあんたもそうッスね♪", 1, 123901, 0, 0, 6707);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "誰よりも早く\nあんたに見せたいッス\n一人前になった自分！", 1, 123901, 0, 0, 6708);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "うーん、今日も\nよく眠れたッス～！\n絶好調、間違いなし！", 1, 123901, 0, 1, 6709);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おお、もうお昼ッスか\nどうりでお腹が空くと\n思ったッス～えへへ", 1, 123901, 0, 2, 6710);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "パトロールのあとは\n歯みがきに宿題に…\n大忙しッスね、夜！", 1, 123901, 0, 3, 6711);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "こんなにリラックス\nできるなんて…\n平和な証拠ッスね～", 1, 123901, 0, 0, 6713);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "か、かわいい…♪\nさあ、自分と握手…\nううん、抱っこッス♪", 1, 123901, 0, 0, 6714);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "優しい匂いッスね…♪\nこれくらいみんなを\n包み込めるように\nなりたいッス～", 1, 123901, 0, 0, 6715);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ひっくちゅ！　うー…\nちょっと冷えるッスね\nぬくぬくするッス～♪", 1, 123901, 0, 0, 6716);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "特訓した分、\nいっぱい食べるッス！\nでっかくなるッス！", 1, 123901, 0, 0, 6718);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "いつか自分の\nヒミツ図鑑が出たり\nして…いやいやいや", 1, 123901, 0, 0, 6719);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "牢獄よりは\nマシな環境ね\n我慢してあげるわ", 1, 106901, 0, 0, 6721);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "退屈ね…\nキャルでもいじって\n暇をつぶそうかしら", 1, 106901, 0, 0, 6722);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ここにいる連中\n私を天気予報士と\n勘違いしてない？", 1, 106901, 0, 0, 6723);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "音波情報が多いわね…\nここ、もう少し静かに\nならないの…？", 1, 106901, 0, 0, 6724);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "共同生活なんて\n久しぶりだわ\n…懐かしいわね", 1, 106901, 0, 0, 6725);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あの子たちのギルド\n経営が雑すぎるわ…！\n教育が必要みたいね", 1, 106901, 0, 0, 6726);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "とどめを刺される\n準備はできているのに\nまだなのかしら…？", 1, 106901, 0, 0, 6727);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "私と戦う気になった？\nあら、まだなのね…\nその時を待ってるわよ", 1, 106901, 0, 0, 6728);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "私というリソースは\n有効活用しなさい\n子守なんてごめんだわ", 1, 106901, 0, 0, 6729);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "どうしてそんなに\n頭がいいか？\n生まれつきよ", 1, 106901, 0, 0, 6730);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "視力は権能に\n影響しないわよ\n当たり前じゃない", 1, 106901, 0, 0, 6731);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あなたまで天気を\n教えろですって…？\nぶっ殺すわよ？", 1, 106901, 0, 0, 6732);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "暇なら付き合いなさい\n好きなゲームでいいわ\nどうせ私が勝つもの", 1, 106901, 0, 0, 6733);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "人生朝露…\n悔いのない一日を\n過ごしなさい", 1, 106901, 0, 1, 6734);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "午睡はいいわよ…\nふわぁ…眠りは思考に\n必要不可欠なの…", 1, 106901, 0, 2, 6735);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夙興夜寝なんて\nやめておきなさい\n休息は大切よ", 1, 106901, 0, 3, 6736);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "私を満足させるなんて\n大したものね…晶に\n大量生産させるわ", 1, 106901, 0, 0, 6738);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "キャルの代わりに\nズタズタにする物が\n欲しかったの…♪", 1, 106901, 0, 0, 6739);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りじゃない\n見たことのない調合ね\n誰が用意したの？", 1, 106901, 0, 0, 6740);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "パワーが足りないわね\nもっとよ、もっと私を\n寛がせなさい", 1, 106901, 0, 0, 6741);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "栄養価はともかく\n味のバランスは\n悪くないわね", 1, 106901, 0, 0, 6743);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "つまらない本は\n私が書き直すわ\nこれはどうかしら？", 1, 106901, 0, 0, 6744);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "今年はアカリと\nお姉ちゃんでサンタが\n二人…つまり幸せも\n二倍ですね♪", 1, 124001, 0, 0, 6746);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "クリスマスに向けての\nサックス練習…\nお兄ちゃんと一緒に\n猛特訓です！", 1, 124001, 0, 0, 6747);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "クリスマスツリーの\n飾りつけ、完璧です♪\nお兄ちゃんお姉ちゃん\n喜んでくれるかな？", 1, 124001, 0, 0, 6748);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "わあ、お外が真っ白！\n生クリームが\nいーっぱいの\nケーキみたいです♪", 1, 124001, 0, 0, 6749);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "煙突から入ると\nお洋服が汚れちゃう…\n玄関からじゃ\nダメなのかなぁ？", 1, 124001, 0, 0, 6750);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お兄ちゃんが来たら\nサンタのお洋服\nいっぱい褒めて\nもらおっと♪", 1, 124001, 0, 0, 6751);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "聖夜をお兄ちゃんと\n過ごせたら…\nアカリもちょっぴり\n大人になれるかも♪", 1, 124001, 0, 0, 6752);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今のアカリは\nサンタさんですから♪\nなんでもお願いして\nくださいね？", 1, 124001, 0, 0, 6753);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お外は寒いですから\nアカリとくっついて\nお出かけしましょ♪", 1, 124001, 0, 0, 6754);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お兄ちゃんは\nアカリのトナカイさん\nですから、ずーっと\nそばにいてください♪", 1, 124001, 0, 0, 6755);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お兄ちゃん、助けて！\nアカリのカラダで\nラッピング練習したら\n絡まっちゃいました…", 1, 124001, 0, 0, 6756);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "プレゼント、いっぱい\n準備できました♪\nお兄ちゃんの分は…\nまだヒミツでーす♪", 1, 124001, 0, 0, 6757);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "アカリ、プレゼントは\n大人っぽいのがいいな\n早くお兄ちゃんに\n追いつきたいから♪", 1, 124001, 0, 0, 6758);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます♪\nふふ、アカリサンタは\nいい子のお手本なので\n早寝早起きなんです♪", 1, 124001, 0, 1, 6759);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あれ、もうお昼？\nクリスマスナンバーの\n練習してたら\nもうこんな時間…", 1, 124001, 0, 2, 6760);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "冬の夜空は星が\nキレイですね～\nお兄ちゃん、一緒に\n見に行きませんか？", 1, 124001, 0, 3, 6761);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "はぁ、快適すぎて\nとろけちゃいそう…\nこういうプレゼントも\nいいかもです…", 1, 124001, 0, 0, 6763);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "やん、かわいいです♪\nえへへ、お兄ちゃんは\nどんなプレゼントが\n欲しいですか～？", 1, 124001, 0, 0, 6764);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "わわ、大人な香り…\nロマンチックな\nクリスマスが\n過ごせそうです♪", 1, 124001, 0, 0, 6765);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "これでカラダを温めて\nアカリの温もり…\nお兄ちゃんに\nおすそ分けしよっと♪", 1, 124001, 0, 0, 6766);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "お腹がパンパンです…\nでもこれで\nちょっとサンタさんに\n近づけたかも…？", 1, 124001, 0, 0, 6768);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "クリスマスイブの\n恋人との過ごし方…？\nはわわ、アカリには\nまだ早いかもです…！", 1, 124001, 0, 0, 6769);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 14, 3, "わっ、すごいすごい！\n不思議な絵本ですね♪\nこの本でお兄ちゃんに\nイタズラしちゃお♪", 1, 124001, 0, 0, 6771);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 15, 3, "アカリ、ホカホカに\nなっちゃいました～♪\n…ぎゅってしても\nいいですよ？", 1, 124001, 0, 0, 6772);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "またエンジェルになる\nかもとは思ってたけど\n…サンタさん要素の\n追加は想定外だったわ", 1, 124101, 0, 0, 6773);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ラフィたちがいない\nときは私がなんとか\nしないとね\n一応…エンジェルだし", 1, 124101, 0, 0, 6774);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "部屋の飾りつけとか\nするのも…あり？\nふふ、浮かれすぎかな", 1, 124101, 0, 0, 6775);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "パーティーだったら\nみんなで大人数向けの\nボードゲームもできる\nかも…やったっ", 1, 124101, 0, 0, 6776);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "この服のモコモコ…\n気づいたら触っちゃう\n…やるわね、ラフィ", 1, 124101, 0, 0, 6777);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "アイツと一緒にいると\n人見知りとは違う\n緊張があるのよね…\nって今の聞いてたっ？", 1, 124101, 0, 0, 6778);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ぬいぐるみ…\nいじめてないわよね？\n…大事にしてるって？\nそれはそれで…あうぅ", 1, 124101, 0, 0, 6779);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "いい子と悪い子って\nどう見分けるのかしら\n…まさか素直さとか？\nだったら困る！", 1, 124101, 0, 0, 6780);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "プレゼントといえば\nやっぱりゲーム！\n年末商戦サイコー♪", 1, 124101, 0, 0, 6781);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "サンタさんはお仕事を\n見られちゃ\nいけないのよね？\n…天職？", 1, 124101, 0, 0, 6782);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "この服は汚れ対策も\nバッチリなのよね\n煙突に入れるように\n…いや私はNGよ！？", 1, 124101, 0, 0, 6783);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "アンタのお願い…\n今なら一つくらい\n聞いてあげるわよ？\nほら、サンタ衣装だし", 1, 124101, 0, 0, 6784);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "私たちって\nなぜかぬいぐるみと\n縁があるわよね\n…ふふ", 1, 124101, 0, 0, 6785);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お、おはよっ\n…ふぅ、寝ぐせを\n直すのが間に合って\nよかったぁ", 1, 124101, 0, 1, 6786);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "え…一緒にごはん？\nそ、そう…うん。OK\nまあ、せっかくだし？", 1, 124101, 0, 2, 6787);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "この時間のゲームって\n妙に楽しいのよね\n…ということで、\nちょっと遊ばない？", 1, 124101, 0, 3, 6788);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ああ～ダメになるぅ…\nもうここでずっと\nゲームしてた～い", 1, 124101, 0, 0, 6790);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "プレゼントのために\n研究は必要よね、うん\n…はぁ、かわいい～♪", 1, 124101, 0, 0, 6791);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "集中力を高める香りも\nあるのよね…\n勝負をするときには\n持ち歩こうかしら", 1, 124101, 0, 0, 6792);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "なんだかまったり\nしちゃうわね…\n時間が溶けるわ…", 1, 124101, 0, 0, 6793);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "お腹いっぱい\n食べられるのも\n幸せなことよね", 1, 124101, 0, 0, 6795);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ちっちゃいときは\nアカリと一緒に絵本を\n読んだなぁ…懐かしい", 1, 124101, 0, 0, 6796);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 14, 3, "飛び出す絵本…\nこれでゲームブックを\n作ったらおもしろく\nなる気がするわ…", 1, 124101, 0, 0, 6798);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 15, 3, "あったまる…\nモフモフ…ふわふわ…\nちょっと休憩しても…\nいいよね…？", 1, 124101, 0, 0, 6799);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "あら、どうしたの？\nもしかして、私と\n新しい実験を\n始めたくなった？", 1, 105101, 0, 0, 6800);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "調子が悪いときは\n診療所に来て\n君は特別に、じっくり\n診察してあげるわ♪", 1, 105101, 0, 0, 6801);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "特別じゃなくても\nまったり過ごす\nクリスマスも\nいいものだね", 1, 124201, 0, 0, 6802);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ニットの帽子に\nマフラーに耳当て…\n素顔用の防寒対策を\n整えなければ", 1, 124201, 0, 0, 6803);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "靴下が\n見当たらなかったから\n枕元にはかわりに\n鎧を置いておこう", 1, 124201, 0, 0, 6804);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "聖女なんて言われる程\n素晴らしくはないけど\n心は聖くいたいものだ\n日々精進だね", 1, 124201, 0, 0, 6805);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "兜がないから\nイルミネーションが\nいつもよりまぶしく\n感じるよ", 1, 124201, 0, 0, 6806);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "皆の幸福を\n祈願して\nクリスマスリースを\n飾ろうか", 1, 124201, 0, 0, 6807);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "私にはかわいすぎる\n衣装だが…開き直って\nクリスマス気分を\n楽しんでしまおう", 1, 124201, 0, 0, 6808);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ツリーの飾りつけ\n手伝ってくれるかい？\nセンスは少年に\nお任せするよ", 1, 124201, 0, 0, 6809);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "パーティーは\n用意してる時も楽しい\nねえ少年、この気持ち\n分かってくれるかい？", 1, 124201, 0, 0, 6810);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "なんでトナカイの鼻は\n赤いのかって？\n無灯ソリ運転は違反で\n取り締まられるからだ", 1, 124201, 0, 0, 6811);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "トモちゃんや\nマツリちゃんは\nいい子だから、きっと\nサンタさんに会えるね", 1, 124201, 0, 0, 6812);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ヒイラギの髪飾り\n実は気にいってるんだ\n少年にも\n褒めてもらいたいな", 1, 124201, 0, 0, 6813);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ねえ少年…そろそろ\n見慣れてほしい\nそんなにまじまじ\n見つめられると照れる", 1, 124201, 0, 0, 6814);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝日に照らされて\n街がキラキラ白銀に\n輝いてるよ", 1, 124201, 0, 1, 6815);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ご飯を食べて\nちょっと散歩しようか\n祝祭に沸く街は\nとてもきれいだよ", 1, 124201, 0, 2, 6816);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "やっぱりクリスマスは\n夜が本番って感じだね\nキャンドルを灯して\n厳かに過ごそうか", 1, 124201, 0, 3, 6817);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "鎧姿では無縁だったが\nふかふかしていて\n気持ちいいな…\nふかふか…ふかふか…", 1, 124201, 0, 0, 6819);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふふ、かわいいね\n抱きしめると\nあの雪の日に産まれた\n赤ちゃんを思い出す", 1, 124201, 0, 0, 6820);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "兜を脱いだおかげで\nこの香りに出会えた\n…クリスマスの魔法も\n悪くないかもね", 1, 124201, 0, 0, 6821);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "指先から体の芯まで\n暖まるね\nこれなら雪の日でも\n安心だよ", 1, 124201, 0, 0, 6822);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐ、もぐ…\nあまり食べるところ\n見ないでほしい", 1, 124201, 0, 0, 6824);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "素敵なレストランの\n特集記事が載ってる\n聖夜に予約が取れたら\n最高に幸せだろうね", 1, 124201, 0, 0, 6825);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 14, 3, "わっ！\n…………いや\n驚いてなどいない", 1, 124201, 0, 0, 6827);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 15, 3, "ふふ…頬に直接\nふかふかを感じられる\n温かくて気持ちいいよ", 1, 124201, 0, 0, 6828);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ピアノに読書…\nグレアと一緒に\nなにをしようかな～♪", 1, 124301, 0, 0, 6829);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "元の世界へ戻った時\n授業に遅れないよう\nグレアと勉強しとこう", 1, 124301, 0, 0, 6830);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "街に魔物料理屋さんが\nあるんだ！　グレアと\n食べに行ってみよう♪", 1, 124301, 0, 0, 6831);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "せっかく新しい魔法を\n覚えたし、グレアにも\n見てもらいたいな！", 1, 124301, 0, 0, 6832);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "グレアも誘って\nランドソルをもっと\n探索したい！", 1, 124301, 0, 0, 6833);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "私たちも\nあの人を見習って\nバイトとかしよう！", 1, 124301, 0, 0, 6834);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "いつかあの人を\n私たちの学院に\n招待したいな！", 1, 124301, 0, 0, 6835);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あのね！\nこれからグレアと\n魔法愛好会に\n行くんだ！", 1, 124301, 0, 0, 6836);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "これからなにするの？\n私たちもついて行って\nいいかな！？", 1, 124301, 0, 0, 6837);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "グレアと一緒に\nあなたも魔法の練習\nしてみない？", 1, 124301, 0, 0, 6838);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "グレアとよく話すの\nマナリアの制服\nあなたに着せたいって", 1, 124301, 0, 0, 6839);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "グレアのそばって\n温かいんだ～！\nぬくぬくだよ～♪", 1, 124301, 0, 0, 6840);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あなたは\nグレアと私の友達！\nこれからもずっと！", 1, 124301, 0, 0, 6841);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう！\n今朝はグレアと一緒に\n外を散歩してきたよ！", 1, 124301, 0, 1, 6842);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹空いたな…\nよし、グレアと一緒に\n魔物料理を作ろう！", 1, 124301, 0, 2, 6843);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もうこんな時間だね\n明日のために\nそろそろ寝ようかな！", 1, 124301, 0, 3, 6844);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "はぁ～この感触…\nグレアの尻尾みたいで\n安らぐ～", 1, 124301, 0, 0, 6846);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ぬいぐるみって\nいいよね…私もよく\nグレアに抱き付くんだ", 1, 124301, 0, 0, 6847);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り～…\nグレアもこういうの\n好きなんだよ！", 1, 124301, 0, 0, 6848);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかいね～…\nグレアにくっついてる\n時を思い出すよ～…", 1, 124301, 0, 0, 6849);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "この世界にしかない\nおいしいものが\nたくさんあるよね！", 1, 124301, 0, 0, 6851);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "世界を繋ぐ魔法の\nヒント…本に書いて\nないかなぁ…", 1, 124301, 0, 0, 6852);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ピアノに読書…\n今日のアンは\nなにをするのかな…", 1, 124401, 0, 0, 6855);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "私はアンほど\n勉強はできないから\nちゃんと自習しないと", 1, 124401, 0, 0, 6856);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "一度始めたら\nとことん追求するのが\nアンなんだよね…", 1, 124401, 0, 0, 6857);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ふふ…夢中になってる\nアンを眺めてるだけで\n一日があっという間…", 1, 124401, 0, 0, 6858);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ランドソルは広いね…\nアンと一緒にいろんな\n場所へ行ってみたい", 1, 124401, 0, 0, 6859);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "アンやあの人の笑顔を\n見てると、すごく\n安心するんだ…", 1, 124401, 0, 0, 6860);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "もしあの人が私たちの\n学院に編入したら…\nふふ、楽しそうだね", 1, 124401, 0, 0, 6861);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "アンもあなたも\nすごいな…\nみんなとすぐに\n仲良くなっちゃうから", 1, 124401, 0, 0, 6862);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あなたはこれから\nなにをするの？\nその…アンと一緒に\nついていってもいい？", 1, 124401, 0, 0, 6863);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "アンから魔法の練習に\n誘われた？　実は私も\n…一緒にどうかな？", 1, 124401, 0, 0, 6864);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あなたがマナリアに\n編入したら\n楽しいのになって\nアンとよく話すんだ…", 1, 124401, 0, 0, 6865);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "こっちの世界にも\nアンのように\n私を受け入れてくれる\n人たちがいるんだね…", 1, 124401, 0, 0, 6866);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "元の世界へ帰る日が\n来たとしても私たちは\n「さよなら」より\n「またね」がいいよね", 1, 124401, 0, 0, 6867);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう。さっき\nランドソルの朝日を\nアンと見てきたんだ", 1, 124401, 0, 1, 6868);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "私たちは\nこれからなんだけど\nあなたはお昼ごはん\n何を食べたの？", 1, 124401, 0, 2, 6869);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ\nアンが眠る時間だ…\nあなたもおやすみ", 1, 124401, 0, 3, 6870);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "はぁ、疲れが取れる…\nこの尻尾…\nちょっと重いんだよね", 1, 124401, 0, 0, 6872);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "これ…\nアンに見せたら\n喜ぶだろうな…", 1, 124401, 0, 0, 6873);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り…\nアンの感想も\n聞いてみたいな", 1, 124401, 0, 0, 6874);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかい…\nアンがここにいたら\n本を読みながら\n寝ちゃうんだろうな", 1, 124401, 0, 0, 6875);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいしいからたくさん\n食べれちゃうけど\nまた尻尾…\n大きくなっちゃうかな", 1, 124401, 0, 0, 6877);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "アンがおススメ\nしてくれた本は\nこれかな…？", 1, 124401, 0, 0, 6878);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "凶、凶、凶…大凶？\nなによこのおみくじ\n自宅用だからって\n排出率が適当すぎよ…", 1, 124701, 0, 0, 6881);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "今年こそ最高の新薬が\nもはや偶然に近い\n最小限の手間で\n作れますように", 1, 124701, 0, 0, 6882);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "喉に詰まる前に\n溶けてなくなるお餅…\n最優先の研究課題だわ", 1, 124701, 0, 0, 6883);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "よし、完成♪\nミツキ特製…\n「新解釈おせち料理」\n医学的根拠が満載よ", 1, 124701, 0, 0, 6884);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "お年玉を彼に…\nあげるべき…？\n色んな意味で微妙ね…", 1, 124701, 0, 0, 6885);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ふふ、今年もまた一年\n彼のバイタルを\n記録できるのね♪", 1, 124701, 0, 0, 6886);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "今年こそ\n私の薬で彼を魔改造…\nううん、大人の男に！", 1, 124701, 0, 0, 6887);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "コマ回しのコマを\n見てたら目が回った？\nそう…手当は不要よ…", 1, 124701, 0, 0, 6888);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "私の顔で\n福笑いを作った？\nあら…隻眼まで\n再現度が高いわね♪", 1, 124701, 0, 0, 6889);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "門松よし、しめ縄よし\nこんなギルドでもね\n一応縁起を担ぐのよ", 1, 124701, 0, 0, 6890);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "本気の薬草を煮込んだ\n本気の七草粥よ\n色は気にしちゃダメ", 1, 124701, 0, 0, 6891);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "君が今年も健康で\nつつがなく…実験台を\n務められますように", 1, 124701, 0, 0, 6892);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "いくつ新年を迎えても\n俗世の垢にまみれない\nそんな君こそが…\n私には最高のお薬よ", 1, 124701, 0, 0, 6893);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お正月なんだから\nいつまでも寝てないで\nさぁ、実験開始よ♪", 1, 124701, 0, 1, 6894);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "カルタも双六もしたし\nあとは実験くらいしか\nやることがないわね", 1, 124701, 0, 2, 6895);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "日頃からたいがい\n意味深な夢を見るけど\n初夢はまた別かしら…", 1, 124701, 0, 3, 6896);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "さすがにこの格好で\n寝正月を敢行するのは\nためらわれるわね", 1, 124701, 0, 0, 6898);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "や、闇医者たる者\nこんな愛くるしい物に\n心奪われるわけには…", 1, 124701, 0, 0, 6899);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "お雑煮のいい香り…\n食欲が増進されるわ\nアロマも立派なお薬ね", 1, 124701, 0, 0, 6900);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "胸元は閉じないわよ？\nでも時々ここで\nこっそり暖まるの…", 1, 124701, 0, 0, 6901);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "無から有が生まれてる\n新年早々物理の法則を\n無視してくるのね…", 1, 124701, 0, 0, 6903);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "どれもこれも読んだわ\n新しい婚活本の\n入荷はまだかしら…", 1, 124701, 0, 0, 6904);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "彼が一生懸命\n書いてくれた年賀状\n気持ちがこもっていて\nすごくうれしいわ♪", 1, 124601, 0, 0, 6906);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "しっかり丁寧に\n大掃除したから\nとってもいい気持ちで\n新年を迎えられたわ♪", 1, 124601, 0, 0, 6907);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "彼の着物姿\nきっと凛々しいわよね\n想像しただけで\n笑顔になるわ～♪", 1, 124601, 0, 0, 6908);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お雑煮は地域によって\n違いがあるけれど\n愛情が隠し味なのは\nどこも一緒よね♪", 1, 124601, 0, 0, 6909);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "彼と凧揚げして\n遊びたいけど\n森では引っかかって\nできないかしら…？", 1, 124601, 0, 0, 6910);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "今年も彼が素直に\n成長できるように\nたくさんいい子いい子\nしてあげましょう…♪", 1, 124601, 0, 0, 6911);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "絵馬に彼と\n書いた通り\n今年もみんなが笑って\n過ごせますように", 1, 124601, 0, 0, 6912);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "先生と初詣に\n行きましょう〜♪\n迷子にならないように\n手を繋いで、ね？", 1, 124601, 0, 0, 6913);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "初売りセールいいわね\nでも気を付けないと\nあれこれ欲しくなって\n買い過ぎちゃうかも…", 1, 124601, 0, 0, 6914);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "風邪をひかないように\n温かくするんですよ～\nえ？　先生、温めて？\nふふ、甘えん坊さんね", 1, 124601, 0, 0, 6915);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あなたのために\nちょっと豪華なおせち\n用意したのよ\nお口に合うかしら？", 1, 124601, 0, 0, 6916);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あなたも着物着たい？\nふふ、貫禄出ちゃって\n先生ドキドキ\nしちゃうかも…♪", 1, 124601, 0, 0, 6917);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あなたの成長は\nとってもうれしいけど\n今年もまだ、あなたの\n先生でいたいな…♪", 1, 124601, 0, 0, 6918);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あら、起きたの？\nお雑煮できてるから\nちゃんとお顔\n洗ってらっしゃいね", 1, 124601, 0, 1, 6919);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ご飯を\nしっかり食べて\nみんなでかるた大会\nしましょう〜♪", 1, 124601, 0, 2, 6920);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "は～い、良い子は\nもう寝る時間ですよ\n素敵な初夢が\n見られますように♪", 1, 124601, 0, 3, 6921);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "このフカフカちゃんも\n天日干ししたいけど…\nその前にちょっと\n休憩しちゃおうかしら", 1, 124601, 0, 0, 6923);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "うふふ、かわいい～\nアオイちゃんや\nハツネちゃんも\nきっと気に入るわね♪", 1, 124601, 0, 0, 6924);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "お正月は空気も\n透き通ってるから\nいつも以上に\n素敵な香りに感じるわ", 1, 124601, 0, 0, 6925);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "火のぬくもりに\n抱かれていると\n不思議と眠気が…\nふああ…", 1, 124601, 0, 0, 6926);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "愛情のこもった料理は\nおいしいだけじゃなく\n心も満たされちゃう♪", 1, 124601, 0, 0, 6928);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "お正月のお作法も\nたくさんあるのね～\n先生も日々勉強だわ～", 1, 124601, 0, 0, 6929);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "少年への感謝をどんな\n形で伝えるべきか…\n言葉よりも物の方が\n良いのだろうか？", 1, 104701, 0, 0, 6931);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "話し相手になって\nもらってもいいかな？\n少年と一緒にいると\nとても楽しいんだ", 1, 104701, 0, 0, 6932);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "お正月だからって\nギャングのボスは\n油断できないよ～？", 1, 124501, 0, 0, 6933);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "イノリちゃんがお年玉\n欲しいんだって♪\n悪い子だったし\n10ルピでいいかな☆", 1, 124501, 0, 0, 6934);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "お正月だからお雑煮を\n作ったんだけど\nカヤちゃんには\n大好評だったよ♪", 1, 124501, 0, 0, 6935);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ラーゴがお餅を\n食べたがってるけど…\nこの子にあげるのは\nちょっと心配かな～？", 1, 124501, 0, 0, 6936);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "お正月は晴れ着の子が\nやっぱり多いよね～\n今度、私の漫画でも\n出してみようかな？", 1, 124501, 0, 0, 6937);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "君と二人っきりで\n神殿に初詣…\n行ってみたいな～♪", 1, 124501, 0, 0, 6938);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "君とお正月を\n過ごしていると\n面倒なことも\n全部忘れられそう…", 1, 124501, 0, 0, 6939);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "この着物、どう思う？\n似合ってたら\nうれしいけどな～♪", 1, 124501, 0, 0, 6940);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "袖を引っ張ったり\nしないでね？\n着崩れしちゃうから♪", 1, 124501, 0, 0, 6941);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お正月ならではの\n漫画ネタってある？\n参考にしたいんだよね", 1, 124501, 0, 0, 6942);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "昔は凧あげとか\n駒回しとかしてたけど\n大人になるとそういう\n機会も減るよね…", 1, 124501, 0, 0, 6943);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "君にもお年玉を\nあげようか？\n好きな額を言ってね☆", 1, 124501, 0, 0, 6944);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "来年も、再来年も…\nこうしてみんなで\n新年がお祝いできると\n素敵だね～♪", 1, 124501, 0, 0, 6945);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよ～♪\n朝ごはんは\n焼いたお餅とか\nどうかな？", 1, 124501, 0, 1, 6946);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼だね～\nおせちを用意したから\nみんなで食べよっか", 1, 124501, 0, 2, 6947);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もうこんな時間だね～\n一日中着物だったから\n肩が凝っちゃったよ", 1, 124501, 0, 3, 6948);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "このまま寝たら\nしわになるかな？\n着替えた方がいい？", 1, 124501, 0, 0, 6950);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "こういうのって\nラーゴのおもちゃに\nちょうどいいかも♪", 1, 124501, 0, 0, 6951);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りだけど\n着物に移らないように\n気をつけないとね", 1, 124501, 0, 0, 6952);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ちょうどいい\n火加減だね♪\nぽかぽかするよ～♪", 1, 124501, 0, 0, 6953);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "着物の時は\nほどほどにしないと…\n欲張ったら、お腹が\n苦しくなるからね～", 1, 124501, 0, 0, 6955);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふーん\nイノリちゃんは最近\nこんな漫画を\n読んでるんだ～♪", 1, 124501, 0, 0, 6956);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "楽園の気配は…ナシ！\nみんな前を向いてるね\nそうこなくっちゃ！", 1, 124801, 0, 0, 6958);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "レッスンの成果も\nこの格好くらい\n目に見えたら\n分かりやすいのになぁ", 1, 124801, 0, 0, 6959);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "次の曲はワイルドで\n悪い感じもいいなぁ…\nカヤとムイミちゃん\nみたいなイメージで！", 1, 124801, 0, 0, 6960);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "私…服、着てるよね？\nうんうん、着てる！\nあんまり体が軽いと\n急に焦る瞬間あるな～", 1, 124801, 0, 0, 6961);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "最近ファンの年齢層が\n幅広くなってきたかも\nこれって私…国民的\nアイドルに近づいた？", 1, 124801, 0, 0, 6962);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "パティスリーとコラボ\nしたらどんな感じかな\n…ノゾミンマカロン♪\nとか？　…いけるかも", 1, 124801, 0, 0, 6963);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "彼と一緒にいると…\nうれしくって苦しいな\nでも両方諦められない\n…アイドルらしいや", 1, 124801, 0, 0, 6964);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "この格好、チカと\nツムギも似合うと\n思うんだけどな～\nキミもそう思うよね？", 1, 124801, 0, 0, 6965);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "街を歩いてたらね？\nライブとか写真集の\n告知イベントだって\n思われちゃった！", 1, 124801, 0, 0, 6966);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "私が持ってた剣に\n結んであったリボン…\n何か気づいてくれた？\nヒントは…色だよ♪", 1, 124801, 0, 0, 6967);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "キミの気配ってすごく\n分かりやすいんだよ\n近くにいたらすぐに\nピンとくるんだ♪", 1, 124801, 0, 0, 6968);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あ、それ…はじめて\nキミにあげた音響盤！\nね、一緒に聴こうよ", 1, 124801, 0, 0, 6969);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ぼうっとしてたら\nイタズラしちゃうよ♪\nもっともっと私のこと\n見てないとダーメ！", 1, 124801, 0, 0, 6970);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝は今日のはじまり！\n昨日よりももっと\nいい一日にしようね♪", 1, 124801, 0, 1, 6971);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "レッスンがんばったし\nまだお昼だし…\nランチ大盛りにしても\nセーフだよね！", 1, 124801, 0, 2, 6972);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "寝る前に明日の予定を\n確認しておかないと！\nえっと、集合場所は…", 1, 124801, 0, 3, 6973);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "一休みのつもりが\nなが～い休憩になるの\nあるあるだよね～", 1, 124801, 0, 0, 6975);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ノゾミンの熱烈ハグ♪\n…ここだけ聞いたら\nスクープになっちゃう\nかも？　なーんて！", 1, 124801, 0, 0, 6976);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "香りってなんだか\n記憶に残るよねー\n…こういうの私だけ？\nみんなも同じだよね？", 1, 124801, 0, 0, 6977);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "なんだかライブの\n熱気を思い出して\nきちゃった…！\nレッスンしよっと！", 1, 124801, 0, 0, 6978);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "お腹が減ってたら\nいいパフォーマンスは\nできないもんね！\n…んー、おいし～♪", 1, 124801, 0, 0, 6980);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "いい歌詞を書くには\nしっくりくる言葉を\n知っておかないと！", 1, 124801, 0, 0, 6981);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "うだうだ悩んでる\nヤツがいたら\nオレのとこ連れてこい\n背中押してやるからさ", 1, 124901, 0, 0, 6983);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "最近どことなく\nファミリーの連中が\n浮き足立ってんだよな\n…なんでだ？", 1, 124901, 0, 0, 6984);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "イノリのヤツ\nやたらと脇腹\nつついてきやがって…\nくすぐったいっての", 1, 124901, 0, 0, 6985);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "身軽になったのは\nいいが…くそっ\nどこもかしこも\nスースーする…", 1, 124901, 0, 0, 6986);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "思い出に浸るのも\n悪くはないが\nやっぱ人間\n未来に生きないとな！", 1, 124901, 0, 0, 6987);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "またムイミやノゾミと\nツルむのもいいな\nそこにカレもいたら\nなおいいぜ", 1, 124901, 0, 0, 6988);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "未来のことを考えると\nなぜかいつもカレが\n頭に浮かんじまう…\nええい、やめだやめ！", 1, 124901, 0, 0, 6989);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ちょっくらオレと\n腕相撲しねえか？\nこの新しい力\n試させてくれ！", 1, 124901, 0, 0, 6990);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "なあ、悪いが上着\n貸してくれないか？\nこのカッコ、割と\n肌寒いんだよ…", 1, 124901, 0, 0, 6991);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おっ、生まれ変わった\n喧嘩屋にご用命か？\nいいぜ、キミの\n依頼なら二つ返事だ！", 1, 124901, 0, 0, 6992);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "なんか悩みごとが\nあるなら、なんでも\n話してくれよな\nオレとキミの仲だろ？", 1, 124901, 0, 0, 6993);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "このカッコが\nきれいだって？\nや、やめろよ…\n照れくさいだろ…", 1, 124901, 0, 0, 6994);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "キミがいると、なにを\nするにも退屈しないぜ\nだから今日も\n付き合ってくれよな！", 1, 124901, 0, 0, 6995);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう！　新しい\n未来がやってきたぜ！\n一秒だって時間は\n無駄にするなよ？", 1, 124901, 0, 1, 6996);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "そろそろ昼飯に\nしないか？\n穴場のうまい店に\n案内してやるからさ", 1, 124901, 0, 2, 6997);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜更かしは\n未来の前借りだ\n体壊さないように\nほどほどにしとけよ？", 1, 124901, 0, 3, 6998);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "お、いいなこれ\nファミリーの\nアジトにも\n置いときたいぜ", 1, 124901, 0, 0, 7000);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "べ、別にかわいいもん\nなんて、そんなに\n好きじゃないし…\n嫌いでもないけどさ", 1, 124901, 0, 0, 7001);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "嗅いだことない\n香りだな\nなかなか気に入った！", 1, 124901, 0, 0, 7002);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "薄着で暖を取るのって\n最高にぜいたくだよな\nへへっ、堪能させて\nもらうとするか", 1, 124901, 0, 0, 7003);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "こいつはいいや\nこのカッコだと\n消耗が激しくて\nやたら腹が減るからな", 1, 124901, 0, 0, 7005);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "甘辛コーデ…\nへぇ、そんなのが\nあるのか…\nわ、悪くねえかもな", 1, 124901, 0, 0, 7006);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "はぁ…\nもっともっと長い時間\n先輩と過ごせたらなぁ", 1, 105501, 0, 0, 7008);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "えへへ…♪\n先輩が、すぐそばに\nいてくれるなんて…\n幸せだなぁ…♪", 1, 105501, 0, 0, 7009);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "はーっはっは！\n強くてカッコいい\n大悪党、ここに参上！", 1, 125001, 0, 0, 7010);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "みんなおしゃれで\nカッコいいけど\n今のアタシも\n負けてないぞ！", 1, 125001, 0, 0, 7011);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ギャングのアジトも\nよかったけど\nここも賑やかで\n悪くないな！", 1, 125001, 0, 0, 7012);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "悪党にも休息は必要だ\nここならゆっくり\n休めそうだ！\n邪魔するぞ！", 1, 125001, 0, 0, 7013);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "いっぱい人がいるな…\nアタシの悪党っぷりを\n広めるチャンスだ！", 1, 125001, 0, 0, 7014);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ここにいれば\nいい思い出がたくさん\n作れそうだな！", 1, 125001, 0, 0, 7015);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "いつかアタシも\nオクトーと一緒に\nこんなアジトを手に\n入れてやるからな！", 1, 125001, 0, 0, 7016);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ん？　アタシの格好が\n気になるのか？\nならもっと近くで\n見てもいいぞ！", 1, 125001, 0, 0, 7017);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おい、暇だから\nアタシと遊べ！\nカヤとノゾミも呼んで\n大騒ぎするぞ！", 1, 125001, 0, 0, 7018);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "オマエ、前より強く\nなってないか！？\nくっそー！　アタシも\n負けてらんないぞー！", 1, 125001, 0, 0, 7019);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "今日は特別にアタシの\n思い出話を聞かせて\nやる！　さーて、どの\n悪事から話そうか…", 1, 125001, 0, 0, 7020);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "オマエとの付き合いも\n結構長くなったよな？\nこれからも\nよろしく頼むぞ！", 1, 125001, 0, 0, 7021);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "オマエまでいなく\nなったらアタシが困る\n勝手にどっか\n行くんじゃないぞ！", 1, 125001, 0, 0, 7022);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "起きろ、起きろー！\n大悪党の朝は早いんだ\nさっさと\n顔洗ってこい！", 1, 125001, 0, 1, 7023);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼飯どうしようか…\nそうだ！　オマエの\nおススメに連れてけ！\nいい店期待してるぞ！", 1, 125001, 0, 2, 7024);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "明日を思い切り\n楽しむためにも\n早く寝とけよ！\nまた明日な！", 1, 125001, 0, 3, 7025);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "こうやって座ると…\nおお！　すっごく悪党\nっぽいぞ！", 1, 125001, 0, 0, 7027);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "オマエ、仲間に\nなりたそうな目を\nしてるな！", 1, 125001, 0, 0, 7028);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "うん、いい匂いだ！\n何の匂いかは全然\n分かんないけどな！", 1, 125001, 0, 0, 7029);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "炎ってなんだか\nカッコいいよな！\n見てるだけで心が\n燃えてくるぞ！", 1, 125001, 0, 0, 7030);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いっぱい食べれば\nちょっとは\n背が伸びるかな…？", 1, 125001, 0, 0, 7032);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ぐぬぅ…たまには\n本でもと思ったけど\nやっぱりアタシは\nバトル担当だな！", 1, 125001, 0, 0, 7033);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "お邪魔しまーす★\nなーんてもう\nすっかりくつろいで\nますけどー♪", 1, 118201, 0, 0, 7035);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "騎士さんの\nギルドハウス…★\nなんだかドキドキ\nしちゃいます♪", 1, 118201, 0, 0, 7036);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ぺんぽこりんの\n置き場所はー…\nま、このへんで★", 1, 118201, 0, 0, 7037);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "うーん、これは\n壊しがいがありそ…\nウソウソ、冗談です★", 1, 118201, 0, 0, 7038);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "オトモダチでも\n作ってみますかー\nくすっ★", 1, 118201, 0, 0, 7039);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "退屈ですねー\n騎士さん、構って\nくれないかなー", 1, 118201, 0, 0, 7040);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "もっともっと早く\n騎士さんに逢えてたら\n…なんて、わたし\nらしくないですね", 1, 118201, 0, 0, 7041);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "わたし一人にするの\n不安だったりします？\nちゃーんとイイコに\nしてますってー★", 1, 118201, 0, 0, 7042);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お出かけします？\nそれともおうちで\nまったりしますー？", 1, 118201, 0, 0, 7043);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "女の子をすぐ家に\nあげちゃうなんて…\nふふ、やっぱり隅に\n置けないですねー★", 1, 118201, 0, 0, 7044);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "騎士さん騎士さーん★\nウザ絡みしても\nいいですかー？\n騎士さんってばー★", 1, 118201, 0, 0, 7045);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "一緒にゴロゴロ\nしませんかー？\nコイビトっぽくて\n楽しそうですし♪", 1, 118201, 0, 0, 7046);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "うふふ★\nこーやってあなたに\n優しくされると…\nときめいちゃいます♪", 1, 118201, 0, 0, 7047);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます★\nあれれー？\nまだおねむですかー？", 1, 118201, 0, 1, 7048);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "騎士さん、お昼は\nもう食べましたー？\nわたし、ラーメンが\n食べたいでーす★", 1, 118201, 0, 2, 7049);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あ、夜更かししてちゃ\nダメですよー？\nほらほら、お布団に\nごーごー★", 1, 118201, 0, 3, 7050);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふかふかのふわふわー\nついついまーったり\nしちゃいます★", 1, 118201, 0, 0, 7052);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かっわいー★\n名前はー、んー…\nぱんぱかぷんで★", 1, 118201, 0, 0, 7053);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "くんくん★\nうーん…\nたぶん素敵な香り♪", 1, 118201, 0, 0, 7054);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかーい★\n心も体も\nぽっかぽかですねー★", 1, 118201, 0, 0, 7055);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ★\nんー、おいしくって\n止まらないですねー★", 1, 118201, 0, 0, 7057);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "へー★\nほほー★\nふんふーん★", 1, 118201, 0, 0, 7058);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "さ～て時間もあるし\nラテアートの練習でも\nするかにゃ～♪", 1, 125101, 0, 0, 7060);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "カフェの猫たちも\n元気に働いてくれて\nお客さんからの評判も\n上々にゃ～♪", 1, 125101, 0, 0, 7061);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "カフェのカウンターに\nファントムキャッツの\n目安箱を置こうかにゃ", 1, 125101, 0, 0, 7062);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "あんこもコーヒーも\n原料は豆にゃ～\nそりゃ相性いいに\n決まってるにゃ♪", 1, 125101, 0, 0, 7063);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "あいつの為に\nタマキ特製ブレンドを\n開発したいにゃ♪", 1, 125101, 0, 0, 7064);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あいつと働いてると\nなぜかあっという間に\n閉店時間が\n来ちゃうのにゃ～", 1, 125101, 0, 0, 7065);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あいつといると\n新しいアイデアが\n溢れるほど\n出てきちゃうのにゃ♪", 1, 125101, 0, 0, 7066);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "キミがコーヒーを\n淹れてくれたのにゃ？\nにゃはは、常温で\n猫舌にも優しいにゃ♪", 1, 125101, 0, 0, 7067);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "料理が上手くなったら\nカフェご飯メニューも\n充実させたいにゃ～", 1, 125101, 0, 0, 7068);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お店の経営は大変\nだけど、キミとなら\n乗り越えられるって\n確信してるにゃ！", 1, 125101, 0, 0, 7069);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ん？　この制服\n似合ってるにゃ？\nにゃはは！　褒めても\n１ルピも出ないにゃ♪", 1, 125101, 0, 0, 7070);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あたしが好きなのは\n猫に好かれる人にゃ♪\n…ん、キミ猫に懐かれ\nまくってるにゃ…", 1, 125101, 0, 0, 7071);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "キミの制服姿\nけっこーイケてるにゃ\nあたしがお客さんなら\n通いつめちゃうにゃ♪", 1, 125101, 0, 0, 7072);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝は一杯の\nコーヒーから始まる…\nにゃふふん♪\nシャレた朝だにゃ～♪", 1, 125101, 0, 1, 7073);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼はたい焼きと\nコーヒーのセットで\nまったり休憩\nしようにゃ～♪", 1, 125101, 0, 2, 7074);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "コーヒー淹れたにゃ\n星空を見ながら\n二人で飲もうにゃ…♪", 1, 125101, 0, 3, 7075);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふにゃ～ん…ゴロゴロ\nコーヒーと同じくらい\n癒されるにゃ～…♪", 1, 125101, 0, 0, 7077);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "こいつかわいいにゃ～\nうちの猫たちとも\nいい勝負なのにゃ！", 1, 125101, 0, 0, 7078);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ん～いい香りだにゃ～\nコーヒーもそうだけど\n香りの癒し効果は\n抜群にゃ～♪", 1, 125101, 0, 0, 7079);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "猫に暖かいものは\nまるまれと言ってる\nようなもんにゃ…♪\nまるまる…", 1, 125101, 0, 0, 7080);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "にゃは～うまいにゃ♪\nカフェの新メニューに\n採用しちゃおう\nかにゃ～♪", 1, 125101, 0, 0, 7082);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "にゃるほど…\n調べれば調べるほど\nコーヒーは\n奥が深いのにゃ…", 1, 125101, 0, 0, 7083);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "ワタシの手料理は\n坊やの口に合うらしい\n胃袋は討ち取ったぞ♪", 1, 107101, 0, 0, 7085);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "胸に再度触れると\n誓約は無効になるのか\n…だと？　鋭い質問だ\n安心しろ。ならん☆", 1, 107101, 0, 0, 7086);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ようやくこの服にも\n慣れてきたかな？\nふふっ、たまには\nこういう服も悪くない", 1, 125201, 0, 0, 7087);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "今日も店は好調だが、\n私は軍人だからな\n当初の目的も\n忘れないようにしよう", 1, 125201, 0, 0, 7088);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "猫が近くに来ると\nついつい見てしまうな\n仕事が終わったら\n遊んでやるかな♪", 1, 125201, 0, 0, 7089);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "コーヒーの淹れ方が\nうまくなってきたな♪\nどうせならお菓子も\n研究してみるか！", 1, 125201, 0, 0, 7090);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "利益を考えると\n価格をあげるべきか？\n…いや、利益よりも\n皆の笑顔の方が大事だ", 1, 125201, 0, 0, 7091);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "またあいつを\n呼んでしまったな…\n今度、コーヒーでも\n淹れて労ってやるか♪", 1, 125201, 0, 0, 7092);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "次に入荷するお菓子は\nあいつの意見を聞くか\nどんな味が好きか\n気になるしな", 1, 125201, 0, 0, 7093);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "なに、コーヒーを\n淹れてほしい？\nふふっ♪\n仕方のない奴だな！", 1, 125201, 0, 0, 7094);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "…そうだ。\nコーヒーと乾パンは\n合うのではないか？\n今度試してみよう！", 1, 125201, 0, 0, 7095);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "コーヒーもいいが、\nココアも悪くないぞ♪\n貴公も一緒にどうだ？", 1, 125201, 0, 0, 7096);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "魔法少女に比べれば\n大人しい服だろう？\nだが、カフェには\nこの服でバッチリだ！", 1, 125201, 0, 0, 7097);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "貴公はコーヒーを\n飲めるのかっ？それは\nうらやましいな…", 1, 125201, 0, 0, 7098);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "貴公の働きぶりには\n目を見張るものがある\nその姿は、その…\n結構かっこいいぞっ！", 1, 125201, 0, 0, 7099);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "さぁ、今日も一日、\n頑張るぞっ！\n気合いを入れて\n開店準備だっ！", 1, 125201, 0, 1, 7100);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼は稼ぎ時だからな！\n荒波を乗り切るため\n貴公も一緒に\n頑張ってくれるか？", 1, 125201, 0, 2, 7101);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふあぁ…もう夜か\n今日は頑張ったからな\nはやめに休むとしよう", 1, 125201, 0, 3, 7102);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "はふぅ～…\nたまにはこうして\nゆったりするのも\n悪くないな…", 1, 125201, 0, 0, 7104);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "猫もかわいいが、\nこいつもなかなか…\n見ていると、\n撫でたくなるな♪", 1, 125201, 0, 0, 7105);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "これは良い香りだな\nふむ、コーヒーも\nより香り高いものが\n作れるよう試すか！", 1, 125201, 0, 0, 7106);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ふぅ～…\n体を温めなければ、\nすぐに動けないからな", 1, 125201, 0, 0, 7107);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "これもうまいが、\n私はお菓子も…\nいや、食べすぎは\n体に良くないな", 1, 125201, 0, 0, 7109);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "…書物は参考になるな\n次はこのやり方を\n試してみるかな", 1, 125201, 0, 0, 7110);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "愛と希望の魔法少女！\n弟くんの平和は\nお姉ちゃんが守るよ♪", 1, 120001, 0, 0, 7112);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "魔法少女の戦い方を\n見せてあげる！\nお姉ちゃんチョップ♪", 1, 120001, 0, 0, 7113);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "闇の力が高まってる…\n早く弟くんを\nギュ～ってしないと！", 1, 120001, 0, 0, 7114);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ミニ弟くんを\n部屋中に呼び出して\n弟くんハウスに～♪", 1, 120001, 0, 0, 7115);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "決めポーズの練習でも\nしよっかな…\nはい、ポーズ♪", 1, 120001, 0, 0, 7116);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "魔法少女の力で\n弟くんのそばに\n瞬間移動したいなぁ", 1, 120001, 0, 0, 7117);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "禁じられた必殺技\nその名も──\n闇のお姉ちゃん頭突き", 1, 120001, 0, 0, 7118);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "魔法少女な\nお姉ちゃんに\n興味津々だねっ？\n全部教えてあげるね♪", 1, 120001, 0, 0, 7119);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "闇のお姉ちゃんとして\n世界を弟くんのものに\n…な～んて冗談冗談♪", 1, 120001, 0, 0, 7120);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "弟くんって魔法少女に\nなりたがってたよね？\n…うん。応援するね！", 1, 120001, 0, 0, 7121);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "サインが欲しいの？\nふふっ、任せて！\n愛する弟くんへ、と♪", 1, 120001, 0, 0, 7122);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ふんふふ～ん♪\n魔法少女お姉ちゃんの\nテーマソング完成っ♪", 1, 120001, 0, 0, 7123);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "えへへ、弟くんからの\n愛と希望を感じるよ…\n更に変身しちゃうぞ♪", 1, 120001, 0, 0, 7124);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "弟くんの朝を魔法で\n守りに来たよ！\n希望の朝だねっ♪", 1, 120001, 0, 1, 7125);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "弟くんのお昼を魔法で\n守りに来たよ！\n愛のお弁当をどうぞ♪", 1, 120001, 0, 2, 7126);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "弟くんの夜を魔法で\n守りに来たよ！\nここからは闇の時間♪", 1, 120001, 0, 3, 7127);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "魔法少女の一休み♪\n愛と希望と…闇の力が\n回復していくね～♪", 1, 120001, 0, 0, 7129);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいかわいい♪\nお姉ちゃんの魔法で\n増やしちゃうぞ…♪", 1, 120001, 0, 0, 7130);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この香り…\n弟くんと同じ…\nくんくん、くんくん…", 1, 120001, 0, 0, 7131);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "体を温めておいて…\nこの熱を、ぜ～んぶ\n弟くんに伝えるよ…！", 1, 120001, 0, 0, 7132);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ミニ弟くんを呼ぶには\nいっぱい食べないと…\n魔法ってお腹減るから", 1, 120001, 0, 0, 7134);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "弟くんの平和を守る…\nそのためには\nチェックチェック…♪", 1, 120001, 0, 0, 7135);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この服も、最初は\n慣れなかったのですが\n今ではすっかり\n体に馴染んでおります", 1, 125301, 0, 0, 7137);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "自然を守るためにも\nお勉強は欠かせません\n日々精進でございます", 1, 125301, 0, 0, 7138);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "採取した薬草を\n調合しておきましょう\nいつ必要になるか\n分かりませんからね", 1, 125301, 0, 0, 7139);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "合宿は過酷でしたが\nおかげでちょっと\n力持ちになったような\n気がいたします…♪", 1, 125301, 0, 0, 7140);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "わんわんのほうの\n主さまに、ごはんを\nあげる時間ですね…", 1, 125301, 0, 0, 7141);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "もっともっと訓練や\nお勉強を重ねて\n主さまのお役に\n立たなくては…", 1, 125301, 0, 0, 7142);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "おや、そろそろ\nわんわんのほうの\n主さまをお散歩に\n連れていく時間です", 1, 125301, 0, 0, 7143);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "主さま、よろしければ\nお散歩に行きませんか\n今日の森は穏やかで\n過ごしやすいかと", 1, 125301, 0, 0, 7144);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "わんわんのほうの\n主さまも、今では\n【美食殿】の大切な\n仲間でございます", 1, 125301, 0, 0, 7145);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "森には危険が\nいっぱいでございます\nケガをなさらないよう\nお気をつけください", 1, 125301, 0, 0, 7146);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "もし森や動物のことで\n気になることがあれば\n気軽にお尋ねください", 1, 125301, 0, 0, 7147);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "森へ行く前には\n必ず装備の点検を\nお願いいたします\n約束ですよ、主さま？", 1, 125301, 0, 0, 7148);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "森の中で主さまたちと\nゆったり過ごす時間は\nわたくしにとって\n大切なひとときです", 1, 125301, 0, 0, 7149);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\n朝ごはんをしっかり\n食べて、お勤めに\n備えましょう", 1, 125301, 0, 1, 7150);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "わんわんのほうの\n主さまにおやつを\nあげる時間です\nどうぞ、召し上がれ", 1, 125301, 0, 2, 7151);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "どれだけ野営に\n慣れたとしても\nベッドで眠れるなら\nそうしたいところです", 1, 125301, 0, 3, 7152);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "こちらなのですが\nわんわんのほうの\n主さまもお気に入りの\nようです", 1, 125301, 0, 0, 7154);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "わんわんのほうの\n主さまにも、こうした\n玩具を与えるべき\nでしょうか…？", 1, 125301, 0, 0, 7155);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "心地よい香りです\n次は、自然由来の\n香料も試しましょう", 1, 125301, 0, 0, 7156);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "暖をとるのは\n野営の時などに\nとても大事なことで\nございますね", 1, 125301, 0, 0, 7157);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食べられる時に食べて\nおくのも、大自然では\n重要でございます", 1, 125301, 0, 0, 7159);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "より知識を蓄え\n自然の力を活用できる\nようにいたしましょう", 1, 125301, 0, 0, 7160);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "今回の「冥風戦記」も\nなかなかよく書けたぞ\nふふっ、シグルドも\n喜んでくれるかな？", 1, 100901, 0, 0, 7162);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "貴様のためならば\n我が真なる魔力\nいつでも\n解き放とうぞ！", 1, 100901, 0, 0, 7163);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ニャットちゃんに\nブラッシングを\nしてあげようかな", 1, 125401, 0, 0, 7164);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ふふ…\nこれがレンジャーの\n制服ですか", 1, 125401, 0, 0, 7165);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "そろそろ\nパトロールの\n時間だ…", 1, 125401, 0, 0, 7166);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "魔物について\nもっと知りたいな\n本を探しに行こう", 1, 125401, 0, 0, 7167);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "レンジャーになって\n体調を崩す日が\n減った気がします…", 1, 125401, 0, 0, 7168);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "本だけじゃわからない\n世界のことを、\nもっと知りたいです…", 1, 125401, 0, 0, 7169);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "こんな私にも\nできることはある…\nそう信じています", 1, 125401, 0, 0, 7170);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あの…良かったら\n一緒に見回りへ\n行きませんか？", 1, 125401, 0, 0, 7171);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "またあなたと一緒に\nレンジャーの仕事が\nできたらうれしいです", 1, 125401, 0, 0, 7172);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "けほっこほっ\n…だ、大丈夫です\nたまに出るだけなので", 1, 125401, 0, 0, 7173);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ニャットちゃん\nあなたにも\n懐いてきましたね", 1, 125401, 0, 0, 7174);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ニャットちゃんと\n散歩に出かけようかな\n…あの人も誘って", 1, 125401, 0, 0, 7175);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あなたと肩を並べて\nレンジャーの仕事が\nできてうれしいです…", 1, 125401, 0, 0, 7176);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\nレンジャー・シオリ\n元気に出勤します", 1, 125401, 0, 1, 7177);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ニャットちゃんにも\nお昼ごはんを\n用意しなくちゃ", 1, 125401, 0, 2, 7178);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "明日は仕事だから\n早起きしなくちゃ\nおやすみなさい", 1, 125401, 0, 3, 7179);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふぅ…仕事で\n走り回ったので\n少し休憩します", 1, 125401, 0, 0, 7181);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "仕事が終わった後に\nこうして触れていると\n癒されますね…", 1, 125401, 0, 0, 7182);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "森の香りがします…\n今日はよく\n眠れそうです…", 1, 125401, 0, 0, 7183);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ニャットちゃんと\n同じぐらい\n暖かいです…", 1, 125401, 0, 0, 7184);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "レンジャーの仕事を\nしていると\nお腹が空きます", 1, 125401, 0, 0, 7186);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "どんなに忙しくても\n読書だけは\nやめられませんね", 1, 125401, 0, 0, 7187);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "兄様のお留守の間\nわたくしが、兄様の\n御家を守ります！", 1, 125801, 0, 0, 7189);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "に、に、兄様の御家…\n招待いただいた以上は\n失礼のないよう\n振る舞わなくては…！", 1, 125801, 0, 0, 7190);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ふふっ…兄様の素敵な\nお人柄が、家中から\nにじみ出ています…♪", 1, 125801, 0, 0, 7191);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "靴を脱がずに\n御家に上がるのに\n慣れていなくて…あ！\n飛べばいいのでは…！", 1, 125801, 0, 0, 7192);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ここに花を生けたら\n華やぎそうですね\n兄様はお花…\n好きでしょうか…？", 1, 125801, 0, 0, 7193);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ずっとここにいたい…\nなどと言ったら\n兄様を困らせて\nしまいますよね…", 1, 125801, 0, 0, 7194);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "お料理などを作って\n兄様を出迎えられたら\nいいのに…料理の腕も\n磨かなくては…！", 1, 125801, 0, 0, 7195);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "このような姿で\n失礼しております…！\nネ、ネズミがいたので\nつい本気を…！", 1, 125801, 0, 0, 7196);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おかえりなさいませ\nお忙しい御身をどうぞ\n癒してくださいね", 1, 125801, 0, 0, 7197);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "兄様の話し相手…！？\nど、どうしましょう…\nわたくしには面白い\n話なんて…はうぅ…！", 1, 125801, 0, 0, 7198);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "なぜか、動物などに\n好かれる体質で…\n迷い猫捜しのバイトの\nお役に立てますか？", 1, 125801, 0, 0, 7199);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "に、兄様の家に来たら\n『添い寝』をするのが\n礼儀とリアさんが…\n本当…でしょうか？", 1, 125801, 0, 0, 7200);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "わたくしはここに\nいて…よいのですね？\n『仲間』として…", 1, 125801, 0, 0, 7201);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝は得意なんです\nもし兄様が苦手なら\nわたくしが起こして\n差し上げますよ", 1, 125801, 0, 1, 7202);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "兄様…昼餉を作って\nみたのですが、失敗\nしてしまいました…", 1, 125801, 0, 2, 7203);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふあぁ…\nはっ！　お…\nお恥ずかしい所を…！", 1, 125801, 0, 3, 7204);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "こ、これは…！\n人様の御家なのに\nつい…駄目になって…\nしまいますぅ…！", 1, 125801, 0, 0, 7206);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "と、飛びかかっては\nこない…ですよね…？", 1, 125801, 0, 0, 7207);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "すぅ…はぁ…\nこのかぐわしさ\n心が洗われます…", 1, 125801, 0, 0, 7208);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "なんて暖かい…\n兄様の優しくお広い\n御心のようです…♪", 1, 125801, 0, 0, 7209);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "こんなに食べていたら\nはしたない…\nでしょうか？", 1, 125801, 0, 0, 7211);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "兄様の本棚はまるで\n知識の宝庫ですね\n己の世間知らずぶりを\n実感してしまいます", 1, 125801, 0, 0, 7212);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "次の冒険に向けて\n騎空士弁当を作ろっと\nまずはおにぎりから！", 1, 125501, 0, 0, 7214);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "魔法の修行しなくちゃ\nもっともっと頼れる\n団長になりたいから！", 1, 125501, 0, 0, 7215);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ビカラちゃんを\n遊びに誘いたいけど…\nどういう場所が\n好きなんだろう？", 1, 125501, 0, 0, 7216);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "仕事を真面目に\nしっかりこなすことが\n騎空艇への\n一番の近道だよね", 1, 125501, 0, 0, 7217);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ここにいる人の中で\n騎空団に興味ある人\nいたりしないかな…？", 1, 125501, 0, 0, 7218);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "これまでも想い出は\nいっぱいできたけど…\nこれからもたくさん\n想い出を作りたいな！", 1, 125501, 0, 0, 7219);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "仲間がいるから\n騎空士は限界だって\n超えられるんだね", 1, 125501, 0, 0, 7220);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "この衣装\n魔法使いらしいでしょ\n服に着られないよう\n頑張らなくちゃね！", 1, 125501, 0, 0, 7221);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あなたとなら\nどんな相手だって\n怖くなんてないよ！", 1, 125501, 0, 0, 7222);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "カリンさんから\n新しい依頼が来たよ！\n一緒に頑張ろ！", 1, 125501, 0, 0, 7223);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "操舵士になるのは\nずいぶん難しそう…\nいつか頼れる仲間が\n見つかるといいな", 1, 125501, 0, 0, 7224);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "手合わせしたいの？\nいいよ、たまには\n団長らしいところ\n見せてあげるね！", 1, 125501, 0, 0, 7225);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "まだ二人きりだけど…\nこの騎空団は\n私の宝物だよ！", 1, 125501, 0, 0, 7226);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう～…\n昨日は遅くまで\n魔法の研究してて…\nふわぁ…眠いなぁ…", 1, 125501, 0, 1, 7227);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "さてと、お昼休み！\n紅茶淹れてくるから\n一緒に飲もうよ！", 1, 125501, 0, 2, 7228);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "遅くまでお疲れさま！\n無理しない程度に\nお互い頑張ろう！", 1, 125501, 0, 3, 7229);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "魔法の研究は\n一旦、休憩！\n頭を休めなくちゃ", 1, 125501, 0, 0, 7231);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "魔法みたいに\nかわいい！\n騎空団に入る？\nなんてね！", 1, 125501, 0, 0, 7232);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい匂い…\nそれになんだか\n集中力が増したかも", 1, 125501, 0, 0, 7233);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "体だけじゃなくて\n心までポカポカする…\nなんだか魔法みたい", 1, 125501, 0, 0, 7234);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いろいろ考え事したら\nお腹が空いちゃった！\nいただきまーす！", 1, 125501, 0, 0, 7236);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "『摂理の彼方へ\n至るには…』\n…この魔導書\n勉強になるなあ", 1, 125501, 0, 0, 7237);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "こちらの服を着ると\n冒険に出かけたく\nなっちゃいますね", 1, 125701, 0, 0, 7239);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "冒険者の心得その一\n準備はできる限り\nしっかりとこなすべし\nなんてどうでしょう？", 1, 125701, 0, 0, 7240);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "調合に必要な素材は\nあれとこれとそれと…\n時間があるとついつい\n考えちゃいますね", 1, 125701, 0, 0, 7241);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "せっかくですから\nより良い素材を\n自分で集めたいですね", 1, 125701, 0, 0, 7242);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "このポーションが\nみなさんの役に立つと\nうれしいですね", 1, 125701, 0, 0, 7243);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "冒険者の心得その二\n危なくなった時は\nまず逃げるべし！\n大事なことですね", 1, 125701, 0, 0, 7244);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あの人の冒険は\nいつも楽しそうで\n元気がもらえます", 1, 125701, 0, 0, 7245);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ぜひおすすめしたい\n依頼があるんです\nこちらをどうぞ♪", 1, 125701, 0, 0, 7246);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ほしいお薬があれば\n錬金術で作って\nさしあげますよ", 1, 125701, 0, 0, 7247);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "依頼で気になる\nところがあれば\n何でもご確認ください", 1, 125701, 0, 0, 7248);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "このギルドハウスに\n錬金術の実験設備を…\nえ？　だめですか？", 1, 125701, 0, 0, 7249);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ポーションをどうぞ\n大丈夫、効果は\n確認済みですので♪", 1, 125701, 0, 0, 7250);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "次はどんな冒険に\n行かれるんですか？\nいつでもお供しますよ", 1, 125701, 0, 0, 7251);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日もいい一日に\nなりそうですね\n冒険日和といった\nところでしょうか", 1, 125701, 0, 1, 7252);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "いい時間ですし\nランチにしませんか？\n次の冒険の\n作戦会議も兼ねて♪", 1, 125701, 0, 2, 7253);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜も遅いですし\n明日の冒険のため\n今日は早く寝ましょう", 1, 125701, 0, 3, 7254);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふう…やはり冒険は\n事務仕事と違いますね\n少し休憩を…", 1, 125701, 0, 0, 7256);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "冒険は緊張の連続です\nかわいい物で\n心を癒しましょう", 1, 125701, 0, 0, 7257);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ふむ、この香りは…\n素晴らしいバランスで\n調合されていますね", 1, 125701, 0, 0, 7258);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "この火力…\n錬金術の調合に\n使えそうですね", 1, 125701, 0, 0, 7259);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "冒険の際は食べられる\n時に食べておく！\n…とペコリーヌさんも\nおっしゃってましたね", 1, 125701, 0, 0, 7261);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ…なるほど\nこんな調合も\nあるのですね…\n奥が深いです", 1, 125701, 0, 0, 7262);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "アイツどこ行った…？\n戦うならアタシも\n連れてけよなー！", 1, 106101, 0, 0, 7264);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "今日も悪いヤツ退治…\nの前に腹ごしらえだ！\nなんか食べに行くぞ！", 1, 106101, 0, 0, 7265);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "みんなー！\nギルドハウスで\nぼくと握手！", 1, 125601, 0, 0, 7266);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "種族も年齢も違うけど\nみんな楽しそうだね！\nやっぱりここはぼくの\nゆ～とぴあさ！", 1, 125601, 0, 0, 7267);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ハハッ！　まるで\nパーティー会場だね！\nこれは楽しませがいが\nあるってものだよ！", 1, 125601, 0, 0, 7268);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "やぁみんな！\nご利益満点のネズ耳は\nいかがかな？\nひとつ３ルピだよ！", 1, 125601, 0, 0, 7269);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ここにいれば\n遊び相手に困らないね\nかしこみかしこみ～！", 1, 125601, 0, 0, 7270);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "どこか遊びに\n行こうかな♪\nそうだ、あの人にも\n声をかけてみよう！", 1, 125601, 0, 0, 7271);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あの人といると\nぼくまで楽しくなって\nくるんだよね！\n毎日パレード気分さ！", 1, 125601, 0, 0, 7272);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ネズ耳の在庫が\n切れたんだ！\n作るのを\n手伝ってくれるかい？", 1, 125601, 0, 0, 7273);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ん？　握手かい？\nいいとも！\nいつでも何度でも\nしてあげるよ！", 1, 125601, 0, 0, 7274);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "この衣装に興味が\nあるのかい？\nきみ、なかなか\n見る目があるね！", 1, 125601, 0, 0, 7275);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "しばらくここに厄介に\nなるつもりなんだ\nあとで街を案内\nしてくれるかい？", 1, 125601, 0, 0, 7276);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "とっておきのチーズ\nきみと半分こだ！\nみんなには内緒だよ？", 1, 125601, 0, 0, 7277);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "きみはいてほしい時に\nいつもそばに\nいてくれるね\n本当にかしこみだよ！", 1, 125601, 0, 0, 7278);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "やぁ、おはよう！\n気持ちのいい朝だね\n今日も楽しくネズ耳\n売りにはげもうか！", 1, 125601, 0, 1, 7279);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼だね！\nおいしいチーズを\n持ってきたから\nぼくと半分こだ！", 1, 125601, 0, 2, 7280);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日も一日\n楽しかったね！\nいい夢が見られること\n間違いなしさ！", 1, 125601, 0, 3, 7281);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ぼくにも休息は\n必要さ！\nリラックス〜\nリラックス〜♪", 1, 125601, 0, 0, 7283);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ぼくのぬいぐるみも\n作って売ろうかな…\n修繕費も一気に\n集まるかもね！", 1, 125601, 0, 0, 7284);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りだね！\nトーゴクのお香に\nよく似てるよ", 1, 125601, 0, 0, 7285);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "はぁ…温まるねぇ…\nそうだ、この火で\nチーズでも炙って\nみようかな", 1, 125601, 0, 0, 7286);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "うーん、この味…\nトーゴクを思い出すよ\nどれ、もう一つ\nいただこうか！", 1, 125601, 0, 0, 7288);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "これはランドソルの\nガイド本だね！\nありがたく参考に\nさせてもらうよ！", 1, 125601, 0, 0, 7289);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "まさか、わらわが\nこのような装束を\n纏う日がくるとはな…\n感慨深いものじゃ", 1, 126201, 0, 0, 7291);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "わらわの美貌で\nこのギルドハウスも\nより華やかに\nなったようじゃな", 1, 126201, 0, 0, 7292);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "つまらぬ戦いで\n晴れ着を汚しとうない\n今日は一日\nゆっくりするかの", 1, 126201, 0, 0, 7293);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "今日はわらわが食事の\n準備をして、あやつの\n帰りを待ってやろう\n献立は何がよいかの…", 1, 126201, 0, 0, 7294);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ユキといったか…\n掴みどころのない\nやつじゃが、根性は\n認めてやるかの", 1, 126201, 0, 0, 7295);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "こうして、仲間と\nのんびり過ごす時間も\n悪くないのう♪", 1, 126201, 0, 0, 7296);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あやつを誘って\n月を見に行こうかの\n夜が楽しみじゃ♪", 1, 126201, 0, 0, 7297);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "いかなる衣装で\nあろうとも、わらわは\n完璧に着こなして\nしまうのじゃ♪", 1, 126201, 0, 0, 7298);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "なんじゃ？\nわらわの姿に\n見惚れておったとな？\nす、素直でよいのじゃ", 1, 126201, 0, 0, 7299);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "吸血鬼であるわらわに\n相応しい装束じゃろう\nあとは真っ赤な血を\n添えたいのう…", 1, 126201, 0, 0, 7300);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お主、疲れておるな？\nわらわが癒してやろう\nほれ、近う寄るのじゃ", 1, 126201, 0, 0, 7301);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お主がおるだけで\nギルドハウスが\n賑やかになるのう\nある種の才能じゃな♪", 1, 126201, 0, 0, 7302);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "眷属よ、風呂にするか\nご飯にするか\nそれとも、わらわに…\nいや、忘れるのじゃ", 1, 126201, 0, 0, 7303);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝一番、わらわに\n会いたかったとな…\n眷属よ\n褒めてつかわすぞ♪", 1, 126201, 0, 1, 7304);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "眷属よ、わらわが\n食事を用意したぞ\n忌々しい太陽に負けず\n頑張るのじゃ", 1, 126201, 0, 2, 7305);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "眠るには惜しい夜じゃ\n眷属よ、もうしばらく\nわらわの傍に\nおるがよい", 1, 126201, 0, 3, 7306);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふかふかじゃの♪\n今度あやつにも\n座らせてやろう", 1, 126201, 0, 0, 7308);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "愛いやつじゃ\n少しばかり、わらわが\n遊んでやろうかの", 1, 126201, 0, 0, 7309);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "気品ある香りじゃのう\nわらわの古城にも\n一つ欲しいところじゃ", 1, 126201, 0, 0, 7310);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "よいぬくもりじゃ…\n忌々しい太陽とは\n大違いじゃの", 1, 126201, 0, 0, 7311);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "味付けの参考に\nあと、もう一つだけ…\n止まらんのじゃ…", 1, 126201, 0, 0, 7313);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "吸血鬼の弱点について\n記されておるのか…\nふむ、眠気が\nさめてしもうたぞ", 1, 126201, 0, 0, 7314);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "このままボクが美しく\nなり続けても、彼なら\nきっと隣にいてくれる\nはずだよね！", 1, 100801, 0, 0, 7316);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "もっとそばに来なよ\nボクの隣は\nキミのための\n特等席なんだから", 1, 100801, 0, 0, 7317);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ドレスの影響かな…\n前より黒や赤が\n好きになったかも", 1, 126301, 0, 0, 7318);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ボクがいるだけで\nここがぐんっと\n華やかになったね♪", 1, 126301, 0, 0, 7319);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ボクを描いた絵画\n今度持ってきて\n飾ってあげようかな", 1, 126301, 0, 0, 7320);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ボクはボクに\n魅了されっぱなしさ♪\nまさに魔性の存在だよ", 1, 126301, 0, 0, 7321);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "美のアドバイスを\n聞きたい人いるかい？\nボクがもっともっと\n輝かせてあげるよ♪", 1, 126301, 0, 0, 7322);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あの人、今度はボクを\nどう褒めるだろう？\nもし語彙が尽きても\n許してあげよっと♪", 1, 126301, 0, 0, 7323);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あの人に似合うコーデ\n考えてあげよっと\n案外、なんでも\n着こなしそうだよね♪", 1, 126301, 0, 0, 7324);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "吸血鬼になるなんて\nやっぱりゴメンだね！\n永遠の美よりも\n大事なことがあるのさ", 1, 126301, 0, 0, 7325);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お肌にいいものは\n大体好きだよ\nトマトジュースとかね", 1, 126301, 0, 0, 7326);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "銀のアクセサリーが\nボクは大好きでね\nいつでもプレゼント\n待ってるよ♪", 1, 126301, 0, 0, 7327);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "イリヤみたいにお城に\n住んでみたいんだ♪\n美を統べる者に\n相応しいでしょ？", 1, 126301, 0, 0, 7328);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "今のボクがカップを\n触ると壊しちゃうんだ\nだからほら、キミが\nボクに紅茶を飲ませて", 1, 126301, 0, 0, 7329);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "キミも美を磨けば\nもっと輝けるはずさ！\nボクがメイクとか\nしてあげようか？", 1, 126301, 0, 0, 7330);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "んん、まだ眠い…\n美のためにも、\nもうひと眠りするよ…", 1, 126301, 0, 1, 7331);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ボクにぴったりな\n日傘を買ったんだ♪\n散歩にでも行こうよ！", 1, 126301, 0, 2, 7332);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜こそボクの時間！\nさぁ、あまねく人々へ\nボクの美を広めよう！", 1, 126301, 0, 3, 7333);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "リラックスは大事だよ\n心の余裕こそが\n美の秘訣だからね♪", 1, 126301, 0, 0, 7335);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "キミもボクの\n美の虜にしてあげる♪\nうれしいでしょ？", 1, 126301, 0, 0, 7336);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "人々を魅了するほどの\n魔性の香り…\nボクにふさわしいね♪", 1, 126301, 0, 0, 7337);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "冷えは美の大敵さ\nボクのように\n美しくなりたいなら\n体を温めるべきだよ", 1, 126301, 0, 0, 7338);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食事をするボクの\nなまめかしさ…♪\n吸血鬼すらも\nドキッとするだろうね", 1, 126301, 0, 0, 7340);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "吸血鬼って\n美しい存在だよね…\nボクほどではないけど", 1, 126301, 0, 0, 7341);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ここがナイトさんの\nお家なんですねーっ！\n雰囲気そっくりっ！", 1, 126401, 0, 0, 7343);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ドアも壁もお菓子じゃ\nないんですよねっ？\n不思議ですねーっ♪", 1, 126401, 0, 0, 7344);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "失礼のないように\n気をつけないとっ！\nライラエルさまとも\n約束してますからっ！", 1, 126401, 0, 0, 7345);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "向こうに帰るころには\nお土産話がいっぱい\nできてるといいな～♪", 1, 126401, 0, 0, 7346);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "戦闘用のアームの他に\n観光用のアームも\nあったらいいのにな～", 1, 126401, 0, 0, 7347);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ナイトさんの充填と\nライラエルさまの充填\nどっちも違って\nどっちも大好きです♪", 1, 126401, 0, 0, 7348);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "…ナイトさんが\nマスターになって\nくれたら…えへへっ\nなんでもないですっ！", 1, 126401, 0, 0, 7349);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お手伝いだったら\n任せてくださいっ！\nお家の移転とか\nしちゃいますかっ？", 1, 126401, 0, 0, 7350);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "こっちに来るときは\nポポおじいさんが\nしっかりメンテして\nくれるんですよっ♪", 1, 126401, 0, 0, 7351);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お家の中にいるのも\nいいですけど、お外も\n気になります～っ！\nお出かけしましょう♪", 1, 126401, 0, 0, 7352);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ヴォルガーノさんに\nそっくりの子猫さんを\n見かけたんですっ！\nご親戚ですかねっ？", 1, 126401, 0, 0, 7353);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ここだけの話ですよ？\n…実はケーブルって\n触られると、ちょっと\nくすぐったいんですっ", 1, 126401, 0, 0, 7354);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "このお家の持ち主は\nナイトさんですよね？\nそれじゃここでは\nご主人さまですねっ", 1, 126401, 0, 0, 7355);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございますっ\n今日もフルパワーで\nがんばりましょうっ♪", 1, 126401, 0, 1, 7356);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼の時間ですねっ！\nランチの充填、\nお願いしまーすっ♪", 1, 126401, 0, 2, 7357);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ眠らなくて\n大丈夫ですかっ？\n夜ふかしさんなら\nお付き合いしますよ♪", 1, 126401, 0, 3, 7358);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "エネルギーの消費を\n抑えるのも大切\nですよね～っ", 1, 126401, 0, 0, 7360);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "わたしが触っても\n平気なんて…！\nかわいくて頑丈っ！\n好きですっ！", 1, 126401, 0, 0, 7361);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "センサーによると…\nこの香りはいい香りに\n該当するみたいですっ\nなるほどーっ！", 1, 126401, 0, 0, 7362);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかいのって\nいいですよねっ！\nみなさんうれしそう\nですしっ♪", 1, 126401, 0, 0, 7363);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "これがこっちの世界の\nごはんなんですねっ\nおいしい気がします！", 1, 126401, 0, 0, 7365);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "そーっとそーっと…\n本を破かないように…\n書いてある内容より\n難しいです～っ！", 1, 126401, 0, 0, 7366);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ウィスタリア家の\nプライベートビーチも\nご案内しますわね♪", 1, 126701, 0, 0, 7368);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "世界を巡る\nリゾートクルーズも\nご用意できますわよ", 1, 126701, 0, 0, 7369);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "避暑地に専用の\n別荘がありますの\n今度ご招待しますわね", 1, 126701, 0, 0, 7370);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "日焼けは乙女の\n天敵ですわね\n備えはしっかりと…", 1, 126701, 0, 0, 7371);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "線香花火だけでは\n物足りませんわね\nもっとドカーンと…", 1, 126701, 0, 0, 7372);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ギルド活動も全力で！\nバカンスも全力で！\nそれが私ですわ！", 1, 126701, 0, 0, 7373);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "私のセンスで選んだ\n特注の水着ですもの\n似合って当然ですわ♪", 1, 126701, 0, 0, 7374);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ご希望ならすぐにでも\n夏の飛空艇遊覧ツアー\nへご招待しますわ♪", 1, 126701, 0, 0, 7375);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "夏の賑やかな\n雰囲気は好きですが…\n暑さには参りますわね", 1, 126701, 0, 0, 7376);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "日の光を浴びるほどに\n輝きを増す夏の私！\n今日も絶好調ですわ♪", 1, 126701, 0, 0, 7377);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "夏祭りに協力するなら\n資金と人材、どちらも\n用意しないとですわね", 1, 126701, 0, 0, 7378);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あなたさま…その…\nそうも見つめられると\n照れてしまいます…", 1, 126701, 0, 0, 7379);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "タマキさんの働く\n海の家も訪れて\nみたいですわね♪", 1, 126701, 0, 0, 7380);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "港の市場が\n賑わう頃ですわね！\n私たちも参りますわよ", 1, 126701, 0, 1, 7381);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "冷たい飲み物でも\nご一緒にいかが？\nうちのシェフに用意\nさせてありますの", 1, 126701, 0, 2, 7382);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "まだもう少し…\nこの夏の夜を\nあなたさまと…", 1, 126701, 0, 3, 7383);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "あなたさまも\n良ければこちらへ\nいらっしゃいな♪", 1, 126701, 0, 0, 7385);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "夏に合わせた装いに\n替えてみるのも\n楽しそうですわね♪", 1, 126701, 0, 0, 7386);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この夏めいた爽やかな\n香り…期間限定で\n売り出したいですわ", 1, 126701, 0, 0, 7387);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "く…我慢です…\nこの暑さに耐えてこそ\n美しさにも磨きが…", 1, 126701, 0, 0, 7388);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "暑い季節に働く\nみなさまへ差し入れも\n必要ですわね", 1, 126701, 0, 0, 7390);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "夏のトレンドを\n押さえておくのも\n大事ですわね", 1, 126701, 0, 0, 7391);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "上手くいけば\nヒット商品になる\nポテンシャルを\n感じますわね…！", 1, 126701, 0, 0, 7393);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "この極上の肌触り…\n言い値で買いますわ\n一体おいくらですの？", 1, 126701, 0, 0, 7394);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "せっかくのバカンス…\n自由に羽を\n伸ばすとしましょう", 1, 126601, 0, 0, 7395);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "たとえどのような\n秘密を持とうとも\n私には筒抜けですよ", 1, 126601, 0, 0, 7396);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "子供だましの怪談に\n関心はありませんが…\n霊には興味があります\n観察対象として、ね", 1, 126601, 0, 0, 7397);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "彼の絵日記…\nあとでゆっくりと\n読ませてもらいます", 1, 126601, 0, 0, 7398);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "セミの鳴き声に入道雲\nそしてクリームソーダ\nこれでこそ夏ですね", 1, 126601, 0, 0, 7399);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "夏休みの宿題でも\n作るとしましょうか\n彼の限界を少し超えた\n負荷を与えるには…", 1, 126601, 0, 0, 7400);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "彼と過ごす夏を\n特別なものにしたい…\nそれが私の望みです", 1, 126601, 0, 0, 7401);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "夏だからといって\n浮かれすぎないように\n節度を持って\n楽しみなさい？", 1, 126601, 0, 0, 7402);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ああ見えてもマサキは\n私のプリンセスナイト\nあまり侮られては\n困りますよ？", 1, 126601, 0, 0, 7403);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "私の秘密ですか？\nまんじゅうが怖い…\nというのはどうです？", 1, 126601, 0, 0, 7404);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ここは誰かの秘密を\n盗み聞くのに\n最適な場所ですね\n…ジョークですよ", 1, 126601, 0, 0, 7405);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "一緒に風鈴の音を\nのんびり楽しもう…？\n…別に構いませんよ\n貴方とならば", 1, 126601, 0, 0, 7406);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "貴方に約束しましょう\n決して忘れられない\n夏にしてあげますよ", 1, 126601, 0, 0, 7407);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "早起きとは感心ですね\nでは一緒に\n体操でもしましょうか", 1, 126601, 0, 1, 7408);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼食は流しそうめん？\n非効率的ですね\n…食べないとは\n一言も言っていません", 1, 126601, 0, 2, 7409);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "…貴方が望むならば\nいくらでも怖い話を\nしてあげますが…\nいかがですか？", 1, 126601, 0, 3, 7410);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "七冠にも休息は\n必要なのです\nしばらくここで\n休ませてもらいますよ", 1, 126601, 0, 0, 7412);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "なかなか気に入った…\nというのは\n誰にも秘密です", 1, 126601, 0, 0, 7413);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "薫風を思わせる\nこのさわやかな香り…\n悪くないセンスですね", 1, 126601, 0, 0, 7414);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "夏だからこそ\n冷え対策は\n重要なのです\n…とはいえ暑いですね", 1, 126601, 0, 0, 7415);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "私がどのような味が\n好きなのかは…\n当然秘密です", 1, 126601, 0, 0, 7417);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "夏を舞台にした\n小説は数多くあります\n彼が好きそうな本を\n何冊か見繕いましょう", 1, 126601, 0, 0, 7418);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "見た目も手触りも\n完璧に覚えました\nいつでも模倣できます", 1, 126601, 0, 0, 7420);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "ふむ…夏らしい\nクッションですね\nナイトプールに\n映えそうです", 1, 126601, 0, 0, 7421);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "レイ様も格好良いけど\n騎士さんもなかなか…\nって、今の聞こえて\nませんよねっ？", 1, 105401, 0, 0, 7422);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "騎士さんはシンプルな\n服が似合いそうです！\n今度、一緒に\n見に行きましょう♪", 1, 105401, 0, 0, 7423);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "最初はどうかな～って\n思ったけど…\n水着姿でも案外\n問題ないのよね…", 1, 126801, 0, 0, 7424);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "水着で飲みすぎると\nお腹が冷える、って\n言うけど…麦しゅわ\nなら問題ないわね！", 1, 126801, 0, 0, 7425);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "暑ければ暑いほど\nその後の麦しゅわは\nおいしくなるのよ…", 1, 126801, 0, 0, 7426);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "しっかりと仕事を\nこなしてから、\nしっかりと麦しゅわ！\nやっぱりこれね！", 1, 126801, 0, 0, 7427);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ふふっ、デザインも\n着心地も最高ね\n奮発して用意して\n正解だったわ♪", 1, 126801, 0, 0, 7428);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "伝説の麦しゅわ、\n飲めるものなら\nまた飲みたいわね…", 1, 126801, 0, 0, 7429);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "二つ名に恥じない\n聖騎士として\n私…飲むわ！", 1, 126801, 0, 0, 7430);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "この格好なら水に\n濡れても大丈夫！\nなんだけど、さすがに\n書類は濡らせないわね", 1, 126801, 0, 0, 7431);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "そうやってじっと\n見られると…ちょっと\n恥ずかしいわ…", 1, 126801, 0, 0, 7432);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日もいい天気ね\nふふっ、あとで\nビーチに遊びに\n行きましょ♪", 1, 126801, 0, 0, 7433);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "水着姿も慣れると\n案外快適ね\nそうだ、キミも\n水着になっちゃう？", 1, 126801, 0, 0, 7434);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "例え水着姿であろうと\n聖騎士としての誇りは\n忘れてないわ！", 1, 126801, 0, 0, 7435);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "キミとだったら\n麦しゅわなしでも\n最高の夏のバカンスに\nなると思うわ♪", 1, 126801, 0, 0, 7436);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "仕事終わりの\n麦しゅわのために\n今日も一日\n頑張るわよ♪", 1, 126801, 0, 1, 7437);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今日のお昼は\nどうしようかしら…\nさ、さすがに昼からは\n自重してるわよ？", 1, 126801, 0, 2, 7438);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "さ、一日の疲れを\n洗い流すために…\n軽～く飲むわよ！", 1, 126801, 0, 3, 7439);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "こうやって\n直に触れると\n肌触りの良さが\nよく分かるわ♪", 1, 126801, 0, 0, 7441);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "今日もかわいいわね～\nどう？　今度\nお姉さんの一人飲みに\n付き合わない？", 1, 126801, 0, 0, 7442);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りね～…はっ！\n麦しゅわの匂いの\nアロマポットなんて\nあったらよくない？", 1, 126801, 0, 0, 7443);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "こんな格好で火に\n当たってると焙られる\nスルメの気分が\nちょっと分かるわ…", 1, 126801, 0, 0, 7444);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…うん、\n結構おつまみにも\nむいてそうね～♪", 1, 126801, 0, 0, 7446);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "試験に使った参考書、\nたまには読み返して\nおかないとね", 1, 126801, 0, 0, 7447);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "ふふ♪\nいい手触りね～", 1, 126801, 0, 0, 7449);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "…はふう～…\nゴロゴロするのって\n最高ね～", 1, 126801, 0, 0, 7450);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ん…やっぱり\nこの水着…\n大胆、なんじゃ…？", 1, 126901, 0, 0, 7451);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "海でもお世話って、\nできるのかしら…？\n浮き輪代わりになる、\nとか…？", 1, 126901, 0, 0, 7452);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "～♪\nふふ…海に行く\n準備も、楽しい…かも", 1, 126901, 0, 0, 7453);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "あうぅ…水着で\n歩いてると…お尻…\nすぐ食い込んじゃう…", 1, 126901, 0, 0, 7454);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "海では、はしゃいだ\nほうがいいのよね…\nわ、わー、い…♪\n…こうかしら？", 1, 126901, 0, 0, 7455);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あなたとなら…\n楽しい夏の思い出、\n作れる…気がするの…", 1, 126901, 0, 0, 7456);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "また来年も…\n再来年も…\nあなたと海へ\n行けますように…", 1, 126901, 0, 0, 7457);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "水着の着方を\n練習してるの…\n後ろ、変じゃない…？", 1, 126901, 0, 0, 7458);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "海に行く支度…\n進んでるかしら…？\nお手伝い、する…？", 1, 126901, 0, 0, 7459);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ひ、日除けの準備は\n万全よ…\nずっと太陽の下に\nいたら…溶けちゃう…", 1, 126901, 0, 0, 7460);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "泳ぐ練習…\nこ、ここでするのは\n…さすがに変？", 1, 126901, 0, 0, 7461);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "人混みに入るのは\nまだ不安で…\nでも、あなたといれば\nきっと…大丈夫…", 1, 126901, 0, 0, 7462);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あなたのおかげで\n海の楽しいところを\nたくさん知ったわ…\nありがとう…♪", 1, 126901, 0, 0, 7463);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お出かけの日の朝は\n早い、のよね…？\nだから、ずっと\n起きていたわ…", 1, 126901, 0, 1, 7464);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今頃ビーチの日差しは\n強いんでしょうね…\nそ、想像しただけで…\nめまいが…", 1, 126901, 0, 2, 7465);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ビーチの夜といえば\n花火って、聞いたわ…\nバン、って言わない\n花火…ある…？", 1, 126901, 0, 3, 7466);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "素肌にふわふわが…\n気持ちいい…♪", 1, 126901, 0, 0, 7468);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "うふふ…\n一緒に海…行く？", 1, 126901, 0, 0, 7469);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ふぅ…♪\n気分まで…\n晴れやかになるわ…", 1, 126901, 0, 0, 7470);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "暑いような…\n寒いような…\n不思議な気持ちに\nなるわ…ね？", 1, 126901, 0, 0, 7471);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "泳いだ後には\nいっぱい食べたほうが\n体によさそう、ね…", 1, 126901, 0, 0, 7473);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ビーチの日陰で\n読書するのも…\n気持ちよさそう…♪", 1, 126901, 0, 0, 7474);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "これで合ってる…？\n遊び方わからなくて…", 1, 126901, 0, 0, 7476);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "ふわふわ…♪\n海の底にいるみたい…", 1, 126901, 0, 0, 7477);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "恥ずかしい格好で\n室内を歩くこの快感\nクセになりそうです…", 1, 127001, 0, 0, 7478);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "この水着…\nどうしてかポーズを\n決めたくなりますね…", 1, 127001, 0, 0, 7479);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "海にはどんな生き物が\nいるのでしょう～\n胸が高鳴ります～♪", 1, 127001, 0, 0, 7480);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "夏は暑いですね…\nクウカの体が熱いのも\n夏のせい…ぐふふ…♪", 1, 127001, 0, 0, 7481);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ドＳさんと無人島に\n取り残されて…という\n妄想はかなりイイです", 1, 127001, 0, 0, 7482);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ドＳさんの\n欲望に満ちた眼差し…\nクウカ、受け止めます", 1, 127001, 0, 0, 7483);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "海に行くのが\n楽しみです…\nドＳさんと…ぐふふ♪", 1, 127001, 0, 0, 7484);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "「もっと過激な水着を\n見せてみろよ」なんて\nいけませんドＳさん…", 1, 127001, 0, 0, 7485);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "水着のままで\n踊ればいいのですね…\nドＳさんの望みなら！", 1, 127001, 0, 0, 7486);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ドＳさんの熱い視線を\n感じます…じゅるり…\nもっと見てください…", 1, 127001, 0, 0, 7487);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "こんな格好のクウカを\n放っておくなんて…\nさすがですドＳさん！", 1, 127001, 0, 0, 7488);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "海で水着といえば\n何かが起きる予感…！\nドＳさんの新たな攻め\n期待していますね…！", 1, 127001, 0, 0, 7489);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "恥ずかしいですけど\n頑張っちゃいました\nドＳさん…こういう\n水着、好きですか？", 1, 127001, 0, 0, 7490);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "こんな朝からクウカを\n水着に着替えさせて…\n本当にドＳさんは\n欲望に正直ですね！", 1, 127001, 0, 1, 7491);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "こんな昼間から\nドＳさんがヌルヌルの\n液体をクウカに～！\nえっ…日焼け止め？", 1, 127001, 0, 2, 7492);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ドＳさん…これから\nクウカと夜の海を\n見に行きませんか？\nきっと綺麗ですよ…♪", 1, 127001, 0, 3, 7493);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ここなら妄想に\n集中できます～♪\nじゅるり～♪", 1, 127001, 0, 0, 7495);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "こうもかわいいと\n妄想に登場させるのも\n気が引けます…", 1, 127001, 0, 0, 7496);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "クウカを昂らせる\nこの香り…！\nは！　ドＳさんの罠！", 1, 127001, 0, 0, 7497);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "体を熱くさせて\n水着を脱がそうと！？\nテクニカルです…！", 1, 127001, 0, 0, 7498);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "クウカの口の中に\nたくさん…♪\n止まりません…！", 1, 127001, 0, 0, 7500);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "読書は心が穏やかに\nなりますね…！\nぐふふ…穏やかに…", 1, 127001, 0, 0, 7501);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "いい乗り心地です…♪\nあっ…普通に楽しんで\nしまいました…", 1, 127001, 0, 0, 7503);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "これは…\n妄想に役立ちそうな\n感触です…！", 1, 127001, 0, 0, 7504);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "成長した自分に\nあわせて、もっと\nかっこいいポーズを\n研究するッス！", 1, 100501, 0, 0, 7505);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "これからも一緒に\n最高のヒーローを\n目指していくッスよ♪", 1, 100501, 0, 0, 7506);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "お父さん、娘の\n水着姿がそんなに\nうれしいの？", 1, 127101, 0, 0, 7507);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "怖い話を子どもたちに\n聞かせたら泣かれて\nしまいました…\n加減が難しいです…", 1, 127101, 0, 0, 7508);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "海に行くと父が\n水着の女性ばかり\n追いかけて困ります…", 1, 127101, 0, 0, 7509);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "拾った貝殻で\n新しい占いでも\nはじめてみようかな", 1, 127101, 0, 0, 7510);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "貝殻を耳に当てると\n波の音が…あっ\nこれはダメです\nよくない声がします", 1, 127101, 0, 0, 7511);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "この飲み物、スーッと\n体に沁み込んでくる…\nあの人にも\n教えてあげたいです", 1, 127101, 0, 0, 7512);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "強い日差しも騒がしい\n海も苦手なのに\nあの人となら不思議と\n楽しく思えるんです", 1, 127101, 0, 0, 7513);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "夏限定、水と氷を\n使った特別な占いは\nいかがですか？", 1, 127101, 0, 0, 7514);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "暑い日々にはやはり\n怪談ですね\n厳選フルコースで\nお聞かせします", 1, 127101, 0, 0, 7515);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "寒気がする？　それは\n霊ではなくかき氷の\n食べ過ぎですよ", 1, 127101, 0, 0, 7516);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "今日の占い、あなたの\nラッキーパーソンは…\n白い水着の女性です", 1, 127101, 0, 0, 7517);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あの、よければ\n日焼け止めを塗って\nもらえませんか？\n背中は届かなくて…", 1, 127101, 0, 0, 7518);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "海に行きませんか？\n二人きりで静かな\n砂浜を散歩したいです", 1, 127101, 0, 0, 7519);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "潮騒だけが響く朝の海\n心が落ち着きます\nこれから一緒に散歩に\n行ってみませんか？", 1, 127101, 0, 1, 7520);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "不思議です。どうして\n普通のご飯でも、海で\n食べると特別おいしく\n感じるのでしょう…", 1, 127101, 0, 2, 7521);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜の海に行きませんか\n今なら夜光虫が\n見られるかも\nしれませんよ", 1, 127101, 0, 3, 7522);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "夏は知らぬ間に体力を\n消耗しています\n適度に休息して\nいきましょう", 1, 127101, 0, 0, 7524);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "このぬいぐるみ…\n大丈夫です\n何も憑いては\nいませんよ", 1, 127101, 0, 0, 7525);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ほのかにお線香\nみたいな香り…\nなんだか\n落ち着きます", 1, 127101, 0, 0, 7526);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "人魂、鬼火\nセントエルモの火…\n炎を見ていると色々と\n連想してしまいます", 1, 127101, 0, 0, 7527);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "お腹を壊さぬよう\n食い合わせには\nご注意ください", 1, 127101, 0, 0, 7529);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "これはいい\n怪談集ですね…\nつい読みふけって\nしまいます", 1, 127101, 0, 0, 7530);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "ふふ、こういうのに\n乗るとなんだか\n子どもに戻った\nみたいですね", 1, 127101, 0, 0, 7532);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "こ、これは…\nちょっとメルヘン\n過ぎて恥ずかしい\nですね…", 1, 127101, 0, 0, 7533);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "本当に素敵なお家…♪\n騎士たちの人柄を\n感じられるようで…\n不思議と落ち着きます", 1, 126501, 0, 0, 7534);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "調度品をつい間食…\nという習慣がこちらの\n世界にはないのですね\n…気をつけないと", 1, 126501, 0, 0, 7535);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "手土産のお菓子は\nどちらに置けば\nよいでしょうか？", 1, 126501, 0, 0, 7536);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "まるでおとぎ話の中に\n入ってしまったかの\nよう…別世界とは\nよく言ったものです", 1, 126501, 0, 0, 7537);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "お忍び…ふふっ♪\nときめく響きです\nなんだかお茶目で…\n密やかな印象が", 1, 126501, 0, 0, 7538);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ふわ…\nああ、ついあくびが…\n居心地がよすぎるのも\n困り物ですね…ふふ♪", 1, 126501, 0, 0, 7539);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "騎士には不思議な力が\nあるだけでなく\n何者かの加護が\nあるようですね…", 1, 126501, 0, 0, 7540);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "この『王家の装備』は\n少し気難しいのです\nわたし以外が触れると\nその…ビリビリっと", 1, 126501, 0, 0, 7541);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "子どもたちに新しい\n遊びを教わりました♪\nにーらめっこしましょ\nあっぷっ…ぷ～っ！", 1, 126501, 0, 0, 7542);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "実は憧れていたのです\n友人の家を訪ねると\nいう経験に…ふふっ", 1, 126501, 0, 0, 7543);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ぎるどはうす…\nぎるど活動の拠点だと\n管理協会？　の方に\nうかがいました", 1, 126501, 0, 0, 7544);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あなたは運命を\n信じますか？\nわたしは…信じます\nよい運命だけですが♪", 1, 126501, 0, 0, 7545);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "もしわたしが本当に\n天使だったとしたら…\nどうされますか？\n…ふふ、冗談です♪", 1, 126501, 0, 0, 7546);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "パンケーキの香りで\n目覚める朝は\nとても良いものですよ\nぜひともお試しを♪", 1, 126501, 0, 1, 7547);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ひと休みの時間ですね\n食事にお昼寝…\nすべきことを行って\n英気を養いましょう", 1, 126501, 0, 2, 7548);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ休まれては？\n眠れないようであれば\n寝物語か子守歌でも\nふふ、遠慮は無用です", 1, 126501, 0, 3, 7549);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "すう………はっ！\n眠ってはいませんよ？\nいくら居心地が良い\nからといって…ふわぁ", 1, 126501, 0, 0, 7551);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "まあ、あいらしい…♪\nぜひわたしの寝室に\n招待させてください", 1, 126501, 0, 0, 7552);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "なんて、かぐわしい…\nオーブンからただよう\n焼き菓子の香りとは\nまた異なる魅力が…", 1, 126501, 0, 0, 7553);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "みなで暖をとりながら\n互いに語り笑い合う\n…心休まる時間ですね", 1, 126501, 0, 0, 7554);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食は心と体に\nゆとりを生みます\n…辛い食べ物の場合？\nそれは、その…", 1, 126501, 0, 0, 7556);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "こちらの世界の知識を\n蓄えておかなければ\nテーブルマナーに\nついてのページは…", 1, 126501, 0, 0, 7557);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "新しい色の蛍光ペン\n買ったのよね\nこれで勉強が\n楽しくなるわ～♪", 1, 127201, 0, 0, 7559);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "学食のランチ、結構\nおいしいのよね～\n今度ペコリーヌに\n教えてやろうかしら？", 1, 127201, 0, 0, 7560);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ふふふ…扉に黒板消し\n仕掛けてるの…あいつ\n引っかかるかしら？", 1, 127201, 0, 0, 7561);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "部活するなら運動部も\n悪くないかもね～\n夕日に向かって\n突っ走ってやるわ！", 1, 127201, 0, 0, 7562);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "毎日窮屈な制服着て\n学生も大変ね～\n…ま、かわいいけど", 1, 127201, 0, 0, 7563);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あいつに貸したノート\n変な落書きとか\nしてなかったよね…？\n…その、相合傘とか…", 1, 127201, 0, 0, 7564);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "昨日の家庭科で\n作ったクッキー…\nあいつにどうやって\n渡そうかな…？", 1, 127201, 0, 0, 7565);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "宿題教えてって？\nしょうがないわね～\nじゃあ一緒に\nやりましょ", 1, 127201, 0, 0, 7566);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あ、明日あたしたち\n日直当番よね？\nめんどい仕事は\nあんたに任せるわ～", 1, 127201, 0, 0, 7567);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "寮生活は楽しいけど\n就寝時間が早すぎよね\nいきなり消灯されると\nビックリするわ", 1, 127201, 0, 0, 7568);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "校則で禁止だけど、\nにけつでほうき通学\nとか青春っぽくない？", 1, 127201, 0, 0, 7569);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "制服って好きな人とも\n自然にお揃いになれて\nいいわよね…って別に\nあんたとって訳じゃ…", 1, 127201, 0, 0, 7570);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あんたネクタイ\n曲がってるわよ～？\nほら直したげるから\nこっち向いて？", 1, 127201, 0, 0, 7571);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよ～！\n今日も元気に登校よ！\n忘れ物ないようにね！", 1, 127201, 0, 1, 7572);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "午前の授業疲れたわ～\nしっかりお昼を食べて\n午後も頑張るわよ！", 1, 127201, 0, 2, 7573);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "うう…学校の怪談\n思い出しちゃった…\n…別に怖くないけど！", 1, 127201, 0, 3, 7574);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふかふか～\n…気持ち良すぎて\n制服のまま\n寝ちゃいそうね…", 1, 127201, 0, 0, 7576);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいくて癒されるわ\n寮に持ち込んでも\n大丈夫かしら…？", 1, 127201, 0, 0, 7577);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "集中力の高まる香りで\n勉強の効率爆上がりね\n次のテストで\nいい点取るわよ～！", 1, 127201, 0, 0, 7578);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "うう、ちょっと冷えて\n来たわね…\nスカートの下に\nジャージ穿こうかしら", 1, 127201, 0, 0, 7579);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐっ…もぐっ…\n食べとかないと教室で\nお腹なっちゃうわ～", 1, 127201, 0, 0, 7581);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "図書室で借りた本\n明日返却日なのよね…\n今日中に読むわよ！", 1, 127201, 0, 0, 7582);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "あいつに背中を\n預けるのもいい気分だ\nいつかは、全部…", 1, 104301, 0, 0, 7584);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "な、なんだよ？\nじっと見るんじゃねぇ\n尻尾が揺れちまうだろ", 1, 104301, 0, 0, 7585);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "魔法の練習！\nむむむ～…\nそれっ…！", 1, 127301, 0, 0, 7586);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "そだ！　これ着て\nルー学行こっかな？　\n制服自慢しちゃお♪", 1, 127301, 0, 0, 7587);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "赤点回避の魔法とか\nあったら最高じゃね？\n誰かうちに教えて～", 1, 127301, 0, 0, 7588);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "制服が一番映える\n場所ってどこだろ？\n教室？　遊園地？", 1, 127301, 0, 0, 7589);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ベンキョーつらたん…\n今度キャルっちに\n助けてもらお", 1, 127301, 0, 0, 7590);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "部活か…\nヒデサイと一緒に\nやったら楽し～かも♪", 1, 127301, 0, 0, 7591);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "男子の制服\nもにカワだった…\n今度ヒデサイに\n借りよっかな？", 1, 127301, 0, 0, 7592);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ちょすー、うちの\nさいきょー魔法で\nテンアゲしてあげる～", 1, 127301, 0, 0, 7593);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "九九って呪文ぽくね？\nほら、例えばヒチシ…\nヒチシ、なんだっけ？", 1, 127301, 0, 0, 7594);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ヒデサイセンセー\nうちにベンキョー\n教えて！", 1, 127301, 0, 0, 7595);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "学割マジ助かるー\nヒデサイ、一緒に\nどんどん使ってこー♪", 1, 127301, 0, 0, 7596);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "今度ヒデサイに\nお弁当作ったげる\n屋上で一緒に食べよ♪", 1, 127301, 0, 0, 7597);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ヒデサイのバイブス\n上がる言葉教えてよ\nつらたんな時、うちが\nいっぱい言ったげるよ", 1, 127301, 0, 0, 7598);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ちょすちょす～\n今日も朝から\nバイブス十分♪", 1, 127301, 0, 1, 7599);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼どうしよっかな\nたまにはガッツリ\nいっちゃう系？", 1, 127301, 0, 2, 7600);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "やべ、宿題まだ\nできてないし…\nヒデサイ助けて～", 1, 127301, 0, 3, 7601);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "充電ちう～\n…ガッコーのイスも\nこれにして～", 1, 127301, 0, 0, 7603);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいし、\n癒されるし、キュン死\nしちゃうじゃん…！", 1, 127301, 0, 0, 7604);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "リフレッシュの\n魔法発見！\nいい香り～♪", 1, 127301, 0, 0, 7605);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ぽかぽかサイコー♪\n今日はもーずーっと\nここにいたいかも～", 1, 127301, 0, 0, 7606);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "超おいし～♪\n学食にあったら\n毎日リピする～", 1, 127301, 0, 0, 7608);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ…\nねむみパない…\n続きはまた今度～", 1, 127301, 0, 0, 7609);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "今度は子どもたちも\nサラサリアに連れて\n行ってあげたいわ", 1, 127501, 0, 0, 7611);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "子どもたちから\nお姫さまみたいって\n言われちゃった♪", 1, 127501, 0, 0, 7612);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "この剣…火を点けたり\nするのに便利なのよ\nコントロールも効くし", 1, 127501, 0, 0, 7613);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "あのサラサリアの\nカラっとした暑さが\nちょっと恋しいわ…", 1, 127501, 0, 0, 7614);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "買ってきたお土産、\nお世話になってる\nみんなに配りましょ♪", 1, 127501, 0, 0, 7615);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あんたと一緒なら\nどこの国でだって\n暮らしていけそうね♪", 1, 127501, 0, 0, 7616);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "今の事業を大きくして\nあんたと世界中の国を\n飛び回ったり…なんて\nすてきじゃない？", 1, 127501, 0, 0, 7617);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "サラサリアで食べた\n料理が恋しい…？\nもう…また今度\n作ってあげるわよ", 1, 127501, 0, 0, 7618);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今度旅行するなら\nどこに行こうかしら？\n希望があれば教えてね", 1, 127501, 0, 0, 7619);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "サラサリアの香辛料、\nランドソルでも\n人気が出そうよね\nいいビジネスの予感！", 1, 127501, 0, 0, 7620);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "そんなにじっと\n見られるとさすがに\n恥ずかしいってば…", 1, 127501, 0, 0, 7621);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お嫁さんは憧れるけど\nお婿さんになって\nもらうのもありよね…\nあんたはどう思う？", 1, 127501, 0, 0, 7622);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "やっぱり、あんたには\nいつもあたしの隣に\n居てほしいな…", 1, 127501, 0, 0, 7623);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "陽射しが強くなる前に\n雑多な用事は\n片付けちゃいましょ", 1, 127501, 0, 1, 7624);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "サラサリアで食べた\n料理を再現してみたの\n味見してくれる？", 1, 127501, 0, 2, 7625);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "暑さに負けないように\n睡眠はちゃんと\n取っておかないと", 1, 127501, 0, 3, 7626);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "こっちでもあっちでも\n忙しいのは変わらない\nわね…ちょっと休憩～", 1, 127501, 0, 0, 7628);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "サラサリアで見た\nぬいぐるみも\nかわいかったわね", 1, 127501, 0, 0, 7629);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "お香って地域ごとの\n特色が出るわよね\nこの香りは…\nちょっと神秘的？", 1, 127501, 0, 0, 7630);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "砂漠地方も夜は冷える\nのよね。温かいものが\nあると安心するわ…♪", 1, 127501, 0, 0, 7631);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食べ慣れた味って\nどうしてほっと\nするのかしら…", 1, 127501, 0, 0, 7633);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "今後の取引相手に\nなるかもしれないし\n向こうの文化も\n勉強しておかないと…", 1, 127501, 0, 0, 7634);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "犯人はこの中にいる！\n探偵として一度は\n言ってみたいセリフさ", 1, 101401, 0, 0, 7636);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "助手くんの情報を\n仕入れておかないと…\n理想の私を、ずっと\n見ていてほしいからね", 1, 101401, 0, 0, 7637);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "久々の長旅で\n里心がついちまったね\nしばらくランドソルで\nのんびりしようか", 1, 127601, 0, 0, 7638);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "たまには違う服装\n違う得物を使うのも\n悪くないね", 1, 127601, 0, 0, 7639);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "サラサリアにいた時は\n砂まみれで大丈夫かと\n思ってたけど、今じゃ\n懐かしく感じるよ", 1, 127601, 0, 0, 7640);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "魔法の絨毯、あれは\n楽だし速いし便利\nだったねえ…土産に\n一枚欲しかったな", 1, 127601, 0, 0, 7641);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "砂上での戦いは\nなかなかいい鍛錬に\nなったね…今度は\n修行しに行くとしよう", 1, 127601, 0, 0, 7642);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "サラサリアの人たちも\n気のいい連中だったが\n元気にやってるかねえ", 1, 127601, 0, 0, 7643);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "旅の恥はかき捨てって\nいうけど、悪い旅じゃ\nなかったね。次は\nアイツとどこに行こう", 1, 127601, 0, 0, 7644);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "この格好を冷やかしに\n来たのかい？\n生憎、もうすっかり\n慣れちまったよ", 1, 127601, 0, 0, 7645);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ギルドの連中に\n土産をわたしに\n行くところなんだ\n付き合っておくれよ", 1, 127601, 0, 0, 7646);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "久々に水場で\n釣りがしたいねえ…\nもちろんお前さんも\nくるんだろう？", 1, 127601, 0, 0, 7647);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "おっと\nサラサリアの連中から\n便りが来てるよ\nさ、一緒に読もうか", 1, 127601, 0, 0, 7648);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "最近サラサリアの踊り\nを練習してるんだ\nあとで振付けを\n見ておくれよ", 1, 127601, 0, 0, 7649);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "なんだいお前さん？\n…なんだか若奥さん\nっぽいって？　まあ、\nそりゃあ、ねえ…", 1, 127601, 0, 0, 7650);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "いい時間だね\n日が昇りきる前に\nやることをすませ\nとかないと", 1, 127601, 0, 1, 7651);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼はどうしようかね\nサラサリア風の\n食事でもつくろうか", 1, 127601, 0, 2, 7652);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "さて、早めに寝ようか\n砂漠の夜は冷えるから\n…っと、まだ旅行中の\n気分でいたよ", 1, 127601, 0, 3, 7653);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "良い座り心地だ\nサラサリア宮殿の\n応接間を\n思い出すねえ…", 1, 127601, 0, 0, 7655);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ランプの魔神に\nあげたら喜ぶかねえ？\n次に会う時までに\n見繕ってみようか", 1, 127601, 0, 0, 7656);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この香り…\nサラサリア土産の\n香木かい？", 1, 127601, 0, 0, 7657);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "旅先での焚火を\n思い出すよ\nなんだかほっとするね", 1, 127601, 0, 0, 7658);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ふふ、慣れてる味も\nいいけど、むこうの\n味付けが懐かしく\nなっちまうね", 1, 127601, 0, 0, 7660);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ…\n千夜一夜物語か\nおもしろいもんだねえ", 1, 127601, 0, 0, 7661);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "立派なギルドハウス♪\n帰る場所が素敵だと\n冒険に出るのも\n楽しくなりそうです♪", 1, 126001, 0, 0, 7663);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "お掃除でも…と\n思いましたけど、\nさすがお兄さんのお家\nきれいにしてますね♪", 1, 126001, 0, 0, 7664);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "わたしたちもいつか\n立派なギルドハウスが\n持てる冒険者に\nなりたいです…♪", 1, 126001, 0, 0, 7665);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "わたし冒険者ですけど\n家を守ってお兄さんの\n帰りを待つのも\n悪くない…かも？", 1, 126001, 0, 0, 7666);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "お菓子焼こうかな…♪\nちょっと多めに作って\nお兄さんにも\n食べてもらおうっと♪", 1, 126001, 0, 0, 7667);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "このお家、とっても\n大好きになりました♪\nだからその…もう少し\nいてもいいですか…？", 1, 126001, 0, 0, 7668);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "お兄さんに\n感謝の手紙を書いて\n枕元に隠して\nおこうかな…♪", 1, 126001, 0, 0, 7669);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "…お兄さん\nお暇なんですか？\nじゃあ一緒に冒険へ\n出かけましょう♪", 1, 126001, 0, 0, 7670);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お兄さんは苦手な食材\nとかありますか？\nあの、もしよければ\n今から手料理を…♪", 1, 126001, 0, 0, 7671);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "まったり過ごす\nお家時間もいいですね\n冒険者には羽休めも\n大事ですから♪", 1, 126001, 0, 0, 7672);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "いつでもお兄さんを\n守れるように\nこの姿でいることに\n慣れておきますね…！", 1, 126001, 0, 0, 7673);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お兄さん眠そうです…\nちょっとお昼寝\nしちゃいましょうか♪\nはい、膝枕…♪", 1, 126001, 0, 0, 7674);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お兄さん怪我を…！？\nわたしが治療を…\nふー…ふー…", 1, 126001, 0, 0, 7675);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます♪\n朝、元気に挨拶すれば\n幸せな一日が過ごせる\nそうですよ♪", 1, 126001, 0, 1, 7676);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ごはんの時間です\n…手がふさがってる？\nわかりました、じゃあ\nあ～んしますね♪", 1, 126001, 0, 2, 7677);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふわぁ…眠くなって\nきちゃいました…\nお兄さん…お泊りして\nいいですか…？", 1, 126001, 0, 3, 7678);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふにゃ～～…♪\nこんな姿、他の人には\n見せられません…♪\nもふもふ～～…♪", 1, 126001, 0, 0, 7680);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "お兄さんこういうの\n好きなのかな～…\nふふっ、わたしも♪\nぎゅ～～～っ♪", 1, 126001, 0, 0, 7681);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "アロマの癒し効果…\n上手くアレンジして\nみなさんの治療に\n活かせないかな～？", 1, 126001, 0, 0, 7682);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "は～気持ちいい～♪\n身体が暖まると\n心もぽかぽかです♪", 1, 126001, 0, 0, 7683);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "うふふ、おいしい♪\nプレシアちゃんなら\n無限にぱくぱく～って\nしちゃいそうです…♪", 1, 126001, 0, 0, 7685);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "本はわたしを\n知らない世界に\n連れていってくれる…\nまるでお兄さんです♪", 1, 126001, 0, 0, 7686);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "話題の新刊…\nあの人も読んでるかな\n今度会う時、感想\n聞いてみたいな…♪", 1, 103801, 0, 0, 7688);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "うにゃっ…あ、熱を\n測ってくれたんですか\nありがとうございます\nバッチリ元気ですよ♪", 1, 103801, 0, 0, 7689);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "お兄の、けはい…\nん、みつけた\nぎゅ", 1, 126101, 0, 0, 7690);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "きょろきょろ\nここも\nぱとろる、するよ", 1, 126101, 0, 0, 7691);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "おうち\nにぎやか\nさみしく、ない", 1, 126101, 0, 0, 7692);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "きょだい、おにぎり\nきょだい、肉まん\nきょだい…お兄？", 1, 126101, 0, 0, 7693);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "はっぴーちゃん\nどこ？\nお兄、たべた？", 1, 126101, 0, 0, 7694);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "くんくん…この、へや\nお兄の、におい\nすんでる\nすめる？", 1, 126101, 0, 0, 7695);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "おそうじ、にがて\nでも\nれんしゅう\nきゅっきゅ", 1, 126101, 0, 0, 7696);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "みみ、さわり、たい？\nんー…だめ…\nむずむず\nなので", 1, 126101, 0, 0, 7697);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "くろぷれしあ\nかっこいい？\nん…あざます", 1, 126101, 0, 0, 7698);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お兄の、おうち\nきょうみ、ましまし\nたんけん\nするね", 1, 126101, 0, 0, 7699);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "なでなで、される…と\nねむ…く…\nぶぅ…ぶぅ…ぶぅ…", 1, 126101, 0, 0, 7700);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "かみ、りぼん\nおてつだい\nよろ\nです", 1, 126101, 0, 0, 7701);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ここ\nすむ\nね？\nまいにち、いっしょ", 1, 126101, 0, 0, 7702);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ぐっもにん\nあさごはん\nあさごはん", 1, 126101, 0, 1, 7703);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お兄\nおつかれ？\nれっつ、まいぺーす", 1, 126101, 0, 2, 7704);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ひとりで、ねれる\nでも\nひとりじゃ、なくても\nねれる、よ…？", 1, 126101, 0, 3, 7705);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふかふか\nパパの、おなか\nみたい", 1, 126101, 0, 0, 7707);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "こんにちは\nぷれしあ、です\nおともだち、なろ？", 1, 126101, 0, 0, 7708);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい、におい\nでも、お兄\nもっと、いい、におい", 1, 126101, 0, 0, 7709);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "とりま\nお肉、やこ", 1, 126101, 0, 0, 7710);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…\nむげん肉まん、も\nきぼう", 1, 126101, 0, 0, 7712);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ぜんぶ、よんだ\nもっと、ぶあついほん\nでも、いーよ？", 1, 126101, 0, 0, 7713);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "幸せなクリスマスを\n過ごすため\nギルドハウスを\nきれいにしなくちゃ♪", 1, 127901, 0, 0, 7715);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "えへへ♪\n彼へのプレゼント…\n枕元にそっと\nおいておきましょう☆", 1, 127901, 0, 0, 7716);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "クリスマスといえば\n七面鳥の丸焼き…☆\nよだれを拭いて\nいざ準備です♪", 1, 127901, 0, 0, 7717);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "彼に用意した\nプレゼント…\n大きすぎて\nくつ下に入りません…", 1, 127901, 0, 0, 7718);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "プレゼントは\n貰う方も、贈る方も\nどちらも幸せを\n感じますね…☆", 1, 127901, 0, 0, 7719);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "夜景が見える\nレストランであの人と\nクリスマスデート…\n憧れちゃいますね☆", 1, 127901, 0, 0, 7720);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "プレゼントはわたし…\n恥ずかしいですけど\nこの贈り物、彼に\n喜んでほしいです…☆", 1, 127901, 0, 0, 7721);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "オーナメントを\nたくさん用意したので\n二人でツリーに\n飾りつけましょう☆", 1, 127901, 0, 0, 7722);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あはは、お腹\n空いちゃいました？\nパーティーまで\n我慢してください♪", 1, 127901, 0, 0, 7723);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ジングルベ～ル♪\nあなたも一緒に\nクリスマスソング\n歌っちゃいましょう♪", 1, 127901, 0, 0, 7724);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "サプライズプレゼント\nの用意をして…って\nあなた！？　い、今の\n聞いてませんよね…？", 1, 127901, 0, 0, 7725);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "クリスマスの夜は\nパーティーしましょう\nできれば…その…\n二人っきりで…☆", 1, 127901, 0, 0, 7726);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あなたと過ごした\n最高のクリスマス…\nずっとずっと心の奥に\nしまっておきますね", 1, 127901, 0, 0, 7727);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます！\n皆の願いが叶うような\n素敵な一日に\nしましょうね☆", 1, 127901, 0, 1, 7728);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ですね！\nディナーの買い出しが\n済んだら、少しお昼寝\nしちゃいましょうか☆", 1, 127901, 0, 2, 7729);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ就寝の\n時間ですね～\n枕元にくつ下の準備を\nお忘れなく～☆", 1, 127901, 0, 3, 7730);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふ～気持ちいい…☆\nお家でまったり過ごす\nクリスマスも\nいいですよね…♪", 1, 127901, 0, 0, 7732);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいですね～♪\nサンタさんからの\n贈り物でしょうか～？", 1, 127901, 0, 0, 7733);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "すう～…はあ～…\nすごく素敵な香り…\n炊き立てのご飯と\nいい勝負です…♪", 1, 127901, 0, 0, 7734);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "暖かいですけど…\nあの日の山小屋を\n思い出して\n恥ずかしいですね…☆", 1, 127901, 0, 0, 7735);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "むしゃむしゃもぐもぐ\n止まりませんよ\nクリスマスですから\nむしゃむしゃもぐもぐ", 1, 127901, 0, 0, 7737);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "物語に出てくる\nサンタさんみたいに\nわたしも幸せを\n運びたいです…☆", 1, 127901, 0, 0, 7738);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 14, 3, "わっ！\nこ…これは素敵な\nサプライズプレゼント\nですね…☆", 1, 127901, 0, 0, 7740);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 15, 3, "これを着ればわたしも\n立派なサンタさんに\nなれますかね…？", 1, 127901, 0, 0, 7741);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "ここが今のあたしの\n居場所ってやつです\nふふっ、なかなか\n悪くねー気分ですよ", 1, 106601, 0, 0, 7742);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "これからはボス代行\nとしてブイブイ\nいわせてやるです\nついてくるですよ！", 1, 106601, 0, 0, 7743);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "陛下～♪\n貴女のクレジッタが\nおめかしして\nはせ参じましたわ～♪", 1, 128001, 0, 0, 7744);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "パーティーとは景気の\n良さを見せつける場…\n倹約などは\nもっての外でしてよ！", 1, 128001, 0, 0, 7745);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "この天井の高さなら\n搬入できそうですわね\n陛下用の特注ケーキ♪", 1, 128001, 0, 0, 7746);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "…ぶぇっくしゅ！\nふう…少し背中を\n開けすぎたかしら…？", 1, 128001, 0, 0, 7747);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ここは秘書の目も\n届きませんから\nチクりメモの心配も\nありませんのよね～♪", 1, 128001, 0, 0, 7748);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "いくらでも二度見して\nよろしくてよ？\n本当にわたくしだと\n心から納得できるまで", 1, 128001, 0, 0, 7749);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "袖の下以外の贈り物も\nなかなかどうして…\n悪くないものですのね", 1, 128001, 0, 0, 7750);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "こう見えてダンスの\nたしなみはありますの\nお相手してあげても\nよろしくってよ", 1, 128001, 0, 0, 7751);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ドレスはもちろん\n特注品ですわ♪\nもしや貸衣装だと\n思いまして？", 1, 128001, 0, 0, 7752);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "バッグの中身？\n仕事に必要なものと…\n心を潤わせるための\n宝石がいくつか♪", 1, 128001, 0, 0, 7753);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "やる気というものは\n仕事に必要な条件です\nいわばドレスコードの\nようなものですわね", 1, 128001, 0, 0, 7754);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "全ての仕事は自分の\n血となり肉となり\nお金にもなるもの\nなのです。経験談です", 1, 128001, 0, 0, 7755);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "今年の教訓を活かして\n来年は更に素晴らしい\nクリスマスにして\n差し上げますわ！", 1, 128001, 0, 0, 7756);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\n今日という稼ぎ時の\nはじまりですわよ！", 1, 128001, 0, 1, 7757);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "安くて早くておいしい\nそれがランチに必須の\n栄養素ですわ！", 1, 128001, 0, 2, 7758);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "宵越しの仕事は\n安眠の敵！\n熟睡したいのであれば\n今が勝負時ですわよ！", 1, 128001, 0, 3, 7759);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "たまにはこうして\n休息を取ることも…\n…はっ！？\nドレスにシワが～っ！", 1, 128001, 0, 0, 7761);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "…わたくしの勘が\n言っていますわ\nこの愛らしさ！\n爆売れ確・定！", 1, 128001, 0, 0, 7762);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りですわね…\nお金の匂いには\n敵いませんけれども♪", 1, 128001, 0, 0, 7763);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "……ハッ！？\n完全にボーッとして\nしまいましたわ…！\nぬくもり…恐ろしい！", 1, 128001, 0, 0, 7764);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "考えませんわ…\n考えませんわよ！\nカロリーのことはっ！", 1, 128001, 0, 0, 7766);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ビジネス本以外の本を\n読むのも、たまには\n悪くありませんわね…", 1, 128001, 0, 0, 7767);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 14, 3, "よくできていますわね\nこの絵本！\n子ども向けだと甘く\n見ていましたわ…！", 1, 128001, 0, 0, 7769);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 15, 3, "この視界の狭さ…\n思い出しますわね\nティッシュ配りの\nアルバイト時代を…", 1, 128001, 0, 0, 7770);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ふふふ…こっそり\nスイーツを食べる\nリノちゃん見～っけ♪", 1, 128101, 0, 0, 7771);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "お姉ちゃんの抜き打ち\nお部屋チェック～♪\n…ケーキの食べこぼし\nこれはリノちゃんだね", 1, 128101, 0, 0, 7772);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "この衣装は目立つから\nどこにいても弟くんに\n気付いてもらえるね！", 1, 128101, 0, 0, 7773);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "弟くん、協力して！\nリノちゃんにお勉強\nしなさいって圧を\nかけるんだよっ…♪", 1, 128101, 0, 0, 7774);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "絆の力を感じるよ\nこれならもっと万全な\n弟くんのお世話が\nできそうだねっ！", 1, 128101, 0, 0, 7775);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お姉ちゃんもたまには\nリノちゃんみたいに\n甘えてみようかな…", 1, 128101, 0, 0, 7776);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "弟くんとリノちゃん\nどっちも大切な\n私のきょうだいだよ", 1, 128101, 0, 0, 7777);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "分かってるよ♪\nお姉ちゃんの膝枕を\nご所望だねっ？　え？\n違う？　違わないよ？", 1, 128101, 0, 0, 7778);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "リノちゃんがね\nお姉ちゃんチョップを\n防ぐ妹白刃取りを\n訓練してるんだよね", 1, 128101, 0, 0, 7779);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お姉ちゃん頭突きは\n封印しないとね…\nだって、今使うと\n頭飾りで威力が…ね", 1, 128101, 0, 0, 7780);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ふふっ♪\n目をつぶってても\n弟くんは見えてるよ\n…そこでしょ？", 1, 128101, 0, 0, 7781);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お姉ちゃんも\nリノちゃんみたいに\nかわいさいっぱいに\n振舞っちゃうぞ♪", 1, 128101, 0, 0, 7782);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "弟くんっ♪\nいつもお姉ちゃんの\n声が届く範囲にいてね\n…絶対だよ", 1, 128101, 0, 0, 7783);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう、弟くん！\nリノちゃんが起こして\nくれたんだね♪\n…先を越されちゃった", 1, 128101, 0, 1, 7784);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お姉ちゃんランチの\n時間だぞ♪\nさ、食べさせてあげる\nお口を開けて…♪", 1, 128101, 0, 2, 7785);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おやすみの時間だよ\n…弟くんは真ん中ね\n左右には私たち姉妹が\nいるから安心だよ♪", 1, 128101, 0, 3, 7786);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "お姉ちゃんは全力で\nリラックスしてても\n弟くんの声一つで\nすぐにでも動けるよ♪", 1, 128101, 0, 0, 7788);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "リノちゃんこういうの\n好きそうだよね\n今度プレゼントして\nみようかな？", 1, 128101, 0, 0, 7789);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい匂いがするね～\nあれ？\nリノちゃんのケーキの\n甘い匂いも混ざってる", 1, 128101, 0, 0, 7790);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "お姉ちゃんの\n弟くんへの愛も\n熱く燃えあがるね…！", 1, 128101, 0, 0, 7791);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "たくさん食べて\n栄養を補給して\nお姉ちゃん力に\n全て変換するよっ！", 1, 128101, 0, 0, 7793);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ことわざ辞典…\nリノちゃんにこれを\n読ませようかな", 1, 128101, 0, 0, 7794);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "そろ～り、そろり…\nお姉ちゃんが居ぬ間に\nスイーツを～…♪", 1, 128201, 0, 0, 7797);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "いつか\nお姉ちゃんに似合う服\n作ってみたいですね", 1, 128201, 0, 0, 7798);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "あいたっ！？\nひらひらしたとこ\n踏んづけちゃいました", 1, 128201, 0, 0, 7799);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お姉ちゃんと\nお兄ちゃんの二人から\n勉強しろって圧力が～", 1, 128201, 0, 0, 7800);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "私の中にも秘めた力が\n眠っているはず…\nそう、妹パワーが", 1, 128201, 0, 0, 7801);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "私もお兄ちゃんを\n甘やかしてみたいです\n…お姉ちゃんみたいに", 1, 128201, 0, 0, 7802);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "お兄ちゃんの部屋を\nこっそり拝見～♪\nはっ！？　これは\nお姉ちゃんの視線…！", 1, 128201, 0, 0, 7803);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お姉ちゃん頭突きは\n大地を揺らす威力です\n私とお兄ちゃんは\n挨拶感覚で喰らいます", 1, 128201, 0, 0, 7804);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お姉ちゃんチョップは\n雲を裂く切れ味です\n早く妹白刃取りを\n完成させないと…", 1, 128201, 0, 0, 7805);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お姉ちゃんみたいに\n大人っぽく着こなす\nには一体どうしたら…", 1, 128201, 0, 0, 7806);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "弓のデザインも\nかわいいんですよっ♪\n常に持ち歩きたいです\nけど…危ないですよね", 1, 128201, 0, 0, 7807);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "きれいな服を着てると\nお姫さま気分に\nなれますね…あとは\n王子さまがいれば…♪", 1, 128201, 0, 0, 7808);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お兄ちゃんっ！\n私は褒められて伸びる\nタイプなのでもっと\nナデナデしてください", 1, 128201, 0, 0, 7809);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "妹モーニングコール♪\nお姉ちゃんより先に\n起こしに来れました！", 1, 128201, 0, 1, 7810);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ああっ、お姉ちゃん！\nお兄ちゃんにアーン\nするなんてずるいです\n私もしたいですっ！", 1, 128201, 0, 2, 7811);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おやすみの時間ですね\nえへへ、きょうだいで\n並んで寝るのって\n楽しいですよね！", 1, 128201, 0, 3, 7812);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "スイーツを食べた後は\nお腹を休めましょう～\n平気平気…ちゃぁんと\n運動もしますからぁ…", 1, 128201, 0, 0, 7814);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "お姉ちゃんも\nこういうかわいいもの\n好きなんですかね", 1, 128201, 0, 0, 7815);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "くんくん…\nなんの匂いでしょうか\n新しいスイーツ？", 1, 128201, 0, 0, 7816);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "きょうだい３人\n肩を寄せて暖まるとか\nよくないですかっ？", 1, 128201, 0, 0, 7817);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いつも元気な妹で\nいるためには\nよく食べるのが大事！", 1, 128201, 0, 0, 7819);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "なんか姉に関する本が\nちらほらと混ざって…\nこれお姉ちゃんの\n仕業ですね！？", 1, 128201, 0, 0, 7820);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ふんふんふ～ん\nお正月で世間は\n浮かれてるですねえ\nま、いいですけど♪", 1, 128301, 0, 0, 7823);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "は～、お正月は\nだらだらできて\n最高ですね\n…いつも通りですけど", 1, 128301, 0, 0, 7824);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ビッグな幹部は\nビッグなお年玉が\nもらえるはずです\n楽しみですね", 1, 128301, 0, 0, 7825);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "今度ドラちゃんに\nお年玉を持っていって\nやりたいですね", 1, 128301, 0, 0, 7826);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "そういえばアユアユと\n約束してたですよ…\nそろそろ出かける\nですかね", 1, 128301, 0, 0, 7827);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お年玉がもらえたら\n何に使うか…\n今のうちに\n考えとくです", 1, 128301, 0, 0, 7828);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "年神の報酬の駄菓子が\nたまってきたですね…\nガキどもにでも\n配っちまうですよ", 1, 128301, 0, 0, 7829);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あたしのレアな\n晴れ着姿、今のうちに\nしっかり目に焼き付け\nとくがいいですよ", 1, 128301, 0, 0, 7830);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お兄さんは今日も\nヒマそうですねぇ…\nしょうがないから\nかまってやるですよ", 1, 128301, 0, 0, 7831);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そういえばカヤぴぃ\n見なかったですか？\n喧嘩屋初売りセール\nとか言ってたですけど", 1, 128301, 0, 0, 7832);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お正月ならではの\n大きなシノギ…\nなにかないですかね？", 1, 128301, 0, 0, 7833);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "いいとこに来たですよ\nさっき走ったら帯が\n曲がっちゃったです\n直すの手伝うです！", 1, 128301, 0, 0, 7834);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "年神の仕事ですか？\nこれからいくとこです\nお兄さんも一緒に\n来やがるですよ！", 1, 128301, 0, 0, 7835);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふぁあ…\nどうしたですか？\nお正月に早起きなんて\n無粋ってヤツですよ…", 1, 128301, 0, 1, 7836);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "小腹が減ったですね\n一緒におせちでも\nつつきにいくですよ！", 1, 128301, 0, 2, 7837);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜はあたしの時間\nと言いたいとこですが\n初夢のために早く\n寝とくですかね…", 1, 128301, 0, 3, 7838);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "正月は食っちゃ寝\nするのが仕事…\nって聞いたこと\nあるですよ", 1, 128301, 0, 0, 7840);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふふっ、晴れ着の\nあたしの次くらいには\nかわいいですね", 1, 128301, 0, 0, 7841);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "なんかいい匂い…？\nよく知らんですけど\n晴れ着からも同じ\n匂いがしてるですね…", 1, 128301, 0, 0, 7842);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ふ～あったまるです…\nお正月の唯一の弱点は\n寒いことですからね…", 1, 128301, 0, 0, 7843);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…正月太り？\nあたしには関係ない\n言葉ですね", 1, 128301, 0, 0, 7845);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "あったあった…\nトーゴクには\nドラゴンの神宮も\nあるんですね", 1, 128301, 0, 0, 7846);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "お正月のトラブルも\nハツネちゃんが\nめでたく解決\nしてみせるのだ～！", 1, 128401, 0, 0, 7848);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "そうだ、新年会に\nサプライズ大作戦を\nしかけちゃおう！", 1, 128401, 0, 0, 7849);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "イノリちゃんも\nカスミンも振袖姿が\nかわいかったな～", 1, 128401, 0, 0, 7850);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "シオリンに\nお年玉あげたいし\n彼にバイトを紹介\nしてもらおうかな？", 1, 128401, 0, 0, 7851);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "今度はどんな凧を\n飛ばそうかな？\nみんなが驚くような\n凧がいいよね～", 1, 128401, 0, 0, 7852);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ひらめいた！\n彼への年賀状は\nきらーんっ☆って\n感じにしよう！", 1, 128401, 0, 0, 7853);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "来年も彼の隣で\n初日の出が\n見られるといいな～", 1, 128401, 0, 0, 7854);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日はキミが\nギルドハウスに来る\n予知夢を見たんだよ～\nふふ、正夢になったね", 1, 128401, 0, 0, 7855);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "この振袖どうかな？\nすっごくかわいいよね\nえへへ、ありがとう～", 1, 128401, 0, 0, 7856);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ハツネちゃんおみくじ\n開始！　きらーんっ☆\nキミは大吉なのだ～\nどう元気出たかな？", 1, 128401, 0, 0, 7857);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "今度エルフの森にある\n薬草を使って七草粥を\n作ろうと思うんだ～\nぜひ食べてほしいな♪", 1, 128401, 0, 0, 7858);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お正月っぽい遊びを\n色々と用意したのだ～\nたまにはギルドハウス\nでゆっくり過ごそうよ", 1, 128401, 0, 0, 7859);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "もしかして眠たいの？\n…じゃあ、また膝枕\nしてあげてもいいよ？", 1, 128401, 0, 0, 7860);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "いっぱい寝たから\n元気いっぱいだよ～\n今日もがんばろう！", 1, 128401, 0, 1, 7861);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼だね～\nおせちがあるから\nキミも食べるでしょ？", 1, 128401, 0, 2, 7862);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ寝る時間だね\n今日はどんな夢を\n見られるかな～", 1, 128401, 0, 3, 7863);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "いい座り心地～\n寝正月で過ごすのも\n最高なのだ～", 1, 128401, 0, 0, 7865);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいな～\n癒されてぐっすり\n眠れそうだよ～", 1, 128401, 0, 0, 7866);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り～\nリラックスすると\n眠たくなっちゃうよ…", 1, 128401, 0, 0, 7867);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ポカポカいい気持ち～\n初日の出の温もりを\n思い出しちゃうな～♪", 1, 128401, 0, 0, 7868);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ、おいし～\nでもいっぱい食べたら\n眠くなっちゃった…", 1, 128401, 0, 0, 7870);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ\nお正月料理も\n色々あるんだね～\n今度作ってみようかな", 1, 128401, 0, 0, 7871);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "最近カレを見てたら\n何故かおいしそうに\n思えてくるんだよな…", 1, 106501, 0, 0, 7873);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "手握っててくれるか？\nじゃないとオレ…\n力が抑えきれない…", 1, 106501, 0, 0, 7874);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "つかの間の平和を享受\nしながらぬくぬくと\n読書に耽る…\nふふ、最高だね", 1, 128501, 0, 0, 7875);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "お正月飾りなんて\n置いたらはしゃいでる\nように見えるかな…？", 1, 128501, 0, 0, 7876);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ま、まずい…\n一人遊びしすぎて\nお正月遊びをほぼ\n極めつつある…", 1, 128501, 0, 0, 7877);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ミステリーは\n時と場所を選ばない\nつまり…新年でも\n探偵は休まないよ！", 1, 128501, 0, 0, 7878);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "お世話になった人に\n年賀状でも書こうかな\n助手くん、喜んで\nくれるかな…えへへっ", 1, 128501, 0, 0, 7879);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "絵馬に願い事を書こう\n助手くんと一緒に\nいられますように…♪\n…は、恥ずかしいな", 1, 128501, 0, 0, 7880);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "助手くんはもっと\n派手な着物のほうが\n好みだったかな…？\nき、気になる…", 1, 128501, 0, 0, 7881);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "やあ。助手くんも\nお正月休みを\n持て余してるのかい？\nふふ、似た者同士だね", 1, 128501, 0, 0, 7882);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "助手くん助手くん！\n凧あげしにいこう！\n…そ、捜査の一環で", 1, 128501, 0, 0, 7883);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "着物は転びそうで\n怖いんだよなあ…\nお、押さないでね？\nフリじゃないよ！？", 1, 128501, 0, 0, 7884);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ひ、人目を憚る\n本を読むなら\nみんなが帰省中の今！\nはっ！　助手くん！？", 1, 128501, 0, 0, 7885);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ね、ねえ…助手くん…\n一緒に初詣いかない？\nあ、いや！　深い\n意味はないんだけど！", 1, 128501, 0, 0, 7886);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あはは…助手くんと\n一緒だと家でごろごろ\nしてるだけでも\n楽しいや…♪", 1, 128501, 0, 0, 7887);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふぁ～…\nお正月休みのおかげで\n昼夜逆転中だよ…", 1, 128501, 0, 1, 7888);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お正月も依頼が\nひっきりなしだね\nさあ、街へ出よう！\nもちろん君も一緒にね", 1, 128501, 0, 2, 7889);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "も、もっと\n近くにきてもいいよ？\n冬の夜は…寒いからね", 1, 128501, 0, 3, 7890);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ううぅ～…！\nこのままじゃ\n寝正月だぁ…！", 1, 128501, 0, 0, 7892);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "みんなが帰省中でも\nこれがあれば\n寂しくない…かな", 1, 128501, 0, 0, 7893);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "うーん…♪\nお正月休みの\nリフレッシュに\nちょうどいいや♪", 1, 128501, 0, 0, 7894);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ふぅ…あったまるな\n冬は寒いから\n助かるよ…", 1, 128501, 0, 0, 7895);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "うーん、おいしい♪\n読書のお供に\nちょうどいい", 1, 128501, 0, 0, 7897);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "時間に余裕があると\n読書が進むよ\nいざ、本棚読破だ♪", 1, 128501, 0, 0, 7898);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この新しい力…\nさらに使いこなせる\nようになるには…", 1, 128801, 0, 0, 7900);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "私に眠る属性の力…\n風の力以外には\nどんな力があるのかな", 1, 128801, 0, 0, 7901);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "今の私なら\nどこまでいけるのか…\nやれるだけ\nやってみよう", 1, 128801, 0, 0, 7902);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "風の力の制御…\n段々とコツが\n掴めてきたな", 1, 128801, 0, 0, 7903);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "風の力か…\n応用の幅は広そうだ\n何ができそうか\n色々試してみよう", 1, 128801, 0, 0, 7904);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "今度、私とキミで\n料理対決でもする？\n簡単には負けないよ", 1, 128801, 0, 0, 7905);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "この胸に溢れる\n温かな気持ちは…\nきっと彼への…", 1, 128801, 0, 0, 7906);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "一段と剣技が\n冴えてきたような…\nいや…油断禁物だ", 1, 128801, 0, 0, 7907);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "かっこいいって？\nありがとう…そんなに\n真っすぐ褒められると\n照れてしまうな…", 1, 128801, 0, 0, 7908);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "どれほど厚い壁が\n立ち塞がろうと\n打ち破ってみせる", 1, 128801, 0, 0, 7909);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "手が空いてるなら\n剣の稽古に少し\n付き合ってくれるかな", 1, 128801, 0, 0, 7910);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "試練を乗り越えて…\n私の中にあるものが\nはっきりと分かったよ", 1, 128801, 0, 0, 7911);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "キミから流れてくる\n力の温かさ…これが\n私たちの絆なんだ", 1, 128801, 0, 0, 7912);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝だよ、そろそろ\n起きる時間だ\nそれとも私に起こして\nほしいのかな？", 1, 128801, 0, 1, 7913);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼食は私が作るよ\nリクエストはある？\nできる範囲で応えるよ", 1, 128801, 0, 2, 7914);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おやすみ。また明日も\n一緒に冒険しよう\n約束だよ？", 1, 128801, 0, 3, 7915);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "休める時は休む…\n戦い続けるには\n必要なことだからね", 1, 128801, 0, 0, 7917);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "心の安らぎの大切さ…\nそれを知れたのは\nキミたちのおかげだね", 1, 128801, 0, 0, 7918);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "気持ちが落ち着くな…\nこの香り、風の力で\n纏えたりしないかな", 1, 128801, 0, 0, 7919);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "暖まった空気の流れ…\n以前より風の変化に\n気づくようになったな", 1, 128801, 0, 0, 7920);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "この味付け…\n今度試してみようか\n味見は任せたからね", 1, 128801, 0, 0, 7922);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "心技体、すべてを\n鍛えるには座学も\n必要だからね", 1, 128801, 0, 0, 7923);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "瞑想するのに\nいいところはあるかな\n集中できて…お昼寝は\n我慢できるところ", 1, 128901, 0, 0, 7925);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ここにはあったかい\n空気が流れてるなぁ…\nみんなが受け入れて\nくれるおかげだね", 1, 128901, 0, 0, 7926);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "まるで心の中に\n光が満ちてるみたい…\nこの気持ち、みんなに\nおすそ分けしたいな♪", 1, 128901, 0, 0, 7927);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "この衣装は属性の力を\n反映しやすいんだよね\nキラキラしてるのも\n納得だよ", 1, 128901, 0, 0, 7928);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "エルフの里のみなさん\n元気かなぁ…\nまた会いに行きたいな", 1, 128901, 0, 0, 7929);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "まだ変身できてる…\nわたしと騎士クンの\n修行の成果\n出てるなぁ…ふふっ♪", 1, 128901, 0, 0, 7930);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "この服を脱いだら\nどうなるのかな…\nた、試す勇気は\nないけど…", 1, 128901, 0, 0, 7931);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふぅ…あ、騎士クン\nちょうど瞑想してたの\n一緒に…する？", 1, 128901, 0, 0, 7932);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "不思議だけど\nいつの間にか\n出たり消えたりするの\n…背中の輪っか！", 1, 128901, 0, 0, 7933);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "この服って肌触りが\nとってもいいんだよ\nさ、触ってみる？\nスベスベだよ？", 1, 128901, 0, 0, 7934);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "アストラルの力…\nすごく持続できてるね\n修行の成果が出てるよ", 1, 128901, 0, 0, 7935);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "この力があれば\n暗いところで\n落とし物をしても\n見つけやすいかも…？", 1, 128901, 0, 0, 7936);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "冒険の準備なら\nできてるよ\nいつでも声をかけてね\n…楽しみにしてる！", 1, 128901, 0, 0, 7937);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう騎士クン\n一緒にお散歩とか…\nどうかな？", 1, 128901, 0, 1, 7938);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ご飯のあとの\n瞑想って難しいんだよ\n眠くなっちゃって…", 1, 128901, 0, 2, 7939);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜ふかしさんは\nほどほどにね？\n一日頑張った自分を\n休ませてあげないと", 1, 128901, 0, 3, 7940);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "のんびりしてたら\nケーキが食べたく\nなっちゃうなぁ…\nでも太る…よね…？", 1, 128901, 0, 0, 7942);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "わあ、かわいい…！\n見てるだけで\nにやけちゃう…♪", 1, 128901, 0, 0, 7943);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "これは…花の香りかな\n知ってる花かも…？\n当ててみようっ", 1, 128901, 0, 0, 7944);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかいと\nどうしてこんなに\n落ち着くんだろう…", 1, 128901, 0, 0, 7945);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食べ過ぎたらお腹が\n目立っちゃうかもって\n分かってるのに…！\n止められないよ～っ！", 1, 128901, 0, 0, 7947);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "こ、恋の精霊とか\nいたりするのかな…？\nはっ！　ダメダメっ！\n実力で頑張らないと", 1, 128901, 0, 0, 7948);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "お部屋の中でも\n修行、修行っ♪\nでも燃やさないように\n注意しなきゃだね", 1, 128701, 0, 0, 7950);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "うーん…この衣装\n厚着か薄着か\nどっちなんだろう…？", 1, 128701, 0, 0, 7951);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "いつもの肉球がない分\nお片付けしやすいな♪\n騎士くんのお部屋\nピカピカにしとこー！", 1, 128701, 0, 0, 7952);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お休みは騎士くんと\nＢＢＱに行きたいなー\nあたしと一緒なら\n火の心配はいらないよ", 1, 128701, 0, 0, 7953);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "この姿ならもっと\n人を助けられる…！\nえへへっ！\n燃えてきたーーっ！", 1, 128701, 0, 0, 7954);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "騎士くんが帰ったら\nアイラみたいな笑顔で\nお疲れさまさまって\nお出迎えしよっと…♪", 1, 128701, 0, 0, 7955);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "この姿の時、いつも\n胸が熱く燃えてるのは\nずっと騎士くんのこと\n考えてるからかな…？", 1, 128701, 0, 0, 7956);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "騎士くん騎士くん！\nあたしに触れると\nやけどしちゃうよ…？\nなんちゃってー♪", 1, 128701, 0, 0, 7957);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おっ、騎士くん\n修行に行きたいの？\nえへへっ、いいねー♪\n二人で燃えちゃおー！", 1, 128701, 0, 0, 7958);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そうだ騎士くん\nじゃんけんしよっか？\nグローブ外してるから\nチョキも出せるよっ♪", 1, 128701, 0, 0, 7959);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "この姿でいられる時間\nすごく増えてきた…！\nえへへ！　あたしたち\n修行の成果出てるね！", 1, 128701, 0, 0, 7960);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "じっと見つめないでよ\n顔が真っ赤に…やば！\nほんとに顔から\n火噴いちゃいそう…！", 1, 128701, 0, 0, 7961);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "火には強くなれても\n騎士くんに触られた\nほっぺはずーっと\n熱くてたまんないや…", 1, 128701, 0, 0, 7962);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよー騎士くん！\n今日も一日\n燃え滾っていくよー！\nファイヤーッ！！", 1, 128701, 0, 1, 7963);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "騎士くんお昼だよ！\nちゃんとご飯食べて\n午後からの修行も\n乗り切ろうねー！", 1, 128701, 0, 2, 7964);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日もお疲れさま！\nそうだ、寝る前に\nキャンプファイヤー\n囲んじゃおっか♪", 1, 128701, 0, 3, 7965);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ぼふーんっ！\nえへへ、気持ちいい…\n修行の前に\nちょっと休憩ー♪", 1, 128701, 0, 0, 7967);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいな～♪\nなでなでなでなでなで\nなでなでなでなでっ！\nあははっ、摩擦熱！", 1, 128701, 0, 0, 7968);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ん～いい香り♪\n少し熱したほうが\n香りが広がるね…って\n蒸発しちゃった！！！", 1, 128701, 0, 0, 7969);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "外でも自分の火で\nあったまれるけど\nお部屋でぬくぬく\nするのが一番だよね♪", 1, 128701, 0, 0, 7970);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐっ！\nお腹が減っては\n人助けはできずっ！\nもぐもぐもぐっ！", 1, 128701, 0, 0, 7972);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ…\nなるほどなるほど…\n…これが上手な\nＢＢＱのやり方か…", 1, 128701, 0, 0, 7973);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "…壁も扉も柱も\n全て記録で見たまま\n本当に…来ているのね", 1, 129001, 0, 0, 7975);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "…騒がしい場所\n騎士クンが受け入れて\nくれるのをいいことに", 1, 129001, 0, 0, 7976);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ここが…騎士クンの\n守りたかった場所\n騎士クンの思い出が\n詰まった場所…ね", 1, 129001, 0, 0, 7977);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "視線を感じる…\nこちらの様子を\n探るような…心の動き\n取るに足らないけれど", 1, 129001, 0, 0, 7978);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "…そこかしこで…\n言葉にもしたくない\n相手が過ごしていた\n記録を思い出す…", 1, 129001, 0, 0, 7979);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "人は多いけれど…\n雪深い山中よりは\n過ごしやすい…か", 1, 129001, 0, 0, 7980);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "自覚したことは\nあまりなかったけれど\nひどく…諦めの悪い女\nなのかもしれない", 1, 129001, 0, 0, 7981);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お招きありがとう\nそれで…何をして\nいればいい…かな？", 1, 129001, 0, 0, 7982);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ここは…明るいね\nわたしの城と比べると\nなんだか眩しいくらい", 1, 129001, 0, 0, 7983);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "仮面はもう必要ないよ\nだって…わたしの顔を\n騎士クンに見て\nもらえなくなるから", 1, 129001, 0, 0, 7984);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "騎士クンさえよければ\nわたしの城に専用の\n部屋を用意するよ\n…いつでも", 1, 129001, 0, 0, 7985);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "…騎士クンのマント\nまた貸してほしいな\nきれいに使うから\n…だめ？", 1, 129001, 0, 0, 7986);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "いつか二人の願いが\n重なり合えるって…\n信じているね\n…いつまでだって…", 1, 129001, 0, 0, 7987);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう、騎士クン\n…昨日は夢の中で\nお話ししすぎちゃって\nごめんね。ふふっ", 1, 129001, 0, 1, 7988);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹は…空いてない？\n食べ物はないけれど\n空腹を忘れる魔法なら\nかけてあげられるよ", 1, 129001, 0, 2, 7989);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "騎士クン…\nまだ、眠らないの？\n…そう。それなら…\nわたしも起きているね", 1, 129001, 0, 3, 7990);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "肩の力を抜くには…\nまだ時間がかかりそう\nきっと…騎士クンと\n二人きりなら別なのに", 1, 129001, 0, 0, 7992);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ぺんぽこりん…\nそう、確かあれも\nこんな感じだった…", 1, 129001, 0, 0, 7993);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "花の香りは…好き\nつかの間\n心を穏やかに\nしてくれるから", 1, 129001, 0, 0, 7994);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あたたかい…けれど\n騎士クンの優しさに\n比べれば、まだまだ", 1, 129001, 0, 0, 7995);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おい、しい…？\nこの感覚が、それ？\nなぜか…納得できる", 1, 129001, 0, 0, 7997);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "情報を入手するには\nわざわざ本を開く\n必要があるだなんて…\nプレイヤーは面倒ね", 1, 129001, 0, 0, 7998);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "メルクリゾートか…\n良い記憶はないな\nよし忘れよう", 1, 129301, 0, 0, 8000);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "知性の戦士ユニ！\nその恐るべき筋力！\nふおお！　うにゃー！", 1, 129301, 0, 0, 8001);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ぽーん！\n石用の水着ください！\nセクシーロゼッタが、\n渚の視線を独占です！", 1, 129301, 0, 0, 8002);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "学院から奨学金を\n勝ち取るより某財団を\nだまくらかした方が\n早い気がしてきたな…", 1, 129301, 0, 0, 8003);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "わんつぅ、わんつぅ…\nんぎゃあ足攣ったー！\nおのれカルミナとやら\n絶対に許さん！", 1, 129301, 0, 0, 8004);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ところで…なぜぼくは\nプールでもないのに\n水着のままなんだ…\nおのれ世界め！", 1, 129301, 0, 0, 8005);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "彼と二人で撮った動画\nうう、凝視に耐えん…\nなんだこのムズ痒さは", 1, 129301, 0, 0, 8006);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "なに？　水着姿で\n寒くないのかだと？\n普段からもっと薄着の\n娘が沢山いるだろう", 1, 129301, 0, 0, 8007);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "シノブ君にメリゾの\n招待状を送ったのだが\n御尊父の暴走を\n心配していたな…", 1, 129301, 0, 0, 8008);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ミミ君らにメリゾの\n招待状を送ったのだよ\n迎える準備をせねば…\nおしゃぶり持ってる？", 1, 129301, 0, 0, 8009);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "本質の賢者…？\nいや元気にしているが\nなぜ君がぼくの身内を\n知っているんだ…？", 1, 129301, 0, 0, 8010);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "水着が似合ってる？\nな、なんだね突然…\nやめたまえよふひひ…", 1, 129301, 0, 0, 8011);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "今度は夏にメリゾへ\n行きたいものだ\nむろん君も一緒だぞ", 1, 129301, 0, 0, 8012);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ぐああっ、朝陽が…！\n朝陽が昇っている…！\n夜行性ユニ死んじゃう", 1, 129301, 0, 1, 8013);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "はぁ…もう昼か…\nそろそろ寝ないとな\n規則正しい生活を\nしないと不健康だ…", 1, 129301, 0, 2, 8014);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ひゃっはー、夜だー！\nオレたちの時間だぜ！\nふおおブチ上がり～！", 1, 129301, 0, 3, 8015);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "これは…ぼくにここで\n寝ろということか？\n一向に構わんが…", 1, 129301, 0, 0, 8017);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "きゃっきゃっ！\nこれかわい～！\n…よし、今日も\n子供の擬態完璧だな", 1, 129301, 0, 0, 8018);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ふむ、良い香りだ\nだがそれだけか…\nとくに精神高揚効果は\nないのか…ちぇー", 1, 129301, 0, 0, 8019);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "火を見ていると…\n魔導罐を思いだすな…\nかに座、元気かな…", 1, 129301, 0, 0, 8020);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ええい、\n固形食物はいらん！　\nポーションを出せ！", 1, 129301, 0, 0, 8022);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "やはり書は文系に限る\nなんと心地よい筆致…\nぐああ突然理系文が！\nひぃ目が理系になる！", 1, 129301, 0, 0, 8023);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "ほああ～！\n知性の海上騎士ユニ！\nこれは新たな可能性！", 1, 129301, 0, 0, 8025);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "これは…なんだ？\n何が面白いんだ？\n難しいな…", 1, 129301, 0, 0, 8026);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "大切な人と過ごす\n正月の思い出、か…\n昔の私だったら\n考えられなかったな", 1, 108901, 0, 0, 8027);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "叶えたい願いなら\nたくさんあるよ\nそれでも一番を選ぶ\nなら、やはりキミと…", 1, 108901, 0, 0, 8028);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "神殿にあった\n恋愛おみくじ…\n引いてみようかな…", 1, 108801, 0, 0, 8029);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "騎士クン。来年も\nまた一緒におみくじ\n結ぼうね。約束だよ", 1, 108801, 0, 0, 8030);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "今度は騎士くんと\n一緒にうつった写真、\nおばあちゃんに\n送ろうっと♪", 1, 108701, 0, 0, 8031);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "あ、騎士くん！\n今年も…ううん\nこれからも、よろしく\nおねがいします♪", 1, 108701, 0, 0, 8032);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "旧校舎の地下牢…\n真冬のサマー計画…\n等身大のＰＲ…\nうッ、頭が…！", 1, 129401, 0, 0, 8033);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "暇だし鏡でも見るか。\nお、いい腹筋育って…\nあ？　何見てんだコラ", 1, 129401, 0, 0, 8034);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "オレは金色の疾風！\nんん…なんか違うな。\n我が名は金色の…\nあ？　何見てんだコラ", 1, 129401, 0, 0, 8035);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "モニカとユニ先輩って\n口調と身長似てるけど\n子供扱いに対する\n反応は真逆だよね…", 1, 129401, 0, 0, 8036);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "シオリン元気かな…\n昔くちゃくちゃに\n撫でくり回して\n嫌がられたっけなァ…", 1, 129401, 0, 0, 8037);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "べつにいんだけどさ…\nあんたの知り合いって\n普段から水着みたいな\nカッコの女多くない？", 1, 129401, 0, 0, 8038);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "そだ、弟らがあんたに\n会いたがってたンだ。\n暇だったらいつでも\nウチ来てやってよ", 1, 129401, 0, 0, 8039);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "特別講座は色々あった\nけど…メリゾ自体は\nまあ悪くなかったよね", 1, 129401, 0, 0, 8040);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "水着と合わせる小物に\nセンス出るよね、\nって話をミィコ先輩が\nしててマジわかりみ", 1, 129401, 0, 0, 8041);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "水着のミフユねえさん\nやっぱ仕上がってたね\nあれが竜殺しの体か…\nバリかっけーな…", 1, 129401, 0, 0, 8042);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "はにょんっ！？\nや、だからさ…\n後ろから声かけんな、\nつってンじゃん…", 1, 129401, 0, 0, 8043);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "メリゾの特別講座が\n上手くいったのも\n敏腕カメラマンがいた\nお陰だよ。ありがとね", 1, 129401, 0, 0, 8044);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あ？　この水着が？\n似合っ…え、なんて？\nごめ、聞こえんくて。\nもっかい言ってみて", 1, 129401, 0, 0, 8045);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "もう朝とかマジないわ\n昨日二人に付き合って\nオールでカラオケだよ", 1, 129401, 0, 1, 8046);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "はぁ授業行かなきゃ…\n真っ昼間から勉強とか\nマジつらたん過ぎ…", 1, 129401, 0, 2, 8047);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日これから夜勤で…\nいやバイトちゃーくて\nボランティアの話よ？\n校則違反よくない", 1, 129401, 0, 3, 8048);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "うわ、ふっかふか…\nオニほど安らぐわ…\nやば、ユニってくる…", 1, 129401, 0, 0, 8050);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "うちも妹いりゃ\nこーゆーのもなァ…\nま自分用でもいいか", 1, 129401, 0, 0, 8051);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ふーん…\nいいじゃんこの香り\n抜群に嗅げるわ", 1, 129401, 0, 0, 8052);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "うちン家のルーツの森\n大火災でなくなった\nらしンだよね…\n生まれる前の話だけど", 1, 129401, 0, 0, 8053);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "何コレありがてぇー\n食料ほくほく過ぎて草\n米ガチで尊いわァ…", 1, 129401, 0, 0, 8055);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "いいけど、なんでうち\n水着で本読んでンだよ\nどーゆープレイだよ", 1, 129401, 0, 0, 8056);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "金色の海上騎士クロエ\n推して参る！　覇ァ！\nあ？　何見てんだコラ", 1, 129401, 0, 0, 8058);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "何コレ、貝の椅子？\nどーやって遊ぶんだ…\nいや座って終わりか…\nまァそりゃそーか…", 1, 129401, 0, 0, 8059);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "さてと…\n明日の訓練メニュー\n考えねえとな", 1, 129801, 0, 0, 8060);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "また新入りの女子に\n弁当もらっちまった…\nありがたく食うけどよ", 1, 129801, 0, 0, 8061);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "種族なんて関係なく\nみんなが力を合わせて\nランドソルを守る…\nいい時代になったよな", 1, 129801, 0, 0, 8062);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "誰にだって長所はある\n新入りのいいところを\n見つけてやるのも\n教官の仕事だ", 1, 129801, 0, 0, 8063);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "厳し過ぎても\n甘過ぎてもダメ…\n教官ってのは難しいぜ", 1, 129801, 0, 0, 8064);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "戦いが苦手な新入りを\nどうフォローするか…\n後であいつと\n相談してみるか", 1, 129801, 0, 0, 8065);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あいつは優し過ぎて\n戦いに向いてねえ\n…そういう甘さ\n嫌いじゃねえけどな", 1, 129801, 0, 0, 8066);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "強くなる近道はねえ\n地道な鍛錬あるのみだ\nさ、訓練始めるぞ！", 1, 129801, 0, 0, 8067);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "新入りにも\nいつも言ってるが…\n装備の手入れは\n念入りにしろよな？", 1, 129801, 0, 0, 8068);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "座学も受けてえのか？\nいい心がけだな！\nなんでも教えてやるよ\n…魔法以外ならな", 1, 129801, 0, 0, 8069);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "新入りたちがよく\n恋バナしててな…\nお、おまえは…誰か\n気になるやついるか？", 1, 129801, 0, 0, 8070);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "なあ、ストレッチ\n手伝ってくれねえか？\n訓練前にしっかり\n筋肉ほぐさねえと…", 1, 129801, 0, 0, 8071);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ずいぶん頑張って\n鍛えたよな、おまえ\nよし！　ご褒美に\nお菓子作ってやるよ♪", 1, 129801, 0, 0, 8072);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "訓練日和だな！\nさぁて…まずは\n走り込みといくか！", 1, 129801, 0, 1, 8073);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼飯はしっかり食えよ\nでなきゃ、\nこの後もたねえぜ？", 1, 129801, 0, 2, 8074);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "とっくに消灯時間だ\nさっさと寝な？\n明日も早いんだからよ", 1, 129801, 0, 3, 8075);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "休むのも訓練のうちだ\n今はのんびり\nさせてもらうぜ", 1, 129801, 0, 0, 8077);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "いい面構えだ\n気に入ったぜ！\nあたしの班に入るか？\n…なんてな♪", 1, 129801, 0, 0, 8078);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "…いやされる匂いだな\n新入りたちにも\nすすめてみるか…", 1, 129801, 0, 0, 8079);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったけえからって\n寝ないようにしねえと\n教官としての\n威厳に関わるからな…", 1, 129801, 0, 0, 8080);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食事も訓練の一環だ\nとはいえ食い過ぎには\n気をつけねえと…", 1, 129801, 0, 0, 8082);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "トーゴクの剣術…か\nなにか訓練に\n活かせるかもしれねえ", 1, 129801, 0, 0, 8083);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "あのおかたに近付く\n不埒な輩には、特別な\n訓練で地獄を見て\nいただきましょう", 1, 129901, 0, 0, 8085);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "これだけ広ければ\n多少派手に\n動き回っても\n問題なさそうですね", 1, 129901, 0, 0, 8086);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "…今誰か私を\n「鬼」教官と\n呼びませんでしたか？", 1, 129901, 0, 0, 8087);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "新しく開発したこの薬\n誰か試してくれる人は\nいませんか？", 1, 129901, 0, 0, 8088);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "厳しくすれば投げ出し\n優しくすればサボる\n人というのはどこまで\n度し難いのでしょう", 1, 129901, 0, 0, 8089);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "はじめましょう\nあのおかたの心を\n射貫くための\nシミュレーションを", 1, 129901, 0, 0, 8090);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あらゆる苦難と\n忌々しい女から守る\nためにも、私自身も\n鍛えておかねば", 1, 129901, 0, 0, 8091);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あなた様、そんなに\n見つめられると…え？\nエリコはカッコいい？\nええ、当然ですとも", 1, 129901, 0, 0, 8092);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "不調があればすぐ\n報告してください\n体のケアも教官の\n大事な役目ですので", 1, 129901, 0, 0, 8093);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "新しい訓練器具の\n使い心地はどう…え？\n重すぎる？　これでも\n軽くしたのですが…", 1, 129901, 0, 0, 8094);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "運動後には特製の\n栄養ドリンクをどうぞ\nクスクス、何も\n入れたりしてませんわ", 1, 129901, 0, 0, 8095);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "よくがんばりました\nあなた様。あぁ…\nお疲れになったお顔も\n素敵ですわ", 1, 129901, 0, 0, 8096);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あなた様、二人だけの\n遠征訓練へ\nまいりましょう。\n既に準備万端ですわ", 1, 129901, 0, 0, 8097);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "まだ眠いですか？\nならばストレッチで\n体を痛めつ…ではなく\nほぐしていきましょう", 1, 129901, 0, 1, 8098);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼はお弁当をご用意\nいたしました。量も\nスタミナも増し増し\n残さず食べてください", 1, 129901, 0, 2, 8099);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "よい睡眠こそ健やかな\n体に不可欠。ですので\n私が寝ずの番をさせて\nいただきますわ", 1, 129901, 0, 3, 8100);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "休憩用に使おうと思い\nましたが、心地よくて\n立てなくなって\nしまいますわ…", 1, 129901, 0, 0, 8102);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "中に重しを詰めれば\n愛でながら運動が\n可能ですわ", 1, 129901, 0, 0, 8103);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "香りでリラックスさせ\n同時に暗示を\nかけてみましょうか", 1, 129901, 0, 0, 8104);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "…くっ、眠気を誘う\nこの暖かさ…\n油断も隙もありません", 1, 129901, 0, 0, 8105);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "主食はこちらで十分\nまかなえますわね\nそれでは私はおかずを\n作りましょう", 1, 129901, 0, 0, 8107);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "まあ、実用書の類も\n揃っているのですね\nとても助かりますわ", 1, 129901, 0, 0, 8108);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "……（そわそわ）", 1, 129601, 0, 0, 8110);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ここに寄らずの花陣…\n作ったらダメですよね", 1, 129601, 0, 0, 8111);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "部屋の隅が\n落ち着きます\nそれか、陽の当たる所", 1, 129601, 0, 0, 8112);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "身を隠せる場所が\nあると…\n助かるんですけど", 1, 129601, 0, 0, 8113);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "複雑な造りの家ですね\n触って壊れたり─\nしませんか？", 1, 129601, 0, 0, 8114);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "出入りするひと\nみんな、笑顔…\n…変わった家ですね", 1, 129601, 0, 0, 8115);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "この家なら安全─\nかもしれません\n魔物が出ないので", 1, 129601, 0, 0, 8116);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "これも、視察の一環\n遊びに来たわけじゃ\nないです", 1, 129601, 0, 0, 8117);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "長話─苦手です\n疲れるので…\nふぅ…", 1, 129601, 0, 0, 8118);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ここで友達を作れと\nネアさんが…\nそう、言われても…", 1, 129601, 0, 0, 8119);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "世話をするのは\n得意です\n…花の、ですよ？", 1, 129601, 0, 0, 8120);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "媛へのお土産を\n探してるんですけど…\n…貴方のおすすめ、\n聞いておきます", 1, 129601, 0, 0, 8121);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "平和でのんきで…\n貴方らしい家です\n一応、褒めてます", 1, 129601, 0, 0, 8122);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "花に、お水─？\n…いりません", 1, 129601, 0, 1, 8123);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "日が高いうちは\nむやみに外へ出ません\n面倒事、多いので…", 1, 129601, 0, 2, 8124);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜番。私がします\nあまり眠らない\n性質なので…", 1, 129601, 0, 3, 8125);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ここなら根を張れる\nかもしれません\n…張りませんけど", 1, 129601, 0, 0, 8127);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "こんなにやわな体じゃ\n身を守れませんよ─\n…あ。生き物じゃ\nないんですね", 1, 129601, 0, 0, 8128);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "花みたいに─\nいい匂い、です", 1, 129601, 0, 0, 8129);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "火を見てると、\nジオ・ゲヘナを\n思い出します…ふぅ", 1, 129601, 0, 0, 8130);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食事も立派な戦支度\n媛が言ってました", 1, 129601, 0, 0, 8132);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "知識も武器の一つだと\n媛が…でも、\nこれでどうやって…？", 1, 129601, 0, 0, 8133);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "天気もいいしお花畑に\nピクニックでも\n行こうかな♪", 1, 130701, 0, 0, 8135);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "あ、どこからか\nお花の匂いが…\nいい香りですね", 1, 130701, 0, 0, 8136);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "新しいシャベルとか\nじょうろもほしいなぁ\nお小遣いしっかり\nためないとね", 1, 130701, 0, 0, 8137);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お花飾りたいけど\n花瓶はどこかな…\nあとであの人に\n聞いてみよっと", 1, 130701, 0, 0, 8138);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "お花の観察日記\n書かなきゃ\n日々勉強は\n欠かせませんよ", 1, 130701, 0, 0, 8139);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "衣装にお花を足して\nみたけど、あの人\n気付いてくれるかな？", 1, 130701, 0, 0, 8140);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "この花冠、上手に\n作れたかも…\n日頃のお礼にあの人に\nあげようかな…", 1, 130701, 0, 0, 8141);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あなたは何のお花が\n好きですか？　ほら、\n一応知っておいたら\n役に立つかもですし", 1, 130701, 0, 0, 8142);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "そのお花、乱暴に\n扱っちゃダメですよ\n花粉が服について\nとれなくなりますから", 1, 130701, 0, 0, 8143);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "土いじりしたから\n服が汚れてますよ\nはたいてあげますから\nじっとしててください", 1, 130701, 0, 0, 8144);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "そんなにすぐに芽は\n出ませんよ\nまあ、楽しみなのは\n私も同じですけど…", 1, 130701, 0, 0, 8145);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "この衣装、そんなに\n気になります？　なら\nこうしてお花を\n着ければおそろいです", 1, 130701, 0, 0, 8146);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お花の種を私に？\nありがとうございます\nせっかくなので一緒に\nお世話しませんか？", 1, 130701, 0, 0, 8147);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お花にお水をあげるの\n手伝ってもらえます？\nお水は朝にあげるのが\nいいんですよ", 1, 130701, 0, 1, 8148);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "とっておきのお花見\nスポットに\nご案内しますよ\nお弁当も忘れずに！", 1, 130701, 0, 2, 8149);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もうこんな時間\n早く寝ましょう\n草木も眠るなんとか\nって言いますからね", 1, 130701, 0, 3, 8150);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "お花のお手入れって\nけっこう疲れますね…\nここでちょっと一息\nしちゃおっと", 1, 130701, 0, 0, 8152);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "耳にお花を着ければ…\nえへへ、すっごく\nかわいくなったね！", 1, 130701, 0, 0, 8153);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "これはラベンダー\nこっちはミモザ\nフローラル系の香り\nっていいですねぇ", 1, 130701, 0, 0, 8154);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ポカポカしますね～\nまるで春の陽気\nみたいです～", 1, 130701, 0, 0, 8155);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "お花を一輪さすだけで\nご飯の時間がとても\n華やかになりますね", 1, 130701, 0, 0, 8157);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "お花の本が\nいっぱいある！\n今日はこれで\nお勉強です！", 1, 130701, 0, 0, 8158);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ふんふ～ん♪\n華やかな服を着ると\n心がウキウキします♪", 1, 130801, 0, 0, 8160);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "花祭りで出会った\nみなさん…\nお元気でしょうか？\nまたお会いしたいです", 1, 130801, 0, 0, 8161);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "はっ！　そうでした\nこの服の時は\nメイドのお仕事は\nお休みでした…", 1, 130801, 0, 0, 8162);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "この服は替えが\nありませんから\n大きなドジには\n気を付けないと…", 1, 130801, 0, 0, 8163);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "目立ったほつれもなし\n…うん、いい感じに\n補修できました♪", 1, 130801, 0, 0, 8164);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "メイド姿でなくても\n心はいつでも\nお嬢さまの\nメイドです♪", 1, 130801, 0, 0, 8165);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "この服を着ると心が\n浮き立つのはあのかた\nと一緒にいる気持ちに\nなるからでしょうか？", 1, 130801, 0, 0, 8166);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "はい、今日は一日\nこの服で過ごそうと\n思います\n変じゃないですよね？", 1, 130801, 0, 0, 8167);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "花祭りのおかげで\n少しだけお花に\n詳しくなった…\nような気がします！", 1, 130801, 0, 0, 8168);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "花祭り、今度は\nお嬢さまと救護院の\nみんなと一緒に\n行ってみたいですね", 1, 130801, 0, 0, 8169);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "今度キョウカちゃんと\n花祭りの服でお花を\n見にお出かけ\nするんです", 1, 130801, 0, 0, 8170);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "メイド服を全部洗濯\nしちゃうなんて…\nドジっちゃいましたぁ", 1, 130801, 0, 0, 8171);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "花祭りの服は私たちの\n思い出の服ですから…\nこれからも\n大切にします♪", 1, 130801, 0, 0, 8172);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "はう、そうでした\nお花にお水を\nあげる時間です！", 1, 130801, 0, 1, 8173);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ご飯は\nバスケットを持って\nお花畑に食べ\nに行きませんか？", 1, 130801, 0, 2, 8174);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふぁあ…繕い物を\nしていたらこんな時間\nになってしまいました\n早く寝ないと…", 1, 130801, 0, 3, 8175);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふわふわしてて\nきもちいいです～\nどんな生地を\nつかってるんだろ～？", 1, 130801, 0, 0, 8177);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいですね～\nぬいぐるみさんにも\n服をつくって\nあげたいです♪", 1, 130801, 0, 0, 8178);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りです～\nあれ？　もしかして\n私の服についてる花と\n同じ香りが…？", 1, 130801, 0, 0, 8179);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "暖かいですけど\nあまり近づいちゃうと\n頭の花飾りが乾燥\nしちゃいそうですね…", 1, 130801, 0, 0, 8180);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…\nいい花を咲かせるには\nしっかりとした栄養が\n必要だそうです！", 1, 130801, 0, 0, 8182);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "なるほどなるほど…\nお花のお手入れは\n奥が深いですね…", 1, 130801, 0, 0, 8183);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "マホマホ王国にも\nサーカス団設立や\n夢と希望を届けますえ", 1, 131001, 0, 0, 8185);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "せっかくの晴れ舞台や\nかっこいいポーズも\nできるようにしたいわ", 1, 131001, 0, 0, 8186);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "むむむむ～っ。うーん\nクルルはんみたいに\n胸から宝石を出すんは\n難しいみたいやわ", 1, 131001, 0, 0, 8187);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "あむっ…んん～♪\nやっぱり練習のあとは\n甘いものに限るわぁ", 1, 131001, 0, 0, 8188);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "アーサーたちの衣装も\n今のうちに考えんと…\n生地、足りるやろか", 1, 131001, 0, 0, 8189);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "王子はんとなら\nどんなアイデアも\n見つけられます♪", 1, 131001, 0, 0, 8190);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "うちの晴れ姿が\n王子はんの目に一等\n輝いて見えますように", 1, 131001, 0, 0, 8191);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "キリっとしたうちも\nかっこいい？\nもう、上手やなぁ", 1, 131001, 0, 0, 8192);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "新しい演目考えたんよ\nなぁ王子はん、意見\n聞かせてもらえます？", 1, 131001, 0, 0, 8193);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "聞いてや王子はん\n動物さんたちとさらに\n息が合うてきたんよ\nみんな頑張り屋さんや", 1, 131001, 0, 0, 8194);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "演技の感想なら\n大歓迎どすえ♪\nたんと聞かせてや～", 1, 131001, 0, 0, 8195);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "王子はん、本番当日は\n最前席で見たってな\nそしたらうち、もっと\n頑張れますさかい♪", 1, 131001, 0, 0, 8196);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "この技をあなたに\n捧げます…なんて♪\n驚いたやろ？\nどっきり作戦成功や♪", 1, 131001, 0, 0, 8197);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "素敵なショーのためや\n今日も焦らず一歩ずつ\n成長していきまひょ\nな、王子はん♪", 1, 131001, 0, 1, 8198);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お弁当、王子はんも\n一緒にいかがどす？\nみんなで食べて団結や", 1, 131001, 0, 2, 8199);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜のサーカスも\n幻想的でとっても\n魅力的なんよ\n一緒にいきまひょか♪", 1, 131001, 0, 3, 8200);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "練習が終わったあとは\nの～んびりして\n体力を回復せな…", 1, 131001, 0, 0, 8202);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "この子たちとなら\n空中ブランコや\n玉乗りもええなぁ", 1, 131001, 0, 0, 8203);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りやなぁ\n本番前の緊張も\n和らげてくれそうやわ", 1, 131001, 0, 0, 8204);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "このあったかい感じ…\nスポットライトの熱を\n思い出すわぁ", 1, 131001, 0, 0, 8205);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ちゃんと食べへんと\nいい演技はできまへん\n団長はんも言うてたわ", 1, 131001, 0, 0, 8207);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "動物さんたちのことも\nもっと勉強せな\n大事な仲間やさかい", 1, 131001, 0, 0, 8208);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "器用じゃないが、\n情には厚いよ\nこういう女を「一途」\nってそう言うんだろ？", 1, 105601, 0, 0, 8210);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "斬れないものはないと\n思ってきたさ。だけど\n…この気持ちだけは\n斬れないね、絶対に", 1, 105601, 0, 0, 8211);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "んしょ、んしょっ…！\n日頃の感謝を込めて\nヒーローさんのお家を\nきれいにしますです♪", 1, 130901, 0, 0, 8212);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ふむふむ…\n新アトラクションは\nこのギルドハウスを\nモチーフに…", 1, 130901, 0, 0, 8213);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ごそごそ、こそこそ…\nヒーローさんに内緒で\nどこかにお礼の宝石を\n隠しておきましょう…", 1, 130901, 0, 0, 8214);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "パークの運営が\n落ち着いたら\nわたしもギルド活動？\nしてみたいですます♪", 1, 130901, 0, 0, 8215);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "こんなすてきな\nおうちに住めたら…\nいえ！　うさぎ小屋で\n十分です～っ", 1, 130901, 0, 0, 8216);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ヒーローさんのおうち\nだって意識したら\nアトラクションよりも\nドキドキしてきます…", 1, 130901, 0, 0, 8217);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ヒーローさんのことを\n考えると顔が赤く…\nこれってもしかして\nひょっとして…？", 1, 130901, 0, 0, 8218);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あっ、ヒーローさん！\n話しかけてくれた記念\nということで、宝石\n受け取ってください♪", 1, 130901, 0, 0, 8219);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "元気がない時は\n語尾にぴょんですっ！\nさあヒーローさんも\nやってみるぴょん♪", 1, 130901, 0, 0, 8220);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ヒーローさんへのご恩\nおばあちゃんうさぎに\nなるまでに、お返し\nできるでしょうか…？", 1, 130901, 0, 0, 8221);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ヒーローさん！\n二人で一緒に\nパレードの練習\nしませんか～♪", 1, 130901, 0, 0, 8222);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あはは♪\nヒーローさんは\n人を笑顔にする力が\nありますです♪", 1, 130901, 0, 0, 8223);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ヒーローさんに\n一日一恩返しですっ！\n返し終わるまで\nやめませんですます♪", 1, 130901, 0, 0, 8224);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます♪\nんしょ、んしょっ…！\n気持ちよく起きられた\n記念に宝石どうぞ♪", 1, 130901, 0, 1, 8225);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼にフードコートで\nかばばん君バーガー\n買ってきましたよ！\n一緒に食べますです♪", 1, 130901, 0, 2, 8226);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日も一日\nお疲れさまですっ♪\nマッサージしますから\n寝そべってください♪", 1, 130901, 0, 3, 8227);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "はふぅ～…♪\nお仕事の疲れも\nぴょんぴょ～んって\n飛んでっちゃいます♪", 1, 130901, 0, 0, 8229);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "わぁっ、とっても\nかわいいですますっ！\nギルドハウスの\nマスコットですね♪", 1, 130901, 0, 0, 8230);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ヒーローさんの好きな\n香り…これを宝石に\nつければ、受け取って\nもらえるでしょうか？", 1, 130901, 0, 0, 8231);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "はあ、気持ちいい♪\nヒーローさんの\n好きな温度に\n調整しときますです♪", 1, 130901, 0, 0, 8232);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "支配人は体が資本っ！\nたくさん食べ…すぎて\n動けなくなっちゃい\nましたぁ～…！", 1, 130901, 0, 0, 8234);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "パークの\nガイドブックとか\nあったらいいですね♪", 1, 130901, 0, 0, 8235);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "外あつすぎ溶けるわ～\nやっぱ部屋ん中で\n水着がラクだねー", 1, 131101, 0, 0, 8237);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ン～\nカリザきゅんどこー？\nもしかして逃げた？", 1, 131101, 0, 0, 8238);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ミソラちゃんと\nリリちゃん誘って\nそろそろイイコト\nしよっかなー？", 1, 131101, 0, 0, 8239);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "おねえちゃんに\n頼まれたシゴトは\nまた今度にすっかー\n夏休みだしー♪", 1, 131101, 0, 0, 8240);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "騎士きゅんの\nプリンセスフォームも\n見てみたいんだよなー\nンフ♡", 1, 131101, 0, 0, 8241);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "スライムを\nこーしてあーしたら\n騎士きゅんの泳ぐ\n練習に使えるっぽ？", 1, 131101, 0, 0, 8242);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "おかえり～♡\nって水着で迎えたら\n騎士きゅん喜んで\nくれるかなー？", 1, 131101, 0, 0, 8243);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "騎士きゅん\nこのサングラス\nかけてみる？\nぜってー似合うよー", 1, 131101, 0, 0, 8244);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "日焼け痛かったら\nいつでも言ってねー\nスライムでひんやり\nしてあげるよ～♪", 1, 131101, 0, 0, 8245);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今から外で\n焼いてこっかなー\n騎士きゅんもどー？", 1, 131101, 0, 0, 8246);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "スライムマッサージ\nしてあげよっかー\nほーれ、もみもみ～♡", 1, 131101, 0, 0, 8247);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "騎士きゅんが選んだ\n水着も着てみたーい\nネアおねえちゃんに\nどんなの着てほしい？", 1, 131101, 0, 0, 8248);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "騎士きゅ～ん\n尻相撲しよっかー♪\nおねえちゃんに\n勝てたらご褒美だぞ～", 1, 131101, 0, 0, 8249);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "暑すぎてムダに\n早起きしちった～\n二度寝すっか～\n…ふぁあ…", 1, 131101, 0, 1, 8250);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "夏バテしても\nスイカとかかき氷なら\n全然ウェルカム\nなんだよなー", 1, 131101, 0, 2, 8251);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日はこのまま\n水着で寝るかー\n夢ん中で泳ごー", 1, 131101, 0, 3, 8252);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "いったんキューケイ…\nンー…よし\n充電カンリョ～♪", 1, 131101, 0, 0, 8254);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "仲間になりたそうに\nこっち見てんねー\nきゃわいいしおっけ～", 1, 131101, 0, 0, 8255);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ン～いいニオーイ\nお日様あたった\n騎士きゅんの\n次くらいかな～", 1, 131101, 0, 0, 8256);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "カラダ冷えてきたから\nたすかるーおかげで\nまだまだ水着イケるわ", 1, 131101, 0, 0, 8257);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "うめ～\nとまんねぇ～\n夏バテどこいった～？", 1, 131101, 0, 0, 8259);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ…\nこれは意外と\nぬるっと読めるっぽー", 1, 131101, 0, 0, 8260);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "ンフフ～\n海の戦士ってカンジ？\nアリよりのアリだね～", 1, 131101, 0, 0, 8262);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "あーやべ\n一瞬で寝そー\nヤバだわ～", 1, 131101, 0, 0, 8263);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "服や紙が易々と\n燃えぬとは\nランドソルとはまこと\n住み易き国で候", 1, 129701, 0, 0, 8264);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "どの世界にあっても\n民は活力に溢れ\n街は賑わうもの…\n善哉、善哉", 1, 129701, 0, 0, 8265);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "食べ歩きに世界征服…\nギルドとはかくも\n自由気儘な徒党に\nありんすなぁ", 1, 129701, 0, 0, 8266);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "連絡は…今日もなし\n我が妹子は相変わらず\n放埓なことよ喃", 1, 129701, 0, 0, 8267);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "モネは相変わらず\n警戒しきりなれど…\nそのようなところも\n愛らしくあり申す", 1, 129701, 0, 0, 8268);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "なんと長閑な世にや\nありけむ…この平和は\n騎士殿たちの努力の\n賜物にありんす喃", 1, 129701, 0, 0, 8269);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "『王家の装備』は\n使わぬのかと？\n…フフ。すでに\n用いており申す", 1, 129701, 0, 0, 8270);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今ばかりは媛という\n立場は置いて\nこの地の者らと\n歓談したく候", 1, 129701, 0, 0, 8271);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "強さの秘密？　…フフ\n女子の秘密を暴くのは\n野暮にござんす\nご寛恕いただきたく候", 1, 129701, 0, 0, 8272);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "此方の家屋、\n見目以上に\n堅牢であり申す\n何ぞ仕掛けがありや？", 1, 129701, 0, 0, 8273);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "心地よい時間とは\n疾く過ぎ去りゆくもの\n此処で過ごすと改めて\n実感できる喃", 1, 129701, 0, 0, 8274);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "視線が気になる？\nこれはすみませぬ\nなにぶん、お前さまは\n見ていて飽きませぬ故", 1, 129701, 0, 0, 8275);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お前さまの前では\n誰もが心を開く…\nなんとまぁ罪作りな\n色男にありんすな？", 1, 129701, 0, 0, 8276);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "よく眠れましたかの？\n寝る子は良く育つ、と\n古くより申します由", 1, 129701, 0, 1, 8277);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "美食殿の作法に倣い\n皆で共に昼餉を頂くと\n致しんしょう", 1, 129701, 0, 2, 8278);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "逢魔ヶ時は望まぬ客も\n参るもの…お前さまも\n気をつけなんし", 1, 129701, 0, 3, 8279);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "わっちの蛇に\n勝るとも劣らぬ\n座り心地で候", 1, 129701, 0, 0, 8281);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "魂、万物に宿る\nとの云いあらば\n情愛を注いでやるのが\nよかろうの", 1, 129701, 0, 0, 8282);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いと香しき哉…\n騎士殿は香の道にも\n詳しくあられるか", 1, 129701, 0, 0, 8283);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ジオ・ゲヘナの\n灼熱と比ぶれば\nそよ風と変わり\nござんせん", 1, 129701, 0, 0, 8284);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "美味なる哉…この味\nぺコリーヌ姫が好むも\n道理にありんす", 1, 129701, 0, 0, 8286);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "トーゴクに、オーマ…\n書で見るだけでも\n心惹かれる土地よの", 1, 129701, 0, 0, 8287);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "暑い日には\n冷たいものですよねー\nかき氷とか食べて\nすっきりしたいです★", 1, 131201, 0, 0, 8289);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "海への行き来は\nテレポーテーションに\nお任せです★", 1, 131201, 0, 0, 8290);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "トロピカルジュースが\n飲みたいでーす♪\n海の家で見たんですよ\nカップル用ジュース★", 1, 131201, 0, 0, 8291);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ご飯どうしようかなー\nあ、海鮮ラーメンとか\n美味しそうかも★", 1, 131201, 0, 0, 8292);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "水鉄砲、普通に撃つと\n少し物足りないかも…\nどるるるる～ん★って\n感じが欲しいですよね", 1, 131201, 0, 0, 8293);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "コイビトっぽいこと\nアオハルっぽいこと\nいっぱいしたいです★\n修羅場とかも♪", 1, 131201, 0, 0, 8294);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "騎士さんが溺れたら\n絶対助けに行きますね\n人工呼吸でもなんでも\nしてあげますから★", 1, 131201, 0, 0, 8295);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "騎士さーん\n日焼け止めの塗り直し\nお願いします★\n優しくしてくださいね", 1, 131201, 0, 0, 8296);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "海で食べたフルーツ？\nはい、まだありますよ\nこっちでもあーんして\n食べさせましょうか★", 1, 131201, 0, 0, 8297);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ぺんぽこりんは\nどうしたのかって？\nどうしたんでしょうね\nどーでもいいです★", 1, 131201, 0, 0, 8298);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "今日はどんな\nイイコトしましょうか\n思い出作り？\n人助けもいいですね★", 1, 131201, 0, 0, 8299);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ヒモを引っ張ったら…\n「セ・キ・ニ・ン」\n取ってもらいますよ？\nなーんてウソですけど", 1, 131201, 0, 0, 8300);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "みんなでイイコトも\n楽しいですけど～\n…二人でイイコト\nしちゃいますか？", 1, 131201, 0, 0, 8301);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝ですよー！\n今日も一日、\nイイコト日和ですね♪", 1, 131201, 0, 1, 8302);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "日差しにご注意ですね\n日焼け止め…誰かに\n塗ってほしいなー？\n…ちらっ★", 1, 131201, 0, 2, 8303);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜の海って\n惹かれちゃいますよね\n…ロマンチックです★", 1, 131201, 0, 3, 8304);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "う～ん、まったり～\nこれぞ新ジャンル\nおうちバカンス★", 1, 131201, 0, 0, 8306);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "よーしよーし★\nわたしとイイコト\n一緒にしましょうねー", 1, 131201, 0, 0, 8307);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りですねー\nリラックスタイムに\nちょうどよさそう★", 1, 131201, 0, 0, 8308);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "水遊びのあとは\nしっかり体を\n温めないとですよね★", 1, 131201, 0, 0, 8309);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "栄養補給もバッチリ★\n遊びもイイコトも\nお腹が減ってたら\nできませんからねー？", 1, 131201, 0, 0, 8311);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "今だと海関連の本とか\n興味あるんですよねー\n魚とか海難救助とか★", 1, 131201, 0, 0, 8312);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "かっこいー★\n名前はー…\nぷんぷくぽんとか？", 1, 131201, 0, 0, 8314);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "映えますねー\n写真撮ったら\n素敵な思い出に\nなりそうです★", 1, 131201, 0, 0, 8315);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "海でもないのに\nこの姿でいるのは…\nやはり、場違いでは\nありませんか…？", 1, 131601, 0, 0, 8316);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "スイカとは割ることと\n見つけたり！\n…ですが目隠しすれば\n見当たらないもの…", 1, 131601, 0, 0, 8317);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "まぁ、膝に砂が…\n気がつきませんでした\nまるでわんぱくな\nお子様のよう…ふふっ", 1, 131601, 0, 0, 8318);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "家の中でスイカを割る\nわけにはまいりません\nここは潔く包丁で\n切りましょう", 1, 131601, 0, 0, 8319);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ミソラ様やネア様の\n大胆さを見習って…\nき、騎士きゅーん…★\n難しいですね…", 1, 131601, 0, 0, 8320);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "きゅ、急に暗く…！？\n…失礼しました\n鉢巻きが下がってきた\nだけでした…ううぅ", 1, 131601, 0, 0, 8321);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "わたくしに剣の才は\nあるのでしょうか…\nいえ、何事もまずは\nやってみなくては", 1, 131601, 0, 0, 8322);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "なにか羽織った方が\nよろしいですよね…？\nそのままでいい？\nそれはそれで…その…", 1, 131601, 0, 0, 8323);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あの、兄様…？\nスイカの種を飛ばす\n遊びもあるというのは\n…本当なのでしょうか", 1, 131601, 0, 0, 8324);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "強くなるための修行は\nまだ始まったばかり\nまずは己の目指すべき\n道を見定めなくては", 1, 131601, 0, 0, 8325);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "同じ薄着であっても\n黒い天使の姿より…\n気が楽です", 1, 131601, 0, 0, 8326);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "はい、ただいまー！\n…あっ！\n海の家でのお手伝いの\nくせが、つい…", 1, 131601, 0, 0, 8327);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "兄様さえよろしければ\nまた一緒に海へ…\nあ…申し訳ありません\n浮ついてしまいました", 1, 131601, 0, 0, 8328);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "本日もイイコトをして\n清々しい一日を\n過ごしたいものです\nまさに一日一善ですね", 1, 131601, 0, 1, 8329);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼時になると\n海の家の料理を\n思い出してしまいます\n焼きそばにかき氷…♪", 1, 131601, 0, 2, 8330);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "兄様…よろしければ\n浜辺を歩きませんか？\nきっと、月が\nきれいでしょうから", 1, 131601, 0, 3, 8331);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふわふわ心地よすぎて\n眠くなってしまいます\n水着姿では\nいけません…ふぁ…", 1, 131601, 0, 0, 8333);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "なんてよい手触り…\n癖になってしまいます\nふふ、よしよし…♪", 1, 131601, 0, 0, 8334);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "爽やかな香り…♪\n日焼け止めクリームを\n思い出してしまいます", 1, 131601, 0, 0, 8335);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "冷たい水で冷えた体が\n温まります…♪\nまるで兄様のようです", 1, 131601, 0, 0, 8336);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "お腹が空いては\n修行ができません…！\n動きに障りない程度に\n栄養の補給を…！", 1, 131601, 0, 0, 8338);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "剣術とスイカ割りが\n上達する指南書…\n見つかりませんね…", 1, 131601, 0, 0, 8339);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "さあ、ともに大海原を\n参りましょう！\nなんて…ふふっ♪", 1, 131601, 0, 0, 8341);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "まるでおとぎ話の\n登場人物になった\nような心持ちです…♪", 1, 131601, 0, 0, 8342);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "あたしはなんで水着で\n室内をうろついてるの\nかしら…不思議だわ", 1, 131701, 0, 0, 8343);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "あ、天井が汚れてる\n仕方ないわね\nひとっ飛びしますか", 1, 131701, 0, 0, 8344);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "はい、お疲れさま♪\n出迎えの言葉は\nやっぱこれよね♪", 1, 131701, 0, 0, 8345);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "そういえばあたしって\n羽があるけど\n泳げるのかしら…", 1, 131701, 0, 0, 8346);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "あいつのために\n浮き輪も用意したし\n抜かりはないわよ", 1, 131701, 0, 0, 8347);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "海までのガイド計画も\nまとまったわね\nふふっ…楽しみだわ", 1, 131701, 0, 0, 8348);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "この水着、あいつが\n選んでくれたのよね\n…大事にしないと", 1, 131701, 0, 0, 8349);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ネビアは最近どう？\n迷惑かけてない？\n…かけてるのね", 1, 131701, 0, 0, 8350);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あんた…部屋の片付け\nくらい自分でしなさい\n散らかってたわよ？\n…片付けておいたけど", 1, 131701, 0, 0, 8351);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もしかして暇なの？\nだったら記憶でも\n見せましょうか？\n凄く恥ずかしいやつ♪", 1, 131701, 0, 0, 8352);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "夏ってこんなに\n暑いのね…\n海にばかり行く\n気持ちが分かったわ", 1, 131701, 0, 0, 8353);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あんたの水着って\n新しいの買わないの？\nなんならあたしが\n選んであげるわよ♪", 1, 131701, 0, 0, 8354);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "気軽に触れ合える\n距離にいる…\nあたしにとって\nとても大事なことよ", 1, 131701, 0, 0, 8355);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あらおはよう\n夏の朝は暑いわね\nシャワーでも浴びて\nさっぱりしなさい", 1, 131701, 0, 1, 8356);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼は何を食べるの？\nガイド妖精として\n提案しましょうか？", 1, 131701, 0, 2, 8357);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜更かしは厳禁よ\n無理やり眠らせて\nあげましょうか？", 1, 131701, 0, 3, 8358);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "アメスさまだって\nゴロゴロするときは\nあるのよ～", 1, 131701, 0, 0, 8360);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "…ふふっ♪\n何よ、あたしが\nかわいいものを\n愛でちゃだめなの？", 1, 131701, 0, 0, 8361);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "こういういい香り…\n塔の中じゃなかなか\n楽しめないのよね", 1, 131701, 0, 0, 8362);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "水着を着てるのに\n温まるのって\n矛盾してない？\n気にしすぎかしら", 1, 131701, 0, 0, 8363);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "あんたと行動するなら\n沢山食べられるように\nならなきゃね…！", 1, 131701, 0, 0, 8365);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "文字を読むのと\nデータを読むのは\nまったく違うわ", 1, 131701, 0, 0, 8366);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "へぇ、面白いじゃない\nこういう経験、昔じゃ\nできなかったわ", 1, 131701, 0, 0, 8368);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "面白いクッションね\nところであんた…\nあたしで遊んでない？\n気のせいならいいけど", 1, 131701, 0, 0, 8369);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "また新しい悪戯\n思いついちゃった♪\n誰に仕掛けようかしら", 1, 118601, 0, 0, 8370);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "あ～あ、退屈…\nフィオでもからかって\nこようかしら♪", 1, 118601, 0, 0, 8371);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ミソギの悪戯って\nレベル高いのよね…\n負けてらんないわ！", 1, 118601, 0, 0, 8372);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "家事ニガテなのよね～\nコッコロたちには\n感謝しないとね", 1, 118601, 0, 0, 8373);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "私も魔物料理に\n慣れてきちゃった…\n毒されてるわね…", 1, 118601, 0, 0, 8374);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あいつに仕掛ける\n次の悪戯は～…♪\nこれ…ううん…\nやっぱこっちかしら？", 1, 118601, 0, 0, 8375);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "結局ギルドハウスが\n一番落ち着くわね\n…私たちの家だもの", 1, 118601, 0, 0, 8376);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "悪戯のコツでも\n教えてあげよっか？\n…え～興味ないの？", 1, 118601, 0, 0, 8377);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "これからもずーっと\n退屈しない毎日に\nしてあげる♪\n私の悪戯でね♪", 1, 118601, 0, 0, 8378);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ちょうど退屈してたの\nたーっぷりと\n構ってもらうわよ♪", 1, 118601, 0, 0, 8379);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "案内が必要なら\n頼ってくれていいわよ\n一応は私だって\nガイド妖精だし！", 1, 118601, 0, 0, 8380);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "冒険のガイドなら\n私に任せなさい♪\nある意味忘れられない\n旅にしてあげる♪", 1, 118601, 0, 0, 8381);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "妖精がいる家は\n栄えるのよ♪　だから\nずっといてあげる\nあんたのそばにね♪", 1, 118601, 0, 0, 8382);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "きゃははっ！\n寝ぐせついてるわよ？\nこのままにしましょ！\nだって面白いし！", 1, 118601, 0, 1, 8383);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "自由に外へ行けるって\nすっごく幸せなことよ\nさ、散歩行きましょ♪", 1, 118601, 0, 2, 8384);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "安心していいわ\n寝てるあんたに\n悪戯しないから\n…あんたにはね♪", 1, 118601, 0, 3, 8385);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "悪くはないけど…\nあいつの頭の方が\n座り心地いいかも", 1, 118601, 0, 0, 8387);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "この子を使った\n悪戯は…\n…止めとこっと\nこんなにかわいいし♪", 1, 118601, 0, 0, 8388);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "このギルドハウスに\nピッタリな匂いね♪\n一言で言えば…\nカオスって感じ？", 1, 118601, 0, 0, 8389);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "なんていうか…\n心があたたかいわ\n…変な感じ！", 1, 118601, 0, 0, 8390);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ガイド妖精にも\n食事の機能があって\nよかったのかも\nしれないわね…もぐ…", 1, 118601, 0, 0, 8392);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "じれったい物語ね…\nこんなの霧を使えば\n一瞬で終わるのに！", 1, 118601, 0, 0, 8393);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "わる～い子は\nトゥンヌス漁船に\n乗ってもらおうかな～", 1, 131801, 0, 0, 8395);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "たまにはファミリーの\nみんなにもお休みを\nあげないとね～☆", 1, 131801, 0, 0, 8396);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "海辺に素敵な\nバーがあるんだ～\n彼が大人になったら\n一緒に行きたいな♪", 1, 131801, 0, 0, 8397);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "夏の風を肌で\n感じるの好きかも～\nラーゴはどう？", 1, 131801, 0, 0, 8398);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "海岸線を\nのんびり散歩もいいね\n砂や貝殻に紛れた\nお宝探しの旅だよ～☆", 1, 131801, 0, 0, 8399);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "みんなで集まって\nビーチパーティーでも\n開いちゃおっかな～♪", 1, 131801, 0, 0, 8400);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "さて、この水着…\n彼は気に入って\nくれてるかな～？", 1, 131801, 0, 0, 8401);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "心ゆくまで夏を\n楽しんじゃお～☆\nほら君も♪", 1, 131801, 0, 0, 8402);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "水着似合ってるって？\nふふ♪　うれしいこと\n言ってくれるね～☆", 1, 131801, 0, 0, 8403);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "熱中症には\n気を付けないと\nだめだよ～？", 1, 131801, 0, 0, 8404);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "海の家ならうちの\nファミリーでやってる\nとこにしよっか☆\n豪遊しちゃお～♪", 1, 131801, 0, 0, 8405);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "君と一緒なら\nどんな夏になるのか\n楽しみだね～♪", 1, 131801, 0, 0, 8406);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "君といると子供心を\nくすぐられちゃうな～\n大人だって思いっきり\n遊んでいいんだよね♪", 1, 131801, 0, 0, 8407);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "さ、今日は何をして\n過ごそっかな～…\nねえ、君は何したい？", 1, 131801, 0, 1, 8408);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ふふ♪\n波音が心地良い\n時間だね～☆", 1, 131801, 0, 2, 8409);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今夜は星空の下で\n乾杯しよっか～☆\n飲み物取ってくるね♪", 1, 131801, 0, 3, 8410);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ここ涼しい～♪\nちょっと一休み\nしていこっか☆", 1, 131801, 0, 0, 8412);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "こういうのも良いけど\nやっぱりラーゴの方が\nかわいいかな～♪", 1, 131801, 0, 0, 8413);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "爽やかな香りだね～\nこういう感覚も絵で\n表現してみたいな～", 1, 131801, 0, 0, 8414);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "続きを描く前に\n原稿を乾かさないとね\nインクがにじむと\n直すの大変なんだよ～", 1, 131801, 0, 0, 8415);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "今日は水着だし…\n食べるのは控えめに\nしておこっかな", 1, 131801, 0, 0, 8417);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "話題の作品は\nチェックしないとね～\nあっ、この作家さん\n新刊出すんだ～", 1, 131801, 0, 0, 8418);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "うちの出店の客引きに\nこういう乗り物系を\n使うのもアリかな～☆", 1, 131801, 0, 0, 8420);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "これ、背景用の\n参考資料に\n一つ欲しいかも♪", 1, 131801, 0, 0, 8421);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ここに帰るのも\n久しぶり…あれから\n変わったところは\nあるかしら？", 1, 181201, 0, 0, 8422);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "バイトも復帰しなきゃ\nうちのギルドにとって\n食費は重要だもの…！", 1, 181201, 0, 0, 8423);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "コッコロマ…っ\n…うぅ…\nこの癖は\n直らないのね…", 1, 181201, 0, 0, 8424);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "この世界はまだまだ\n知らないことだらけね\n『裏世界』とか…", 1, 181201, 0, 0, 8425);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "必ずみんなを\n助け出してみせるわ\n…もちろん、兄さんも", 1, 181201, 0, 0, 8426);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "またみんなと\n暮らせるなんて…\n夢じゃ、ないのよね", 1, 181201, 0, 0, 8427);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "たくさんの人が\n私に優しくしてくれる\n…だからこそ、私も\n頼れる人になりたいわ", 1, 181201, 0, 0, 8428);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "次はランドソルの\n街の外にも行きたいわ\nあの…よかったらまた\n一緒に回ってくれる？", 1, 181201, 0, 0, 8429);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "独りぼっちで眠るのは\nやっぱり寂しかったわ\n…みんなで雑魚寝？\nそんなの…絶対やるわ", 1, 181201, 0, 0, 8430);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ネビアってば大泣きで\n私を出迎えてくれたの\n…すごく嬉しかったわ", 1, 181201, 0, 0, 8431);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "この翼、陽に当たると\n本当に綺麗よね…\n自分のだけれど、つい\nずっと見ちゃうもの", 1, 181201, 0, 0, 8432);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "おにーたんっ♪\n…呼びたくなっただけ\n本当にそれだけよっ？", 1, 181201, 0, 0, 8433);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "どうしたの？\n…ふふっ、安心して\nこれからもずっと\n私はここにいるわ", 1, 181201, 0, 0, 8434);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "みんな起きだす時間ね\n街が活気づいてく感じ\n嫌いじゃないわ", 1, 181201, 0, 1, 8435);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "【美食殿】のお昼は\nいつも美味しいから\nまた太っちゃいそうね", 1, 181201, 0, 2, 8436);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おやすみなさい\n明日も、その先も\n一緒に冒険しましょう", 1, 181201, 0, 3, 8437);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "休憩も大事…よね\nじゃあ遠慮なく…\nふぅ～…♪", 1, 181201, 0, 0, 8439);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "はぁ…ふわふわ…♪\nこのかわいさには\nもう抗えないわ…", 1, 181201, 0, 0, 8440);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "落ち着く香り…\nこの匂いを嗅いでると\n帰ってきたなって\n思うわね", 1, 181201, 0, 0, 8441);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "みんなで野宿した時も\n焚火の明かりを見て\nすごく安心したのよね", 1, 181201, 0, 0, 8442);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ペコリーヌさんには\n負けるけど…\n美味しくって手が\n止まらないわ…！", 1, 181201, 0, 0, 8444);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "プリンセスフォーム…\n一体どういう仕組みで\n発動するのか、文献に\n書いてないかしら…", 1, 181201, 0, 0, 8445);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "すごーく暑いけど、\nこの暑さをどうやって\n乗り越えるかって\n考えるのも楽しいかも", 1, 131901, 0, 0, 8447);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "氷で彫刻を作るの？\nそれは楽しそうだけど\nすぐに溶けちゃわ\nないかしら？", 1, 131901, 0, 0, 8448);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "お日様の下で遊ぶのも\n部屋の中で涼むのも\nどっちも夏ならではの\n楽しみ方なのね", 1, 131901, 0, 0, 8449);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "生き物の観察日記、\n私も書いてみたいな\nパックのお昼寝日記\nなんてどうかしら？", 1, 131901, 0, 0, 8450);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "さまぁばけぇしょんは\n計画を立てるもの\nなんだって\n私も挑戦してみるわね", 1, 131901, 0, 0, 8451);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "この世界のことを\nもっと知って\nアーラム村のみんなに\nお話ししてあげるの", 1, 131901, 0, 0, 8452);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "いつルグニカに帰るか\nわからないからこそ\n毎日頑張らなきゃね", 1, 131901, 0, 0, 8453);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日はどこに行くの？\n私は、えーと…\nかき氷が食べたいわ！", 1, 131901, 0, 0, 8454);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ここにも精霊が\n住んでたりするの？\n…精霊じゃなくて\nがいど妖精？", 1, 131901, 0, 0, 8455);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "パックったら、\n近所の子にいっぱい\nなでなでされてたわ\nすごーく人気者ね！", 1, 131901, 0, 0, 8456);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "実は…線香花火の\n特訓をしてたの！\n次は負けないんだから", 1, 131901, 0, 0, 8457);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "昨日、みんなの\n似顔絵も絵日記に\n描いてみたんだけど…\n笑っちゃダメよ？", 1, 131901, 0, 0, 8458);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "何気ない時間だって\n後で思い返せば\nずっと忘れない\n素敵な思い出になるの", 1, 131901, 0, 0, 8459);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "気持ちよく起きて、\nいい一日を過ごしたい\nそんなときには\nラジーオタイソーね！", 1, 131901, 0, 1, 8460);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ごはんの時間ね\n暑さに負けないように\nしっかり食べましょう", 1, 131901, 0, 2, 8461);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "外は涼しいみたいだし\n夜の散歩に行ってみる\nのはどうかしら？", 1, 131901, 0, 3, 8462);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "遊び疲れたら\nここでひとやすみ…\nふわぁ…\n眠くなっちゃった…", 1, 131901, 0, 0, 8464);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "細かいところまで\nすごーく丁寧に\n作られてる…", 1, 131901, 0, 0, 8465);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "わっ、なんだか\nすーっとする香りね\nちょっぴり涼しく\nなったみたい", 1, 131901, 0, 0, 8466);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "海で遊ぶと\n体が冷えるから\nあったかいのも\nすごーく嬉しい…", 1, 131901, 0, 0, 8467);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "これも美味しい…！\nペコリーヌが\nどんどん食べちゃう\n気持ちが分かるかも", 1, 131901, 0, 0, 8469);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "このお話も面白い…！\nあっという間に時間が\n過ぎちゃったわ…\n…ね、寝てません！", 1, 131901, 0, 0, 8470);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "この子と一緒に海に\nいったら楽しそうね！\nどこに行けば\n会えるのかしら？", 1, 131901, 0, 0, 8472);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "ふかふかね！\nこうしてると波の音が\n聞こえてきそう…", 1, 131901, 0, 0, 8473);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "こちらでは水着姿で\n過ごすのも\n珍しくないようですね", 1, 132101, 0, 0, 8474);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "メイド服ではなく\n姉様と色違いの水着…\nレムは嬉しいです", 1, 132101, 0, 0, 8475);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "少し室温が高いかも\nしれませんね…\nいくつか氷を配置して\nおきましょうか", 1, 132101, 0, 0, 8476);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "清涼感があるとはいえ\n鉄球をビーチバレーの\nボールに代用するのは\n危ないでしょうか…", 1, 132101, 0, 0, 8477);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ふぅー…ふぅー…\nようやく浮輪が\n膨らみました\n姉様にお渡ししないと", 1, 132101, 0, 0, 8478);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "海のことをもっと\n教えていただけますか\n…スバルくんと海の\n話をしたいんです", 1, 132101, 0, 0, 8479);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "もし海に行く機会が\nあればレムにも…\nお声がけくださいね\nぜひ、お願いします", 1, 132101, 0, 0, 8480);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "何を着ていても\nメイドはメイド\n掃除も料理も\nなんでもござれです", 1, 132101, 0, 0, 8481);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "スバルくんとあなたは\n兄弟のように\n仲がいいですね\n姉様とレムと一緒です", 1, 132101, 0, 0, 8482);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "この姿で子どもたちと\n遊ぶのは…さすがに\nはばかられますね\nやはり着替えてきます", 1, 132101, 0, 0, 8483);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ナンパ…というものが\n海にはあるそうです\nスバルくんがとても\n警戒していました", 1, 132101, 0, 0, 8484);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "魚釣りでしたら\nレムもご一緒します\n氷漬けの魚の備蓄を\n補充したかったので", 1, 132101, 0, 0, 8485);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "子どもたちと砂遊びの\n約束をしているんです\nあなたもご一緒に\nいかがですか？", 1, 132101, 0, 0, 8486);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ラジーオタイソーは\nもうされましたか？\n体がほぐれますよ", 1, 132101, 0, 1, 8487);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ですね。では\n姉様に焼きそばを…\nもちろん皆様の分も\n用意してありますよ", 1, 132101, 0, 2, 8488);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "熱帯夜であっても\nお休みの際はお腹を\n冷やさないように\n気をつけてくださいね", 1, 132101, 0, 3, 8489);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "とても気持ちよさそう\nです…！\nさっそく姉様に\nお教えしないと", 1, 132101, 0, 0, 8491);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "季節に合わせた\n着せ替えができれば\n子どもたちも\n楽しめそうです", 1, 132101, 0, 0, 8492);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ふむふむ…この香りは\n疲れを癒やしてくれ\nますね。エミリア様に\nお持ちします", 1, 132101, 0, 0, 8493);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "身も心もほぐれます\n思っていたよりも\n体が冷えていたみたい\nですね…ふう…", 1, 132101, 0, 0, 8494);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…んうっ！？\nこのすっぱさは…\n梅干し、ですか…\nくせになりますね…！", 1, 132101, 0, 0, 8496);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "海に関する詩文なども\nあるのでしょうか…\n気になります", 1, 132101, 0, 0, 8497);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "地竜とは違った\n乗り心地です…\n本物にも乗ってみたい\nものですね", 1, 132101, 0, 0, 8499);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "この大きさで\n本物の貝であれば…\nどんな料理にするか\n想像が膨らみます", 1, 132101, 0, 0, 8500);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "これがこの世界の\n居住環境か…\n面白い構造だね", 1, 132001, 0, 0, 8501);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "暇を持て余していてね\n誰か話し相手に\nなってくれないかな", 1, 132001, 0, 0, 8502);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "目新しいものが\nたくさんあるね\n胸が躍るよ", 1, 132001, 0, 0, 8503);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "頑丈そうな建物だ\nここなら彼女たちが\n暴れても大丈夫かな？", 1, 132001, 0, 0, 8504);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "力が制限されていて\n良かった面もある\n君も吐かずにすんだし", 1, 132001, 0, 0, 8505);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "悪さなんてするわけ\nないじゃないか\n傷つくなぁ", 1, 132001, 0, 0, 8506);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "普段と違う格好で\n歩き回るのも\n悪くない経験だ", 1, 132001, 0, 0, 8507);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ボクに聞きたいことが\nあるなら遠慮なく\n質問するといい", 1, 132001, 0, 0, 8508);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "気軽に魔女に\n話しかけるなんて\n君は物好きだね", 1, 132001, 0, 0, 8509);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "この世界においては\nボクは異物だからね\n大人しくしているさ", 1, 132001, 0, 0, 8510);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ボクの反応を\n見たいのかい？\n君の好奇心には\n恐れ入るよ", 1, 132001, 0, 0, 8511);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ボクの手を借りたい？\nもちろん構わないさ\n対価はいただくけどね", 1, 132001, 0, 0, 8512);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ボクと海を見たい？\nふふ、魅力的な\nお誘いだね", 1, 132001, 0, 0, 8513);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お目覚めかな？\nさて、君の見た夢を\n教えてくれないかな？", 1, 132001, 0, 1, 8514);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "食後のお茶を\n一緒にどうだろうか？\nさあ、席に座ってよ", 1, 132001, 0, 2, 8515);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おや、お休みかな？\n魔女の前で無防備だね\n…無論、何もしないさ", 1, 132001, 0, 3, 8516);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "こういう椅子は\n茶会には向かないね\nつい気が緩んでしまう", 1, 132001, 0, 0, 8518);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "こういうものを好きな\n女の子がいいのかな？\n君の嗜好を知りたいな", 1, 132001, 0, 0, 8519);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りだ\nこれにはどんな\n効能があるんだろう？", 1, 132001, 0, 0, 8520);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "火の点け方に\nボクのいた世界との\n違いはないのかな？", 1, 132001, 0, 0, 8521);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "これもまた未知の味だ\n存分に味わわせて\nもらうとしよう", 1, 132001, 0, 0, 8523);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "素晴らしいね\nここには叡智が\n詰まっている", 1, 132001, 0, 0, 8524);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "魔物を模倣した\nぬいぐるみか…\n実物を見たくなるね", 1, 132001, 0, 0, 8526);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "いい気持ちだ…ボクと\nしたことが、何も考え\nられなくなりそうだ", 1, 132001, 0, 0, 8527);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "願わずにいられません\nどうかこちらの\n世界には…悲劇が\n生まれませんようにと", 1, 109701, 0, 0, 8528);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "食事のご希望があれば\nなんなりと。お腹が\nいっぱいになるまで\n沢山ご用意しますね", 1, 109701, 0, 0, 8529);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "あの男、これからも\n観察が必要ね\nラムの目の届く範囲に\n置く必要があるわ", 1, 109801, 0, 0, 8530);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "素直なところは\nあの男の美点ね\n癪だけど、偶然にも\nラムと同じだわ", 1, 109801, 0, 0, 8531);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "迷惑かけちゃったけど\n雪遊びは楽しかったわ\nまたやりたい…なんて\n言ったら怒られるかも", 1, 109901, 0, 0, 8532);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "数えきれないくらいの\n思い出を、みんなで\n作りましょう！", 1, 109901, 0, 0, 8533);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "わわっ、今すごく\nいい香りがしたけど…\n誰の香水かな\n教えてほしいな…♪", 1, 132201, 0, 0, 8534);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "錬金術用の釜、\n置くならどこかな？\n自分専用の錬金釜、\n憧れちゃうよね♪", 1, 132201, 0, 0, 8535);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "この匂い…誰か\n唐揚げ食べたみたい\nうぅ…お腹空いて\nきちゃうよ", 1, 132201, 0, 0, 8536);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "次の新曲のタイトルは\n『恋の錬金術』！\nうーん、ちょっと\nベタ過ぎるかな…", 1, 132201, 0, 0, 8537);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "あ、錬金の素材\n切らしてたんだ…\n彼を誘って採集に\n行ってこようかな", 1, 132201, 0, 0, 8538);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "瞬時に着替えができる\n薬とかできないかな？\n舞台で衣装チェンジ！\nなーんて、楽しそう♪", 1, 132201, 0, 0, 8539);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "彼が遊びに来た後は\n部屋の空気がほんのり\n彼の匂いなんだ…\nなんだか幸せだな♪", 1, 132201, 0, 0, 8540);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日もバイト？\nそれならこれ飲んで\n私のお手製ポーション\nがんばってきてね！", 1, 132201, 0, 0, 8541);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "新しくできたカレー屋\n行ってみない？\n時々スパイスの香りが\n流れてくるんだよ", 1, 132201, 0, 0, 8542);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "私のフィギュア\nそっくりでしょ！\nルイちゃんが作って\nくれたんだ", 1, 132201, 0, 0, 8543);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あれ、シャンプー\n変えた？　私と同じの\nだよ！　どうしよう\nドキドキしちゃう…", 1, 132201, 0, 0, 8544);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "いらっしゃいませ♪\n何を作りますか？\nなーんてね。錬金堂で\nまた一日店長したいな", 1, 132201, 0, 0, 8545);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "クンクン…彼の\nハンカチ…いい匂い♪\n私だけの秘密のお守り\nにしてるんだ", 1, 132201, 0, 0, 8546);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ねえねえ、天気も\nいいし一緒に錬金の\n素材集めに行こうよ！", 1, 132201, 0, 1, 8547);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ご飯、用意したよ\nあはは、さすがに\nランチは錬成しないよ\n私の手作りだよ♪", 1, 132201, 0, 2, 8548);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日も一日お疲れさま\nこれ飲んでゆっくり\n休んで。薬じゃないよ\nホットミルクだよ？", 1, 132201, 0, 3, 8549);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "昨日、遅くまで\n錬金術の勉強してた\nから眠くって…\nちょっと一休みっと", 1, 132201, 0, 0, 8551);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "この子にちょっとだけ\n香水かけて、と…\nんー！　だっこした時\nすっごくいい匂い♪", 1, 132201, 0, 0, 8552);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "花みたいな、\nお菓子みたいな\nいい香り。気持ちが\n穏やかになるね♪", 1, 132201, 0, 0, 8553);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "外でもこの暖かさを\n感じられる道具、\n作れたりしないかな？", 1, 132201, 0, 0, 8554);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "素材集めに行くと\nお腹が空くんだよね\nイロハちゃんも\nこの味好きそう", 1, 132201, 0, 0, 8556);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "錬金術にはたくさんの\n知識が必要だからね\nさあ、今日も調合書を\n読まなくちゃ", 1, 132201, 0, 0, 8557);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ここが騎士さんたちの\n住んでる場所…！\n粗相がないように\n気をつけなきゃ", 1, 127701, 0, 0, 8559);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ジオ・テオゴニアの\nみんな、私がいない間\nちゃんとお仕事\nしてればいいけど…", 1, 127701, 0, 0, 8560);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "コッコロさんも\n従者として長いって\n聞いたような…\nあの年ですごい…！", 1, 127701, 0, 0, 8561);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "自分がもてなされる\n側になるのって\nやっぱりちょっと\n落ち着かないかも…", 1, 127701, 0, 0, 8562);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "今度のお休みの日は\n何しよう…？\nあっ、最近できたお店\nヴルムと行こうかな？", 1, 127701, 0, 0, 8563);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お買い物したら\nかわいいからって\nたくさんおまけして\nもらっちゃった…♪", 1, 127701, 0, 0, 8564);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ここにいると、つい\nぼんやりしちゃう…\nこれも騎士さんの力…\nなのかな", 1, 127701, 0, 0, 8565);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お手伝いできることは\nありませんか？\nお世話でもなんでも\n任せてくださいっ", 1, 127701, 0, 0, 8566);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ランドソルに初めて\n来たときは驚きました\n砂糖の山と思ったら…\nあんなに寒いなんて！", 1, 127701, 0, 0, 8567);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あの、ヴルムを\n見ませんでしたか？\nもう…あの子ってば\nまた仕事をサボって…", 1, 127701, 0, 0, 8568);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "家具や家が壊れても\n食べられないなんて\nなんだかもったいない\nですね", 1, 127701, 0, 0, 8569);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "とっておきの紅茶を\n手に入れたんです\n一杯いかがですか？\nその、日頃のお礼です", 1, 127701, 0, 0, 8570);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "頑張ってて偉いって…\nほ、褒めてもなんにも\n出ませんからね！？\n…えへへ♪", 1, 127701, 0, 0, 8571);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます！\nモーニングティーは\nいかがですか？\n私、準備しますねっ", 1, 127701, 0, 1, 8572);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ライラエルさまも\nお昼寝はお好きです\nけど…だからって\n寝すぎはダメですよ！", 1, 127701, 0, 2, 8573);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おやすみなさい\nくれぐれも寝不足には\n気をつけてくださいね", 1, 127701, 0, 3, 8574);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "しっかりしないと…\nメイドの私が\n気を抜くなんて…\nそんな…ふぅ…", 1, 127701, 0, 0, 8576);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "わぁ、かわいい…♪\nってダメダメ！\nメイドなんだから\n落ち着かないと…！", 1, 127701, 0, 0, 8577);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい匂い…♪\nこの香り、\nライラエルさまも\n好きそうです！", 1, 127701, 0, 0, 8578);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ランドソルの環境に\n触れると、この光の\nありがたみが\n身に沁みますね…", 1, 127701, 0, 0, 8579);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "甘くない食べ物が\n一般的なのも\n慣れてきました\nあむ…おいひぃ…♪", 1, 127701, 0, 0, 8581);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ランドソルの文字、\n私たちのところと\nちょっと違いますね…\n覚えられるかなぁ", 1, 127701, 0, 0, 8582);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "甘い匂いがしない…\nジオ・テオゴニアとは\n別の世界なんですね", 1, 127801, 0, 0, 8584);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "掃除めんど…\nん…このくらいで\nまー十分でしょ", 1, 127801, 0, 0, 8585);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "そろそろ食事の\n用意もしなきゃ…\nあーやる事多い…", 1, 127801, 0, 0, 8586);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "秘密の隠れ場所、\nまた姉さんにバレた…\n次のを探さないと", 1, 127801, 0, 0, 8587);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "知らない間に仕事が\n終わったり…しないか\nしてくれたらいいのに", 1, 127801, 0, 0, 8588);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "きちんともてなすには\n騎士さんの好みも\n覚えてかないと…", 1, 127801, 0, 0, 8589);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ご主人サマに\nご奉仕します～♪\n…キャラじゃないか\nやめやめ、恥ずかし…", 1, 127801, 0, 0, 8590);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "居心地いいっすね…\n今日からここに\n住んでもいいですか", 1, 127801, 0, 0, 8591);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あの、ちょっと姉さん\n怒らせちゃったんで\n匿ってくれません？", 1, 127801, 0, 0, 8592);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "羽と尻尾が格好いい？\n意外と邪魔ですよ\n仰向けで寝にくいし", 1, 127801, 0, 0, 8593);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ワークライフバランス\nっていい言葉ですね\nぜひライフ多めで", 1, 127801, 0, 0, 8594);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "騎士さんって\n働き者ですね\nそのままあたしの\n仕事も…いえなんでも", 1, 127801, 0, 0, 8595);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "熱心に見てても\n尻尾は触らせて\nあげませんってば\n角？　角なら…まぁ", 1, 127801, 0, 0, 8596);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "寝ても寝ても\n寝足りない…ふぁ…\nあー…眠たい…", 1, 127801, 0, 1, 8597);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "アフタヌーンティーの\n準備は得意ですよ\nつまみ食いとか\n…つまみ食いとか", 1, 127801, 0, 2, 8598);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "よく休んでください\n布団は干しといたんで\n…姉さんが", 1, 127801, 0, 3, 8599);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふー…\nこのままずーっと\nここに居たい…", 1, 127801, 0, 0, 8601);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "あんたも一緒に\nサボっちゃうか～\n…なんて", 1, 127801, 0, 0, 8602);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "落ち着く匂い…\n騎士さんの好み\nなんですかね", 1, 127801, 0, 0, 8603);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "こういうとこの\n掃除って面倒だし…\n今度でいっか", 1, 127801, 0, 0, 8604);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ご飯の前に\nこんな食べたら\n姉さんきっと怒るな…", 1, 127801, 0, 0, 8606);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "食に関する本が\nやけに多い…\nお国柄ですかね", 1, 127801, 0, 0, 8607);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "すんすん…\nお兄さんの匂いが\nぷんぷんする～♡\nザコくっさぁ♡", 1, 130201, 0, 0, 8609);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ぴこーん！\nいひひっ、新作メカの\n面白いアイデア、\n思いついちった～♡", 1, 130201, 0, 0, 8610);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "メカもいじりたいし\n服もアクセもほしー…\nあ～、おこづかい\n足んないよ～！", 1, 130201, 0, 0, 8611);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お勉強でもしよっかな\nザコお兄さんには\n絶対わかんない\nよーなやつ♡", 1, 130201, 0, 0, 8612);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "お兄さんの部屋って\nどこどこぉ？\nメカの実験室に\n使えそうだよね～♡", 1, 130201, 0, 0, 8613);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "次のデートコースは\nどんなのかなー？\n…いや、むしろ次は\nぼくが決めちゃうっ？", 1, 130201, 0, 0, 8614);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "強奪計画は念入りに♡\nお兄さんのハートも\n全力でザコザコにする\n計画、立てないとね♡", 1, 130201, 0, 0, 8615);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ねー、ヒマヒマヒマ～\nかまってかまってー♡\nどっか連れてけー♡", 1, 130201, 0, 0, 8616);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今日はこっちで\nご飯食べたいなー♡\n…帰っても５日連続の\nバカナ姉カレーだし…", 1, 130201, 0, 0, 8617);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "依頼行くならぼくも\n連れてってよー♡\nお兄さんのザコっぷり\n見ててあげる～♡", 1, 130201, 0, 0, 8618);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お兄さんはぼくより\nオトナだもんね～♡\nじゃあオモテナシ、\n期待してるから～♡", 1, 130201, 0, 0, 8619);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ヤマ姉になんかお土産\n持って帰ろうかなー？\nザコお兄さん、選ぶの\n付きあって～♡", 1, 130201, 0, 0, 8620);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "遊びにいくときは\nザコお兄さんも\n誘ってあげるよ♡\nどうせヒマでしょ～？", 1, 130201, 0, 0, 8621);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふぁ～、ねむぅ～…\n夜更かしぶん寝るから\nあとで起こして～♡\nあ、変なこと禁止～♡", 1, 130201, 0, 1, 8622);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おなかすいたぁ～\nなんか食べ行こ♡\n甘いのおごって～♡", 1, 130201, 0, 2, 8623);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "えー、もう寝る時間？\nじゃあ…添い寝して\nあげよっか？\nなーんて、ウッソー♡", 1, 130201, 0, 3, 8624);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "おお～ふわっふわ～♪\nバンディシャーク号の\n座席に使いたーい！", 1, 130201, 0, 0, 8626);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "カワイイ～♡\n改造したらもっと\nカワイくなるかな～？", 1, 130201, 0, 0, 8627);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "くんくん…いい匂い♡\nザコお兄さんって\nこーゆー香りが\n好きなのかなぁ～", 1, 130201, 0, 0, 8628);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "はー、あったかーい♡\nバンディシャーク号\nにも欲しいかもー♪", 1, 130201, 0, 0, 8629);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食べれるときに\n食べるのが大事って\nヤマ姉言ってたしね～", 1, 130201, 0, 0, 8631);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "あ、この本読んだよ♡\n参考文献リストが\nしっかりしてて\n勉強になったなー♪", 1, 130201, 0, 0, 8632);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "部屋は多少ゴチャつい\nてる方が落ち着くのさ\nバンディシャーク号\nみたいにね♪", 1, 130001, 0, 0, 8634);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "呆けてるのもいいが\nちいと物足りないねぇ\n麦しゅわもブドウ朱も\n無いなんてさ", 1, 130001, 0, 0, 8635);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "この家セキュリティが\nなってないねぇ…\n盗賊目線でちょっくら\n指南でもしてやるか", 1, 130001, 0, 0, 8636);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "不思議だねぇ\nここで飲むと、酔いが\n回るのが早い気が\nするよ…ヒック", 1, 130001, 0, 0, 8637);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ふむ…\nクルマが壊れた時は\nアジト代わりに\n使えそうだ♪", 1, 130001, 0, 0, 8638);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "カカッ、いい部屋だ！\n妹を迎える準備は\nできてるみたいだねぇ", 1, 130001, 0, 0, 8639);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "…っと、油断したら\n落ち着いちまうね\nボーヤの甘っちょろい\n雰囲気のせいだよ", 1, 130001, 0, 0, 8640);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "さすがにこの家から\n盗みはしないさ\nいずれは妹たちの\n共有財産になるからね", 1, 130001, 0, 0, 8641);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ボーヤ、暇なら\n博打でもやるかい？\nアタシが負けたら\n掃除でもしてやるよ", 1, 130001, 0, 0, 8642);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "立派な家じゃないか！\n一国一城の主とは\nちょっとボーヤのこと\n見くびってたかもねぇ", 1, 130001, 0, 0, 8643);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "かわいい義弟のためだ\nアタシが盗ってきた\nお宝をくれてやるよ\n好きな場所に飾りな！", 1, 130001, 0, 0, 8644);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "妹と結ばれる前に\n他の女との関係は\n清算しとくように\nわかったね、ボーヤ？", 1, 130001, 0, 0, 8645);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お、ヤシオーリかい？\nフフン、義弟からの\nお酌とあっちゃあ\n断れないねぇ♪", 1, 130001, 0, 0, 8646);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "うう…清々しい朝だが\n頭がいてぇ…\nちっと昨日は\n飲みすぎたか…？", 1, 130001, 0, 1, 8647);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ほらこれ、ワカナに\n作らせた弁当だ\nこれで昼からも\nバリバリやりな！", 1, 130001, 0, 2, 8648);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "まだまだ夜はこれから\n…と言いたいとこだが\n早寝して立派に育ちな\nそれが妹たちの為だよ", 1, 130001, 0, 3, 8649);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "中々いい座り心地だが\n盗賊が腑抜ける訳には\nいかないね…が…\nもう少しだけ座るか…", 1, 130001, 0, 0, 8651);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "こういうのの中に\n実はレアなブツが\n隠されてるとか\nありがちだねぇ", 1, 130001, 0, 0, 8652);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ふうん、ボーヤは\nこういう匂いが\n好きなのかい？\n妹たちに教えてやろう", 1, 130001, 0, 0, 8653);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "体を温めんにゃ\n酵露をカッとやるのが\n一番だが、これも存外\n悪くないねぇ…♪", 1, 130001, 0, 0, 8654);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ガツガツ…\nん、悪くねェ味だ\nこれにヤシオーリでも\nありゃ文句はないね", 1, 130001, 0, 0, 8656);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "本にも載ってない\nレアもんのお宝か…\nフッ、想像しただけで\n血沸き肉躍るねぇ…！", 1, 130001, 0, 0, 8657);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "今日の買い物は\nいつものお野菜と…\nあっ、確か特売が\nあったはず…！", 1, 130101, 0, 0, 8659);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "お掃除、お掃除…♪\nきゅっきゅっ…\nよいしょ、っと…", 1, 130101, 0, 0, 8660);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "洗濯ものも\nたまらないうちに\nやっちゃわないと…", 1, 130101, 0, 0, 8661);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "夕飯のメニュー…\n何にしよう？\n期限の早い食材は…", 1, 130101, 0, 0, 8662);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "色々お菓子も\n作ってみたいけど…\n予算…足りるかなぁ…", 1, 130101, 0, 0, 8663);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "騎士さん…どんな\n料理が好きなんだろ？\n前に作ったコロッケは\n評判よかったけど…", 1, 130101, 0, 0, 8664);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "騎士さんと\nおしゃべりすると、\n胸があたたかくなる…\nなんでだろ…？", 1, 130101, 0, 0, 8665);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あっ、騎士さん\nどうかしましたか？\n御用ならいつでも…♪", 1, 130101, 0, 0, 8666);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "削っても削っても\n家計簿は赤字…\n騎士さ～ん…\n助けてください～！", 1, 130101, 0, 0, 8667);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "手が空いてたら\n日用品の買い出し、\n手伝ってもらっても\nいいですか…？", 1, 130101, 0, 0, 8668);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "やっと一息つけそう…\nあっ、わたし\nお茶を淹れてきますね", 1, 130101, 0, 0, 8669);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "困りごとがあったら\n言ってくださいね\nわたし…騎士さんの\n力になりたいです", 1, 130101, 0, 0, 8670);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "助けてもらった分は\n必ず返しますから…\nそれまでわたしのこと\n見ててくださいね…♪", 1, 130101, 0, 0, 8671);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "忘れ物はないですか？\n今日のお仕事も\n頑張りましょうね…！", 1, 130101, 0, 1, 8672);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ご飯できてますよ\n大したものじゃなくて\n恐縮ですけど…", 1, 130101, 0, 2, 8673);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜更かしはだめですよ\nわたしも家事を\n終わらせたら寝ないと", 1, 130101, 0, 3, 8674);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "これ…割れ物防止の\nクッションに\n使えるかも…？", 1, 130101, 0, 0, 8676);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "こういうのいいなぁ…\nけど…フブキちゃんに\n絶対改造されちゃう…", 1, 130101, 0, 0, 8677);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい匂い…でも\n切れかけてるかも？\nえっと補充するには…", 1, 130101, 0, 0, 8678);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかい…\nちょっとだけなら\n休んでも…いいよね", 1, 130101, 0, 0, 8679);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "これがあったら\nもうお料理を\n作らなくて済むかも？", 1, 130101, 0, 0, 8681);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "新しい節約レシピは…\nあ、この草って\n食べられるんだ…", 1, 130101, 0, 0, 8682);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "愛溢れるランドソルの\nクリスマス…ですか\nいけませんね、つい\n胸が躍ってしまいます", 1, 132801, 0, 0, 8684);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ツリーの飾りと\nわたしの髪…\nくるくるしていて\n似ているかも…くすっ", 1, 132801, 0, 0, 8685);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "この姿で傲慢な\nわたしになったら…\nいつもより怖がらせて\nしまうでしょうね…", 1, 132801, 0, 0, 8686);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "悪魔として、人を\nドキドキさせなくては\nい、イオから教わった\n…投げキスの練習を…", 1, 132801, 0, 0, 8687);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ジオ・テオゴニアの\nお菓子は、ツリーの\n飾りに向いていそう\nですね…ふふっ", 1, 132801, 0, 0, 8688);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "騎士のギルドハウス…\nクリスマスの時期も\n暖かいのですね…", 1, 132801, 0, 0, 8689);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "城の皆と過ごす宴も\n楽しいですが…\n騎士と二人の宴も\n幸せです…", 1, 132801, 0, 0, 8690);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "騎士、あなたの\nもてなしに感謝します\nクリスマスの何たるか\n教えてくださいね", 1, 132801, 0, 0, 8691);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "この黒い羽は\nどう手入れすれば？\nイオなら知っている\nでしょうか…", 1, 132801, 0, 0, 8692);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "城の皆も連れてきたい\nほど、クリスマスは\n楽しい行事ですね\nお土産も迷います", 1, 132801, 0, 0, 8693);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "クリスマスの晩餐に\n招待されたのですが…\nその…辛いものは\nありませんよね…？", 1, 132801, 0, 0, 8694);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "クリスマスと言わず…\nいつでも星に祈って\nいますよ？　騎士達に\n幸せがあるように、と", 1, 132801, 0, 0, 8695);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "悪魔として騎士を\nドキドキさせる…？\nそ、そのようなこと\nわたしには…うぅ…", 1, 132801, 0, 0, 8696);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝は寒いですね…\n雪…積もっている\nでしょうか？", 1, 132801, 0, 1, 8697);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ふあぁ…いけません\n公務の滞在先で\nお昼寝など…", 1, 132801, 0, 2, 8698);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜は悪魔として\n夢を見せましょう\n騎士はどんな夢が\n見たいですか？", 1, 132801, 0, 3, 8699);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふぅ…落ち着きます…\n家でゆっくりと過ごす\nクリスマスも\n良いものですね", 1, 132801, 0, 0, 8701);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "リンドのプレゼントに\nぬいぐるみは…？\n…子ども扱いすると\n落ち込むでしょうか…", 1, 132801, 0, 0, 8702);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "暖かいお部屋に\nこの香りを漂わせたら\nふふっ…素敵な時間を\n過ごせそうです", 1, 132801, 0, 0, 8703);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "これがあれば、\n寒い冬も安心ですね\n暖かくて…このまま\n眠ってしまいそうです", 1, 132801, 0, 0, 8704);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "悪魔の力を使ったら\nお腹が空いてきて\nしまって…\n恥ずかしいです…", 1, 132801, 0, 0, 8706);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "クリスマスには多くの\n伝承があるのですね…\n天使の伝承まで\nありましたし…", 1, 132801, 0, 0, 8707);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 14, 3, "まぁ…！\nよくできていますね\nサプライズプレゼント\n…でしょうか。ふふ♪", 1, 132803, 0, 0, 8709);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 15, 3, "ど、どうでしょう…？\n親善交流の催しに\nなりそうでしょうか…", 1, 132804, 0, 0, 8710);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ギルドハウスって\nあったかぁ～い♪\n心がぽかぽかするの！", 1, 132901, 0, 0, 8711);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "クリスマスの悪魔の\nお仕事はないわね！\nだってここのみんな\nいい子なんですもの♪", 1, 132901, 0, 0, 8712);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "みんなちゃんと\n寝られてるかしら？\n夜更かしせずに、\nいい夢見てね♪", 1, 132901, 0, 0, 8713);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "毎回、来年が\n楽しみになるような\n素敵なクリスマスを\n過ごしたいわね♪", 1, 132901, 0, 0, 8714);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "訳ありケーキを見ると\n刑務作業を思い出すわ\n…あれも貴重な体験\nだったのかしら…？", 1, 132901, 0, 0, 8715);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ロマンチックな\nクリスマスに備えて\n今のうちに少女漫画で\n予習しておかないと！", 1, 132901, 0, 0, 8716);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ほっぺにチューなら\nもう一回しても…\nや、やっぱり無理！\n恥ずかしいわ～！", 1, 132901, 0, 0, 8717);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "またみんなで\nセッションしたいわね\nカラーベルの練習した\n成果を見せたいの♪", 1, 132901, 0, 0, 8718);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "君はサンタさんに\nどんなプレゼントを\n頼んでいたのかしら？\n気になるわ～！", 1, 132901, 0, 0, 8719);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "愛が壊れても、\n何度でも治してあげる\n私たちの間に、\n愛の尽きる日はないわ", 1, 132901, 0, 0, 8720);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "冬休みって短いようで\n長く感じちゃうわよね\n学校のみんなと\n早く会いたいな～♪", 1, 132901, 0, 0, 8721);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "愛をテーマにした\n冬休みの作文の宿題、\n君の分を読むのが\n今から楽しみね♪", 1, 132901, 0, 0, 8722);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "よかったらまた\n私をハニーって呼んで\nほしいの。ダーリン♪", 1, 132901, 0, 0, 8723);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう！\n冬の朝は冷えるから\n風邪を引かないように\n対策しましょうね", 1, 132901, 0, 1, 8724);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ご飯は一緒に\n食べに行きましょう！\nクリスマス限定の\nランチコースよ♪", 1, 132901, 0, 2, 8725);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ねえねえ、キャンドル\nイルミネーションを\n見に行きましょうよ！\nロマンチックよ～♪", 1, 132901, 0, 3, 8726);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "暖かいクリスマスを\n過ごすのに必須よね♪\nふふ、柔らかぁい！", 1, 132901, 0, 0, 8728);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "どの子もかわいい～♪\nクリスマスツリーの\n下で、一緒にお祝い\nしてもらいたいな♪", 1, 132901, 0, 0, 8729);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "なんだか胸の奥が\n温かくなる匂いね～\nリラックスしちゃう♪", 1, 132901, 0, 0, 8730);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかぁい♪\nあ、でも夜になったら\nサンタさんが入れる\nように、火を消すのよ", 1, 132901, 0, 0, 8731);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "寒い冬だからこそ\nしっかり食べて\n備えておかなきゃ！", 1, 132901, 0, 0, 8733);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "『聖夜の６時間』…？\n気になる小説だけど…\n勝手に読んじゃ悪い\nわよね…ガマンよ…！", 1, 132901, 0, 0, 8734);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 14, 3, "きゃっ…！\nこんな不思議な本が\nあったのね～\nちょっと面白いかも♪", 1, 132901, 0, 0, 8736);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 15, 3, "もふもふ、ふわふわで\nあったかくて\n気持ちいい～…♪", 1, 132901, 0, 0, 8737);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "冬といえばサマー！\n…って言うけど夏は\n何をＰＲするんだろ\nメルクリゾート…", 1, 129501, 0, 0, 8738);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "奨学金の道は遠いな…\nあまりに遠すぎて\n最近忘れてたまである", 1, 129501, 0, 0, 8739);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "暇だし鏡でも見よっと\nはー、今日も顔が良…\nげ、若干むくんでる？\nはー、今日終わった", 1, 129501, 0, 0, 8740);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "水着…お姉ちゃんと\n貸し借りするんだけど\nこれって少数派姉妹？", 1, 129501, 0, 0, 8741);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ちゅむ、ツムギちゃん\n今日も可愛いねデュフ\n…なんで推し語りの声\nキモくなるんだろ私…", 1, 129501, 0, 0, 8742);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あれ…なんで私\n水着のまま部屋の中\nうろついてるんだっけ\n…こわ！　てか寒っ！", 1, 129501, 0, 0, 8743);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "先輩よく友達と海に\n行くって言ってたけど\n…え、誰とだろ？\nまあ誰でもいいけどさ", 1, 129501, 0, 0, 8744);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "始まる…\nチエルの夏が始まる…\nあ冬でしたっけ？\nまどっちでもいいです", 1, 129501, 0, 0, 8745);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "こないだトミヱ先輩\n壁に喧嘩売ってました\n相変わらず元気ですね", 1, 129501, 0, 0, 8746);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ユニ先輩にお芝居の\n出来を聞かれたんで\n可愛いって答えました\n嘘は言ってません", 1, 129501, 0, 0, 8747);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "クロエ先輩の腹筋\nかっちょいーですよね\nさりげ触りたいけど\nあいつ隙ないんですよ", 1, 129501, 0, 0, 8748);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "先輩もうカメラ係は\nやらないんです？\nチエルはやってますよ\n最高の被写体を常に", 1, 129501, 0, 0, 8749);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "メリゾでカップル割の\n企画あるらしいんです\nちなみに先輩は…\nあ、いえ、何でも…", 1, 129501, 0, 0, 8750);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝ごはんは抜いても\n朝ちぇるだけは\n抜いちゃ駄目ですよ", 1, 129501, 0, 1, 8751);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼なに食べるか\n悩んでます？\nおごってくれるなら\nいい店教えますけど", 1, 129501, 0, 2, 8752);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "この時間帯になると\nユニ先輩がごそごそ\n蠢きだすんですよね…", 1, 129501, 0, 3, 8753);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "世界の美少女が…\nこんな格好で\nくつろいでたら…\nまずい…事案になる", 1, 129501, 0, 0, 8755);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "え、この子って\nウォータープルーフ？\nメリゾにも連れて\nいけちゃうカンジ？", 1, 129501, 0, 0, 8756);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "はぁ～、いい香り…\nそういえばメリゾの\nスタッフルームも\n『贅』な匂いしてた…", 1, 129501, 0, 0, 8757);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "薄着で暖まるとか…\n冷静になっちゃ\n駄目なやつですよね\nこれ…", 1, 129501, 0, 0, 8758);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おにぎり１個は\nちぇるに換算すると…\n２５ちぇるくらい？", 1, 129501, 0, 0, 8760);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "あれー？　この辞書\nまだちぇるの項目\n載ってないんだ？", 1, 129501, 0, 0, 8761);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "何これ…地味に楽しい\nあとたぶん\nクロエ先輩が好きそう", 1, 129501, 0, 0, 8763);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "これは良きですねー\n自宅でメリゾ気分とか\nユニ先輩もにっこり", 1, 129501, 0, 0, 8764);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ここが騎士氏の\nお住まいですか\nふむ…地縛霊は\nいなさそうですね", 1, 133001, 0, 0, 8765);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ここは土足厳禁では\nないみたいですね\nま、私には関係ないか\n足、透っけ透けなので", 1, 133001, 0, 0, 8766);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ランドソルの裏路地\nあそこは最高ですね\n暗くてじめじめしてて\n癒されるー", 1, 133001, 0, 0, 8767);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "っ！\n今ラップ音が…？\nまさか幽霊？\nやだ、怖い", 1, 133001, 0, 0, 8768);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "獣人族にエルフ族…\nなるほど騎士氏が\n幽霊程度では驚かない\n訳です…ちぇ", 1, 133001, 0, 0, 8769);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "今日の深夜\n騎士氏が起きるまで\n枕元でずーっと\n立っててみようかな", 1, 133001, 0, 0, 8770);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "騎士氏の驚く顔を\n見ると胸が高鳴る…\n変ですね、心臓なんて\n動いてないのに", 1, 133001, 0, 0, 8771);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "安心して下さい\n勝手にすり抜けて\n騎士氏の部屋は\n覗きませんよ…多分", 1, 133001, 0, 0, 8772);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "なんですか騎士氏\n怖い話でも聞きます？\nじゃあいきますね…\n今貴方の前に幽霊がっ", 1, 133001, 0, 0, 8773);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "この家…幽霊が\n寄ってくる間取りに\nなってますね\nまあ、嘘ですけど", 1, 133001, 0, 0, 8774);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "料理はしませんよ\n指きったら痛いので\nえ…透ければいい？\n……天才ですか？", 1, 133001, 0, 0, 8775);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お散歩ですか？\n深夜なら付き合います\nあ、やっぱり断ります\n幽霊出たら怖いので", 1, 133001, 0, 0, 8776);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "騎士氏の部屋のセンス\n好きですよ…もっと\nじめじめしていれば\nなおよし、ですが", 1, 133001, 0, 0, 8777);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "レイスになってから\nあまり言わなくなった\n挨拶第一位はこちら…\nおはようございます", 1, 133001, 0, 1, 8778);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "騎士氏。午後からも\n頑張って下さいね\n私は日陰で休みます\nでは、おつです", 1, 133001, 0, 2, 8779);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜も更けてきましたね\nここからがレイスの\n本領発揮…では早速\nう　ら　め　し　や～", 1, 133001, 0, 3, 8780);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "中々座り心地が\nよろしいですね\nブロッケンに跨る方が\n安心はしますが", 1, 133001, 0, 0, 8782);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "知ってますよ\nどうせ貴方も\n夜中になったら\n動き回るんでしょ？", 1, 133001, 0, 0, 8783);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "すう…はあ…\nすごく落ち着く香り\n…落ち着き過ぎて\n成仏しそうでした", 1, 133001, 0, 0, 8784);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "温度は感じませんが\nなぜかほっこり\n温かい気持ちです\nなんででしょうね？", 1, 133001, 0, 0, 8785);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…\n食べ物は基本好きです\n消化の方法は…\n企業秘密で", 1, 133001, 0, 0, 8787);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "苦手なんですよね\nホラー小説\nだって幽霊とか\n怖いじゃないですか", 1, 133001, 0, 0, 8788);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この得も言われぬ\n高揚感…やはり\n正月はいいものだな！", 1, 133201, 0, 0, 8790);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "む、いかんな\n気付くと黒豆と\n栗きんとんばかり\n食べてしまう…", 1, 133201, 0, 0, 8791);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ギルドの連中にも\nお年玉を渡してみるか\n少しは士気が上がる\nかもしれないな！", 1, 133201, 0, 0, 8792);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "正月くらいはのんびり\n羽を伸ばすとしよう\n適切な休暇も軍人の\n大事な責務だからな", 1, 133201, 0, 0, 8793);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "正月で浮かれすぎた\n者も多いはずだ\n念のため街を見回りに\n行くとしよう", 1, 133201, 0, 0, 8794);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "む、このおせち料理は\n絶品だな！\nあいつの分も\nとっておいてやろう", 1, 133201, 0, 0, 8795);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "今年の抱負は…\nそうだな、あいつと\nさらに高みを目指す\nこれでいこう", 1, 133201, 0, 0, 8796);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "えっ、お年玉！\n…い、いや、私は\n子どもではないからな\nえ、遠慮させてもらう", 1, 133201, 0, 0, 8797);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "凧あげすごろく\nこま回し、たとえ遊び\nでも手は抜かんぞ\nさあ、勝負だ！", 1, 133201, 0, 0, 8798);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そのきな粉餅も\nうまそうだな…\n私のあんこと交換\nしないか？", 1, 133201, 0, 0, 8799);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "貴公、正月料理を\n食べ過ぎてないか？\nじ、実は私も少々、な", 1, 133201, 0, 0, 8800);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "貴公、お参りに行くぞ\n何？　外が寒いだと？\n仕方ない、手ぐらいは\nつないでやろう", 1, 133201, 0, 0, 8801);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "貴公と新たな年を\n迎えられてうれしいぞ\n今年も一つ\nよろしくたのむ！", 1, 133201, 0, 0, 8802);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "起きろ貴公。早朝なら\n参拝客も少ないはず\n今のうちにお参りを\n済ませよう", 1, 133201, 0, 1, 8803);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼食に餅を焼いたぞ\nのどに詰まらせない\nようにゆっくり噛んで\n食べるんだ", 1, 133201, 0, 2, 8804);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜ふかしはあまり\n褒められたものでは\nないが…正月くらいは\n目をつむろう", 1, 133201, 0, 3, 8805);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "これに座って飲む\n甘酒は格別だな", 1, 133201, 0, 0, 8807);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "せっかくの正月だし\nこいつにも着物を\n着せてやりたいな", 1, 133201, 0, 0, 8808);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "これは梅の香り…？\nふふ、なかなか\n風流ではないか", 1, 133201, 0, 0, 8809);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "冬の寒さが堪えるな…\nここでしっかりと\n暖をとるとしよう", 1, 133201, 0, 0, 8810);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "正月はのんびり\nしたいからな、勝手に\n食事が出てくるのは\n本当に助かる", 1, 133201, 0, 0, 8812);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむ、これが世界の\n新年のお祝いか\nなかなか興味深いな", 1, 133201, 0, 0, 8813);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "一年の計は元旦にあり\n計画を立てて、\n有意義な一年を\n過ごしましょ", 1, 133501, 0, 0, 8815);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "年末年始はどうしても\n出費が増えちゃうし\nしばらくはきっちり\n節約しなきゃ…！", 1, 133501, 0, 0, 8816);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "タタミにフトン、\nトーゴク文化の内装…\nランドソルでももっと\n流行らないかしら", 1, 133501, 0, 0, 8817);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "子どもたちが凧を\n手作りして遊んでたの\n偉いわよね、みんな…", 1, 133501, 0, 0, 8818);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "お年玉をあげる側に\nなって、分かる苦労…\n大人になるって\nこういうことかしら", 1, 133501, 0, 0, 8819);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "一応実家にも\n顔を出さないと…\nよかったらだけど、\nあんたも来る？", 1, 133501, 0, 0, 8820);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "毎日一緒にいて、\nささやかな幸せを\n同じように感じて…\nそれだけで十分ね", 1, 133501, 0, 0, 8821);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "着物姿、もっと\nじっくり見たいの？\nさすがに照れるわよ、\nもう…", 1, 133501, 0, 0, 8822);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "整理整頓、できてる？\nもし散らかってるなら\nお正月休みのうちに\n片づけちゃいましょ", 1, 133501, 0, 0, 8823);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今年もみんなが無事に\n過ごせますように…\nほら、一緒に\nお祈りしましょ", 1, 133501, 0, 0, 8824);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "みんな、あんたと\n遊ぶのが楽しみだって\n子どもに好かれる\nタイプなのよね", 1, 133501, 0, 0, 8825);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あんたの運勢は大吉！\nラッキーパーソンは\n金髪の幼なじみよ\n…なんてねっ", 1, 133501, 0, 0, 8826);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "初夢は実現するのよね\nそれじゃ、あたしは\nあんたと…んんっ\nなんでもないわ", 1, 133501, 0, 0, 8827);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "外が寒いと、その分\n目も冴えるわよね\nこのまま朝の散歩に\n行こうかしら", 1, 133501, 0, 1, 8828);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お正月休みでも、\n食べてばっかじゃダメ\nしっかり動いて\n体を引き締めましょ", 1, 133501, 0, 2, 8829);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ちゃんとあったかく\nして寝るのよ\nお正月から\n風邪ひかないようにね", 1, 133501, 0, 3, 8830);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "着物、しわに\nなっちゃいそう…\nでもそれ以上に、\n心地よくって…はぁ", 1, 133501, 0, 0, 8832);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "門松みたいに\nこの子も飾ってみる？\n運勢がよくなるかも♪", 1, 133501, 0, 0, 8833);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この匂い、もしかして\nトーゴクのお香？\nワビサビを感じるわ", 1, 133501, 0, 0, 8834);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ふぅ、あったかい…\n冷えた体に\n染み渡ってくるわ…", 1, 133501, 0, 0, 8835);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "んっ、おいしい！\nおせちばっかじゃ\nやっぱり飽きちゃう\nものね…", 1, 133501, 0, 0, 8837);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "験担ぎとか縁起物とか\n調べてみると\nいろいろあって\n面白いのよね～", 1, 133501, 0, 0, 8838);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ふーん、いい家ね\nアタシの巣に\nしちゃおうかしら？", 1, 133601, 0, 0, 8840);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "お姉ちゃん…\n早く会いたいなぁ…", 1, 133601, 0, 0, 8841);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "メドゥシアナも\n気に入るかしら？\n今度連れてこよっと！", 1, 133601, 0, 0, 8842);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お邪魔してるだけ\nなのも悪いわよね…\nお返しはしないとね\n…ネズミ退治とか？", 1, 133601, 0, 0, 8843);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "何か平和よね\nランドソルって…\nアタシ的にはもう少し\n荒っぽくてもいいわ", 1, 133601, 0, 0, 8844);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ランドソルも\n楽しい街よね…\n案内してくれる\nアイツのおかげ？", 1, 133601, 0, 0, 8845);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "アタシ、アイツに\n頼りすぎてるかも…？\nで、でも！　断らない\nアイツも問題だわ！", 1, 133601, 0, 0, 8846);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ねぇ、つまんなーい！\nもっとアタシを\n楽しませなさいよねー", 1, 133601, 0, 0, 8847);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "この家悪くないけど…\nもっとムシムシ\nジメジメにできない？", 1, 133601, 0, 0, 8848);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "何よ？\n用もないのに声掛けた\n…とか言ったら\n容赦しないわよ？", 1, 133601, 0, 0, 8849);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "少し部屋が寂しいわね\nそうだ、アンタを\n石にして家具に…\n冗談よ、ふふんっ♪", 1, 133601, 0, 0, 8850);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ねぇ、もう少し\n話していかない？\nアンタの話なら…\n特別に聞いてあげるわ", 1, 133601, 0, 0, 8851);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "い、いつも\nあ、あ、ありが…\nうぅ、何でもないー！", 1, 133601, 0, 0, 8852);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "やっと起きたわね？\n寝ぼすけなんだから！\n尻尾でひっぱたいて\n起こそうかと思ったわ", 1, 133601, 0, 1, 8853);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "人捜しは日の高い\nうちに限るわ！\nさぁ、メドゥシアナ！\n全速力で出発進行よ!", 1, 133601, 0, 2, 8854);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "アタシ…\n子どもじゃないもん…\n眠くなんか…\nないんだからぁ…", 1, 133601, 0, 3, 8855);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふわふわであったかい\nつい、とぐろを\n巻きたくなるわね…", 1, 133601, 0, 0, 8857);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "アンタ、こんな\nヤワな体じゃ駄目よ\nウロコくらい\n生やしたらどうなの？", 1, 133601, 0, 0, 8858);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "くんくん…\n…ふん\n悪くないじゃない\n…くんくんくんくん…", 1, 133601, 0, 0, 8859);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかいの大好き！\nジオ・ゲヘナでも\nよく日向ぼっこ\nしたもんだわ…ふわぁ", 1, 133601, 0, 0, 8860);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "お姉ちゃんを捜すなら\n…もぐ\n体力つけないとね\n…もぐもぐ", 1, 133601, 0, 0, 8862);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "何よ？　たまには\n勉強くらいするわよ\nお姉ちゃんに\n笑われちゃうもの", 1, 133601, 0, 0, 8863);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この装いと力…\n今の世界との\n整合性を上手いこと\n合わせておかないとだ", 1, 133701, 0, 0, 8865);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "この格好…開発してた\n当時のまんまだ\nサイズもそのまま♪\n体型維持も完璧っ！", 1, 133701, 0, 0, 8866);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "あとで装備の手入れも\nやっとかないと\n…剣なら研ぐだけで\n終わるんだけどなぁ", 1, 133701, 0, 0, 8867);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "自分の原点を\n振り返ってみるのも\nたまには必要だね", 1, 133701, 0, 0, 8868);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "完璧じゃなくても\n今できる全力を尽くす\nその事に意味がある…\nそうだよね、少年", 1, 133701, 0, 0, 8869);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "始まりのあの日、\nそして向かうべき道…\nいつも忘れずにいよう", 1, 133701, 0, 0, 8870);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "誰かを救うために\n許容される犠牲なんて\nあっちゃいけない…\n全部、助けてやる", 1, 133701, 0, 0, 8871);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おっと少年、\n何か御用かな？\nキミに関わる事なら\n最優先で対応するよ", 1, 133701, 0, 0, 8872);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "困った事があれば\n頼ってもらって\n構わないからね！\nむしろもっと頼って！", 1, 133701, 0, 0, 8873);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そうだ、時間あるなら\n武器のメンテを\n手伝ってくれないかな\n数が多くてさ～", 1, 133701, 0, 0, 8874);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "遠距離戦の心得、\n少年にもレクチャー\nしてあげよっか？", 1, 133701, 0, 0, 8875);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "無茶しないで、って\n言ってもするだろうし\nせめてアタシの手が\n届く範囲で頼むよ", 1, 133701, 0, 0, 8876);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "虚実入り混じる\nこの世界でキミが…\n進むべきルートを\n照らしてくれたんだ", 1, 133701, 0, 0, 8877);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "グッモーニン！\n朝だよ少年、今日も\n張り切っていこう！", 1, 133701, 0, 1, 8878);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "クレープの代わりに\nガレットを焼いたんだ\nこの味で少年を\n唸らせてみせよう！", 1, 133701, 0, 2, 8879);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もうこんな時間だ\n遅くならないうちに\n作業を切り上げようか\n少年も早く寝なよ？", 1, 133701, 0, 3, 8880);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "あえて緊張を解くのも\n戦いには必要だし…\nそうそう…大事大事…", 1, 133701, 0, 0, 8882);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "愛着を抱かせる事を\n意図したデザインだね\n心理的効果の観点から\n分析してみようか…", 1, 133701, 0, 0, 8883);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "香りは記憶と密接に\n結びつく事がある…\n懐かしい匂いだね…", 1, 133701, 0, 0, 8884);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "癒されるな…\n何がこの感情変化を\n引き起こすんだろう？", 1, 133701, 0, 0, 8885);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食の偉大さを感じるな\n戦闘糧食ってやっぱり\n味気ないしなぁ…", 1, 133701, 0, 0, 8887);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "実用ばかりじゃなく\n詩や物語ってのも\n人には必要だよね", 1, 133701, 0, 0, 8888);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この場所の開発版も\n探せばあるかもな\nさて、どんなデザイン\nだったのやら…", 1, 133901, 0, 0, 8890);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "今まで数々の波乱に\n身を投じたが…やはり\n波乱にはこの姿が一番\n似合いだよ☆", 1, 133901, 0, 0, 8891);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "むっ…この角に羽と\n尻尾は家具とぶつかり\nやすいな。兎の時は\n気にならなかったが…", 1, 133901, 0, 0, 8892);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "いつもより闘争を\n求める気分になるな\n初心に帰るとは\nこのことか…？", 1, 133901, 0, 0, 8893);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "未調整上等☆\nそれを上手く使い\nこなしてこその\nワタシだろう？", 1, 133901, 0, 0, 8894);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "坊やとできそうな\n愉しいことは…\nふむ、多すぎて迷うな", 1, 133901, 0, 0, 8895);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "時折、坊やの居心地の\nよさに絆されそうに\nなってしまうな\nワタシらしくもない…", 1, 133901, 0, 0, 8896);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "どうだ、おろした\n髪型も艶やかだろう？\nそんじょそこらの\n賞賛では満足せんぞ☆", 1, 133901, 0, 0, 8897);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "外に出るぞ！\n共に退屈を殺しに\n行こうじゃないか☆", 1, 133901, 0, 0, 8898);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "角と翼も触りたい？\nワタシの虚数魔境に\n挑むというなら\n止めはせんよ☆", 1, 133901, 0, 0, 8899);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "なんだ、困りごとか？\nクリスティーナさんが\n何でも聞いてやろう☆\n解決するかは別だがな", 1, 133901, 0, 0, 8900);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "力が欲しいか？\nならば呼ぶがいい！\nワタシの名を☆", 1, 133901, 0, 0, 8901);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "悪魔との契約は絶対\nなのだそうだが…\nどうだ、坊や\n一つ契ってみるか？", 1, 133901, 0, 0, 8902);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "まだ眠い？　甘えるな\n寝首を掻かれたく\nなければ飛び起きて\nこい…☆", 1, 133901, 0, 1, 8903);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼食の準備を\nしてやろう。\n毒見はいらんぞ？\n安心するといい！", 1, 133901, 0, 2, 8904);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "坊やは寝る時間だ\n寝ないのならば…\n大人の時間に\n付き合ってもらうか☆", 1, 133901, 0, 3, 8905);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 3, "角と翼、尻尾の\nコンディションまで\n完璧だな☆", 1, 133901, 0, 0, 8906);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "なかなかのフワモコ\n具合だが…ううむ…\n翼と尻尾が邪魔だな", 1, 133901, 0, 0, 8907);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "うーむ、角と尻尾を\n追加して…さらに槍を\n持たせた方が見栄えが\nよさそうだ", 1, 133901, 0, 0, 8908);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りだな\n血と砂塵の臭いで\n上書きするまでの\n間に合わせに最適だ☆", 1, 133901, 0, 0, 8909);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "生温いな\nもっと焦がれるほどの\n熱量が欲しいところだ", 1, 133901, 0, 0, 8910);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 6, 3, "普段はないものが\n生えているのだから、\n運動でしっかり感覚を\n掴んでおかなければな", 1, 133901, 0, 0, 8911);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "腹が減っては戦は…\nと言うからな\nしっかり食べて\nおくとしようか☆", 1, 133901, 0, 0, 8912);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "『家庭を築くための\n絶対条件』…？\nふむ…興味がある\nタイトルだ", 1, 133901, 0, 0, 8913);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "奇妙な感覚です\nまるであの頃の自分に\n変装しているかのよう", 1, 133801, 0, 0, 8915);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "グレゴール？\nおっと、そうでした\n今は昔の姿になって\n離れていましたね", 1, 133801, 0, 0, 8916);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "このアバターでいると\n妙に子どもたちからの\n視線を感じますね…", 1, 133801, 0, 0, 8917);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "リソースの割り振りが\n変わっただけなのに\n随分と身体が軽く\n感じますね", 1, 133801, 0, 0, 8918);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "普段グレゴールに\n任せている分身の管理\n自分でやるには\nいささか煩雑ですね…", 1, 133801, 0, 0, 8919);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "長老に頼まれて描いた\n妖精の絵…いったい\n何に使ったのでしょう", 1, 133801, 0, 0, 8920);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "私自身をモデルにした\n完全なるNPCたち\nそれが私の分身です", 1, 133801, 0, 0, 8921);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "このアバターが\n気になるのですか？\n貴方はつくづく\n妖精に縁がありますね", 1, 133801, 0, 0, 8922);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ちょうどよかった\nグレゴールを見かけ\nませんでしたか？", 1, 133801, 0, 0, 8923);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あの翅は飾りでは\nありません。ただ…\nグレゴールに乗って\n飛ぶ方が楽なだけです", 1, 133801, 0, 0, 8924);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "妖精とは本来神話に\nおけるトリックスター\n運命をかき回すことが\n存在意義なのです", 1, 133801, 0, 0, 8925);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "変貌大妃の権能との\n相性を考えなければ\nこの姿こそが私たちの\n最強の姿です", 1, 133801, 0, 0, 8926);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "変化とは一種の喪失\nだからこそ得られる物\nがある…貴方のそれも\n大切にするのですよ", 1, 133801, 0, 0, 8927);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "マサキからの定時連絡\nが来ませんね…心配は\n不要ですが、様子を\n見に行きましょうか", 1, 133801, 0, 1, 8928);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼食の時間ですね\nグレゴールのために\nカロリーの高い物を\n食べに行きましょう", 1, 133801, 0, 2, 8929);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜更かしはダメですよ\n悪いスパイが暗躍して\nいる時間帯ですからね", 1, 133801, 0, 3, 8930);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふむ、座り心地は中々\nですが…私にはやはり\n玉座の方があいますね", 1, 133801, 0, 0, 8932);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふふ、いいでしょう\n我が配下に加えます\n存分に働きなさい", 1, 133801, 0, 0, 8933);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "時折晶からしていた\nあの甘い匂いは何の\nアロマだったのか…", 1, 133801, 0, 0, 8934);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "燃え盛る炎もこうして\n暖炉の中なら安全です\nクリスもあの衝動を\n管理さえできれば…", 1, 133801, 0, 0, 8935);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "そういえば真那が\n獄中で手持無沙汰に\nひたすらおにぎりを\n食べていましたね…", 1, 133801, 0, 0, 8937);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "これは、妖精学の本…\n長老の蔵書から借りて\n読みふけったものです", 1, 133801, 0, 0, 8938);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "どんな詩を\n作ろうかしら…？\n…大体、暗く\nなっちゃうけど…", 1, 134301, 0, 0, 8940);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "唱喚術の練習…\nここでやったら\n迷惑よね…", 1, 134301, 0, 0, 8941);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "チカちゃんとの\nデュエット…\n足をひっぱってない…\nかしら…？", 1, 134301, 0, 0, 8942);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "唱喚士の修行…\n滝に打たれるとか…\n崖を登るとか…\nなくて、よかった…", 1, 134301, 0, 0, 8943);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "精霊さん、肉じゃが\n食べる、かしら…？\n魔力だけだと…\n飽きちゃいそうだし…", 1, 134301, 0, 0, 8944);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "精霊さんのお世話に\n慣れたぶん…\nあのひとのお世話も\n上手にできる…はず？", 1, 134301, 0, 0, 8945);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "これからも、歌うわ…\nこの声が、彼の力に\nなる、限り──", 1, 134301, 0, 0, 8946);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "この服…踊り子さんに\n間違われちゃって…\nあ…お、お触りしちゃ\nだめよ…？", 1, 134301, 0, 0, 8947);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あなたはどんな\n精霊が…好き…？\n唱喚…してみたいわ…", 1, 134301, 0, 0, 8948);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あんまり白い服って…\n着ないの…その…\nこ、ころんだりして…\n汚すから…", 1, 134301, 0, 0, 8949);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "じ、実はね…\nこの体の模様…筆で\n書いてもらうたび…\nくすぐったい…の…", 1, 134301, 0, 0, 8950);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "精霊さん…あなたと\n遊びたいみたい…\nや、やっぱり…\nパパ…だから…？", 1, 134301, 0, 0, 8951);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あなたを歌にしたら…\n…ふふっ、だめね\n一曲じゃ…あなたを\n表現できない、わ…", 1, 134301, 0, 0, 8952);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝の修行は…\nうとうと…し…ちゃ…\n……（かくん）\n……あぅっ？", 1, 134301, 0, 1, 8953);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "せ、精霊さんと…\nかくれんぼ中なの…\nうぅ…見つからない…\n日が暮れちゃいそう…", 1, 134301, 0, 2, 8954);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "精霊さん、寝たから…\nふふっ…ここからは\nパパとふたりの時間…\n…ね？", 1, 134301, 0, 3, 8955);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふぅ…修行と育児は…\nちょっとだけ…\n休憩…ふぁ…", 1, 134301, 0, 0, 8957);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "あなたとも契約…\n…できる、かしら？\nふふっ…", 1, 134301, 0, 0, 8958);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りに包まれたら\n精神統一も\nはかどりそう…♪", 1, 134301, 0, 0, 8959);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あたたかい場所…\nここで作詞したら…\n穏やかな詩が\n書ける、かも…", 1, 134301, 0, 0, 8960);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "精霊さんのお世話を\nしていると…\nお腹、空いちゃって…", 1, 134301, 0, 0, 8962);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふふっ…♪\n色んな楽譜…\n集めるの、楽しい…♪", 1, 134301, 0, 0, 8963);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "けんぞくまだかな？\nはやく会いたいなー\nヴァンピィちゃん\nずっと待ってるからね", 1, 122301, 0, 0, 8965);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "けんぞくのこと\nずっとずっと守るよ！\nだからいつまでも\n一緒にいてね", 1, 122301, 0, 0, 8966);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "私の歌や想いを\n誰かに託せる…\nこれほどうれしい\nことはありません", 1, 134401, 0, 0, 8967);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "コッコロさんの\n包容力はすごいです\nあんなふうに私も\n人を包み込めたら…", 1, 134401, 0, 0, 8968);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "最近のボイトレは\nランファさんと一緒に\nやるんです。お互いに\n切磋琢磨しますよ！", 1, 134401, 0, 0, 8969);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "先輩として相応しい\n立ち振る舞いを\n心がけたいですね\nしっかりしなきゃ…！", 1, 134401, 0, 0, 8970);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ランファさんが\n踊ったら映えるかも…\nアイドルにも興味を\n持ってもらえないかな", 1, 134401, 0, 0, 8971);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "支え導くために\n寄り添って考える…\nあの人からたくさん\n教わったことでしたね", 1, 134401, 0, 0, 8972);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "いつだってあなたに\n恥じることのない\n姿をお見せしたいです", 1, 134401, 0, 0, 8973);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あなたの手は温かくて\n触れていると\n落ち着きますね…♪", 1, 134401, 0, 0, 8974);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "里のみんなから修行の\n差し入れを頂きました\nよろしければ、一緒に\n食べましょう♪", 1, 134401, 0, 0, 8975);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ノゾミにもお土産を\n用意したいですね\n里のお土産選び、\n付き合ってください♪", 1, 134401, 0, 0, 8976);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "精霊たちも、あなたが\n大好きみたいです♪\n優しさが伝わって\nいるんでしょうね", 1, 134401, 0, 0, 8977);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "特訓が終わったら、\n二人でどこかに\n出かけましょうか♪", 1, 134401, 0, 0, 8978);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ひゃ…す、すみません\n肌の模様を\nなぞられると、\nくすぐったくて…", 1, 134401, 0, 0, 8979);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\n精霊たちと一緒に、\n今日も頑張ります\n応援してくださいね♪", 1, 134401, 0, 1, 8980);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼の時間です\n今日も精いっぱい\n修行を頑張りましょう", 1, 134401, 0, 2, 8981);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もうすっかり夜ですね\n眠るまで子守唄を\n歌ってあげますよ？\nふふ♪", 1, 134401, 0, 3, 8982);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "無理せず休憩するのも\n大切ですよね\nふかふか～…ふふっ♪", 1, 134401, 0, 0, 8983);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "今日はこの子に\n歌の特訓を聞いて\nもらいましょう♪", 1, 134401, 0, 0, 8984);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "素敵な香り…\nふふ、精霊たちも\n気に入ったみたいです", 1, 134401, 0, 0, 8985);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかい…\nこの衣装、やっぱり\n少し冷えやすいものね", 1, 134401, 0, 0, 8986);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "特訓の後のご飯は\n美味しいですね♪\nこれでまた頑張れます", 1, 134401, 0, 0, 8987);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "唱喚士についての\n書籍はないみたい\nいつか私がここに\n楽譜を入れたいな", 1, 134401, 0, 0, 8988);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ギルドハウスの平和も\n任せてください\n何が来たって\n守ってみせますよ！", 1, 134601, 0, 0, 8992);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "このギルドハウスも\nいつの間にか出撃台に\n改造されてたり\nするんでしょうか…？", 1, 134601, 0, 0, 8993);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "戦いを経験してこそ\n実感できますね\n平和はいいもの、\n友達は素晴らしいもの", 1, 134601, 0, 0, 8994);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "次はランドソルで\n巨大ロボットが\nブームになったり？\n…さすがにないか", 1, 134601, 0, 0, 8995);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "改めて見るとこの服…\nか、体の線とか\n結構目立ってるかも…", 1, 134601, 0, 0, 8996);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "団長さんって\n知らない人とも\n話せる系ですよね\nコツはいったい…", 1, 134601, 0, 0, 8997);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ＢＢ団、世界を救う！\nまだ信じられないけど\n本当にあった出来事\nなんですよね…！", 1, 134601, 0, 0, 8998);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "パイロットも\n視力が大事なんです\n弓使いの経験が\n生きました！", 1, 134601, 0, 0, 8999);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ギガンティック\nマイフレンドくん、\n出撃！\nあ、ただの妄想です", 1, 134601, 0, 0, 9000);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "コクピットから\n降りたあとに残る\nふわふわ感…ちょっと\n癖になりませんか？", 1, 134601, 0, 0, 9001);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ひえっ、敵襲！？\nあっすみません、\nちょっと\n寝ぼけてたかも…", 1, 134601, 0, 0, 9002);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "共に戦場を駆け抜け\nＢＢ団の絆もより強く\nこれからも結束を\n強めましょうね！", 1, 134601, 0, 0, 9003);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "同じコクピットに\n乗ったのに比べれば、\nスキンシップくらい…\nや、やっぱ緊張します", 1, 134601, 0, 0, 9004);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます！\n今日もがんばりますっ\n…クローチェさんを\n見習ってみました…", 1, 134601, 0, 1, 9005);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ご飯の時間ですね\nがんばって他の人\n誘ってみようかな…", 1, 134601, 0, 2, 9006);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜の見張りは\n任せてください\n一人きりの夜も\n慣れてますから！", 1, 134601, 0, 3, 9007);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "休めるときに\n休んでおかなくちゃ\nいつ何が起こるか\n分かりませんからね", 1, 134601, 0, 0, 9009);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "師匠もこういうの\n好きだったのかな…\nなんだかしんみり\nしちゃいます", 1, 134601, 0, 0, 9010);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "香りでリラックス…\n余裕のない時でも\nこういう安らぎは\n大切ですよね", 1, 134601, 0, 0, 9011);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかい…\nこれはきっと友情と\n同じぬくもり…", 1, 134601, 0, 0, 9012);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "新鮮なご飯、感動…！\n師匠たちの世界だと\nご飯は保存食ばかり\nでしたからね…", 1, 134601, 0, 0, 9014);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "操縦マニュアル、\nしっかり読んで\n性能を引き出さなきゃ", 1, 134601, 0, 0, 9015);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "屋内で飛べなくても\nここなら平気ですっ\n助けてくれる人が\nたくさんいますからっ", 1, 134501, 0, 0, 9017);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "新ボディになってから\n人や物が前より身近に\n感じられて、わたし、\n幸せですっ♪", 1, 134501, 0, 0, 9018);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "配達以外にも何か\nお仕事したいですっ！\nハグで遊覧飛行とか、\n喜んでもらえますか？", 1, 134501, 0, 0, 9019);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "むむむ～…\n文字を書くのって\n難しいですね～っ\n練習しなくちゃっ！", 1, 134501, 0, 0, 9020);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "簡易点検、よしっ！\nポポおじいさんに\n点検の仕方を教わって\n今日も絶好調ですっ", 1, 134501, 0, 0, 9021);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "明日は北の空、\n明後日は南の空っ♪\nえへへっ、見せたい\n景色がいっぱいですっ", 1, 134501, 0, 0, 9022);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ついナイトさんを\n探しちゃいます…\nわたし、寂しんぼさん\nだったんでしょうかっ", 1, 134501, 0, 0, 9023);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "どんなところでも\nひとっ飛びっ♪\nわたしに任せて\nくださいねっ！", 1, 134501, 0, 0, 9024);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "まだ知らない機能が\nエアリアルには\n隠されてるかもっ…\nワクワクしますねっ！", 1, 134501, 0, 0, 9025);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ひゃんっ！　…あはは\nエアリアルになっても\nケーブルに触られると\nくすぐったいですねっ", 1, 134501, 0, 0, 9026);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ヴォルガーノさんに\nそっくりの子猫さんに\n最近触れたんですっ！\nかわいかったな～っ♪", 1, 134501, 0, 0, 9027);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ハグしてくれるん\nですかっ？\nえへへっ、ぎゅーっ♪", 1, 134501, 0, 0, 9028);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ナイトさんと一緒に\nいるだけで、胸が\nぽかぽか～って\nあったかいですっ♪", 1, 134501, 0, 0, 9029);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございますっ\n目覚まし飛行は\nいかがでしょうかっ？", 1, 134501, 0, 1, 9030);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ですよっ！\nいっぱい補給して\nまたフルパワーで\nがんばりましょうっ♪", 1, 134501, 0, 2, 9031);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "眠れない夜はわたしに\n任せてくださいっ！\n充填さえあればずっと\n一緒にいられますよっ", 1, 134501, 0, 3, 9032);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "歩きづらいので\nこういう休憩ポイント\nって助かります～っ", 1, 134501, 0, 0, 9034);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "スラスターを付けたら\nこの子たちも空を\n自由に飛べたり\nするんでしょうかっ？", 1, 134501, 0, 0, 9035);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "あっ、これに似た\n香りを近くのお店で\n検知したことが\nありますっ♪", 1, 134501, 0, 0, 9036);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "高熱源反応を検知っ\nわたしのスラスターも\n熱量の高さなら\nかなりものですよっ♪", 1, 134501, 0, 0, 9037);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐもぐ…っ\n食べたぶんはあとで\n真空パックにして\nお返ししますねっ", 1, 134501, 0, 0, 9039);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "本を読むのって\n楽しいですねっ♪\n前はびりびりーって\nしちゃってたのでっ", 1, 134501, 0, 0, 9040);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "なかなかの住処ですね\nこの私の別邸にして\nあげてもいいですよ♪", 1, 134701, 0, 0, 9042);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "はぁ…いつになったら\nすべての神力が\n戻るのでしょう？", 1, 134701, 0, 0, 9043);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ここも悪くないですが\n昔私が作った庭園は、\nもっと良い場所でした\n焼けちゃいましたが…", 1, 134701, 0, 0, 9044);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "うう…\nおなかが空きました…\nお米が食べたいです…", 1, 134701, 0, 0, 9045);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ここは平和ですねえ…\nジオ・ゲヘナも\nこのくらい穏やかなら\n住みやすいのですが", 1, 134701, 0, 0, 9046);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "騎士さんのおかげで\n神力が戻ってきました\n良い働きですよ♪", 1, 134701, 0, 0, 9047);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "騎士さんのいる場所が\n今の私がいるべき場所\nなのかもしれませんね", 1, 134701, 0, 0, 9048);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "頭がたかーい！\n…ですよっ！", 1, 134701, 0, 0, 9049);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ほーちゃんと呼ぶ権利\n安売りはしませんよ？\n特別ですから！", 1, 134701, 0, 0, 9050);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "私とおしゃべりを？\nまあ、いいでしょう♪\n何を話しましょうか？\nこの羽の秘密とか？", 1, 134701, 0, 0, 9051);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "小鳥扱いは\nやめなさーい！\nこれでも神様ですよ？", 1, 134701, 0, 0, 9052);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "き、気安く触るのは…\n…い、いえ、\n騎士さんなら…まぁ…", 1, 134701, 0, 0, 9053);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "絢爛豪華な絆！\nこの私と結べるなんて\n光栄でしょう？", 1, 134701, 0, 0, 9054);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふわぁぁ～\nおはようごじゃいます\n…んむむ", 1, 134701, 0, 1, 9055);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ご飯は何を…\nえっ？　私？\nそそんな゛あ゛！", 1, 134701, 0, 2, 9056);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あの…騎士さん？\n添い寝する権利とか…\nほしくないですか？", 1, 134701, 0, 3, 9057);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "はぁ～ふかふか…\n…へ？\n鳥の巣にいるみたい？", 1, 134701, 0, 0, 9059);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふむ…\nそばに置いてあげても\nいいでしょう", 1, 134701, 0, 0, 9060);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ほわぁ～\nいいかおり～", 1, 134701, 0, 0, 9061);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あたたかい…\nなんだか元気が\nでてきますねっ", 1, 134701, 0, 0, 9062);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "たくさん食べて力を\n取り戻さなくてはっ\n…んがぐぐっ", 1, 134701, 0, 0, 9064);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ…\n人の子にしては\nよく書けていますね♪", 1, 134701, 0, 0, 9065);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "素敵なお家ですね\n温かみがあって\nどこか騎士様に\n似ております。ふふ", 1, 133101, 0, 0, 9067);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "賑やかな街ですね\nこれほど活気豊かだと\nつい外に出てみたく\nなってしまいます", 1, 133101, 0, 0, 9068);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "別世界の存在は知って\nおりましたが、いざ\n目の当たりにすると\n驚きの連続ですわ", 1, 133101, 0, 0, 9069);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "この街は様々な種族が\nなにはばかることなく\n混在しているのですね\n…我々も、いつかは…", 1, 133101, 0, 0, 9070);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ランドソルにも香水の\nお店があるのですね\nどんな香りが揃って\nいるのでしょうか…♪", 1, 133101, 0, 0, 9071);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "昨日、素敵な花園を\n見つけたのです\n今日のお茶会は\nそちらでしましょうか", 1, 133101, 0, 0, 9072);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "気を抜いてはいけない\nとわかっていても、\nここだとつい安心して\nしまいます…ふう…", 1, 133101, 0, 0, 9073);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ごきげんよう\n街で見つけた茶葉を\n試しているんです\n騎士様も一杯どうぞ♪", 1, 133101, 0, 0, 9074);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "親切な方ばかりですね\n素敵なお友だちが\nできそうな予感で、\nワクワクしてます…♪", 1, 133101, 0, 0, 9075);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "黄泉の食卓の皆様用に\nお土産を用意しないと\n騎士様のお知恵も\n頼りにしておりますわ", 1, 133101, 0, 0, 9076);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ジオ・ニヴルヘルと\n比べると、この世界は\n本当に明るいですね\n少し眩しいくらいです", 1, 133101, 0, 0, 9077);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あまり、血の巡りが\n良くなくて…\n騎士様の手は\nとても温かいですね", 1, 133101, 0, 0, 9078);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "今度はわたくしに\nジオ・ニヴルヘルを\n案内させてくださいね\n観光案内のお返しです", 1, 133101, 0, 0, 9079);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\n朝の眩しい太陽には\nなかなか慣れません…", 1, 133101, 0, 1, 9080);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "騎士様、お茶は\nいかがでしょうか？\n一度一休みして、\n英気を養いましょう", 1, 133101, 0, 2, 9081);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "眠れないのでしょうか\nまぶたが重くなるまで\nわたくしをお話し\n相手になさって下さい", 1, 133101, 0, 3, 9082);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "思わず気が抜けそうに\nなってしまいます…\nふふ、ふわふわ…♪", 1, 133101, 0, 0, 9084);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "まあ、かわいらしい\nグレイスもきっと\n気に入りそうな\nデザインですわ", 1, 133101, 0, 0, 9085);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "まあ、いい香り…\n心安らぐようですわ\n素敵なセンスを\nお持ちなのですね♪", 1, 133101, 0, 0, 9086);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "燃え移りや乾燥がある\nから近づかないほうが\nいいとわかりつつも…\nああ、温かい…♪", 1, 133101, 0, 0, 9087);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食が細いというよりは\n消化があまりうまく\nできなくて…本当は\nまだ頂きたいのですが", 1, 133101, 0, 0, 9089);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "『薔薇の下の契り』？\nまあ、男性同士で…！\nそんな…こ、これ以上\nここで読むわけには！", 1, 133101, 0, 0, 9090);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ダーリンが帰ってくる\n前に部屋の掃除しよ♪\n…ふふ、これってもう\n新婚生活だよね…♪", 1, 132301, 0, 0, 9092);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "家具のセンスまで\n私と同じだなんて\n運命って怖いわ…♪", 1, 132301, 0, 0, 9093);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "あの人はベッドの下に\n何か隠してるのかな…\nな、なんて全っ然\n気にならないし…っ！", 1, 132301, 0, 0, 9094);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "うっかりして\n角引っかけないように\nしないとね…", 1, 132301, 0, 0, 9095);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "錬金術を使わなくても\nあなたの心を鷲掴む\n私は恋も錬金術も\n失敗しないんだから！", 1, 132301, 0, 0, 9096);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あの人って破廉恥なの\n興味あるのかしら…？\n基本破廉恥禁止だけど\nあの人だけは…許す…", 1, 132301, 0, 0, 9097);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "手狭になれば錬金術で\n新しい部屋作るから\nいつ家族が増えても\n安心だよね…♪", 1, 132301, 0, 0, 9098);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "錬金術でカレーライス\n作っちゃおっかな♪\n具材を釜でグツグツ…\nま、料理とも言うわね", 1, 132301, 0, 0, 9099);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "錬金術に興味がある？\nじゃあさっそく私が\n手取り足取り教えるわ\nって…やだ破廉恥っ！", 1, 132301, 0, 0, 9100);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "イロハちゃんとの\n虫捕りは命懸けよ！\n一万匹捕れるまで\n帰れないんだから…", 1, 132301, 0, 0, 9101);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ソノさんって\n体は小さいけど\nとっても頼れる私の\nお姉さん的存在なの♪", 1, 132301, 0, 0, 9102);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "はあ…部屋中に広がる\nダーリンの香り…♪\n…ってノゾミみたいに\nなっちゃってる！？", 1, 132301, 0, 0, 9103);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "鹿の獣人族の特徴は\nこのエッチな角…\n違っ！　叡智よ叡智！\n噛んだだけだからっ！", 1, 132301, 0, 0, 9104);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あ、おはよう！\n寝る前に飲んだ\n目覚めすっきり秘薬の\n効果はバッチリかな？", 1, 132301, 0, 1, 9105);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "午後からも頑張る\nあなたのために\n愛妻弁当作ったの♪\n一緒に食べよ？", 1, 132301, 0, 2, 9106);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日も一日お疲れさま\n眠れないなら隣で…\nじゃなかった早寝して\n明日も頑張ろうね！", 1, 132301, 0, 3, 9107);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "いい錬成をするには\n適度な休憩も必要よね\n…気持ち良くてたまに\n寝落ちしちゃうけど…", 1, 132301, 0, 0, 9109);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいぬいぐるみ\n錬成じゃなくて\n手編みで作ったら\n驚いてくれるかも♪", 1, 132301, 0, 0, 9110);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "くん、くん…\nん～いい匂い♪\nノゾミの香水と\nいい勝負だわ", 1, 132301, 0, 0, 9111);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ああ、暖かい\nでもソノさんの作った\nミートパイの方が\nもっと温かいわ…♪", 1, 132301, 0, 0, 9112);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…私も\n食べても減らない秘薬\n錬成して他の食べ物も\n作れないかな？", 1, 132301, 0, 0, 9114);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ…\nこのレシピ面白いわね\n今度錬成してみよっと", 1, 132301, 0, 0, 9115);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "おー、体が軽い\n腰痛も胃もたれも\nないし、最高かよ", 1, 132501, 0, 0, 9117);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "いっつも力入れてたら\nいざって時困るし\nやっぱ省エネだな", 1, 132501, 0, 0, 9118);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "やば…なんか急に\nブドウ朱飲みたい…\nルイちゃんに頼むか？\nいや、でもなあ…", 1, 132501, 0, 0, 9119);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "あれ、あの材料の在庫\nまだあったっけ…\nルイちゃんに確認しよ", 1, 132501, 0, 0, 9120);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "イロハのやつ変な\nイタズラしてない\nといいけど…", 1, 132501, 0, 0, 9121);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "今日のシフトは～…\nお、彼と一緒じゃん\nふふっ…", 1, 132501, 0, 0, 9122);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "イロハのやつ\n不用意に私の体で\n彼に抱きつくなって\nこっちが恥ずかしい…", 1, 132501, 0, 0, 9123);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日も元気だねえ\n若いってうらやま…\nっていや、今は私の\n方が若いじゃん", 1, 132501, 0, 0, 9124);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ん～？　どしたん\nヒマならうちの店で\nバイトしてく？", 1, 132501, 0, 0, 9125);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "イロハ見なかった？\n今日は手伝うって約束\nしてたのにさあ…", 1, 132501, 0, 0, 9126);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ルイちゃん特製\nエナドリ（子ども用）\nこれ飲んで今日も\nお仕事頑張るかー", 1, 132501, 0, 0, 9127);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "元の体なら\n君と目線、合うのにね\n…ってドラマかよ\nごめん、今の忘れて", 1, 132501, 0, 0, 9128);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "なんかヒマそうじゃん\n用事ないなら\nお姉さんがコーヒー\n淹れたげよっか", 1, 132501, 0, 0, 9129);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふわあ…おはよ\n今日もお仕事\nがんばりますかー", 1, 132501, 0, 1, 9130);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ちょうどいいや\n一緒にお昼どうよ\nお姉さんが\n奢ってあげよう", 1, 132501, 0, 2, 9131);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふぁぁ…ふぅ\nここからは大人の時間\nなんだけどさぁ\n眠くてかなわん…", 1, 132501, 0, 3, 9132);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "おお～なんか前より\nでっかく感じるわ～\nてそりゃそうか", 1, 132501, 0, 0, 9134);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "そいえば、イロハって\nあんまこういうの\n欲しがらなかったな～\nクワガタばっかで", 1, 132501, 0, 0, 9135);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "はあ…いい匂いだね\nさすがルイちゃん特製\n錬金アロマ\n次の目玉商品だな", 1, 132501, 0, 0, 9136);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ユカリっち焚火の前で\nキメる麦しゅわに\nハマってるらしいけど\n興味あるわぁ…", 1, 132501, 0, 0, 9137);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "うわこれ…\n無限にいけちゃうわ\n子どもの胃袋\n恐るべし…", 1, 132501, 0, 0, 9139);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむ、こんな需要が…\n次の新商品として\nルイちゃんに試作\n頼んでみるか～", 1, 132501, 0, 0, 9140);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "服はその人の個性です\n仕立て屋は\nその手伝いをする\nプロなんです♪", 1, 134801, 0, 0, 9142);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "糸を紡いで紡いで\n巻き巻き～♪", 1, 134801, 0, 0, 9143);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ふむ…あの人の衣装\nなかなか斬新ですね\n後でどうなってるのか\n見せてもらおう♪", 1, 134801, 0, 0, 9144);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "動きやすさと\nファッション性\n両立させてみせますよ", 1, 134801, 0, 0, 9145);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "今度のコレクション\n新作にワイルドな\nルームウェアは\nどうかな…？", 1, 134801, 0, 0, 9146);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "騎士さんもたまには\n衣装の感想とか言って\nくれてもいいのにな～", 1, 134801, 0, 0, 9147);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ノゾミさんとチカさん\nにも、おそろいの服を\nプレゼントしてみよう\n二人とも似合いそう♪", 1, 134801, 0, 0, 9148);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ジオ・ゲヘナでまた\n素材収集したいんです\n手伝ってくれますか？", 1, 134801, 0, 0, 9149);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "えっ？　薄着すぎ？\nおしゃれのためなら\nこのくらいへっちゃら\nですよ…っくしゅん！", 1, 134801, 0, 0, 9150);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "穴が開いてる？\nこれはそーいう\nデザインですー！", 1, 134801, 0, 0, 9151);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ちょっとどこ\n触ってるんですかー！\n…あ、糸くず\n取ってくれたんですね", 1, 134801, 0, 0, 9152);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "騎士さんに\n新しい生地の服を…\nいや、シャレじゃ\nないですよ？", 1, 134801, 0, 0, 9153);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "素敵な着こなしには\n健康な体も大切！\n騎士さんに見られても\n恥ずかしくないように", 1, 134801, 0, 0, 9154);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます！\nさあ、着替えて！\n私が見繕ってあげます", 1, 134801, 0, 1, 9155);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼は激辛料理です\nジオ・ゲヘナで\nハマッちゃって…\n一緒にどうですか？", 1, 134801, 0, 2, 9156);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "睡眠不足は美容の大敵\nていうかシンプルに…\nね、眠い…", 1, 134801, 0, 3, 9157);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "くつろげますね～\nでももうちょっと\n生地の手触りが…\nって、職業病？", 1, 134801, 0, 0, 9159);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいものって\n心を癒してくれますね\n服もそうありたいです", 1, 134801, 0, 0, 9160);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り～♪\nこの匂いにはどんな服\nが合うかなあ…？", 1, 134801, 0, 0, 9161);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "この服露出が多いから\n温かいとほっとする～\nずっとこうして\nいたいかも…", 1, 134801, 0, 0, 9162);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いくらでも\n食べられちゃうから、\n自分でストップ\nかけないと…", 1, 134801, 0, 0, 9164);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "しっかり勉強して\nジオ・ゲヘナに\nお洒落を伝えたいです", 1, 134801, 0, 0, 9165);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "あたくしは高貴なる\nマンティコア！\nサソリでもコウモリ\nでもありませんわよ♪", 1, 134901, 0, 0, 9167);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "なかなか居心地がいい\nお部屋ですわね～\n…さてどうやって\nあたくしのものに…", 1, 134901, 0, 0, 9168);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "高貴なるお審美眼で\nあの家具の価値を\n測ってやりますわ\n…ギリ合格ですわ！", 1, 134901, 0, 0, 9169);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "高貴なる笑い声は\n一日にしてならず\nお子様の頃から練習を\n重ねてきたのですわ！", 1, 134901, 0, 0, 9170);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "お美しいあたくし様と\n同じ空間にいられる…\nどうぞその喜びを\n噛みしめなさいな♪", 1, 134901, 0, 0, 9171);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "アナタがお土下座して\n頼むなら、あたくしも\nもう少しここに残って\n構いませんわよ♪", 1, 134901, 0, 0, 9172);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "馬ボーンをあたくしに\n振り向かせるには\nどうしたら…って、\nこの言い方は語弊が！", 1, 134901, 0, 0, 9173);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "少し寒いですわね…\n…この服装のせい？\nこっちだって好きで\n着てねぇですわよ！", 1, 134901, 0, 0, 9174);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あのラミアが来たら\nあたくし様はお用事で\nお留守って言って\n追い返すんですのよ！", 1, 134901, 0, 0, 9175);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "こっちの世界にも\n闘技場がありますの？\nそこもお頂点を極めて\nしまおうかしら～♪", 1, 134901, 0, 0, 9176);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "馬ボーンって\n人畜無害そうなお面の\nわりに、時々やること\nえげつねぇですわね…", 1, 134901, 0, 0, 9177);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ねぇ馬ボーン…\nアナタあの魔札、\nまだ持ってまして？\nとっとと捨てなさい！", 1, 134901, 0, 0, 9178);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "絶対にあたくし様の\nお尻尾に触るんじゃ\nねぇですわよ…？\nいえ、振りではなく！", 1, 134901, 0, 0, 9179);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふわぁ…\n打倒ネフィのお作戦を\n夜通し考え過ぎて、\n寝不足ですわぁ…", 1, 134901, 0, 1, 9180);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "もうお昼ですの？\nあたくし様に相応しい\n優雅なおランチと\n参りますわよ～♪", 1, 134901, 0, 2, 9181);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あら馬ボーンったら\nまだ起きてますの？\n…ぐぬぬ、夜の間に\n仕掛ける作戦が…", 1, 134901, 0, 3, 9182);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "このおフカフカ感…♪\n剣闘士宿舎の\nゴワゴワなお寝床とは\n大違いですわね！", 1, 134901, 0, 0, 9184);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "なんですの、この\n弱っちそうなお顔は…\nおかわいそうですし、\nお僕にしてあげますわ", 1, 134901, 0, 0, 9185);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "馬ボーンはこういう\n匂いが好みですの？\nふーん…ほーう…\nなるほどですわ…♪", 1, 134901, 0, 0, 9186);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あぁ～～…\nそうそう、これくらい\n暑い方が快適ですわ…", 1, 134901, 0, 0, 9187);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ、もぐっ…\nまぁそこそこ？\n悪くないお味では\nありますわねっ", 1, 134901, 0, 0, 9189);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "こんな本よりも、\n華麗なるカノン様の\n活躍録でも置いた方が\n世のためになりますわ", 1, 134901, 0, 0, 9190);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "さっきねー、外で猫と\n木登り競争したんだよ\nなかなか手ごわい\n相手だった！", 1, 132401, 0, 0, 9192);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "いっぱい食べて\n大きくなるんだ～\nあっでもこれ\nソノちゃんの体か", 1, 132401, 0, 0, 9193);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "強いおねーさんの\n気配を感じる…\nどこから？\n…そこら中から！", 1, 132401, 0, 0, 9194);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "虫捕り網の手入れは\nいつもバッチリ！\nいつ何が出るか\nわからないもんね", 1, 132401, 0, 0, 9195);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "うちの中で走り回ると\nソノちゃんに\n怒られちゃうけど…\nここならいける？", 1, 132401, 0, 0, 9196);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "おじちゃんも\nお部屋にいろいろ\n隠してるのかな？\nルイちゃんみたいに", 1, 132401, 0, 0, 9197);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "世界一になったら\nおじちゃんにも\nいっぱい褒めて\nほしいな…約束っ♪", 1, 132401, 0, 0, 9198);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "高いとこのものが\n取りたいときは\nイロハに言ってね\nイロハ得意だから！", 1, 132401, 0, 0, 9199);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "どうも、イロハです\n剣士たるもの、\nあいさつは大事って\n教わったんだ♪", 1, 132401, 0, 0, 9200);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "イロハと勝負だね！\n受けて立つよ～！\n…あれ、違った？", 1, 132401, 0, 0, 9201);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あっ！　ルイちゃんに\n素材集め頼まれてたの\n忘れてた…！　やばい\nおじちゃん手伝って！", 1, 132401, 0, 0, 9202);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "実はイロハって\n褒めたら伸びる\nタイプなんだ\nだからよろしくね♪", 1, 132401, 0, 0, 9203);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "このお部屋、すごく\n居心地がいいんだ～\nやっぱりおじちゃんが\nいるからかな？", 1, 132401, 0, 0, 9204);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "昨日仕掛けた罠で\n虫捕れてるかな？\nあとで一緒に\n見に行こうね♪", 1, 132401, 0, 1, 9205);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "もうお昼だよね？\nイロハのお腹が\n空いてきたから\n間違いないよ！", 1, 132401, 0, 2, 9206);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ふわぁ～…\nあ、あくびじゃないよ\nイロハ大人なんだから\n眠くなんか…ふわぁ…", 1, 132401, 0, 3, 9207);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふわふわしたものって\nつい飛び込みたく\nなっちゃうよね\n…うずうずっ", 1, 132401, 0, 0, 9209);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいのもいいけど\nカッコよさも欲しいな\nそーだ、角とかもっと\nいっぱい付けてみる？", 1, 132401, 0, 0, 9210);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "おー、いい匂い♪\nこれもしかして\nルイちゃんの新作？\n爆売れ間違いなしだよ", 1, 132401, 0, 0, 9211);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ぬくぬくぽかぽか、\n気持ちいいー…\nでもちょっと\n暑くなってきたな", 1, 132401, 0, 0, 9212);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐもぐ…\nこれはいい食材を\n使っておりますなぁ\nうん、三ツ星！", 1, 132401, 0, 0, 9214);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむなるほど…\nこっ、これは…！\n…ごめん、適当に\n言ってみた", 1, 132401, 0, 0, 9215);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "また海に行く時に\n備えて…次の計画を\n練る必要がある…", 1, 135001, 0, 0, 9217);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "騒がしいのも…\n以前ほど気にならない\n慣れてしまった…？", 1, 135001, 0, 0, 9218);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "眩暈がする暑さも\n騎士クンと同じ気温を\n感じられるなら…いい", 1, 135001, 0, 0, 9219);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "騎士クンに\n好意を抱く者は\nみんな有罪\n…わたしは例外", 1, 135001, 0, 0, 9220);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "体も心も…外の世界に\n馴染んできた気がする\n少しずつ、だけど…", 1, 135001, 0, 0, 9221);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "騎士クンの手…\n大きかった…\n…また、つなぎたいな", 1, 135001, 0, 0, 9222);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "夏が終わっても…\nその先の季節も\n…その次の夏も\n騎士クンと一緒に…", 1, 135001, 0, 0, 9223);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "騎士クンといるとね\n渇いてた心が…\n潤される、気がするの", 1, 135001, 0, 0, 9224);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "騎士クンは…\nしたいこと、ある？\n夏にだけ…できること\n一緒に、しようね", 1, 135001, 0, 0, 9225);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "仮想領域の夢でも\n現実の海でも…\n騎士クンと一緒なら\nそこが本物の夏、だね", 1, 135001, 0, 0, 9226);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "肝試しがしたい…？\n…うまく驚けるかな\n練習しなくちゃ…", 1, 135001, 0, 0, 9227);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "騎士クンとなら\nどんな夏でも…\nきっと楽しい…♪", 1, 135001, 0, 0, 9228);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "水着…どうかしら…？\n…よかった\nシミュレーションの\n成果ね。ふふ", 1, 135001, 0, 0, 9229);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "騎士クン…眠たそう\nもうちょっと…寝る？\n後で起こしてあげるね", 1, 135001, 0, 1, 9230);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お出かけするなら\n水筒を用意するね…\n夏の水分補給は大事…", 1, 135001, 0, 2, 9231);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "また…夜の海を\n見に行きたいな\n騎士クンと一緒に\n連れていってくれる？", 1, 135001, 0, 3, 9232);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "騎士クンを待つには\nちょうどいい…\n…落ち着く…", 1, 135001, 0, 0, 9234);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "こういう物を\n城に置いた方が\nかわいいって思って\nもらえる…かな…？", 1, 135001, 0, 0, 9235);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "夏に合わせた香りね…\n涼やかな風が胸を\n吹き抜けるような…", 1, 135001, 0, 0, 9236);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "火は落ち着く…\n身体感覚を味わえる\n作り物の…この体でも", 1, 135001, 0, 0, 9237);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "『食』…騎士クンと\n話す共通の話題には\n悪くなさそう…", 1, 135001, 0, 0, 9239);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "『好きな人と楽しめる\n夏デート特集』…？\n……ふむ…", 1, 135001, 0, 0, 9240);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "わたしの趣味では\nないけれど…\n騎士クンが望むなら\n城に置いても…？", 1, 135001, 0, 0, 9242);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "む…悪くない\nこれなら\n騎士クンと一緒に…？", 1, 135001, 0, 0, 9243);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "一日中水着でいるって\n浮かれているみたいね\n夏は短いから、沢山\n楽しまなくちゃね", 1, 135101, 0, 0, 9244);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ちょっと暑いし\n氷の上を滑って\n涼もうかしら", 1, 135101, 0, 0, 9245);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "そろそろ運送ギルドの\nアルバイトの時間だわ\n準備しなきゃ", 1, 135101, 0, 0, 9246);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "エリスさん、水着が\nすごく似合ってた…\nどこで買ったのかしら", 1, 135101, 0, 0, 9247);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "未練が残らないように\nこの夏休みでやりたい\nことはやらなくちゃ", 1, 135101, 0, 0, 9248);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "かき氷を作ったら\n彼も食べるかしら？\nアイスクリームの\nほうがいいかな…", 1, 135101, 0, 0, 9249);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "水着を着ていれば\nどこにいても\nリゾート気分だわ♪", 1, 135101, 0, 0, 9250);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "夏はおいしいものが\nたくさんあるし\n【美食殿】の活動も\n忙しくなりそうね♪", 1, 135101, 0, 0, 9251);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "わ、私の尻尾…\nそんなに気になる？\nつついたらダメよ\nいいわね…？", 1, 135101, 0, 0, 9252);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夏は日が長いし\nまだまだたくさん\n遊べそうね♪", 1, 135101, 0, 0, 9253);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "今日は一緒に海に\n行かない？\nあなたも水着\n持ってきてるでしょ", 1, 135101, 0, 0, 9254);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "そろそろ日焼け止めを\n塗り直さなきゃ…あの\nお願いしてもいい…？", 1, 135101, 0, 0, 9255);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "私たちで最高の\n夏休みにしましょう\nね、おにーたん♪", 1, 135101, 0, 0, 9256);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "夏の朝は早いわね\nもうセミも鳴いてるし\nあなたも早起きだわ…\n見習わなくちゃ", 1, 135101, 0, 1, 9257);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "日中は暑いだろうし\nゆっくりしましょう\nお昼寝タイムはどう？", 1, 135101, 0, 2, 9258);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "この時間のアイス\nクリームは格別よね♪\n何味にしようかしら", 1, 135101, 0, 3, 9259);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "暑い夏はしっかり\n休むことが大切\nふぅ…いい気持ち♪", 1, 135101, 0, 0, 9261);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふわふわの毛並み\n暑くないのかしら\nかわいいだけじゃなく\n忍耐強くもあるのね", 1, 135101, 0, 0, 9262);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "爽やかでいい匂い…♪\nジトジトしがちの夏に\nピッタリなアロマね", 1, 135101, 0, 0, 9263);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ずっと水着でいると\n流石に冷えるわね\nうん、いい心地だわ", 1, 135101, 0, 0, 9264);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "はむっはむっ…\nしっかり食べて\n夏バテ対策しないと", 1, 135101, 0, 0, 9266);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむふむ…面白いわね\n今度プレシアちゃんと\n一緒に読もうかしら", 1, 135101, 0, 0, 9267);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "私のフロートと少し\n似ている気がする\nサイズ的にはこっちが\nお兄さんかしら…ふふ", 1, 135101, 0, 0, 9269);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "ふふ、きれい♪\nまるで\n海のステージね！", 1, 135101, 0, 0, 9270);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "じゅんび、おっけー\nうみでも\nおふろでも\nおんせんでも", 1, 135201, 0, 0, 9271);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ひまわり。すき\nおっきくて\nたね、うまし", 1, 135201, 0, 0, 9272);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ハッピーちゃん\nいい、におい\nひやけ？\nやきぶた？", 1, 135201, 0, 0, 9273);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "じーわ、じーわ…\nせみの、なきごえ\nきいてる、だけで\nあつい。かも…", 1, 135201, 0, 0, 9274);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "アイス、かきごおり…\nあつい、なつ\nだから\nひえひえ、ひっす", 1, 135201, 0, 0, 9275);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "おっきくなるまほー\nきわめたい\nお兄を\nだっこ。するよ", 1, 135201, 0, 0, 9276);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "「あなた」\n…ちょっと、ちがう？\nシェフィたち\nみたいに、ならない…", 1, 135201, 0, 0, 9277);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "じゃりじゃり\nべたべた\n…シャワー\nいって、きます", 1, 135201, 0, 0, 9278);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "（すんすん）\nお兄。ほんのり\nうみの、におい\nおいしそう", 1, 135201, 0, 0, 9279);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "お兄。みて\nべろ、まっさお\nぶるーはわい\nカラー", 1, 135201, 0, 0, 9280);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あつくても\nあついもの\nおいしい\n…バーベキュー…", 1, 135201, 0, 0, 9281);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ついんて\nバランス、むずかし\nお兄\nリボン、よろ", 1, 135201, 0, 0, 9282);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "みずぎ\nにあってる。って\nお兄。いった\nもっと。みて？", 1, 135201, 0, 0, 9283);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよ\nあさごはん\nやきざかな", 1, 135201, 0, 1, 9284);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おひる\nおひるね\nいっしょに、しよ？", 1, 135201, 0, 2, 9285);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おそと\nまっくら\nはなび\nしよ？", 1, 135201, 0, 3, 9286);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふわぁ…\nあそびすぎ\nおつかれ\nねむねむ", 1, 135201, 0, 0, 9288);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "よしよし\nおるすばん\nおねがい。ね", 1, 135201, 0, 0, 9289);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "（くんくん）\nれもんの、におい\nじゅる", 1, 135201, 0, 0, 9290);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "さかな、くしやき\nすたんばい、おっけー\nいつでも、やける。よ", 1, 135201, 0, 0, 9291);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いっぱい、あそびたい\nいっぱい、つよくなる\nいっぱい、たべる", 1, 135201, 0, 0, 9293);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "おさかなの、ほん\nおもしろかった\nでも\nおなかが…", 1, 135201, 0, 0, 9294);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "れっつ、ごー\nすいへーせん\nせかい\nいっしゅー", 1, 135201, 0, 0, 9296);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "きぶんは、かいばしら\nバターやき\nおすすめ", 1, 135201, 0, 0, 9297);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "成長して着れなく\nなっちゃう前に\nこの水着でできること\n全部しちゃいたいな♪", 1, 135301, 0, 0, 9298);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "お家で水着だと\n開放的な気分かも♪\nふふ、お兄さんにも\n教えてあげなきゃ♪", 1, 135301, 0, 0, 9299);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "泳ぎの練習しちゃお♪\nすいすい、すいすいー\n…ちょっと、\n子供っぽかったかも…", 1, 135301, 0, 0, 9300);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "インドア派だけど\n夏の屋外は好き…や…\nお兄さんと一緒なら\nどこでも…", 1, 135301, 0, 0, 9301);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "夏だからってちょっと\n羽目外しすぎかな…\nわたし…やっぱり\n真面目じゃない…かも", 1, 135301, 0, 0, 9302);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "わたしの水着姿…\n少しは大人っぽいって\n思ってくれたかな…？", 1, 135301, 0, 0, 9303);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "家の中は涼しいのに\nお兄さんのこと\n考えると暑くなって…\n夏バテしちゃいそう…", 1, 135301, 0, 0, 9304);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お兄さんと一緒なら\n夏休みの日記\n書くことが多すぎて\nページが足りません♪", 1, 135301, 0, 0, 9305);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "かき氷食べましょ♪\n…ふふ、お兄さん\n舌の色すごいですよ♪\nわたしも…べ～っ♪", 1, 135301, 0, 0, 9306);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日は海に行きます？\nそれともお家で\nのんびりですか？\nわたしはどっちでも♪", 1, 135301, 0, 0, 9307);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "夏バテしないように\nスタミナ料理のレシピ\nお勉強しました♪", 1, 135301, 0, 0, 9308);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "夏が終わっちゃっても\nこの水着を着てたら\n夏の思い出、忘れずに\nいてくれますか…？", 1, 135301, 0, 0, 9309);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "…この日焼け跡\nお兄さんと\nわたしだけの\n秘密…ですよ？", 1, 135301, 0, 0, 9310);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます！\n朝の体操１、２、３♪\nしゃきっと目覚めて\nいい一日にしましょ♪", 1, 135301, 0, 1, 9311);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼休憩ですね♪\n午後からも頑張れる様\nお兄さんのこと\n癒しますね…♪", 1, 135301, 0, 2, 9312);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ寝る時間…\nお兄さんが眠るまで\n一緒にいますね…\n…ふあぁ…", 1, 135301, 0, 3, 9313);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "気持ちいいけど、汗…\n染みちゃわないように\n気をつけないと…", 1, 135301, 0, 0, 9315);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ぎゅう～♪\nなんて、ちょっと\nあざといかな…♪", 1, 135301, 0, 0, 9316);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "夏にぴったりの\nフルーティーな香り♪\nお兄さん、好きかな？", 1, 135301, 0, 0, 9317);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "水着で暖まるのって\nなんだか贅沢な気分♪\nこたつでアイス的な♪", 1, 135301, 0, 0, 9318);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "お腹ぽっこりに\nならないよう\n気をつけないと…\nでも止まらない…", 1, 135301, 0, 0, 9320);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "弾ける水着でビーチの\n視線を独り占め…かぁ\nわたしはお兄さんの\n視線だけで…なんて♪", 1, 135301, 0, 0, 9321);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "これで夏の大冒険に\nしゅっぱ～つ！\n…なんちゃって♪", 1, 135301, 0, 0, 9323);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "なんだか女神さま\nみたい…？\nふふ、わたしには\n似合わないかもです♪", 1, 135301, 0, 0, 9324);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "真っ白い日差し─\nジオ・ゲヘナには\nなかったものですね\n─悪くはないです", 1, 135401, 0, 0, 9325);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "しばらくここで\n休んでます\n人の多い街中よりは\n落ち着くので─", 1, 135401, 0, 0, 9326);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ここにも─\nあるんでしょうか\n海で使う遊び道具…", 1, 135401, 0, 0, 9327);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "見張りは─\nここならあまり\n必要なさそう…", 1, 135401, 0, 0, 9328);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "夏のバカンス─\n媛が楽しんでるなら\n私は十分です", 1, 135401, 0, 0, 9329);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "知らない相手は、\n苦手だけど─\n…少しだけ、\n話してみても…", 1, 135401, 0, 0, 9330);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ここにいると\n安心する、ような…\n土壌が─良い…？", 1, 135401, 0, 0, 9331);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "夏の正装、水着─\n着方、間違えて\nないですよね…？", 1, 135401, 0, 0, 9332);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "相変わらず、\nおしゃべりが\n好きなんですね\n私は─普通です", 1, 135401, 0, 0, 9333);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "─喉が渇きました\n…いえ、花にお水が\n欲しいわけじゃなくて", 1, 135401, 0, 0, 9334);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "─いつもより\n花がつやつやしてる？\n…あ、褒めて\nくれたんですか", 1, 135401, 0, 0, 9335);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "この部屋─\n貴方が飾りつけを？\nわかります、何となく", 1, 135401, 0, 0, 9336);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "すぐ傍にいると、\n暑くなりませんか？\n─私は別に\nかまいませんが", 1, 135401, 0, 0, 9337);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝から元気ですね─\nおかげですっかり\n目が覚めました", 1, 135401, 0, 1, 9338);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "外─暑そうです\n出かけるなら\n気を付けてください\n倒れたりしないよう…", 1, 135401, 0, 2, 9339);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "─貴方も\n夜更かしですか？\n…少しだけなら\n付き合いますよ", 1, 135401, 0, 3, 9340);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "貴方もここで\n休みたいですか？\n─ダメです\n今は私が使うので", 1, 135401, 0, 0, 9342);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ゆるい顔つきですね\nジャングルでは\n生き残れそうに\nないです─", 1, 135401, 0, 0, 9343);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "─ん…\nこれ、海の香り？\n─いい匂い…", 1, 135401, 0, 0, 9344);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "…暑さには\n慣れてますよ\n寒いのよりは、ずっと", 1, 135401, 0, 0, 9345);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "栄養は、大事です\n味は─あまり\n気にしたこと、\nありませんでした", 1, 135401, 0, 0, 9347);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "適当に本を読んでいる\nだけです─\n…別に、遊びについて\n調べたりしてません", 1, 135401, 0, 0, 9348);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "魔物を模した\n人形─ですね\n戦闘訓練用に？", 1, 135401, 0, 0, 9350);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "貝のクッションですか\n─噛みついてきたり\nしないですよね", 1, 135401, 0, 0, 9351);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "シントーメッキャク\n火もまた涼し…\nむむむ…やっぱり夏は\n暑いデース！", 1, 137101, 0, 0, 9352);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "海にも新しい忍法の\nヒントがあるはずデス\nショーグンと海底散歩\nも楽しそうデス", 1, 137101, 0, 0, 9353);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "釣りの心得は\nメイキョーシスイ…\n忍者の修行に\nうってつけデス♪", 1, 137101, 0, 0, 9354);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "天下統一の後のことも\n考えねばなりまセン\n今度はテンジョー統一\nデスかね…？", 1, 137101, 0, 0, 9355);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "デケデケデン♪\nテルテル坊主完成デス\n晴れてないとお外で\n遊べまセンからね！", 1, 137101, 0, 0, 9356);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "次のオモテナシも\nショーグンをワクワク\nさせマス♪　今から\n用意しておかねばデス", 1, 137101, 0, 0, 9357);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "新しい忍法の開発に\n休みはないのデス！\nショーグンの天下統一\nを思えばなんのその！", 1, 137101, 0, 0, 9358);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "海の前に準備運動デス\nまずは手を後ろに、\n素早く忍者走り！\nシュバババッ", 1, 137101, 0, 0, 9359);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "夏にお祭りは\n欠かせないデスよね♪\n地域のイベント情報は\n見逃しまセン！", 1, 137101, 0, 0, 9360);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ショーグン、団扇で\nあおいであげマス！\n忍法・扇風の術ー！\nうりゃりゃりゃー！", 1, 137101, 0, 0, 9361);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ワタシが必要な時は\n風鈴を鳴らすデス！\n風よりも早く\n駆けつけマスよ！", 1, 137101, 0, 0, 9362);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "じっと見つめられると\n顔が熱くなってきて…\nはっ、ショーグンの\n新しい忍法デスか！？", 1, 137101, 0, 0, 9363);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ショーグン、日焼けは\nノン、デスよ！\nワタシがクリームぬり\nぬりしてあげマース！", 1, 137101, 0, 0, 9364);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようデス！\n朝ごはんはワタシに\nお任せデス。\n毎日みそ汁作るデス！", 1, 137101, 0, 1, 9365);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "日差しに注意デスよ\nネッチューショーに\n日焼け、どっちも\n大変デスからね！", 1, 137101, 0, 2, 9366);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ショーグン、\n外で花火しまショウ！\nぱちぱちキレイで\n楽しいデスよ！", 1, 137101, 0, 3, 9367);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "遊びに備えて\n今は休む時…\nガシンショータンデス", 1, 137101, 0, 0, 9369);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "この子たちにも\n手伝ってもらって\n新しい忍法を開発\nしてみまショウ♪", 1, 137101, 0, 0, 9370);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "むむっ、ここまで\n潮の香りが漂って\nきた気がしマス！", 1, 137101, 0, 0, 9371);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "海に入った後は\n体を温めねば\nやはりサウナも\n必要デスね！", 1, 137101, 0, 0, 9372);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いっぱい食べて\nいっぱい遊ぶデス！\n夏バテなんかに\n負けてられまセン！", 1, 137101, 0, 0, 9374);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "『BUSHIDO』の\n最新刊が待ち遠しい\nデス…マイゾーキン\n特集、読みたいデス", 1, 137101, 0, 0, 9375);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "ショーグンとこの子に\n乗って、天下統一まで\nシュババババッ！\nなんてどうでショウ", 1, 137101, 0, 0, 9377);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "ぽよんぽよ～ん♪\nショーグンと一緒に\n遊んでみたいデス♪", 1, 137101, 0, 0, 9378);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "今度はシナツちゃんの\n世界へ行ってみたいな\nエリスちゃんも誘って\n大人女子旅とか最高♪", 1, 135501, 0, 0, 9379);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "あっはっはー！\nよし、今日も絶好調！\nま、いつも笑ってたら\n不調なんてないけど♪", 1, 135501, 0, 0, 9380);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ん～あっちの世界と\nほとんど一緒だね！\n違ってるところ探しに\n出かけてみよっかな？", 1, 135501, 0, 0, 9381);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ううーん、のんびり\nするのもいいけど\nどこか行ってみたいな\n人助けとか、ね", 1, 135501, 0, 0, 9382);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "あっ、そーだ\n向こうへ帰る前に\nこっちのお土産とか\n買っとかなくちゃ", 1, 135501, 0, 0, 9383);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ふ～ん、騎士くんって\nこういうのが好みか～\n後でヒヨリちゃんに\n教えてあげよ♪", 1, 135501, 0, 0, 9384);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "次はあたしが恩を返す\n番だね。騎士くんに\n助けが必要になったら\n絶対駆けつけるよ！", 1, 135501, 0, 0, 9385);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あっ騎士くん！\n困ってることない？\nお姉さんがなんでも\n力になっちゃうよ！", 1, 135501, 0, 0, 9386);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "また闘技場に行こうよ\nちょっと運動不足でさ\nバーンと暴れたい気分\nなんだよね♪", 1, 135501, 0, 0, 9387);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "いつか大人になったら\n一緒に飲もうよ！\nあははっ、騎士くん\n指切りげんまん♪", 1, 135501, 0, 0, 9388);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "一緒に作った麦しゅわ\nカップ、最高だね♪\n騎士くんの分もどうぞ\nちゃんとジュースだよ", 1, 135501, 0, 0, 9389);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ねえ…ぶっちゃけ\nヒヨリちゃんのこと\nどう思ってるのかな？\nお姉さんに聞かせなよ", 1, 135501, 0, 0, 9390);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "騎士くん、うっかり\n飲みすぎたあの日の\nコトは誰にも内緒で\nお願いね。約束だよ！", 1, 135501, 0, 0, 9391);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あはは、騎士くん\n新しい朝だよー！\n今日はどんな一日か\nワクワクするね～♪", 1, 135501, 0, 1, 9392);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "午後からも笑顔で\n元気に乗り切ろうね！\n外に行くもよし、\n部屋で麦しゅわもよし", 1, 135501, 0, 2, 9393);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ここからは大人の時間\n騎士くんにはまだ少し\n早いかな～？\nだから、おやすみ♪", 1, 135501, 0, 3, 9394);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "麦しゅわ飲み過ぎた\n夜はここにダーイブ\n…なんて大人に\nなっちゃダメだよ～？", 1, 135501, 0, 0, 9396);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "あたしの世界の子たち\nこういうの好きかな？\nお土産に探してみよう\n気に入るかも♪", 1, 135501, 0, 0, 9397);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ん～いいね♪\nあとでお気に入りの\nフレーバーも\n試してみよっかな？", 1, 135501, 0, 0, 9398);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ほうほう…熱い！\nサラサリアは\nいつも暖かいから\nこういうの新鮮！", 1, 135501, 0, 0, 9399);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ん～おいしい！\nけどやっぱご飯は\nみんなで一緒に\n食べたいな～", 1, 135501, 0, 0, 9401);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "文字ばっかの本は\nちょーっと苦手かも…\n必要なら読むけどさ？", 1, 135501, 0, 0, 9402);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "皆思い思いに過ごして\nいるのに、不思議と\n落ち着く。いつまでも\nここにいられたら…", 1, 135601, 0, 0, 9406);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "皆に挨拶をせねば\n…いや、今は、まだ\nタイミングが悪い…\nまた今度にしよう…", 1, 135601, 0, 0, 9407);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "私の服装…この場で\n浮いてないだろうか\nまずい、心配に\nなってきた…！", 1, 135601, 0, 0, 9408);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "アイラたちとの旅行も\n楽しかったな…\nまた３人で温泉に\nいきたいものだ", 1, 135601, 0, 0, 9409);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ここで剣の稽古は\nさすがによろしくない\n代わりに今日は瞑想を\nすることにしよう", 1, 135601, 0, 0, 9410);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "人とのつながりは\n大切にしなければ\n今日こそは誰かに\n話しかけるぞ…！", 1, 135601, 0, 0, 9411);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "できることが増えて、\n迷うばかりの毎日…\nそれが楽しく尊いと\n今実感している…", 1, 135601, 0, 0, 9412);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ええと…奇遇だな\nこんなところで\n会うなんて。いや違う\n…その、こんにちは…", 1, 135601, 0, 0, 9413);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "弟子たちへの土産も\n探しておかないとな\nよければキミからも\nアドバイスを頼む…", 1, 135601, 0, 0, 9415);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "剣の稽古をしたい？\nふっ…いいとも\nキミとならいくらでも\n準備をしてすぐ戻る", 1, 135601, 0, 0, 9416);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "よければまた、\n街を案内してくれ\n名所旧跡もだがキミと\n歩くのは楽しいんだ", 1, 135601, 0, 0, 9417);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "感謝の心を\n忘れたことはないよ\nキミたちの優しさに\n救われた一人として…", 1, 135601, 0, 0, 9418);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "うむ、いい顔だな\n良い一日は、\n良い目覚めから始まる\n心掛けておくといい", 1, 135601, 0, 1, 9419);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "もう昼時か\n誰かを誘って食事に…\n…いや無理だ、\nハードルが高い…！", 1, 135601, 0, 2, 9420);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜はいい…\n誰とも話さず\n一人きりでいても、\n不自然ではないからな", 1, 135601, 0, 3, 9421);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "…いかんな、これは\n気を抜くとこのまま\n離れられなくなる…", 1, 135601, 0, 0, 9423);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "シナツだ、よろしく\n……ふぅ\n人形相手の練習なら\n緊張しないのだがな…", 1, 135601, 0, 0, 9424);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ふむ…集中力が\n高まりそうな香りだな\n稽古にも役立つだろう\n皆にも教えてやろうか", 1, 135601, 0, 0, 9425);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "凍える人に寄り添い\n温もりを与える…\n私もそんな存在に\nなりたいものだ", 1, 135601, 0, 0, 9426);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食の楽しみ…\nあまり意識して\nいなかったが、\nやはりいいものだな", 1, 135601, 0, 0, 9428);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "…っと、いかん\n読みふけっていたら\nいくらでも時間を\n過ごせてしまうぞ…", 1, 135601, 0, 0, 9429);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "また空を飛びたいな～\nふわふわ～ってなる\nあの感じが気持ちいい\nんだよね～♪", 1, 135701, 0, 0, 9433);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "またサラサリアに\n行きたいなー\n…串焼きの味が\n忘れられなくって♪", 1, 135701, 0, 0, 9434);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "悩んでる人がいたら\n背中を押してあげたい\nあたしがそれで、勇気\nづけられたみたいに", 1, 135701, 0, 0, 9435);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "気持ちを言葉にするの\n大事って分かってても\nいざとなると緊張して\n上手くできないなぁ…", 1, 135701, 0, 0, 9436);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "あっちの世界でも\nギルドハウスは\nあるのかな…？\n今度探してみよっと♪", 1, 135701, 0, 0, 9437);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "アイラに会って少し\n成長できたかも…！\n素敵な女の人目指して\nもっと頑張るぞーっ♪", 1, 135701, 0, 0, 9438);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あっちのあたしは\n騎士くんに選ばれた…\nよし、あたしも\n頑張らなくっちゃ…！", 1, 135701, 0, 0, 9439);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "部屋の模様替えする？\nサラサリア風の家具も\nあったら素敵だよね！", 1, 135701, 0, 0, 9440);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "なんだかお疲れ気味？\nそうだっ、サラサリア\nで教わったマッサージ\nをしてあげるっ♪", 1, 135701, 0, 0, 9441);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "騎士くんっ！\n今からあたしとデート\nしませんかっ！", 1, 135701, 0, 0, 9442);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "今ちょうど、踊りの\n練習してたとこなの\n騎士くんも\n一緒にどう？", 1, 135701, 0, 0, 9443);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "き、騎士くん！\nこの前の続き…\n手、繋いでいい…？", 1, 135701, 0, 0, 9444);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "えへへへ、騎士くんが\nあたしの背中を押して\nくれると、勇気も\n100万倍だよっ♪", 1, 135701, 0, 0, 9445);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよ、騎士くん！\n今日もいい朝だよ！\nサラサリアみたいに\n太陽が輝いてるもん！", 1, 135701, 0, 1, 9446);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "フレフレ、騎士くん！\n午後もファイトー！\nあたしは日陰でお昼寝\nタイム…なんてねっ♪", 1, 135701, 0, 2, 9447);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜に騎士くんといると\n空飛ぶ絨毯から見た\nサラサリアの夜景を\n思い出しちゃうな♪", 1, 135701, 0, 3, 9448);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "休憩きゅうけ～い♪\n強い人と戦った後は\nしっかりと体を\n休ませないとね", 1, 135701, 0, 0, 9450);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "にゃ～、\nかわいいにゃ～♪\nアンブラを\n思い出しちゃうよ♪", 1, 135701, 0, 0, 9451);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "わっ…すごくいい\n匂い～サラサリアの\n砂漠の匂いにちょっと\n似てるかも", 1, 135701, 0, 0, 9452);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "サラサリアの太陽\nみたいに暖かい♪\n日向ぼっこしてる\nみたいでしあわせ…", 1, 135701, 0, 0, 9453);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ん～おいしいっ！\nアイラもきっと\n好きな味だね…！\n今度食べてもらおっ！", 1, 135701, 0, 0, 9455);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "これは恋愛指南本…！\nふむ…意中の男性と\nキスするには…って\nこれはまだ早いよ～！", 1, 135701, 0, 0, 9456);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "あてがここにいたら、\nみんな寒い思いを\nしちまうかな…\nご、ごめんな", 1, 135801, 0, 0, 9460);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "あて、みんなより\n体でっけぇし…\nもうちょっと隅っこ\n行っとこうかな", 1, 135801, 0, 0, 9461);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "さ、騒がしいとこは\n苦手だども…\nここはそんなに\n気になんね…", 1, 135801, 0, 0, 9462);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "いろいろ勉強してぇな\nイナカもんだから、\nみんなに迷惑とか\nかけねぇように…", 1, 135801, 0, 0, 9463);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "家具とか、飾りとか、\n壊しちまったら大変…\nき、気ぃつけねぇとっ", 1, 135801, 0, 0, 9464);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あ、あての三味線、\n聴きたいの…？\nこ、心の準備が\nできてからで、い…？", 1, 135801, 0, 0, 9465);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "っ、ぁぶね…\nあてったらまた、\n騎士さのこと見て、\n溶けそうになってた…", 1, 135801, 0, 0, 9466);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お、おめさ、その…\nおやつさん、いらね？\nかき氷とかなら、\nあて、作れるよ…？", 1, 135801, 0, 0, 9467);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あ、あてに…何か用？\n…声、聴きたかった？\nな、なら…えっと…\nおしゃべり…する？", 1, 135801, 0, 0, 9468);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "こっちさ来てから…\n向こうの世界の\n何年分も、おしゃべり\nしたかもしんね…", 1, 135801, 0, 0, 9469);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "こっちの世界には、\n氷滑りって遊びが\nあるって…？\nあてにもできっかな…", 1, 135801, 0, 0, 9470);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ん…あては元気だよ\n悩みがあっても、\nおめさの声もらうと\n吹っ飛んじまうし…", 1, 135801, 0, 0, 9471);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "騎士さが近くに\nいてくれる…\n今は、それだけで\nいいんだ…うん…", 1, 135801, 0, 0, 9472);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お、おはよ…\nおめさのおかげで、\n昨夜もよく眠れたよ…", 1, 135801, 0, 1, 9473);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "…あっ、もう昼飯の\n時間かぁ…\n考えごとしてたら\nあっという間だよ", 1, 135801, 0, 2, 9474);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "景色は似てるけど…\nこの世界の夜は、\nざわざわ音がして\n賑やかだな…", 1, 135801, 0, 3, 9475);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "あんま縮こまってると\n体硬くなっちまうし…\nたまにはのんびり…", 1, 135801, 0, 0, 9477);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "えへへ、めんこいな…\nそだ、仁太坊たちも\n並んでたら\nもっとめんこいかも…", 1, 135801, 0, 0, 9478);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この匂い…なんか、\nは、はいから…？\nあて、イナカもん\nだから…", 1, 135801, 0, 0, 9479);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あ、暑くて溶けそう…\nだども、我慢できたら\n修行になる…かも…？", 1, 135801, 0, 0, 9480);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ん…♪　うめぇ…\nこんなうめぇもん\n毎日食べられるの、\n幸せだなぁ…", 1, 135801, 0, 0, 9482);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "こっちの世界にも…\n雪女が出る物語、\nあるみてぇだな…\nか、悲しい話だども…", 1, 135801, 0, 0, 9483);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "なかなか上等な\n家じゃねェか\nちっとばかし\n軒を借りるぜ", 1, 135901, 0, 0, 9487);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "俺の棒っきれの\n置き場所は…\nま、玄関にでも\n立てかけときゃいいか", 1, 135901, 0, 0, 9488);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "こっちの世界は\n眩しくって敵わねェぜ\n目がチカチカしやがる", 1, 135901, 0, 0, 9489);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "建物の様式が同じでも\n世界と住人が違えば\n印象も変わるモンだな", 1, 135901, 0, 0, 9490);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "街の連中は\n戦いなんて知らねェ\nのんきなツラしてんな\n…いいトコじゃねェか", 1, 135901, 0, 0, 9491);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "騎士公のヤツ、\nまたぞろ厄介事に\n巻き込まれや\nしてねェだろうな…", 1, 135901, 0, 0, 9492);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ふわぁ…\nこうも居心地がいいと\n眠くなっちまうぜ", 1, 135901, 0, 0, 9493);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "俺ばっかり\n見てんじゃねェよ\n赤鬼になっちまわぁ", 1, 135901, 0, 0, 9494);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "注いでくれんのか？\nあんがとよ\nんじゃ俺からも\nお返しだぜ", 1, 135901, 0, 0, 9495);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おう、暇してるなら\n鍛錬に付き合えよ\nじっとしてっと\n体がなまって仕方ねェ", 1, 135901, 0, 0, 9496);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "退屈してきたな…\n散歩にでも行くか？\n騎士公なら退屈しねェ\n場所知ってるだろ", 1, 135901, 0, 0, 9497);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "女との関係は\nきちっとしとけよ\n俺だって助けらんねぇ\nもんはあるからな", 1, 135901, 0, 0, 9498);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "角に触りたいだぁ？\n…まあ、騎士公の\n頼みなら…\nあんま手荒にすんなよ", 1, 135901, 0, 0, 9499);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "起きろ\n朝の鍛錬の時間だぜ\nほれ、さっさと\n身支度しちまいな", 1, 135901, 0, 1, 9500);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼飯ィ？\n俺の分はいらねぇよ\n気ィつかわねぇで\nくんな", 1, 135901, 0, 2, 9501);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "まだ起きてんのか？\nさっさと寝ねェと\nこうやって鬼が来るぜ", 1, 135901, 0, 3, 9502);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "悪くない座り心地だな\n気ィ抜くと、ダメに\nされちまいそうだぜ", 1, 135901, 0, 0, 9504);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "…今こいつ動いたか？\nグレ公あたりが\n悪さしてんじゃ\nねェだろうな", 1, 135901, 0, 0, 9505);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "騎士公はこういう\n香りが好みか？\nお姫とユキノに\n教えてやるとすっか", 1, 135901, 0, 0, 9506);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "地獄の釜よりかは\nちとぬるいが…\nなかなか\nいい火力してやがるぜ", 1, 135901, 0, 0, 9507);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "こっちの世界の本にも\n鬼が出てくるのか", 1, 135901, 0, 0, 9510);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "フランシュシュ１号、\nサクラです！　サガの\n心を、歌でみんなに\n届けにきました！", 1, 136101, 0, 0, 9514);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ランドソルはドキドキ\nいっぱいの街やけん！\nサガとどっちが\n暮らしやすかろうねっ", 1, 136101, 0, 0, 9515);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ソロ活動がんばって、\n憧れの子にもも～っと\n近づくと！　成長した\n私、早く見せたか～！", 1, 136101, 0, 0, 9516);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "部屋におるとは、伝説\nのメンバーばかり…！\n私もこのランドソルで\n伝説ば刻むとよ！", 1, 136101, 0, 0, 9517);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "あそこの修繕が気に\nなると…。…あのっ！\nあ、ついあの子を\n呼びそうに…えへへっ", 1, 136101, 0, 0, 9518);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "アイドルのレッスン、\n気になると？　まず、\n脚をぐい～っと広げて\n…あわわ、戻らん！？", 1, 136101, 0, 0, 9519);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "騎士さんのコネが\nあれば、いつか堂々と\nゾンビアイドルで\n売り出せるかもっ…！", 1, 136101, 0, 0, 9520);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようござい\nまーす！　挨拶は基本\nやけん、元気よくっ！\nさ、一緒にやろう！", 1, 136101, 0, 0, 9521);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "身だしなみチェック、\nよしっ。今日もいい\n天気っ♪　さあ、\nいってきまーーす！！", 1, 136101, 0, 0, 9522);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あんまり引っ張ると、\nう、腕が～…！　あ、\n気にせんで。伸びても\nすぐ元に戻るけんっ♪", 1, 136101, 0, 0, 9523);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "私、持っとらんって\n思ってきたけど、それ\nが何ね！　友達ば、\nいっぱい持っとるけん", 1, 136101, 0, 0, 9524);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "嚙めば噛むほど味が\n出る…騎士さんは\nサガのアタリメ\nみたいな人やねっ♪", 1, 136101, 0, 0, 9525);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "騎士さんにだけ教え\nますね。私の秘密…\n私の死因を。え？\nもう分かる気もする？", 1, 136101, 0, 0, 9526);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ぼ～っとしとかれんね\n「ぶっ殺すぞ」って\n気合入れてくれる子が\n両方の街におるけんっ", 1, 136101, 0, 1, 9527);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あのすごか食べっぷり\nよう思い出すとよ\n元気かな…変なもん\n食べてないかな…", 1, 136101, 0, 2, 9528);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜、出歩くと、怖～い\nアンデッドに襲われる\nかもしれんよ！\n気をつけんと…！", 1, 136101, 0, 3, 9529);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "リラックス！　もっと\nがんばってリラックス\nせんといかんね！\nむむむ～っ！", 1, 136101, 0, 0, 9531);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "が～ばや～らしか～♪\nあの子のお土産に\nしたいけど、同じの\n売っとらんかな…？", 1, 136101, 0, 0, 9532);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ん～、いい香りっ♪\nいつもこやん素敵な\n香りのする人が、私の\n友達におってね…", 1, 136101, 0, 0, 9533);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "え～と…熱いとその…\n傷んじゃいそうで、\nちょっと心配やけん…\nそ…その…私の体が", 1, 136101, 0, 0, 9534);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "わあ、美味しか～っ！\nランドソルのグルメも\nなかなか手強いっ…！\nサガも負けられんね～", 1, 136101, 0, 0, 9536);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "アイドル雑誌はあると\nですかね？　フラン\nシュシュのランキング\nは…しょぼぼぼーん…", 1, 136101, 0, 0, 9537);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "名探偵から聖職者へ、\n華麗なる変装だ！\nいや、心の中まで\n敬虔に…変貌、かな♪", 1, 137401, 0, 0, 9541);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "真実の鏡で、誰の謎も\n解いてみせるよ。\n恋の謎は…私が解いて\nほしいくらいだ…", 1, 137401, 0, 0, 9542);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "歩き方も…厳かに…\n気品と高潔さが\n感じられるように\n練習しなくてはね", 1, 137401, 0, 0, 9543);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "私の行いはきっと、\nどこかで見られている\nかつてお別れをした\n大切なあの子にも…ね", 1, 137401, 0, 0, 9544);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "異議あり！　…う～ん\nもっと威厳をもって…\n異議あり！　はっ、\n聞いていたのかいっ！", 1, 137401, 0, 0, 9545);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "静かに心を見つめれば\n大切なものが分かる\n助手くんとの時間の\nかけがえなさも、ね", 1, 137401, 0, 0, 9546);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "私も、想い合う二人の\n神聖な誓約の儀と\nいうものに憧れるよ\nつまり結婚式、にね…", 1, 137401, 0, 0, 9547);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "珈琲を一杯お願い\nするよ、助手くん\nこれがないと私の\n推理が冴えなくてね", 1, 137401, 0, 0, 9548);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "懺悔があるなら聞き\n届けよう。…え～っ！\n棚にある私のチョコを\n食べてしまったって！", 1, 137401, 0, 0, 9549);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "助手くん、今日の\n依頼は何件かな\nもし誰も来ないなら\n一緒にお出かけしよう", 1, 137401, 0, 0, 9550);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "さあ、出かけようか\n君と私で巡礼の旅だ\n鞄の中身はただ一つ\n真実を愛する心、さ！", 1, 137401, 0, 0, 9551);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "一緒に祈ってくれる\nかい？　ありがとう\n一人では真実が重荷に\nなるときもあってね", 1, 137401, 0, 0, 9552);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "何でも話してほしい\n分かち合いたいんだ\n喜びも悲しみも、君が\n背負う、なにもかも", 1, 137401, 0, 0, 9553);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう！　聖職者は\n早起きなのさ♪\nふわぁ…はっ、今の\nあくびは見てないね？", 1, 137401, 0, 1, 9554);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今日のお昼は…\n一緒に台所で\n作らないかい？\n新婚さんみたいに♪", 1, 137401, 0, 2, 9555);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜のお祈りをしよう\n凶悪な事件なんて、\nもう起きないように", 1, 137401, 0, 3, 9556);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "はあ…ふかふか～…\n堕落してしまいそう…\nなんとも罪なアイテム\nだねえ、これは…", 1, 137401, 0, 0, 9558);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいな…♪\n探偵事務所の机に\n置いたら場を和ませて\nくれそうだね", 1, 137401, 0, 0, 9559);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "はあ…心が落ち着く\nけして、その、小説の\n謎解きにイライラして\nいたわけではないよ？", 1, 137401, 0, 0, 9560);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "…暖かいね。こんな\n暖かさをあまねく\n世に届けるのが、\n今の私の役目だよ", 1, 137401, 0, 0, 9561);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "こんなにおいしい\nなんて、きっと重大な\n秘密が隠されているに\n違いないよね！", 1, 137401, 0, 0, 9563);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "時には推理小説でなく\n教えを説く本もいいね\nちょっとだけ…眠く\nなっちゃうけど…", 1, 137401, 0, 0, 9564);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "すんすん…\nなんか甘い匂いが\nするよーな？\nどこかなどこかな～", 1, 136201, 0, 0, 9568);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "お部屋の中、\nいっぱい歩いたよ～\nよーし、今日の訓練\nお～しまいっ♪", 1, 136201, 0, 0, 9569);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "どうしてドーナツには\n穴が開いてるんだろ？\nカスミちゃーん、\nおしえてーっ？", 1, 136201, 0, 0, 9570);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "いち、に、さん、し、\nごー、ろく…ナーナ！\nえへへへへ～♪", 1, 136201, 0, 0, 9571);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "訓練しなきゃだけど…\nおやつとかゲームとか\nいろいろありすぎて…\nで、でもぉ～っ！", 1, 136201, 0, 0, 9572);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ここ、騎士ちゃんの\nお部屋って感じする！\nだってすっごく\n安心するもん", 1, 136201, 0, 0, 9573);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "お耳を澄ませたら～…\n騎士ちゃんの声、\nどこからだって\n聞こえちゃうんだ♪", 1, 136201, 0, 0, 9574);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "はい、ナーナだよっ\n騎士ちゃんに\nあいさつしてもらうと\n元気が出てくるねっ", 1, 136201, 0, 0, 9575);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ナーナの頭の角、\n気になっちゃった？\nさわってもいいよ～", 1, 136201, 0, 0, 9576);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ナーナ、ずーっと\nだめだめだったけど…\nいつまでもそれじゃ\nだめだってわかったよ", 1, 136201, 0, 0, 9577);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "るんるる～、らら～♪\nあっ、一緒に歌う？\nせーの、らんらら～♪", 1, 136201, 0, 0, 9578);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ねぇ騎士ちゃんっ\n今日も一緒に\nおでかけしようよ！\nどこへ行こっかな～♪", 1, 136201, 0, 0, 9579);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ランドソルのごはん、\nどれもおいしいけど…\n一番はやっぱり\n騎士ちゃんのごはん！", 1, 136201, 0, 0, 9580);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよ～っ！\nおっきな声で\nあいさつすると\n気持ちいいよね♪", 1, 136201, 0, 1, 9581);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ごはんの時間だ！\nサクサクドーナツと\nもちもちドーナツ、\nどっちにしようかな～", 1, 136201, 0, 2, 9582);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "うーん、眠くなって\nきちゃった…\nみんなはまだまだ\n夜ふかしするの～？", 1, 136201, 0, 3, 9583);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "訓練の後はちゃんと\n休むのが大事だよ\n…ナーナはいつも\n休んでるけどっ…", 1, 136201, 0, 0, 9585);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "あなたもナーナの\nお友達になっちゃお？\n「ウン、イイヨ！」\nやったぁ～♪", 1, 136201, 0, 0, 9586);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい匂～い♪\nこの匂いつけたら\nナーナもお洒落さんに\nなれるかな～", 1, 136201, 0, 0, 9587);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ん～、あったかーい♪\nあっでも、お耳が\n焦げないように\n気をつけなきゃ…！", 1, 136201, 0, 0, 9588);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "いくら食べても\nなくならないなんて…\nすごすぎるよぉ～っ！\n絶対ふとっちゃう～！", 1, 136201, 0, 0, 9590);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "むずかしそーな本だ！\nふむふむどれどれ…\nうん、むずかしい！", 1, 136201, 0, 0, 9591);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "クリスマスの時期は\nやりたいことが\nたくさんあって…\n忙しいけど楽しいね", 1, 136401, 0, 0, 9595);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "みんながウキウキ\nしてるの、\n伝わってくるな♪", 1, 136401, 0, 0, 9596);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "思い切っておしゃれ\nしてみたけど…\nちょっと照れちゃう", 1, 136401, 0, 0, 9597);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "誘惑に負けて\n限定のスイーツセット\n買っちゃった…！", 1, 136401, 0, 0, 9598);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "帽子だけでも、\n印象が変わるんだよね\n新しい自分に\nなれたかな♪", 1, 136401, 0, 0, 9599);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "魔物のお料理…\nわたしも騎士クンに\n教えてもらおうかな…", 1, 136401, 0, 0, 9600);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "騎士クンの温もりが\n恋しくなっちゃうのも\n寒い冬だから…だよね", 1, 136401, 0, 0, 9601);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "大人っぽいコーデで、\nちょっと背伸びした\n気分…なんてねっ♪", 1, 136401, 0, 0, 9602);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今度一緒に\nお出かけしようよ\n騎士クンのお洋服\n選んであげるから", 1, 136401, 0, 0, 9603);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今度はここで\nパーティーしようよ\nきっと楽しいから", 1, 136401, 0, 0, 9604);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "風邪には気をつけてね\nわたしが温めてあげ…\nな、なんでもない！", 1, 136401, 0, 0, 9605);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "一緒にゆっくり\nおしゃべりしよう？\nいくらでも付き合うよ", 1, 136401, 0, 0, 9606);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "騎士クン、\nぎゅーってさせて？", 1, 136401, 0, 0, 9607);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう♪\n昨夜はわたし、\n騎士クンと夢の中でも\nデートしちゃった", 1, 136401, 0, 1, 9608);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ごはんの代わりに\nケーキは\nさ、さすがに\nいけないよね？", 1, 136401, 0, 2, 9609);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あのね、一緒に\n夜更かし、しない？\n今夜だけ…ね？", 1, 136401, 0, 3, 9610);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ん～、気持ちいい\nよかったら騎士クンも\n一緒に…", 1, 136401, 0, 0, 9612);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ぬいぐるみも\n楽しそうっ\nふふっ、かわいい♪", 1, 136401, 0, 0, 9613);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "アロマオイルとかも\nプレゼントの定番\nだよね…", 1, 136401, 0, 0, 9614);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "冷えた体が\nあったまって…\nね、眠くなっちゃう…\nふわぁ…", 1, 136401, 0, 0, 9615);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "愛情のこもった\nお料理って、\nいくらでも\n食べられちゃう…！", 1, 136401, 0, 0, 9617);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "夢占いかぁ…\n昨夜の夢は、\nどんな意味なんだろ？\n…えぇっ、そんな…！", 1, 136401, 0, 0, 9618);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 14, 3, "次のプレゼントは\nこういう本もいいかも\n騎士クンも\n喜んでくれそう…♪", 1, 136401, 0, 0, 9622);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 15, 3, "ふわもこだけど、\n動くのは大変っ…", 1, 136401, 0, 0, 9623);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "今からギルドハウスを\nクリスマス風に改造\nしちゃいます♪\nイイコトですよね★", 1, 136301, 0, 0, 9624);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ええっと…飾りつけを\nするには、まず\nテレポーテーションで\nツリーをもってきて…", 1, 136301, 0, 0, 9625);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "クリスマスとはずっと\n無縁な人生でしたし\n普通にそれっぽいコト\nしてみたいですねー", 1, 136301, 0, 0, 9626);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "おうちでまったりも\nイイカンジです★\nあまーいココアでも\n淹れてみましょうか", 1, 136301, 0, 0, 9627);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ケーキを食べ過ぎると\nいつかのユイさん\nみたいになっちゃう\nので要注意ですね★", 1, 136301, 0, 0, 9628);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "騎士さんは他の子と\nクリスマスデート中\nなんですかねー？\n邪魔しにいこうかなー", 1, 136301, 0, 0, 9629);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "騎士さんと\nクリスマスデート…\nふふっ、考えると\nニヤニヤしちゃいます", 1, 136301, 0, 0, 9630);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あ、騎士さん\nお邪魔してまーす★\nクリスマスも一緒に\nイイコトしましょうか", 1, 136301, 0, 0, 9631);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "外が寒すぎなので\n今日はイイコトクラブ\nも休部中ですよ★\nゆっくりしましょう♪", 1, 136301, 0, 0, 9632);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "この衣装ふわふわして\nついつい触りたく\nなっちゃいますよね？\n好きなだけイイですよ", 1, 136301, 0, 0, 9633);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "この白い衣装を血で\n真っ赤に染め上げる\n…なーんて事件は\n起きませんよ、多分", 1, 136301, 0, 0, 9634);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "クリスマスプレゼント\nのお届けでーす★\nプレゼントはもちろん\nわ・た・し、ですよ♥", 1, 136301, 0, 0, 9635);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "このギルドハウスは\nキスをしないと出られ\nないみたいですねー\n騎士さんどうしましょ", 1, 136301, 0, 0, 9636);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "うぅ～、寒さで\n目が覚めちゃいました\n風邪引きたくないので\nぎゅっ★　しますね♪", 1, 136301, 0, 1, 9637);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ちょっと気分転換に\n散歩でもいきますか\n雪が積もっていたら\n雪だるま作りましょう", 1, 136301, 0, 2, 9638);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "サンタさんがそろそろ\n来る時間ですかね？\nやることやってベッド\nにいきましょうか★", 1, 136301, 0, 3, 9639);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふぅ…\n聖夜騎姫★\nチャーミングスカイも\n充電が必要なんです", 1, 136301, 0, 0, 9641);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ぺんぽこりんはクビで\nこの子を戦わせるのも\nアリですね★\n壊れちゃいますけど♪", 1, 136301, 0, 0, 9642);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "はぁ…イイ香り♪\nクリスマスに\nピッタリですね", 1, 136301, 0, 0, 9643);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかーい♪\nもうここから\n動けないですー", 1, 136301, 0, 0, 9644);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "これだけ食べたら\n冬眠もできそうです\n春になったら\n起こしてくださーい♪", 1, 136301, 0, 0, 9646);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "へー、クリスマス\nケーキの作り方…\nランファさんにも後で\nシェアしてみますか", 1, 136301, 0, 0, 9647);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 14, 3, "あはっ、イイですねー\nバイオレンスな展開\nはなくてもちゃんと\n面白くなるんですね★", 1, 136301, 0, 0, 9651);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 15, 3, "こうして遊んでいると\nぺんぽこりんの\n着ぐるみもほしく\nなっちゃいます♪", 1, 136301, 0, 0, 9652);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "お父さまのような\n威厳のある佇まいを\n心がけたいものです", 1, 137601, 0, 0, 9653);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "見慣れた部屋が\n少し小さく感じます\nこの体の感覚にも\n早く慣れなければ…", 1, 137601, 0, 0, 9654);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "…おや？\n以前は見えなかった\n高いところの埃が…\nすぐに対処いたします", 1, 137601, 0, 0, 9655);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "わんわんの主さまも\n驚いたご様子でした\n人の成長は早いものと\n思われたでしょうか…", 1, 137601, 0, 0, 9656);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "すらりとした長い足…\n自分のものと\n分かっていても、つい\n見つめてしまいます…", 1, 137601, 0, 0, 9657);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "主さまのために\nできることも\n増えました…\nふふ、胸が躍ります", 1, 137601, 0, 0, 9658);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "わたくしの願いは、\n主さまと共にあること\nいわば、生涯を\n添い遂げるように…", 1, 137601, 0, 0, 9659);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "新たな姿でも変わらず\nおはようから\nおやすみまで\nお供いたしますよ", 1, 137601, 0, 0, 9660);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "装いも、大人の体に\n相応しいものに…\nエレガントさを\n心がけてみました", 1, 137601, 0, 0, 9661);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "昨日の買い出しでは\n少々買いすぎましたが\n大荷物でも平気でした\nすばらしいです…♪", 1, 137601, 0, 0, 9662);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "主さまのための\n大事な体ですからね\n長い髪の手入れも\n念入りにいたします", 1, 137601, 0, 0, 9663);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "本日の添い寝は\n大人と子ども、\nどちらの姿に\nいたしましょうか", 1, 137601, 0, 0, 9664);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あなたさま…\nあぁいえ、その…\n少し違う呼び名を\n試してみようかと", 1, 137601, 0, 0, 9665);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\n主さまとのご挨拶で\n始まる一日…\nワクワクいたします", 1, 137601, 0, 1, 9666);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "おや、もうお昼時…\nお腹の空き具合が\n違うと、少々感覚が\n鈍ってしまいますね", 1, 137601, 0, 2, 9667);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おやすみの際には\nわたくしの子守唄を…\n安眠の力も以前より\n増しておりますよ♪", 1, 137601, 0, 3, 9668);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "いつでも主さまに\n尽くせるよう、\n体を休めることも\n大事です…ふぅ", 1, 137601, 0, 0, 9670);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "愛らしいものを\n慈しむ心は、\n大人になっても\n変わりません…", 1, 137601, 0, 0, 9671);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "大人の体になると、\n匂いの感じかたも\n少し変わるような…？\n不思議なものです", 1, 137601, 0, 0, 9672);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "手足が冷えないよう\nしっかり温めて…\n冷え性は大人の悩みと\n伺いましたので", 1, 137601, 0, 0, 9673);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "胃のほうも、前より\n大きくなった模様です\n手が止まりません…\nもぐもぐ…", 1, 137601, 0, 0, 9675);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "久々に、主さまに\n本の読み聞かせを\nしましょうか\nふふ、楽しみです", 1, 137601, 0, 0, 9676);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "弟くんは何が好きかな\n縁起物がいっぱいの\nおせち料理を\n食べてほしいんだよね", 1, 136501, 0, 0, 9682);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ちょっと…帯がきつい\nかも…おせち料理の\n食べすぎかな？\n気を付けなくちゃ", 1, 136501, 0, 0, 9683);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "初日の出は見なくちゃ\n新しい一年の始まりを\n告げるお日さまに\n挨拶しておきたいし", 1, 136501, 0, 0, 9684);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "甘酒って不思議…\nすっごく寒い日に\n飲むと、もっと\nおいしくなるんだもん", 1, 136501, 0, 0, 9685);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "着物のお姉ちゃん♪\nいつもとは違う格好で\n弟くんをドキドキ\nさせちゃおっと♪", 1, 136501, 0, 0, 9686);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "うふふ…弟くんの寝顔\nかわいかったなぁ♪\nもはや国宝級だよ！", 1, 136501, 0, 0, 9687);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "弟くんの着物姿、\nかっこよかった～♪\nはぁぁ…思い出したら\nドキドキしてきた…♪", 1, 136501, 0, 0, 9688);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "私の着物が気になる？\n触ってもいいよ\n肌触りがよくって、\n着心地も最高なんだ～", 1, 136501, 0, 0, 9689);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "初詣に行くときは手を\n繋ごうね。人混みの\n中ではぐれたりしたら\n大変だもんっ", 1, 136501, 0, 0, 9690);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "叶えたいことが\nあったら言ってね？\nお姉ちゃんが全力で\n協力するから！", 1, 136501, 0, 0, 9691);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お正月は一緒に\n過ごしてお買い物も\nして…ラブラブな\n時間を楽しもうねっ♪", 1, 136501, 0, 0, 9692);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "…大好きだよ、弟くん\nふふっ、急にごめんね\nどうしても今、伝えた\nいって思っちゃったの", 1, 136501, 0, 0, 9693);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "弟くんにもらった指輪\n宝物だよ♪　だけど\nいつか本当の新婚さん\nになりたいな…♪", 1, 136501, 0, 0, 9694);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お正月の朝は空気が\n冷たいよね。こんな\nときは、太陽の光を\n浴びながらお散歩しよ", 1, 136501, 0, 1, 9695);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼はお雑煮！\n出汁も具材も\nこだわったから、\n楽しみにしててね♪", 1, 136501, 0, 2, 9696);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ寝よっか？\nそうだ、添い寝をして\nあげる！　寒いとなか\nなか寝付けないでしょ", 1, 136501, 0, 3, 9697);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "座り方には気を付け\nないと。きれいな\n着物に、しわは作り\nたくないもんね", 1, 136501, 0, 0, 9699);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふわふわでかわいいね\nこの子たちも、\n弟くんとの生活、\nお祝いしてくれてる？", 1, 136501, 0, 0, 9700);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "くんくん…神社のお香\nみたい♪　いいこと\nありそうな気が\nしてきたよ", 1, 136501, 0, 0, 9701);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "寒い日に暖炉はありが\nたいな～♪　ここで\nお餅を焼けば、お腹も\n膨れて一石二鳥かも♪", 1, 136501, 0, 0, 9702);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "お腹いっぱい…でも\nまだ食べたい！　う～\nこれじゃ、正月太りへ\nまっしぐらだよ～", 1, 136501, 0, 0, 9704);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ラブラブだけじゃなく\nもくもくと一緒に本を\n読むのもいいよね♪\nお正月は時間もあるし", 1, 136501, 0, 0, 9705);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "『囲い完全』の絵馬を\n吊るしてきました！\nこれで家の中は\nもう大丈夫ですね！", 1, 137901, 0, 0, 9711);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "正月遊びも雪遊びも\n全部やりたいです！\nえへへ、ちょっぴり\n欲張りでしょうか？", 1, 137901, 0, 0, 9712);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "マスターから\nお年玉貰えましたー！\n何に使おうか\n迷っちゃいますね～♪", 1, 137901, 0, 0, 9713);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ついだらっとしちゃう\nお正月だからこそ！\n楽しかったって言える\n思い出を作るんです♪", 1, 137901, 0, 0, 9714);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "おせち♪　おせち♪\n中でも昆布と数の子が\n好きなんですよ～♪", 1, 137901, 0, 0, 9715);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "今年の恋愛運は大吉♪\n一歩踏み出すチャンス\n絶対逃さずに\n掴み取りますよ～！", 1, 137901, 0, 0, 9716);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "こっそりポストに\nお兄ちゃんへの\n年賀状を投入☆\nいつ気付くかな～♪", 1, 137901, 0, 0, 9717);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お正月の初夢は…\n一兄二姉三マスター\nでした！　縁起が\nいいです♪", 1, 137901, 0, 0, 9718);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お兄ちゃん、お餅つき\nしませんか？\n兄妹のチームワークで\n沢山作りますよ！", 1, 137901, 0, 0, 9719);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "さむ～い…\n…お兄ちゃん、\nポケット失礼しますね\n…えへへっ♪", 1, 137901, 0, 0, 9720);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お掃除はお任せあれ！\n頼りになる妹目指して\nお手伝いしますよー！", 1, 137901, 0, 0, 9721);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お兄ちゃんと過ごす\nお正月は毎年\n大大吉ですよ☆", 1, 137901, 0, 0, 9722);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "寒いなら\n私が妹ゆたんぽに\nなってあげますよ♪\nぎゅってして下さい☆", 1, 137901, 0, 0, 9723);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝ごはんにお雑煮は\nどうですか？\nマスター秘伝のレシピ\nアレンジしてみました", 1, 137901, 0, 1, 9724);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼になっても\nお正月は冷えますね～\n一緒にこたつに入って\nぬくぬくしませんか？", 1, 137901, 0, 2, 9725);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "もう寝る時間ですね～\nお兄ちゃんも\nいい初夢が\n見られますように♪", 1, 137901, 0, 3, 9726);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "くんくん…\nあ、ここちょっとだけ\nお兄ちゃんの匂いが…\nくんくんくんくん…", 1, 137901, 0, 0, 9728);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "この子たちにも\n初日の出を見せて\nあげたいですね～♪\n連れていけるかな？", 1, 137901, 0, 0, 9729);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "これがお兄ちゃんの\n好みの香りですね\nメモしておきましょう", 1, 137901, 0, 0, 9730);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "こう暖かいと\nだんだん眠く…\nふわぁ～…", 1, 137901, 0, 0, 9731);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいしい～☆\nでも、着物の時は\nちゃんと抑えめに\nしておかないと…！", 1, 137901, 0, 0, 9733);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "『黎明界完全攻略本』\n作って入れておいたら\n誰かの役に立つ日が\n来るかも…？", 1, 137901, 0, 0, 9734);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "冥界ではないのに\n落ち着きますわ\n騎士様の気配が\nあるからでしょうか…", 1, 138001, 0, 0, 9740);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "普段食が細いせいか\n少し食べすぎると\nすぐ体重が…気を付け\nなくてはいけませんね", 1, 138001, 0, 0, 9741);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ジオ・テオゴニアには\nお菓子の城があるとか\n本当に童話のようです\n想像が膨らみますわ", 1, 138001, 0, 0, 9742);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "刺激的な料理の数々\nジオ・ゲヘナの強さは\nきっと食生活の影響も\n大きいのでしょうね", 1, 138001, 0, 0, 9743);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ランドソルの魚は大き\nくて活きが良いとか\n釣り…わたくしでも\nできるでしょうか？", 1, 138001, 0, 0, 9744);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "解決すべき問題は沢山\nありますが、騎士様と\n共に、乗り越えられる\nと信じておりますわ", 1, 138001, 0, 0, 9745);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "この装い…風が吹くと\nすぐ裾がめくれて…\n騎士様に見られたら\n大変です…！", 1, 138001, 0, 0, 9746);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "魚の捌き方なら\nおまかせください♪\n体が覚えるまで何度も\n練習しましたから", 1, 138001, 0, 0, 9747);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "料理の楽しさを知って\nしまいました…♪\n大切な人と食卓を共に\nする、その尊さも…", 1, 138001, 0, 0, 9748);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "手、ですか？\nばんそうこうだらけで\nお恥ずかしいですが…\nこれも勲章です", 1, 138001, 0, 0, 9749);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "本日は視察の公務が\nありまして。あの…\n騎士様。一緒に来ては\nいただけませんか…？", 1, 138001, 0, 0, 9750);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "食べた人の服が\n弾けないように\nするにはどうしたら\n良いのでしょうか…", 1, 138001, 0, 0, 9751);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "料理の道は一日にして\n成らず…日々の精進で\n騎士様に飽きられない\n味を目指します…！", 1, 138001, 0, 0, 9752);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\n清々しい朝ですね…♪\nっくしゅん！　肌寒い\nのは困りものですが…", 1, 138001, 0, 1, 9753);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼を食べたら一休み\nいたしましょう\n騎士様と共に過ごす\n時間が幸せです…♪", 1, 138001, 0, 2, 9754);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "騎士様、お夜食は\n必要ですか？\n練習で作ってみたので\nその…よければ…", 1, 138001, 0, 3, 9755);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "はぁ…身も心も\n溶けてしまいそう…♪\nこの姿は、他の誰にも\n見せられませんね", 1, 138001, 0, 0, 9757);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "なんて愛らしい…♪\n霊獣たちの仲間に\n迎えられたりしない\nでしょうか…♪", 1, 138001, 0, 0, 9758);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "落ち着きますわね…\n心を静める香りに\n今は少しだけ\n心をゆだねましょう", 1, 138001, 0, 0, 9759);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あら？　一緒にいた\nあの子たちはどこに…\n…もしかして乾燥や\n蒸発が怖いのかしら", 1, 138001, 0, 0, 9760);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "美味しい…♪\n作り手の真心を\n感じますわね\nもう一ついただきます", 1, 138001, 0, 0, 9762);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ランドソルの料理…\nレシピがあれば、\nわたくしにも作れる\nでしょうか…？", 1, 138001, 0, 0, 9763);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "万博の余韻に\n心がふわふわとして…\nいつもより浮いて\nしまっているかも…♪", 1, 138101, 0, 0, 9769);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ランドソルはまるで\nペコリーヌ姫のよう\n国民を見れば彼女の\n人柄が感じられます", 1, 138101, 0, 0, 9770);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "マスコットキャラ…\nわが国でも導入すべき\nでしょうか。クルルに\n相談してみましょう", 1, 138101, 0, 0, 9771);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "後腐れのない\n公平な勝負であれば\n全力で臨みますよ\nふふ、腕が鳴ります", 1, 138101, 0, 0, 9772);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "弱気になったとき、\n身近な人の存在が、\nわたしに前を向かせる\n力をくれるのです", 1, 138101, 0, 0, 9773);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お菓子を食べたときの\n笑顔が見たくて\nお菓子を作っているの\nかもしれません", 1, 138101, 0, 0, 9774);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "種族も、生まれすら、\n世界が違っても、\nわたしたちはきっと\n心を通わせられます", 1, 138101, 0, 0, 9775);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "信じていますからね、\n騎士？　もしめくろう\nとしたら…天罰です♪", 1, 138101, 0, 0, 9776);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "意外と力はあるんです\nよ。お菓子作りに力は\n必要なので。試しに\n腕相撲をしてみます？", 1, 138101, 0, 0, 9777);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "気分転換に部屋の模様\n替えをしませんか？\nジオ・テオゴニア風に\nお菓子の家具とか♪", 1, 138101, 0, 0, 9778);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お茶にしましょうね\n先日採ったはちみつ、\n持ってきたんです♪\n何杯入れますか？", 1, 138101, 0, 0, 9779);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "食べたいお菓子は\nありますか？\nいつでも作りますよ\nお礼は笑顔で十分です", 1, 138101, 0, 0, 9780);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あなた…ふふっ♪\nすみません、なぜだか\nそう呼んでみたく\nなったんです…♪", 1, 138101, 0, 0, 9781);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ふわふわパンケーキに\nハチミツをたっぷり…\n朝食がまだなら一緒に\nいかがですか？　騎士", 1, 138101, 0, 1, 9782);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼はハニートースト\nです♪　甘いものを\nたくさん食べて、午後\nもがんばりましょう", 1, 138101, 0, 2, 9783);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夕飯はドーナツです\nそれも食べ放題♪\nお腹いっぱいになる\nまで食べてくださいね", 1, 138101, 0, 3, 9784);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "腰を下ろす時間も必要\nですね。浮いていては\n大事なことを見逃す\nかもしれませんから", 1, 138101, 0, 0, 9786);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "見た目のかわいらしさ\n触れたときの柔らかさ\nお菓子と同じ、調和が\n大切ですね…♪", 1, 138101, 0, 0, 9787);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "素敵な香りですね…\n今日のティータイムは\nこの香りに合う\nお菓子を出しますね", 1, 138101, 0, 0, 9788);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あたたかいと、安心感\nで、つい…まだ秘密に\nするはずの気持ちも\n話してしまいそうです", 1, 138101, 0, 0, 9789);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食は人を幸せにします\n…とはいえ、食べすぎ\nには注意、ですね", 1, 138101, 0, 0, 9791);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "『アストルムの珍味\n100選』？　これは\n興味深い…甘いものも\nあるでしょうか？", 1, 138101, 0, 0, 9792);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "戦を忘れ、我が家にて\n憩ふ時こそ至高也\nゆるりゆるりと…♪", 1, 138201, 0, 0, 9798);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "美食巡りし冒険\n御暇なる折にでも\nお聞きしたくありんす", 1, 138201, 0, 0, 9799);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "身丈異なれば\n見ゆるものも異にして\n趣深く候。騎士殿の\n御顔も近うなれば…♪", 1, 138201, 0, 0, 9800);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ランドソルの食の祭典\n煮炊きの技を競うとは\n新奇なる験。大変\n美味しゅう御座んした", 1, 138201, 0, 0, 9801);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "種種様様なる国の御饗\n正しく千差万別也\n腹が千切れる程味わい\nましょうぞ、騎士殿や", 1, 138201, 0, 0, 9802);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "他者に信を置くは\n思いの他に至難極みて\n難しきこと也", 1, 138201, 0, 0, 9803);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "騎士殿は只在るが侭に\nその御身体も御心も\nわっちが身命を賭して\n御守りします故", 1, 138201, 0, 0, 9804);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "いけませぬ、騎士殿や\n今のわっちが如何に\n『ないすばでぃ』と\nいえど戯れは程々に♪", 1, 138201, 0, 0, 9805);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "食を求めし旅路\nわっちを連れ給はんや\n騎士殿や？", 1, 138201, 0, 0, 9806);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "よき縁こそ\n万事に代えべからざる\n至宝なりけり", 1, 138201, 0, 0, 9807);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "此の装束の生地は\n最上の膚触りに候\n騎士殿であれば\n撫で給へど苦しからず", 1, 138201, 0, 0, 9808);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "時には媛としての\n公の事を離れ\n羽を伸ばすも一興\nさ、参ろうぞ騎士殿や", 1, 138201, 0, 0, 9809);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "騎士殿や\nもっと御傍に\n─コロコロコロ\n愛い顔でありんすの", 1, 138201, 0, 0, 9810);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "一日の計は朝に\nありと申しんす\n御目覚めのほどは\n如何かえ騎士殿や", 1, 138201, 0, 1, 9811);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "はや昼時を迎え候\n共に昼餉の支度を\nしませむか", 1, 138201, 0, 2, 9812);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "宵の明くるまで\n起き明かすは体に毒\n我が身を労わりて疾く\nお休みくだしゃんせ", 1, 138201, 0, 3, 9813);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "実に優れたる座し心地\nわっちの蛇も\n僻みてしまうやも\nしれませぬ喃", 1, 138201, 0, 0, 9814);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "どれ\n稚児らの土産に\n斯様が如き玩具でも\n買うて帰りましょうや", 1, 138201, 0, 0, 9815);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ふむ…此の香り\n鬼岩城砦の薫物として\n取り入れたく候", 1, 138201, 0, 0, 9816);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "暖かき心地も\nジオ・ゲヘナの地に\n住まえば清新とすら\n覚えまする", 1, 138201, 0, 0, 9817);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "斯様な佳肴も\n皆で食してこそ\n味わい際立つもので\nありんしょう", 1, 138201, 0, 0, 9818);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "異なる国々の\n『れしぴ』を蒐集し\nモネらに振る舞うも\n一興やもしれぬ喃", 1, 138201, 0, 0, 9819);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この国の矜持は\nユースティアナの\n矜持でもあります！", 1, 138301, 0, 0, 9820);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "お腹も心もいっぱい！\n今なら書類も、完璧に\nこなしてみせますよ\n…たぶん…", 1, 138301, 0, 0, 9821);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "至高のおにぎり…\n考えるだけで\nお腹がペコペコに…", 1, 138301, 0, 0, 9822);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "みなさんがわたしを\n想ってくれたように\nわたしの想いも\n伝えていきたいです", 1, 138301, 0, 0, 9823);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "みなさんから\nお預かりした力…\n大切に使いますね", 1, 138301, 0, 0, 9824);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "えへへ☆\nお腹が空くって\n幸せなことですね！", 1, 138301, 0, 0, 9825);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あの人がにぎって\nくれたおにぎり…\nまた食べたくなって\nきちゃいました☆", 1, 138301, 0, 0, 9826);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日はどんな食卓に\nしましょうか？\n幸せなごはん、\nたくさん作りましょう", 1, 138301, 0, 0, 9827);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "料理が愛で\nできているように、\nわたしの体も愛で\nできているんですよね", 1, 138301, 0, 0, 9828);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "覚醒とは関係なく\nあなたのおにぎりを\nお腹も胸も弾けるほど\nいっぱい食べたいです", 1, 138301, 0, 0, 9829);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "誰にも奪わせない…\nわたしの決意が\n女神アストライアに\n伝わったんでしょうか", 1, 138301, 0, 0, 9830);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あなたと半分こした\nあのおにぎりは\n幸せの味がしました☆\nごちそうさまです♪", 1, 138301, 0, 0, 9831);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あなたと食卓を囲う\n幸せ…あの日常が\nあるから、今日の\nわたしも元気です☆", 1, 138301, 0, 0, 9832);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お腹がペコペコで\n目が覚めちゃいました\nあなたもですか？\nおそろいですね☆", 1, 138301, 0, 1, 9833);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "矜持だけでは\nお腹は膨れません…\nということでランチ♪\nあなたもどうですか？", 1, 138301, 0, 2, 9834);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ寝る準備を…\nの前に、お夜食です☆\nあなたとゆっくり、\nおしゃべりしながら…", 1, 138301, 0, 3, 9835);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "プリンセスにも\n休憩は必要\nですよね～…", 1, 138301, 0, 0, 9837);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいくて\n食べちゃいたい…\nもちろん冗談ですよ～", 1, 138301, 0, 0, 9838);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "はわわ～…\nいい香りでお腹も\nグーって言ってます…", 1, 138301, 0, 0, 9839);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "はぁ～♪\nぬくぬくですね…\nあの人もいたら\nもっとぬくぬくなのに", 1, 138301, 0, 0, 9840);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "はむはむはむ…♪\nお腹が空くって\n幸せですね☆", 1, 138301, 0, 0, 9842);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "『この大陸には\n星の女神の名が\n与えられた』って\n書いてありますね", 1, 138301, 0, 0, 9843);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 1, "騎士きゅんのために\nスライム風呂でも\n用意しとくか～", 1, 123301, 0, 0, 9849);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (12, 103, 2, "おねえちゃんの肌\nぷるっぷるっしょ～？\n触ってイイよ～♡", 1, 123301, 0, 0, 9850);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この水着どうですか？\n黒、なんて…大胆？\n背伸びしすぎたかも…", 1, 138701, 0, 0, 9851);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "お尻を鍛えたせいで\nちょっとムチムチに…\n元からじゃないですっ", 1, 138701, 0, 0, 9852);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "水着を着てるうちに\nバンディシャーク号の\n洗車やっちゃおうかな", 1, 138701, 0, 0, 9853);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "真冬はサマー！\n…考えたひとは\n悪魔だと思ってます…\n真冬は真冬です…", 1, 138701, 0, 0, 9854);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "常夏のリゾート\nメリゾでのんびり…\nとっても楽しかったな\nまた行きましょうね", 1, 138701, 0, 0, 9855);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ずっと水着でいると\n感覚が麻痺してきて…\nお尻を突き出すのも\n慣れちゃって…はぅぅ", 1, 138701, 0, 0, 9856);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "せっかくの水着だし\n今度は海にいきたいな\nもちろん騎士さんと\n一緒に…えへへ♪", 1, 138701, 0, 0, 9857);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "買い物してたら\n決勝見ましたって人に\n握手をせがまれて…\nわたしって、有名人？", 1, 138701, 0, 0, 9858);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "修行したおかげで\nたくさん洗い物しても\n腰が痛くないんです！", 1, 138701, 0, 0, 9859);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "伝説の桃闘者…\nそれが、わたし？\nで、伝説のままで\nいいんじゃないかな…", 1, 138701, 0, 0, 9860);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ウォータースライダー\n一緒に滑りましょう\n泳げなくても大丈夫\nわたしが支えますから", 1, 138701, 0, 0, 9861);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "わたしのお尻、\n『桃尻』らしいけど…\n褒められてるのかな？\n自分じゃ見えないし…", 1, 138701, 0, 0, 9862);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "尻文字であいうえお…\n特訓で繰り返したから\n今でも勝手にお尻が\n動いちゃう…", 1, 138701, 0, 0, 9863);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます！\n朝ごはんできてますよ\nあまーい卵焼きです", 1, 138701, 0, 1, 9864);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼は何つくろう…\n朝の残りの卵を使って\nオムライスとか？", 1, 138701, 0, 2, 9865);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "泳ぎ疲れた時は\n早めに寝るのが一番\nお布団ひきますね", 1, 138701, 0, 3, 9866);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "こういうの\nバンディシャーク号\nにも置きたいな…", 1, 138701, 0, 0, 9868);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "かわいいけど\nいざ買うってなると\nそのお金でおかずを…\nって考えちゃうなあ", 1, 138701, 0, 0, 9869);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "カレーのアロマって\nないのかな…？\n食欲増進によさそう？", 1, 138701, 0, 0, 9870);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "はあ…暖かい…\n雪山での特訓は\nつらかったなぁ…", 1, 138701, 0, 0, 9871);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "無限キャベツは\n作ったことあるけど\nこれは太りそう…\nでも、止まらない～", 1, 138701, 0, 0, 9873);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "スポーツ選手名鑑に\nワカナって載ってる！\nミフユコーチ、\n仕事速すぎっ！", 1, 138701, 0, 0, 9874);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "いい乗り心地\nスパイクちゃん達より\n速いのかな…？", 1, 138701, 0, 0, 9876);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "この貝の中に入って\nじっとしてたら\nいつかわたしも\n輝く真珠に…？", 1, 138701, 0, 0, 9877);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "水着を着てると、\nいつもより少し大胆に\nなれる気がする…", 1, 138801, 0, 0, 9880);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "やってみたいこと、\nいろいろ増えたなぁ\nあの人もきっと\n応援してくれるよね", 1, 138801, 0, 0, 9881);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "魔法のお尻、\nピュアリーピーチっ\n…す、すみません\n冗談です", 1, 138801, 0, 0, 9882);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "防水加工したら、\nプールでも読書できる\nよね。ぷかぷか浮いて\n読書なんて…素敵だな", 1, 138801, 0, 0, 9883);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "濡れた耳や尻尾は\nしっかり乾かして…\n毛並みが乱れちゃうと\n直すのが大変", 1, 138801, 0, 0, 9884);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あの人のお尻は\nどんな感じなんだろ…\nはっ、私ったら\nいったい何を…？", 1, 138801, 0, 0, 9885);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "強くなればその分、\nあの人の隣で戦える\n最強の桃闘者として…\nは、やめておこう…", 1, 138801, 0, 0, 9886);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "昨日、買い物中に\n声をかけられたんです\nもしかして私、\n有名人になってる…？", 1, 138801, 0, 0, 9887);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "水着で過ごしてると\n動きやすくていいな～\nなんて思っちゃいます\n慣れって怖いですね", 1, 138801, 0, 0, 9888);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "腕も脚も、前より\n力がついてると\n思うんです\n…触ってみます？", 1, 138801, 0, 0, 9889);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "特訓の成果で、感覚が\n鋭くなった気がします\nあなたの声も\n聞き逃しませんよ", 1, 138801, 0, 0, 9890);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あの、その…\n私のお尻、あなたも\n魅力的だって\n思いますか…？", 1, 138801, 0, 0, 9891);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あなたが何かに\n挑戦するときは、\n私も精いっぱい\nサポートしますっ…", 1, 138801, 0, 0, 9892);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\n体を動かすと質のいい\n睡眠をとれるみたい\n早起きできましたよ♪", 1, 138801, 0, 1, 9893);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ごはん、一緒に\nどうですか？　また\nピーチクラッシュ・\nフェアに行きたくて", 1, 138801, 0, 2, 9894);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "寝る前はストレッチ\n一緒にしませんか\nそれともマッサージが\nいいですか？", 1, 138801, 0, 3, 9895);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "この感触、あの人の\nふくらはぎと同じ…？", 1, 138801, 0, 0, 9897);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ぬいぐるみさんも、\nヒップレスリングの\n練習してみる？", 1, 138801, 0, 0, 9898);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この香り…\nはちみっさに少し\n似てるような…？\nき、気のせいだよね", 1, 138801, 0, 0, 9899);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "水着で冷えた体が\n温まるの、ほっとする\nこれが冬の醍醐味…？", 1, 138801, 0, 0, 9900);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "日々の食事が\n健康な体を作る…\nよく食べてよく鍛える\nそれが全ての基本♪", 1, 138801, 0, 0, 9902);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "スポーツ名鑑かぁ…\n…えっ、私のことが\nもう載ってる…？", 1, 138801, 0, 0, 9903);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "いい乗り心地だけど…\n夢中になってたら\nニャットちゃんが\n拗ねちゃうかも", 1, 138801, 0, 0, 9905);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "このクッション、\n気持ちいいなぁ\nこう、お尻にぴたっと\nフィットする感じで…", 1, 138801, 0, 0, 9906);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "おふくろの味が恋しい\nです…まぁ、キョウカ\nお嬢様のお義母さんの\nことなんですけどね", 1, 138901, 0, 0, 9909);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "あれ？　もしかして私\nここに入り浸りすぎ？\nもはや地縛霊ですね\n…それも悪くないか", 1, 138901, 0, 0, 9910);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "守護騎士をクビに\nなったときはショック\nでしたね。一人きり\nだったらグレてたかも", 1, 138901, 0, 0, 9911);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "騎士氏へのお礼にドッ\nキリプレゼントとか\nしたいですね。心臓が\n止まるレベルのやつ", 1, 138901, 0, 0, 9912);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "よっ、ふっ、はっ！\n…やはり幽霊たるもの\nポールダンスができて\nこそ一人前です", 1, 138901, 0, 0, 9913);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ヒマです。騎士氏でも\n捕まえてヒマつぶしに\n付き合ってもらうしか\nないですね。騎士氏～", 1, 138901, 0, 0, 9914);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "騎士氏の好物を調査\nしておきますか。これ\nから先、まだまだお世\n話になりそうですから", 1, 138901, 0, 0, 9915);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "私が呪われるのって\nズルくないですか？\nこちとら当たり判定が\n曖昧な幽霊なのに", 1, 138901, 0, 0, 9916);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "油断大敵ですよ。いつ\n誰が背後に忍び寄るか\nわかりませんからね\nたとえば私みたいに", 1, 138901, 0, 0, 9917);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "立ってる棒を見ると、\nポールダンスができる\nか確かめますよね\n…あれ、私だけ？", 1, 138901, 0, 0, 9918);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "はーい、ウサギちゃん\nへのお触りは禁止です\nよー。次にやったら\n首ちょんぱでーす", 1, 138901, 0, 0, 9919);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "生きる上で知識は必要\n…ということで勉強を\n教えたい気分なので、\nそこに座ってください", 1, 138901, 0, 0, 9920);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "やはり私を飼いたいの\nでしょう？　罪な女で\nすね私は…糸くずがつ\nいてただけ？　…ちっ", 1, 138901, 0, 0, 9921);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "起きていたのですね。\n寝起きドッキリを\n仕掛けようとして\nいたのに。残念無念", 1, 138901, 0, 1, 9922);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼食を食べずに午後を\n乗り切ろうなんて思わ\nないでくださいね。\n死にたいんですか？", 1, 138901, 0, 2, 9923);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ここからは大人の\n時間…さっさと\n寝ないと、枕元で\nポールダンスしますよ", 1, 138901, 0, 3, 9924);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "なかなかのふわふわ\n具合。私のお尻に\nついてるポンポンと\nいい勝負です。やるな", 1, 138901, 0, 0, 9926);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "貴方、ウサギ耳を\nつけてみませんか？\n実は私、仲間を増やし\nたくて暗躍中なんです", 1, 138901, 0, 0, 9927);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り…キョウカ\nお嬢様たちと過ごした\n家の匂いみたい…安心\nするんですよね何故か", 1, 138901, 0, 0, 9928);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "一発芸。飛んで火に\n入るウサギちゃん！\nって感じで火に飛び\n込むのウケるかな…？", 1, 138901, 0, 0, 9929);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ポールダンスは全身\n運動ですからね。しっ\nかり食べてエネルギー\nを補給しておかないと", 1, 138901, 0, 0, 9931);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "『ウサギの飼い方』？\n…やはり騎士氏は私を\n飼いたいとか？　一応\n私も読んでおきますか", 1, 138901, 0, 0, 9932);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "キレイなお洋服です\nからちゃんとお手入れ\nもしないと…よし♪", 1, 139001, 0, 0, 9938);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "怖くない幽霊さんも\nいるんですね\n…グレイスさんとか、\nグレイスさんとか…", 1, 139001, 0, 0, 9939);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "みんなとお嬢様ごっこ\n楽しかったな\nまたみんなを誘って\nやってみようかな", 1, 139001, 0, 0, 9940);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "お嬢様の練習\nもう少ししようかな\n…誰も見てないよね？\nおほほ、ほほほほっ♪", 1, 139001, 0, 0, 9941);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ネクロマンシーの本\n読んでみようかな\n怖いけど…ゾンビに\n詳しくなれるかも…？", 1, 139001, 0, 0, 9942);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あの人が執事に\nなってくれたら…\nどんな感じなんだろ？", 1, 139001, 0, 0, 9943);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "幽霊になっても\n一緒にいたい人…\n…な、なんで\nあの人の顔が…！", 1, 139001, 0, 0, 9944);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日もお勉強手伝って\nくれますか？\nひ、一人でもできます\nけど…ダメですか？", 1, 139001, 0, 0, 9945);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "宿題が終わったら\n一緒に遊びましょう\nだからまずはお勉強！", 1, 139001, 0, 0, 9946);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今度の休みは\n図書館に行きましょう\n静かでいいですよ", 1, 139001, 0, 0, 9947);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "手を繋いでください\n鎖の代わりです\n離さないでくださいね", 1, 139001, 0, 0, 9948);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "鎖がなくたって\nちゃんと面倒見て\nあげます。あなたの\nこと、心配ですから", 1, 139001, 0, 0, 9949);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "今日は執事として私に\n付き合ってください\nあ、あくまで\nおままごとですから！", 1, 139001, 0, 0, 9950);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "いい朝ですね\nじゃなかった…\nいい朝ですわね\nおほほほ♪", 1, 139001, 0, 1, 9951);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "執事、今日のお昼は\nなにかしら？\nなんて…えへへ♪", 1, 139001, 0, 2, 9952);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "この格好なら\n夜更かしも平気…\nん…ふわぁ…", 1, 139001, 0, 3, 9953);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "勉強の休憩時間です\nサボりじゃないです\nちゃんと戻ります", 1, 139001, 0, 0, 9954);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "お揃いのドレスを\n着たらかわいいかも♪\nそしたら一緒に\nお出かけもできそう", 1, 139001, 0, 0, 9955);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "青い薔薇の香り\nあったらいいのに…\n探してみようかな", 1, 139001, 0, 0, 9956);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ぽかぽか優しい温かさ\nだけど、ゾンビは\n腐敗が進んじゃう\nのかな…？", 1, 139001, 0, 0, 9957);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…お嬢様は\nきっとにんじんも\nピーマンも優雅に\n食べるはず…っ", 1, 139001, 0, 0, 9958);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふしんしゃ取りが\nふしんしゃになる…\n気を付けないと！", 1, 139001, 0, 0, 9959);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "覇瞳天星…\n陛下は自在に\n使いこなしてた\nあたしも必ず…！", 1, 139101, 0, 0, 9960);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "鼻血はもう慣れた…\nって言ったら\n負けな気がする…", 1, 139101, 0, 0, 9961);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "スズナのメモ\nあたしが言った通りに\n書いてあるのかしら\n全然読めないけど", 1, 139101, 0, 0, 9962);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "魔物レース場で\n魔物が暴走するなんて\n元調教師としては\n見過ごせないわね…", 1, 139101, 0, 0, 9963);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "失敗したって凹んで\nられないわ。スズナの\n言う通りこれも一種の\nアオハルなのかもね", 1, 139101, 0, 0, 9964);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "あいつの未来にさ\nあたしは…いるのかな\n…いたいな、ずっと", 1, 139101, 0, 0, 9965);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あいつのこと考えると\nこの瞳がなくても\n未来が明るく視える\n…何言ってんのあたし", 1, 139101, 0, 0, 9966);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ねえ、一緒におでん\n作りましょ。がんもに\nこんにゃく、大根に卵\nフーフーしてよね？", 1, 139101, 0, 0, 9967);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "いい？　あの水晶玉で\n視たあたしたちの未来\n二人だけの秘密よ？\n絶対よ？", 1, 139101, 0, 0, 9968);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日も訓練に行くわよ\n休んだらなまっちゃう\nかもしれないでしょ\n付き合いなさい", 1, 139101, 0, 0, 9969);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "この瞳の力\nなじんできたかも\nちょっとすごくない？\n褒めていいわよ♪", 1, 139101, 0, 0, 9970);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あの時は膝枕ありがと\n今度はあたしがして\nあげる。やってほしい\n時に言いなさい♪", 1, 139101, 0, 0, 9971);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あんたの未来\nあたしが独占するから\n…覚悟しなさいよ", 1, 139101, 0, 0, 9972);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよ\n予知しなくても分かる\n今日はいい日になるわ", 1, 139101, 0, 1, 9973);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お腹すいたわ～\n訓練三昧でへとへと\nなんか作って…\nメニューはお任せで", 1, 139101, 0, 2, 9974);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "変な夢見そうで\n寝つけないのよ…\n…別に怖くないけど\n…コラ！頭なでんな！", 1, 139101, 0, 3, 9975);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "はぁ～…\n頭を休ませないと\n予知がブレるのよ", 1, 139101, 0, 0, 9976);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "いつかあいつと一緒に\n住むなら部屋に置いて\nみたり…なんちゃって", 1, 139101, 0, 0, 9977);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り…\n疲れきった頭に\nすっごく沁みるわ…", 1, 139101, 0, 0, 9978);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "温かいと落ち着くわ\n猫の本能ってやつ？\n陛下は…どうなんだろ", 1, 139101, 0, 0, 9979);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "鼻血の出し過ぎで\n貧血ぎみだわ…\nもう一個食べとこ…", 1, 139101, 0, 0, 9980);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "占い横丁ガイドブック\nランドソルの母特集…\nって、これあたし！？\nいつの間に！？", 1, 139101, 0, 0, 9981);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "魔法の勉強を、もっと\nしたいな。大切な人を\n守るためには、強さと\n知識が必要だから", 1, 139201, 0, 0, 9982);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "お姉ちゃんが弓を引く\n姿、カッコいいなぁ～\n…あの耳も、すっごく\nかわいいんだよね♪", 1, 139201, 0, 0, 9983);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "エリカさんはやっぱり\n頼りになるな。仲間と\nしてそばにいてくれる\nと、すごく心強いんだ", 1, 139201, 0, 0, 9984);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "学校のみんなに、\nアストルムのことを\n話したら…信じて\nもらえるかな…？", 1, 139201, 0, 0, 9985);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "魔物ってたくさん\n種類があるんだね\nおいしいとか、\nおいしくないとか…", 1, 139201, 0, 0, 9986);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "この格好、わたしに\n似合ってるかな…？\n学校のみんなが見たら\nびっくりするかも♪", 1, 139201, 0, 0, 9987);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "一緒に過ごした時間は\n短いけれど…友だちの\nためなら、いくらでも\nがんばれますっ！", 1, 139201, 0, 0, 9988);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あの子　会いたや\nあの海越えて…♪\nはっ…もしかして今の\n聞いてました…！？", 1, 139201, 0, 0, 9989);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "偶然かもしれないけど\n偶然で終わらせたく\nないんだ。わたしが\nこの世界に来た意味を", 1, 139201, 0, 0, 9990);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "魔物を食べると健康に\nいいのかな？\nなんだか元気が\n有り余っちゃって…！", 1, 139201, 0, 0, 9991);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ちょっと相談に乗って\nもらっていいですか？\nこの世界だからできる\n戦術を相談したくって", 1, 139201, 0, 0, 9992);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "みんなのこと、知り\nたいです。一緒に戦う\nためだけじゃなくて…\n仲良くなりたいから", 1, 139201, 0, 0, 9993);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "戦車道をやってみませ\nんか？　あなたなら\nきっと立派な戦車道を\n歩めると思うから", 1, 139201, 0, 0, 9994);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます！\n寝坊した時は最悪を\n想定しつつ、次はどう\nするかを考えましょう", 1, 139201, 0, 1, 9995);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ごはんは海鮮に\nしませんか？　街を\nお散歩してたらいい\nお店を見つけたの", 1, 139201, 0, 2, 9996);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ眠る時間だね\n演習があってもなく\nても、睡眠はしっかり\nとりましょうね", 1, 139201, 0, 3, 9997);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふかふか～♪\n車内のクッションに\nこれも足したら\nみんな喜ぶかな♪", 1, 139201, 0, 0, 9998);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "わ～、かわいい～♪\n戦車の中に置いておい\nたら、ピンチのときに\n落ち着かせてくれそう", 1, 139201, 0, 0, 9999);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り～♪　ふふ、\n前に見せてもらった\n生け花を思い出すなあ", 1, 139201, 0, 0, 10000);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あたたまりながら干し\n芋を焼こうかな。おい\nしい匂いに人が集まっ\nてきちゃったりして♪", 1, 139201, 0, 0, 10001);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "世界は違っても、\nおいしいものはたくさ\nんあるんだ♪　いくら\nでも食べられちゃうな", 1, 139201, 0, 0, 10002);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "魔法の本は内容が難し\nいけど、ちゃんと読ん\nで、なにができるのか\nを理解しなくっちゃ！", 1, 139201, 0, 0, 10003);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "弓の命中率はまだ上げ\nられる。打てば必中、\nその矜持を返上する\nつもりはないからな", 1, 139301, 0, 0, 10004);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "まさか自分に獣の耳が\nあるとはな…慣れると\n便利だが…見た目が\nかわいくて困るな…", 1, 139301, 0, 0, 10005);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "世界が変わっても\nわたしがやることは\n変わらない。西住流は\nわたしが守る", 1, 139301, 0, 0, 10006);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "積み重ねた訓練が\n裏切ることはない\n自らを信じ、一射に\n魂を込めて放つだけだ", 1, 139301, 0, 0, 10007);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "エリカにはもっと自信\nを持ってほしい。わた\nしが信頼を置き指名し\nた次期隊長なのだから", 1, 139301, 0, 0, 10008);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ほしいのは勝利のみ\n…だが負けることで\n得られるものもある\n難しいものだな", 1, 139301, 0, 0, 10009);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "不確定要素が多い状況\nでなら、みほを隊長に\n推すのは必定。きっと\n力を発揮してくれる", 1, 139301, 0, 0, 10010);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "【美食殿】の活動方針\nには共感を覚えるよ\nおいしい食事は、隊の\n士気を左右するからな", 1, 139301, 0, 0, 10011);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "戦車でなく生身で戦う\nとなるとあなたたち\nには遠く及ばない\n今後も精進せねばな", 1, 139301, 0, 0, 10012);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "この足音は…やはり\nあなたか。マホ姫の\nおかげで、以前よりも\n感覚が磨かれたよ", 1, 139301, 0, 0, 10013);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "お互い作戦を伝えたり\n指揮をしたり\nする身だ、\n体調には気を付けよう", 1, 139301, 0, 0, 10014);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "油断大敵だ。数的有利\nだとしても戦術次第で\n対等に戦えるのだから\n…経験から得た教訓だ", 1, 139301, 0, 0, 10015);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あなたの援護には感謝\nしている。想定以上の\n動きができるのは敵に\nとっても脅威だからな", 1, 139301, 0, 0, 10016);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう。朝食は\nしっかりとるように\n腹が減っては戦も\n訓練もできないからな", 1, 139301, 0, 1, 10017);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "みほとエリカを誘って\n昼食にするとしよう\n午後も演習があるし…\nここはカレーにしよう", 1, 139301, 0, 2, 10018);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ就寝時間だ\n健康な心身を保つため\nにも、良質な睡眠は\n欠かせない", 1, 139301, 0, 3, 10019);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "休息時間はまだだぞ\nしかし…うう、この\n柔らかさの誘惑には\n抗いがたいな…", 1, 139301, 0, 0, 10020);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふむ…かわいいな\nボコとは違うがみほの\n好みに近い気がする", 1, 139301, 0, 0, 10021);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香りだ。戦車で\n走る草原の匂い。土の\n匂い…かすかな火薬の\n匂いもする…", 1, 139301, 0, 0, 10022);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あたたかい…そして\n熱い。まるで人の心だ\n誰もが胸に炎を抱えて\nいるものだからな", 1, 139301, 0, 0, 10023);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "泊りがけの演習に持参\nしたいな…食事が質素\nだと悪い結末になるの\nは歴史が証明している", 1, 139301, 0, 0, 10024);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふむ…この世界にある\n戦術が書かれた本か\n興味深い。熟読させて\nもらうとしよう", 1, 139301, 0, 0, 10025);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "双剣使い…いいわね♪\nわたしの戦場は後方\nではなく前線という\nことなのでしょう？", 1, 139401, 0, 0, 10026);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "本来の自分を忘れる\nなんて…不可抗力でも\nあってはならない失敗\nよ…あぁっ、もうっ！", 1, 139401, 0, 0, 10027);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "西住隊長がいる。ただ\nそれだけで安心感が\nある。…わたしもそん\nな隊長になりたいな…", 1, 139401, 0, 0, 10028);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "元副隊長には絶対に\n負けないわ！　競争\nじゃないし今は仲間\nだけど…それでも…！", 1, 139401, 0, 0, 10029);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "双剣の手入れをして\nおこうかしら。今の\nわたしの相棒は、\nこの剣なんだもの", 1, 139401, 0, 0, 10030);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ハンバーグは…いいわ\n肉肉しさとジューシー\nな味わいが、わたしに\nパワーをくれるのよね", 1, 139401, 0, 0, 10031);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "相手が誰だろうと\n無様な姿は見せないわ\nそれが私の果たすべき\n責務でしょう？", 1, 139401, 0, 0, 10032);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "わたしがキャルと\n似てる…？\nそんなことないわよ！\n…そうでしょ？", 1, 139401, 0, 0, 10033);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "この世界に来られて\n一応感謝してるのよ\n代え難い経験を\nさせてもらったもの", 1, 139401, 0, 0, 10034);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "士気の維持は、みんな\n苦労するのよ。でも、\nあなたはやってのける\n…すごいわ、本当に", 1, 139401, 0, 0, 10035);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "クローチェさんって\n面白い人よね。また\nアイアシェッケを\n採りにいきましょ", 1, 139401, 0, 0, 10036);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "誰にでも力になりたい\n人はいるわ。わたしに\nも、あなたにも。お互\nい、がんばりましょう", 1, 139401, 0, 0, 10037);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "これだけ長く離れて\nいたからこそ…次に\n乗る時はもっと戦車道\nを突き詰められそうよ", 1, 139401, 0, 0, 10038);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう。朝食は必ず\n食べなさいよ。食事は\n一日の基本だもの\nなにをするにもね", 1, 139401, 0, 1, 10039);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼食もだけど、休憩も\n忘れてはだめよ。少し\n眠ると訓練の質が\nあがるのよ…ふわぁ…", 1, 139401, 0, 2, 10040);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ寝たほうが\nいいわ。今日の疲れを\n明日に持ち越すのは\n愚者のすることよ", 1, 139401, 0, 3, 10041);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふかふか…たまらない\nわね…疲れてるときに\n横になったら、逃げ\nられない気がするわ", 1, 139401, 0, 0, 10042);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "守るものがあると人は\n強くなれることもある\n…あなたには我が隊に\n入る許可を与えるわ", 1, 139401, 0, 0, 10043);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "はぁ～…心が落ち着く\nいい匂い…エルフの里\nに流れる空気を\n思い出す爽やかさだわ", 1, 139401, 0, 0, 10044);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "見ていると心が穏やか\nになるわ…ケンカした\n相手とも素直に\nなれたりするかしら", 1, 139401, 0, 0, 10045);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいしいものが無限に\n出てくる？　なんて\n恐ろしいものを置いて\nるの…？　…はむはむ", 1, 139401, 0, 0, 10046);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "『おいしいカレーの作\nり方』を読んで新たな\n『エリカレー』を\n隊長に振る舞うわ…！", 1, 139401, 0, 0, 10047);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "掃除のしがいがある\n部屋でしゅね～\nいきましゅよ～！", 1, 136901, 0, 0, 10048);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "タコ足マッサージは\nキャンセル待ちでしゅ\nにゅるにゅるでしゅ♪", 1, 136901, 0, 0, 10049);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "たっくしゃんの卵から\n生き残り大きくなった\nラッキーガールでしゅ\nエンギモノでしゅ♪", 1, 136901, 0, 0, 10050);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "姫姉しゃまのところに\n初めて来た時のこと\nかすかに覚えてましゅ", 1, 136901, 0, 0, 10051);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "どこかにタコ壺を\n置きたいでしゅね\nそうしたらもっと\n快適に過ごせましゅ", 1, 136901, 0, 0, 10052);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "騎士しゃんもお世話が\n必要でしゅ。あたち、\n姫姉しゃまの小姓と\n両方やりましゅ！", 1, 136901, 0, 0, 10053);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "騎士しゃんを見てると\nお腹が空くのは\nどうちてでしょうか\nうじゅ…", 1, 136901, 0, 0, 10054);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "しゅけしゅけお洋服は\nおしゃれでせくちー、\n深海ファッションの\nとれんどなんでしゅよ", 1, 136901, 0, 0, 10055);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "小姓は忙ちいんでしゅ\n騎士しゃんも一緒に\nお仕事どうでしゅか？\n小姓一日入門でしゅ！", 1, 136901, 0, 0, 10056);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "部屋に体色を同化して\nカモフラージュ…♪\nうじゅ！？　なんで\n見つかったんでしゅ？", 1, 136901, 0, 0, 10057);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "ひゃ、ごめんなしゃい\nデュラ爺しゃん～\n…あれ？　違いまちた\nびっくりちまちたよ！", 1, 136901, 0, 0, 10058);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "『イケてるタコには\n毒がある』んでしゅ\nあたちは…持ってない\nでしゅ…うじゅる…", 1, 136901, 0, 0, 10059);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "先のほうはちょっと\nビンカンなので\nやさちく、ぎゅって\nつないでほちいでしゅ", 1, 136901, 0, 0, 10060);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "しゅっきりお目覚め\nくしゅぐりコースで…\nうじゅうじゅうじゅ♪\n逃がしましぇんよ～", 1, 136901, 0, 1, 10061);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "特製タコパスタなら\nすぐご用意できましゅ\nぶちぶちっ！\n…ちぎりすぎまちた", 1, 136901, 0, 2, 10062);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "子守唄を歌いましゅ\n深海の深～い眠りに\nいざなってあげるの\nでしゅ！", 1, 136901, 0, 3, 10063);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "じゅるじゅるじゅる…\nっと、油断すると\nお口が崩れて…\nこうちて…よち、と", 1, 136901, 0, 0, 10065);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "いいこいいこ～\nみなしゃんに\nかわいがられる\nマスコットでしゅね～", 1, 136901, 0, 0, 10066);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ふわ～いい香りでしゅ\nお肌も、足も、\nちっとりぬるぬる、\nぷるぷるでしゅ～", 1, 136901, 0, 0, 10067);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "どこからか焼きタコの\n香ばしい匂いが…♪\nうじゅ！？\nあたちからでちた！", 1, 136901, 0, 0, 10068);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ここに、もうひと味…\nぱっぱっぱ、っと♪\nコショーはやっぱり\n役に立ちましゅ", 1, 136901, 0, 0, 10070);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "王子しゃまを好きに\nなった人魚しゃん…\n一緒に海に帰らな\nかったんでしゅね…", 1, 136901, 0, 0, 10071);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "スミレ様にはお世話に\nなってばかりで…\nいつかこのご恩を\nお返ししたいです", 1, 139501, 0, 0, 10077);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "兄様の周りは強いお方\nばかり。皆様について\nいくためにも、より\n強い自分になります", 1, 139501, 0, 0, 10078);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "多くの人に笑顔に\nなってもらいたい\nわたくしの力は、その\nために使いたいのです", 1, 139501, 0, 0, 10079);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "『繋がりの巫女』の\n力で外出中の兄様と\n会話ができたりも…？\nもっと修業します…！", 1, 139501, 0, 0, 10080);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ふぅ…今は羽を休める\nとしましょう。ギルド\nハウスでは常在戦場も\n少しだけ緩めて…", 1, 139501, 0, 0, 10081);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "妄想に似た理想は、\nいりません。等身大の\n兄様だけを、この瞳に\n映し続けたいのです", 1, 139501, 0, 0, 10082);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "…お帰りになるまで\nあと何分でしょう？\n一日千秋の思いで\nお待ちしております", 1, 139501, 0, 0, 10083);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "白と黒だとどちらが\n好きですか？　兄様の\n好みを知りたくて…\nあ、服装の話ですよ？", 1, 139501, 0, 0, 10084);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "兄様のことをもっと\n教えてくださいませ\nたとえば…味の好みや\n寝る時の格好なども", 1, 139501, 0, 0, 10085);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "戦場の誉れもうれしい\nものですが、兄様から\nのお言葉がなによりも\nうれしいのです", 1, 139501, 0, 0, 10086);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "抜けた羽で羽毛布団を\n作れないでしょうか？\nもちろん作った布団は\n兄様に贈ります…♪", 1, 139501, 0, 0, 10087);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "また、お手合わせを\nお願いします、兄様\n…稽古のときは二人で\nいられますから…♪", 1, 139501, 0, 0, 10088);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "白は、何色にでも\n染まることができる色\nどうぞ、兄様が思う\nように染めてください", 1, 139501, 0, 0, 10089);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます\n今日も兄様に朝から\nご挨拶ができて、\nわたくしは幸福です♪", 1, 139501, 0, 1, 10090);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ご飯を食べて、\n今は羽を休めましょう\n宜しければ、わたくし\n手料理に挑戦をっ…", 1, 139501, 0, 2, 10091);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "そろそろ就寝の時間\nですね。成長するため\nには、修業だけでなく\n睡眠も大事です", 1, 139501, 0, 3, 10092);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "あぁ…なんという\nふかふかさ…いくら\n修業を重ねてもこれに\n抗うことは不可能です", 1, 139501, 0, 0, 10094);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "無生物とも『繋がる』\nことはできるのでしょ\nうか…？　試して\nみたいと思います", 1, 139501, 0, 0, 10095);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り…嗅いでいる\nと自然の中にいるよう\nで、集中したいときに\n重宝しそうです", 1, 139501, 0, 0, 10096);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "滝行の後は体が冷えて\nしまって…はぁ…♪\nぽかぽかで、心まで\n温かくなります…♪", 1, 139501, 0, 0, 10097);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "最近はカロリー消費が\n多いことばかりなので\nたくさん食べられます\n…もぐもぐっ♪", 1, 139501, 0, 0, 10099);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "『薔薇の下の契り』？\nだ、男性同士で…！？\nこのような観念が\n存在していたとは…っ", 1, 139501, 0, 0, 10100);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "かえる、ばしょ\nかえり、まつ、ばしょ\nいつでも、きれいに\nめざせ、しゅふ", 1, 139701, 0, 0, 10106);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "つばさ、おそろい\nハッピーちゃんと\nうれしみ", 1, 139701, 0, 0, 10107);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "このやり、ふぉーく\nないふ、も\nひつよう、なので\nリリのやり、かりるね", 1, 139701, 0, 0, 10108);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "はね、おちる\nいつの、まにか\nたいへん、おそうじ", 1, 139701, 0, 0, 10109);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "お兄の、かえり。まつ\nおふろ、じゅんび\nきっと、よろこぶ", 1, 139701, 0, 0, 10110);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "パパ。はなし、たい\nよんでみよ\nまほうじん、かく。", 1, 139701, 0, 0, 10111);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "わたしたち、なかよし\nまぶだち、こえてる\nじっしつ、ふうふ？", 1, 139701, 0, 0, 10112);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "お兄、おかえり\nつかれて、ない？\nまっさーじ、する？", 1, 139701, 0, 0, 10113);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "つばさ、おおきい\nうで、とどかない\nお兄。リボン、よろ", 1, 139701, 0, 0, 10114);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おいしいもの\nどこか、ないかな\nあ、お兄。みっけ", 1, 139701, 0, 0, 10115);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "このやり、つかって\nちーず、ふぉんでゅ\nしよう、お兄", 1, 139701, 0, 0, 10116);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お兄。どこにも\nいかないで\nまつの、さびしい", 1, 139701, 0, 0, 10117);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お兄、ほめて\nそうじ、せいとん\nかんりょう", 1, 139701, 0, 0, 10118);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよ\nあさごはん、べーこん\n…ハッピーちゃん？", 1, 139701, 0, 1, 10119);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ふあ…ちょい、ねむ\nらんち、まんぷく\nお兄。おひるね、しよ", 1, 139701, 0, 2, 10120);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "よぞら、おさんぽ\nほし、きらきら\nきれい", 1, 139701, 0, 3, 10121);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "すわる、ねる\nつばさ、ぽじしょん\nなやむ。いつも", 1, 139701, 0, 0, 10123);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "いつも、あざます\nだっこ、させてくれて\nこんごとも、よろ", 1, 139701, 0, 0, 10124);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "わたしの、つばさ。も\nいいにおい、する\nおひさま、みたい", 1, 139701, 0, 0, 10125);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ハッピーちゃん\nやけど、気をつけて\nちゃーしゅー、なる", 1, 139701, 0, 0, 10126);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "うぷ。\nおなか、はちきれ\nしあわせと、ひきかえ", 1, 139701, 0, 0, 10128);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "パパがくれた、ほん\nちょいむず\nおとなの、かいだん", 1, 139701, 0, 0, 10129);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "槍のお手入れって\nお花の世話に似てます\n心を込めてこまめに…\n人の心も同じですね", 1, 139601, 0, 0, 10135);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "帰る場所があるって…\n帰りたい所があるって\n幸せなことですね…♪", 1, 139601, 0, 0, 10136);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "総長ちゃんって\n呼ばれるの、慣れない\nけど…実はちょっと\n気に入ってます♪", 1, 139601, 0, 0, 10137);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "今日の夕飯は\nメンチカツに\nしようかな？", 1, 139601, 0, 0, 10138);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "モネちゃんにもらった\n髪飾りつけて、一緒に\nお出かけしたいな…♪\n今度誘ってみよう", 1, 139601, 0, 0, 10139);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ホンネで話すのって\n恥ずかしいけど…\nもっと仲良くなれる\n気がします", 1, 139601, 0, 0, 10140);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "聖女なんかじゃなくて\n戦乙女として、\n一緒に戦いたい\n後悔しないためにも", 1, 139601, 0, 0, 10141);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "誰かを癒すこと…もう\n躊躇いません。だから\n小さなケガでも教えて\nくださいね？", 1, 139601, 0, 0, 10142);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "わたし、悪い子です\nわたしを甘やかす\nお兄さんも共犯者\nですよ。ふふっ…", 1, 139601, 0, 0, 10143);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ヴァルキュリア…\n部屋の中だとちょっと\n窮屈ですかね…？", 1, 139601, 0, 0, 10144);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あ、お部屋に羽根が…\nわたしが居た証拠？\n…じゃなくって、\nすぐお掃除しますねっ", 1, 139601, 0, 0, 10145);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "お兄さん、また\n二人でお出かけ\nしたいです…♪", 1, 139601, 0, 0, 10146);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "一緒に空飛びます？\nわたしがお兄さんを\n抱っこして\nあげますよ～っ♪", 1, 139601, 0, 0, 10147);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今日一日、\nお兄さんのこと\n独り占めして\nいいですか？", 1, 139601, 0, 1, 10148);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼ですよ。ごはん\n食べに行きませんか？\n今日は、二人だけで\nあ、明日も明後日も♪", 1, 139601, 0, 2, 10149);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "わたしが寝かしつけて\nあげます♪\nえへへ、ひそかな夢\nだったんです、実は", 1, 139601, 0, 3, 10150);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ふぅ…\n羽も心も\n休まります…", 1, 139601, 0, 0, 10152);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "この子もちょっと\nあざといんじゃない\nかな～？\n仲間ですねっえへへ♪", 1, 139601, 0, 0, 10153);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り♪\n今度お兄さんに\n教えてあげたいな", 1, 139601, 0, 0, 10154);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったかくて\nしあわせで\nお兄さんのこと\n思い出しちゃう", 1, 139601, 0, 0, 10155);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "たくさん食べて\n体力つけようっと\n恋も戦いも、\n体が資本だから", 1, 139601, 0, 0, 10157);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "こ、恋占いの本\n読んじゃおっかな…\nわたしとお兄さんの\n相性は…ドキドキ", 1, 139601, 0, 0, 10158);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この姿だと冷凍\nトゥンヌスが素早く\n完璧に作れるみたい\n覚醒の無駄遣いかしら", 1, 139801, 0, 0, 10164);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "兄さんは私の\n赤ちゃん化のこと\nどう思ってたんだろう\n怖くて聞けないけど…", 1, 139801, 0, 0, 10165);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "コッコロマ…っ\n…いけない、また\n口が滑っちゃった…\n覚醒でもダメなのね…", 1, 139801, 0, 0, 10166);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "プレシアちゃんに\n「せんぱい」って…\nふふ、悪くないわね", 1, 139801, 0, 0, 10167);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "アイス食べたいわ\nチョコミントのダブル\n特訓で頑張ったご褒美\nってことにしましょ♪", 1, 139801, 0, 0, 10168);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "甘える練習、なかなか\n難しかったわ。今度は\nどんな風に甘えよう…\nはっ、癖になってる…", 1, 139801, 0, 0, 10169);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "好きって気持ち、\n抑えきれなくなってる\nこれって覚醒の副作用\nだったりしないわよね", 1, 139801, 0, 0, 10170);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "腕の紋章も大きくなる\nって不思議ね。成長の\n証？　あなたが言うと\n誇らしく思えるわね♪", 1, 139801, 0, 0, 10171);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "今度一緒に空を飛んで\nみない？　大丈夫\n私が抱えてあげる\n大きい翼が役に立つわ", 1, 139801, 0, 0, 10172);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "覚醒するとお腹が減る\nなんて知らなかったわ\nペコリーヌさんは共感\nしてくれたけど…", 1, 139801, 0, 0, 10173);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "キャルが翼の手入れの\n仕方を教えてくれたの\nこれって猫の毛繕い\nみたいなものかしら？", 1, 139801, 0, 0, 10174);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "この翼であなたを\n守りたい…でも本当は\nあなたが私を守って\nくれてるのよね…♪", 1, 139801, 0, 0, 10175);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "ね…、ちょっとだけ\n甘えてもいい？\n兄さんに甘えるのとは\n違う甘え方で…", 1, 139801, 0, 0, 10176);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "いい朝ね。朝日が\n眩しくて二度寝でき\nないなら、翼で日陰を\n作ってあげるわよ？", 1, 139801, 0, 1, 10177);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼はお弁当を持って\nどこか行かない？\n兄さんも誘って３人で", 1, 139801, 0, 2, 10178);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜遅くまで起きて…\n眠れないの？\n…私が子守唄、歌う？", 1, 139801, 0, 3, 10179);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ここでなら\n赤ちゃん化しても\n安全…よね？", 1, 139801, 0, 0, 10181);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふふ、かわいい…\nホマレさんに見せたら\nスケッチされそうね", 1, 139801, 0, 0, 10182);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り…\n…チョコミントの\nアロマとかないかしら", 1, 139801, 0, 0, 10183);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "温かくて落ち着くわ\n彼の隣にいるときと\n同じぬくもり…\nなんてね", 1, 139801, 0, 0, 10184);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "覚醒してると\n消耗が激しくて…\nホマレさんを\n見習わなきゃね", 1, 139801, 0, 0, 10186);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "恋愛の指南書、一冊\n読んでみようかな\n「甘え上手な彼女に\nなる方法」ふむふむ…", 1, 139801, 0, 0, 10187);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "こっちの過激な水着は\n最終兵器として、\nとっておこうっと", 1, 139901, 0, 0, 10193);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ダーリンのために特製\nトロピカルドリンクを\n錬成しておかなくちゃ\nいつでも飲めるように", 1, 139901, 0, 0, 10194);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "お部屋で水着…\nもしかして私って\nすごく破廉恥！？", 1, 139901, 0, 0, 10195);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "塩飴の錬成完了！\n暑い日のお出かけも\nばっちりね", 1, 139901, 0, 0, 10196);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "イロハちゃんと\nソノさんの水着も\n錬成できたわ！", 1, 139901, 0, 0, 10197);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ダーリンの視線を\n釘付けにするポーズ…\nこ、こうかしら？", 1, 139901, 0, 0, 10198);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ふふっ\nダーリンの帰りを\n水着姿でお出迎え♪\n刺激が強すぎるかな…", 1, 139901, 0, 0, 10199);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "大人の階段…\n大人の階段…\nち、違っ！階段で昇降\n運動しようと思って！", 1, 139901, 0, 0, 10200);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "バ、バナナボートって\nなんだか…ううん\n分からないならいいの", 1, 139901, 0, 0, 10201);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "私、この夏が人生で\n一番楽しいわ。だって\nあなたがいるから", 1, 139901, 0, 0, 10202);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "桃色の本が落ちてた？\nわ、私のじゃないわ\nでも預かっておくわね", 1, 139901, 0, 0, 10203);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "カップルストローを\n買ってきちゃった\nまた一緒に飲まない？", 1, 139901, 0, 0, 10204);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "世界で一番\n水着が似合う女の子に\nなってみせるわ\n楽しみにしてて♪", 1, 139901, 0, 0, 10205);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよう。わ、寝汗\nすごいわね！　制汗の\n秘薬を塗ってあげる", 1, 139901, 0, 1, 10206);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "どんなに暑くても\n私はあなたと\nくっついてたいな♪", 1, 139901, 0, 2, 10207);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ハート型の花火を\n買ったの。まるで\n私たちの心みたいね♪", 1, 139901, 0, 3, 10208);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "セクシーな\n寝ころびポーズで\nダーリンを悩殺よ♪", 1, 139901, 0, 0, 10210);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "派手な水着に\nキュートなぬいぐるみ\nいい組み合わせかも♪", 1, 139901, 0, 0, 10211);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "くんくん…\n汗の匂い大丈夫かな…\nこれでいい匂いに\nなったよね？", 1, 139901, 0, 0, 10212);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あつっ！　水着で\n近づいたらお肌が\nヒリヒリしちゃう…", 1, 139901, 0, 0, 10213);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "くびれが気になるけど\n食べるときはしっかり\n食べないと…ね？", 1, 139901, 0, 0, 10215);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "マサオはミツコの\n水着をずらし…ごくり\nす、すごい本だわ！", 1, 139901, 0, 0, 10216);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "あっ、背中の突起が\n当たって…\nく、くすぐったい…", 1, 139901, 0, 0, 10218);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "この上でダーリンと\nいちゃいちゃ…\nへ、えへへ…", 1, 139901, 0, 0, 10219);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "んん…ファビュラス\nビーチの視線を\n独り占めしてしまい\nそうですわ…", 1, 140001, 0, 0, 10222);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "フム…この部屋も\nリゾートスタイルに\n模様替えしてみては？", 1, 140001, 0, 0, 10223);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "音響盤で波音のBGM\nでも流しましょうか\n一気にリゾート気分を\n味わえますわよ♪", 1, 140001, 0, 0, 10224);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "秘書の目を盗んで\nひと時の休憩…\nふふ…ドリンクでも\nあれば完璧ですわね♪", 1, 140001, 0, 0, 10225);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "少年のセンス\n割とよろしいですわね\nホテルの内装について\n意見を貰おうかしら？", 1, 140001, 0, 0, 10226);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "少年へのプレゼント\n何がいいでしょうね？\n部屋の様子を見れば\n好みがわかるかも…", 1, 140001, 0, 0, 10227);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ふふ…サプライズで\nプレゼントですわ\nわたくしとお揃いの\n金・色・ビ・キ・ニ♪", 1, 140001, 0, 0, 10228);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "いい仕事をするコツは\n高いモチベを保つこと\nこの水着も\nその一環でしてよ♪", 1, 140001, 0, 0, 10229);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ちょ、なんですの？\nあなたの持ってるそれ\n巨大化の秘薬じゃ\nないでしょうね…！？", 1, 140001, 0, 0, 10230);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "さあさあ準備は\nできたかしら？\n今からバカンスへ\n出発ですわよ～♪", 1, 140001, 0, 0, 10231);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "リゾートの夏は稼ぎ時\nですがたまには自分が\n休暇を取ってみるのも\n悪くありませんわね♪", 1, 140001, 0, 0, 10232);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "あらあら、なんですの\n目を逸らしたりして？\n少年には少～し刺激が\n強すぎたかしら♪", 1, 140001, 0, 0, 10233);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "少年、また今度デート\nして差し上げますわ\nもちろん仕事として…\n…仕事として、です", 1, 140001, 0, 0, 10234);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "大事な会議は\n頭の回る午前中に\n片づけるのが\n鉄則ですわよっ！", 1, 140001, 0, 1, 10235);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "いい仕事をするため\nお昼はしっかり\n食べませんとね！\n…お腹が出ない程度に", 1, 140001, 0, 2, 10236);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "今日は定時で\n上がれましたの？\nお疲れさまの乾杯でも\nしましょうか…♪", 1, 140001, 0, 3, 10237);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "中々いい座り心地…\nバカンスには\nもってこいですわね♪", 1, 140001, 0, 0, 10239);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "あら、かわいい\nリゾートとコラボして\n限定グッズを売れば…\nふふっ、アリですわね", 1, 140001, 0, 0, 10240);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "海の香りのアロマ…\nふふ、売れそうですわ\nルイズマリーさんに\n発注しようかしら♪", 1, 140001, 0, 0, 10241);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "水着姿で暖まる…\nこれぞ贅沢の極み\nですわね", 1, 140001, 0, 0, 10242);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "もぐもぐ…フム\n中々いけますわね\nホテルのメニューに\n提案してみようかしら", 1, 140001, 0, 0, 10244);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "……っ！？\n表紙は経営学ですが\n中身はおピンク…絶対\nあの子の私物ですわ…", 1, 140001, 0, 0, 10245);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "フフ、あの鮫も\nぬいぐるみにすれば\nちょっとはかわいく\nなりますでしょうか？", 1, 140001, 0, 0, 10247);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "オッホッホッ\nファビュラスな\n女神さまといった\nところでしょうか♪", 1, 140001, 0, 0, 10248);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "ん～♡　ぼくの水着…\nやっぱサイコーすぎ♡\nセンスよすぎて怖～♡", 1, 140101, 0, 0, 10251);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "フォトスポットの\nライトもうちょい\n小型化できそーだよね\n色も派手にしたいし？", 1, 140101, 0, 0, 10252);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "サメちゃんフロート\nもっとデカくした～い\nザコお兄さん、\nお小遣いちょーだい♡", 1, 140101, 0, 0, 10253);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "もっとラヴ数\n伸びないかな～♡\nザコお兄さんになんか\nいい案出してもらお", 1, 140101, 0, 0, 10254);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "イズナ～♡\nあつくない～？\nお水飲む～？\nばしゃー♪", 1, 140101, 0, 0, 10255);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "お兄さんの写真で\nフォルダ一杯じゃん…\n…消さないけど♡", 1, 140101, 0, 0, 10256);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "お兄さんいないと\nホントつまんな～\n…なんかムカつく…\nザコお兄さんのクセに", 1, 140101, 0, 0, 10257);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ぼくの配信見た～？\nザコお兄さんも\nラヴと高評価\nお願いしま～す♡", 1, 140101, 0, 0, 10258);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "かき氷食べた～い♡\nお兄さんのおごりね♡\nシロップ全がけで～♡", 1, 140101, 0, 0, 10259);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "とくべつに日焼け止め\n塗らせてあげる♡\nご奉仕はドレーの\n義務っしょ～♡", 1, 140101, 0, 0, 10260);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "次の配信ネタ考えて♡\n万バズ狙えるやつね♡\nあ、インセンティブは\nぼくが全部もらうけど", 1, 140101, 0, 0, 10261);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "ザコお兄さん…\nカメラで撮るの\n成長したじゃ～ん♡\nごほーびあげよっか♡", 1, 140101, 0, 0, 10262);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "お兄さんヒマなら\nぼくの配信手伝って♡\nべ、別にさびしいとか\nじゃないし～…？", 1, 140101, 0, 0, 10263);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "朝から暑すぎ～…\nお兄さんうちわ係ね♡\nあおいであおいで♡", 1, 140101, 0, 1, 10264);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼は海の家ね～\nぜったいカレー以外で\nカレー、バカナ姉ので\nもう飽き飽きだし～", 1, 140101, 0, 2, 10265);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ナイトプール行こ♡\nライトアップのぼく\n撮りたいっしょ♡", 1, 140101, 0, 3, 10266);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "ちょっと休憩～♡\nお兄さんも来る～？\n…ぷぷっ♡\nドキってしたっしょ♡", 1, 140101, 0, 0, 10268);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "イズナに似てる～♡\n…イズナの方が\n万倍かわいいけど～♡", 1, 140101, 0, 0, 10269);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ん～いいニオイ♡\nこれ配信で紹介したら\nバズりそ～♡", 1, 140101, 0, 0, 10270);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "夏仕様に改造して～\n冷風出るよーにしよ♡\n設計はこうして～…", 1, 140101, 0, 0, 10271);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ん～おいし♡\n食べたらお昼寝～♡\nぼくの夏、さいこ～♡", 1, 140101, 0, 0, 10273);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ん～配信機材の本…\nけっこー使えるじゃん\n参考にしよっと♡", 1, 140101, 0, 0, 10274);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "これ浮き輪にしたら\n映えそ～じゃん♡\n撮って撮って～♡", 1, 140101, 0, 0, 10276);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "人魚姫ごっこ～♡\nザコお兄さんは～…\nぼくのドレー王子で♡", 1, 140101, 0, 0, 10277);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "今日の天気は…晴れ♪\nけんぞくとプールに\nおよぎにいこーっと", 1, 140201, 0, 0, 10280);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "フブキってすっごく\n負けずギライだよね\nちょっとかわいーかも", 1, 140201, 0, 0, 10281);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "コメントきてるみたい\nザツダン配信\nそろそろやろっか", 1, 140201, 0, 0, 10282);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ねえけんぞく、\nこの水着どうかな？\n似合ってる？", 1, 140201, 0, 0, 10283);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ヴァンピィちゃんって\nいい子ちゃん…なの？\nよくわかりませんし！", 1, 140201, 0, 0, 10284);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ベスちゃんと\nまたプール行きたいな\nもちろんけんぞくもね", 1, 140201, 0, 0, 10285);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "ジドリって\nむずかしーよね\n首が斜めになっちゃう", 1, 140201, 0, 0, 10286);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "あっデバイスがない！\n…けんぞくが拾って\nくれたの？　ありがと", 1, 140201, 0, 0, 10287);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "ねえけんぞく！\nカプ推し、ってなに？\nかぷってするの？", 1, 140201, 0, 0, 10288);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ショケンデス！\n…えへへ、\n言ってみたかっただけ", 1, 140201, 0, 0, 10289);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "さいきょーザツダン\n配信ミタミタ！\nはじまるよー！", 1, 140201, 0, 0, 10290);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "けんぞくは\nヴァンピィちゃんの\n…かれぴっぴ…？", 1, 140201, 0, 0, 10291);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "デバイス見てたら\nおめめがしょぼしょぼ\nしてきちゃった…", 1, 140201, 0, 0, 10292);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "フブキはまだ\n寝てるみたい\nねぼすけさんだね♪", 1, 140201, 0, 1, 10293);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お外いくの？\nじゃあ日焼け止め\n塗ってほしーな♪", 1, 140201, 0, 2, 10294);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ナイトプールの\nじかんだよ！\n今夜も遊びにいこっ！", 1, 140201, 0, 3, 10295);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "水にプカプカするのも\nスキだけど、\nフカフカもきもちいい", 1, 140201, 0, 0, 10297);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "こういうの抱いてたら\nベスちゃんが\nやきもちやくかなぁ？", 1, 140201, 0, 0, 10298);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい匂～い♪\nヴァンピィちゃんの\nお鼻ひくひくしちゃう", 1, 140201, 0, 0, 10299);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "水に濡れたら\nちゃんと乾かさないと\n…はぁ、ぽかぽか…", 1, 140201, 0, 0, 10300);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "およぐとおなかが\nすいちゃいますし♪\nもぐもぐ…", 1, 140201, 0, 0, 10302);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "本をたくさん読んだら\nフブキみたいな\n発明できるかな？", 1, 140201, 0, 0, 10303);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "プールに持っていって\n浮かべたいなー\nぷかぷか～♪", 1, 140201, 0, 0, 10305);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "おっきな貝がら～！\n食べられちゃうかも\nぱくっ♪　って", 1, 140201, 0, 0, 10306);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "フツーの建物って\nなーんか慣れないわね\nひっくり返して\nさかさまにしていい？", 1, 140301, 0, 0, 10309);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "ふーん、こーゆーの\nあいつの趣味なんだ\nや、べつにあたしは\nなんだっていいけど", 1, 140301, 0, 0, 10310);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "ここ、妖精が\n住み着いてんのよね\nちょい殺虫剤\n買ってくるわー", 1, 140301, 0, 0, 10311);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "あいつの日記とか\n探してやろっと\n何書いてるか\n想像つくけどー", 1, 140301, 0, 0, 10312);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "へーわな夢はいっぱい\nあったけど。ここも\n大概へーわ過ぎるのよ\n調子狂うってーの", 1, 140301, 0, 0, 10313);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "メリゾに行ったら次は\n何しよっかなー\n…ヒップレスリング？\n絶っっ対やんないから", 1, 140301, 0, 0, 10314);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "あんたはあたしの\nオモチャなんだから\nもうイロイロ\n諦めちゃいなさい♡", 1, 140301, 0, 0, 10315);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "水着？　着ないわよ\nそーそーレアイベ\n起こしてやるワケ\nないっしょ", 1, 140301, 0, 0, 10316);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "やっほーヒーロー\n今日は誰に会いに\n来…え、あたし？\nなんかむかつくわね…", 1, 140301, 0, 0, 10317);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "あんた夢ン中と違って\n気軽に絡んで来すぎ\nじゃない？　ま、\n放置よりいっか…♪", 1, 140301, 0, 0, 10318);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "うひゃっ！？\nきゅ、きゅーに\n現れんなっての！\nばかぁ…！", 1, 140301, 0, 0, 10319);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "はー、ヒマだわ\nあんた、なんか\n芸でもしなさいよ\n腹踊りとか？", 1, 140301, 0, 0, 10320);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "あんた、あたしと\nしたいことある？\nあ、聞いただけ。気が\n向いたら検討したげる", 1, 140301, 0, 0, 10321);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはよ。あんたが\n起きてるときに話すの\n変なカンジするわー", 1, 140301, 0, 1, 10322);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "昼ごはん作ってきた？\nいい心がけじゃない\nティア様が\nいただいてあげる♡", 1, 140301, 0, 2, 10323);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "おそよー、ヒーロー\nさっさと寝なさいよね\nそれともあたしと\n夜通し話でもしたい？", 1, 140301, 0, 3, 10324);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "はーゆったりできるわ\n今度あいつにここで\n肩もみさせてやろっと\n人払いしてからね…", 1, 140301, 0, 0, 10326);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "わー\nかーわいーい♡\n…枕とかにゃ\n丁度いいかもね", 1, 140301, 0, 0, 10327);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "バグだっつっても\n匂いまで感じられる…\nヘンなもんね、あたし", 1, 140301, 0, 0, 10328);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "ふわーあったか…\nうっかりリラックス\nしそうになるわ", 1, 140301, 0, 0, 10329);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "ちょ、これあたしを\n太らそーって罠じゃ\nないでしょーね…？", 1, 140301, 0, 0, 10331);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "日記探してやろっと\nん？　自称健全小説に\n桃闘者ランキング？\n…なにこの本棚？", 1, 140301, 0, 0, 10332);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この姿だといつもの\nメイド服は無理…か\n…エプロンだけなら？\nいやへんふしかっての", 1, 140501, 0, 0, 10338);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "姉貴に怒られる前に\n戻んないと…いや？\nここは逆にサボって…", 1, 140501, 0, 0, 10339);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "シーツ乾かすの\nもっと楽にしたいな\n…炎の剣…試すか？", 1, 140501, 0, 0, 10340);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "リンゴ入りの\nポテトサラダ\n姉貴も気に入るかな", 1, 140501, 0, 0, 10341);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "うわ、はちみつ\n切れてるじゃん\n買い出しかぁ…だる…", 1, 140501, 0, 0, 10342);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "ここにいると\nなんか安心する…\nあの人のせいかな", 1, 140501, 0, 0, 10343);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "隣にいたいって\nこの気持ちは\n設定なんかじゃない\nあたしが感じてること", 1, 140501, 0, 0, 10344);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おや騎士さん\nお茶でもどーです？\nお菓子もあるんで\nサボりじゃないですよ", 1, 140501, 0, 0, 10345);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "実はこの姿でなにが\nできるか、実験して\nみたいんですよね…\n助手募集中なんですが", 1, 140501, 0, 0, 10346);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "翼、気になります？\n触ってもいいですけど\nくすぐるのはナシで", 1, 140501, 0, 0, 10347);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "来ると思ってました\n騎士さんのこと\nだいぶ読めてきたんで\n的中率７割ですかね", 1, 140501, 0, 0, 10348);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "急成長したせいで、\n歩く時のバランスが…\n…騎士さんちょっと\nおんぶお願いします", 1, 140501, 0, 0, 10349);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "渋いのに甘かった\nあの紅茶…また\n淹れてほしいなって", 1, 140501, 0, 0, 10350);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございます…\nふぁあ…眠気覚ましに\n散歩でも行きます？", 1, 140501, 0, 1, 10351);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼の付け合わせは\nポテトサラダです\nもちろん甘い\nリンゴ入りで", 1, 140501, 0, 2, 10352);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "夜更かし仲間ですね\n星がキレイですし\nよかったら空、一緒に\n飛んでみます？", 1, 140501, 0, 3, 10353);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "どんな力があっても\nこの誘惑には\n勝てない…\nもう動きたくない…", 1, 140501, 0, 0, 10355);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふわふわ…\n触り心地いいな\n姉貴のほっぺたみたい", 1, 140501, 0, 0, 10356);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "ん？　…この匂い\nちょっとだけ\nはちみつっぽい？", 1, 140501, 0, 0, 10357);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "あったか…\nあー動きたくない…\n一生ここにいたーい…", 1, 140501, 0, 0, 10358);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おにぎりに\n甘い具材入れたら\nどんな味になるか\n次、実験してみよ", 1, 140501, 0, 0, 10360);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "あたしも騎士さんに\nなにか作ってみるかな\nレシピレシピ…", 1, 140501, 0, 0, 10361);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "この場所…\n退屈しないわ\n面白そうな人や物が\nたくさんあるもの", 1, 140401, 0, 0, 10367);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "クー？　部屋の中で\n粗相をしてはダメよ\n後で散歩に連れて\n行ってあげるから", 1, 140401, 0, 0, 10368);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "気が抜けているようで\nとても穏やか\n…私にもこんな場所が\nあるといいんだけど", 1, 140401, 0, 0, 10369);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ついこのまま\nここにいたくなる…\nこれもある種の\n『呪い』かしら？", 1, 140401, 0, 0, 10370);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "ここが、騎士の\n帰るべき居場所…\nちょっとだけ\nうらやましいわね", 1, 140401, 0, 0, 10371);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "静かなほうが好き\nだけど…騒がしい\n世界もちゃんと\n知っていかなきゃね", 1, 140401, 0, 0, 10372);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "どんなに満たされても\nまだ足りないと思って\nしまう。『強欲』\nなのも困りものね", 1, 140401, 0, 0, 10373);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "私なんかに構っていて\nいいの？　ふふ、他の\n女の子に嫉妬されても\n知らないわよ？", 1, 140401, 0, 0, 10374);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "貴方とのおしゃべりは\n退屈しなくて好きよ\n私が知らない世界が\n見つかりそうだから", 1, 140401, 0, 0, 10375);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "ひねくれた性格だから\nひねくれた性格の人に\n惹かれる性質なの\nでも…貴方は別みたい", 1, 140401, 0, 0, 10376);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "そんなに私が欲しい？\nまぁ、罪滅ぼしって\nことなら…なんてね、\n冗談よ？", 1, 140401, 0, 0, 10377);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "私の居場所は私で\n見つける。でも、\nたまにはここへ立ち\n寄ってもいいかしら…", 1, 140401, 0, 0, 10378);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "何も考えず、旅をする\nそうしたら私も…貴方\nのように大切な何かを\n見つけられるかしら", 1, 140401, 0, 0, 10379);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ジオ・二ヴルヘルは\nずっと暗いから、\nこの世界の朝という\nのは慣れないわね", 1, 140401, 0, 1, 10380);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お昼の時間ね\n手料理でも振る舞い\nましょうか？\nこう見えても得意なの", 1, 140401, 0, 2, 10381);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "やっぱり夜は\n落ち着くわね\n静寂が全てを\n包み込んでくれる", 1, 140401, 0, 3, 10382);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "思えば、こうやって\n腰を据えてくつろげる\nなんて、久しぶりな\n気がするわね", 1, 140401, 0, 0, 10384);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ふふ、かわいいわね\nもちろんクーほどじゃ\nないけどね？", 1, 140401, 0, 0, 10385);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "この香り、嫌いじゃ\nないわ。気分が\n鎮まって、余計なこと\nを考えなくて済むもの", 1, 140401, 0, 0, 10386);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "…あたたかい\nこの感覚も、私を\n満たしてくれる\n一つの答えなのかしら", 1, 140401, 0, 0, 10387);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "食事を楽しむ機会\nなんて多くはなかった\nけど、意外と悪くは\nないものね", 1, 140401, 0, 0, 10389);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "知識は身につけて\nおいて損はないわ\nいざという時の\nために…ね", 1, 140401, 0, 0, 10390);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "敵影なーしっ\n今日もギルドハウスは\n安心安全ですっ♪", 1, 140601, 0, 0, 10396);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "お水でざぶーんと\n流しちゃうので\nお部屋のお掃除も\nお任せですっ♪", 1, 140601, 0, 0, 10397);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "新ボディになったので\nライラエルさまたち\nとも、いつか海に\n遊びにいきたいですっ", 1, 140601, 0, 0, 10398);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "ボディに書かれた\nこの文字…\nまるっこくて\nかわいいですねっ♪", 1, 140601, 0, 0, 10399);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "高いところに\n置かれたものでも\nこの伸びるアームなら\nキャッチも簡単ですっ", 1, 140601, 0, 0, 10400);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "裏世界の管理者には\nなりましたけどっ、\nわたしはこれまでと\n変わりませんよっ♪", 1, 140601, 0, 0, 10401);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "胸の中にある\nたくさんの気持ち…\nわたしの大切な\n宝物ですっ♪", 1, 140601, 0, 0, 10402);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "ひゃっ\n上半身の装甲は\n薄めなので触られると\nくすぐったいですねっ", 1, 140601, 0, 0, 10403);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "腕のクローはいつでも\n切り替え可能ですっ♪\nハグのときは普通の\n腕なので安心ですよっ", 1, 140601, 0, 0, 10404);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "またギルドのお仕事が\nしたいですっ\nマスターのお役に\n立ちますのでっ♪", 1, 140601, 0, 0, 10405);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "また一緒に海へ遊びに\nいきませんかっ？\n泳ぐときはわたしが\nエスコートしますねっ", 1, 140601, 0, 0, 10406);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "他の国の海はどんな\n感じなんでしょうかっ\nいろんなお魚さんが\n見れるといいなーっ", 1, 140601, 0, 0, 10407);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "成長は苦しいことも\nありますけど…\nそれでもわたしは成長\nしていきたいですっ", 1, 140601, 0, 0, 10408);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "おはようございますっ\n朝海水浴で\n目を覚ましましょうっ", 1, 140601, 0, 1, 10409);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "お魚さんを\n獲ってきましたっ！\nたくさん食べて午後も\nフルパワーですっ", 1, 140601, 0, 2, 10410);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "海中から見る\n夜空はすごく\nキラキラだそうですっ\n一緒に見ませんかっ？", 1, 140601, 0, 3, 10411);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "たくさん泳いだあとは\n休憩が大切ですっ♪\n充填完了したら、また\n遊びにいきましょうっ", 1, 140601, 0, 0, 10413);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ぎゅーってしたい\nですけど…\nまずは濡れたボディを\n乾かさないとですねっ", 1, 140601, 0, 0, 10414);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "香りを検知しましたっ\n落ち着く…って\nこんな気持ちなんで\nしょうかっ？", 1, 140601, 0, 0, 10415);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "お水の乾燥よーしっ♪\n水中用モードでも\nメンテナンスは\n必要ですよねっ♪", 1, 140601, 0, 0, 10416);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "おいしいって気持ち…\nだんだんわかってきた\nような気がしますっ♪", 1, 140601, 0, 0, 10418);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "この本…\n前に読んだときよりも\n気持ちがいっぱい\n伝わってきますっ", 1, 140601, 0, 0, 10419);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 10, 3, "いつかは本物の\nお魚さんたちとも\nこんなふうに\n遊んでみたいですっ", 1, 140601, 0, 0, 10421);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 11, 3, "この貝さん\nふかふかですっ\n海に持っていけば\nどこでも休めますねっ", 1, 140601, 0, 0, 10422);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 1, "戦士の帰還、って\nところね。やっぱり\nここは懐かしいかんじ\n家主の人柄かしら？", 1, 140701, 0, 0, 10425);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 1, "あの家具の陰、ハイド\nするのによさそうね\nかくれんぼでもしたら\nあたしの優勝かも♪", 1, 140701, 0, 0, 10426);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 1, "アルファは待機\nブラボーは突入！\n…ふふ、すっかり\nハマっちゃったみたい", 1, 140701, 0, 0, 10427);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 1, "次の訓練はいつが\nいいかしら。レモンと\nハチミツ…じゃなくて\n的の準備をしなきゃね", 1, 140701, 0, 0, 10428);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 1, "この装備、レプリカを\n作ったら人気商品に\nなりそう。アキノさん\nに相談してみようかな", 1, 140701, 0, 0, 10429);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 1, "次のお弁当プランを\n練っておかなきゃね\nあいつの「おいしい」\nが、あたしの報酬よ", 1, 140701, 0, 0, 10430);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 1, "誰かより…なんて不安\nはいらないのよね。今\nこの瞬間も、思い出は\n重なっていくんだから", 1, 140701, 0, 0, 10431);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "なあに？\nそんなにあたしの\nスーツ姿が気になる？\n…って、見過ぎよ！？", 1, 140701, 0, 0, 10432);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "驚かせようったって\n残念♪　あんたが声を\nかけてくるパターンは\nお見通しなんだから♪", 1, 140701, 0, 0, 10433);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "見て。向こうの建物に\n怪しい影があるわ…\nあたしたちの出番ね\n作戦を練るわよ", 1, 140701, 0, 0, 10434);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 2, "あたしの後ろに立った\nやつ…手をあげて！\n…なーんてね♪", 1, 140701, 0, 0, 10435);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (4, 101, 2, "どんな新しい世界でも\n新しい装備でも、ほら\nちゃーんと、あんたの\n知ってるあたしでしょ", 1, 140701, 0, 0, 10436);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (8, 102, 2, "うずうずしてるの\nここからまたあんたと\n始めるのは、まったく\n新しい冒険なんだって", 1, 140701, 0, 0, 10437);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 1, 2, "今朝は一緒に演習する\nって約束でしょ？\nまた寝ぼけた顔して…\nはい、顔を洗いにゴー", 1, 140701, 0, 1, 10438);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 2, "あーあー。こちら\nサレン、昼食をとるわ\nデザートは苺サンド\nオーケー、どうぞ", 1, 140701, 0, 2, 10439);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 2, "暗闇だって\nゴーグルがあれば\nあんたの寝顔も\n見えちゃうのよ♪", 1, 140701, 0, 3, 10440);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 2, 3, "この下にターゲットが\n隠れていたら…なんて\nこの装備だとついつい\n考えちゃうのよね", 1, 140701, 0, 0, 10442);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 3, 3, "ターゲット発見！\n非常にかわいい様子\nただちにモフりを実行\nモフモフ…♪", 1, 140701, 0, 0, 10443);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 4, 3, "いい香り…\n戦いで高揚した気持ち\nをここでリセット\nしなくちゃね", 1, 140701, 0, 0, 10444);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 5, 3, "いろんなところに\n冒険に行ったけど、\n暖をとるありがたみは\nどこでもいっしょよね", 1, 140701, 0, 0, 10445);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 7, 3, "お腹が空いては\nなんとやら、よ\nめいっぱい\n補給しないと♪", 1, 140701, 0, 0, 10447);
INSERT INTO `v1_bdbc08bb594b374369cf6b61d90a6d36dba9e2d6a71e3af74e2ab9f67c6296a4` VALUES (1, 8, 3, "ふんふん。上手に撃ち\n抜く方法…彼のハート\nを…ってこれ、恋愛\nマニュアルじゃない！", 1, 140701, 0, 0, 10448);
